def _office_team_slug(value):
    return re.sub(
        r"-+", "-",
        re.sub(r"[^a-z0-9]+", "-", str(value or "").strip().lower()),
    ).strip("-")[:64]


async def office_floor_access_handler(env, request):
    """Return only the signed-in viewer's server-derived elevator grants.

    The shared tower belongs to one authoritative organization.  A matching
    team name in a user-created organization must never unlock its floors, and
    a stale ``org_team_members`` row must not survive deletion of any parent.
    """
    if method_name(request) != "GET":
        return json_response(
            {"error": "method_not_allowed"},
            status=405,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"allow": "GET"},
        )
    try:
        account_bi, account = await _account_session_record(env, request)
    except Exception:
        account_bi, account = "", None
    if (
        not re.fullmatch(r"[0-9a-f]{64}", str(account_bi or ""))
        or not account
        or account.get("status") != "active"
        or _account_kind(account) != "user"
    ):
        return json_response(
            {
                "authenticated": False,
                "allowedFloorIds": [],
                "teams": [],
            },
            status=401,
            cache_control="no-store, max-age=0, must-revalidate",
        )
    await ensure_schema(env)
    office_org = str(
        getattr(env, "OFFICE_MARKETING_ORG", "") or "forkmesh"
    ).strip().lower()
    office_org_bi, office_org_row = (
        await _org_row(env, office_org)
        if valid_node_name(office_org)
        else ("", None)
    )
    rows = []
    if office_org_row:
        rows = await d1_all(
            env,
            "SELECT DISTINCT tm.team AS team "
            "FROM org_team_members tm "
            "INNER JOIN orgs o ON o.org_bi=tm.org_bi "
            "INNER JOIN org_members om "
            "ON om.org_bi=tm.org_bi AND om.member_bi=tm.member_bi "
            "INNER JOIN org_teams ot "
            "ON ot.org_bi=tm.org_bi AND ot.team=tm.team "
            "WHERE tm.org_bi=? AND o.name=? AND tm.member_bi=? "
            "AND om.role IN ('owner','admin','member') "
            "AND ot.permission IN ('read','write','maintain','admin') "
            "ORDER BY tm.team LIMIT 50",
            str(office_org_bi),
            office_org,
            str(account_bi),
        )
    teams = sorted({
        slug
        for slug in (
            _office_team_slug((row or {}).get("team")) for row in rows or []
        )
        if slug
    })
    team_set = set(teams)
    # Only the lobby and the rooftop patio are common floors. Marketing is a
    # department story like every other one: it is granted below solely when
    # this account actually belongs to that team.
    allowed = ["lobby", "rooftop"]
    for floor_id, aliases in OFFICE_FLOOR_TEAM_ALIASES.items():
        if team_set.intersection(aliases):
            allowed.append(floor_id)
    return json_response(
        {
            "authenticated": True,
            "account": clean_string(
                account.get("name", ""), MAX_NODE_NAME).lower(),
            "allowedFloorIds": allowed,
            "teams": teams,
        },
        cache_control="private, no-store, max-age=0, must-revalidate",
        extra_headers={"x-content-type-options": "nosniff"},
    )


async def office_general_access_handler(env, request):
    """Issue a meeting claim for the same account admitted at the lobby."""
    if method_name(request) != "GET":
        return json_response(
            {"error": "method_not_allowed"},
            status=405,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"allow": "GET"},
        )
    try:
        account_bi, record = await _account_session_record(env, request)
        session_id = _request_account_session_id(request)
        entry_claims = _office_entry_ticket_claims(
            env, request.headers.get("x-forkmesh-office-entry") or "")
    except Exception:
        account_bi, record, session_id, entry_claims = "", None, "", None
    if (
        not re.fullmatch(r"[0-9a-f]{64}", str(account_bi or ""))
        or not re.fullmatch(r"[A-Za-z0-9_-]{24,64}", session_id)
        or not record
        or record.get("status") != "active"
        or _account_kind(record) != "user"
        or not entry_claims
        or entry_claims.get("scope") != "world-general"
        or not hmac.compare_digest(
            str(entry_claims.get("accountBi") or ""),
            str(account_bi),
        )
    ):
        return json_response(
            {"error": "registered_office_entry_required"},
            status=401,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"x-content-type-options": "nosniff"},
        )
    name = world_protocol.clean_display_name(
        record.get("name"), "Contributor")
    token = _office_meeting_ticket(
        env, "world-general", 1, str(account_bi), name, session_id)
    claims = _office_meeting_ticket_claims(env, token) or {}
    return json_response(
        {
            "room": {
                "id": "general",
                "name": "general",
                "visibility": "public",
            },
            "meetingWebSocketUrl": (
                "/api/world/office/general/ws?ticket="
                + quote(token, safe="")
            ),
            "expiresAt": int(claims.get("expires") or 0),
            "accountStatus": "Registered",
        },
        cache_control="no-store, max-age=0, must-revalidate",
        extra_headers={"x-content-type-options": "nosniff"},
    )


async def _forward_office_socket(env, request, claims, room_name, path):
    room_id = env.FORKMESH_OFFICE_ROOM.idFromName(room_name)
    source_url = urlparse(request.url)
    target_url = source_url.scheme + "://" + source_url.netloc + path
    last_error = None
    for _attempt in range(2):
        room_object = env.FORKMESH_OFFICE_ROOM.get(room_id)
        try:
            return await room_object.fetch(
                await office_durable_object_request(
                    request, claims, target_url=target_url))
        except Exception as error:
            last_error = error
    await log_durable_object_abort(
        env, request, urlparse(request.url).path, last_error)
    return json_response(
        {"error": "unavailable"}, status=503,
        extra_headers=EXPECTED_DEGRADED_HEADERS)


async def _office_general_socket_handler(env, request):
    if (
        method_name(request) != "GET"
        or (request.headers.get("upgrade") or "").lower() != "websocket"
        or not world_websocket_origin_allowed(request)
    ):
        return _private_replica_not_found()
    url = urlparse(request.url)
    ticket_values = parse_qs(
        url.query, keep_blank_values=False).get("ticket") or []
    claims = (
        _office_meeting_ticket_claims(env, ticket_values[0])
        if len(ticket_values) == 1 else None
    )
    if (
        not claims
        or claims["scope"] != "world-general"
        or not re.fullmatch(
            r"[0-9a-f]{64}", str(claims.get("account_bi") or ""))
    ):
        return _private_replica_not_found()
    try:
        session_account_bi, _session_record = (
            await _account_session_record(env, request))
        session_id = _request_account_session_id(request)
    except Exception:
        session_account_bi, session_id = "", ""
    if (
        not hmac.compare_digest(
            str(session_account_bi or ""),
            str(claims.get("account_bi") or ""))
        or not hmac.compare_digest(
            str(session_id or ""),
            str(claims.get("session_id") or ""))
    ):
        return _private_replica_not_found()
    claims["accountStatus"] = "Registered"
    return await _forward_office_socket(
        env,
        request,
        claims,
        "office:world-general:v1",
        "/api/world/office/world-general/v1/ws",
    )


async def _office_channel_socket_handler(env, request, channel_id):
    if (
        method_name(request) != "GET"
        or (request.headers.get("upgrade") or "").lower() != "websocket"
        or not world_websocket_origin_allowed(request)
    ):
        return _private_replica_not_found()
    url = urlparse(request.url)
    ticket_values = parse_qs(
        url.query, keep_blank_values=False).get("ticket") or []
    claims = (
        _office_meeting_ticket_claims(env, ticket_values[0])
        if len(ticket_values) == 1 else None
    )
    if not claims or claims["scope"] != channel_id:
        return _private_replica_not_found()
    try:
        session_account_bi, _session_record = (
            await _account_session_record(env, request))
        session_id = _request_account_session_id(request)
    except Exception:
        session_account_bi, session_id = "", ""
    if (
        not hmac.compare_digest(
            str(session_account_bi or ""),
            str(claims.get("account_bi") or ""))
        or not hmac.compare_digest(
            str(session_id or ""),
            str(claims.get("session_id") or ""))
    ):
        return _private_replica_not_found()
    try:
        await ensure_schema(env)
        channel = await d1_first(
            env,
            "SELECT data,key_version FROM chat_channels WHERE channel_id=?",
            channel_id,
        )
        if (
            not channel
            or int(channel.get("key_version") or 0)
                != int(claims["version"])
        ):
            return _private_replica_not_found()
        channel_record = await decrypt_row(env, channel.get("data"))
        if not isinstance(channel_record, dict):
            return _private_replica_not_found()
        visibility = (
            "public"
            if channel_record.get("visibility") == "public"
            else "private"
        )
        account = await d1_first(
            env,
            "SELECT data,is_admin FROM users WHERE user_bi=?",
            claims["account_bi"],
        )
        if not account:
            return _private_replica_not_found()
        account_record = await decrypt_row(env, account.get("data"))
        if (
            not account_record
            or account_record.get("status") != "active"
            or _account_kind(account_record) != "user"
        ):
            return _private_replica_not_found()
        is_admin = bool(int(account.get("is_admin") or 0))
        if not is_admin and visibility != "public":
            membership = await d1_first(
                env,
                "SELECT 1 AS allowed FROM chat_channel_members "
                "WHERE channel_id=? AND member_bi=?",
                channel_id,
                claims["account_bi"],
            )
            if not membership:
                return _private_replica_not_found()
        claims["name"] = world_protocol.clean_display_name(
            account_record.get("name"), "Contributor")
        claims["accountStatus"] = "Registered"
    except Exception:
        return _private_replica_not_found()

    version = int(claims["version"])
    return await _forward_office_socket(
        env,
        request,
        claims,
        "office:chat-channel:" + channel_id + ":v" + str(version),
        "/api/world/office/" + channel_id + "/v" + str(version) + "/ws",
    )


async def _revoke_chat_channel_room(env, channel_id, key_version):
    room_name = (
        "chat-channel:" + str(channel_id) + ":v" + str(int(key_version))
    )
    room_id = env.FORKMESH_MAINNODE_ROOM.idFromName(room_name)
    target_url = (
        "https://forkmesh.internal/api/chat/channels/" + str(channel_id)
        + "/v" + str(int(key_version)) + "/revoke"
    )
    last_error = None
    for _attempt in range(2):
        room_object = env.FORKMESH_MAINNODE_ROOM.get(room_id)
        try:
            request = JsRequest.new(
                target_url, to_js({"method": "POST"}))
            response = await room_object.fetch(request)
            if int(getattr(response, "status", 200) or 200) < 400:
                return
        except Exception as error:
            last_error = error
    if last_error is not None:
        raise last_error
    raise RuntimeError("chat_channel_revoke_failed")


async def _revoke_chat_direct_room(env, conversation_id, key_version):
    room_name = (
        "chat-direct:" + str(conversation_id)
        + ":v" + str(int(key_version))
    )
    room_id = env.FORKMESH_MAINNODE_ROOM.idFromName(room_name)
    target_url = (
        "https://forkmesh.internal/api/chat/direct-messages/"
        + str(conversation_id) + "/v" + str(int(key_version)) + "/revoke"
    )
    last_error = None
    for _attempt in range(2):
        room_object = env.FORKMESH_MAINNODE_ROOM.get(room_id)
        try:
            request = JsRequest.new(
                target_url, to_js({"method": "POST"}))
            response = await room_object.fetch(request)
            if int(getattr(response, "status", 200) or 200) < 400:
                return
        except Exception as error:
            last_error = error
    if last_error is not None:
        raise last_error
    raise RuntimeError("chat_direct_revoke_failed")


async def _revoke_office_channel_room(env, channel_id, key_version):
    room_name = (
        "office:chat-channel:" + str(channel_id)
        + ":v" + str(int(key_version))
    )
    room_id = env.FORKMESH_OFFICE_ROOM.idFromName(room_name)
    target_url = (
        "https://forkmesh.internal/api/world/office/" + str(channel_id)
        + "/v" + str(int(key_version)) + "/revoke"
    )
    last_error = None
    for _attempt in range(2):
        room_object = env.FORKMESH_OFFICE_ROOM.get(room_id)
        try:
            request = JsRequest.new(
                target_url, to_js({"method": "POST"}))
            response = await room_object.fetch(request)
            if int(getattr(response, "status", 200) or 200) < 400:
                return
        except Exception as error:
            last_error = error
    if last_error is not None:
        raise last_error
    raise RuntimeError("office_channel_revoke_failed")


class _WorldCommunityRuntime:
    """Narrow adapter from isolated world APIs to established Worker helpers."""

    def __init__(self, env, request=None):
        self.env = env
        self.request = request

    def method(self):
        return method_name(self.request) if self.request is not None else "GET"

    def now(self):
        return int(Date.now())

    def new_id(self):
        # The random id contains no account, address, time, path, or provider
        # information and is safe to use as the public resource identifier.
        return _ap_uuid()

    def instance_id(self):
        """Stable public instance identifier with no account/device material."""
        base = str(getattr(self.env, "PUBLIC_BASE_URL", "") or "").strip()
        try:
            host = str(urlparse(base).hostname or "").strip().lower()
        except Exception:
            host = ""
        if host:
            return host[:253]
        label = clean_string(
            getattr(self.env, "NODE_NAME", "") or "", MAX_NODE_NAME
        ).strip().lower()
        return label or "forkmesh.com"

    def public_origin(self):
        if self.request is not None:
            return _ap_origin(self.env, self.request)
        configured = str(
            getattr(self.env, "PUBLIC_BASE_URL", "") or ""
        ).strip().rstrip("/")
        return configured or "https://forkmesh.com"

    def query_params(self):
        if self.request is None:
            return {}
        values = parse_qs(urlparse(self.request.url).query)
        return {
            str(key): str(items[0])
            for key, items in values.items()
            if isinstance(items, list) and items
        }

    def response(self, data, status=200, cache_control=None,
                 extra_headers=None):
        return json_response(
            data,
            status=status,
            cache_control=cache_control,
            extra_headers=extra_headers,
        )

    async def ensure_schema(self):
        await ensure_schema(self.env)

    async def json_body(self, limit):
        """Read one bounded JSON object; an empty mutation body becomes {}."""
        if self.request is None:
            return None, "invalid_json"
        try:
            raw_length = self.request.headers.get("content-length") or ""
            if raw_length and int(raw_length) > int(limit):
                return None, "payload_too_large"
        except (TypeError, ValueError):
            return None, "invalid_content_length"
        try:
            raw = await self.request.text()
        except Exception:
            return None, "invalid_json"
        if len(str(raw or "").encode("utf-8")) > int(limit):
            return None, "payload_too_large"
        if not str(raw or "").strip():
            return {}, ""
        try:
            data = json.loads(raw)
        except Exception:
            return None, "invalid_json"
        return (data, "") if isinstance(data, dict) else (None, "invalid_json")

    async def session(self, data=None):
        return await _account_session_record(
            self.env, self.request, data if isinstance(data, dict) else {})

    async def is_admin(self, name):
        return await _is_admin(self.env, name)

    async def account(self, name):
        name = clean_string(name or "", MAX_NODE_NAME).strip().lower()
        if not valid_node_name(name):
            return "", ""
        account_bi, rec = await _account_row(self.env, name)
        if (
            not rec
            or rec.get("status") != "active"
            or _account_kind(rec) != "user"
        ):
            return "", ""
        return account_bi, clean_string(
            rec.get("name") or name, MAX_NODE_NAME).strip().lower()

    async def blind(self, value):
        return await blind_index(self.env, str(value or ""))

    async def seal(self, value):
        return await encrypt_row(self.env, value)

    async def open(self, value):
        return await decrypt_row(self.env, value)

    async def repository_access(self, owner, repo, _actor):
        # Named public repository reads are available to signed-in workshop
        # participants. Private/missing names fail closed and require the same
        # owner-session authorization as every other named owner surface.
        _repo_bi, row = await _security_scan_repository_row(
            self.env, owner, repo)
        if not row:
            return False
        if not await _repo_is_private(self.env, owner, repo):
            return True
        ok, _response = await _authorize_owner_account(
            self.env, owner, {}, self.request, allow_admin=False)
        return bool(ok)

    async def authorize_repository_owner(self, owner, data=None):
        account_bi, rec = await _account_session_record(
            self.env,
            self.request,
            data if isinstance(data, dict) else {},
        )
        actor = clean_string(
            (rec or {}).get("name") or "", MAX_NODE_NAME
        ).strip().lower()
        if (
            not account_bi
            or not actor
            or not await _account_owns_node(self.env, actor, owner)
        ):
            return "", ""
        return account_bi, actor

    async def authorize_owner_node(self, owner):
        return bool(
            self.request is not None
            and await _authorize_owner(self.env, self.request, owner)
        )

    async def enqueue_issue(
        self, owner, repo, title, body, requester, mention_id, remote_url
    ):
        provenance = (
            "\n\nReviewed public fediverse source: " + str(remote_url)
            if remote_url else ""
        )
        return await _forkbot_enqueue_issue(
            self.env,
            owner,
            repo,
            title,
            str(body).rstrip() + provenance,
            requester,
            source="fediverse-review",
            labels=["fediverse", "manually-reviewed"],
            federated_mention_id=mention_id,
            federated_remote_url=remote_url,
        )

    async def publish_followup(self, mention_id, record, message, number):
        remote = {
            "actor_id": record.get("actorUrl", ""),
            "url": record.get("actorUrl", ""),
            "handle": record.get("author", ""),
            "inbox": record.get("inbox", ""),
            "shared_inbox": record.get("sharedInbox", ""),
        }
        note = {
            "id": record.get("remoteId", ""),
            "url": record.get("remoteUrl", ""),
        }
        return bool(await _ap_send_mention_reply(
            self.env,
            self.request,
            record.get("actorOwner", ""),
            record.get("repo", ""),
            remote,
            note,
            message,
            number,
            dedupe_id=mention_id,
            object_uuid=mention_id,
        ))

    async def audit(self, actor, action, target_type="", target="",
                    outcome="success", details=None):
        await _audit_sensitive_action(
            self.env,
            actor,
            action,
            target_type,
            target,
            outcome=outcome,
            details=details,
        )

    async def d1_all(self, sql, *args):
        return await d1_all(self.env, sql, *args)

    async def d1_first(self, sql, *args):
        return await d1_first(self.env, sql, *args)

    async def d1_run(self, sql, *args):
        return await d1_run(self.env, sql, *args)

    async def batch(self, statements):
        return await _contribution_run_batch(self.env, statements)


class _OfficeMarketingTasksRuntime:
    """Least-privilege adapter for the configured organization's task board."""

    def __init__(self, env, request):
        self.env = env
        self.request = request

    def method(self):
        return method_name(self.request)

    def now(self):
        return int(Date.now())

    def new_id(self):
        return _ap_uuid()

    def same_origin(self):
        return _request_same_origin(self.request)

    def response(self, data, status=200, cache_control=None,
                 extra_headers=None):
        return json_response(
            data,
            status=status,
            cache_control=cache_control,
            extra_headers=extra_headers,
        )

    async def ensure_schema(self):
        await ensure_schema(self.env)

    async def json_body(self, limit):
        try:
            raw_length = self.request.headers.get("content-length") or ""
            if raw_length and int(raw_length) > int(limit):
                return None, "payload_too_large"
        except (TypeError, ValueError):
            return None, "invalid_content_length"
        try:
            raw = await self.request.text()
        except Exception:
            return None, "invalid_json"
        if len(str(raw or "").encode("utf-8")) > int(limit):
            return None, "payload_too_large"
        if not str(raw or "").strip():
            return {}, ""
        try:
            data = json.loads(raw)
        except Exception:
            return None, "invalid_json"
        return (data, "") if isinstance(data, dict) else (None, "invalid_json")

    async def session(self, data=None):
        return await _account_session_record(
            self.env,
            self.request,
            data if isinstance(data, dict) else {},
        )

    async def organization(self):
        configured = str(
            getattr(self.env, "OFFICE_MARKETING_ORG", "") or "forkmesh"
        ).strip().lower()
        if not valid_node_name(configured):
            return "", None
        return await _org_row(self.env, configured)

    async def membership(self, org_bi, account):
        role = await _org_role(self.env, org_bi, account)
        if not role:
            return "", ""
        return role, await _org_permission(self.env, org_bi, account)

    async def active_user(self, name):
        name = clean_string(name or "", MAX_NODE_NAME).strip().lower()
        if not valid_node_name(name):
            return None
        account_bi, record = await _account_row(self.env, name)
        if (
            not record
            or record.get("status") != "active"
            or _account_kind(record) != "user"
        ):
            return None
        return {
            "bi": str(account_bi or ""),
            "name": clean_string(
                record.get("name") or name, MAX_NODE_NAME
            ).strip().lower(),
        }

    async def eligible_users(self):
        rows = await d1_all(
            self.env,
            "SELECT user_bi,data FROM users "
            "ORDER BY username COLLATE NOCASE LIMIT 1000",
        )
        members = []
        for row in rows or []:
            try:
                record = await decrypt_row(
                    self.env, row.get("data"))
            except Exception:
                record = None
            name = clean_string(
                (record or {}).get("name") or "", MAX_NODE_NAME
            ).strip().lower()
            if (
                record
                and record.get("status") == "active"
                and _account_kind(record) == "user"
                and valid_node_name(name)
                and name not in members
            ):
                members.append(name)
        return members

    async def marketing_members(self, org_bi):
        """Return active users on an authoritative Marketing floor team."""
        rows = await d1_all(
            self.env,
            "SELECT DISTINCT tm.member_bi AS member_bi,tm.name AS name,"
            "tm.team AS team "
            "FROM org_team_members tm "
            "INNER JOIN org_members om "
            "ON om.org_bi=tm.org_bi AND om.member_bi=tm.member_bi "
            "INNER JOIN org_teams ot "
            "ON ot.org_bi=tm.org_bi AND ot.team=tm.team "
            "WHERE tm.org_bi=? "
            "AND om.role IN ('owner','admin','member') "
            "AND ot.permission IN ('read','write','maintain','admin') "
            "ORDER BY tm.name COLLATE NOCASE LIMIT 1000",
            str(org_bi or ""),
        )
        aliases = OFFICE_FLOOR_TEAM_ALIASES["marketing"]
        members = []
        seen = set()
        for row in rows or []:
            if _office_team_slug(row.get("team")) not in aliases:
                continue
            name = clean_string(
                row.get("name") or "", MAX_NODE_NAME
            ).strip().lower()
            member = await self.active_user(name)
            if not member or name in seen:
                continue
            seen.add(name)
            members.append(member)
        return members

    async def marketing_member(self, org_bi, name):
        requested = clean_string(
            name or "", MAX_NODE_NAME
        ).strip().lower()
        if not requested:
            return None
        for member in await self.marketing_members(org_bi):
            if str(member.get("name") or "").lower() == requested:
                return member
        return None

    async def marketing_attendance(self, members, now):
        """Aggregate the last seven UTC calendar days for Marketing desks."""
        day_ms = 24 * 60 * 60 * 1000
        now = max(0, int(now or 0))
        today = now // day_ms
        first_day = max(0, today - 6)
        start_ms = first_day * day_ms
        totals = {}
        valid_members = []
        for member in members or []:
            account_bi = str((member or {}).get("bi") or "")
            name = clean_string(
                (member or {}).get("name") or "", MAX_NODE_NAME
            ).strip().lower()
            if not account_bi or not name:
                continue
            valid_members.append(name)
            rows = await d1_all(
                self.env,
                "SELECT in_at,out_at,last_seen_at "
                "FROM world_office_attendance "
                "WHERE account_bi=? "
                "AND visit_scope='office' "
                "AND in_at<? "
                "AND COALESCE(out_at,NULLIF(last_seen_at,0),?)>=? "
                "ORDER BY in_at ASC LIMIT 500",
                account_bi,
                now + 1,
                now,
                start_ms,
            )
            for row in rows or []:
                entered = max(start_ms, int(row.get("in_at") or 0))
                exited = row.get("out_at")
                if exited is None:
                    exited = min(
                        now,
                        max(
                            entered,
                            int(row.get("last_seen_at") or now),
                        ),
                    )
                exited = min(now, max(entered, int(exited or entered)))
                cursor = entered
                while cursor < exited:
                    bucket = cursor // day_ms
                    boundary = (bucket + 1) * day_ms
                    portion = min(exited, boundary) - cursor
                    totals[(name, bucket)] = (
                        totals.get((name, bucket), 0) + portion
                    )
                    cursor += portion
        days = []
        for bucket in range(first_day, today + 1):
            stamp = time.gmtime(bucket * 24 * 60 * 60)
            days.append({
                "date": time.strftime("%Y-%m-%d", stamp),
                "label": time.strftime("%a %m/%d", stamp).upper(),
                "hours": [
                    {
                        "member": name,
                        "hours": round(
                            totals.get((name, bucket), 0) / 3600000, 2),
                    }
                    for name in valid_members
                ],
            })
        return days

    async def blind(self, value):
        return await blind_index(self.env, str(value or ""))

    async def seal(self, value):
        return await encrypt_row(self.env, value)

    async def open(self, value):
        return await decrypt_row(self.env, value)

    async def audit(self, actor, action, target_type="", target="",
                    outcome="success", details=None):
        await _audit_sensitive_action(
            self.env,
            actor,
            action,
            target_type,
            target,
            outcome=outcome,
            details=details,
        )

    async def d1_all(self, sql, *args):
        return await d1_all(self.env, sql, *args)

    async def d1_first(self, sql, *args):
        return await d1_first(self.env, sql, *args)

    async def d1_run(self, sql, *args):
        return await d1_run(self.env, sql, *args)


class _ChatChannelsRuntime(_WorldCommunityRuntime):
    async def session(self, data=None):
        account_bi, record = await super().session(data)
        if account_bi and record:
            return account_bi, record
        # Desktop clients authenticate with their account key, not a session
        # token, so the World office's channel rooms can also be read from the
        # Qt app (see _chat_channel_signed_session for the read-only bound).
        return await _chat_channel_signed_session(self.env, self.request)

    async def room_access(self, channel_id, key_version, account_bi, actor):
        room = (
            "chat-channel:" + str(channel_id) + ":v" + str(int(key_version))
        )
        ticket = _chat_channel_ticket(
            self.env, channel_id, key_version, account_bi)
        session_id = _request_account_session_id(self.request)
        meeting_ticket = _office_meeting_ticket(
            self.env, channel_id, key_version, account_bi, actor, session_id)
        return {
            "room": room,
            "passphrase": await _chat_channel_passphrase(
                self.env, channel_id, key_version),
            "webSocketUrl": (
                "/api/chat/channels/" + str(channel_id) + "/ws?ticket="
                + quote(ticket, safe="")
            ),
            "meetingWebSocketUrl": (
                "/api/world/office/channels/" + str(channel_id)
                + "/ws?ticket=" + quote(meeting_ticket, safe="")
            ),
        }

    async def revoke_room(self, channel_id, key_version):
        await _revoke_chat_channel_room(
            self.env, channel_id, key_version)
        await _revoke_office_channel_room(
            self.env, channel_id, key_version)

    async def channel_passphrase(self, channel_id, key_version):
        return await _chat_channel_passphrase(
            self.env, channel_id, key_version)

    async def history(self, channel_id, key_version, since_ts=0):
        return await chat_history_since(
            self.env,
            "chat-channel:" + str(channel_id) + ":v" + str(int(key_version)),
            since_ts,
        )


class _ChatDirectMessagesRuntime(_WorldCommunityRuntime):
    async def search_accounts(self, query, limit):
        value = clean_string(query or "", MAX_NODE_NAME).strip().lower()
        if not value:
            return []
        escaped = (
            value.replace("\\", "\\\\")
            .replace("%", "\\%")
            .replace("_", "\\_")
        )
        prefix = escaped + "%"
        contains = "%" + escaped + "%"
        rows = await d1_all(
            self.env,
            "SELECT data,username FROM users "
            "WHERE username LIKE ? ESCAPE '\\' "
            "ORDER BY CASE WHEN username=? THEN 0 "
            "WHEN username LIKE ? ESCAPE '\\' THEN 1 ELSE 2 END,"
            "username COLLATE NOCASE LIMIT ?",
            contains,
            value,
            prefix,
            max(int(limit) * 5, int(limit)),
        )
        names = []
        for row in rows or []:
            try:
                record = await decrypt_row(self.env, row.get("data"))
            except Exception:
                record = None
            name = clean_string(
                (record or {}).get("name") or row.get("username") or "",
                MAX_NODE_NAME,
            ).strip().lower()
            if (
                record
                and record.get("status") == "active"
                and _account_kind(record) == "user"
                and valid_node_name(name)
                and name not in names
            ):
                names.append(name)
                if len(names) >= int(limit):
                    break
        return names

    async def room_access(
            self, conversation_id, key_version, account_bi):
        room = (
            "chat-direct:" + str(conversation_id)
            + ":v" + str(int(key_version))
        )
        ticket = _chat_direct_ticket(
            self.env, conversation_id, key_version, account_bi)
        return {
            "room": room,
            "passphrase": await _chat_direct_passphrase(
                self.env, conversation_id, key_version),
            "webSocketUrl": (
                "/api/chat/direct-messages/" + str(conversation_id)
                + "/ws?ticket=" + quote(ticket, safe="")
            ),
        }


