WORLD_QA_CARD_KEYS = frozenset(item[0] for item in WORLD_QA_CARDS)


async def world_qa_handler(env, request):
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST"):
        return json_response(
            {"ok": False, "error": "method_not_allowed"},
            status=405,
            extra_headers={"Allow": "GET, POST"},
        )
    data = {}
    if method == "POST":
        if not _request_same_origin(request):
            return json_response({"ok": False, "error": "origin_not_allowed"},
                                 status=403)
        try:
            data = await bounded_json_request(request, 2048)
        except RequestBodyTooLarge:
            return json_response({"ok": False, "error": "payload_too_large"},
                                 status=413)
        except Exception:
            return json_response({"ok": False, "error": "invalid_json"},
                                 status=400)
    dynamic_rows = await d1_all(
        env,
        "SELECT item_key,title,how_to_test,added_at FROM world_qa_items "
        "WHERE active=1 ORDER BY added_at DESC,item_key LIMIT 64",
    )
    deck_cards = list(WORLD_QA_CARDS)
    deck_keys = set(WORLD_QA_CARD_KEYS)
    for row in dynamic_rows or []:
        key = clean_string(row.get("item_key"), 80)
        title = clean_string(row.get("title"), 160)
        how_to_test = clean_string(row.get("how_to_test"), 720)
        if not key or key in deck_keys or not title or not how_to_test:
            continue
        deck_cards.append((key, title, how_to_test))
        deck_keys.add(key)
    deck_cards = deck_cards[:64]
    deck_keys = {item[0] for item in deck_cards}

    async def global_qa_snapshot():
        global_rows = await d1_all(
            env,
            "SELECT item_key,verdict,COUNT(*) AS count "
            "FROM world_qa_reviews GROUP BY item_key,verdict",
        )
        global_reviews = {}
        for row in global_rows or []:
            key = clean_string(row.get("item_key"), 80)
            verdict = clean_string(row.get("verdict"), 12).lower()
            if (
                key not in deck_keys
                or verdict not in ("pass", "fail", "unsure")
            ):
                continue
            counts = global_reviews.setdefault(
                key, {"pass": 0, "fail": 0, "unsure": 0, "total": 0})
            count = max(0, int(row.get("count") or 0))
            counts[verdict] += count
            counts["total"] += count
        tester_rows = await d1_all(
            env,
            "SELECT COUNT(DISTINCT account_bi) AS testers "
            "FROM world_qa_reviews",
        )
        return global_reviews, {
            "pass": sum(item["pass"] for item in global_reviews.values()),
            "fail": sum(item["fail"] for item in global_reviews.values()),
            "unsure": sum(item["unsure"] for item in global_reviews.values()),
            "reviewed": sum(item["total"] for item in global_reviews.values()),
            "testers": max(
                0, int(((tester_rows or [{}])[0]).get("testers") or 0)),
            "total": len(deck_cards),
        }

    global_reviews, global_stats = await global_qa_snapshot()

    account_bi, record = await _account_session_record(env, request, data)
    if not account_bi or not record:
        return json_response({
            "ok": True,
            "authenticated": False,
            "revision": WORLD_QA_DECK_REVISION,
            "cards": [
                {
                    "key": key,
                    "title": title,
                    "howToTest": how_to_test,
                    "global": global_reviews.get(
                        key,
                        {"pass": 0, "fail": 0, "unsure": 0, "total": 0},
                    ),
                }
                for key, title, how_to_test in deck_cards
            ],
            "reviews": {},
            "stats": {"pass": 0, "fail": 0, "unsure": 0, "reviewed": 0,
                      "total": len(deck_cards)},
            "globalReviews": global_reviews,
            "globalStats": global_stats,
            "canRoute": False,
        }, cache_control="no-store")
    actor = clean_string(
        (record or {}).get("name"), MAX_NODE_NAME).strip().lower()
    can_route = False
    if actor:
        org_bi, org_row = await _org_row(env, "forkmesh")
        if org_row:
            role = await _org_role(env, org_bi, actor)
            permission = await _org_permission(env, org_bi, actor)
            can_route = (
                role in ("owner", "admin")
                or permission in ("maintain", "admin")
            )
    if method == "POST":
        item_key = clean_string(data.get("key"), 80)
        if item_key not in deck_keys:
            return json_response({"ok": False, "error": "unknown_qa_item"},
                                 status=400)
        action = clean_string(data.get("action"), 24).lower()
        if action in ("route_todo", "route_issue"):
            if not can_route:
                return json_response(
                    {"ok": False, "error": "forbidden"}, status=403)
            card = next(
                (item for item in deck_cards if item[0] == item_key),
                None,
            )
            if not card:
                return json_response(
                    {"ok": False, "error": "unknown_qa_item"}, status=400)
            _, title, how_to_test = card
            now = int(Date.now())
            if action == "route_todo":
                task_suffix = re.sub(
                    r"[^a-z0-9-]+", "-", item_key.lower()).strip("-")
                task_key = ("task:qa-" + task_suffix)[:53].rstrip("-")
                peak = await d1_first(
                    env,
                    "SELECT COALESCE(MAX(priority),0) AS priority "
                    "FROM world_build_board_items",
                )
                priority = min(
                    64, max(1, int((peak or {}).get("priority") or 0) + 1))
                await d1_run(
                    env,
                    "INSERT INTO world_build_board_items "
                    "(item_key,kind,owner,repo,issue_number,title,priority,"
                    "updated_by_bi,updated_at,completed_at,completed_by_bi) "
                    "VALUES (?,'task','','',0,?,?,?,?,0,'') "
                    "ON CONFLICT(item_key) DO UPDATE SET "
                    "title=excluded.title,priority=excluded.priority,"
                    "updated_by_bi=excluded.updated_by_bi,"
                    "updated_at=excluded.updated_at,completed_at=0,"
                    "completed_by_bi=''",
                    task_key, title, priority, account_bi, now,
                )
                route_result = {
                    "target": "todo",
                    "key": task_key,
                }
            else:
                body = (
                    "QA follow-up requested from the 24-hour World deck.\n\n"
                    "How to test:\n" + how_to_test
                )
                queued, result = await _forkbot_enqueue_issue(
                    env,
                    "forkmesh",
                    "forkmesh",
                    "QA follow-up: " + title,
                    body,
                    actor,
                    source="qa-deck",
                    labels=["qa"],
                )
                if not queued:
                    return json_response(
                        {"ok": False, "error": str(result or "issue_failed")},
                        status=409,
                    )
                route_result = {
                    "target": "issues",
                    "number": int((result or {}).get("issueNumber") or 0),
                }
            await _audit_sensitive_action(
                env,
                actor,
                "world.qa_" + action,
                "world_qa_item",
                item_key,
                "success",
                route_result,
            )
        else:
            verdict = clean_string(data.get("verdict"), 12).lower()
            if verdict not in ("pass", "fail", "unsure"):
                return json_response(
                    {"ok": False, "error": "invalid_verdict"}, status=400)
            await d1_run(
                env,
                "INSERT INTO world_qa_reviews("
                "account_bi,item_key,verdict,reviewed_at) VALUES(?,?,?,?) "
                "ON CONFLICT(account_bi,item_key) DO UPDATE SET "
                "verdict=excluded.verdict,reviewed_at=excluded.reviewed_at",
                account_bi, item_key, verdict, int(Date.now()),
            )
        global_reviews, global_stats = await global_qa_snapshot()
    rows = await d1_all(
        env,
        "SELECT item_key,verdict,reviewed_at FROM world_qa_reviews "
        "WHERE account_bi=? ORDER BY reviewed_at DESC LIMIT 128",
        account_bi,
    )
    reviews = {}
    for row in rows:
        key = clean_string(row.get("item_key"), 80)
        verdict = clean_string(row.get("verdict"), 12).lower()
        if key in deck_keys and verdict in ("pass", "fail", "unsure"):
            reviews[key] = {
                "verdict": verdict,
                "reviewedAt": max(0, int(row.get("reviewed_at") or 0)),
            }
    stats = {
        "pass": sum(1 for item in reviews.values()
                    if item["verdict"] == "pass"),
        "fail": sum(1 for item in reviews.values()
                    if item["verdict"] == "fail"),
        "unsure": sum(1 for item in reviews.values()
                      if item["verdict"] == "unsure"),
        "reviewed": len(reviews),
        "total": len(deck_cards),
    }
    return json_response({
        "ok": True,
        "authenticated": True,
        "revision": WORLD_QA_DECK_REVISION,
        "cards": [
            {
                "key": key,
                "title": title,
                "howToTest": how_to_test,
                "global": global_reviews.get(
                    key, {"pass": 0, "fail": 0, "unsure": 0, "total": 0}),
                **reviews.get(key, {}),
            }
            for key, title, how_to_test in deck_cards
        ],
        "reviews": reviews,
        "stats": stats,
        "globalReviews": global_reviews,
        "globalStats": global_stats,
        "canRoute": can_route,
        **({"routeResult": route_result}
           if method == "POST" and "route_result" in locals() else {}),
    }, cache_control="no-store")


WORLD_PREFERENCES_MAX_BYTES = 320 * 1024
WORLD_PREFERENCES_MAX_VIEWS = 4
WORLD_PREFERENCES_PRIVACY_KEYS = (
    "name", "country", "browser", "os", "activity", "inactivity",
    "localTime", "nodes",
)


def _world_preference_timestamp(value, now):
    try:
        value = int(value)
    except (TypeError, ValueError, OverflowError):
        return 0
    return value if 0 <= value <= now + 5 * 60 * 1000 else 0


def _clean_world_settings(raw):
    source = raw if isinstance(raw, dict) else {}
    result = {}
    string_limits = {
        "theme": 24,
        "focusMusicTrackId": 80,
        "availability": 20,
        "activityCategory": 48,
        "publicDoor": 12,
        "statusEmoji": 48,
        "statusNote": 40,
        "outfitColor": 32,
        "outfitStyle": 32,
    }
    for key, limit in string_limits.items():
        if key in source:
            result[key] = clean_string(source.get(key), limit)
    number_bounds = {
        "lightLevel": (40, 140),
        "moveSpeed": (50, 300),
        "moveAccel": (25, 1000),
        "focusMusicVolume": (0, 100),
    }
    for key, bounds in number_bounds.items():
        try:
            value = int(round(float(source.get(key))))
        except (TypeError, ValueError, OverflowError):
            continue
        result[key] = max(bounds[0], min(bounds[1], value))
    for key in (
        "focusMusicMuted", "faceImage", "labels", "reducedData",
        "debugPanel",
    ):
        if key in source:
            result[key] = bool(source.get(key))
    privacy = source.get("privacy")
    if isinstance(privacy, dict):
        result["privacy"] = {
            key: bool(privacy.get(key))
            for key in WORLD_PREFERENCES_PRIVACY_KEYS
            if key in privacy
        }
    return result


def _clean_world_saved_view(raw, now):
    if not isinstance(raw, dict):
        return None
    view_id = clean_string(raw.get("id"), 40)
    label = clean_string(raw.get("label"), 14)
    if (
        not re.fullmatch(r"[a-z0-9-]{8,40}", view_id)
        or not label
        or not re.fullmatch(r"[\w _-]{1,14}", label, re.UNICODE)
    ):
        return None
    office = raw.get("office") is True
    floor_id = clean_string(raw.get("floorId"), 30)
    space = clean_string(raw.get("space"), 32)
    if office and not re.fullmatch(r"[a-z0-9-]{1,30}", floor_id):
        return None
    camera = raw.get("camera") if isinstance(raw.get("camera"), dict) else {}
    try:
        x = float(raw.get("x"))
        y = float(raw.get("y"))
        z = float(raw.get("z"))
        heading = float(raw.get("heading"))
        yaw = float(camera.get("yaw"))
        pitch = float(camera.get("pitch"))
        zoom = float(camera.get("zoom"))
    except (TypeError, ValueError, OverflowError):
        return None
    if (
        any(not math.isfinite(value) for value in (
            x, y, z, heading, yaw, pitch, zoom))
        or abs(x) > 100 or abs(y) > 100 or abs(z) > 100
        or abs(heading) > math.pi or abs(yaw) > math.pi * 2
        or abs(pitch) > math.pi / 2 or not 0.2 <= zoom <= 8
    ):
        return None
    thumbnail = clean_string(raw.get("thumbnail"), 48000)
    if not re.fullmatch(
            r"data:image/webp;base64,[A-Za-z0-9+/=]+", thumbnail):
        thumbnail = ""
    return {
        "id": view_id,
        "label": label,
        "office": office,
        "floorId": floor_id if office else "",
        "space": "town-square" if office else space,
        "x": x,
        "y": y,
        "z": z,
        "heading": heading,
        "camera": {
            "mode": (
                "first-person"
                if camera.get("mode") == "first-person"
                else "third-person"
            ),
            "yaw": yaw,
            "pitch": pitch,
            "zoom": zoom,
        },
        "thumbnail": thumbnail,
        "updatedAt": _world_preference_timestamp(
            raw.get("updatedAt"), now),
    }


def _clean_world_preferences(raw, now):
    source = raw if isinstance(raw, dict) else {}
    views = []
    seen = set()
    for item in source.get("savedViews", []) if isinstance(
            source.get("savedViews"), list) else []:
        view = _clean_world_saved_view(item, now)
        if not view or view["id"] in seen:
            continue
        seen.add(view["id"])
        views.append(view)
    views.sort(key=lambda item: item["updatedAt"], reverse=True)
    return {
        "settings": _clean_world_settings(source.get("settings")),
        "settingsUpdatedAt": _world_preference_timestamp(
            source.get("settingsUpdatedAt"), now),
        "savedViews": views[:WORLD_PREFERENCES_MAX_VIEWS],
        "updatedAt": _world_preference_timestamp(
            source.get("updatedAt"), now),
    }


async def world_preferences_handler(env, request):
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST"):
        return json_response({"error": "method_not_allowed"}, status=405)
    data = {}
    if method == "POST":
        if not _request_same_origin(request):
            return json_response({"error": "origin_not_allowed"}, status=403)
        try:
            data = await bounded_json_request(
                request, WORLD_PREFERENCES_MAX_BYTES)
        except RequestBodyTooLarge:
            return json_response({"error": "payload_too_large"}, status=413)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
    account_bi, rec = await _account_session_record(env, request, data)
    if not account_bi or not rec:
        return json_response({"error": "invalid_session"}, status=401)
    now = int(Date.now())
    stored = _clean_world_preferences(
        rec.get("world_preferences"), now)
    if method == "POST":
        incoming = _clean_world_preferences(data, now)
        settings = stored["settings"]
        settings_updated_at = stored["settingsUpdatedAt"]
        if incoming["settingsUpdatedAt"] >= settings_updated_at:
            settings = incoming["settings"]
            settings_updated_at = incoming["settingsUpdatedAt"]
        by_id = {view["id"]: view for view in stored["savedViews"]}
        for view in incoming["savedViews"]:
            previous = by_id.get(view["id"])
            if not previous or view["updatedAt"] >= previous["updatedAt"]:
                by_id[view["id"]] = view
        views = sorted(
            by_id.values(),
            key=lambda item: item["updatedAt"],
            reverse=True,
        )[:WORLD_PREFERENCES_MAX_VIEWS]
        stored = {
            "settings": settings,
            "settingsUpdatedAt": settings_updated_at,
            "savedViews": views,
            "updatedAt": now,
        }
        rec["world_preferences"] = stored
        await _save_account(env, account_bi, rec)
    return json_response({
        "ok": True,
        **stored,
        "storage": "account-encrypted",
    }, cache_control="no-store")


