def room_key_from_path(pathname, account_bi=""):
    direct_pattern = globals().get("CHAT_DIRECT_MESSAGE_DO_RE")
    match = direct_pattern.match(pathname) if direct_pattern else None
    if match and match.group(3) == "ws":
        conversation_id = match.group(1)
        direct_version = int(match.group(2))
        info = {
            "key": (
                "chat-direct:" + conversation_id + ":v"
                + str(direct_version)
            ),
            "owner": "",
            "repo": "",
            "room": conversation_id,
            "compat": False,
            "direct_id": conversation_id,
            "direct_version": direct_version,
        }
        if re.fullmatch(r"[0-9a-f]{64}", str(account_bi or "")):
            info["account_bi"] = str(account_bi)
        return info

    match = CHAT_CHANNEL_DO_RE.match(pathname)
    if match and match.group(3) == "ws":
        channel_id = match.group(1)
        channel_version = int(match.group(2))
        info = {
            "key": (
                "chat-channel:" + channel_id + ":v"
                + str(channel_version)
            ),
            "owner": "",
            "repo": "",
            "room": channel_id,
            "compat": False,
            "channel_id": channel_id,
            "channel_version": channel_version,
        }
        if re.fullmatch(r"[0-9a-f]{64}", str(account_bi or "")):
            info["account_bi"] = str(account_bi)
        return info

    match = REPO_ROOM_RE.match(pathname)
    if match:
        owner = safe_segment(match.group(1))
        repo = safe_segment(match.group(2))
        room = safe_segment(match.group(3), MAX_ROOM_NAME)
        if not owner or not repo or not room:
            return None
        return {
            "key": f"repo:{owner}/{repo}:room:{room}",
            "owner": owner,
            "repo": repo,
            "room": room,
            "compat": False,
        }

    match = ROOM_RE.match(pathname)
    if not match:
        return None

    room = safe_segment(match.group(1), MAX_ROOM_NAME)
    if not room:
        return None
    return {
        "key": f"legacy:room:{room}",
        "owner": "",
        "repo": "",
        "room": room,
        "compat": True,
    }


def clean_media_png(value, max_bytes):
    """clean_avatar_png generalized for repo branding: accepts a bare-base64 or
    data-URL PNG up to max_bytes raw, returns (normalized_b64, error)."""
    if not isinstance(value, str):
        return "", "bad_image"
    image = value.strip()
    if image.startswith("data:image/png;base64,"):
        image = image.split(",", 1)[1].strip()
    if not image:
        return "", ""
    if len(image) > 4 * ((max_bytes + 2) // 3):
        return "", "image_too_large"
    try:
        raw = base64.b64decode(image, validate=True)
    except Exception:
        return "", "bad_image"
    if len(raw) > max_bytes:
        return "", "image_too_large"
    if not raw.startswith(PNG_HEADER):
        return "", "bad_image"
    return base64.b64encode(raw).decode(), ""


def clean_avatar_png(value):
    if not isinstance(value, str):
        return "", "bad_avatar"
    avatar = value.strip()
    if avatar.startswith("data:image/png;base64,"):
        avatar = avatar.split(",", 1)[1].strip()
    if not avatar:
        return "", ""
    if len(avatar) > MAX_AVATAR_B64:
        return "", "avatar_too_large"
    try:
        raw = base64.b64decode(avatar, validate=True)
    except Exception:
        return "", "bad_avatar"
    if len(raw) > MAX_AVATAR_BYTES:
        return "", "avatar_too_large"
    if not raw.startswith(PNG_HEADER):
        return "", "bad_avatar"
    return base64.b64encode(raw).decode(), ""


# Owners (or repo names) that must never appear in the public catalog / under
# /network/, and may never register host presence. Seeded with a known phantom
# account that kept re-publishing; extend without a code change via the
# BLOCKED_CATALOG_OWNERS env var (comma/space separated, case-insensitive).
_BLOCKED_CATALOG_DEFAULT = {"7cbaf0dc"}


def _blocked_catalog_set(env):
    raw = (getattr(env, "BLOCKED_CATALOG_OWNERS", "") or "").replace(",", " ")
    extra = {part.strip().lower() for part in raw.split() if part.strip()}
    return _BLOCKED_CATALOG_DEFAULT | extra


def _is_blocked_catalog_identity(env, *values):
    blocked = _blocked_catalog_set(env)
    for value in values:
        if value and str(value).strip().lower() in blocked:
            return True
    return False


async def purge_blocked_catalog(env):
    # Delete any catalog rows (and their host-presence rows) belonging to a
    # blocked owner, so phantom entries already in D1 disappear and stay gone.
    for owner in _blocked_catalog_set(env):
        owner_bi = await blind_index(env, owner)
        rows = await d1_all(
            env, "SELECT key_bi FROM repositories WHERE owner_bi=?", owner_bi)
        for r in (rows or []):
            await _delete_repo_scoped_state(env, r["key_bi"])
            await d1_run(
                env, "DELETE FROM host_presence WHERE repo_bi=?", r["key_bi"])
        await d1_run(env, "DELETE FROM repositories WHERE owner_bi=?", owner_bi)


async def purge_stale_account_devices(env):
    # Prune the reinstall/rotate device sprawl (see STALE_DEVICE_RETAIN_MS):
    # account_devices rows untouched for the retention window, but ONLY when the
    # same account still has a newer device row. That guarantees a node's current
    # key is never deleted — deleting the key the node signs with would silently
    # 401 its drains, the very bug _owner_signing_pubkeys fixes. A pruned key that
    # a user later rotates back to is simply re-registered on the next login
    # (_register_account_device upserts). Returns the number of rows removed.
    now = int(Date.now())
    cutoff = now - STALE_DEVICE_RETAIN_MS
    rows = await d1_all(
        env,
        "SELECT device_bi, account_bi, COALESCE(last_seen,0) AS last_seen "
        "FROM account_devices WHERE COALESCE(last_seen,0) < ? "
        "ORDER BY last_seen ASC LIMIT ?",
        cutoff, STALE_DEVICE_PURGE_BATCH)
    removed = 0
    for row in rows or []:
        account_bi = row.get("account_bi")
        seen = int(row.get("last_seen") or 0)
        newer = await d1_first(
            env,
            "SELECT 1 AS x FROM account_devices "
            "WHERE account_bi=? AND COALESCE(last_seen,0) > ? LIMIT 1",
            account_bi, seen)
        if not newer:
            continue  # the account's most-recent key — keep it so it can sign
        await d1_run(
            env, "DELETE FROM account_devices WHERE device_bi=?",
            row.get("device_bi"))
        removed += 1
    return removed


async def active_registered_node_bis(env, now=None):
    # A node is active if either its physical node row has recent activity, its
    # signed account heartbeat is recent, or its signed direct-HTTPS endpoint is
    # fresh and healthy. The last union preserves bounded upgrade compatibility.
    await ensure_schema(env)
    now = int(now if now is not None else Date.now())
    cutoff = now - REGISTERED_NODE_ACTIVE_MS
    active = set()
    rows = await d1_all(
        env,
        """SELECT node_bi AS key FROM nodes WHERE COALESCE(last_seen, 0) >= ?
           UNION
           SELECT name_bi AS key FROM account_presence WHERE ts >= ?
           UNION
           SELECT n.node_bi AS key
             FROM mirror_https_endpoints e
             JOIN nodes n ON lower(n.name)=lower(e.node_name)
            WHERE e.healthy=1 AND e.abuse_blocked=0
              AND e.integrity='ok' AND e.checked_at >= ?
           UNION
           SELECT r.owner_bi AS key
             FROM host_presence hp
             JOIN repositories r ON r.key_bi = hp.repo_bi
            WHERE hp.ts >= ?""",
        cutoff, cutoff, cutoff, cutoff,
    )
    for row in rows or []:
        key = str(row.get("key") or "")
        if key:
            active.add(key)
    return active


async def _decrypted_public_catalog(env, now):
    # Decrypted {key_bi, is_private, data} rows for every retained public repo,
    # memoized per-isolate for PUBLIC_CATALOG_MEMO_TTL_MS — see the comment on
    # _PUBLIC_CATALOG_MEMO for why this must not re-decrypt the whole catalog on
    # every call. Online/serving eligibility is checked separately from fresh
    # signed endpoint evidence; an offline owner must not disappear here.
    cached = _PUBLIC_CATALOG_MEMO
    if cached["rows"] is not None and now - cached["ts"] < PUBLIC_CATALOG_MEMO_TTL_MS:
        return cached["rows"]
    # Single-flight refill: under a clone burst every concurrent request lands
    # here the moment the TTL lapses, and each used to start its OWN full scan
    # + sequential decrypt_row() pass — recreating, once per TTL window, the
    # event-loop congestion this memo exists to prevent ("Cannot enter into
    # task" on git-upload-pack info/refs). The first caller claims the refresh
    # slot (no await between check and claim, so the claim is atomic on the
    # single-threaded loop) and refills; concurrent callers keep the stale
    # rows, which only feed best-effort mirror selection. Deliberately NOT a
    # shared future/lock: a request resuming inside I/O another request
    # started dies with "Cannot perform I/O on behalf of a different request"
    # (see ensure_schema). A cold isolate (rows is None) still refills from
    # every caller — there is nothing stale to serve them.
    if cached["rows"] is not None and \
            now - cached["refresh_ts"] < PUBLIC_CATALOG_MEMO_TTL_MS:
        return cached["rows"]
    cached["refresh_ts"] = now
    try:
        rows = await d1_all(
            env,
            "SELECT key_bi, owner_bi, data, is_private FROM repositories WHERE is_private = 0")
        catalog_rows = []
        decrypted = {}
        for row in rows:
            blob = str(row.get("data") or "")
            rec = _CATALOG_ROW_DECRYPT_MEMO.get(blob)
            if not rec:
                rec = await decrypt_row(env, blob)
                if not rec:
                    continue
            if rec.get("visibility") != "public":
                continue
            if len(decrypted) < CATALOG_ROW_DECRYPT_MEMO_MAX:
                decrypted[blob] = rec
            catalog_rows.append({
                "key_bi": row.get("key_bi"),
                "is_private": int(row.get("is_private") or 0),
                "data": rec,
            })
        _CATALOG_ROW_DECRYPT_MEMO.clear()
        _CATALOG_ROW_DECRYPT_MEMO.update(decrypted)
    except BaseException:
        # Release the slot (covers CancelledError from a canceled request) so
        # the next caller retries instead of waiting out a phantom refresh.
        cached["refresh_ts"] = 0
        raise
    cached["rows"] = catalog_rows
    cached["ts"] = now
    return catalog_rows


async def purge_stale_registered_nodes(env, force=False):
    # Remove expired transient presence and bound only truly orphaned physical
    # node registrations. Repository catalog rows are durable owner-signed
    # identity: temporary downtime must never cascade into namespace deletion.
    # A stale node that still owns a repository or direct-HTTPS endpoint remains
    # registered and is simply reported offline until fresh evidence returns.
    await ensure_schema(env)
    now = int(Date.now())
    if not force and now - int(_stale_node_purge.get("ts") or 0) < STALE_NODE_PURGE_INTERVAL_MS:
        return 0
    _stale_node_purge["ts"] = now
    cutoff = now - REGISTERED_NODE_ACTIVE_MS
    try:
        await d1_run(env, "DELETE FROM account_presence WHERE ts < ?", cutoff)
        await notify_stale_hosts_offline(env, cutoff)
        await d1_run(env, "DELETE FROM host_presence WHERE ts < ?", cutoff)
    except Exception:
        pass
    active = await active_registered_node_bis(env, now)
    rows = await d1_all(
        env,
        """SELECT n.node_bi, n.name FROM nodes n
           WHERE COALESCE(n.last_seen, 0) < ?
             AND NOT EXISTS (
                 SELECT 1 FROM repositories r
                  WHERE r.owner_bi = n.node_bi
             )
             AND NOT EXISTS (
                 SELECT 1 FROM mirror_https_endpoints e
                  WHERE e.node_bi = n.node_bi
                     OR lower(e.node_name) = lower(n.name)
             )
           ORDER BY COALESCE(n.last_seen, 0) ASC
           LIMIT ?""",
        cutoff, STALE_NODE_PURGE_BATCH,
    )
    removed = 0
    for row in rows or []:
        node_bi = str(row.get("node_bi") or "")
        if not node_bi or node_bi in active:
            continue
        try:
            await d1_run(env, "DELETE FROM nodes WHERE node_bi=?", node_bi)
            removed += 1
        except Exception:
            continue
    if removed:
        await purge_catalog_related_caches()
    return removed


# --- D1 storage --------------------------------------------------------------
# Durable Objects are reserved for transient relaying (chat rooms + the live
# file/git tunnel). Everything that must persist lives in D1, and every row is
# encrypted at rest: each table stores HMAC "blind index" columns (for lookups
# and uniqueness) plus a single AES-GCM-encrypted JSON `data` blob. The worker
# holds DATA_KEY, so this protects data at rest but is not zero-knowledge.

PBKDF2_ITERS = 100000
SOLANA_RE = re.compile(r"^[1-9A-HJ-NP-Za-km-z]{32,44}$")

# Legacy deposit-record constants remain only for read-only historical status
# and the offline migration tool. Signup is free; no deployed Worker creates
# deposit wallets, holds a wallet signing key, or sweeps funds.
LAMPORTS_PER_SOL = 1000000000
# Historical records without an explicit amount use this compatibility value
# for display/reconciliation only. No live endpoint requests it.
MIN_JOIN_LAMPORTS = 5_000_000
# Per-isolate memo of the decrypted public repo catalog. _select_browse_mirror
# runs on EVERY public info/refs request (git clone's round-robin mirror
# pick) and previously re-ran a full D1 scan plus a sequential AES-GCM
# decrypt_row() per public repo on each call — under a clone burst (CI, many
# contributors pulling at once) that held the single Worker event loop long
# enough for the runtime to cancel a request as hung ("Cannot enter into
# task"), same failure mode already fixed elsewhere via per-isolate memoization
# (see the 2026-07-11 free-plan overload notes). A short TTL is fine: this only
# feeds best-effort mirror selection, not the integrity-checked ref content.
_PUBLIC_CATALOG_MEMO = {"ts": 0, "rows": None, "refresh_ts": 0}
PUBLIC_CATALOG_MEMO_TTL_MS = 5000
# Ciphertext -> decrypted record, reused ACROSS catalog memo refills. The 5s
# memo above stopped every request from re-decrypting the catalog, but the one
# request that claims each refill still paid a full AES-GCM decrypt_row() per
# public repo — pure Pyodide CPU (base64 + JS-boundary crossings per row) that
# grows with the catalog and landed on whichever request lapsed the TTL. Under
# clone traffic that is an info/refs request, and a large catalog pushed that
# single request past the Workers CPU limit ("Worker exceeded CPU time limit"
# on GET .../info/refs, adhoc #183 — the same clone-path family as #144/#153/
# #167). A row's encrypted blob is rewritten (fresh IV) on every update, so an
# unchanged blob is byte-identical and its previous plaintext is still valid:
# a refill now only decrypts rows whose ciphertext actually changed. Records
# are shared read-only by catalog consumers (they already share them for a TTL
# window via the memo above) and must not be mutated. Rebuilt from the rows
# seen each refill, so deleted rows drop out and the memo stays bounded by the
# live catalog (plus a hard cap as a backstop).
_CATALOG_ROW_DECRYPT_MEMO = {}
CATALOG_ROW_DECRYPT_MEMO_MAX = 4096
DONATION_ADDRESS_TTL_MS = 60 * 60 * 1000
# Historical expiry metadata is retained for migration/reconciliation only.
DONATION_ADDRESS_DELETE_GRACE_MS = 60 * 60 * 1000
# Reserve one approximate transaction fee when checking whether the external
# community pool can support a locally reviewed transfer plan.
REWARD_POOL_FEE_RESERVE_LAMPORTS = 5000
# A node counts as online for payouts if it has sent a heartbeat within this
# window (reuses the host-presence staleness window).
ACCOUNT_PRESENCE_STALE_MS = 10 * 60 * 1000
HEARTBEAT_SOLANA_BALANCE_TIMEOUT_MS = 1500
# Per-isolate throttle for the heartbeat's optional public balance probe:
# wallet -> last probe ms. Five minutes avoids an RPC subrequest on every
# 60-second heartbeat. Balance never gates eligibility.
HEARTBEAT_SOLANA_BALANCE_MIN_MS = 5 * 60 * 1000
_HEARTBEAT_BALANCE_PROBES = {}
# Community reward-pool planning (issue #308): the Worker may read one configured
# public address and create unsigned distribution intents. Its owner signs those
# intents on their own device; no Worker secret or cron path can sign or sweep.
CENTRAL_FUND_DISTRIBUTION_INTERVAL_MS = 60 * 60 * 1000  # plan hourly
# Reward timing, amount, observed uptime, and optional contribution threshold
# are operator-configurable within conservative bounds. Randomized rounds pay
# one eligible node; "instant" voluntary contributions use a separate all-node
# intent and never bypass these eligibility checks.
REWARD_DEFAULT_AMOUNT_LAMPORTS = 100_000
REWARD_DEFAULT_JITTER_MS = 45 * 60 * 1000
REWARD_DEFAULT_MIN_UPTIME_MS = 30 * 60 * 1000
REWARD_ENDPOINT_FRESH_MS = 10 * 60 * 1000
REWARD_OBSERVATION_GAP_MS = 20 * 60 * 1000
REWARD_CONTRIBUTION_MIN_LAMPORTS = 10_000
REWARD_CONTRIBUTION_MAX_LAMPORTS = 100 * LAMPORTS_PER_SOL
REWARD_CONTRIBUTION_EXPIRES_MS = 60 * 60 * 1000
REWARD_PENDING_EXPIRES_MS = 24 * 60 * 60 * 1000
# Legacy Solana messages are size-bounded. Eight ordinary System transfers per
# transaction leaves headroom for signatures/account metadata; larger all-node
# distributions become an explicitly numbered multi-intent batch.
REWARD_TRANSFERS_PER_INTENT = 8

_schema_ready = False
_stale_node_purge = {"ts": 0}
LEGACY_WALLET_CUSTODY_MARKER = "legacy_wallet_custody_v2"
LEGACY_WALLET_CUSTODY_TABLES = (
    "accounts",
    "users",
    "nodes",
    "federated_signup",
    "issue_bounty",
    "bounty_wallet",
    "central_fund",
)

# Derived WebCrypto keys are pure functions of the DATA_KEY secret, which is
# constant for an isolate's lifetime. Deriving them (SHA-256 digest + importKey,
# two async WebCrypto round trips each) on every blind_index / encrypt_row /
# decrypt_row call was the dominant per-request CPU cost on hot polled endpoints
# (/api/notifications, /api/accounts/<name>). Cache the imported CryptoKeys,
# keyed by the current secret so a secret rotation still takes effect.
_data_key_cache = {"secret": None, "key": None}
_hmac_key_cache = {"secret": None, "key": None}
_room_key_cache = {"secret": None, "value": None}


# Compatibility columns required by indexes in SCHEMA_STATEMENTS. These run
# before the CREATE statements so an existing table can be upgraded before an
# index references its new columns. A fresh database has no table yet, so the
# failed ALTER is ignored and the current CREATE TABLE supplies the columns.
SCHEMA_PRE_CREATE_ALTER_STATEMENTS = [
    "ALTER TABLE ap_outbox ADD COLUMN dedupe_bi TEXT",
    "ALTER TABLE ap_comments ADD COLUMN parent_remote_id_bi TEXT",
    """ALTER TABLE ap_comments ADD COLUMN lifecycle TEXT NOT NULL DEFAULT 'active'
       CHECK (lifecycle IN (
         'active', 'edited', 'tombstoned', 'moderated',
         'awaiting-redelivery'
       ))""",
    # Direct-message lazy upgrades must precede SCHEMA_STATEMENTS: that list
    # creates indexes/triggers over these columns, and CREATE TABLE IF NOT
    # EXISTS cannot add them to a database that predates migration 0084.
    """ALTER TABLE chat_direct_conversations
       ADD COLUMN message_count INTEGER NOT NULL DEFAULT 0
       CHECK (message_count >= 0)""",
    """ALTER TABLE chat_direct_participants
       ADD COLUMN last_read_count INTEGER NOT NULL DEFAULT 0
       CHECK (last_read_count >= 0)""",
    """ALTER TABLE chat_direct_participants
       ADD COLUMN initiated INTEGER NOT NULL DEFAULT 0
       CHECK (initiated IN (0, 1))""",
]

# Post-CREATE column additions for tables that predate them. Idempotent: a
# re-run raises "duplicate column name", which the applier swallows.
SCHEMA_ALTER_STATEMENTS = [
    # Private repos flag (won't be added by CREATE TABLE IF NOT EXISTS).
    "ALTER TABLE repositories ADD COLUMN is_private INTEGER NOT NULL DEFAULT 0",
    # Plaintext blind index of the (signature-verified) submitter on each inbox
    # row, so a per-author quota can be enforced with a COUNT instead of
    # decrypting every pending row.
    "ALTER TABLE issue_inbox ADD COLUMN submitter_bi TEXT",
    # Mirror drain leases. Deploy migrations add their compound index; the
    # lazy compatibility path stays correct with the existing repo index.
    "ALTER TABLE issue_inbox ADD COLUMN claimed_by_bi TEXT NOT NULL DEFAULT ''",
    "ALTER TABLE issue_inbox ADD COLUMN claim_expires_at INTEGER NOT NULL DEFAULT 0",
    "ALTER TABLE issue_inbox ADD COLUMN mirrored_by_bi TEXT NOT NULL DEFAULT ''",
    "ALTER TABLE issue_inbox ADD COLUMN mirrored_at INTEGER NOT NULL DEFAULT 0",
    # Completed Office tasks retain their encrypted copy, accumulated time,
    # and audit history while remaining impossible to restart.
    """ALTER TABLE world_office_marketing_tasks
       ADD COLUMN completed_at INTEGER NOT NULL DEFAULT 0
       CHECK (completed_at >= 0)""",
    """CREATE INDEX IF NOT EXISTS idx_world_office_marketing_tasks_completion
       ON world_office_marketing_tasks(
           org_bi, completed_at, updated_at DESC)""",
    # A bounded heartbeat closes interrupted Office visits and carries only the
    # public floor label used by the lobby board.
    """ALTER TABLE world_office_attendance
       ADD COLUMN last_seen_at INTEGER NOT NULL DEFAULT 0
       CHECK (last_seen_at >= 0)""",
    """ALTER TABLE world_office_attendance
       ADD COLUMN floor_id TEXT NOT NULL DEFAULT ''
       CHECK (length(floor_id) <= 32)""",
    """CREATE INDEX IF NOT EXISTS idx_world_office_attendance_live
       ON world_office_attendance(out_at, last_seen_at DESC)""",
    """ALTER TABLE world_office_attendance
       ADD COLUMN visit_scope TEXT NOT NULL DEFAULT 'legacy'
       CHECK (visit_scope IN ('legacy', 'office'))""",
    """CREATE INDEX IF NOT EXISTS idx_world_office_attendance_scope
       ON world_office_attendance(visit_scope, account_bi, in_at)""",
    # Assigned issue titles are already public repository metadata; retain a
    # bounded copy so the build-board card survives the recent-issues window.
    """ALTER TABLE world_build_board_items
       ADD COLUMN title TEXT NOT NULL DEFAULT ''
       CHECK (length(title) <= 160)""",
    "ALTER TABLE pull_inbox ADD COLUMN submitter_bi TEXT",
    "ALTER TABLE commit_inbox ADD COLUMN submitter_bi TEXT",
    "ALTER TABLE discussion_inbox ADD COLUMN submitter_bi TEXT",
    # Raw User-Agent of each release download, shown in the admin list (migration 0034).
    "ALTER TABLE release_downloads ADD COLUMN ua TEXT",
    # Operator-settable flag granting a user access to the /outreach console
    # without a roster row (migration 0040). Mirrors is_admin.
    "ALTER TABLE users ADD COLUMN enable_outreach INTEGER NOT NULL DEFAULT 0",
    # Early local builds created membership rows before their encrypted display
    # payload was added. Existing blind-index grants remain valid; new writes
    # always provide this ciphertext column.
    "ALTER TABLE chat_channel_members ADD COLUMN data TEXT",
    # Reward eligibility independently re-verifies the exact signed health
    # evidence. Keeping the normalized operation list lets that verifier
    # recompute the signed digest and required-operation subset instead of
    # trusting a mutable forkmesh_active boolean.
    """ALTER TABLE mirror_https_endpoints
       ADD COLUMN forkmesh_operations_json TEXT NOT NULL DEFAULT '[]'""",
    # Heading offset in radians for an administrator-locked scene object
    # (migration 0082). 0 keeps the object's authored rotation.
    "ALTER TABLE world_object_layout ADD COLUMN rotation REAL NOT NULL DEFAULT 0",
    # Edge-observed sign-in address of each account session, shown only to the
    # owner of that account in the World security tab and account settings.
    "ALTER TABLE account_sessions ADD COLUMN client_ip TEXT NOT NULL DEFAULT ''",
]

# Fingerprint of the DDL this build would apply. Stored in schema_meta after a
# full apply so later cold isolates can skip the replay with one SELECT.
_SCHEMA_FINGERPRINT = hashlib.sha256(
    "\n".join(
        SCHEMA_PRE_CREATE_ALTER_STATEMENTS
        + SCHEMA_STATEMENTS
        + SCHEMA_ALTER_STATEMENTS
    ).encode("utf-8")
).hexdigest()


async def ensure_schema(env):
    # A Worker isolate serves many requests concurrently on one event loop, so
    # this must never block on a cross-request coordination primitive: an
    # asyncio.Lock shared between concurrently-running requests here used to
    # let one request's await resume inside another request's I/O context,
    # which Cloudflare rejects ("Cannot perform I/O on behalf of a different
    # request") on the very next await in the waiting request. Every request
    # instead takes the cheap fingerprint SELECT fast path independently
    # (schema.py's CREATE statements are all IF NOT EXISTS / idempotent), so
    # concurrent cold-isolate requests never touch a shared awaitable.
    if _schema_ready:
        return
    await _apply_schema(env)


async def _assert_legacy_wallet_custody_ready(env):
    """Refuse D1-backed service while a historical wallet key remains.

    Migration 0057 invalidates the marker on every upgraded deployment. The
    first matching Worker then decrypts every row in every historical
    key-bearing shape. A missing/invalid ciphertext or any recognized wallet
    secret fails closed; only a complete clean scan writes the fast-path
    marker. The explicit offline scrub writes the same marker after its guarded
    updates, so a quiesced migrated database starts without another full scan.
    """
    marker = await d1_first(
        env, "SELECT v FROM schema_meta WHERE k=?", LEGACY_WALLET_CUSTODY_MARKER)
    if marker and str(marker.get("v") or "").startswith("clean-v2:"):
        return
    for table in LEGACY_WALLET_CUSTODY_TABLES:
        try:
            rows = await d1_all(env, "SELECT data FROM " + table)
        except Exception as error:
            if "no such table" in str(error).lower():
                continue
            raise
        for row in rows or []:
            decoded = await decrypt_row(env, row.get("data", ""))
            if not isinstance(decoded, dict):
                raise RuntimeError("legacy_custody_migration_required")
            if _admin_contains_wallet_key(decoded):
                raise RuntimeError("legacy_custody_migration_required")
    await d1_run(
        env,
        "INSERT INTO schema_meta (k,v) VALUES (?,?) "
        "ON CONFLICT(k) DO UPDATE SET v=excluded.v",
        LEGACY_WALLET_CUSTODY_MARKER,
        "clean-v2:" + _SCHEMA_FINGERPRINT,
    )


async def _apply_schema(env):
    global _schema_ready
    # Fast path: the deploy's migrate.sh (and any prior isolate's full apply)
    # records the applied DDL's fingerprint. One SELECT replaces the ~110
    # sequential statements below — which, replayed on every cold isolate, were
    # the dominant startup cost for both requests and the per-minute cron (the
    # cron routinely blew its resource limits and the /status page recorded the
    # missing samples as downtime).
    try:
        row = await d1_first(
            env, "SELECT v FROM schema_meta WHERE k='fingerprint'")
        if row and row.get("v") == _SCHEMA_FINGERPRINT:
            await _assert_legacy_wallet_custody_ready(env)
            prune_actors = globals().get("_ap_prune_actor_inventory")
            if callable(prune_actors):
                await prune_actors(env)
            _schema_ready = True
            return
    except Exception as exc:
        # Only a genuinely absent schema_meta table means "first run against
        # this DB". A transient D1 failure (overload / internal error) must
        # propagate instead: falling through here made every request replay
        # the full DDL right when the DB was already struggling, amplifying
        # the overload into a death spiral.
        if "no such table" not in str(exc).lower():
            raise
    for sql in SCHEMA_PRE_CREATE_ALTER_STATEMENTS:
        try:
            await env.DB.prepare(sql).run()
        except Exception:
            pass
    for sql in SCHEMA_STATEMENTS:
        await env.DB.prepare(sql).run()
    for sql in SCHEMA_ALTER_STATEMENTS:
        try:
            await env.DB.prepare(sql).run()
        except Exception:
            pass
    await d1_run(
        env,
        "INSERT INTO schema_meta (k, v) VALUES ('fingerprint', ?) "
        "ON CONFLICT(k) DO UPDATE SET v=excluded.v",
        _SCHEMA_FINGERPRINT,
    )
    await _assert_legacy_wallet_custody_ready(env)
    prune_actors = globals().get("_ap_prune_actor_inventory")
    if callable(prune_actors):
        await prune_actors(env)
    _schema_ready = True


def js_nullish(value):
    return value is None or type(value).__name__ in ("JsNull", "JsUndefined")


def d1_row_to_dict(row):
    if js_nullish(row):
        return None
    if hasattr(row, "to_py"):
        row = row.to_py()
        if js_nullish(row):
            return None
    return dict(row)


async def d1_all(env, sql, *args):
    stmt = env.DB.prepare(sql)
    if args:
        stmt = stmt.bind(*args)
    result = await stmt.all()
    out = []
    results = getattr(result, "results", None)
    if js_nullish(results):
        return out
    for row in results:
        converted = d1_row_to_dict(row)
        if converted is not None:
            out.append(converted)
    return out


async def d1_first(env, sql, *args):
    stmt = env.DB.prepare(sql)
    if args:
        stmt = stmt.bind(*args)
    row = await stmt.first()
    return d1_row_to_dict(row)


async def d1_run(env, sql, *args):
    stmt = env.DB.prepare(sql)
    if args:
        stmt = stmt.bind(*args)
    await stmt.run()


# --- Encryption-at-rest + blind index ---------------------------------------

# Known placeholder values that must never reach production: application rows
# include credentials and historical migration records, and publicly known
# at-rest encryption would be equivalent to storing those values in plaintext.
_INSECURE_DATA_KEYS = frozenset({
    "", "forkmesh-dev-data-key", "forkmesh-dev-data-key-change-me",
})


def _require_data_secret(env):
    # Fail closed: a missing or placeholder DATA_KEY would silently encrypt every
    # protected application row under a public key. Set a real Worker secret:
    #   uvx --from workers-py pywrangler secret put DATA_KEY
    secret = (getattr(env, "DATA_KEY", "") or "").strip()
    if secret in _INSECURE_DATA_KEYS:
        raise RuntimeError(
            "DATA_KEY is unset or a known placeholder; refusing to use a public "
            "key for at-rest encryption. Set DATA_KEY as a Worker secret.")
    return secret


async def _data_key(env):
    secret = _require_data_secret(env)
    if _data_key_cache["secret"] == secret and _data_key_cache["key"] is not None:
        return _data_key_cache["key"]
    digest = await js_crypto.subtle.digest("SHA-256", _to_js(secret.encode()))
    key = await js_crypto.subtle.importKey(
        "raw", digest, to_js({"name": "AES-GCM"}), False,
        _to_js(["encrypt", "decrypt"])
    )
    _data_key_cache["secret"] = secret
    _data_key_cache["key"] = key
    return key


async def encrypt_row(env, obj):
    key = await _data_key(env)
    iv = js_crypto.getRandomValues(Uint8Array.new(12))
    plaintext = json.dumps(obj).encode()
    cipher = await js_crypto.subtle.encrypt(
        to_js({"name": "AES-GCM", "iv": iv}), key, _to_js(plaintext)
    )
    blob = bytes(iv.to_py()) + bytes(Uint8Array.new(cipher).to_py())
    return base64.b64encode(blob).decode()


async def decrypt_row(env, stored, key=None):
    try:
        blob = base64.b64decode(stored)
        iv = _to_js(blob[:12])
        cipher = _to_js(blob[12:])
        if key is None:
            key = await _data_key(env)
        plain = await js_crypto.subtle.decrypt(
            to_js({"name": "AES-GCM", "iv": iv}), key, cipher
        )
        return json.loads(bytes(Uint8Array.new(plain).to_py()).decode())
    except Exception:
        return None


async def _hmac_key(env):
    # A distinct key context so the blind-index HMAC key isn't the AES key.
    secret = _require_data_secret(env) + ":blind-index"
    if _hmac_key_cache["secret"] == secret and _hmac_key_cache["key"] is not None:
        return _hmac_key_cache["key"]
    digest = await js_crypto.subtle.digest("SHA-256", _to_js(secret.encode()))
    key = await js_crypto.subtle.importKey(
        "raw", digest, to_js({"name": "HMAC", "hash": "SHA-256"}), False,
        _to_js(["sign"])
    )
    _hmac_key_cache["secret"] = secret
    _hmac_key_cache["key"] = key
    return key


async def _room_chat_passphrase(
        env, owner="mainnode", repo="forkmesh", room="general"):
    # A repository-scoped room-chat passphrase, derived ONE-WAY from DATA_KEY
    # with its own domain separation (same pattern as the blind-index HMAC key).
    # The legacy authenticated mainnode/forkmesh room deliberately retains the
    # v1 derivation so its retained chat remains readable across this rollout.
    # Public World #general uses a separate, explicitly public derivation and a
    # separate Durable Object room. Giving that key to a guest therefore cannot
    # decrypt authenticated channels or any repository-scoped room.
    #
    # Neither key is a source-code constant. The public room key is intentionally
    # available to guests, while authenticated room keys require repository
    # authorization. This is NOT confidentiality from the relay: its operator
    # holds DATA_KEY and can derive both. SHA-256 is preimage-resistant, so
    # exposing the public passphrase does not expose DATA_KEY or protected
    # application records guarded by the same at-rest key.
    owner = safe_segment(owner)
    repo = safe_segment(repo)
    room = safe_segment(room, MAX_ROOM_NAME)
    if not owner or not repo or not room:
        raise ValueError("invalid repository room scope")
    scope = owner.lower() + "/" + repo.lower()
    if (
        scope == "mainnode/forkmesh"
        and room.lower() == PUBLIC_WORLD_GENERAL_ROOM
    ):
        suffix = ":room-chat-passphrase-public-world-general-v1"
    else:
        suffix = (
            ":room-chat-passphrase-v1"
            if scope == "mainnode/forkmesh"
            else ":room-chat-passphrase-v2:" + scope
        )
    secret = _require_data_secret(env) + suffix
    if _room_key_cache["secret"] == secret and _room_key_cache["value"]:
        return _room_key_cache["value"]
    digest = await js_crypto.subtle.digest("SHA-256", _to_js(secret.encode()))
    value = bytes(Uint8Array.new(digest).to_py()).hex()
    _room_key_cache["secret"] = secret
    _room_key_cache["value"] = value
    return value


async def _room_key_requester(env, request, owner, repo):
    # Resolve the authenticated account/node requesting one repository-scoped
    # passphrase. Browser/mobile callers use their bearer session. A desktop
    # node signs a v2 canonical string that binds the proof to this exact
    # repository. The v1 proof remains accepted only for the well-known public
    # mainnode/forkmesh room so already-installed clients can upgrade cleanly.
    actor = await _authed_account_name(env, request)
    if actor:
        return actor
    params = parse_qs(urlparse(request.url).query)
    node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    ts = clean_string(params.get("ts", [""])[0], 20)
    sig = clean_string(params.get("sig", [""])[0], 200)
    if not node or not sig or not _ts_ok(ts):
        return ""
    pubkey = await _owner_pubkey(env, node)
    if not pubkey:
        return ""
    canonical = (
        "forkmesh-room-key-v2\n" + node + "\n" + owner.lower() + "\n"
        + repo.lower() + "\n" + str(ts)
    ).encode()
    if await ed25519_verify(pubkey, sig, canonical):
        return node
    if owner.lower() == "mainnode" and repo.lower() == "forkmesh":
        legacy = (
            "forkmesh-room-key-v1\n" + node + "\n" + str(ts)
        ).encode()
        if await ed25519_verify(pubkey, sig, legacy):
            return node
    return ""


# Canonical prefixes a desktop client signs with its account's Ed25519 key to
# read the chat-channel API without a browser session token (the Qt app holds
# keys, not sessions). Each proof names the exact resource it opens.
CHAT_CHANNEL_LIST_PROOF = "forkmesh-chat-channels-v1"
CHAT_CHANNEL_ACCESS_PROOF = "forkmesh-chat-channel-access-v1"
CHAT_CHANNEL_HISTORY_PROOF = "forkmesh-chat-channel-history-v1"


async def _chat_channel_signed_session(env, request):
    # Resolve the account behind a key-signed chat-channel read. Reads only: a
    # signature never creates, joins, or moderates a channel. The account must
    # still be an active user, and every channel-scoped authorization
    # (membership/visibility/admin) is applied by the API exactly as it is for
    # a session-token caller.
    if method_name(request) != "GET":
        return "", None
    url = urlparse(request.url)
    params = parse_qs(url.query)
    node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    ts = clean_string(params.get("ts", [""])[0], 20)
    sig = clean_string(params.get("sig", [""])[0], 200)
    if not node or not sig or not _ts_ok(ts):
        return "", None
    access = CHAT_CHANNEL_ROOM_ACCESS_RE.match(url.path)
    history = CHAT_CHANNEL_HISTORY_RE.match(url.path)
    if access or history:
        canonical = (
            (CHAT_CHANNEL_ACCESS_PROOF if access else CHAT_CHANNEL_HISTORY_PROOF)
            + "\n" + node + "\n" + (access or history).group(1) + "\n" + str(ts)
        ).encode()
    elif CHAT_CHANNELS_RE.match(url.path):
        canonical = (
            CHAT_CHANNEL_LIST_PROOF + "\n" + node + "\n" + str(ts)
        ).encode()
    else:
        return "", None
    pubkey = await _owner_pubkey(env, node)
    if not pubkey or not await ed25519_verify(pubkey, sig, canonical):
        return "", None
    account_bi, record = await _account_row(env, node)
    if (
        not account_bi
        or not record
        or record.get("status") != "active"
        or _account_kind(record) != "user"
    ):
        return "", None
    return account_bi, record


async def _room_key_authorized(env, request):
    # Compatibility wrapper retained for isolated callers/tests. Authorization
    # for the endpoint itself is repository-scoped in chat_room_key_handler.
    return bool(await _room_key_requester(
        env, request, "mainnode", "forkmesh"))


async def chat_room_key_handler(env, request):
    # Serve the isolated public World #general passphrase to any visitor, or a
    # repository-scoped room passphrase to an authenticated participant.
    # Missing and unauthorized private repositories share one 404 response, and
    # the private catalog record is not decrypted until its blind-index ACL gate
    # has passed.
    await ensure_schema(env)
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    params = parse_qs(urlparse(request.url).query)
    owner = safe_segment(params.get("owner", ["mainnode"])[0])
    repo = safe_segment(params.get("repo", ["forkmesh"])[0])
    room = safe_segment(params.get("room", ["general"])[0], MAX_ROOM_NAME)
    if not owner or not repo or not room:
        return _private_replica_not_found()
    public_world_general = (
        owner.lower() == "mainnode"
        and repo.lower() == "forkmesh"
        and room.lower() == PUBLIC_WORLD_GENERAL_ROOM
    )
    if not public_world_general:
        requester = await _room_key_requester(env, request, owner, repo)
        if not requester:
            return json_response({"error": "unauthorized"}, status=401)
        context = await _repository_access_context(
            env, request, owner, repo, viewer=requester)
        if context is None:
            return _private_replica_not_found()
    return json_response(
        {
            "ok": True,
            "scope": owner.lower() + "/" + repo.lower(),
            "room": room.lower(),
            "access": (
                "public-world-general"
                if public_world_general
                else "authenticated-repository"
            ),
            "passphrase": await _room_chat_passphrase(
                env, owner, repo, room),
        },
        cache_control="no-store, max-age=0, must-revalidate",
    )


CHAT_ACTIVITY_CACHE_KEY = "https://forkmesh.internal/api/chat/activity"
CHAT_ACTIVITY_TTL = 30


async def chat_activity_handler(env, request):
    # Lightweight public digest behind the site-wide header chat badge: how many
    # retained #general messages exist and how many user accounts are registered.
    # Counts only — chat_history bodies stay encrypted and user rows are never
    # decrypted (email_bi is only set on email-bearing user accounts, so it
    # separates users from keyless node reservations without touching `data`).
    # Edge-cached so every page load across the site collapses to one D1 read
    # pair per colo per TTL.
    del request
    cached = await edge_cache_match(CHAT_ACTIVITY_CACHE_KEY)
    if cached is not None:
        return cached
    await ensure_schema(env)
    msg_row = await d1_first(
        env,
        "SELECT COUNT(*) AS c, MAX(ts) AS latest FROM chat_history "
        "WHERE room_key=?",
        FLAGSHIP_ROOM_KEY,
    )
    user_row = await d1_first(
        env,
        "SELECT COUNT(*) AS c FROM users "
        "WHERE email_bi IS NOT NULL AND email_bi <> ''",
    )
    resp = json_response(
        {
            "ok": True,
            "messageCount": int((msg_row or {}).get("c") or 0),
            "latestMessageTs": int((msg_row or {}).get("latest") or 0),
            "userCount": int((user_row or {}).get("c") or 0),
        },
        cache_seconds=CHAT_ACTIVITY_TTL,
    )
    await edge_cache_put(CHAT_ACTIVITY_CACHE_KEY, resp)
    return resp


async def blind_index(env, value):
    # Deterministic, searchable HMAC of a normalized identifier (never plaintext).
    key = await _hmac_key(env)
    norm = (value or "").strip().lower().encode()
    sig = await js_crypto.subtle.sign("HMAC", key, _to_js(norm))
    return bytes(Uint8Array.new(sig).to_py()).hex()


# --- Password (PBKDF2-SHA256) -----------------------------------------------

async def hash_password(password):
    salt = js_crypto.getRandomValues(Uint8Array.new(16))
    base_key = await js_crypto.subtle.importKey(
        "raw", _to_js(password.encode()), to_js({"name": "PBKDF2"}), False,
        _to_js(["deriveBits"])
    )
    bits = await js_crypto.subtle.deriveBits(
        to_js({"name": "PBKDF2", "salt": salt, "iterations": PBKDF2_ITERS,
               "hash": "SHA-256"}),
        base_key, 256
    )
    return (base64.b64encode(bytes(salt.to_py())).decode(),
            base64.b64encode(bytes(Uint8Array.new(bits).to_py())).decode())


async def verify_password(password, salt_b64, hash_b64):
    try:
        salt = base64.b64decode(salt_b64)
        expected = base64.b64decode(hash_b64)
        base_key = await js_crypto.subtle.importKey(
            "raw", _to_js(password.encode()), to_js({"name": "PBKDF2"}), False,
            _to_js(["deriveBits"])
        )
        bits = await js_crypto.subtle.deriveBits(
            to_js({"name": "PBKDF2", "salt": _to_js(salt),
                   "iterations": PBKDF2_ITERS, "hash": "SHA-256"}),
            base_key, 256
        )
        got = bytes(Uint8Array.new(bits).to_py())
        return hmac.compare_digest(got, expected)
    except Exception:
        return False


# --- TOTP (RFC 6238, HMAC-SHA1, 6 digits, 30s) ------------------------------

def _b32_decode(secret):
    s = (secret or "").strip().upper().replace(" ", "")
    return base64.b32decode(s + "=" * ((8 - len(s) % 8) % 8))


def gen_totp_secret():
    raw = bytes(js_crypto.getRandomValues(Uint8Array.new(20)).to_py())
    return base64.b32encode(raw).decode().rstrip("=")


async def _totp_at(secret_b32, counter):
    key = await js_crypto.subtle.importKey(
        "raw", _to_js(_b32_decode(secret_b32)),
        to_js({"name": "HMAC", "hash": "SHA-1"}), False, _to_js(["sign"])
    )
    msg = struct.pack(">Q", counter)
    mac = bytes(Uint8Array.new(await js_crypto.subtle.sign(
        "HMAC", key, _to_js(msg))).to_py())
    offset = mac[-1] & 0x0F
    code = ((mac[offset] & 0x7F) << 24 | (mac[offset + 1] & 0xFF) << 16 |
            (mac[offset + 2] & 0xFF) << 8 | (mac[offset + 3] & 0xFF)) % 1000000
    return "%06d" % code


async def totp_verify(secret_b32, code):
    code = (code or "").strip()
    if not code.isdigit() or len(code) != 6:
        return False
    counter = int(Date.now()) // 1000 // 30
    for delta in (-1, 0, 1):  # allow one step of clock skew either way
        if hmac.compare_digest(await _totp_at(secret_b32, counter + delta), code):
            return True
    return False


# --- Catalog (repositories table) -------------------------------------------

async def _contribution_owner_user_bi(env, account_bi, account_rec):
    """Resolve a publishing user, linked node owner, or unlinked node fallback."""
    account_rec = account_rec or {}
    kind = clean_string(account_rec.get("kind", ""), 16).lower()
    if kind == "user" or (kind != "node" and account_rec.get("pass_hash")):
        return account_bi
    row = await d1_first(
        env, "SELECT user_bi FROM nodes WHERE node_bi=?", account_bi)
    return (row or {}).get("user_bi") or account_bi


async def _contribution_retarget_linked_nodes(
        env, old_user_bi, old_user_name, new_user_bi, new_user_name):
    """Persist a renamed or removed user link in every owned node record."""
    old_user_name = clean_string(old_user_name, MAX_NODE_NAME).lower()
    new_user_name = clean_string(new_user_name, MAX_NODE_NAME).lower()
    if not old_user_bi or not old_user_name:
        return
    rows = await d1_all(
        env,
        "SELECT node_bi, name, data FROM nodes WHERE user_bi=? AND node_bi!=?",
        old_user_bi, old_user_bi,
    )
    for row in rows:
        mirrored_rec = await decrypt_row(env, row.get("data", "")) or {}
        node_name = clean_string(
            row.get("name") or mirrored_rec.get("name", ""),
            MAX_NODE_NAME,
        ).lower()
        if not node_name:
            continue
        node_bi = row.get("node_bi")
        authoritative_bi, authoritative_rec = await _account_row(
            env, node_name)
        node_rec = dict(authoritative_rec or mirrored_rec)
        kind = clean_string(node_rec.get("kind", ""), 16).lower()
        if kind == "user" or (kind != "node" and node_rec.get("pass_hash")):
            continue
        if not node_bi:
            node_bi = authoritative_bi
        if not node_bi:
            continue
        if new_user_bi and new_user_name:
            node_rec["owner"] = new_user_name
        else:
            node_rec.pop("owner", None)
        await _save_account(env, node_bi, node_rec)


async def _contribution_actor_user_bis(env, actor_keys):
    """Resolve registered primary, node, and active device keys to users."""
    keys = sorted({key for key in actor_keys if isinstance(key, str) and key})
    if not keys:
        return {}
    rows = await d1_all(
        env,
        """WITH requested(pubkey) AS (
               SELECT CAST(value AS TEXT) FROM json_each(?)
             ), candidates(pubkey, user_bi) AS (
               SELECT requested.pubkey,
                      COALESCE(NULLIF(nodes.user_bi, ''), nodes.node_bi)
                 FROM requested
                 JOIN nodes ON nodes.pubkey=requested.pubkey
               UNION ALL
               SELECT requested.pubkey,
                      COALESCE(NULLIF(owner_node.user_bi, ''),
                               account_devices.account_bi)
                 FROM requested
                 JOIN account_devices
                   ON account_devices.pubkey=requested.pubkey
                 LEFT JOIN nodes AS owner_node
                   ON owner_node.node_bi=account_devices.account_bi
                WHERE account_devices.enabled=1
                  AND account_devices.revoked_at=0
                  AND instr(',' || account_devices.capabilities || ',',
                            ',contribution_key_proof,') > 0
             ), unambiguous AS (
               SELECT pubkey, MIN(user_bi) AS user_bi
                 FROM candidates
                WHERE user_bi IS NOT NULL AND user_bi != ''
                GROUP BY pubkey
               HAVING COUNT(DISTINCT user_bi)=1
             )
             SELECT pubkey, user_bi FROM unambiguous""",
        json.dumps(keys, separators=(",", ":")),
    )
    return {
        row["pubkey"]: row["user_bi"]
        for row in rows
        if row.get("pubkey") and row.get("user_bi")
    }


async def _contribution_project_bi(env, record):
    identity = record.get("rootCommit") or (
        record.get("owner", "") + "/" + record.get("name", "")
    )
    return await blind_index(env, "profile-project:" + identity.lower())


def _contribution_publication_day():
    value = time.gmtime(int(Date.now()) // 1000)
    return "%04d-%02d-%02d" % (value.tm_year, value.tm_mon, value.tm_mday)


async def _contribution_run_batch(env, statements):
    """Execute one ordered D1 batch, with a small test-runtime fallback."""
    database = getattr(env, "DB", None)
    batch = getattr(database, "batch", None) if database is not None else None
    if batch is not None:
        prepared = []
        for sql, args in statements:
            statement = database.prepare(sql)
            if args:
                statement = statement.bind(*args)
            prepared.append(statement)
        await batch(prepared)
        return
    for sql, args in statements:
        await d1_run(env, sql, *args)


async def _contribution_write_catalog_state(
        env, record, account_bi, account_rec, source_repo_bi,
        encrypted_catalog_record):
    """Atomically write repository visibility and its contribution boundary."""
    is_private = 1 if record.get("visibility") == "private" else 0
    statements = [(
        """INSERT INTO repositories (key_bi, owner_bi, data, is_private)
             VALUES (?,?,?,?)
             ON CONFLICT(key_bi) DO UPDATE SET
               owner_bi=excluded.owner_bi, data=excluded.data,
               is_private=excluded.is_private""",
        (source_repo_bi, account_bi, encrypted_catalog_record, is_private),
    )]
    if is_private:
        statements.append((
            "UPDATE profile_contribution_projects SET is_public=0 "
            "WHERE source_repo_bi=?",
            (source_repo_bi,),
        ))
    else:
        owner_user_bi = await _contribution_owner_user_bi(
            env, account_bi, account_rec)
        project_bi = await _contribution_project_bi(env, record)
        encrypted_labels = await encrypt_row(env, {
            "owner": record.get("owner", ""),
            "name": record.get("name", ""),
        })
        statements.append((
            """INSERT INTO profile_contribution_projects
                 (source_repo_bi, source_account_bi, owner_user_bi, project_bi,
                  first_public_day, is_public, active_generation_bi,
                  captured_at, verified_from, data)
                 VALUES (?,?,?,?,?,1,NULL,0,NULL,?)
                 ON CONFLICT(source_repo_bi) DO UPDATE SET
                   is_public=1,
                   source_account_bi=CASE
                     WHEN profile_contribution_projects.active_generation_bi IS NULL
                     THEN excluded.source_account_bi
                     ELSE profile_contribution_projects.source_account_bi END,
                   owner_user_bi=CASE
                     WHEN profile_contribution_projects.active_generation_bi IS NULL
                     THEN excluded.owner_user_bi
                     ELSE profile_contribution_projects.owner_user_bi END,
                   project_bi=CASE
                     WHEN profile_contribution_projects.active_generation_bi IS NULL
                     THEN excluded.project_bi
                     ELSE profile_contribution_projects.project_bi END,
                   data=CASE
                     WHEN profile_contribution_projects.active_generation_bi IS NULL
                     THEN excluded.data
                     ELSE profile_contribution_projects.data END""",
            (
                source_repo_bi,
                account_bi,
                owner_user_bi,
                project_bi,
                _contribution_publication_day(),
                encrypted_labels,
            ),
        ))
    await _contribution_run_batch(env, statements)
    if is_private:
        # A repository that becomes private must not retain even an encrypted
        # automatic-publication queue. Keep the compatibility guard for the
        # isolated contribution test harness, which loads this helper alone.
        purge_digests = globals().get("_ap_purge_repo_digest_queues")
        if callable(purge_digests):
            await purge_digests(
                env, record.get("owner", ""), record.get("name", ""))


async def _contribution_move_repo_namespace(
        env, old_repo_bi, new_repo_bi, old_account_bi, new_account_bi,
        new_owner, repo, record):
    project = await d1_first(
        env,
        "SELECT owner_user_bi, data FROM profile_contribution_projects "
        "WHERE source_repo_bi=?",
        old_repo_bi,
    )
    next_record = dict(record)
    next_record["owner"] = new_owner
    next_record["name"] = repo
    new_project_bi = await _contribution_project_bi(env, next_record)
    project_data = await decrypt_row(env, (project or {}).get("data")) or {}
    project_data["owner"] = new_owner
    project_data["name"] = repo
    encrypted_project = await encrypt_row(env, project_data)

    await d1_run(
        env,
        "UPDATE profile_contribution_receipts SET source_account_bi=?, "
        "source_repo_bi=? WHERE source_repo_bi=?",
        new_account_bi, new_repo_bi, old_repo_bi,
    )
    await d1_run(
        env,
        "UPDATE profile_contribution_days SET source_account_bi=?, "
        "source_repo_bi=?, project_bi=?, data=? WHERE source_repo_bi=?",
        new_account_bi, new_repo_bi, new_project_bi, encrypted_project,
        old_repo_bi,
    )
    await d1_run(
        env,
        "UPDATE profile_contribution_languages SET source_repo_bi=?, "
        "project_bi=?, owner_user_bi=CASE WHEN owner_user_bi=? THEN ? "
        "ELSE owner_user_bi END WHERE source_repo_bi=?",
        new_repo_bi, new_project_bi, old_account_bi, new_account_bi,
        old_repo_bi,
    )
    await d1_run(
        env,
        "UPDATE profile_contribution_projects SET source_repo_bi=?, "
        "source_account_bi=?, project_bi=?, "
        "owner_user_bi=CASE WHEN owner_user_bi=? THEN ? ELSE owner_user_bi END, "
        "data=? WHERE source_repo_bi=?",
        new_repo_bi, new_account_bi, new_project_bi,
        old_account_bi, new_account_bi, encrypted_project, old_repo_bi,
    )


def _contribution_generation_statements(
        generation_bi, snapshot_hash, snapshot, account_bi, owner_user_bi,
        source_repo_bi, project_bi, encrypted_labels, encrypted_project,
        day_rows, language_rows, created_at):
    return [
        (
            """INSERT OR IGNORE INTO profile_contribution_days
                 (generation_bi, subject_user_bi, source_account_bi,
                  source_repo_bi, project_bi, day, commits, issues, pulls,
                  reviews, captured_at, data)
                 SELECT ?, CAST(json_extract(value, '$[0]') AS TEXT), ?, ?, ?,
                        CAST(json_extract(value, '$[1]') AS TEXT),
                        CAST(json_extract(value, '$[2]') AS INTEGER),
                        CAST(json_extract(value, '$[3]') AS INTEGER),
                        CAST(json_extract(value, '$[4]') AS INTEGER),
                        CAST(json_extract(value, '$[5]') AS INTEGER), ?, ?
                   FROM json_each(?)""",
            (
                generation_bi, account_bi, source_repo_bi, project_bi,
                snapshot["capturedAt"], encrypted_labels,
                json.dumps(day_rows, separators=(",", ":")),
            ),
        ),
        (
            """INSERT OR IGNORE INTO profile_contribution_languages
                 (generation_bi, owner_user_bi, source_repo_bi, project_bi,
                  language, bytes, files, captured_at)
                 SELECT ?, ?, ?, ?,
                        CAST(json_extract(value, '$[0]') AS TEXT),
                        CAST(json_extract(value, '$[1]') AS INTEGER),
                        CAST(json_extract(value, '$[2]') AS INTEGER), ?
                   FROM json_each(?)""",
            (
                generation_bi, owner_user_bi, source_repo_bi, project_bi,
                snapshot["capturedAt"],
                json.dumps(language_rows, separators=(",", ":")),
            ),
        ),
        (
            """INSERT OR IGNORE INTO profile_contribution_receipts
                 (generation_bi, snapshot_hash, source_account_bi,
                  source_repo_bi, captured_at, head, day_rows, language_rows,
                  created_at) VALUES (?,?,?,?,?,?,?,?,?)""",
            (
                generation_bi, snapshot_hash, account_bi, source_repo_bi,
                snapshot["capturedAt"], snapshot["head"], len(day_rows),
                len(language_rows), created_at,
            ),
        ),
        (
            """UPDATE profile_contribution_projects
                  SET source_account_bi=?, owner_user_bi=?, project_bi=?,
                      active_generation_bi=?, captured_at=?, verified_from=?,
                      data=?
                WHERE source_repo_bi=? AND is_public=1
                  AND (active_generation_bi IS NULL OR captured_at < ?)
                  AND EXISTS (
                    SELECT 1 FROM repositories
                     WHERE key_bi=? AND is_private=0)""",
            (
                account_bi, owner_user_bi, project_bi, generation_bi,
                snapshot["capturedAt"], snapshot["from"], encrypted_project,
                source_repo_bi, snapshot["capturedAt"], source_repo_bi,
            ),
        ),
    ]


async def _contribution_prune_inactive_generations(env, source_repo_bi):
    statements = []
    for table in (
            "profile_contribution_days", "profile_contribution_languages",
            "profile_contribution_receipts"):
        statements.append((
            "DELETE FROM " + table + " WHERE source_repo_bi=? "
            "AND generation_bi NOT IN ("
            "SELECT active_generation_bi FROM profile_contribution_projects "
            "WHERE source_repo_bi=? AND active_generation_bi IS NOT NULL)",
            (source_repo_bi, source_repo_bi),
        ))
    await _contribution_run_batch(env, statements)


async def _contribution_ingest_snapshot(
        env, request_data, record, account_bi, account_rec, source_repo_bi):
    """Verify, stage, and compare-and-swap one optional public snapshot."""
    if record.get("visibility") != "public":
        return {"accepted": False, "warning": ""}
    transport = safe_contribution_transport(request_data)
    if not transport["present"]:
        return {"accepted": False, "warning": ""}
    if transport["warning"]:
        return {"accepted": False, "warning": transport["warning"]}
    try:
        snapshot, _raw, snapshot_hash = contributions.decode_snapshot_payload(
            transport["payload"], now_ms=int(Date.now()))
    except ValueError:
        return {"accepted": False, "warning": "invalid_contribution_payload"}
    if snapshot["head"] != record.get("commit"):
        return {"accepted": False, "warning": "contribution_head_mismatch"}
    if snapshot["branch"] != record.get("branch"):
        return {"accepted": False, "warning": "contribution_branch_mismatch"}
    if str(snapshot["capturedAt"]) != record.get("updatedAt"):
        return {"accepted": False, "warning": "contribution_time_mismatch"}

    # Fast path for a re-attestation republish: it re-sends the SAME snapshot, so
    # its content hash -> generation_bi is unchanged. If that generation is
    # already the active one for this repo, the ingest is a pure no-op (the
    # staging batch below is all INSERT OR IGNORE plus a captured_at<? UPDATE that
    # can't advance for an equal capturedAt). Skip the expensive signature verify,
    # actor lookups, staging batch, and prune entirely — re-running the full
    # ingest on every drifted-pin re-attest was a major driver of the Worker CPU
    # (Cloudflare 1102) overload the desktop then hammered with retries.
    generation_bi = await blind_index(
        env, "profile-generation:" + source_repo_bi + ":" + snapshot_hash)
    active_row = await d1_first(
        env,
        "SELECT active_generation_bi FROM profile_contribution_projects "
        "WHERE source_repo_bi=?",
        source_repo_bi,
    )
    if active_row and active_row.get("active_generation_bi") == generation_bi:
        return {"accepted": True, "warning": ""}

    try:
        canonical = contributions.snapshot_signature_canonical(
            record["owner"], record["name"], record["updatedAt"],
            snapshot_hash)
    except (KeyError, ValueError):
        return {"accepted": False, "warning": "invalid_contribution_payload"}
    owner_pubkey = clean_string((account_rec or {}).get("pubkey", ""), 120)
    if not owner_pubkey or not await ed25519_verify(
            owner_pubkey, transport["signature"], canonical):
        return {"accepted": False, "warning": "invalid_contribution_signature"}

    owner_user_bi = await _contribution_owner_user_bi(
        env, account_bi, account_rec)
    project_bi = await _contribution_project_bi(env, record)
    actor_users = await _contribution_actor_user_bis(
        env, [row[1] for row in snapshot["days"]])
    grouped_days = {}
    for day, actor_key, commits, issues, pulls, reviews in snapshot["days"]:
        subject_user_bi = actor_users.get(actor_key)
        if not subject_user_bi:
            continue
        counts = grouped_days.setdefault((subject_user_bi, day), [0, 0, 0, 0])
        counts[0] += commits
        counts[1] += issues
        counts[2] += pulls
        counts[3] += reviews
    day_rows = [
        [subject_user_bi, day, *counts]
        for (subject_user_bi, day), counts in sorted(grouped_days.items())
        if any(counts)
    ]

    grouped_languages = {}
    for extension, byte_count, file_count in snapshot["extensions"]:
        language, _color = contributions.language_for_extension(extension)
        totals = grouped_languages.setdefault(language, [0, 0])
        totals[0] += byte_count
        totals[1] += file_count
    language_rows = [
        [language, totals[0], totals[1]]
        for language, totals in sorted(grouped_languages.items())
        if totals[0] or totals[1]
    ]
    labels = {"owner": record["owner"], "name": record["name"]}
    encrypted_labels = await encrypt_row(env, labels)
    project_data = {**labels, "coverage": snapshot["coverage"]}
    encrypted_project = await encrypt_row(env, project_data)
    statements = _contribution_generation_statements(
        generation_bi, snapshot_hash, snapshot, account_bi, owner_user_bi,
        source_repo_bi, project_bi, encrypted_labels, encrypted_project,
        day_rows, language_rows, int(Date.now()))
    await _contribution_run_batch(env, statements)

    active = await d1_first(
        env,
        """SELECT projects.active_generation_bi, projects.captured_at,
                  projects.is_public,
                  receipts.snapshot_hash AS active_snapshot_hash,
                  CASE WHEN repositories.key_bi IS NOT NULL
                             AND repositories.is_private=0 THEN 1 ELSE 0 END
                    AS repository_public
             FROM profile_contribution_projects AS projects
             LEFT JOIN profile_contribution_receipts AS receipts
               ON receipts.generation_bi=projects.active_generation_bi
             LEFT JOIN repositories
               ON repositories.key_bi=projects.source_repo_bi
            WHERE projects.source_repo_bi=?""",
        source_repo_bi,
    ) or {}
    await _contribution_prune_inactive_generations(env, source_repo_bi)
    active_generation_bi = active.get("active_generation_bi")
    active_captured_at = int(active.get("captured_at") or 0)
    if active_generation_bi == generation_bi:
        return {"accepted": True, "warning": ""}
    if not active.get("is_public") or not active.get("repository_public"):
        return {
            "accepted": False,
            "warning": "contribution_repository_private",
        }
    if active_generation_bi and active_captured_at > snapshot["capturedAt"]:
        return {"accepted": False, "warning": "contribution_snapshot_older"}
    if active_generation_bi and active_captured_at == snapshot["capturedAt"]:
        return {"accepted": False, "warning": "contribution_snapshot_conflict"}
    return {"accepted": False, "warning": "contribution_activation_deferred"}


def _contribution_cache_key(profile_bi, from_value, to_value, revision=""):
    return (
        PROFILE_CONTRIBUTION_CACHE_PREFIX + quote(str(profile_bi), safe="")
        + "?from=" + from_value + "&to=" + to_value
        + (("&revision=" + revision) if revision else "")
    )


async def _contribution_profile_revision(
        env, subject_user_bi, from_value, to_value):
    """Hash every public source that can affect this profile and range."""
    rows = await d1_all(
        env,
        """WITH public_projects AS (
               SELECT projects.*
                 FROM profile_contribution_projects AS projects
                 JOIN repositories
                   ON repositories.key_bi=projects.source_repo_bi
                WHERE projects.is_public=1 AND repositories.is_private=0
             ), foreign_activity_projects AS (
               SELECT DISTINCT sources.project_bi
                 FROM public_projects AS sources
                 JOIN profile_contribution_days AS days
                   ON days.source_repo_bi=sources.source_repo_bi
                  AND days.generation_bi=sources.active_generation_bi
                WHERE sources.active_generation_bi IS NOT NULL
                  AND days.subject_user_bi=?
                  AND days.day>=? AND days.day<=?
             ), foreign_activity_sources AS (
               SELECT sources.*
                 FROM public_projects AS sources
                 JOIN foreign_activity_projects AS activity
                   ON activity.project_bi=sources.project_bi
                WHERE sources.owner_user_bi!=?
             ), revision_sources AS (
               SELECT 'owned' AS source_scope,
                      sources.source_repo_bi, sources.source_account_bi,
                      sources.owner_user_bi, sources.project_bi,
                      sources.first_public_day,
                      sources.active_generation_bi, sources.captured_at,
                      sources.verified_from
                 FROM public_projects AS sources
                WHERE sources.owner_user_bi=?
               UNION ALL
               SELECT 'foreign' AS source_scope,
                      sources.source_repo_bi, sources.source_account_bi,
                      sources.owner_user_bi, sources.project_bi,
                      sources.first_public_day,
                      sources.active_generation_bi, sources.captured_at,
                      sources.verified_from
                 FROM foreign_activity_sources AS sources
             )
             SELECT source_scope, source_repo_bi, source_account_bi,
                    owner_user_bi, project_bi, first_public_day,
                    COALESCE(active_generation_bi, '') AS active_generation_bi,
                    captured_at, COALESCE(verified_from, '') AS verified_from
               FROM revision_sources
              /* contribution_profile_revision */
              ORDER BY source_scope ASC, project_bi ASC, source_repo_bi ASC""",
        subject_user_bi, from_value, to_value,
        subject_user_bi, subject_user_bi,
    )
    canonical = [
        [
            row.get("source_scope") or "",
            row.get("source_repo_bi") or "",
            row.get("source_account_bi") or "",
            row.get("owner_user_bi") or "",
            row.get("project_bi") or "",
            row.get("first_public_day") or "",
            row.get("active_generation_bi") or "",
            int(row.get("captured_at") or 0),
            row.get("verified_from") or "",
        ]
        for row in rows
    ]
    return hashlib.sha256(json.dumps(
        canonical, separators=(",", ":")).encode()).hexdigest()


async def _contribution_internal_cache_get(cache_key):
    cached = await edge_cache_match(cache_key)
    if cached is None:
        return None
    try:
        payload = await cached.json()
    except Exception:
        return None
    return payload if isinstance(payload, dict) else None


async def _contribution_internal_cache_put(cache_key, payload):
    cached_response = json_response(
        payload, cache_seconds=PROFILE_CONTRIBUTION_CACHE_TTL)
    await edge_cache_put(cache_key, cached_response)


async def _contribution_activity_rows(
        env, subject_user_bi, from_value, to_value):
    return await d1_all(
        env,
        """WITH public_projects AS (
               SELECT projects.*
                 FROM profile_contribution_projects AS projects
                 JOIN repositories
                   ON repositories.key_bi=projects.source_repo_bi
                WHERE projects.is_public=1 AND repositories.is_private=0
             ), candidate_days AS (
               SELECT DISTINCT sources.project_bi, days.day
                 FROM public_projects AS sources
                 JOIN profile_contribution_days AS days
                   ON days.source_repo_bi=sources.source_repo_bi
                  AND days.generation_bi=sources.active_generation_bi
                WHERE sources.active_generation_bi IS NOT NULL
                  AND days.subject_user_bi=?
                  AND days.day>=? AND days.day<=?
             ), ranked_day_sources AS (
               SELECT candidates.project_bi, candidates.day,
                      sources.source_repo_bi,
                      sources.active_generation_bi,
                      ROW_NUMBER() OVER (
                        PARTITION BY candidates.project_bi, candidates.day
                        ORDER BY sources.captured_at DESC,
                                 sources.source_repo_bi ASC) AS source_rank
                 FROM candidate_days AS candidates
                 JOIN public_projects AS sources
                   ON sources.project_bi=candidates.project_bi
                  AND sources.active_generation_bi IS NOT NULL
                  AND sources.verified_from<=candidates.day
             ), active_day_sources AS (
               SELECT * FROM ranked_day_sources WHERE source_rank=1
             ), selected_days AS (
               SELECT sources.project_bi, days.day,
                      days.commits, days.issues,
                      days.pulls, days.reviews, days.source_repo_bi,
                      days.captured_at, days.data
                 FROM active_day_sources AS sources
                 JOIN profile_contribution_days AS days
                   ON days.source_repo_bi=sources.source_repo_bi
                  AND days.generation_bi=sources.active_generation_bi
                  AND days.day=sources.day
                WHERE days.subject_user_bi=?
             ), owned_ranked AS (
               SELECT sources.*,
                      MIN(sources.first_public_day) OVER (
                        PARTITION BY sources.project_bi
                      ) AS logical_first_public_day,
                      ROW_NUMBER() OVER (
                        PARTITION BY sources.project_bi
                        ORDER BY sources.captured_at DESC,
                                 sources.source_repo_bi ASC) AS source_rank
                 FROM public_projects AS sources
                WHERE sources.owner_user_bi=?
             ), owned_projects AS (
               SELECT * FROM owned_ranked WHERE source_rank=1
             ), activity_days AS (
               SELECT day,
                      SUM(commits) AS commits,
                      SUM(issues) AS issues,
                      SUM(pulls) AS pulls,
                      SUM(reviews) AS reviews,
                      0 AS repositories
                 FROM selected_days GROUP BY day
             ), repository_days AS (
               SELECT logical_first_public_day AS day,
                      0 AS commits, 0 AS issues, 0 AS pulls, 0 AS reviews,
                      COUNT(*) AS repositories
                 FROM owned_projects
                WHERE logical_first_public_day>=?
                  AND logical_first_public_day<=?
                GROUP BY logical_first_public_day
             ), combined_days AS (
               SELECT day, SUM(commits) AS commits, SUM(issues) AS issues,
                      SUM(pulls) AS pulls, SUM(reviews) AS reviews,
                      SUM(repositories) AS repositories
                 FROM (
                   SELECT * FROM activity_days
                   UNION ALL
                   SELECT * FROM repository_days
                 ) GROUP BY day
             )
             SELECT 0 AS row_order, 'summary' AS row_kind, '' AS day,
                    COALESCE(SUM(commits), 0) AS commits,
                    COALESCE(SUM(issues), 0) AS issues,
                    COALESCE(SUM(pulls), 0) AS pulls,
                    COALESCE(SUM(reviews), 0) AS reviews,
                    COALESCE(SUM(repositories), 0) AS repositories,
                    (SELECT COUNT(*) FROM owned_projects)
                      AS repository_count
               FROM combined_days
             UNION ALL
             SELECT 1 AS row_order, 'day' AS row_kind, day,
                    commits, issues, pulls, reviews, repositories,
                    0 AS repository_count
               FROM combined_days
             ORDER BY row_order ASC, day ASC""",
        subject_user_bi, from_value, to_value, subject_user_bi,
        subject_user_bi,
        from_value, to_value,
    )


async def _contribution_recent_rows(
        env, subject_user_bi, from_value, to_value):
    return await d1_all(
        env,
        """WITH public_projects AS (
               SELECT projects.*
                 FROM profile_contribution_projects AS projects
                 JOIN repositories
                   ON repositories.key_bi=projects.source_repo_bi
                WHERE projects.is_public=1 AND repositories.is_private=0
             ), candidate_days AS (
               SELECT DISTINCT sources.project_bi, days.day
                 FROM public_projects AS sources
                 JOIN profile_contribution_days AS days
                   ON days.source_repo_bi=sources.source_repo_bi
                  AND days.generation_bi=sources.active_generation_bi
                WHERE sources.active_generation_bi IS NOT NULL
                  AND days.subject_user_bi=?
                  AND days.day>=? AND days.day<=?
             ), ranked_day_sources AS (
               SELECT candidates.project_bi, candidates.day,
                      sources.source_repo_bi,
                      sources.active_generation_bi,
                      ROW_NUMBER() OVER (
                        PARTITION BY candidates.project_bi, candidates.day
                        ORDER BY sources.captured_at DESC,
                                 sources.source_repo_bi ASC) AS source_rank
                 FROM candidate_days AS candidates
                 JOIN public_projects AS sources
                   ON sources.project_bi=candidates.project_bi
                  AND sources.active_generation_bi IS NOT NULL
                  AND sources.verified_from<=candidates.day
             ), active_day_sources AS (
               SELECT * FROM ranked_day_sources WHERE source_rank=1
             ), selected_days AS (
               SELECT days.*
                 FROM active_day_sources AS sources
                 JOIN profile_contribution_days AS days
                   ON days.source_repo_bi=sources.source_repo_bi
                  AND days.generation_bi=sources.active_generation_bi
                  AND days.day=sources.day
                WHERE days.subject_user_bi=?
             ), owned_ranked AS (
               SELECT sources.*,
                      MIN(sources.first_public_day) OVER (
                        PARTITION BY sources.project_bi
                      ) AS logical_first_public_day,
                      ROW_NUMBER() OVER (
                        PARTITION BY sources.project_bi
                        ORDER BY sources.captured_at DESC,
                                 sources.source_repo_bi ASC) AS source_rank
                 FROM public_projects AS sources
                WHERE sources.owner_user_bi=?
             ), owned_projects AS (
               SELECT * FROM owned_ranked WHERE source_rank=1
             ), recent_candidates AS (
               SELECT day AS activity_day, 'commits' AS kind,
                      0 AS kind_order, commits AS activity_count,
                      project_bi, source_repo_bi, data
                 FROM selected_days WHERE commits>0
               UNION ALL
               SELECT day, 'issues', 1, issues,
                      project_bi, source_repo_bi, data
                 FROM selected_days WHERE issues>0
               UNION ALL
               SELECT day, 'pulls', 2, pulls,
                      project_bi, source_repo_bi, data
                 FROM selected_days WHERE pulls>0
               UNION ALL
               SELECT day, 'reviews', 3, reviews,
                      project_bi, source_repo_bi, data
                 FROM selected_days WHERE reviews>0
               UNION ALL
               SELECT logical_first_public_day, 'repositories', 4, 1,
                      project_bi, source_repo_bi, data
                 FROM owned_projects
                WHERE logical_first_public_day>=?
                  AND logical_first_public_day<=?
             )
             SELECT activity_day, kind, activity_count, project_bi,
                    source_repo_bi, data
               FROM recent_candidates
              ORDER BY activity_day DESC, kind_order ASC,
                       project_bi ASC, source_repo_bi ASC
              LIMIT 20""",
        subject_user_bi, from_value, to_value, subject_user_bi,
        subject_user_bi,
        from_value, to_value,
    )


async def _contribution_language_rows(env, owner_user_bi):
    return await d1_all(
        env,
        """WITH ranked_sources AS (
               SELECT projects.source_repo_bi, projects.project_bi,
                      projects.active_generation_bi,
                      ROW_NUMBER() OVER (
                        PARTITION BY projects.project_bi
                        ORDER BY projects.captured_at DESC,
                                 projects.source_repo_bi ASC) AS source_rank
                 FROM profile_contribution_projects AS projects
                 JOIN repositories
                   ON repositories.key_bi=projects.source_repo_bi
                WHERE projects.owner_user_bi=? AND projects.is_public=1
                  AND repositories.is_private=0
                  AND projects.active_generation_bi IS NOT NULL
             ), selected_sources AS (
               SELECT * FROM ranked_sources WHERE source_rank=1
             )
             SELECT languages.language, SUM(languages.bytes) AS bytes
               FROM selected_sources AS sources
               JOIN profile_contribution_languages AS languages
                 ON languages.source_repo_bi=sources.source_repo_bi
                AND languages.generation_bi=sources.active_generation_bi
              WHERE languages.owner_user_bi=?
              GROUP BY languages.language
              ORDER BY languages.language ASC""",
        owner_user_bi, owner_user_bi,
    )


async def _contribution_coverage_rows(
        env, subject_user_bi, from_value, to_value):
    return await d1_all(
        env,
        """WITH public_projects AS (
               SELECT projects.*
                 FROM profile_contribution_projects AS projects
                 JOIN repositories
                   ON repositories.key_bi=projects.source_repo_bi
                WHERE projects.is_public=1 AND repositories.is_private=0
             ), candidate_days AS (
               SELECT DISTINCT sources.project_bi, days.day
                 FROM public_projects AS sources
                 JOIN profile_contribution_days AS days
                   ON days.source_repo_bi=sources.source_repo_bi
                  AND days.generation_bi=sources.active_generation_bi
                WHERE sources.active_generation_bi IS NOT NULL
                  AND days.subject_user_bi=?
                  AND days.day>=? AND days.day<=?
             ), ranked_day_sources AS (
               SELECT candidates.project_bi, candidates.day,
                      sources.source_repo_bi,
                      ROW_NUMBER() OVER (
                        PARTITION BY candidates.project_bi, candidates.day
                        ORDER BY sources.captured_at DESC,
                                 sources.source_repo_bi ASC) AS source_rank
                 FROM candidate_days AS candidates
                 JOIN public_projects AS sources
                   ON sources.project_bi=candidates.project_bi
                  AND sources.active_generation_bi IS NOT NULL
                  AND sources.verified_from<=candidates.day
             ), selected_day_sources AS (
               SELECT * FROM ranked_day_sources WHERE source_rank=1
             ), activity_sources AS (
               SELECT DISTINCT project_bi, source_repo_bi
                 FROM selected_day_sources
             ), owned_projects AS (
               SELECT DISTINCT project_bi
                 FROM public_projects
                WHERE owner_user_bi=?
             ), owned_ranked_sources AS (
               SELECT sources.*,
                      ROW_NUMBER() OVER (
                        PARTITION BY sources.project_bi
                        ORDER BY CASE
                           WHEN sources.active_generation_bi IS NOT NULL
                            AND sources.verified_from IS NOT NULL
                            AND sources.verified_from<=? THEN 0
                           WHEN sources.active_generation_bi IS NOT NULL
                             THEN 1
                           ELSE 2
                         END ASC,
                                 sources.captured_at DESC,
                                 sources.source_repo_bi ASC) AS source_rank
                 FROM public_projects AS sources
                 JOIN owned_projects
                   ON owned_projects.project_bi=sources.project_bi
             ), coverage_source_keys AS (
               SELECT source_repo_bi, project_bi
                 FROM owned_ranked_sources
                WHERE source_rank=1
               UNION
               SELECT source_repo_bi, project_bi FROM activity_sources
             )
             SELECT sources.source_repo_bi, sources.project_bi,
                    sources.owner_user_bi, sources.verified_from,
                    sources.captured_at, sources.data,
                    CASE WHEN owned.project_bi IS NOT NULL
                         THEN 1 ELSE 0 END AS is_owned
               FROM coverage_source_keys AS keys
               JOIN public_projects AS sources
                 ON sources.source_repo_bi=keys.source_repo_bi
               LEFT JOIN owned_projects AS owned
                 ON owned.project_bi=keys.project_bi
              ORDER BY sources.project_bi ASC, sources.source_repo_bi ASC
              LIMIT ?""",
        subject_user_bi, from_value, to_value, subject_user_bi,
        from_value, MAX_CATALOG_REPOS,
    )


async def _contribution_profile_payload(
        env, profile_bi, profile_name, from_value, to_value):
    activity_rows, recent_rows, language_rows, coverage_rows = (
        await asyncio.gather(
            _contribution_activity_rows(
                env, profile_bi, from_value, to_value),
            _contribution_recent_rows(
                env, profile_bi, from_value, to_value),
            _contribution_language_rows(env, profile_bi),
            _contribution_coverage_rows(
                env, profile_bi, from_value, to_value),
        )
    )
    summary = next(
        (row for row in activity_rows if row.get("row_kind") == "summary"),
        {},
    )
    days = [
        row for row in activity_rows if row.get("row_kind") == "day"
    ]

    decrypted = {}
    recent_activity = []
    for row in recent_rows[:20]:
        encrypted = row.get("data", "")
        if encrypted not in decrypted:
            decrypted[encrypted] = await decrypt_row(env, encrypted) or {}
        labels = decrypted[encrypted]
        owner = clean_string(labels.get("owner", ""), MAX_NODE_NAME).lower()
        repo = clean_string(labels.get("name", ""), MAX_REPO_SEGMENT)
        if not owner or not repo:
            continue
        recent_activity.append({
            "date": row.get("activity_day", ""),
            "kind": row.get("kind", ""),
            "count": int(row.get("activity_count") or 0),
            "repository": {
                "owner": owner,
                "name": repo,
                "url": "/" + quote(owner, safe="") + "/"
                       + quote(repo, safe=""),
            },
        })

    decoded_coverage = []
    for row in coverage_rows:
        encrypted = row.get("data", "")
        if encrypted not in decrypted:
            decrypted[encrypted] = await decrypt_row(env, encrypted) or {}
        decoded_coverage.append({
            **row,
            "coverage": decrypted[encrypted].get("coverage"),
        })
    return contributions.build_profile_contribution_response(
        profile_name, from_value, to_value, summary, days,
        language_rows, recent_activity, decoded_coverage,
    )


async def _contribution_profile_api(env, request, raw_name):
    parsed = urlparse(request.url)
    params = parse_qs(parsed.query, keep_blank_values=True)
    if (set(params) - {"from", "to"}
            or any(len(values) != 1 for values in params.values())):
        return json_response(
            {"error": "invalid_contribution_range"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")
    scalar_query = {key: values[0] for key, values in params.items()}
    try:
        from_value, to_value = contributions.contribution_date_range(
            scalar_query, now_ms=int(Date.now()))
    except ValueError:
        return json_response(
            {"error": "invalid_contribution_range"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")

    name = clean_string(raw_name, MAX_NODE_NAME).lower()
    if not valid_node_name(name):
        return json_response(
            {"error": "not_found"}, status=404,
            cache_control="no-store, max-age=0, must-revalidate")
    profile_bi = await blind_index(env, name)
    rec = await _account_identity_rec_by_bi(env, profile_bi)
    if not rec:
        _, rec = await _account_row(env, name)
    if (not rec or rec.get("status") != "active"
            or rec.get("profile_private")):
        return json_response(
            {"error": "not_found"}, status=404,
            cache_control="no-store, max-age=0, must-revalidate")

    profile_name = clean_string(
        rec.get("name", name), MAX_NODE_NAME).lower() or name
    cacheable = contributions.contribution_cacheable_range(
        from_value, to_value, now_ms=int(Date.now()))
    for attempt in range(2):
        revision = await _contribution_profile_revision(
            env, profile_bi, from_value, to_value)
        cache_key = _contribution_cache_key(
            profile_bi, from_value, to_value, revision)
        if cacheable:
            cached = await _contribution_internal_cache_get(cache_key)
            if (cached and cached.get("ok") is True
                    and cached.get("profile") == profile_name
                    and cached.get("range") == {
                        "from": from_value, "to": to_value}):
                final_revision = await _contribution_profile_revision(
                    env, profile_bi, from_value, to_value)
                if final_revision == revision:
                    return json_response(
                        cached,
                        cache_control="no-store, max-age=0, must-revalidate")
                if attempt == 0:
                    continue
                break

        payload = await _contribution_profile_payload(
            env, profile_bi, profile_name, from_value, to_value)
        final_revision = await _contribution_profile_revision(
            env, profile_bi, from_value, to_value)
        if final_revision != revision:
            if attempt == 0:
                continue
            break
        if cacheable:
            await _contribution_internal_cache_put(cache_key, payload)
        return json_response(
            payload,
            cache_control="no-store, max-age=0, must-revalidate")
    return json_response(
        {"error": "contribution_state_changed"}, status=503,
        cache_control="no-store, max-age=0, must-revalidate")


async def catalog_rate_check(env, owner_bi):
    # Throttle catalog writes per owner: at most one write per cooldown window.
    # Returns a 429 response when throttled, else None (and records this write).
    now = int(Date.now())
    row = await d1_first(
        env, "SELECT ts FROM catalog_rate WHERE owner_bi=?", owner_bi)
    if row:
        try:
            last = int(row["ts"])
        except (TypeError, ValueError):
            last = 0
        if now - last < CATALOG_WRITE_COOLDOWN_MS:
            retry_ms = max(1000, CATALOG_WRITE_COOLDOWN_MS - (now - last))
            retry_seconds = max(1, (retry_ms + 999) // 1000)
            return json_response(
                {"error": "rate_limited", "retryAfterMs": retry_ms},
                status=429,
                extra_headers={"Retry-After": str(retry_seconds)},
            )
    await d1_run(
        env,
        "INSERT INTO catalog_rate (owner_bi, ts) VALUES (?,?) "
        "ON CONFLICT(owner_bi) DO UPDATE SET ts=excluded.ts",
        owner_bi, now,
    )
    return None


async def signup_rate_check(env, ip_bi):
    # Throttle account creation per source IP: at most SIGNUP_MAX_PER_IP within a
    # rolling SIGNUP_RATE_WINDOW_MS. Returns a 429 response when over the limit,
    # else None (and records this creation). A missing IP (local/dev, or a proxy
    # path with no CF header) is not throttled — we only rate-limit what we can
    # attribute — so genuine tests and self-hosting stay unaffected.
    if not ip_bi:
        return None
    now = int(Date.now())
    # One UPSERT owns reset+increment+readback. Parallel signup requests can no
    # longer all observe the same old count and overwrite one another.
    row = await d1_first(
        env,
        "INSERT INTO signup_rate (ip_bi,count,window_start_ts) VALUES (?,1,?) "
        "ON CONFLICT(ip_bi) DO UPDATE SET "
        "count=CASE WHEN ?-signup_rate.window_start_ts>=? "
        "THEN 1 ELSE signup_rate.count+1 END,"
        "window_start_ts=CASE WHEN ?-signup_rate.window_start_ts>=? "
        "THEN ? ELSE signup_rate.window_start_ts END "
        "RETURNING count,window_start_ts",
        ip_bi,
        now,
        now,
        SIGNUP_RATE_WINDOW_MS,
        now,
        SIGNUP_RATE_WINDOW_MS,
        now,
    )
    count = int((row or {}).get("count") or 1)
    window_start = int((row or {}).get("window_start_ts") or now)
    if count > SIGNUP_MAX_PER_IP:
        retry_ms = max(1000, SIGNUP_RATE_WINDOW_MS - (now - window_start))
        return json_response(
            {"error": "rate_limited", "retryAfterMs": retry_ms},
            status=429,
            extra_headers={"Retry-After": str(max(1, (retry_ms + 999) // 1000))},
        )
    return None


async def catalog_handler(env, request):
    await ensure_schema(env)
    method = method_name(request)
    if method == "GET":
        # A logged-in owner may sign a short-lived forkmesh-catalog-view-v1 token to
        # additionally receive their OWN private repos (anonymous callers, and the
        # static website with no key, still get the public-only list). The result is
        # per-viewer, so an authenticated request must never read from or write to
        # the SHARED public edge cache — that would leak private repos to everyone.
        params = parse_qs(urlparse(
            str(getattr(request, "url", "") or "")).query)
        admin_query = _admin_query(params.get("admin", [""])[0])
        headers = getattr(request, "headers", {}) or {}
        cache_control = (headers.get("cache-control") or "").lower()
        bypass_cache = bool(
            params.get("fresh") or params.get("_") or params.get("fmv") or
            "no-cache" in cache_control or "no-store" in cache_control)
        viewer = safe_segment(params.get("viewer", [""])[0])
        view_ts = clean_string(params.get("ts", [""])[0], 20)
        view_sig = clean_string(params.get("sig", [""])[0], 200)
        authed_viewer = ""
        if viewer and view_sig:
            authed_viewer = await verify_catalog_view_token(
                env, viewer, view_ts, view_sig)
        if not authed_viewer and not bypass_cache:
            cached = await edge_cache_match(CATALOG_CACHE_KEY)
            if cached is not None:
                return cached
        # Best-effort D1 housekeeping (drop blocked phantoms, prune stale nodes)
        # only on the cheap, edge-cached anonymous miss. The response is already
        # correct without it — blocked entries are skipped by
        # _is_blocked_catalog_identity — and the staggered cron sweeps D1 on its
        # own schedule. An
        # authenticated (per-viewer, never-cached) request must NOT run these:
        # replaying a burst of DELETEs plus host-offline notifications inline on
        # every catalog load held the single Worker event loop long enough for
        # the runtime to cancel the request as hung ("Cannot enter into task").
        # Housekeeping moved off the request path entirely (2026-07-11): the
        # staggered cron already runs purge_blocked_catalog (minute%15==9) and
        # purge_stale_registered_nodes (minute%15==4), and the response is
        # correct without them — blocked entries are skipped by
        # _is_blocked_catalog_identity, while stale signed catalog entries stay
        # visible with offline availability. Running purges on every 10s cache
        # miss helped melt the free plan during the 2026-07-11 overload.
        # Public repos are listed for everyone; an authenticated viewer additionally
        # gets the private repos they own (matched by blind index) AND any private
        # repo another owner has shared with them (issue #9, via the repo_shares
        # ACL). No other owner's un-shared private repos are ever returned.
        if authed_viewer:
            viewer_bi = await blind_index(env, authed_viewer)
            rows = await d1_all(
                env,
                "SELECT key_bi, owner_bi, data FROM repositories "
                "WHERE is_private = 0 OR owner_bi = ? OR key_bi IN "
                "(SELECT repo_bi FROM repo_shares WHERE grantee_bi = ?)",
                viewer_bi, viewer_bi)
        else:
            rows = await d1_all(
                env,
                "SELECT key_bi, owner_bi, data FROM repositories "
                "WHERE is_private = 0")
        # Repository sockets and their host_presence heartbeat were retired when
        # repository bytes moved to signed direct-HTTPS mirrors. Derive catalog
        # availability from that same trust boundary: a fresh, non-blocked
        # endpoint whose account-bound Ed25519 challenge proved the flagship
        # refs and required operations. node_bi and repositories.owner_bi use
        # the same blind-index domain, so no plaintext node join or client probe
        # is needed here.
        cutoff = int(Date.now()) - HTTPS_MIRROR_STATUS_FRESH_MS
        live_rows = await d1_all(
            env,
            """SELECT node_bi FROM mirror_https_endpoints
                WHERE checked_at>=? AND forkmesh_verified_at>=?
                  AND healthy=1 AND forkmesh_active=1
                  AND integrity='ok' AND abuse_blocked=0""",
            cutoff, cutoff,
        )
        live_endpoint_nodes = {
            str(row.get("node_bi") or "")
            for row in live_rows or []
            if str(row.get("node_bi") or "")
        }
        terms_rows = await d1_all(
            env,
            "SELECT repo_bi,category FROM repo_terms_flags WHERE active=1",
        )
        terms_flags = {
            str(row.get("repo_bi") or ""): clean_string(
                row.get("category"), 20).lower()
            for row in terms_rows or []
            if str(row.get("repo_bi") or "")
        }
        repos = []
        ssh_gateway = _ssh_gateway_settings(env)
        for r in rows:
            rec = await decrypt_row(env, r["data"])
            if rec:
                owner_bi = r.get("owner_bi")
                visibility = rec.get("visibility")
                # Never trust the historical plaintext flag by itself:
                # migration 0011 defaulted pre-existing rows to public. Only a
                # signed record explicitly marked public is anonymous catalog
                # data. A private record selected through a stale flag still
                # requires an owner/share ACL recheck.
                if visibility not in ("public", "private"):
                    continue
                if not owner_bi:
                    rec_owner = clean_string(
                        rec.get("owner", ""), MAX_NODE_NAME).lower()
                    owner_bi = (
                        await blind_index(env, rec_owner)
                        if rec_owner else "")
                if visibility == "private":
                    if not authed_viewer:
                        continue
                    if str(owner_bi or "") != str(viewer_bi):
                        shared = await d1_first(
                            env,
                            "SELECT 1 AS one FROM repo_shares "
                            "WHERE repo_bi=? AND grantee_bi=?",
                            r.get("key_bi"), viewer_bi,
                        )
                        if not shared:
                            continue
                # Defense in depth: never surface a blocked identity even if a
                # row slipped in before the purge ran.
                if _is_blocked_catalog_identity(
                        env, rec.get("owner"), rec.get("name")):
                    continue
                rec["liveHost"] = (
                    str(owner_bi or "") in live_endpoint_nodes
                )
                # Plaintext flag so clients can badge private repos without
                # re-deriving it from the visibility string.
                rec["isPrivate"] = rec.get("visibility") == "private"
                # A private repo surfaced to a viewer who is NOT its owner can only
                # be here because it was shared with them (issue #9). The client
                # badges it and clones it with the grantee view token, not the
                # owner one.
                rec["sharedWithMe"] = bool(
                    authed_viewer and rec["isPrivate"]
                    and rec.get("owner") != authed_viewer)
                terms_category = terms_flags.get(str(r.get("key_bi") or ""))
                rec["termsFlagged"] = bool(terms_category)
                if terms_category:
                    rec["termsCategory"] = terms_category
                # Publish an SSH clone/push URL only when a separate gateway
                # host and its Worker authorization token are both configured.
                # The URL is never a claim that this HTTP Worker terminates SSH.
                if ssh_gateway["configured"]:
                    ssh_url = _ssh_repository_url(
                        env, rec.get("owner", ""), rec.get("name", ""))
                    if ssh_url:
                        rec["sshUrl"] = ssh_url
                # Only this ACL-authorized, no-store catalog response may reveal
                # the random client locator for an encrypted private archive.
                # Anonymous/public catalog rows never reach this branch for a
                # private repository, and the locator itself contains no owner
                # or repository name. It is still not a bearer credential:
                # archive reads independently require the owner/share signature.
                if rec["isPrivate"]:
                    access_id = await _https_mirror_private_catalog_access_id(
                        env, r["key_bi"], int(rec.get("keyEpoch") or 0))
                    if access_id:
                        rec["privateAccessId"] = access_id
                        rec["privateAccessPath"] = (
                            "/api/private-replicas/" + access_id)
                repos.append(rec)
        # Second pass: mark each repo cloneable when its own host is offline but a
        # peer mirroring the same logical repo is online — the relay serves that
        # mirror in place through the repo's own URL (adhoc #61), so the website
        # shows the repo as available (and which nodes are live) instead of a
        # bare "host offline". served_mirror_groups sees the whole public list, so
        # this works even when the freshest live node is a different owner's mirror.
        served = served_mirror_groups(repos)
        for rec in repos:
            rec["cloneOnline"] = repo_clone_online(rec, served)
        repos.sort(key=lambda x: x.get("updatedAt", ""), reverse=True)
        payload = {
            "ok": True,
            "repositories": repos[:MAX_CATALOG_REPOS],
            "sshGatewayConfigured": ssh_gateway["configured"],
            "sshTransport": (
                "node-side-forced-command"
                if ssh_gateway["configured"] else "not-configured"),
            "payoutCustody": "external-self-custodial-public-addresses",
            "payoutNotice": (
                "Repository records may include an operator's optional public "
                "payout address only. ForkMesh holds no wallet key or user "
                "funds, and publication does not guarantee a reward."
            ),
        }
        # Per-viewer responses (with private repos) must never touch the shared
        # public cache — and must say no-store themselves so no downstream cache
        # holds them either; only the public-only list is cacheable.
        if authed_viewer or bypass_cache:
            return json_response(
                payload,
                cache_control="no-store, max-age=0, must-revalidate")
        resp = json_response(payload, cache_seconds=CATALOG_TTL)
        await edge_cache_put(CATALOG_CACHE_KEY, resp)
        return resp

    if method == "POST":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        record = safe_catalog_record(data)
        if not record:
            return json_response(
                {"error": "owner_name_and_maintainer_required"}, status=400
            )
        owner = record["owner"]
        # Blocked phantom identities can never (re)enter the catalog.
        if _is_blocked_catalog_identity(env, owner, record["name"]):
            return json_response({"error": "blocked"}, status=403)
        # Repos are namespaced under a registered account, and only that account's
        # key holder may write its namespace. This ties repo identity to the
        # account (fixes duplicate forks) and prevents impersonation. A registered
        # account is REQUIRED — there is no self-asserted-maintainer fallback.
        # One account fetch serves both the pubkey check and the node touch
        # below (the old code fetched + decrypted the same record twice).
        _, publish_owner_rec = await _account_row(env, owner)
        primary_owner_pub = (publish_owner_rec.get("pubkey", "")
                             if publish_owner_rec else "")
        if not primary_owner_pub:
            return json_response({"error": "account_required"}, status=403)
        owner_pub = await _catalog_publication_key(
            env, owner, record["maintainer"])
        if not owner_pub:
            return json_response({"error": "maintainer_mismatch"}, status=403)
        catalog_sig = clean_string(data.get("catalogSig", ""), 200)
        try:
            catalog_sig_version = int(data.get("catalogSigVersion", 1) or 1)
        except (TypeError, ValueError):
            catalog_sig_version = 0
        if catalog_sig_version == 2:
            # V2 binds every normalized record field, including visibility and
            # the served-ref fingerprint. A relay or replay holder cannot turn
            # a private publication into a public one while reusing a signature.
            signed_record = dict(record)
            signed_record.pop("signature", None)
            record_hash = hashlib.sha256(json.dumps(
                signed_record, sort_keys=True,
                separators=(",", ":")).encode()).hexdigest()
            canonical = ("forkmesh-catalog-v2\n" + record_hash).encode()
        else:
            # Legacy signatures did not bind visibility. They remain accepted
            # only for explicitly public repositories; private publication must
            # upgrade before the relay stores any confidential metadata.
            if record["visibility"] != "public":
                return json_response(
                    {
                        "error": "client_upgrade_required",
                        "requiredCatalogSigVersion": 2,
                    },
                    status=426,
                )
            canonical = (
                "forkmesh-catalog-v1\n" + owner + "\n" + record["name"] +
                "\n" + record["updatedAt"]
            ).encode()
        if not await ed25519_verify(owner_pub, catalog_sig, canonical):
            return json_response({"error": "bad_signature"}, status=401)
        if record["visibility"] == "private":
            opaque_repo_id = record.get("opaqueRepoId", "")
            manifest_hash = record.get("encryptedManifestHash", "")
            manifest_sig = record.get("encryptedManifestSig", "")
            key_epoch = int(record.get("keyEpoch") or 0)
            if (record.get("mirrorEncryption") != "owner-sealed-v1"
                    or not re.fullmatch(r"[a-f0-9]{32}", opaque_repo_id)
                    or key_epoch < 1
                    or not re.fullmatch(r"[a-f0-9]{64}", manifest_hash)
                    or not manifest_sig):
                return json_response({
                    "error": "private_mirror_encryption_required",
                    "required": (
                        "owner-sealed-v1 encrypted archive, opaque repository "
                        "id, key epoch, and owner-signed manifest hash"
                    ),
                }, status=426)
            manifest_canonical = (
                "forkmesh-private-manifest-v1\n" + owner + "\n"
                + record["name"] + "\n" + opaque_repo_id + "\n"
                + str(key_epoch) + "\n" + manifest_hash + "\n"
                + record["updatedAt"]
            ).encode()
            if not await ed25519_verify(
                    owner_pub, manifest_sig, manifest_canonical):
                return json_response(
                    {"error": "bad_private_manifest_signature"}, status=401)
        owner_bi = await blind_index(env, owner)
        try:
            await touch_registered_node(env, owner_bi, publish_owner_rec)
        except Exception:
            pass

        # Repo-state attestation: the same owner key signs the fingerprint of the
        # refs it serves, so the relay can later reject a tampered/stale mirror.
        # Reject the whole write if a present attestation doesn't verify (a bad
        # one must never be pinned); absent is allowed for backward compatibility.
        state_hash = record.get("stateHash", "")
        state_sig = record.get("stateSig", "")
        if state_hash or state_sig:
            state_canonical = (
                "forkmesh-repostate-v1\n" + owner + "\n" + record["name"] +
                "\n" + state_hash + "\n" + record["updatedAt"]
            ).encode()
            if not (state_hash and state_sig and await ed25519_verify(
                    owner_pub, state_sig, state_canonical)):
                return json_response({"error": "bad_state_signature"}, status=401)

        # Anti-spam: throttle writes per owner and cap how many repos one owner may
        # publish, so a single key can't flood the catalog.
        limited = await catalog_rate_check(env, owner_bi)
        if limited is not None:
            return limited

        key_bi = await blind_index(env, owner + "/" + record["name"])
        # Per-owner record cap (an update to an existing repo is always allowed).
        prior_row = await d1_first(
            env, "SELECT data FROM repositories WHERE key_bi=?", key_bi)
        exists = prior_row is not None
        prior_commit = ""
        prior_state_hash = ""
        # Reject rollbacks: a replayed older record must not be able to repin an
        # earlier (validly-signed) repo state and downgrade the served refs.
        if exists:
            prior = await decrypt_row(env, prior_row["data"]) or {}
            prior_commit = clean_string(prior.get("commit", ""), 64)
            candidate_prior_state = clean_string(
                prior.get("stateHash", ""), 64).strip().lower()
            if (
                    (prior.get("source") or "local-node") == "local-node"
                    and re.fullmatch(
                        r"[0-9a-f]{64}", candidate_prior_state)):
                prior_state_hash = candidate_prior_state
            try:
                if int(record["updatedAt"]) < int(prior.get("updatedAt", 0) or 0):
                    return json_response({"error": "stale_update"}, status=409)
            except (TypeError, ValueError):
                pass
        if not exists:
            cnt = await d1_first(
                env, "SELECT COUNT(*) AS c FROM repositories WHERE owner_bi=?", owner_bi)
            if cnt and cnt.get("c", 0) >= CATALOG_MAX_RECORDS_PER_OWNER:
                return json_response({"error": "too_many_repos"}, status=429)
        enc = await encrypt_row(env, record)
        await _contribution_write_catalog_state(
            env, record, owner_bi, publish_owner_rec, key_bi, enc)
        contribution_result = {"accepted": False, "warning": ""}
        if record["visibility"] == "public":
            try:
                contribution_result = await _contribution_ingest_snapshot(
                    env,
                    data,
                    record,
                    owner_bi,
                    publish_owner_rec,
                    key_bi,
                )
            except Exception:
                # Optional snapshot failures do not roll back an authorized
                # repository publication.
                contribution_result = {
                    "accepted": False,
                    "warning": "contribution_ingestion_failed",
                }
        # A working-copy holder's verified attestation also lands in the pin
        # history, which is what lets an honest mirror lag the source by a few
        # publishes without failing the clone integrity gate (clone_state_pins).
        # Mirrors' ("remote-clone") self-attestations are deliberately NOT
        # recorded — they must match a source pin. Best-effort: a failure here
        # must never fail the publish itself.
        if state_hash and record.get("source") == "local-node":
            try:
                # Preserve the state being replaced explicitly. Older releases
                # wrote history best-effort after replacing the catalog row, so
                # an upgraded repository can otherwise lose its only
                # last-known-good handoff pin on the first new publication.
                # The previous record was already owner-signature-verified when
                # accepted; remote-clone self-pins never enter this path.
                history_states = [
                    digest for digest in (
                        prior_state_hash,
                        state_hash.strip().lower(),
                    )
                    if digest
                ]
                for digest in dict.fromkeys(history_states):
                    await d1_run(
                        env,
                        "INSERT INTO repo_state_history "
                        "(key_bi, state_hash, ts) VALUES (?,?,?) "
                        "ON CONFLICT(key_bi, state_hash) "
                        "DO UPDATE SET ts=excluded.ts",
                        key_bi, digest, int(Date.now()),
                    )
                await d1_run(
                    env,
                    "DELETE FROM repo_state_history WHERE key_bi=? "
                    "AND state_hash NOT IN (SELECT state_hash FROM "
                    "repo_state_history WHERE key_bi=? ORDER BY ts DESC LIMIT ?)",
                    key_bi, key_bi, STATE_PIN_HISTORY,
                )
            except Exception:
                pass
        # Cap: keep only the most-recent MAX_CATALOG_REPOS. COUNT first — the
        # old unconditional fetch-and-decrypt of EVERY catalog blob on every
        # publish was pure per-request overhead (the cap is almost never hit).
        total_row = await d1_first(
            env, "SELECT COUNT(*) AS c FROM repositories")
        if total_row and (total_row.get("c", 0) or 0) > MAX_CATALOG_REPOS:
            rows = await d1_all(env, "SELECT key_bi, data FROM repositories")
            decoded = []
            for r in rows:
                rec2 = await decrypt_row(env, r["data"])
                decoded.append((r["key_bi"], rec2.get("updatedAt", "") if rec2 else ""))
            decoded.sort(key=lambda x: x[1], reverse=True)
            for stale_key, _ in decoded[MAX_CATALOG_REPOS:]:
                await _delete_repo_scoped_state(env, stale_key)
                await d1_run(env, "DELETE FROM repositories WHERE key_bi=?", stale_key)
        # Endpoint registration deliberately resets health to pending. Once this
        # account-bound publication has durably pinned the public flagship state,
        # immediately challenge only the publishing node so clone availability
        # does not depend on a later cron tick. The helper is best-effort: an
        # unreachable or invalid proof remains fail-closed in endpoint state but
        # never rolls back an otherwise valid catalog publication.
        await _https_mirror_refresh_catalog_publisher_health(env, record)
        await purge_catalog_related_caches()
        if (
                record["visibility"] == "public"
                and record.get("source") == "remote-clone"):
            try:
                await _promote_hosted_repository_import(env, record)
            except Exception:
                # Import metadata and its notification are useful secondary
                # effects. The signed native catalog is still authoritative
                # and must not be rolled back if this bounded linkage fails.
                pass
        # A public record whose advertised head moved means freshly pushed code
        # just landed on this mirror node. Announce it to the live World room —
        # after the cache purge above, so a viewer's immediate refresh reads
        # the new head. Best-effort and already bounded by catalog_rate_check:
        # a World relay hiccup must never fail an authorized publication.
        new_commit = record.get("commit", "")
        if (record["visibility"] == "public" and exists
                and re.fullmatch(r"[0-9a-f]{40,64}", new_commit)
                and new_commit != prior_commit):
            try:
                await _world_broadcast_mirror_push(
                    env, owner, record["name"], new_commit)
            except Exception:
                pass
        payload = {
            "ok": True,
            "repository": record,
            "contributionsAccepted": bool(contribution_result["accepted"]),
        }
        if contribution_result["warning"]:
            payload["contributionWarning"] = contribution_result["warning"][:80]
        return json_response(payload, status=201)

    if method == "DELETE":
        params = parse_qs(urlparse(request.url).query)
        owner = safe_segment(params.get("owner", [""])[0])
        name = safe_segment(params.get("name", [""])[0])
        ts = clean_string(params.get("ts", [""])[0], 20)
        sig = clean_string(params.get("sig", [""])[0], 200)
        audit_target = owner + "/" + name if owner and name else ""
        if not owner or not name:
            return json_response({"error": "owner_name_required"}, status=400)

        # The desktop still signs the catalog-delete canonical with the
        # repository owner's Ed25519 key. The web Settings tab has no access to
        # that private key, so it instead proves the logged-in account session
        # and the same account->node ownership relationship used by About
        # editing. A valid session for some other account is never a substitute
        # for the signature.
        session_actor = await _authed_account_name(env, request)
        session_authorized = bool(
            session_actor
            and await _account_owns_node(env, session_actor, owner)
        )
        if not session_authorized:
            if session_actor and (not ts or not sig):
                await _audit_sensitive_action(
                    env, session_actor, "repository.delete", "repository",
                    audit_target, "denied", {"reason": "not_authorized"})
                return json_response(
                    {"error": "not_authorized"}, status=403)
            if not ts or not sig:
                return json_response(
                    {"error": "owner_name_ts_sig_required"}, status=400)
            try:
                skew = abs(int(Date.now()) - int(ts))
            except (TypeError, ValueError):
                skew = LOGIN_MAX_SKEW_MS + 1
            if skew > LOGIN_MAX_SKEW_MS:
                return json_response({"error": "stale_request"}, status=401)

        key_bi = await blind_index(env, owner + "/" + name)
        try:
            row = await d1_first(
                env, "SELECT data FROM repositories WHERE key_bi=?", key_bi)
        except Exception:
            await _audit_sensitive_action(
                env, owner, "repository.delete", "repository",
                audit_target, "failed", {"reason": "storage_error"})
            raise
        if not row:
            return json_response({"ok": True, "deleted": False})
        try:
            existing = await decrypt_row(env, row["data"])
        except Exception:
            await _audit_sensitive_action(
                env, owner, "repository.delete", "repository",
                audit_target, "failed", {"reason": "record_unreadable"})
            raise
        if not existing:
            await _audit_sensitive_action(
                env, owner, "repository.delete", "repository",
                audit_target, "failed", {"reason": "record_unreadable"})
            return json_response({"error": "catalog_record_unreadable"}, status=500)
        if not session_authorized:
            try:
                owner_pub = await _owner_pubkey(env, owner)
            except Exception:
                await _audit_sensitive_action(
                    env, owner, "repository.delete", "repository",
                    audit_target, "failed", {"reason": "identity_lookup_error"})
                raise
            if not owner_pub:
                await _audit_sensitive_action(
                    env, owner, "repository.delete", "repository",
                    audit_target, "denied", {"reason": "account_required"})
                return json_response(
                    {"error": "account_required"}, status=403)
            canonical = (
                "forkmesh-catalog-delete-v1\n" + owner + "\n" + name +
                "\n" + ts
            ).encode()
            try:
                authorized = await _verify_owner_signature(
                    env, owner, sig, canonical)
            except Exception:
                await _audit_sensitive_action(
                    env, owner, "repository.delete", "repository",
                    audit_target, "failed",
                    {"reason": "signature_check_error"})
                raise
            if not authorized:
                await _audit_sensitive_action(
                    env, owner, "repository.delete", "repository",
                    audit_target, "denied", {"reason": "bad_signature"})
                return json_response({"error": "bad_signature"}, status=401)
        # Deleting a single repo must purge it as completely as the
        # whole-account teardown does, or leftover scoped state (inboxes,
        # host presence, agent state, bounties, chat history) keeps the repo
        # alive in practice even though its catalog row is gone.
        try:
            await _delete_repo_scoped_state(env, key_bi)
            await d1_run(env, "DELETE FROM repositories WHERE key_bi=?", key_bi)
            await _delete_bounties_namespace(env, owner, name)
            await d1_run(
                env, "DELETE FROM chat_history WHERE room_key LIKE ?",
                "repo:" + owner + "/" + name + ":room:%")
            await d1_run(
                env,
                "DELETE FROM funds_received WHERE scope='project' AND key=?",
                owner + "/" + name)
            await purge_catalog_related_caches()
        except Exception:
            await _audit_sensitive_action(
                env, owner, "repository.delete", "repository",
                audit_target, "failed", {"reason": "mutation_error"})
            raise
        await _audit_sensitive_action(
            env, owner, "repository.delete", "repository",
            audit_target, "success", {"deleted": True})
        return json_response({"ok": True, "deleted": True})

    return json_response({"error": "method_not_allowed"}, status=405)


def _repo_identity_from_clone_url(value):
    raw = clean_string(value, 2048).strip()
    if not raw:
        return "", ""
    path = raw
    try:
        if re.match(r"^[a-z][a-z0-9+.-]*://", raw, re.I):
            path = urlparse(raw).path
        elif raw.startswith("git@") and ":" in raw:
            path = raw.split(":", 1)[1]
    except Exception:
        path = raw
    path = path.split("?", 1)[0].split("#", 1)[0].strip("/")
    parts = [p for p in path.split("/") if p]
    if len(parts) < 2:
        return "", ""
    owner = safe_segment(unquote(parts[-2]))
    name = safe_segment(unquote(parts[-1]))
    if name.lower().endswith(".git"):
        name = safe_segment(name[:-4])
    return owner, name


def _catalog_record_matches_identity(record, owner, repo):
    if not record:
        return False
    owner_l = str(owner or "").lower()
    repo_l = str(repo or "").lower()
    if (str(record.get("owner", "")).lower() == owner_l and
            str(record.get("name", "")).lower() == repo_l):
        return True
    clone_owner, clone_repo = _repo_identity_from_clone_url(record.get("cloneUrl", ""))
    return clone_owner.lower() == owner_l and clone_repo.lower() == repo_l


def _native_repository_logo_id(owner, repo):
    canonical = (
        "forkmesh-native-repository-logo-v1\n"
        + str(owner or "").strip().lower() + "\n"
        + str(repo or "").strip().lower()
    ).encode()
    return "native_" + hashlib.sha256(canonical).hexdigest()[:24]


def _native_repository_logo_record(record, owner, repo):
    source = record if isinstance(record, dict) else {}
    metadata = source.get("logoMetadata")
    metadata = dict(metadata) if isinstance(metadata, dict) else {}
    metadata["description"] = clean_string(
        source.get("description", ""), 500)
    topics = source.get("topics")
    if isinstance(topics, list) and "topics" not in metadata:
        metadata["topics"] = topics
    return {
        "id": _native_repository_logo_id(owner, repo),
        "provider": "forkmesh",
        "providerOwner": str(owner or "").lower(),
        "name": str(repo or ""),
        "fullName": str(owner or "") + "/" + str(repo or ""),
        "metadata": metadata,
        # Missing or malformed visibility stays private/fail-closed.
        "isPrivate": source.get("visibility") != "public",
        "commit": clean_string(source.get("commit", ""), 64).lower(),
    }


def _committed_repository_logo_url(record, owner, repo):
    """Return the immutable raw URL for a conventional root project logo."""
    source = record if isinstance(record, dict) else {}
    if source.get("isPrivate", source.get("visibility") != "public"):
        return ""
    commit = clean_string(source.get("commit", ""), 64).strip().lower()
    if not re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", commit):
        return ""
    metadata = source.get("metadata")
    if not isinstance(metadata, dict):
        metadata = source.get("logoMetadata")
    file_structure = (
        metadata.get("fileStructure")
        if isinstance(metadata, dict) else None
    )
    if not isinstance(file_structure, list):
        return ""
    files = {
        str(path or "").strip().lower(): str(path or "").strip()
        for path in file_structure
        if (
            isinstance(path, str)
            and "/" not in path.strip().rstrip("/")
        )
    }
    path = next(
        (
            files[name]
            for name in ("logo.png", "logo.webp", "logo.jpg", "logo.jpeg")
            if name in files
        ),
        "",
    )
    if not path:
        return ""
    return (
        "/api/repo/%s/%s/raw?path=%s&ref=%s"
        % (quote(owner), quote(repo), quote(path), quote(commit))
    )


async def _native_repository_logo_context(env, request, owner, repo):
    # Reuse the normal repository read boundary so logo GETs have exactly the
    # same owner/share behavior as repository content. The shared gate rejects
    # plaintext-private rows before decryption, treats the encrypted signed
    # visibility as authoritative, and normalizes missing and unauthorized
    # names to the same empty result.
    context = await _repository_access_context(
        env, request, owner, repo)
    if not isinstance(context, dict):
        return None, "", ""
    record = context.get("record")
    actor = clean_string(context.get("viewer"), MAX_NODE_NAME).lower()
    return (
        _native_repository_logo_record(record, owner, repo),
        _native_repository_logo_id(owner, repo),
        actor,
    )


async def native_repository_logo_handler(
        env, request, owner, repo, suggestions=False):
    await ensure_schema(env)
    record, repository_id, actor = await _native_repository_logo_context(
        env, request, owner, repo)
    if not record:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    service = _repository_import_service()
    if not suggestions:
        if method_name(request) != "GET":
            return json_response({"error": "method_not_allowed"}, status=405)
        committed_logo_url = _committed_repository_logo_url(
            record, owner, repo)
        params = parse_qs(urlparse(request.url).query)
        if params.get("image", [""])[0] == "1":
            if committed_logo_url:
                return Response("", status=302, headers={
                    "location": committed_logo_url,
                    "cache-control": "public, max-age=300",
                })
            logo = await service._official_logo(env, repository_id)
            logo = logo or repository_import.deterministic_logo(record)
            return _repository_logo_image_response(
                logo, public=not bool(record.get("isPrivate")))
        if committed_logo_url:
            return json_response({
                "ok": True,
                "repositoryId": repository_id,
                "logo": {
                    "dataUrl": committed_logo_url,
                    "source": "repository",
                },
            }, cache_control="no-store")
        response = await service.logo_for_record(env, repository_id, record)
        return response

    async def can_admin(candidate):
        candidate = str(candidate or actor or "").strip().lower()
        return bool(
            candidate
            and (
                await _repository_import_moderator(env, candidate)
                or await _account_owns_node(env, candidate, owner)
            )
        )

    return await service.native_logo_suggestions(
        env, request, repository_id, record, can_admin)


def _repository_logo_image_response(logo, public=True):
    """Serve one validated native logo as image bytes for social clients."""
    data_url = str(
        (logo or {}).get("dataUrl", "")
        if isinstance(logo, dict) else "")
    if not data_url.startswith("data:image/") or "," not in data_url:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    header, encoded = data_url.split(",", 1)
    media_type = header[5:].split(";", 1)[0].strip().lower()
    if media_type not in (
        "image/svg+xml", "image/png", "image/jpeg", "image/webp"
    ):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    try:
        if ";base64" in header.lower():
            raw = base64.b64decode(encoded, validate=True)
        elif media_type == "image/svg+xml":
            raw = unquote(encoded).encode("utf-8")
        else:
            raw = b""
    except Exception:
        raw = b""
    if not raw or len(raw) > 2 * 1024 * 1024:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    return JsResponse.new(Uint8Array.new(_to_js(bytes(raw))), to_js({
        "status": 200,
        "headers": {
            "content-type": media_type,
            "cache-control": (
                "public, max-age=300"
                if public
                else "private, no-store, max-age=0, must-revalidate"
            ),
            "x-content-type-options": "nosniff",
        },
    }))


async def _repo_about_public(env, request, owner, repo):
    # Public About/branding card + fediverse stats: the repo page's social
    # badge header and Watch button read this. No auth — same visibility as
    # the catalog entry itself.
    # Organization API paths are internally rewritten to the backing node
    # before this handler runs. Recover the public owner from the untouched
    # Request URL, but only when the durable org link still resolves to the
    # canonical owner passed by the router. Catalog/privacy/settings reads
    # continue to use the backing owner; the actor identity and public media
    # URLs must keep the organization name.
    display_owner = owner
    try:
        public_path = urlparse(request.url).path
        public_match = REPO_ABOUT_RE.match(public_path)
    except Exception:
        public_match = None
    if public_match:
        candidate_owner = safe_segment(public_match.group(1))
        candidate_repo = safe_segment(public_match.group(2))
        if candidate_owner and candidate_repo == repo:
            if candidate_owner == owner:
                display_owner = candidate_owner
            elif await _org_repo_node(
                    env, candidate_owner, candidate_repo) == owner:
                display_owner = candidate_owner
    privacy_reader = globals().get("_repo_is_private")
    if callable(privacy_reader) and await privacy_reader(env, owner, repo):
        return json_response({"error": "not_found"}, status=404)
    key_bi = await blind_index(env, owner + "/" + repo)
    repo_row = await d1_first(
        env, "SELECT data FROM repositories WHERE key_bi=?", key_bi)
    if not repo_row:
        return json_response({"error": "not_found"}, status=404)
    rec = await decrypt_row(env, repo_row.get("data"))
    origin = _ap_origin(env, request)
    handle = ap.repo_handle(str(display_owner).lower(), str(repo).lower())
    logo_url = ""
    banner_url = ""
    media_rows = await d1_all(
        env, "SELECT kind, updated_at FROM repo_media WHERE repo_bi=?", key_bi)
    for media in media_rows or []:
        media_url = "/api/repo/%s/%s/media/%s.png?v=%d" % (
            quote(display_owner), quote(repo), media.get("kind", ""),
            int(media.get("updated_at") or 0))
        if media.get("kind") == "logo":
            logo_url = media_url
        elif media.get("kind") == "banner":
            banner_url = media_url
    generated_logo = {}
    resolved_logo = {}
    logo_record_builder = globals().get("_native_repository_logo_record")
    logo_service_factory = globals().get("_repository_import_service")
    repository_import_module = globals().get("repository_import")
    if (callable(logo_record_builder)
            and callable(logo_service_factory)
            and repository_import_module is not None):
        logo_record = logo_record_builder(rec, owner, repo)
        logo_service = logo_service_factory()
        approved_logo = await logo_service._official_logo(
            env, logo_record["id"])
        generated_logo = repository_import_module.deterministic_logo(
            logo_record)
        resolved_logo = approved_logo or generated_logo
    if not logo_url:
        committed_logo_resolver = globals().get(
            "_committed_repository_logo_url")
        logo_url = (
            committed_logo_resolver(rec, display_owner, repo)
            if callable(committed_logo_resolver) else ""
        ) or str(resolved_logo.get("dataUrl") or "")
    followers = 0
    followers_list = []
    fedi_enabled = await _ap_enabled(env)
    ap_settings = await _ap_repo_settings_get(env, owner, repo)
    if fedi_enabled:
        actor_bi = await _ap_actor_bi(env, AP_ACTOR_REPO, handle)
        row = await d1_first(
            env, "SELECT COUNT(*) AS c FROM ap_followers WHERE actor_bi=?",
            actor_bi)
        followers = (row or {}).get("c", 0) or 0
        # The newest followers, so the repo page can show WHO is watching —
        # follower_id/handle are public fediverse identifiers (the remote
        # server publishes the same follow), capped so a popular repo never
        # ships thousands of rows in an About card. The cached remote actor
        # document (LEFT JOIN: absent until that actor is first fetched) adds
        # the presentation every fediverse client already shows for them —
        # display name, avatar, bio, profile URL.
        rows = await d1_all(
            env,
            "SELECT follower_id, follower_handle, created_at, display_name,"
            " avatar_url, summary, url FROM ap_followers"
            " LEFT JOIN ap_remote_actors ON actor_id = follower_id"
            " WHERE actor_bi=? ORDER BY created_at DESC LIMIT 50",
            actor_bi)
        for follower in rows or []:
            follower_url = str(follower.get("follower_id") or "")
            follower_handle = str(follower.get("follower_handle") or "")
            parsed = urlparse(follower_url)
            if not follower_handle and follower_url:
                # Older rows may lack the resolved handle; a readable
                # fallback beats a bare URL in the UI.
                name = parsed.path.rstrip("/").rpartition("/")[2]
                if name and parsed.hostname:
                    follower_handle = "@%s@%s" % (
                        name.lstrip("@"), parsed.hostname)
            if follower_handle or follower_url:
                followers_list.append({
                    "handle": follower_handle,
                    "url": follower_url,
                    "name": clean_string(
                        follower.get("display_name") or "", 80),
                    "avatarUrl": ap.public_media_url(
                        follower.get("avatar_url") or ""),
                    "about": ap_threads.sanitize_remote_content(
                        follower.get("summary") or "", 240),
                    "instance": str(parsed.hostname or "").lower(),
                    "profileUrl": ap.public_media_url(
                        follower.get("url") or "") or follower_url,
                    "followedAt": int(follower.get("created_at") or 0),
                })
    return json_response({
        "ok": True,
        "description": clean_string(
            (rec or {}).get("description", "") or "", 240),
        "website": clean_string((rec or {}).get("website", "") or "", 240),
        "logoUrl": logo_url,
        "logo": resolved_logo,
        "bannerUrl": banner_url,
        "defaultLogoUrl": generated_logo.get("dataUrl") or AP_AVATAR_PATH,
        "defaultBannerUrl": AP_BANNER_PATH,
        "fediverse": {
            # enabled = "this repo currently federates": the instance switch
            # AND the owner's per-repo switch.
            "enabled": fedi_enabled and ap_settings["federate"],
            "handle": "@%s@%s" % (handle, _ap_domain_of(origin)),
            "actorUrl": _ap_actor_url(origin, AP_ACTOR_REPO, handle),
            "followers": followers,
            "followersList": followers_list,
            "settings": ap_settings,
        },
    }, cache_control="public, max-age=30")


async def repo_about_handler(env, request, owner, repo):
    await ensure_schema(env)
    if method_name(request) == "GET":
        return await _repo_about_public(env, request, owner, repo)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    # Only the repo owner (proven by their session token, not a self-asserted
    # ownerAccount string) may edit repo metadata. A platform role is not a
    # decryption/content-management grant. The Qt
    # desktop has no browser session; it proves the owner account's registered
    # Ed25519 key instead (same trust gate as ap-publish / the inbox drains,
    # with a distinct canonical so its tokens can't be replayed elsewhere).
    actor = await _authed_account_name(env, request, data)
    owner_key_authed = False
    if not actor and data.get("ownerSig") and data.get("ts"):
        ts = str(data.get("ts", "") or "")
        owner_pub = await _owner_pubkey(env, owner)
        canonical = ("forkmesh-repo-about-v1\n" + owner + "\n" + repo +
                     "\n" + ts).encode()
        if owner_pub and _ts_ok(ts) and await ed25519_verify(
                owner_pub, str(data.get("ownerSig", "") or ""), canonical):
            actor = str(owner).lower()
            owner_key_authed = True
    if not actor or (not owner_key_authed
                     and not await _account_owns_node(env, actor, owner)):
        return json_response({"error": "not_authorized"}, status=403)
    if not await _owner_pubkey(env, owner):
        return json_response({"error": "account_required"}, status=403)

    # Absent = unchanged, so a settings-only save (Qt fediverse switches)
    # never blanks the description.
    description_provided = "description" in data
    description = clean_string(data.get("description", ""), 240)
    # Optional project website shown under the description (and written into
    # the repo's .forkmesh/info.json by the owner's node). Absent = unchanged;
    # empty string = remove. Only http(s) URLs are accepted.
    website_provided = "website" in data
    website = clean_string(data.get("website", ""), 240).strip()
    if website_provided and website and not re.match(
            r"^https?://[^\s]+$", website):
        return json_response({"error": "invalid_website"}, status=400)
    # Optional repo branding for the fediverse actor (and anything else that
    # wants it): PNG logo (avatar) + banner (profile header). Absent field =
    # leave unchanged; empty string = remove. Validated before any write so a
    # bad image never half-applies the About edit.
    media_updates = {}
    for field, kind, cap in (("logoPng", "logo", MAX_REPO_LOGO_BYTES),
                             ("bannerPng", "banner", MAX_REPO_BANNER_BYTES)):
        if field not in data:
            continue
        png_b64, media_error = clean_media_png(data.get(field), cap)
        if media_error:
            return json_response({"error": media_error, "field": field},
                                 status=400)
        media_updates[kind] = png_b64
    rows = await d1_all(
        env, "SELECT key_bi, data, is_private FROM repositories")
    updated = 0
    text_changed = False
    first = None
    for row in rows:
        record = await decrypt_row(env, row.get("data"))
        if not _catalog_record_matches_identity(record, owner, repo):
            continue
        updated += 1
        if first is None:
            first = record
        # Re-saving the About dialog with unchanged values must be a no-op:
        # every write here cascades into a catalog cache purge, an about_inbox
        # round-trip through the owner's desktop, and an Update(Group)
        # broadcast to every fediverse follower.
        if ((not description_provided or
             str(record.get("description") or "") == description) and
                (not website_provided or
                 str(record.get("website") or "") == website)):
            continue
        if description_provided:
            record["description"] = description
        if website_provided:
            record["website"] = website
        enc = await encrypt_row(env, record)
        await d1_run(
            env,
            "UPDATE repositories SET data=?, is_private=? WHERE key_bi=?",
            enc,
            1 if record.get("visibility") == "private" else 0,
            row.get("key_bi"),
        )
        text_changed = True
    if not updated:
        return json_response({"error": "not_found"}, status=404)
    media_bi = await blind_index(env, str(owner).lower() + "/" + repo)
    media_changed = False
    for kind, png_b64 in media_updates.items():
        existing = await d1_first(
            env, "SELECT data FROM repo_media WHERE repo_bi=? AND kind=?",
            media_bi, kind)
        if not png_b64:
            if existing:
                await d1_run(
                    env, "DELETE FROM repo_media WHERE repo_bi=? AND kind=?",
                    media_bi, kind)
                media_changed = True
            continue
        # Identical bytes keep the stored updated_at: bumping it would rotate
        # the ?v= cache-buster in the actor doc and make every follower server
        # re-download an image that did not change.
        stored = await decrypt_row(env, existing.get("data")) if existing \
            else None
        if stored and stored.get("png") == png_b64:
            continue
        await d1_run(
            env,
            "INSERT INTO repo_media (repo_bi, kind, data, updated_at)"
            " VALUES (?,?,?,?)"
            " ON CONFLICT(repo_bi, kind) DO UPDATE SET data=excluded.data,"
            " updated_at=excluded.updated_at",
            media_bi, kind, await encrypt_row(env, {"png": png_b64}),
            int(Date.now()))
        media_changed = True
    # Per-repo fediverse switches ride the same About save (web gear form and
    # the Qt dialog both send a `fediverse` object). Absent = unchanged; an
    # unchanged value writes nothing, so a plain description re-save never
    # touches the AP tables or the edge cache.
    ap_settings = None
    fedi_data = data.get("fediverse")
    if isinstance(fedi_data, dict):
        current_settings = await _ap_repo_settings_get(env, owner, repo)
        ap_settings = dict(current_settings)
        for key in AP_REPO_SETTING_DEFAULTS:
            if key in fedi_data:
                ap_settings[key] = bool(fedi_data.get(key))
        if ap_settings != current_settings:
            await d1_run(
                env,
                "INSERT INTO ap_repo_settings (repo_bi, data, updated_at)"
                " VALUES (?,?,?) ON CONFLICT(repo_bi) DO UPDATE SET"
                " data=excluded.data, updated_at=excluded.updated_at",
                await _ap_repo_settings_bi(env, owner, repo),
                json.dumps(ap_settings), int(Date.now()))
            # The actor doc, its collections and the webfinger lookup are
            # edge-cached (and misses park a 404): drop them so a federation
            # switch takes effect now, not after the TTL.
            origin = _ap_origin(env, request)
            ap_handle = ap.repo_handle(
                str(owner).lower(), str(repo).lower())
            actor_url = _ap_actor_url(origin, AP_ACTOR_REPO, ap_handle)
            for cache_key in (
                    actor_url, actor_url + "/followers",
                    actor_url + "/following", actor_url + "/outbox",
                    "%s/.well-known/webfinger?resource=acct:%s@%s"
                    % (origin, ap_handle, _ap_domain_of(origin))):
                await edge_cache_delete(cache_key)
            if not (ap_settings["federate"]
                    and ap_settings["broadcastEvents"]):
                # Opt-out is immediate and destructive: queued public metadata
                # cannot later leak in a stale digest after settings change.
                purge_digests = globals().get(
                    "_ap_purge_repo_digest_queues")
                if callable(purge_digests):
                    await purge_digests(env, owner, repo)
    if text_changed:
        # Queue the edit for the owner's desktop node, which writes it into the
        # repo's committed .forkmesh/info.json (the same file the desktop app's
        # own About editor maintains) on its next sync. Latest edit wins.
        about_update = {
            "about": description if description_provided
            else clean_string((first or {}).get("description", "") or "", 240),
            "website": website if website_provided
            else clean_string((first or {}).get("website", "") or "", 240),
            "ts": int(Date.now()),
            "editor": actor,
            "source": "web",
        }
        await d1_run(
            env,
            "INSERT INTO about_inbox (repo_bi, data, queued_at) VALUES (?,?,?)"
            " ON CONFLICT(repo_bi) DO UPDATE SET data=excluded.data,"
            " queued_at=excluded.queued_at",
            media_bi, await encrypt_row(env, about_update), about_update["ts"])
        await _best_effort_inbox_side_effect(
            notify_repo_host(env, owner, repo, "about"))
        await purge_catalog_related_caches()
    if text_changed or media_changed:
        # Tell existing fediverse followers the profile changed (Update
        # activity), so the new logo/banner/description shows up on remote
        # servers now, not whenever their actor cache happens to expire.
        await _best_effort_inbox_side_effect(_ap_broadcast_actor_update(
            env, request, AP_ACTOR_REPO,
            ap.repo_handle(str(owner).lower(), str(repo).lower())))
    # Return only the fields the caller just set — never the full decrypted
    # catalog record (which carries private-repo cloneUrl/visibility/stateHash).
    media_rows = await d1_all(
        env, "SELECT kind FROM repo_media WHERE repo_bi=?", media_bi)
    media_kinds = {r.get("kind") for r in (media_rows or [])}
    result = {
        "ok": True,
        "description": description if description_provided
        else clean_string((first or {}).get("description", "") or "", 240),
        "updated": updated,
        "hasLogo": "logo" in media_kinds,
        "hasBanner": "banner" in media_kinds,
        "isPrivate": bool(first and first.get("visibility") == "private"),
    }
    if ap_settings is not None:
        result["fediverse"] = {"settings": ap_settings}
    return json_response(result)


async def repo_mirrors_handler(env, request, owner, repo):
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    privacy_reader = globals().get("_repo_is_private")
    if (callable(privacy_reader)
            and await privacy_reader(env, owner, repo)):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    # The router internally rewrites an organization URL to its backing node.
    # Recover the untouched public identity for response/cache presentation;
    # backing node identity remains an authorization detail and must not turn
    # /forkmesh/forkmesh into a user-owned /jett/forkmesh repository in UIs.
    public_owner = str(owner or "").strip().lower()
    public_repo = str(repo or "").strip().lower()
    try:
        original_match = REPO_API_PREFIX_RE.match(
            urlparse(str(getattr(request, "url", "") or "")).path)
        requested_owner = safe_segment(
            original_match.group(1)) if original_match else ""
        requested_repo = safe_segment(
            original_match.group(2)) if original_match else ""
        if (
            requested_owner
            and requested_repo == public_repo
            and requested_owner != public_owner
            and await _org_repo_node(
                env, requested_owner, requested_repo) == public_owner
        ):
            public_owner = requested_owner
    except Exception:
        pass
    # Public, poll-heavy payload (repo page + desktop mirror panel): serve
    # from the edge for a few seconds so a burst of viewers costs one build.
    cache_key = ("https://forkmesh.internal/api/repo/%s/%s/mirrors"
                 % (quote(public_owner), quote(public_repo)))
    cached = await edge_cache_match(cache_key)
    if cached is not None:
        return cached
    rows = await d1_all(
        env,
        "SELECT key_bi, owner_bi, data, is_private FROM repositories WHERE is_private = 0"
    )
    catalog_rows = []
    for row in rows:
        rec = await decrypt_row(env, row.get("data"))
        if not rec:
            continue
        if rec.get("visibility") != "public":
            continue
        if _is_blocked_catalog_identity(env, rec.get("owner"), rec.get("name")):
            continue
        catalog_rows.append({
            "key_bi": row.get("key_bi"),
            "is_private": int(row.get("is_private") or 0),
            "data": rec,
        })

    now = int(Date.now())
    # Repository bytes moved off the retired host WebSocket to signed direct
    # HTTPS endpoints. Read the fresh endpoint leases once and map them onto
    # this catalog group directly; the old hydrate path issued up to eight
    # redundant per-owner D1 probes and memoized a transient zero for 30s,
    # making a recovered mirror flicker offline after its signed lease was
    # already healthy again.
    endpoint_rows = await d1_all(
        env,
        """SELECT node_name,base_url,checked_at,latency_ms,region,healthy,
                  integrity,abuse_blocked,forkmesh_verified_at,
                  forkmesh_operations_json,forkmesh_active
             FROM mirror_https_endpoints""",
    )
    endpoint_by_node = {
        clean_string(row.get("node_name", ""), MAX_NODE_NAME).lower(): row
        for row in endpoint_rows or []
        if valid_node_name(
            clean_string(row.get("node_name", ""), MAX_NODE_NAME).lower())
    }
    reachable_seen = {
        node_name: int(row.get("checked_at") or now)
        for node_name, row in endpoint_by_node.items()
        if (
            int(row.get("checked_at") or 0)
            >= now - HTTPS_MIRROR_STATUS_FRESH_MS
            and (
                # Older rows/tests predate signed endpoint attestation. The
                # database migration backfills every security column
                # together, so an entirely absent set is a legacy fresh
                # presence row; a partially populated row must still satisfy
                # every modern integrity gate.
                not any(
                    key in row
                    for key in (
                        "forkmesh_verified_at", "healthy",
                        "forkmesh_active", "integrity", "abuse_blocked",
                    )
                )
                or (
                    int(row.get("forkmesh_verified_at") or 0)
                    >= now - HTTPS_MIRROR_STATUS_FRESH_MS
                    and bool(int(row.get("healthy") or 0))
                    and bool(int(row.get("forkmesh_active") or 0))
                    and str(row.get("integrity") or "") == "ok"
                    and not bool(int(row.get("abuse_blocked") or 0))
                )
            )
        )
    }
    reachable_nodes = set(reachable_seen)
    presence = {}
    for row in catalog_rows:
        record = row.get("data") or {}
        node_name = clean_string(
            record.get("machineName") or record.get("owner", ""),
            MAX_NODE_NAME,
        ).lower()
        key = str(row.get("key_bi") or "")
        if key and node_name in reachable_seen:
            presence[key] = reachable_seen[node_name]
    first_rows = await d1_all(env, "SELECT repo_bi, ts FROM repo_first_hosted")
    first_hosted = {
        str(r.get("repo_bi")): int(r.get("ts") or 0)
        for r in first_rows
        if r.get("repo_bi")
    }
    # Recent owner-attested state pins, so the payload can mark which mirrors
    # the clone integrity gate is rejecting (same gathering as _state_pins).
    # Scoped to this request's catalog group — the old full-table scan read
    # every repo's pin history on every /mirrors poll.
    history = {}
    group_keys = [str(r.get("key_bi") or "") for r in catalog_rows
                  if r.get("key_bi")]
    for offset in range(0, len(group_keys), 80):
        key_batch = group_keys[offset:offset + 80]
        hist_rows = await d1_all(
            env,
            "SELECT key_bi, state_hash FROM repo_state_history"
            " WHERE key_bi IN (%s)" % ",".join("?" for _ in key_batch),
            *key_batch)
        for r in hist_rows:
            history.setdefault(str(r.get("key_bi") or ""), []).append(
                r.get("state_hash"))
    linked_row = await d1_first(
        env,
        "SELECT 1 AS linked FROM org_repos "
        "WHERE node_owner=? AND repo=? LIMIT 1",
        str(owner or "").strip().lower(),
        str(repo or "").strip().lower(),
    )
    payload = build_repo_mirrors_payload(
        owner,
        repo,
        catalog_rows,
        presence,
        first_hosted,
        now,
        HOST_PRESENCE_STALE_MS,
        5 * 1000,
        history,
        linked_canonical=bool(linked_row),
        reachable_nodes=reachable_nodes,
    )
    if payload is None:
        return json_response({"error": "not_found"}, status=404)
    payload["owner"] = public_owner
    payload["repo"] = public_repo
    # Owner column: a headless mirror's catalog record carries no ownerUser of
    # its own, but the node account may be claim-linked to a user (adhoc #53:
    # the node record's `owner` field names the linked user). Resolve that link
    # here so every surface — web repo page and the desktop Mirror nodes panel —
    # shows the human owner without each publisher having to know it.
    for mirror in payload.get("mirrors", []):
        node_name = str(mirror.get("node") or "").strip().lower()
        endpoint = endpoint_by_node.get(node_name) or {}
        try:
            operations = json.loads(
                str(endpoint.get("forkmesh_operations_json") or "[]"))
        except Exception:
            operations = []
        if not isinstance(operations, list):
            operations = []
        mirror.update({
            "endpoint": str(endpoint.get("base_url") or ""),
            "checkedAt": int(endpoint.get("checked_at") or 0),
            "latencyMs": max(0, int(endpoint.get("latency_ms") or 0)),
            "region": clean_string(endpoint.get("region", ""), 40),
            "endpointHealthy": bool(int(endpoint.get("healthy") or 0)),
            "endpointIntegrity": str(
                endpoint.get("integrity") or "unknown"),
            "endpointFresh": bool(node_name in reachable_seen),
            "abuseBlocked": bool(int(endpoint.get("abuse_blocked") or 0)),
            "operations": [
                clean_string(value, 40)
                for value in operations[:32]
                if isinstance(value, str)
            ],
        })
        if mirror.get("ownerUser"):
            continue
        if not node_name:
            continue
        try:
            _, node_rec = await _account_row(env, node_name)
        except Exception:
            continue
        if not node_rec:
            continue
        if _account_kind(node_rec) == "user":
            mirror["ownerUser"] = node_name
        else:
            mirror["ownerUser"] = str(node_rec.get("owner") or "").strip()
    # Node cabinets and the repository Mirrors panel poll while visible. Keep a
    # tiny shared edge window to collapse bursts without leaving an integrity
    # transition or completed sync stuck on screen for ten seconds.
    response = json_response(payload, cache_seconds=3)
    await edge_cache_put(cache_key, response)
    return response


# --- Release download counts -------------------------------------------------

async def record_release_download(env, repo_bi, sha256, ua=""):
    """Log one completed release-asset download. Best-effort; never raises —
    called fire-and-forget from the streaming DO response, so a D1 hiccup must
    never fail or delay the download itself."""
    try:
        await ensure_schema(env)
        await d1_run(
            env,
            "INSERT INTO release_downloads (repo_bi, sha256, ts, ua) VALUES (?, ?, ?, ?)",
            repo_bi, sha256, int(Date.now()), ua,
        )
    except Exception:
        pass


async def release_download_counts(env, repo_bi):
    await ensure_schema(env)
    rows = await d1_all(
        env,
        "SELECT sha256, COUNT(*) AS n FROM release_downloads "
        "WHERE repo_bi=? GROUP BY sha256",
        repo_bi,
    )
    return {str(r.get("sha256")): int(r.get("n") or 0) for r in rows if r.get("sha256")}


async def release_downloads_handler(env, request, owner, repo):
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    privacy_reader = globals().get("_repo_is_private")
    if callable(privacy_reader) and await privacy_reader(env, owner, repo):
        return json_response({"error": "not_found"}, status=404)
    repo_bi = await blind_index(env, owner + "/" + repo)
    counts = await release_download_counts(env, repo_bi)
    return json_response({"ok": True, "counts": counts})


# --- Public waitlist (waitlist table) ---------------------------------------

def _waitlist_normalize_email(value):
    email = str(value or "").strip().lower()
    if len(email) > 254 or not _WAITLIST_EMAIL_RE.fullmatch(email):
        return ""
    return email


async def waitlist_handler(env, request):
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    if not isinstance(data, dict):
        return json_response({"error": "invalid_json"}, status=400)
    email = _waitlist_normalize_email(data.get("email", ""))
    if not email:
        return json_response({"error": "valid_email_required"}, status=400)
    source = clean_string(data.get("source", "features"), MAX_WAITLIST_FIELD)
    path = clean_string(data.get("path", ""), MAX_WAITLIST_FIELD)
    user_agent = clean_string(request.headers.get("user-agent") or "", 512)
    await d1_run(
        env,
        """INSERT OR IGNORE INTO waitlist
           (email, created_at, source, path, user_agent)
           VALUES (?,?,?,?,?)""",
        email, int(Date.now()), source, path, user_agent,
    )
    return json_response({"ok": True}, status=201)


# --- Accounts (users/nodes tables) — name + solana + password + TOTP --------

def _account_kind(rec):
    rec = rec or {}
    kind = clean_string(rec.get("kind", ""), 16).strip().lower()
    if kind in ("user", "node"):
        return kind
    return "user" if rec.get("pass_hash") else "node"


def _account_has_legacy_wallet_key(rec):
    # Compatibility detector only. A historical account blob can still contain
    # a donation wallet seed until the offline migration scrubs it. No active
    # Worker write may copy that seed into a new ciphertext.
    return isinstance(rec, dict) and bool(rec.get("donation_secret"))


async def _mirror_account_identity_tables(env, name_bi, rec, email_bi=None,
                                          ip_bi=None, is_admin=None,
                                          touch_seen=False):
    # Authoritative store for account records: the physical users/nodes tables
    # (migration 0025). The legacy accounts table these once mirrored was
    # dropped by migration 0042; old clients keep using /api/accounts/* but
    # every record lives here now, keyed by blind_index(name) on both tables.
    if _account_has_legacy_wallet_key(rec):
        raise RuntimeError("legacy_custody_migration_required")
    name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    if not name:
        return
    kind = _account_kind(rec)
    now = int(Date.now())
    if kind == "user":
        if email_bi is None and rec.get("email"):
            email_bi = await blind_index(env, clean_string(rec.get("email", ""), 254).lower())
        if js_nullish(ip_bi):
            ip_bi = ""
        enc_user = await encrypt_row(env, rec)
        await d1_run(
            env,
            """INSERT INTO users (user_bi, data, email_bi, username, is_admin, ip_bi)
               VALUES (?,?,?,?,?,?)
               ON CONFLICT(user_bi) DO UPDATE SET
                 data=excluded.data,
                 email_bi=COALESCE(excluded.email_bi, users.email_bi),
                 username=excluded.username,
                 is_admin=CASE WHEN ? THEN excluded.is_admin ELSE users.is_admin END,
                 ip_bi=COALESCE(NULLIF(excluded.ip_bi, ''), users.ip_bi)""",
            name_bi, enc_user, email_bi, name,
            int(is_admin or 0), ip_bi, 1 if is_admin is not None else 0)
    else:
        await d1_run(env, "DELETE FROM users WHERE user_bi=?", name_bi)

    pubkey = clean_string(rec.get("pubkey", ""), 120)
    if pubkey or kind == "node":
        # A node-kind record without a pubkey is a keyless reservation (name
        # parked before the key binds at finalize); it must still persist here
        # now that the nodes table is the only store for node records.
        owner = clean_string(rec.get("owner", ""), MAX_NODE_NAME).lower()
        if not owner and kind == "user":
            owner = name
        owner_bi = await blind_index(env, owner) if owner else None
        enc_node = await encrypt_row(env, rec)
        last_seen = now if touch_seen else 0
        await d1_run(
            env,
            """INSERT INTO nodes (node_bi, user_bi, pubkey, data, name, last_seen)
               VALUES (?,?,?,?,?,?)
               ON CONFLICT(node_bi) DO UPDATE SET
                 user_bi=excluded.user_bi, pubkey=excluded.pubkey,
                 data=excluded.data, name=excluded.name,
                 last_seen=CASE WHEN ? THEN
                   MAX(nodes.last_seen, excluded.last_seen)
                   ELSE nodes.last_seen END""",
            name_bi, owner_bi, pubkey, enc_node, name, last_seen,
            1 if touch_seen else 0)
    else:
        await d1_run(env, "DELETE FROM nodes WHERE node_bi=?", name_bi)


async def touch_registered_node(env, name_bi, rec=None):
    # A real node activity signal (registration/finalize, signed heartbeat,
    # desktop login, or host WebSocket connect). Plain account reads repair the
    # users/nodes mirror but deliberately do NOT refresh this timestamp; otherwise
    # merely browsing stale profiles would keep abandoned nodes alive forever.
    if not name_bi:
        return
    if (rec and not _account_has_legacy_wallet_key(rec)
            and clean_string(rec.get("pubkey", ""), 120)
            and name_bi not in _MIRRORED_ACCOUNT_BIS):
        # First touch this isolate: full mirror repair (also stamps last_seen).
        await _mirror_account_identity_tables(
            env, name_bi, rec, touch_seen=True)
        if len(_MIRRORED_ACCOUNT_BIS) < 10000:
            _MIRRORED_ACCOUNT_BIS.add(name_bi)
        return
    # Mirror already repaired this isolate (or no rec): the 1-statement
    # last_seen stamp is all a heartbeat/connect needs — the full mirror
    # rewrite (2 encrypts + 2 upserts) on every beat helped melt the free
    # plan on 2026-07-11.
    await d1_run(
        env, "UPDATE nodes SET last_seen=? WHERE node_bi=?",
        int(Date.now()), name_bi)


async def _account_identity_rec_by_bi(env, name_bi):
    # Authoritative-store lookup by blind_index(name): user_bi and node_bi are
    # both blind_index(name), so one key resolves either table. Returns the
    # decrypted record, or None.
    if not name_bi:
        return None
    row = await d1_first(env, "SELECT data FROM users WHERE user_bi=?", name_bi)
    if not row:
        row = await d1_first(env, "SELECT data FROM nodes WHERE node_bi=?", name_bi)
    if not row:
        return None
    return await decrypt_row(env, row.get("data"))


# name_bis whose users/nodes rows this isolate already refreshed via
# touch_registered_node's full rewrite. The rewrite costs 1-2 encrypt_row +
# 2 upserts — repeating it on every activity signal was a top contributor
# to the 2026-07-11 free-plan CPU overload, so after the first touch a
# heartbeat only stamps last_seen. Write paths call
# _mirror_account_identity_tables directly (via _save_account), so a stale
# entry here can never mask a real update; a recycled isolate simply
# rewrites once more.
_MIRRORED_ACCOUNT_BIS = set()


async def _account_row(env, name):
    name_bi = await blind_index(env, name)
    return name_bi, await _account_identity_rec_by_bi(env, name_bi)


async def _owner_pubkey(env, owner):
    _, rec = await _account_row(env, owner)
    return rec.get("pubkey", "") if rec else ""


async def _account_row_by_pubkey(env, pubkey):
    node = await d1_first(env, "SELECT node_bi, data FROM nodes WHERE pubkey=?", pubkey)
    if node:
        rec = await decrypt_row(env, node.get("data"))
        if rec:
            return node.get("node_bi"), rec
    return None, None


async def _resolve_claimable_node(env, raw_id):
    # A claim-node "node ID" may be the account's chosen name (the common
    # case) or its Ed25519 public key, which the desktop app's own profile
    # card labels "Node ID" (issue #351). Returns (node_bi, node_rec,
    # node_name) or (None, None, "") when neither resolves.
    candidate = (raw_id or "").strip()
    name = candidate.lower()
    if valid_node_name(name):
        node_bi, node_rec = await _account_row(env, name)
        if node_rec:
            return node_bi, node_rec, name
    if valid_node_pubkey(candidate):
        node_bi, node_rec = await _account_row_by_pubkey(env, candidate)
        if node_rec:
            return node_bi, node_rec, node_rec.get("name", "")
    return None, None, ""


def _ts_ok(ts):
    try:
        return abs(int(Date.now()) - int(ts)) <= LOGIN_MAX_SKEW_MS
    except (TypeError, ValueError):
        return False


async def verify_view_token(env, owner, repo, ts, sig):
    # Only the owner account's key holder can browse/clone a private repo.
    if not owner or not repo or not sig or not _ts_ok(ts):
        return False
    pubkey = await _owner_pubkey(env, owner)
    if not pubkey:
        return False
    canonical = ("forkmesh-view-v1\n" + owner + "\n" + repo + "\n" + str(ts)).encode()
    return await ed25519_verify(pubkey, sig, canonical)


async def verify_push_token(env, owner, repo, ts, sig):
    # Write gate for git push over the relay (issue #358): only the owner
    # account's registered key may run receive-pack against the served mirror
    # (collaborator keys are a later extension). It uses a fresh timestamp and
    # Ed25519 over an explicit canonical string with a distinct prefix. This
    # timestamp-signed binding is deliberately the
    # simplest thing that stays in the existing trust model (no server-side nonce
    # state); the freshness window is the short-lived element.
    if not owner or not repo or not sig or not _ts_ok(ts):
        return False
    pubkey = await _owner_pubkey(env, owner)
    if not pubkey:
        return False
    canonical = ("forkmesh-push-v1\n" + owner + "\n" + repo + "\n" + str(ts)).encode()
    return await ed25519_verify(pubkey, sig, canonical)


async def _basic_auth_push_ok(env, owner, repo, request):
    # git supplies the push token in HTTP Basic auth (password="<ts>.<sig>"),
    # from the push URL or a credential helper. The username selects whose key
    # signed it; only the owner may push for now (collaborator keys later).
    header = request.headers.get("authorization") or ""
    if not header.lower().startswith("basic "):
        return False
    try:
        decoded = base64.b64decode(header[6:].strip()).decode("utf-8", "replace")
    except Exception:
        return False
    username, _, password = decoded.partition(":")
    ts, _, sig = password.partition(".")
    if not ts or not sig:
        return False
    if username and username != owner:
        # A non-owner username selects the org-team path (issue #388): the
        # pusher signs with their OWN key and must hold write+ permission on
        # the repo through an organization it is linked under.
        return await verify_org_push_token(env, username, owner, repo, ts, sig)
    return await verify_push_token(env, owner, repo, ts, sig)


async def verify_catalog_view_token(env, viewer, ts, sig):
    # Listing gate: lets a logged-in owner additionally see their OWN private repos
    # in the catalog, which is otherwise public-only. Not bound to a single repo
    # (it authorizes a listing, not one clone) and uses a distinct canonical string
    # so a per-repo forkmesh-view-v1 token can't be replayed as a listing token and
    # vice versa. Returns the viewer's account name on success, "" otherwise — an
    # unknown/garbled viewer simply falls back to the public-only catalog.
    if not viewer or not sig or not _ts_ok(ts):
        return ""
    pubkey = await _owner_pubkey(env, viewer)
    if not pubkey:
        return ""
    canonical = ("forkmesh-catalog-view-v1\n" + viewer + "\n" + str(ts)).encode()
    if await ed25519_verify(pubkey, sig, canonical):
        return viewer
    return ""


async def _repo_shared_with(env, owner, repo, grantee):
    # True when the owner has shared `owner/repo` with the `grantee` account
    # (issue #9). repo_bi is keyed the same way as repositories.key_bi so it joins
    # a private repo to its collaborator rows. Best-effort: any error => not shared
    # (fail closed; a transient DB hiccup must never grant access it shouldn't).
    if not owner or not repo or not grantee:
        return False
    try:
        await ensure_schema(env)
        repo_bi = await blind_index(env, owner + "/" + repo)
        grantee_bi = await blind_index(env, grantee)
        row = await d1_first(
            env,
            "SELECT 1 AS one FROM repo_shares WHERE repo_bi=? AND grantee_bi=?",
            repo_bi, grantee_bi)
        return bool(row)
    except Exception:
        return False


async def verify_share_view_token(env, viewer, owner, repo, ts, sig):
    # Read gate for a private repo shared with a DIFFERENT account (issue #9). The
    # grantee signs with their OWN key — the owner never hands out its key — and
    # access is granted only while the owner keeps an active repo_shares row for
    # them. Distinct canonical prefix so an owner forkmesh-view-v1 token, a host
    # token, or a catalog-listing token can never be replayed here, and vice versa.
    if not viewer or not owner or not repo or not sig or not _ts_ok(ts):
        return False
    if viewer == owner:
        return False  # the owner authenticates via verify_view_token, not here
    pubkey = await _owner_pubkey(env, viewer)
    if not pubkey:
        return False
    canonical = ("forkmesh-share-view-v1\n" + viewer + "\n" + owner + "\n" +
                 repo + "\n" + str(ts)).encode()
    if not await ed25519_verify(pubkey, sig, canonical):
        return False
    return await _repo_shared_with(env, owner, repo, viewer)


async def _repo_is_private(env, owner, repo):
    # Anonymous serving is permitted only by an explicit public catalog row.
    # Missing/malformed records and database failures fail closed. This makes a
    # private repository indistinguishable from an unpublished repository to
    # unauthenticated callers and prevents an outage from becoming a data leak.
    try:
        await ensure_schema(env)
        key_bi = await blind_index(env, owner + "/" + repo)
        row = await d1_first(
            env,
            "SELECT is_private, data FROM repositories WHERE key_bi=?",
            key_bi,
        )
        if not row:
            hosted_resolver = globals().get(
                "_hosted_repository_import_route")
            hosted_route = (
                await hosted_resolver(env, owner, repo)
                if callable(hosted_resolver) else None)
            if hosted_route and tuple(hosted_route) != (owner, repo):
                return await _repo_is_private(
                    env, hosted_route[0], hosted_route[1])
            return True
        if int(row.get("is_private", 1) or 0) != 0:
            return True
        # Migration 0011 historically defaulted existing rows to public.
        # Validate that the signed encrypted record itself explicitly says
        # public before serving; an old row with missing/garbled visibility is
        # hidden until its owner republishes it under the v2 catalog contract.
        decryptor = globals().get("decrypt_row")
        if callable(decryptor):
            record = await decryptor(env, row.get("data"))
            return not record or record.get("visibility") != "public"
        # Isolated compatibility harnesses may omit decrypt_row. Production
        # always has it, so this fallback cannot reopen the deployed boundary.
        return False
    except Exception:
        return True


async def _repository_access_context(
        env, request, owner, repo, viewer=""):
    """Resolve a repository only after applying its normal read boundary.

    Public records must be explicitly public in both the plaintext routing flag
    and the encrypted catalog record. Private/malformed records are gated by
    blind-index owner/share checks before decryption. Missing and unauthorized
    callers both receive ``None`` so named control endpoints cannot become
    repository-existence or decryption oracles.
    """
    try:
        await ensure_schema(env)
        owner = safe_segment(owner)
        repo = safe_segment(repo)
        if not owner or not repo:
            return None
        repo_bi = await blind_index(env, owner + "/" + repo)
        row = await d1_first(
            env,
            "SELECT owner_bi, is_private, data FROM repositories "
            "WHERE key_bi=?",
            repo_bi,
        )
        if not row:
            return None
        plaintext_value = row.get("is_private")
        try:
            plaintext_private = (
                plaintext_value is None
                or str(plaintext_value).strip() == ""
                or int(plaintext_value) != 0
            )
        except (TypeError, ValueError):
            plaintext_private = True

        actor = clean_string(viewer, MAX_NODE_NAME).strip().lower()
        if not actor:
            actor = await _authed_account_name(env, request)
        authorized = False

        async def authorize_private():
            if actor and (
                await _account_owns_node(env, actor, owner)
                or await _repo_shared_with(env, owner, repo, actor)
            ):
                return True
            return await _basic_auth_view_ok(env, owner, repo, request)

        # owner_bi is a non-reversible blind index. Check it before decrypting a
        # plaintext-private row so a corrupt/mismatched row remains invisible.
        if plaintext_private:
            expected_owner_bi = await blind_index(env, owner)
            if str(row.get("owner_bi") or "") != str(expected_owner_bi):
                return None
            authorized = await authorize_private()
            if not authorized:
                return None

        record = await decrypt_row(env, row.get("data"))
        if not _catalog_record_matches_identity(record, owner, repo):
            return None
        signed_public = record.get("visibility") == "public"
        explicit_public = signed_public and not plaintext_private
        if not explicit_public:
            if not authorized:
                authorized = await authorize_private()
            if not authorized:
                return None
        return {
            "repoBi": repo_bi,
            "visibility": "public" if explicit_public else "private",
            "record": record,
            "viewer": actor,
        }
    except Exception:
        return None


async def _basic_auth_view_ok(env, owner, repo, request):
    # Git smart-HTTP carries the view token in HTTP Basic auth (password=
    # "<ts>.<sig>"), which git supplies from the clone URL or a credential helper.
    # The username selects whose key signed the token: the owner itself
    # (forkmesh-view-v1) or a collaborator the repo was shared with, who signs
    # with their OWN key (forkmesh-share-view-v1, issue #9).
    header = request.headers.get("authorization") or ""
    if not header.lower().startswith("basic "):
        return False
    try:
        decoded = base64.b64decode(header[6:].strip()).decode("utf-8", "replace")
    except Exception:
        return False
    username, _, password = decoded.partition(":")
    ts, _, sig = password.partition(".")
    if not ts or not sig:
        return False
    if username and username != owner:
        return await verify_share_view_token(env, username, owner, repo, ts, sig)
    return await verify_view_token(env, owner, repo, ts, sig)


def _basic_auth_challenge():
    return Response(
        "Authentication required.",
        status=401,
        headers={"WWW-Authenticate": 'Basic realm="forkmesh"'},
    )


async def _save_account(env, name_bi, rec, email_bi=None, ip_bi=None):
    # Persist the encrypted record into the users/nodes tables; pass email_bi to
    # (re)index for email login and ip_bi to (re)index the signup IP for
    # duplicate detection. Both are only written when supplied, so a caller that
    # doesn't have them in hand never clobbers a
    # value set at finalize. is_admin is never written here, so a value set
    # directly in the DB survives ordinary account updates.
    await _mirror_account_identity_tables(
        env, name_bi, rec, email_bi=email_bi, ip_bi=ip_bi)


async def _save_account_full(env, name_bi, rec, email_bi=None, ip_bi=None,
                             is_admin=0):
    await _mirror_account_identity_tables(
        env, name_bi, rec, email_bi=email_bi, ip_bi=ip_bi,
        is_admin=is_admin)


async def _move_repo_shares(env, old_repo_bi, new_repo_bi, new_owner, repo):
    rows = await d1_all(
        env, "SELECT grantee_bi, data, ts FROM repo_shares WHERE repo_bi=?",
        old_repo_bi)
    for row in rows:
        rec = await decrypt_row(env, row.get("data", "")) or {}
        rec["owner"] = new_owner
        rec["repo"] = repo
        enc = await encrypt_row(env, rec)
        await d1_run(
            env,
            """INSERT OR REPLACE INTO repo_shares
               (repo_bi, grantee_bi, data, ts) VALUES (?,?,?,?)""",
            new_repo_bi, row.get("grantee_bi"), enc, row.get("ts", 0))
    await d1_run(env, "DELETE FROM repo_shares WHERE repo_bi=?", old_repo_bi)


async def _move_bounties_namespace(env, old_owner, new_owner, repo,
                                   apply_changes=True):
    rows = await d1_all(env, "SELECT bounty_bi, data FROM issue_bounty")
    moves = []
    for row in rows:
        rec = await decrypt_row(env, row.get("data", "")) or {}
        if (rec.get("owner") != old_owner or rec.get("repo") != repo):
            continue
        # Namespace migration re-encrypts the whole record. Refuse to do that
        # while a historical escrow key is still present; the offline custody
        # migration must export, reconcile, and scrub it first.
        if rec.get("secret") or not rec.get("legacy_custody_migrated_at"):
            return "legacy_custody_migration_required"
        try:
            number = int(rec.get("number", 0))
        except (TypeError, ValueError):
            number = 0
        if number <= 0:
            continue
        new_bi = await _bounty_bi(env, new_owner, repo, number,
                                  rec.get("kind", ""))
        old_bi = row.get("bounty_bi")
        if new_bi != old_bi:
            existing = await d1_first(
                env, "SELECT bounty_bi FROM issue_bounty WHERE bounty_bi=?",
                new_bi)
            if existing:
                return "repo_namespace_conflict"
        moves.append((old_bi, new_bi, rec))
    if not apply_changes:
        return ""
    for old_bi, new_bi, rec in moves:
        rec["owner"] = new_owner
        rec["repo"] = repo
        enc = await encrypt_row(env, rec)
        await d1_run(
            env,
            """INSERT INTO issue_bounty (bounty_bi, data) VALUES (?,?)
               ON CONFLICT(bounty_bi) DO UPDATE SET data=excluded.data""",
            new_bi, enc)
        if new_bi != old_bi:
            await d1_run(
                env, "DELETE FROM issue_bounty WHERE bounty_bi=?", old_bi)
    return ""


async def _move_chat_history_namespace(env, old_owner, new_owner, repo):
    old_prefix = "repo:" + old_owner + "/" + repo + ":room:"
    new_prefix = "repo:" + new_owner + "/" + repo + ":room:"
    rows = await d1_all(
        env,
        "SELECT room_key, msg_id, ts, body FROM chat_history WHERE room_key LIKE ?",
        old_prefix + "%")
    for row in rows:
        old_key = row.get("room_key", "")
        new_key = new_prefix + old_key[len(old_prefix):]
        await d1_run(
            env,
            """INSERT OR REPLACE INTO chat_history
               (room_key, msg_id, ts, body) VALUES (?,?,?,?)""",
            new_key, row.get("msg_id"), row.get("ts", 0), row.get("body", ""))
        await d1_run(
            env,
            "DELETE FROM chat_history WHERE room_key=? AND msg_id=?",
            old_key, row.get("msg_id"))


async def _delete_chat_channel_memberships(env, member_bi):
    rows = await d1_all(
        env,
        "SELECT m.channel_id,c.key_version "
        "FROM chat_channel_members m JOIN chat_channels c "
        "ON c.channel_id=m.channel_id WHERE m.member_bi=?",
        member_bi,
    )
    if not rows:
        return
    await d1_run(
        env, "DELETE FROM chat_channel_members WHERE member_bi=?", member_bi)
    for row in rows:
        await _revoke_chat_channel_room(
            env,
            row.get("channel_id", ""),
            int(row.get("key_version") or 1),
        )
        await _revoke_office_channel_room(
            env,
            row.get("channel_id", ""),
            int(row.get("key_version") or 1),
        )


async def _delete_chat_direct_conversations(env, participant_bi):
    rows = await d1_all(
        env,
        "SELECT c.conversation_id,c.key_version "
        "FROM chat_direct_participants p "
        "JOIN chat_direct_conversations c "
        "ON c.conversation_id=p.conversation_id "
        "WHERE p.participant_bi=?",
        participant_bi,
    )
    for row in rows:
        conversation_id = str(row.get("conversation_id") or "")
        key_version = int(row.get("key_version") or 1)
        if not conversation_id:
            continue
        await _revoke_chat_direct_room(
            env, conversation_id, key_version)
        await d1_run(
            env,
            "DELETE FROM chat_direct_participants WHERE conversation_id=?",
            conversation_id,
        )
        await d1_run(
            env,
            "DELETE FROM chat_direct_conversations WHERE conversation_id=?",
            conversation_id,
        )
        await d1_run(
            env,
            "DELETE FROM chat_history WHERE room_key=?",
            "chat-direct:" + conversation_id + ":v" + str(key_version),
        )


async def _move_chat_channel_memberships(
        env, old_member_bi, new_member_bi, new_name):
    if old_member_bi == new_member_bi:
        return
    await _delete_chat_channel_memberships(env, new_member_bi)
    sealed = await encrypt_row(env, {"username": new_name})
    await d1_run(
        env,
        "UPDATE chat_channel_members SET member_bi=?,data=? "
        "WHERE member_bi=?",
        new_member_bi,
        sealed,
        old_member_bi,
    )
    await d1_run(
        env,
        "UPDATE chat_channel_members SET invited_by_bi=? "
        "WHERE invited_by_bi=?",
        new_member_bi,
        old_member_bi,
    )


async def _move_repo_namespace(env, old_owner_bi, old_owner, new_owner_bi,
                               new_owner, apply_changes=True):
    rows = await d1_all(
        env, "SELECT key_bi, data, is_private FROM repositories WHERE owner_bi=?",
        old_owner_bi)
    moves = []
    for row in rows:
        rec = await decrypt_row(env, row.get("data", "")) or {}
        if (rec.get("owner", "").lower() != old_owner.lower()):
            continue
        repo = clean_string(rec.get("name", ""), MAX_REPO_SEGMENT)
        if not repo:
            continue
        old_repo_bi = row.get("key_bi")
        new_repo_bi = await blind_index(env, new_owner + "/" + repo)
        if new_repo_bi != old_repo_bi:
            existing = await d1_first(
                env, "SELECT key_bi FROM repositories WHERE key_bi=?",
                new_repo_bi)
            if existing:
                return "repo_namespace_conflict"
        bounty_error = await _move_bounties_namespace(
            env, old_owner, new_owner, repo, apply_changes=False)
        if bounty_error:
            return bounty_error
        moves.append((row, rec, repo, old_repo_bi, new_repo_bi))
    if not apply_changes:
        return ""

    for row, rec, repo, old_repo_bi, new_repo_bi in moves:
        rec["owner"] = new_owner
        enc = await encrypt_row(env, rec)
        await d1_run(
            env,
            """INSERT INTO repositories (key_bi, owner_bi, data, is_private)
               VALUES (?,?,?,?)
               ON CONFLICT(key_bi) DO UPDATE SET
                 owner_bi=excluded.owner_bi, data=excluded.data,
                 is_private=excluded.is_private""",
            new_repo_bi, new_owner_bi, enc, int(row.get("is_private") or 0))
        await _contribution_move_repo_namespace(
            env,
            old_repo_bi,
            new_repo_bi,
            old_owner_bi,
            new_owner_bi,
            new_owner,
            repo,
            rec,
        )
        await _move_repo_shares(env, old_repo_bi, new_repo_bi, new_owner, repo)
        # Carry the attested pin history to the new namespace so mirrors of a
        # renamed source keep clearing the integrity gate without waiting for
        # fresh publishes to rebuild it.
        try:
            await d1_run(
                env, "UPDATE repo_state_history SET key_bi=? WHERE key_bi=?",
                new_repo_bi, old_repo_bi)
        except Exception:
            pass
        await d1_run(
            env, "UPDATE issue_inbox SET repo_bi=? WHERE repo_bi=?",
            new_repo_bi, old_repo_bi)
        await d1_run(
            env, "UPDATE pull_inbox SET repo_bi=? WHERE repo_bi=?",
            new_repo_bi, old_repo_bi)
        await d1_run(
            env, "UPDATE commit_inbox SET repo_bi=? WHERE repo_bi=?",
            new_repo_bi, old_repo_bi)
        await d1_run(
            env, "UPDATE discussion_inbox SET repo_bi=? WHERE repo_bi=?",
            new_repo_bi, old_repo_bi)
        await d1_run(
            env, "UPDATE host_presence SET repo_bi=? WHERE repo_bi=?",
            new_repo_bi, old_repo_bi)
        await d1_run(
            env, "UPDATE clone_rr SET repo_bi=? WHERE repo_bi=?",
            new_repo_bi, old_repo_bi)
        await d1_run(
            env, "UPDATE repo_first_hosted SET repo_bi=? WHERE repo_bi=?",
            new_repo_bi, old_repo_bi)
        await _move_bounties_namespace(env, old_owner, new_owner, repo)
        await _move_chat_history_namespace(env, old_owner, new_owner, repo)
        await d1_run(
            env,
            "UPDATE funds_received SET key=?, name=? WHERE scope='project' AND key=?",
            new_owner + "/" + repo, new_owner + "/" + repo,
            old_owner + "/" + repo)
        if new_repo_bi != old_repo_bi:
            await d1_run(
                env, "DELETE FROM repositories WHERE key_bi=?", old_repo_bi)
    return ""


async def _rename_account_namespace(env, name_bi, rec, new_name):
    old_name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    new_name = clean_string(new_name, MAX_NODE_NAME).lower()
    if not valid_node_name(new_name):
        return name_bi, rec, "invalid_node_name"
    if new_name == old_name:
        return name_bi, rec, "node_name_unchanged"

    new_name_bi, target = await _account_row(env, new_name)
    if target and (target.get("status") == "active" or
                   target.get("donation_confirmed") or
                   _donation_in_progress(target)):
        return name_bi, rec, "node_name_taken"

    account_row = await d1_first(
        env, "SELECT data, email_bi, ip_bi, is_admin FROM users WHERE user_bi=?",
        name_bi)
    if not account_row:
        return name_bi, rec, "invalid_credentials"

    move_error = await _move_repo_namespace(
        env, name_bi, old_name, new_name_bi, new_name, apply_changes=False)
    if move_error:
        return name_bi, rec, move_error

    next_rec = dict(rec)
    next_rec["name"] = new_name
    await _save_account_full(
        env, new_name_bi, next_rec,
        email_bi=account_row.get("email_bi"),
        ip_bi=account_row.get("ip_bi"),
        is_admin=account_row.get("is_admin", 0),
    )
    move_error = await _move_repo_namespace(
        env, name_bi, old_name, new_name_bi, new_name)
    if move_error:
        return name_bi, rec, move_error
    await _contribution_retarget_linked_nodes(
        env, name_bi, old_name, new_name_bi, new_name)
    await _move_chat_channel_memberships(
        env, name_bi, new_name_bi, new_name)
    # A username move changes the participant blind index and pair identity.
    # Close old DM rooms instead of leaving orphaned membership or silently
    # merging conversations under a different account identity.
    await _delete_chat_direct_conversations(env, name_bi)
    await d1_run(
        env, "UPDATE account_presence SET name_bi=? WHERE name_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env, "UPDATE pending_verifications SET name_bi=? WHERE name_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env, "UPDATE notifications SET recipient_bi=? WHERE recipient_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env, "UPDATE profile_follows SET follower_bi=?, follower_name=? WHERE follower_bi=?",
        new_name_bi, new_name, name_bi)
    await d1_run(
        env, "UPDATE profile_follows SET target_bi=?, target_name=? WHERE target_bi=?",
        new_name_bi, new_name, name_bi)
    await d1_run(
        env, "UPDATE catalog_rate SET owner_bi=? WHERE owner_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env,
        "UPDATE profile_contribution_days SET subject_user_bi=? "
        "WHERE subject_user_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env,
        "UPDATE profile_contribution_languages SET owner_user_bi=? "
        "WHERE owner_user_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env,
        "UPDATE profile_contribution_projects SET owner_user_bi=? "
        "WHERE owner_user_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env, "UPDATE account_devices SET account_bi=? WHERE account_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env, "UPDATE account_ssh_keys SET account_bi=? WHERE account_bi=?",
        new_name_bi, name_bi)
    await d1_run(
        env, "UPDATE account_sessions SET account_bi=? WHERE account_bi=?",
        new_name_bi, name_bi)
    await d1_run(env, "DELETE FROM users WHERE user_bi=?", name_bi)
    await d1_run(env, "DELETE FROM nodes WHERE node_bi=?", name_bi)
    await purge_catalog_related_caches()
    return new_name_bi, next_rec, ""


async def _delete_bounties_namespace(env, owner, repo):
    rows = await d1_all(env, "SELECT bounty_bi, data FROM issue_bounty")
    for row in rows:
        rec = await decrypt_row(env, row.get("data", "")) or {}
        if rec.get("owner") == owner and rec.get("repo") == repo:
            await d1_run(
                env, "DELETE FROM issue_bounty WHERE bounty_bi=?",
                row.get("bounty_bi"))


async def _delete_repo_scoped_state(env, repo_bi):
    await d1_run(
        env, "DELETE FROM profile_contribution_days WHERE source_repo_bi=?",
        repo_bi)
    await d1_run(
        env, "DELETE FROM profile_contribution_languages WHERE source_repo_bi=?",
        repo_bi)
    await d1_run(
        env, "DELETE FROM profile_contribution_receipts WHERE source_repo_bi=?",
        repo_bi)
    await d1_run(
        env, "DELETE FROM profile_contribution_projects WHERE source_repo_bi=?",
        repo_bi)
    await d1_run(env, "DELETE FROM repo_shares WHERE repo_bi=?", repo_bi)
    await d1_run(env, "DELETE FROM issue_inbox WHERE repo_bi=?", repo_bi)
    await d1_run(env, "DELETE FROM pull_inbox WHERE repo_bi=?", repo_bi)
    await d1_run(env, "DELETE FROM commit_inbox WHERE repo_bi=?", repo_bi)
    await d1_run(env, "DELETE FROM discussion_inbox WHERE repo_bi=?", repo_bi)
    await d1_run(env, "DELETE FROM host_presence WHERE repo_bi=?", repo_bi)
    await d1_run(env, "DELETE FROM clone_rr WHERE repo_bi=?", repo_bi)
    await d1_run(env, "DELETE FROM repo_first_hosted WHERE repo_bi=?", repo_bi)
    await d1_run(env, "DELETE FROM repo_agents WHERE repo_bi=?", repo_bi)
    await d1_run(
        env, "DELETE FROM repo_security_scans WHERE repo_bi=?", repo_bi)
    await d1_run(
        env, "DELETE FROM repo_security_scan_reviews WHERE repo_bi=?", repo_bi)
    # Invalidate the per-isolate agent-snapshot digest: a re-published repo
    # gets the same deterministic repo_bi back, and a memoized digest would
    # otherwise make the desktop's identical re-push a silent no-op forever
    # (empty repo_agents while the desktop believes its sessions published).
    _AGENT_PUSH_DIGESTS.pop(repo_bi, None)
    await d1_run(env, "DELETE FROM agent_prompts WHERE repo_bi=?", repo_bi)


async def _delete_repo_namespace(env, owner_bi, owner):
    rows = await d1_all(
        env, "SELECT key_bi, data FROM repositories WHERE owner_bi=?",
        owner_bi)
    owner = clean_string(owner, MAX_NODE_NAME).lower()
    for row in rows:
        repo_bi = row.get("key_bi")
        rec = await decrypt_row(env, row.get("data", "")) or {}
        repo = clean_string(rec.get("name", ""), MAX_REPO_SEGMENT)
        if repo_bi:
            await _delete_repo_scoped_state(env, repo_bi)
            await d1_run(env, "DELETE FROM repositories WHERE key_bi=?", repo_bi)
        if owner and repo:
            await _delete_bounties_namespace(env, owner, repo)
            await d1_run(
                env, "DELETE FROM chat_history WHERE room_key LIKE ?",
                "repo:" + owner + "/" + repo + ":room:%")
            await d1_run(
                env,
                "DELETE FROM funds_received WHERE scope='project' AND key=?",
                owner + "/" + repo)
    await d1_run(env, "DELETE FROM catalog_rate WHERE owner_bi=?", owner_bi)
    await purge_catalog_related_caches()


async def _delete_account_namespace(env, name_bi, rec):
    name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    email = clean_string(rec.get("email", ""), 254).strip().lower()
    await _contribution_retarget_linked_nodes(
        env, name_bi, name, None, "")
    await _delete_repo_namespace(env, name_bi, name)
    await d1_run(env, "DELETE FROM repo_shares WHERE grantee_bi=?", name_bi)
    await d1_run(env, "DELETE FROM account_presence WHERE name_bi=?", name_bi)
    await d1_run(env, "DELETE FROM pending_verifications WHERE name_bi=?", name_bi)
    await d1_run(env, "DELETE FROM notifications WHERE recipient_bi=?", name_bi)
    await d1_run(env, "DELETE FROM profile_follows WHERE follower_bi=? OR target_bi=?", name_bi, name_bi)
    await d1_run(env, "DELETE FROM login_attempts WHERE id_bi=?", name_bi)
    await d1_run(
        env,
        "DELETE FROM profile_contribution_days WHERE subject_user_bi=? OR "
        "source_repo_bi IN (SELECT source_repo_bi FROM "
        "profile_contribution_projects WHERE owner_user_bi=?)",
        name_bi, name_bi)
    await d1_run(
        env,
        "DELETE FROM profile_contribution_languages WHERE owner_user_bi=? OR "
        "source_repo_bi IN (SELECT source_repo_bi FROM "
        "profile_contribution_projects WHERE owner_user_bi=?)",
        name_bi, name_bi)
    await d1_run(
        env,
        "DELETE FROM profile_contribution_receipts WHERE source_repo_bi IN "
        "(SELECT source_repo_bi FROM profile_contribution_projects "
        "WHERE owner_user_bi=?)",
        name_bi)
    await d1_run(
        env,
        "DELETE FROM profile_contribution_projects WHERE owner_user_bi=?",
        name_bi)
    await d1_run(
        env, "DELETE FROM account_devices WHERE account_bi=?", name_bi)
    await d1_run(
        env, "DELETE FROM account_ssh_keys WHERE account_bi=?", name_bi)
    await d1_run(
        env, "DELETE FROM account_sessions WHERE account_bi=?", name_bi)
    await _delete_chat_channel_memberships(env, name_bi)
    await _delete_chat_direct_conversations(env, name_bi)
    if email:
        email_bi = await blind_index(env, email)
        await d1_run(env, "DELETE FROM login_attempts WHERE id_bi=?", email_bi)
    await d1_run(env, "DELETE FROM users WHERE user_bi=?", name_bi)
    await d1_run(env, "DELETE FROM nodes WHERE node_bi=?", name_bi)


def _owned_nodes(rec):
    nodes = rec.get("nodes")
    if not isinstance(nodes, list):
        return []
    return [n for n in nodes if isinstance(n, str) and n]


async def _account_owns_node(env, actor, node_name):
    """True when the logged-in account `actor` may act AS the repo owner
    `node_name`. A repo's owner is a NODE account, but the human logs in with
    the linked USER account (adhoc #53 claim/link), whose name differs — so an
    owner-gated web action must resolve that link, not string-compare names.

    Ownership is recorded on both sides by _link_node_to_user: the node record
    carries `owner` = <user name>, and the user record's `nodes` list carries
    the node name. Either side is accepted (tolerate one being stale)."""
    actor = str(actor or "").strip().lower()
    node_name = str(node_name or "").strip().lower()
    if not actor or not node_name:
        return False
    if actor == node_name:
        return True
    _, node_rec = await _account_row(env, node_name)
    if node_rec and str(node_rec.get("owner", "")).strip().lower() == actor:
        return True
    _, actor_rec = await _account_row(env, actor)
    if actor_rec and node_name in {
            n.strip().lower() for n in _owned_nodes(actor_rec)}:
        return True
    return False


def _clean_profile_timezone(raw):
    value = clean_string(raw, MAX_PROFILE_TIMEZONE).strip()
    if not value:
        return ""
    if not re.match(r"^[A-Za-z0-9_./+-]{1,80}$", value):
        return ""
    return value


async def _profile_catalog_owner_names(env, name):
    name = clean_string(name, MAX_NODE_NAME).lower()
    names = [name] if valid_node_name(name) else []
    _, rec = await _account_row(env, name) if name else ("", None)
    if rec:
        for node in _owned_nodes(rec):
            clean = clean_string(node, MAX_NODE_NAME).lower()
            if valid_node_name(clean) and clean not in names:
                names.append(clean)
    return names


async def _account_mirror_count(env, name):
    total = 0
    for owner in await _profile_catalog_owner_names(env, name):
        owner_bi = await blind_index(env, owner)
        rows = await d1_all(
            env,
            "SELECT data FROM repositories "
            "WHERE owner_bi=? AND is_private=0",
            owner_bi,
        )
        for row in rows or []:
            record = await decrypt_row(env, row.get("data"))
            if record and record.get("visibility") == "public":
                total += 1
    return total


async def _account_social_counts(env, name, viewer_name=""):
    name = clean_string(name, MAX_NODE_NAME).lower()
    if not valid_node_name(name):
        return {
            "followers": 0,
            "following": 0,
            "mirrorCount": 0,
            "isFollowing": False,
        }
    target_bi = await blind_index(env, name)
    followers_row = await d1_first(
        env, "SELECT COUNT(*) AS n FROM profile_follows WHERE target_bi=?",
        target_bi)
    following_row = await d1_first(
        env, "SELECT COUNT(*) AS n FROM profile_follows WHERE follower_bi=?",
        target_bi)
    is_following = False
    viewer = clean_string(viewer_name, MAX_NODE_NAME).lower()
    if valid_node_name(viewer) and viewer != name:
        viewer_bi = await blind_index(env, viewer)
        row = await d1_first(
            env,
            "SELECT 1 AS yes FROM profile_follows WHERE follower_bi=? AND target_bi=?",
            viewer_bi, target_bi)
        is_following = bool(row)
    return {
        "followers": int((followers_row or {}).get("n", 0) or 0),
        "following": int((following_row or {}).get("n", 0) or 0),
        "mirrorCount": await _account_mirror_count(env, name),
        "isFollowing": is_following,
    }


def _profile_txt_value(name):
    return PROFILE_TXT_PREFIX + clean_string(name, MAX_NODE_NAME).lower()


def _profile_link_domain(url):
    parsed = urlparse(url)
    host = (parsed.hostname or "").strip().lower().rstrip(".")
    return host if DOMAIN_NAME_RE.match(host) else ""


def _clean_profile_url(raw):
    value = clean_string(raw, MAX_PROFILE_LINK_URL).strip()
    if not value:
        return ""
    parsed = urlparse(value)
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        return ""
    host = (parsed.hostname or "").strip().lower().rstrip(".")
    if not DOMAIN_NAME_RE.match(host):
        return ""
    return parsed.geturl()


def _clean_mastodon_handle(raw):
    value = clean_string(raw, 120).strip()
    if not value:
        return ""
    if not MASTODON_HANDLE_RE.match(value):
        return ""
    if not value.startswith("@"):
        value = "@" + value
    return value


def _mastodon_url(handle):
    if not handle:
        return ""
    clean = handle[1:] if handle.startswith("@") else handle
    if "@" not in clean:
        return ""
    user, domain = clean.split("@", 1)
    if not user or not DOMAIN_NAME_RE.match(domain):
        return ""
    return "https://" + domain + "/@" + quote(user)


def _profile_links_public(rec):
    links = rec.get("profile_links")
    if not isinstance(links, list):
        return []
    out = []
    for link in links[:MAX_PROFILE_LINKS]:
        if not isinstance(link, dict):
            continue
        url = _clean_profile_url(link.get("url", ""))
        if not url:
            continue
        domain = _profile_link_domain(url)
        out.append({
            "label": clean_string(link.get("label", ""), MAX_PROFILE_LINK_LABEL),
            "url": url,
            "domain": domain,
            "verified": bool(link.get("verified")),
            "verifiedAt": int(link.get("verified_at", 0) or 0),
            "txtName": domain,
            "txtValue": _profile_txt_value(rec.get("name", "")),
        })
    return out


def _account_profile_fields(rec):
    bio = clean_string(rec.get("profile_bio", ""), MAX_PROFILE_BIO).strip()
    about = clean_string(
        rec.get("profile_about", "") or rec.get("profile_readme", ""),
        MAX_PROFILE_ABOUT,
    )
    readme = clean_string(rec.get("profile_readme", ""), MAX_PROFILE_README)
    location = clean_string(
        rec.get("profile_location", ""), MAX_PROFILE_LOCATION).strip()
    timezone = _clean_profile_timezone(rec.get("profile_timezone", ""))
    mastodon = _clean_mastodon_handle(rec.get("mastodon", ""))
    return {
        "profileBio": bio,
        "profileAbout": about,
        "profileReadme": readme,
        "profileLocation": location,
        "profileTimezone": timezone,
        "profilePrivate": bool(rec.get("profile_private")),
        "followersPublic": bool(rec.get("profile_followers_public")),
        "mastodon": mastodon,
        "mastodonUrl": _mastodon_url(mastodon),
        "profileLinks": _profile_links_public(rec),
    }


async def _dns_txt_has_profile_token(domain, token):
    domain = clean_string(domain, 253).strip().lower().rstrip(".")
    if not DOMAIN_NAME_RE.match(domain) or not token:
        return False
    from js import fetch as js_fetch
    url = "https://cloudflare-dns.com/dns-query?name=" + quote(domain) + "&type=TXT"
    try:
        resp = await js_fetch(url, to_js({
            "method": "GET",
            "headers": {"accept": "application/dns-json"},
        }))
        if int(getattr(resp, "status", 0)) != 200:
            return False
        data = json.loads(await resp.text())
    except Exception:
        return False
    answers = data.get("Answer") if isinstance(data, dict) else None
    if not isinstance(answers, list):
        return False
    wanted = token.lower()
    for answer in answers:
        if not isinstance(answer, dict):
            continue
        text = str(answer.get("data", "") or "").replace('" "', "").replace('"', "")
        if wanted in text.lower():
            return True
    return False


async def _clean_profile_links(env, rec, raw_links):
    if raw_links is None:
        return None, None
    if not isinstance(raw_links, list):
        return None, "bad_profile_links"
    prev = {}
    for link in rec.get("profile_links") or []:
        if isinstance(link, dict) and link.get("url"):
            prev[link.get("url")] = link
    token = _profile_txt_value(rec.get("name", ""))
    out = []
    seen = set()
    for item in raw_links[:MAX_PROFILE_LINKS]:
        if not isinstance(item, dict):
            return None, "bad_profile_links"
        url = _clean_profile_url(item.get("url", ""))
        label = clean_string(item.get("label", ""), MAX_PROFILE_LINK_LABEL).strip()
        if not url and not label:
            continue
        if not url:
            return None, "bad_profile_link_url"
        if url in seen:
            continue
        seen.add(url)
        domain = _profile_link_domain(url)
        prior = prev.get(url) or {}
        verified = bool(prior.get("verified"))
        verified_at = int(prior.get("verified_at", 0) or 0)
        if not verified and await _dns_txt_has_profile_token(domain, token):
            verified = True
            verified_at = int(Date.now())
        out.append({
            "label": label,
            "url": url,
            "domain": domain,
            "verified": verified,
            "verified_at": verified_at,
        })
    return out, None


async def _account_public_payload(
        env, rec, session_token=None, session_device_label="",
        session_client_ip=""):
    name = rec.get("name", "")
    solana = (rec.get("solana") or "").strip()
    has_payout = bool(solana and SOLANA_RE.match(solana))
    is_admin = await _is_admin(env, name)
    social = await _account_social_counts(env, name)
    payload = {
        "ok": True,
        "nodeName": name,
        "email": rec.get("email", ""),
        "status": rec.get("status", "active"),
        "pubkey": rec.get("pubkey", ""),
        "emailVerified": bool(rec.get("email_verified")),
        "isAdmin": is_admin,
        "solana": solana if has_payout else "",
        "hasPayoutAddress": has_payout,
        "payoutCustody": "external-self-custodial-public-address",
        "payoutNotice": (
            "ForkMesh stores only the optional public payout address. Wallet "
            "keys, transaction approval, and user-owned funds remain with the "
            "external wallet owner; reward selection and payment are not "
            "guaranteed."
        ),
        "sessionToken": (
            session_token
            if session_token is not None
            else await _account_session_token(
                env, name, session_device_label, session_client_ip)
        ),
        "avatarPng": rec.get("avatar_png", ""),
        "avatarUpdatedAt": rec.get("avatar_updated_at", 0),
        "kind": _account_kind(rec),
        "owner": rec.get("owner", ""),
        "nodes": _owned_nodes(rec),
        "emailNotifications": rec.get("email_notifications") is not False,
        "notificationPreferences": notification_email_preferences(rec),
        "social": social,
    }
    payload.update(social)
    payload.update(_account_profile_fields(rec))
    if is_admin:
        admin_path = _admin_path(env)
        if admin_path:
            payload["adminUrl"] = "/" + admin_path + "?admin=" + quote(name)
    return payload


def _world_public_total_active_ms(value):
    """Return a coarse, bounded public duration without activity timestamps."""
    try:
        total = int(value or 0)
    except (TypeError, ValueError):
        total = 0
    total = max(0, min(WORLD_USER_ACTIVITY_MAX_TOTAL_MS, total))
    return (
        total // WORLD_USER_ACTIVITY_PUBLIC_BUCKET_MS
    ) * WORLD_USER_ACTIVITY_PUBLIC_BUCKET_MS


def _account_world_client_fields(rec):
    """The coarse country/browser/OS the account last chose to publish.

    Stored by /api/world/client so an away member's campfire bench figure —
    which has no live presence frame to read — still shows the same three
    coarse values their avatar wore while they were here.
    """
    return world_protocol.clean_client_profile(
        (rec or {}).get("world_country", ""),
        (rec or {}).get("world_browser", ""),
        (rec or {}).get("world_os", ""),
    )


def _account_chat_user_payload(rec, total_active_ms=0, activity_bucket=""):
    name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    return {
        "name": name,
        "status": rec.get("status", "active"),
        "avatarPng": rec.get("avatar_png", ""),
        "avatarUpdatedAt": rec.get("avatar_updated_at", 0),
        "createdAt": rec.get("created_at", 0),
        "kind": "user",
        "nodes": _owned_nodes(rec),
        # Aggregate-only and rounded down to whole minutes. The public
        # directory deliberately exposes neither a last-seen timestamp nor the
        # current activity interval used by an authenticated World tab.
        "totalActiveMs": _world_public_total_active_ms(total_active_ms),
        # The bench figure's chest activity light: a seven-step recency
        # bucket the caller already derived from the raw touch timestamp, so
        # this function never sees (or could leak) that timestamp itself.
        "activityBucket": activity_bucket,
        **_account_world_client_fields(rec),
    }


USERS_DIRECTORY_CACHE_KEY = "https://forkmesh.internal/api/accounts/users"
USERS_DIRECTORY_TTL = 30
# The World campfire paints its member total straight from this body, so a
# browser-held copy leaves the fire showing an old count until a hard refresh.
# The edge copy still collapses the origin decrypt work; the bytes handed to
# the client are never stored, so a plain reload always repaints the real
# roster. Every caller already throttles its own polling well past the edge
# TTL, so dropping the browser copy adds no extra polling.
USERS_DIRECTORY_CLIENT_CACHE_CONTROL = "no-store, max-age=0, must-revalidate"


async def _users_directory_cache_get():
    # Return the edge-held roster as a fresh no-store response, the same
    # rebuild git_advert_cache_get does: the stored copy carries a public
    # max-age so the Cache API will keep it, which must not reach the browser.
    try:
        hit = await js_caches.default.match(USERS_DIRECTORY_CACHE_KEY)
    except Exception:
        hit = None
    if hit is None:
        return None
    return JsResponse.new(hit.body, to_js({
        "status": 200,
        "headers": {
            "content-type": "application/json; charset=utf-8",
            "cache-control": USERS_DIRECTORY_CLIENT_CACHE_CONTROL,
        },
    }))


async def _account_users_directory(env, request):
    # Public chat roster directory: user profiles only, with no email, password,
    # device, admin, or signature material. Live node presence is still carried
    # by the encrypted room roster; this endpoint fills in offline users.
    # Edge-cached: the chat page polls this to surface new signups, and each
    # origin hit decrypts up to 1000 rows — collapse the polls per colo per TTL.
    # A signup deletes the cached copy so the new account shows without waiting
    # out the TTL. Edge-only: the response is no-store, so no browser ever
    # holds a roster of its own (adhoc #434).
    del request
    cached = await _users_directory_cache_get()
    if cached is not None:
        return cached
    out = []
    seen = set()
    rows = await d1_all(
        env,
        "SELECT u.data,u.user_bi,a.total_active_ms FROM users u "
        "LEFT JOIN world_user_activity a ON a.account_bi=u.user_bi "
        "ORDER BY u.username COLLATE NOCASE LIMIT ?",
        1000,
    )
    # A bucket label only, joined in from its own query so this function
    # body never handles the raw touch timestamp behind it.
    activity_buckets = await _world_user_activity_buckets(env)
    for row in rows or []:
        rec = await decrypt_row(env, row.get("data", ""))
        if (not rec or _account_kind(rec) != "user"
                or rec.get("status") != "active"
                or rec.get("profile_private")):
            continue
        name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
        if not name or name in seen:
            continue
        seen.add(name)
        out.append(_account_chat_user_payload(
            rec, row.get("total_active_ms", 0),
            activity_buckets.get(row.get("user_bi"), "")))

    # The campfire seats members in this same array order, one bench per
    # account for the session — so this is sorted by join date (oldest
    # first) rather than left in the query's alphabetical fetch order.
    out.sort(key=lambda user: user.get("createdAt", 0))

    payload = {"ok": True, "users": out}
    # Two bodies on purpose: the stored one carries the public max-age the
    # Cache API needs to keep it, the returned one carries no-store.
    await edge_cache_put(
        USERS_DIRECTORY_CACHE_KEY,
        json_response(payload, cache_seconds=USERS_DIRECTORY_TTL),
    )
    return json_response(
        payload, cache_control=USERS_DIRECTORY_CLIENT_CACHE_CONTROL)


def _donation_expiry_fields(rec, now):
    try:
        created = int(rec.get("donation_created_at") or rec.get("created_at") or now)
    except (TypeError, ValueError):
        created = now
    try:
        expires = int(rec.get("donation_expires_at") or
                      created + DONATION_ADDRESS_TTL_MS)
    except (TypeError, ValueError):
        expires = created + DONATION_ADDRESS_TTL_MS
    try:
        delete_after = int(rec.get("donation_delete_after") or
                           expires + DONATION_ADDRESS_DELETE_GRACE_MS)
    except (TypeError, ValueError):
        delete_after = expires + DONATION_ADDRESS_DELETE_GRACE_MS
    return created, expires, delete_after


def _account_session_secret(env):
    return (str(getattr(env, "ADMIN_PASS", "") or "") + "|" +
            str(getattr(env, "DATA_KEY", "") or "")).encode()


ACCOUNT_SESSION_COOKIE = "forkmesh_account"
ACCOUNT_SESSION_TOKEN_RE = re.compile(
    r"^v2\.([A-Za-z0-9_-]{24,64})\.([A-Za-z0-9_-]{32,96})$")
ACCOUNT_SESSION_TOUCH_MS = 5 * 60 * 1000
ACCOUNT_SESSION_MAX_ACTIVE = 20


def _account_session_token_digest(env, token):
    return hmac.new(
        _account_session_secret(env),
        ("forkmesh-account-session-token-v2\n" + str(token or "")).encode(),
        "sha256",
    ).hexdigest()


async def _account_session_token(env, name, device_label="", client_ip=""):
    """Mint one random, server-revocable session; D1 stores no bearer token."""
    name = clean_string(name or "", MAX_NODE_NAME).lower()
    if not valid_node_name(name):
        return ""
    await ensure_schema(env)
    now = int(Date.now())
    account_bi = await blind_index(env, name)
    session_id = _b64url_encode(_random_bytes(24))
    secret = _b64url_encode(_random_bytes(32))
    token = "v2." + session_id + "." + secret
    expires = now + ADMIN_SESSION_TTL_MS
    await d1_run(
        env,
        "DELETE FROM account_sessions WHERE expires_at<=? OR "
        "(revoked_at>0 AND revoked_at<=?)",
        now,
        now - 24 * 60 * 60 * 1000,
    )
    # Bound stolen-device persistence and table growth. Retain only the newest
    # sessions for this account before adding the next one.
    await d1_run(
        env,
        "DELETE FROM account_sessions WHERE session_id IN ("
        "SELECT session_id FROM account_sessions WHERE account_bi=? "
        "ORDER BY created_at DESC LIMIT -1 OFFSET ?)",
        account_bi,
        ACCOUNT_SESSION_MAX_ACTIVE - 1,
    )
    await d1_run(
        env,
        "INSERT INTO account_sessions "
        "(session_id,account_bi,token_digest,created_at,last_seen_at,"
        "expires_at,revoked_at,device_label,client_ip) "
        "VALUES (?,?,?,?,?,?,0,?,?)",
        session_id,
        account_bi,
        _account_session_token_digest(env, token),
        now,
        now,
        expires,
        clean_string(device_label or "", 80),
        clean_string(client_ip or "", 64),
    )
    return token


def _account_session_cookie(token):
    token = clean_string(token or "", 512).strip()
    return (
        ACCOUNT_SESSION_COOKIE + "=" + token
        + "; Path=/; Max-Age=%d; HttpOnly; Secure; SameSite=Strict"
        % int(ADMIN_SESSION_TTL_MS / 1000)
    )


def _clear_account_session_cookie():
    return (
        ACCOUNT_SESSION_COOKIE
        + "=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Strict"
    )


def _request_same_origin(request):
    try:
        target = urlparse(request.url)
        origin = urlparse(request.headers.get("origin") or "")
    except Exception:
        return False
    target_port = target.port or (443 if target.scheme == "https" else 80)
    origin_port = origin.port or (443 if origin.scheme == "https" else 80)
    return bool(
        origin.scheme == target.scheme
        and origin.hostname == target.hostname
        and origin_port == target_port
    )


def _request_account_session_token(request, payload=None):
    payload = payload if isinstance(payload, dict) else {}
    token = clean_string(payload.get("sessionToken", ""), 512).strip()
    if not token:
        auth = request.headers.get("authorization") or ""
        if auth.lower().startswith("bearer "):
            token = clean_string(auth[7:], 512).strip()
    # Browser localStorage retains only this non-secret marker. Cookie auth is
    # selected explicitly rather than trying to validate it as a bearer.
    if token == "cookie":
        token = ""
    cookie_auth = not token
    if cookie_auth:
        token = clean_string(
            _cookie_value(request, ACCOUNT_SESSION_COOKIE), 512
        ).strip()
    return token, cookie_auth


def _request_account_session_id(request, payload=None):
    """Return the opaque id carried by this request's account-session token.

    Callers must first validate the token through ``_account_session_record``.
    Parsing the already-validated request again avoids a second D1 lookup while
    still binding a short-lived Office ticket to the exact revocable session.
    """
    try:
        token, _cookie_auth = _request_account_session_token(request, payload)
    except Exception:
        return ""
    match = ACCOUNT_SESSION_TOKEN_RE.fullmatch(
        clean_string(token or "", 512).strip())
    return match.group(1) if match else ""


async def _account_session_lookup(env, token, touch=True):
    match = ACCOUNT_SESSION_TOKEN_RE.fullmatch(
        clean_string(token or "", 512).strip())
    if not match:
        return "", None, ""
    session_id = match.group(1)
    row = await d1_first(
        env,
        "SELECT account_bi,token_digest,last_seen_at,expires_at,revoked_at "
        "FROM account_sessions WHERE session_id=?",
        session_id,
    )
    now = int(Date.now())
    if (
        not row
        or int(row.get("revoked_at") or 0)
        or int(row.get("expires_at") or 0) <= now
        or not hmac.compare_digest(
            str(row.get("token_digest") or ""),
            _account_session_token_digest(env, token),
        )
    ):
        return "", None, ""
    account_bi = str(row.get("account_bi") or "")
    account_row = await d1_first(
        env, "SELECT data FROM users WHERE user_bi=?", account_bi)
    rec = await decrypt_row(env, (account_row or {}).get("data", ""))
    if not rec or rec.get("status") != "active" or _account_kind(rec) != "user":
        return "", None, ""
    if (
        touch
        and now - int(row.get("last_seen_at") or 0)
        >= ACCOUNT_SESSION_TOUCH_MS
    ):
        await d1_run(
            env,
            "UPDATE account_sessions SET last_seen_at=? "
            "WHERE session_id=? AND revoked_at=0",
            now,
            session_id,
        )
    return account_bi, rec, session_id


async def _account_session_token_name(env, token):
    _, rec, _ = await _account_session_lookup(env, token)
    return clean_string(
        (rec or {}).get("name", ""), MAX_NODE_NAME).lower()


async def _account_revoke_sessions(env, account_bi, session_id=""):
    now = int(Date.now())
    if session_id:
        await d1_run(
            env,
            "UPDATE account_sessions SET revoked_at=? "
            "WHERE account_bi=? AND session_id=? AND revoked_at=0",
            now,
            account_bi,
            session_id,
        )
    else:
        await d1_run(
            env,
            "UPDATE account_sessions SET revoked_at=? "
            "WHERE account_bi=? AND revoked_at=0",
            now,
            account_bi,
        )


async def _account_session_record(env, request, data=None):
    payload = data if isinstance(data, dict) else {}
    token, cookie_auth = _request_account_session_token(request, payload)
    if (
        cookie_auth
        and method_name(request) not in ("GET", "HEAD", "OPTIONS")
        and not _request_same_origin(request)
    ):
        return "", None
    name_bi, rec, _ = await _account_session_lookup(env, token)
    if not name_bi or not rec:
        return "", None
    return name_bi, rec


async def _authed_account_name(env, request, data=None):
    # The account name proven by a valid session token — the POST-body
    # `sessionToken` field or an `Authorization: Bearer` header — lowercased, or
    # "" when there is no valid session. Endpoints that act on a per-account
    # resource (notifications, the poll digest, repo metadata) use this so they
    # authorize on a signed session, never on a self-asserted `node`/`ownerAccount`
    # string a caller can set to anyone's name.
    _, rec = await _account_session_record(env, request, data)
    return (rec.get("name", "") if rec else "").strip().lower()


# Legacy reservations may still carry an unexpired historical deposit record.
# This helper recognizes only that migration-era state; new signup is free.
def _donation_in_progress(rec):
    if not rec.get("donation_address") or rec.get("donation_confirmed"):
        return False
    _, expires, _ = _donation_expiry_fields(rec, Date.now())
    return Date.now() < expires


def _transient_client_address(request):
    """Read an address transiently for an endpoint-specific blind index."""
    try:
        headers = request.headers
    except Exception:
        return ""
    value = (headers.get("cf-connecting-ip") or "").strip()
    if not value:
        forwarded = (headers.get("x-forwarded-for") or "").strip()
        value = forwarded.split(",")[0].strip() if forwarded else ""
    return value[:64]


def _generalized_client_category(request):
    """Reduce a user agent to a non-identifying category."""
    try:
        ua = str(request.headers.get("user-agent") or "").lower()
    except Exception:
        ua = ""
    if any(marker in ua for marker in (
            "bot", "crawler", "spider", "curl/", "wget/", "scanner")):
        return "automated-client"
    if "mobile" in ua:
        return "mobile-browser"
    if any(marker in ua for marker in (
            "mozilla/", "chrome/", "safari/", "firefox/", "edg/")):
        return "browser"
    return "other-client" if ua else ""


def _account_session_client_ip(request):
    """Canonicalize the edge-observed sign-in address for session management.

    Only Cloudflare's edge-set header is accepted; X-Forwarded-For is client
    controlled and is intentionally ignored. The value is stored against the
    session row and returned exclusively to the account that owns it, so the
    owner can tell an unfamiliar device apart before revoking it.
    """
    try:
        raw = str(request.headers.get("cf-connecting-ip") or "")
    except Exception:
        return ""
    try:
        return str(ipaddress.ip_address(raw.strip().strip("[]")[:64]))[:64]
    except (ValueError, TypeError):
        return ""


def _account_session_device_label(request, desktop=False):
    """Return a coarse owner-visible label without retaining a raw user agent."""
    if desktop:
        return "Desktop node"
    return {
        "mobile-browser": "Mobile browser",
        "browser": "Web browser",
        "automated-client": "Automated client",
        "other-client": "Other client",
    }.get(_generalized_client_category(request), "Unknown device")


async def _world_moderation_tokens(env, request, now=None):
    """Derive rotating moderation subjects while raw request data is transient."""
    now = int(Date.now()) if now is None else int(now)
    day = now // WORLD_MANUAL_TOKEN_DAY_MS
    address = _transient_client_address(request)
    try:
        # The exact value is used only as keyed-HMAC input in this call frame.
        # Capping it prevents an oversized header from becoming hash work; it is
        # never returned, forwarded, logged, or persisted.
        transient_agent = str(
            request.headers.get("user-agent") or "")[:2048]
    except Exception:
        transient_agent = ""
    tokens = {"ip": "", "agent": ""}
    if address:
        tokens["ip"] = await blind_index(
            env, "world-manual-ip-v1:%d:%s" % (day, address))
    if transient_agent:
        tokens["agent"] = await blind_index(
            env, "world-manual-agent-v1:%d:%s" % (day, transient_agent))
    # `address` and `transient_agent` die with this call. Only keyed, rotating
    # tokens may be forwarded or persisted; public badge display continues to
    # use the existing generalized browser/OS allowlist.
    return tokens


async def _world_active_manual_block(env, tokens, now=None):
    """Return an active explicit block matching either opaque subject token."""
    now = int(Date.now()) if now is None else int(now)
    values = tokens if isinstance(tokens, dict) else {}
    ip_token = str(values.get("ip") or "")
    agent_token = str(values.get("agent") or "")
    if not (
        re.fullmatch(r"[a-f0-9]{64}", ip_token)
        or re.fullmatch(r"[a-f0-9]{64}", agent_token)
    ):
        return None
    await ensure_schema(env)
    row = await d1_first(
        env,
        "SELECT target_type,expires_at FROM world_manual_blocks "
        "WHERE revoked_at=0 AND expires_at>? AND "
        "((target_type='ip' AND subject_token=?) OR "
        "(target_type='agent' AND subject_token=?)) "
        "ORDER BY expires_at ASC LIMIT 1",
        now, ip_token, agent_token,
    )
    if not row:
        return None
    return {
        "targetType": (
            str(row.get("target_type") or "")
            if str(row.get("target_type") or "") in ("ip", "agent")
            else "unknown"),
        "expiresAt": int(row.get("expires_at") or 0),
    }


def _world_manual_control_signature(env, target_type, subject_token, expires_at):
    canonical = (
        "forkmesh-world-manual-block-v1\n%s\n%s\n%d"
        % (target_type, subject_token, int(expires_at))
    ).encode()
    return hmac.new(
        _account_session_secret(env), canonical, "sha256").hexdigest()


async def _world_disconnect_manual_block(
        env, target_type, subject_token, expires_at):
    """Ask the World DO to eject matching live sockets after persistence."""
    world_id = env.FORKMESH_WORLD.idFromName("town-square-v1")
    world_object = env.FORKMESH_WORLD.get(world_id)
    payload = {
        "targetType": target_type,
        "subjectToken": subject_token,
        "expiresAt": int(expires_at),
    }
    control_request = JsRequest.new(
        "https://forkmesh.internal/api/world/manual-block",
        to_js({
            "method": "POST",
            "headers": {
                "content-type": "application/json",
                "x-forkmesh-world-control": _world_manual_control_signature(
                    env, target_type, subject_token, expires_at),
            },
            "body": json.dumps(payload, separators=(",", ":")),
        }),
    )
    response = await world_object.fetch(control_request)
    if int(getattr(response, "status", 0) or 0) != 200:
        return 0
    try:
        result = json.loads(await response.text())
    except Exception:
        return 0
    return max(0, min(64, int(result.get("disconnected") or 0)))


def _world_mirror_push_signature(env, node, repo, commit):
    canonical = (
        "forkmesh-world-mirror-push-v1\n%s\n%s\n%s"
        % (node, repo, commit)
    ).encode()
    return hmac.new(
        _account_session_secret(env), canonical, "sha256").hexdigest()


async def _world_broadcast_mirror_push(env, node, repo, commit):
    """Tell the live World room a mirror node's served head just advanced."""
    world_id = env.FORKMESH_WORLD.idFromName("town-square-v1")
    world_object = env.FORKMESH_WORLD.get(world_id)
    payload = {"node": node, "repo": repo, "commit": commit}
    control_request = JsRequest.new(
        "https://forkmesh.internal/api/world/mirror-push",
        to_js({
            "method": "POST",
            "headers": {
                "content-type": "application/json",
                "x-forkmesh-world-control": _world_mirror_push_signature(
                    env, node, repo, commit),
            },
            "body": json.dumps(payload, separators=(",", ":")),
        }),
    )
    response = await world_object.fetch(control_request)
    return int(getattr(response, "status", 0) or 0) == 200


async def world_moderation_handler(env, request):
    """Create one explicit, temporary World block as a platform admin."""
    if method_name(request) != "POST":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"allow": "POST"})
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response(
            {"error": "invalid_json"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")
    if not isinstance(data, dict):
        return json_response(
            {"error": "invalid_json"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")
    account_bi, rec = await _account_session_record(env, request, data)
    actor = clean_string(
        rec.get("name", "") if rec else "", MAX_NODE_NAME).strip().lower()
    if not actor:
        return json_response(
            {"error": "invalid_session"}, status=401,
            cache_control="no-store, max-age=0, must-revalidate")
    if not await _has_role(env, actor, "platform_administrator"):
        await _audit_sensitive_action(
            env, actor, "world.manual_block", "world_peer", "", "denied",
            {"reason": "platform_administrator_required"})
        return json_response(
            {"error": "forbidden"}, status=403,
            cache_control="no-store, max-age=0, must-revalidate")

    target_type = str(data.get("targetType") or "").strip().lower()
    subject_token = str(data.get("handle") or "").strip().lower()
    duration = data.get("durationMs", WORLD_MANUAL_BLOCK_DEFAULT_MS)
    if target_type not in ("ip", "agent"):
        return json_response(
            {"error": "invalid_target_type"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")
    if not re.fullmatch(r"[a-f0-9]{64}", subject_token):
        return json_response(
            {"error": "invalid_handle"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")
    if (
        isinstance(duration, bool)
        or not isinstance(duration, int)
        or duration < WORLD_MANUAL_BLOCK_MIN_MS
        or duration > WORLD_MANUAL_BLOCK_MAX_MS
    ):
        return json_response(
            {"error": "invalid_duration"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")

    now = int(Date.now())
    # Subject tokens rotate daily. Do not pretend a block can outlive the token
    # it targets, even when the requested bounded duration crosses UTC midnight.
    token_expires = ((now // WORLD_MANUAL_TOKEN_DAY_MS) + 1
                     ) * WORLD_MANUAL_TOKEN_DAY_MS
    expires_at = min(now + duration, token_expires)
    block_id = new_world_peer_id() + new_world_peer_id()
    try:
        await ensure_schema(env)
        await d1_run(
            env,
            "DELETE FROM world_manual_blocks WHERE expires_at<?",
            now - WORLD_MANUAL_BLOCK_RETAIN_MS,
        )
        await d1_run(
            env,
            "INSERT INTO world_manual_blocks "
            "(block_id,target_type,subject_token,created_by_bi,created_at,"
            "expires_at,revoked_at) VALUES (?,?,?,?,?,?,0)",
            block_id, target_type, subject_token, account_bi, now, expires_at,
        )
    except Exception:
        await _audit_sensitive_action(
            env, actor, "world.manual_block", "world_" + target_type,
            subject_token, "failed",
            {"reason": "persistence_failed", "durationMs": duration})
        raise

    disconnected = 0
    try:
        disconnected = await _world_disconnect_manual_block(
            env, target_type, subject_token, expires_at)
    except Exception:
        # Admission checks are D1-backed, so a transient DO control failure does
        # not undo the block. Existing sockets will also disappear on their
        # normal stale/close boundary.
        disconnected = 0
    await _audit_sensitive_action(
        env, actor, "world.manual_block", "world_" + target_type,
        subject_token, "success", {
            "manual": True,
            "targetType": target_type,
            "durationMs": duration,
            "expiresAt": expires_at,
            "disconnectedCount": disconnected,
        })
    return json_response(
        {
            "ok": True,
            "blockId": block_id,
            "targetType": target_type,
            "expiresAt": expires_at,
            "disconnected": disconnected,
            "notice": (
                "This is an explicit temporary administrator action. "
                "ForkMesh automatic abuse detection and quarantine remain off."
            ),
        },
        cache_control="no-store, max-age=0, must-revalidate",
        extra_headers={"x-content-type-options": "nosniff"},
    )


async def world_admin_delete_node_handler(env, request):
    """Permanently remove one named node after an exact admin confirmation."""
    if method_name(request) != "POST":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"allow": "POST"})
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response(
            {"error": "invalid_json"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")
    actor = await _authed_account_name(env, request, data)
    if not actor or not await _is_admin(env, actor):
        return json_response(
            {"error": "not_admin"}, status=403,
            cache_control="no-store, max-age=0, must-revalidate")
    target = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    confirmation = clean_string(data.get("confirmation", ""), 128)
    if not valid_node_name(target):
        return json_response({"error": "invalid_node_name"}, status=400)
    required = "DELETE " + target
    if confirmation != required:
        return json_response(
            {"error": "confirmation_mismatch",
             "requiredConfirmation": required}, status=400)
    if target == actor or target in ("forkmesh", "forkmesh-mainnode"):
        await _audit_sensitive_action(
            env, actor, "world.node_delete", "node", target, "denied",
            {"reason": "protected_node"})
        return json_response({"error": "protected_node"}, status=409)
    target_bi, record = await _account_row(env, target)
    node_row = await d1_first(
        env, "SELECT node_bi FROM nodes WHERE node_bi=?", target_bi)
    if not record or not node_row:
        return json_response({"error": "node_not_found"}, status=404)
    if await _is_admin(env, target):
        await _audit_sensitive_action(
            env, actor, "world.node_delete", "node", target, "denied",
            {"reason": "admin_node"})
        return json_response({"error": "protected_node"}, status=409)

    owner = clean_string(record.get("owner", ""), MAX_NODE_NAME).lower()
    if owner:
        owner_bi, owner_record = await _account_row(env, owner)
        if owner_record:
            owner_record["nodes"] = [
                node for node in _owned_nodes(owner_record)
                if str(node).lower() != target
            ]
            await _save_account(env, owner_bi, owner_record)

    # These node-scoped operational rows do not belong to the account
    # namespace helper. Private routes cascade from the endpoint row.
    await d1_run(
        env, "DELETE FROM reward_node_observations WHERE node_bi=?", target_bi)
    await d1_run(
        env, "DELETE FROM mirror_https_endpoints WHERE node_bi=?", target_bi)
    await _delete_account_namespace(env, target_bi, record)
    await _audit_sensitive_action(
        env, actor, "world.node_delete", "node", target, "success",
        {"owner": owner})
    return json_response(
        {"ok": True, "nodeDeleted": target},
        cache_control="no-store, max-age=0, must-revalidate")


async def _world_layout_objects(env):
    """Project the bounded shared-object placement table for the browser."""
    rows = await d1_all(
        env,
        "SELECT object_id,x,z,rotation,updated_at FROM world_object_layout "
        "ORDER BY object_id LIMIT ?",
        WORLD_LAYOUT_MAX_OBJECTS,
    )
    objects = []
    for row in rows or []:
        objects.append({
            "id": str(row.get("object_id") or ""),
            "x": float(row.get("x") or 0),
            "z": float(row.get("z") or 0),
            "rotation": float(row.get("rotation") or 0),
            "updatedAt": int(row.get("updated_at") or 0),
        })
    return objects


def _world_layout_coordinate(value):
    """Return a bounded, rounded ground coordinate or None."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    # NaN fails both comparisons, so this also rejects non-finite input.
    if not (-WORLD_LAYOUT_MAX_COORDINATE <= value <= WORLD_LAYOUT_MAX_COORDINATE):
        return None
    return round(float(value), 2)


def _world_layout_rotation(value):
    """Return a heading offset in radians wrapped to [0, 2π), or None.

    The offset is relative to the object's authored rotation, so an absent or
    zero value leaves the scene facing the way it was built.
    """
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    # Reject non-finite input before the modulo, which propagates NaN.
    if not (-WORLD_LAYOUT_MAX_ROTATION <= value <= WORLD_LAYOUT_MAX_ROTATION):
        return None
    return round(float(value) % WORLD_LAYOUT_TURN, 4)


async def world_layout_handler(env, request):
    """Serve and admin-update the shared placement of Town Square objects."""
    if method_name(request) == "GET":
        cached = await edge_cache_match(WORLD_LAYOUT_CACHE_KEY)
        if cached is not None:
            return cached
        await ensure_schema(env)
        payload = {"ok": True, "objects": await _world_layout_objects(env)}
        resp = json_response(payload, cache_seconds=WORLD_LAYOUT_TTL)
        await edge_cache_put(WORLD_LAYOUT_CACHE_KEY, resp)
        return resp
    if method_name(request) != "POST":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"allow": "GET, POST"})
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = None
    if not isinstance(data, dict):
        return json_response(
            {"error": "invalid_json"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")
    account_bi, rec = await _account_session_record(env, request, data)
    actor = clean_string(
        rec.get("name", "") if rec else "", MAX_NODE_NAME).strip().lower()
    if not actor:
        return json_response(
            {"error": "invalid_session"}, status=401,
            cache_control="no-store, max-age=0, must-revalidate")
    if not await _has_role(env, actor, "platform_administrator"):
        await _audit_sensitive_action(
            env, actor, "world.layout.move", "world_object", "", "denied",
            {"reason": "platform_administrator_required"})
        return json_response(
            {"error": "forbidden"}, status=403,
            cache_control="no-store, max-age=0, must-revalidate")

    object_id = str(data.get("id") or "").strip().lower()
    if not WORLD_LAYOUT_ID_RE.fullmatch(object_id):
        return json_response(
            {"error": "invalid_object_id"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")
    x = _world_layout_coordinate(data.get("x"))
    z = _world_layout_coordinate(data.get("z"))
    if x is None or z is None:
        return json_response(
            {"error": "invalid_position"}, status=400,
            cache_control="no-store, max-age=0, must-revalidate")

    now = int(Date.now())
    await ensure_schema(env)
    existing = await d1_first(
        env,
        "SELECT object_id,rotation FROM world_object_layout WHERE object_id=?",
        object_id)
    # A client that only drags (and never rotates) omits the heading; keep the
    # locked one instead of silently snapping the object back to square.
    if data.get("rotation") is None:
        rotation = float((existing or {}).get("rotation") or 0.0)
    else:
        rotation = _world_layout_rotation(data.get("rotation"))
        if rotation is None:
            return json_response(
                {"error": "invalid_rotation"}, status=400,
                cache_control="no-store, max-age=0, must-revalidate")
    if not existing:
        count = await d1_first(
            env, "SELECT COUNT(*) AS n FROM world_object_layout")
        if int((count or {}).get("n") or 0) >= WORLD_LAYOUT_MAX_OBJECTS:
            return json_response(
                {"error": "layout_limit"}, status=409,
                cache_control="no-store, max-age=0, must-revalidate")
    await d1_run(
        env,
        "INSERT INTO world_object_layout "
        "(object_id,x,z,rotation,updated_by_bi,updated_at) "
        "VALUES (?,?,?,?,?,?) "
        "ON CONFLICT(object_id) DO UPDATE SET x=excluded.x,z=excluded.z,"
        "rotation=excluded.rotation,"
        "updated_by_bi=excluded.updated_by_bi,updated_at=excluded.updated_at",
        object_id, x, z, rotation, account_bi, now,
    )
    await edge_cache_delete(WORLD_LAYOUT_CACHE_KEY)
    await _audit_sensitive_action(
        env, actor, "world.layout.move", "world_object", object_id,
        "success", {"x": x, "z": z, "rotation": rotation})
    return json_response(
        {"ok": True, "objects": await _world_layout_objects(env)},
        cache_control="no-store, max-age=0, must-revalidate",
        extra_headers={"x-content-type-options": "nosniff"},
    )


# Simple web signup: create an active account from node name + email + password.
# Solana payout details are intentionally handled later from the dashboard profile.
async def _account_signup(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    email = clean_string(data.get("email", ""), 254).strip().lower()
    password = (data.get("password", "") or "")[:256]
    if not valid_node_name(name):
        return json_response({"error": "invalid_node_name"}, status=400)
    if "@" not in email or len(email) < 3:
        return json_response({"error": "valid_email_required"}, status=400)
    if len(password) < 8:
        return json_response({"error": "password_too_short"}, status=400)
    # Same org-namespace guard as _account_reserve (issue #388).
    _, org_holder = await _org_row(env, name)
    if org_holder:
        return json_response({"error": "node_name_taken"}, status=409)

    name_bi, existing = await _account_row(env, name)
    if existing and (existing.get("status") == "active" or
                     existing.get("donation_confirmed") or
                     _donation_in_progress(existing)):
        return json_response({"error": "node_name_taken"}, status=409)

    email_bi = await blind_index(env, email)
    dup = await d1_first(
        env, "SELECT user_bi AS name_bi FROM users WHERE email_bi=?", email_bi)
    if dup and dup.get("name_bi") != name_bi:
        return json_response({"error": "email_taken"}, status=409)

    # Per-IP account-creation throttle (checked only once the name/email are
    # otherwise creatable, so a rejected duplicate doesn't burn the quota).
    signup_ip = _transient_client_address(request)
    throttled = await signup_rate_check(
        env, await blind_index(env, signup_ip) if signup_ip else None)
    if throttled is not None:
        return throttled

    salt, phash = await hash_password(password)
    rec = existing or {}
    rec.update({
        "name": name,
        "email": email,
        "kind": "user",
        "pass_salt": salt,
        "pass_hash": phash,
    })
    rec["status"] = "active"
    rec["email_verified"] = bool(rec.get("email_verified", False))
    rec.setdefault("created_at", int(Date.now()))
    signup_meta = _signup_metadata(request)
    old_signup = rec.get("signup")
    if isinstance(old_signup, dict) and old_signup.get("at"):
        signup_meta["at"] = int(old_signup.get("at") or signup_meta["at"])
    # Overwrite any legacy raw ip/ua keys the next time an account is saved.
    rec["signup"] = signup_meta
    ip_bi = await blind_index(env, signup_ip) if signup_ip else None
    await _save_account(env, name_bi, rec, email_bi=email_bi, ip_bi=ip_bi)
    if rec.get("email") and not rec["email_verified"]:
        sent = await _send_verification_email(env, request, name, rec["email"])
        if not sent:
            await _enqueue_verification(env, name_bi, name, rec["email"])
    # Drop the cached chat roster/activity so open chat pages and header badges
    # pick up the new account on their next poll instead of a TTL later.
    await edge_cache_delete(USERS_DIRECTORY_CACHE_KEY)
    await edge_cache_delete(CHAT_ACTIVITY_CACHE_KEY)
    # Credit the referrer named by the /r/<name> share link, if any.
    await _record_referral_signup(env, name, data.get("ref", ""))
    # "Founding Member" badge: this account's row is already saved above, so
    # counting now tells whether it landed inside the first 100 real signups.
    user_count = await d1_first(
        env,
        "SELECT COUNT(*) AS c FROM users "
        "WHERE email_bi IS NOT NULL AND email_bi <> ''")
    if user_count and int(user_count.get("c") or 0) <= FIRST_100_USERS_LIMIT:
        await _award_badge(env, name, name_bi, "first_100_users")
    payload = await _account_public_payload(
        env, rec,
        session_device_label=_account_session_device_label(request),
        session_client_ip=_account_session_client_ip(request))
    return json_response(
        payload,
        status=201,
        extra_headers={
            "Set-Cookie": _account_session_cookie(payload["sessionToken"])
        },
    )


async def _account_password_record(env, data):
    identifier = clean_string(
        data.get("nodeName", "") or data.get("identifier", "") or
        data.get("email", ""), 254).strip().lower()
    password = (data.get("password", "") or "")[:256]
    if not identifier or not password:
        return "", None, "invalid_credentials"
    name_bi = ""
    rec = None
    if "@" in identifier:
        email_bi = await blind_index(env, identifier)
        row = await d1_first(
            env, "SELECT user_bi AS name_bi, data FROM users WHERE email_bi=?",
            email_bi)
        if row:
            name_bi = row.get("name_bi", "")
            rec = await decrypt_row(env, row.get("data"))
    elif valid_node_name(identifier):
        name_bi, rec = await _account_row(env, identifier)
    if not rec or rec.get("status") != "active" or not rec.get("pass_hash"):
        return "", None, "invalid_credentials"
    if not await verify_password(password, rec.get("pass_salt", ""), rec.get("pass_hash", "")):
        return "", None, "invalid_credentials"
    if _account_kind(rec) != "user":
        return "", None, "not_a_user"
    if not name_bi:
        name_bi = await blind_index(env, rec.get("name", ""))
    return name_bi, rec, ""


async def _account_follow(env, request, target_name, method):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    follower_bi, follower_rec = await _account_session_record(env, request, data)
    if not follower_rec:
        return json_response({"error": "invalid_session"}, status=401)

    target = clean_string(target_name, MAX_NODE_NAME).lower()
    if not valid_node_name(target):
        return json_response({"error": "not_found"}, status=404)
    # Any active, non-private account is followable — node accounts included,
    # matching the fediverse layer (_ap_user_federates) and the public
    # user-or-org page, which both treat the node name as a public identity.
    target_bi, target_rec = await _account_row(env, target)
    if (not target_rec or target_rec.get("status") != "active" or
            bool(target_rec.get("profile_private"))):
        return json_response({"error": "not_found"}, status=404)

    follower = clean_string(follower_rec.get("name", ""), MAX_NODE_NAME).lower()
    if follower == target:
        return json_response({"error": "cannot_follow_self"}, status=400)

    if method == "POST":
        await d1_run(
            env,
            """INSERT OR IGNORE INTO profile_follows
               (follower_bi, target_bi, follower_name, target_name, created_at)
               VALUES (?,?,?,?,?)""",
            follower_bi, target_bi, follower, target, int(Date.now()))
    else:
        await d1_run(
            env,
            "DELETE FROM profile_follows WHERE follower_bi=? AND target_bi=?",
            follower_bi, target_bi)

    social = await _account_social_counts(env, target, follower)
    return json_response({"ok": True, "name": target, **social})


# Claim a public node name. The desktop client signs the claim with its Ed25519
# identity (binding the name to a key); the website may reserve without a key.
# Legacy confirmed-deposit flags are honored only to avoid reclaiming old names.
async def _account_reserve(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    pubkey = clean_string(data.get("pubkey", ""), 120)
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    if not valid_node_name(name):
        return json_response({"error": "invalid_node_name"}, status=400)
    # Org names share the /<name>/<repo> URL namespace (issue #388): a name an
    # organization holds can never become a node name, or the org-alias URL
    # rewrite would be ambiguous.
    _, org_holder = await _org_row(env, name)
    if org_holder:
        return json_response({"error": "node_name_taken"}, status=409)

    name_bi, existing = await _account_row(env, name)
    if existing:
        ex_pub = existing.get("pubkey", "")
        if existing.get("status") == "active" or existing.get("donation_confirmed"):
            return json_response({"error": "node_name_taken"}, status=409)
        held_by_other = bool(ex_pub) and (not pubkey or ex_pub != pubkey)
        # A reservation bound to a different key only blocks the name while its
        # migration-era expiry window is still live. Otherwise it is abandoned,
        # so a fresh install can reclaim the name.
        if held_by_other and _donation_in_progress(existing):
            return json_response({"error": "node_name_taken"}, status=409)
        if held_by_other:
            # Reclaiming an abandoned reservation: drop the previous holder's
            # stale state so the new owner starts a clean, key-bound signup.
            existing = None
        # else: a stale/own reservation — allow re-reserving it (idempotent).

    if pubkey:
        if not _ts_ok(ts):
            return json_response({"error": "stale_request"}, status=401)
        canonical = ("forkmesh-reserve-v1\n" + name + "\n" + ts).encode()
        if not await ed25519_verify(pubkey, signature, canonical):
            return json_response({"error": "bad_signature"}, status=401)

    rec = existing or {}
    rec.update({
        "name": name,
        "kind": "node" if pubkey else rec.get("kind", "node"),
        "status": "reserved",
        "created_at": int(rec.get("created_at") or Date.now()),
    })
    if pubkey:
        rec["pubkey"] = pubkey
    await _save_account(env, name_bi, rec)
    if pubkey:
        try:
            await touch_registered_node(env, name_bi, rec)
        except Exception:
            pass
    return json_response(
        {"ok": True, "nodeName": name, "status": "reserved"}, status=201)


# Legacy step-2 helpers remain below as unreachable migration documentation.
# The live endpoint returns 410: signup is free, and reward/fund transfers are
# unsigned plans completed by an explicitly configured owner-device signer.


def _amount_sol(lamports):
    return "%.9f" % (int(lamports) / LAMPORTS_PER_SOL)


def _solana_pay_uri(address, amount_lamports, reference="", message="Join ForkMesh"):
    uri = ("solana:" + address +
           "?amount=" + _amount_sol(amount_lamports))
    if reference:
        uri += "&reference=" + reference
    uri += ("&label=" + quote("ForkMesh") +
            "&message=" + quote(message))
    return uri


# --- Low-level balance check ------------------------------------------------
# Returns the address balance in lamports, or None if the RPC call failed (so
# callers can distinguish "zero balance" from "couldn't check"). This is the
# lowest-level on-chain read available: a single getBalance, no transaction
# history scan or third-party indexer.
async def _solana_balance_lamports(env, address):
    if not address or not SOLANA_RE.match(address):
        return None
    resp = await _solana_rpc(env, "getBalance", [address])
    if not isinstance(resp, dict):
        return None
    result = resp.get("result")
    if not isinstance(result, dict):
        return None
    try:
        return int(result.get("value"))
    except (TypeError, ValueError):
        return None


async def _account_donation_address(env, request):
    del env, request
    return json_response({
        "error": "legacy_custody_disabled",
        "notice": (
            "ForkMesh signup is free. The Worker no longer creates or holds "
            "deposit-wallet keys."
        ),
        "custody": "self-custodial-only",
    }, status=410, cache_control="no-store")


# Read-only compatibility view for a historical deposit. It projects public
# status and may read the public on-chain balance, but never rewrites the row,
# inspects its retained key field, signs, or broadcasts.
async def _account_donation_status(env, request):
    if not _is_main_relay(env):
        return await _federated_donation_status(env, request)
    params = parse_qs(urlparse(request.url).query)
    name = clean_string(params.get("nodeName", [""])[0], MAX_NODE_NAME).lower()
    _, rec = await _account_row(env, name)
    if not rec:
        return json_response({"error": "no_such_account"}, status=404)
    addr = rec.get("donation_address", "")
    if not addr:
        return json_response({"error": "no_donation_address"}, status=400)
    required = int(rec.get("donation_required_lamports", MIN_JOIN_LAMPORTS))
    now = int(Date.now())
    _, expires_at, delete_at = _donation_expiry_fields(rec, now)
    already_confirmed = bool(rec.get("donation_confirmed"))
    balance = await _solana_balance_lamports(env, addr)
    checking = balance is None
    received = (
        int(rec.get("donation_received_lamports", 0) or 0)
        if checking else int(balance)
    )
    paid = already_confirmed or (received >= required and required > 0)
    expired = not paid and received == 0 and now >= expires_at
    return json_response({
        "ok": True, "paid": paid, "checking": checking,
        "receivedLamports": received, "requiredLamports": required,
        "expired": expired, "hidden": expired, "canRenew": expired,
        "expiresAt": expires_at, "deleteAt": delete_at,
        "status": "legacy_custody_frozen",
        "custody": "migration-required",
        "completedTransfer": rec.get("donation_sweep_sig", ""),
        "notice": (
            "This is a read-only historical status. The Worker cannot access "
            "the retained wallet for signing or move its funds."
        ),
    }, cache_control="no-store")


def _signup_metadata(request):
    # The raw address is used transiently to derive users.ip_bi for duplicate
    # signup throttling; it is never copied into the encrypted account blob.
    # User-agent is reduced to a broad client category, and country to an
    # approximate two-letter edge-derived code.
    return {
        "country": world_request_country(request),
        "clientCategory": _generalized_client_category(request),
        "at": int(Date.now()),
    }


# Step 3: after a confirmed donation, set the email + password that unlock
# universal (any-surface) login. Email + password hash are stored encrypted.
async def _account_finalize(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    email = clean_string(data.get("email", ""), 254)
    password = (data.get("password", "") or "")[:256]
    pubkey = clean_string(data.get("pubkey", ""), 120)
    solana = clean_string(data.get("solana", ""), 64)
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)

    name_bi, rec = await _account_row(env, name)
    if not rec:
        return json_response({"error": "no_such_account"}, status=404)

    # A key-bound (desktop) account proves ownership with its Ed25519 signature;
    # email/password are optional (it logs in by key). A keyless (web) signup just
    # sets an email + password — signup is free (no donation required), and the
    # verification email sent below (Mailtrap) is what confirms a real human is
    # behind the name.
    key_bound = bool(rec.get("pubkey"))
    if key_bound:
        if not _ts_ok(ts):
            return json_response({"error": "stale_request"}, status=401)
        canonical = ("forkmesh-finalize-v1\n" + name + "\n" + email + "\n" +
                     ts).encode()
        if not await ed25519_verify(rec["pubkey"], signature, canonical):
            return json_response({"error": "bad_signature"}, status=401)
    elif pubkey:
        rec["pubkey"] = pubkey  # bind a key now if a web user supplied one

    # Email + password unlock cross-device (password) login. They're required for
    # keyless signups and optional for key-bound ones (which log in by key); when
    # either is supplied they're validated and the email is indexed for login.
    set_credentials = bool(email) or bool(password) or not key_bound
    email_bi = None
    if set_credentials:
        if "@" not in email or len(email) < 3:
            return json_response({"error": "valid_email_required"}, status=400)
        if len(password) < 8:
            return json_response({"error": "password_too_short"}, status=400)
        email_bi = await blind_index(env, email)
        dup = await d1_first(
            env, "SELECT user_bi AS name_bi FROM users WHERE email_bi=?",
            email_bi)
        if dup and dup.get("name_bi") != name_bi:
            return json_response({"error": "email_taken"}, status=409)
        salt, phash = await hash_password(password)
        rec["email"] = email
        rec["pass_salt"] = salt
        rec["pass_hash"] = phash
    if key_bound:
        rec.setdefault("kind", "node")
    else:
        rec["kind"] = "user"
    rec["status"] = "active"
    # Optional public self-custodial payout address for reward consideration.
    if solana and SOLANA_RE.match(solana):
        rec["solana"] = solana
    rec["email_verified"] = bool(rec.get("email_verified", False))
    rec.setdefault("created_at", int(Date.now()))
    # Keep only coarse signup metadata; the transient address is converted to a
    # keyed blind index and never persisted in the account's decryptable blob.
    signup_ip = _transient_client_address(request)
    signup_meta = _signup_metadata(request)
    old_signup = rec.get("signup")
    if isinstance(old_signup, dict) and old_signup.get("at"):
        signup_meta["at"] = int(old_signup.get("at") or signup_meta["at"])
    rec["signup"] = signup_meta
    ip_bi = await blind_index(env, signup_ip) if signup_ip else None
    await _save_account(env, name_bi, rec, email_bi=email_bi, ip_bi=ip_bi)
    if rec.get("pubkey"):
        try:
            await touch_registered_node(env, name_bi, rec)
        except Exception:
            pass
    # Send a verification email (Mailtrap). If the email service is unconfigured
    # or the send fails, fall back to the admin queue so an admin can still verify
    # by hand. A free key-bound join with no email yet has nothing to verify.
    if rec.get("email") and not rec["email_verified"]:
        sent = await _send_verification_email(env, request, name, rec["email"])
        if not sent:
            await _enqueue_verification(env, name_bi, name, rec["email"])
    # Installer link code (adhoc #53): a hosts/SSH install prints a code on the
    # fresh machine and hands it to the daemon, which presents it here when it
    # registers. If the installing desktop's signed offer already arrived the
    # node is linked to that user right now; otherwise the node's half is
    # parked until the offer lands (see _redeem_or_park_link_code).
    link_code = clean_string(data.get("linkCode", ""), 16).strip()
    if key_bound and LINK_CODE_RE.match(link_code):
        result = await _redeem_or_park_link_code(
            env, link_code, node=name, pubkey=rec.get("pubkey", ""))
        if result.get("linked"):
            rec["owner"] = result.get("user", "")
    payload = await _account_public_payload(
        env, rec,
        session_device_label=_account_session_device_label(
            request, desktop=bool(pubkey)),
        session_client_ip=_account_session_client_ip(request))
    return json_response(
        payload,
        status=201,
        extra_headers={
            "Set-Cookie": _account_session_cookie(payload["sessionToken"])
        },
    )


async def _account_profile(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    public_profile_fields = {
        "avatarPng", "profileBio", "profileAbout", "profileReadme",
        "profileLocation", "profileTimezone", "profilePrivate",
        "followersPublic", "mastodon",
        "profileLinks", "nodeName", "email", "identifier", "sessionToken",
        # The dashboard always sends a (usually empty) `password` field even on
        # pages with no password input. Whitelist it so a session-authed
        # public-profile save doesn't get shunted into the credentials branch
        # and rejected with invalid_credentials. Privileged writes still carry
        # a non-whitelisted key (solana, deleteAccount, …) and stay on the
        # password-verified path.
        "password",
    }
    session_bi, session_rec = await _account_session_record(env, request, data)
    if session_rec and not (set(data.keys()) - public_profile_fields):
        name_bi = session_bi
        rec = session_rec
    else:
        identifier = clean_string(
            data.get("nodeName", "") or data.get("identifier", "") or
            data.get("email", ""), 254).strip().lower()
        password = (data.get("password", "") or "")[:256]
        if not identifier or not password:
            return json_response({"error": "invalid_credentials"}, status=401)

        name_bi = ""
        rec = None
        if "@" in identifier:
            email_bi = await blind_index(env, identifier)
            row = await d1_first(
                env, "SELECT user_bi AS name_bi, data FROM users WHERE email_bi=?",
                email_bi)
            if row:
                name_bi = row.get("name_bi", "")
                rec = await decrypt_row(env, row.get("data"))
        elif valid_node_name(identifier):
            name_bi, rec = await _account_row(env, identifier)
        if not rec or rec.get("status") != "active" or not rec.get("pass_hash"):
            return json_response({"error": "invalid_credentials"}, status=401)
        if not await verify_password(password, rec.get("pass_salt", ""), rec.get("pass_hash", "")):
            return json_response({"error": "invalid_credentials"}, status=401)
        if not name_bi:
            name_bi = await blind_index(env, rec.get("name", ""))

    if data.get("deleteAccount") or data.get("disableAccount"):
        await _delete_account_namespace(env, name_bi, rec)
        return json_response({"ok": True, "accountDeleted": True})

    changed = False
    # The Person actor doc only ever surfaces the bio and the profile-private
    # federation gate (_ap_build_actor_doc), so remember just those: the
    # Update(Person) broadcast below must not fire for payout/avatar/
    # notification tweaks — every no-op broadcast fans out one delivery per
    # follower server and pulls a rel=me refetch storm back at us.
    fed_before = (rec.get("profile_bio", ""), bool(rec.get("profile_private")),
                  bool(rec.get("profile_followers_public")))
    if "solana" in data:
        solana = clean_string(data.get("solana", ""), 64).strip()
        if solana and not SOLANA_RE.match(solana):
            return json_response({"error": "bad_solana"}, status=400)
        if solana:
            if rec.get("solana") != solana:
                rec["solana"] = solana
                changed = True
        elif rec.get("solana"):
            rec.pop("solana", None)
            changed = True

    if "avatarPng" in data:
        avatar_png, avatar_error = clean_avatar_png(data.get("avatarPng", ""))
        if avatar_error:
            status = 413 if avatar_error == "avatar_too_large" else 400
            return json_response({"error": avatar_error}, status=status)
        if avatar_png:
            if rec.get("avatar_png") != avatar_png:
                rec["avatar_png"] = avatar_png
                rec["avatar_updated_at"] = int(Date.now())
                changed = True
        elif rec.get("avatar_png"):
            rec.pop("avatar_png", None)
            rec["avatar_updated_at"] = int(Date.now())
            changed = True

    if "profileBio" in data:
        bio = clean_string(data.get("profileBio", ""), MAX_PROFILE_BIO).strip()
        if rec.get("profile_bio", "") != bio:
            if bio:
                rec["profile_bio"] = bio
            else:
                rec.pop("profile_bio", None)
            changed = True

    if "profileAbout" in data:
        raw_about = data.get("profileAbout", "")
        if len(str(raw_about or "").encode("utf-8")) > MAX_PROFILE_ABOUT:
            return json_response({"error": "profile_about_too_large"}, status=413)
        about = clean_string(raw_about, MAX_PROFILE_ABOUT).replace("\r\n", "\n")
        if rec.get("profile_about", "") != about:
            if about:
                rec["profile_about"] = about
            else:
                rec.pop("profile_about", None)
            changed = True

    if "profileReadme" in data:
        raw_readme = data.get("profileReadme", "")
        if len(str(raw_readme or "").encode("utf-8")) > MAX_PROFILE_README:
            return json_response({"error": "profile_readme_too_large"}, status=413)
        readme = clean_string(raw_readme, MAX_PROFILE_README).replace("\r\n", "\n")
        if rec.get("profile_readme", "") != readme:
            if readme:
                rec["profile_readme"] = readme
            else:
                rec.pop("profile_readme", None)
            changed = True

    if "profileLocation" in data:
        location = clean_string(
            data.get("profileLocation", ""), MAX_PROFILE_LOCATION).strip()
        if rec.get("profile_location", "") != location:
            if location:
                rec["profile_location"] = location
            else:
                rec.pop("profile_location", None)
            changed = True

    if "profileTimezone" in data:
        raw_timezone = clean_string(
            data.get("profileTimezone", ""), MAX_PROFILE_TIMEZONE).strip()
        timezone = _clean_profile_timezone(raw_timezone)
        if raw_timezone and not timezone:
            return json_response({"error": "bad_profile_timezone"}, status=400)
        if rec.get("profile_timezone", "") != timezone:
            if timezone:
                rec["profile_timezone"] = timezone
            else:
                rec.pop("profile_timezone", None)
            changed = True

    if "profilePrivate" in data:
        profile_private = bool(data.get("profilePrivate"))
        if bool(rec.get("profile_private")) != profile_private:
            if profile_private:
                rec["profile_private"] = True
            else:
                rec.pop("profile_private", None)
            changed = True

    if "followersPublic" in data:
        followers_public = bool(data.get("followersPublic"))
        if bool(rec.get("profile_followers_public")) != followers_public:
            if followers_public:
                rec["profile_followers_public"] = True
            else:
                rec.pop("profile_followers_public", None)
            changed = True

    if "mastodon" in data:
        raw_mastodon = clean_string(data.get("mastodon", ""), 120).strip()
        mastodon = _clean_mastodon_handle(raw_mastodon)
        if raw_mastodon and not mastodon:
            return json_response({"error": "bad_mastodon"}, status=400)
        if rec.get("mastodon", "") != mastodon:
            if mastodon:
                rec["mastodon"] = mastodon
            else:
                rec.pop("mastodon", None)
            changed = True

    if "profileLinks" in data:
        links, link_error = await _clean_profile_links(
            env, rec, data.get("profileLinks"))
        if link_error:
            return json_response({"error": link_error}, status=400)
        if rec.get("profile_links", []) != links:
            if links:
                rec["profile_links"] = links
            else:
                rec.pop("profile_links", None)
            changed = True

    if "emailNotifications" in data:
        email_notifications = bool(data.get("emailNotifications"))
        if bool(rec.get("email_notifications", True)) != email_notifications:
            if email_notifications:
                rec.pop("email_notifications", None)
            else:
                rec["email_notifications"] = False
            changed = True

    if "notificationPreferences" in data:
        prefs = _clean_notification_preferences(
            data.get("notificationPreferences"), rec)
        if rec.get("notification_preferences", {}) != prefs:
            rec["notification_preferences"] = prefs
            changed = True

    verification_sent = False
    verification_queued = False
    if data.get("resendVerification") and rec.get("email") and not rec.get("email_verified"):
        verification_sent = await _send_verification_email(env, request, rec.get("name", ""), rec.get("email", ""))
        if not verification_sent:
            await _enqueue_verification(env, name_bi, rec.get("name", ""), rec.get("email", ""))
            verification_queued = True

    new_name = clean_string(data.get("newNodeName", ""), MAX_NODE_NAME).lower()
    renamed = False
    if new_name:
        if not rec.get("email_verified"):
            return json_response({"error": "email_not_verified"}, status=403)
        name_bi, rec, rename_error = await _rename_account_namespace(env, name_bi, rec, new_name)
        if rename_error:
            status = 400
            if rename_error in ("node_name_taken", "repo_namespace_conflict"):
                status = 409
            elif rename_error == "invalid_credentials":
                status = 401
            return json_response({"error": rename_error}, status=status)
        changed = False
        renamed = True

    if changed:
        await _save_account(env, name_bi, rec)
        # Public-profile and chat-directory caches carry avatar/profile/device
        # metadata. Purge them on every profile edit; in particular, a privacy
        # opt-out must stop new public reads immediately in this colo.
        profile_name = clean_string(
            rec.get("name", ""), MAX_NODE_NAME).lower()
        await asyncio.gather(
            edge_cache_delete(
                ACCOUNT_LOOKUP_CACHE_PREFIX + quote(profile_name)),
            edge_cache_delete(USERS_DIRECTORY_CACHE_KEY),
            return_exceptions=True,
        )
        # Fediverse followers of this profile get an Update(Person) so bio
        # changes propagate to remote servers immediately — but only when a
        # federated field actually changed (see fed_before above).
        fed_after = (rec.get("profile_bio", ""),
                     bool(rec.get("profile_private")),
                     bool(rec.get("profile_followers_public")))
        if fed_after != fed_before:
            await _best_effort_inbox_side_effect(_ap_broadcast_actor_update(
                env, request, AP_ACTOR_USER,
                clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()))
    current_token, _ = _request_account_session_token(request, data)
    payload = await _account_public_payload(
        env, rec, current_token if current_token else None)
    payload["verificationSent"] = bool(verification_sent)
    payload["verificationQueued"] = bool(verification_queued)
    payload["nodeNameChanged"] = bool(renamed)
    return json_response(
        payload,
        extra_headers={
            "Set-Cookie": _account_session_cookie(payload["sessionToken"])
        },
    )


# --- Users vs nodes: claiming & linking (adhoc #53) --------------------------
#
# Two ways a user (an account with login credentials) becomes the owner of a
# node (a key-bound-only account, e.g. a headless mirror registration):
#
#  1. Website claim: the user enters the node's ID (its account name) on the
#     dashboard. The worker parks a short confirmation code on the node's
#     record; the node learns of it in its next signed heartbeat reply and
#     shows the code on the machine itself. Typing that code back into the
#     website proves the user can see the node, and the records are linked.
#
#  2. Installer link code: a hosts/SSH install prints a code on the fresh
#     machine and hands it to the launched daemon, which presents it when it
#     registers. The desktop app that drove the install offers the same code
#     signed by its own key; whichever side reaches the worker first parks its
#     half in link_codes and the second side completes the link. The new node
#     is attached to the USER behind the installing account (the account
#     itself when it is a user, else that node's own recorded owner).


def _generate_confirm_code():
    return "%06d" % (int.from_bytes(_random_bytes(4), "big") % 1000000)


def _claim_pending(rec, now):
    pending = rec.get("claim_pending")
    if not isinstance(pending, dict):
        return None
    try:
        expires = int(pending.get("expires") or 0)
    except (TypeError, ValueError):
        return None
    if now >= expires or not pending.get("user") or not pending.get("code"):
        return None
    return pending


def _transfer_pending(rec, now):
    pending = rec.get("ownership_transfer_pending")
    if not isinstance(pending, dict):
        return None
    try:
        expires = int(pending.get("expires") or 0)
    except (TypeError, ValueError):
        return None
    if now >= expires or not pending.get("admin"):
        return None
    return pending


async def _resolve_user_by_password(env, data):
    # Web-auth gate for the claim endpoints, matching _account_profile: a
    # state-changing dashboard action re-proves the password on each request
    # (the static site keeps no server-side session). Returns (name_bi, rec)
    # for an active credentialed account, else (None, None).
    identifier = clean_string(
        data.get("identifier", "") or data.get("email", "") or
        data.get("user", ""), 254).strip().lower()
    password = (data.get("password", "") or "")[:256]
    if not identifier or not password:
        return None, None
    name_bi, rec = "", None
    if "@" in identifier:
        email_bi = await blind_index(env, identifier)
        row = await d1_first(
            env, "SELECT user_bi AS name_bi, data FROM users WHERE email_bi=?",
            email_bi)
        if row:
            name_bi = row.get("name_bi", "")
            rec = await decrypt_row(env, row.get("data"))
    elif valid_node_name(identifier):
        name_bi, rec = await _account_row(env, identifier)
    if not rec or rec.get("status") != "active" or not rec.get("pass_hash"):
        return None, None
    if not await verify_password(password, rec.get("pass_salt", ""),
                                 rec.get("pass_hash", "")):
        return None, None
    if not name_bi:
        name_bi = await blind_index(env, rec.get("name", ""))
    return name_bi, rec


async def _link_node_to_user(env, node_name, node_bi, node_rec, user_name):
    # The one place ownership is written: node.owner = user and the node joins
    # the user's nodes list. The user's record is loaded fresh so a stale
    # caller copy can't clobber it. When the node was already owned (the
    # browser link-grant flow may re-home a node), it leaves the previous
    # owner's nodes list so the fleet views stay truthful.
    prev_owner = node_rec.get("owner") or ""
    node_rec["owner"] = user_name
    node_rec.pop("claim_pending", None)
    node_rec.pop("ownership_transfer_pending", None)
    await _save_account(env, node_bi, node_rec)
    if prev_owner and prev_owner != user_name:
        prev_bi, prev_rec = await _account_row(env, prev_owner)
        if prev_rec is not None:
            prev_rec["nodes"] = [n for n in _owned_nodes(prev_rec)
                                 if n != node_name]
            await _save_account(env, prev_bi, prev_rec)
    user_bi, user_rec = await _account_row(env, user_name)
    if user_rec is not None:
        nodes = _owned_nodes(user_rec)
        was_operator = bool(nodes)
        if node_name not in nodes:
            nodes.append(node_name)
        user_rec["nodes"] = nodes
        await _save_account(env, user_bi, user_rec)
        if not was_operator:
            # "Mirror Operator" badge: this is the account's first node, the
            # real event that makes it a mirror operator.
            await _award_badge(env, user_name, user_bi, "mirror_operator")


async def _account_claim_node(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    _, user_rec = await _resolve_user_by_password(env, data)
    if not user_rec:
        return json_response({"error": "invalid_credentials"}, status=401)
    user_name = user_rec.get("name", "")
    raw_id = clean_string(data.get("nodeId", "") or data.get("nodeName", ""),
                          MAX_NODE_NAME)
    if not (valid_node_name(raw_id.strip().lower()) or valid_node_pubkey(raw_id)):
        return json_response({"error": "invalid_node_id"}, status=400)
    node_bi, node_rec, node_id = await _resolve_claimable_node(env, raw_id)
    if node_id == user_name:
        return json_response({"error": "cannot_claim_self"}, status=400)
    if not node_rec or node_rec.get("status") != "active":
        return json_response({"error": "no_such_node"}, status=404)
    if _account_kind(node_rec) != "node":
        # An account that can log in is a user in its own right, not claimable.
        return json_response({"error": "not_a_node"}, status=403)
    if node_rec.get("owner") == user_name:
        return json_response({"ok": True, "alreadyLinked": True,
                              "nodeId": node_id})
    if node_rec.get("owner"):
        return json_response({"error": "node_already_owned"}, status=409)
    now = int(Date.now())
    node_rec["claim_pending"] = {
        "user": user_name,
        "code": _generate_confirm_code(),
        "expires": now + CLAIM_CODE_TTL_MS,
        "attempts": 0,
    }
    await _save_account(env, node_bi, node_rec)
    # The code itself is deliberately NOT returned: it only ever travels
    # worker -> node (heartbeat reply) -> the person standing at both screens.
    return json_response({"ok": True, "pending": True, "nodeId": node_id,
                          "expiresAt": now + CLAIM_CODE_TTL_MS}, status=201)


async def _account_claim_confirm(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    _, user_rec = await _resolve_user_by_password(env, data)
    if not user_rec:
        return json_response({"error": "invalid_credentials"}, status=401)
    user_name = user_rec.get("name", "")
    raw_id = clean_string(data.get("nodeId", "") or data.get("nodeName", ""),
                          MAX_NODE_NAME)
    code = clean_string(data.get("code", ""), 16).strip()
    if not (valid_node_name(raw_id.strip().lower()) or valid_node_pubkey(raw_id)):
        return json_response({"error": "invalid_node_id"}, status=400)
    node_bi, node_rec, node_id = await _resolve_claimable_node(env, raw_id)
    if not node_rec or node_rec.get("status") != "active":
        return json_response({"error": "no_such_node"}, status=404)
    if node_rec.get("owner") == user_name:
        return json_response({"ok": True, "linked": True, "nodeId": node_id,
                              "nodes": _owned_nodes(user_rec)})
    pending = _claim_pending(node_rec, int(Date.now()))
    if not pending or pending.get("user") != user_name:
        return json_response({"error": "no_pending_claim"}, status=404)
    if not code or code != pending.get("code"):
        # A 6-digit code must not be guessable within its TTL: a few misses
        # invalidate the claim entirely (restart it from the dashboard).
        attempts = int(pending.get("attempts") or 0) + 1
        if attempts >= CLAIM_CODE_MAX_ATTEMPTS:
            node_rec.pop("claim_pending", None)
        else:
            pending["attempts"] = attempts
            node_rec["claim_pending"] = pending
        await _save_account(env, node_bi, node_rec)
        return json_response({"error": "bad_code"}, status=401)
    await _link_node_to_user(env, node_id, node_bi, node_rec, user_name)
    _, fresh_user = await _account_row(env, user_name)
    return json_response({"ok": True, "linked": True, "nodeId": node_id,
                          "nodes": _owned_nodes(fresh_user or user_rec)})


async def _redeem_or_park_link_code(env, code, node=None, user=None, pubkey=None):
    # Order-independent rendezvous for installer link codes: called with node=
    # from the fresh node's registration and with user= from the installing
    # desktop's signed offer. When the opposite half is already parked (and
    # fresh), complete the link and burn the code; otherwise park this half.
    # Returns {"linked": True, "node": ..., "user": ...} when the link
    # completed now, else {"linked": False}.
    code_bi = await blind_index(env, "link:" + code)
    now = int(Date.now())
    row = await d1_first(
        env, "SELECT data, ts FROM link_codes WHERE code_bi=?", code_bi)
    other = None
    if row:
        try:
            fresh = now - int(row.get("ts") or 0) <= LINK_CODE_TTL_MS
        except (TypeError, ValueError):
            fresh = False
        other = await decrypt_row(env, row.get("data")) if fresh else None
    if node and other and other.get("user"):
        node_bi, node_rec = await _account_row(env, node)
        if node_rec is not None and _account_kind(node_rec) == "node":
            if pubkey and valid_node_pubkey(pubkey):
                node_rec["pubkey"] = pubkey
            await _link_node_to_user(env, node, node_bi, node_rec,
                                     other["user"])
        await d1_run(env, "DELETE FROM link_codes WHERE code_bi=?", code_bi)
        return {"linked": True, "node": node, "user": other["user"]}
    if user and other and other.get("node"):
        node_name = other["node"]
        other_pubkey = other.get("pubkey", "")
        node_bi, node_rec = await _account_row(env, node_name)
        if node_rec is not None and _account_kind(node_rec) == "node":
            if other_pubkey and valid_node_pubkey(other_pubkey):
                node_rec["pubkey"] = other_pubkey
            await _link_node_to_user(env, node_name, node_bi, node_rec, user)
        await d1_run(env, "DELETE FROM link_codes WHERE code_bi=?", code_bi)
        return {"linked": True, "node": node_name, "user": user}
    parked = {"node": node} if node else {"user": user}
    if node and pubkey and valid_node_pubkey(pubkey):
        parked["pubkey"] = pubkey
    encrypted = await encrypt_row(env, parked)
    await d1_run(
        env,
        "INSERT INTO link_codes (code_bi, data, ts) VALUES (?,?,?) "
        "ON CONFLICT(code_bi) DO UPDATE SET data=excluded.data, ts=excluded.ts",
        code_bi, encrypted, now)
    return {"linked": False}


async def _account_reclaim_node(env, request):
    # Fresh host reinstall with a reused node name: the account may already be
    # active and bound to the previous local Ed25519 key, so reserve/finalize
    # cannot run. Pair the installer link code with a signature from the new key;
    # once the installing user's signed offer is present, re-home this node to
    # that user and rotate the node account's hosting key.
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    pubkey = clean_string(data.get("pubkey", ""), 120)
    code = clean_string(data.get("linkCode", "") or data.get("code", ""), 16).strip()
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    if (not valid_node_name(name) or not valid_node_pubkey(pubkey) or
            not LINK_CODE_RE.match(code)):
        return json_response({"error": "invalid_request"}, status=400)
    if not _ts_ok(ts):
        return json_response({"error": "stale_request"}, status=401)
    canonical = ("forkmesh-reclaim-node-v1\n" + name + "\n" + pubkey + "\n" +
                 code + "\n" + ts).encode()
    if not await ed25519_verify(pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)

    _, node_rec = await _account_row(env, name)
    if not node_rec or node_rec.get("status") != "active":
        return json_response({"error": "no_such_node"}, status=404)
    if _account_kind(node_rec) != "node":
        return json_response({"error": "not_a_node"}, status=403)

    result = await _redeem_or_park_link_code(
        env, code, node=name, pubkey=pubkey)
    if result.get("linked"):
        return json_response({"ok": True, "linked": True,
                              "node": result.get("node", name),
                              "user": result.get("user", "")})
    return json_response({"ok": True, "linked": False, "pending": True,
                          "node": name}, status=202)


async def _account_link_node(env, request):
    # The installing desktop's half of the installer link-code flow: the code
    # printed by install.sh on the fresh machine, offered here signed by the
    # installing account's own key.
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    code = clean_string(data.get("code", ""), 16).strip()
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    if not valid_node_name(name) or not LINK_CODE_RE.match(code):
        return json_response({"error": "invalid_request"}, status=400)
    _, rec = await _account_row(env, name)
    if not rec or rec.get("status") != "active":
        return json_response({"error": "no_such_account"}, status=404)
    pubkey = rec.get("pubkey", "")
    if not pubkey or not _ts_ok(ts):
        return json_response({"error": "unauthorized"}, status=401)
    canonical = ("forkmesh-link-v1\n" + name + "\n" + code + "\n" + ts).encode()
    if not await ed25519_verify(pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)
    user = name if _account_kind(rec) == "user" else (rec.get("owner") or "")
    if not user:
        return json_response({"error": "no_user_account"}, status=403)
    result = await _redeem_or_park_link_code(env, code, user=user)
    if result.get("linked"):
        return json_response({"ok": True, "linked": True,
                              "node": result.get("node", ""), "user": user})
    return json_response({"ok": True, "linked": False, "pending": True,
                          "user": user}, status=202)


async def _account_link_self(env, request):
    # A node links ITSELF to a user account, driven from that node's own desktop
    # app ("Log in as a user" in the node profile). The request proves BOTH
    # secrets at once: control of the node's key (Ed25519 signature) and the
    # user's credentials (identifier + password), so the link completes
    # immediately with no confirmation code — holding both IS the authorization.
    # This is the in-app counterpart to the website's claim-node/claim-confirm
    # code flow, which only proves the password and needs the on-node code to
    # prove the claimer can see the machine.
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    node_name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    if not valid_node_name(node_name):
        return json_response({"error": "invalid_node_id"}, status=400)
    node_bi, node_rec = await _account_row(env, node_name)
    if not node_rec or node_rec.get("status") != "active":
        return json_response({"error": "no_such_node"}, status=404)
    pubkey = node_rec.get("pubkey", "")
    if not pubkey or not _ts_ok(ts):
        return json_response({"error": "unauthorized"}, status=401)
    identifier = clean_string(
        data.get("identifier", "") or data.get("email", "") or
        data.get("user", ""), 254).strip().lower()
    canonical = ("forkmesh-link-self-v1\n" + node_name + "\n" + identifier +
                 "\n" + ts).encode()
    if not await ed25519_verify(pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)
    # Only now spend a password verification (the node signature gates it).
    _, user_rec = await _resolve_user_by_password(env, data)
    if not user_rec:
        return json_response({"error": "invalid_credentials"}, status=401)
    user_name = user_rec.get("name", "")
    if node_name == user_name:
        return json_response({"error": "cannot_link_self"}, status=400)
    if _account_kind(node_rec) != "node":
        # An account that can log in is a user in its own right, not linkable.
        return json_response({"error": "not_a_node"}, status=403)
    if node_rec.get("owner") == user_name:
        return json_response({"ok": True, "linked": True, "alreadyLinked": True,
                              "nodeId": node_name, "user": user_name,
                              "nodes": _owned_nodes(user_rec)})
    if node_rec.get("owner"):
        return json_response({"error": "node_already_owned"}, status=409)
    await _link_node_to_user(env, node_name, node_bi, node_rec, user_name)
    _, fresh_user = await _account_row(env, user_name)
    return json_response({"ok": True, "linked": True, "nodeId": node_name,
                          "user": user_name,
                          "nodes": _owned_nodes(fresh_user or user_rec)})


async def _account_link_grant(env, request):
    # The node profile's "Link this node to your account" button (adhoc #120):
    # the desktop app signs a short-lived grant with the node's own key and
    # opens it as a /dashboard URL in the browser, where the already-logged-in
    # user redeems it here. The signature proves node-key control and names an
    # explicit consent ("attach me to whoever redeems this"), so unlike
    # claim-node no password re-entry or confirmation code is needed — the
    # browser session just names the user. Freshness (LOGIN_MAX_SKEW_MS) plus
    # single use keep a leaked URL from being replayable.
    #
    # Unlike claim-node/link-self this OVERRIDES the node's current
    # association: an already-owned node is re-homed to the redeeming user
    # (leaving the old owner's fleet), and even a node whose account is itself
    # a user can be taken possession of — the node's key signed the grant, so
    # the machine's operator has authorized the hand-over.
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    node_name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    user_name = clean_string(data.get("user", ""), MAX_NODE_NAME).strip().lower()
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    if not valid_node_name(node_name) or not valid_node_name(user_name):
        return json_response({"error": "invalid_request"}, status=400)
    node_bi, node_rec = await _account_row(env, node_name)
    if not node_rec or node_rec.get("status") != "active":
        return json_response({"error": "no_such_node"}, status=404)
    pubkey = node_rec.get("pubkey", "")
    if not pubkey or not _ts_ok(ts):
        return json_response({"error": "unauthorized"}, status=401)
    canonical = ("forkmesh-link-grant-v1\n" + node_name + "\n" + ts).encode()
    if not await ed25519_verify(pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)
    if node_name == user_name:
        # The browser is logged in as this very node's account: nothing to
        # attach, it already belongs to itself.
        return json_response({"ok": True, "linked": True, "alreadyLinked": True,
                              "selfAccount": True, "nodeId": node_name,
                              "user": user_name,
                              "nodes": _owned_nodes(node_rec)})
    _, user_rec = await _account_row(env, user_name)
    if not user_rec or user_rec.get("status") != "active":
        return json_response({"error": "no_such_user"}, status=404)
    if _account_kind(user_rec) != "user":
        # Only an account that can log in can own nodes; a bare node session in
        # the browser can't take possession of another node.
        return json_response({"error": "not_a_user"}, status=403)
    if node_rec.get("owner") == user_name:
        return json_response({"ok": True, "linked": True, "alreadyLinked": True,
                              "nodeId": node_name, "user": user_name,
                              "nodes": _owned_nodes(user_rec)})
    # Burn the grant before linking so it is strictly one-time even if the node
    # is unlinked again inside the signature's freshness window. Parked in
    # link_codes keyed on the full grant; rows age out like installer codes.
    grant_bi = await blind_index(env, "grant:" + node_name + ":" + ts + ":" +
                                 signature)
    now = int(Date.now())
    row = await d1_first(
        env, "SELECT data, ts FROM link_codes WHERE code_bi=?", grant_bi)
    if row:
        return json_response({"error": "grant_used"}, status=409)
    encrypted = await encrypt_row(env, {"grant": node_name})
    await d1_run(
        env,
        "INSERT INTO link_codes (code_bi, data, ts) VALUES (?,?,?) "
        "ON CONFLICT(code_bi) DO UPDATE SET data=excluded.data, ts=excluded.ts",
        grant_bi, encrypted, now)
    await _link_node_to_user(env, node_name, node_bi, node_rec, user_name)
    _, fresh_user = await _account_row(env, user_name)
    return json_response({"ok": True, "linked": True, "nodeId": node_name,
                          "user": user_name,
                          "nodes": _owned_nodes(fresh_user or user_rec)})


async def _login_locked_until(env, id_bi):
    # Returns the lock-expiry ms if the identifier is currently locked, else 0.
    row = await d1_first(
        env, "SELECT locked_until FROM login_attempts WHERE id_bi=?", id_bi)
    if not row:
        return 0
    try:
        locked = int(row.get("locked_until") or 0)
    except (TypeError, ValueError):
        return 0
    return locked if locked > int(Date.now()) else 0


async def _login_record_fail(env, id_bi):
    # Atomically increment/reset one source or source+identifier budget. The
    # returned lock applies only to subsequent *failed* attempts; correct
    # credentials are always verified and can clear the budget, preventing an
    # attacker from locking a known victim out by name alone.
    now = int(Date.now())
    row = await d1_first(
        env,
        "INSERT INTO login_attempts (id_bi, fails, first_fail_ts, locked_until) "
        "VALUES (?,1,?,0) ON CONFLICT(id_bi) DO UPDATE SET "
        "fails=CASE WHEN ?-login_attempts.first_fail_ts>? "
        "THEN 1 ELSE login_attempts.fails+1 END,"
        "first_fail_ts=CASE WHEN ?-login_attempts.first_fail_ts>? "
        "THEN ? ELSE login_attempts.first_fail_ts END,"
        "locked_until=CASE WHEN "
        "(CASE WHEN ?-login_attempts.first_fail_ts>? "
        "THEN 1 ELSE login_attempts.fails+1 END)>=? "
        "THEN ? ELSE 0 END "
        "RETURNING fails,first_fail_ts,locked_until",
        id_bi,
        now,
        now,
        LOGIN_FAIL_WINDOW_MS,
        now,
        LOGIN_FAIL_WINDOW_MS,
        now,
        now,
        LOGIN_FAIL_WINDOW_MS,
        LOGIN_MAX_FAILS,
        now + LOGIN_LOCKOUT_MS,
    )
    return {
        "fails": int((row or {}).get("fails") or 1),
        "lockedUntil": int((row or {}).get("locked_until") or 0),
    }


async def _login_attempt_keys(env, request, identifier):
    source = _transient_client_address(request)
    source_bi = await blind_index(env, source) if source else ""
    keys = []
    if source_bi:
        keys.append(await blind_index(
            env, "login-source:" + source_bi))
        keys.append(await blind_index(
            env, "login-pair:" + source_bi + ":" + identifier))
    else:
        # Local/self-hosted requests without edge address metadata retain a
        # bounded identifier budget, but valid credentials still bypass it.
        keys.append(await blind_index(env, "login-local:" + identifier))
    return keys


async def _login_failure_response(env, attempt_keys, error):
    locked_until = 0
    highest_fail_count = 0
    for attempt_key in attempt_keys:
        result = await _login_record_fail(env, attempt_key)
        if isinstance(result, dict):
            locked_until = max(
                locked_until, int(result.get("lockedUntil") or 0))
            highest_fail_count = max(
                highest_fail_count, int(result.get("fails") or 0))
        else:
            # Compatibility with an older/local rate-limit adapter.
            locked_until = max(locked_until, int(result or 0))
    now = int(Date.now())
    if locked_until > now:
        retry_ms = max(1000, locked_until - now)
    elif highest_fail_count >= 3:
        # Progressive source/pair backoff starts before the hard ceiling. This
        # response is emitted only after credentials have failed verification;
        # a subsequent correct password is still checked immediately.
        retry_ms = min(
            60 * 1000,
            1000 * (2 ** min(6, highest_fail_count - 3)),
        )
    else:
        retry_ms = 0
    if retry_ms:
        return json_response(
            {"error": "too_many_attempts", "retryAfterMs": retry_ms},
            status=429,
            extra_headers={
                "Retry-After": str(max(1, (retry_ms + 999) // 1000))
            },
        )
    return json_response({"error": error}, status=401)


async def _login_clear(env, id_bi):
    await d1_run(env, "DELETE FROM login_attempts WHERE id_bi=?", id_bi)


DESKTOP_NODE_CAPABILITIES = "browse,comment,submit_issue,submit_pr,host_repo,mirror_repo,publish_repo,owner_sign"
CLIENT_CAPABILITIES = "browse,comment,submit_issue,submit_pr"
CONTRIBUTION_KEY_PROOF_CAPABILITY = "contribution_key_proof"


def _device_bind_canonical(account, pubkey, timestamp):
    account = account.strip().lower() if isinstance(account, str) else ""
    if not valid_node_name(account) or not valid_node_pubkey(pubkey):
        raise ValueError("invalid device bind identity")
    if (not isinstance(timestamp, str) or not timestamp.isdigit()
            or len(timestamp) > 16 or str(int(timestamp)) != timestamp):
        raise ValueError("invalid device bind timestamp")
    return (
        "forkmesh-device-bind-v1\n" + account + "\n" + pubkey + "\n"
        + timestamp
    ).encode()


async def _device_proven_user_bis(env, pubkey):
    rows = await d1_all(
        env,
        """WITH proven_device_users(user_bi) AS (
               SELECT COALESCE(NULLIF(user_bi, ''), node_bi)
                 FROM nodes WHERE pubkey=?
               UNION ALL
               SELECT COALESCE(NULLIF(owner_node.user_bi, ''),
                               account_devices.account_bi)
                 FROM account_devices
                LEFT JOIN nodes AS owner_node
                   ON owner_node.node_bi=account_devices.account_bi
                WHERE account_devices.pubkey=?
                  AND instr(',' || account_devices.capabilities || ',',
                            ',contribution_key_proof,') > 0
             )
             SELECT DISTINCT user_bi FROM proven_device_users
              WHERE user_bi IS NOT NULL AND user_bi != ''""",
        pubkey, pubkey,
    )
    return {row.get("user_bi") for row in rows if row.get("user_bi")}


async def _device_retire_unproven_claims(env, account_bi, pubkey):
    await d1_run(
        env,
        "DELETE FROM account_devices WHERE pubkey=? AND account_bi!=? "
        "AND instr(',' || capabilities || ',', "
        "',contribution_key_proof,')=0",
        pubkey, account_bi,
    )


async def _register_account_device(
        env, account_bi, pubkey, kind="desktop_node", label="",
        proof_verified=False, target_user_bi=None):
    if not account_bi or not pubkey:
        return None
    device_bi = await blind_index(env, account_bi + ":" + pubkey)
    now = int(Date.now())
    capabilities = DESKTOP_NODE_CAPABILITIES if kind == "desktop_node" else CLIENT_CAPABILITIES
    if proof_verified:
        capabilities += "," + CONTRIBUTION_KEY_PROOF_CAPABILITY
    base_args = (
        device_bi, account_bi, pubkey, kind, label, capabilities, now, now)
    if proof_verified:
        target_user_bi = target_user_bi or account_bi
        await d1_run(
            env,
            """INSERT INTO account_devices
                 (device_bi, account_bi, pubkey, kind, label, capabilities,
                  enabled, created_at, last_seen, revoked_at)
                 SELECT ?, ?, ?, ?, ?, ?, 1, ?, ?, 0
                  WHERE NOT EXISTS (
                    SELECT 1 FROM nodes
                     WHERE pubkey=?
                       AND COALESCE(NULLIF(user_bi, ''), node_bi) != ?)
                    AND NOT EXISTS (
                    SELECT 1 FROM account_devices AS proven_claim
                    LEFT JOIN nodes AS claim_owner
                      ON claim_owner.node_bi=proven_claim.account_bi
                     WHERE proven_claim.pubkey=?
                       AND instr(',' || proven_claim.capabilities || ',',
                                 ',contribution_key_proof,') > 0
                       AND COALESCE(NULLIF(claim_owner.user_bi, ''),
                                    proven_claim.account_bi) != ?)
                 /* atomic_device_proof_claim */
                 ON CONFLICT(device_bi) DO UPDATE SET
                   last_seen=excluded.last_seen,
                   capabilities=excluded.capabilities,
                   enabled=CASE WHEN account_devices.revoked_at=0
                                THEN 1 ELSE account_devices.enabled END""",
            *base_args, pubkey, target_user_bi, pubkey, target_user_bi,
        )
    else:
        await d1_run(
            env,
            """INSERT INTO account_devices
                 (device_bi, account_bi, pubkey, kind, label, capabilities,
                  enabled, created_at, last_seen, revoked_at)
                 VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?, 0)
                 ON CONFLICT(device_bi) DO UPDATE SET
                   last_seen=excluded.last_seen,
                   capabilities=excluded.capabilities,
                   enabled=CASE WHEN account_devices.revoked_at=0
                                THEN 1 ELSE account_devices.enabled END""",
            *base_args,
        )
    return {"id": device_bi[:16], "kind": kind, "pubkey": pubkey,
            "capabilities": capabilities.split(",")}


async def _account_device_for_pubkey(env, account_bi, pubkey):
    if not account_bi or not pubkey:
        return None
    row = await d1_first(
        env,
        """SELECT device_bi, pubkey, kind, label, capabilities, enabled, last_seen, revoked_at
             FROM account_devices WHERE account_bi=? AND pubkey=?""",
        account_bi, pubkey,
    )
    return row


async def _account_devices_list(env, account_bi):
    rows = await d1_all(
        env,
        """SELECT device_bi, pubkey, kind, label, capabilities, enabled, last_seen, revoked_at
             FROM account_devices WHERE account_bi=? ORDER BY created_at ASC""",
        account_bi,
    )
    out = []
    for row in rows:
        caps = clean_string(row.get("capabilities", ""), 512)
        out.append({
            "id": clean_string(row.get("device_bi", ""), 128)[:16],
            "pubkey": clean_string(row.get("pubkey", ""), 120),
            "kind": clean_string(row.get("kind", ""), 40),
            "label": clean_string(row.get("label", ""), 120),
            "capabilities": [c for c in caps.split(",") if c],
            "enabled": bool(row.get("enabled")) and not bool(row.get("revoked_at")),
            "lastSeen": int(row.get("last_seen") or 0),
        })
    return out


def _with_session_capabilities(payload, *, session_kind, device_kind="", key_matched=False,
                               desktop_capable=False, capabilities=None):
    caps = capabilities or (DESKTOP_NODE_CAPABILITIES.split(",") if desktop_capable else CLIENT_CAPABILITIES.split(","))
    payload["sessionKind"] = session_kind
    payload["deviceKind"] = device_kind
    payload["deviceKeyMatched"] = bool(key_matched)
    payload["desktopCapable"] = bool(desktop_capable)
    payload["capabilities"] = caps
    payload["canHost"] = "host_repo" in caps
    payload["canPublish"] = "publish_repo" in caps
    payload["canOwnerSign"] = "owner_sign" in caps
    return payload


def _is_local_demo_request(request):
    try:
        parsed = urlparse(request.url)
        return (
            parsed.scheme in ("http", "https")
            and parsed.hostname in ("localhost", "127.0.0.1", "::1")
        )
    except Exception:
        return False


async def _ensure_local_demo_account(
        env, request, identifier, password):
    if (
        not _is_local_demo_request(request)
        or identifier != LOCAL_DEMO_EMAIL
        or password != LOCAL_DEMO_PASSWORD
    ):
        return
    email_bi = await blind_index(env, LOCAL_DEMO_EMAIL)
    name_bi = await blind_index(env, LOCAL_DEMO_NAME)
    row = await d1_first(
        env,
        "SELECT user_bi,data,is_admin FROM users WHERE email_bi=?",
        email_bi,
    )
    if row and row.get("user_bi") != name_bi:
        return
    record = await decrypt_row(env, row.get("data")) if row else None
    valid = bool(
        record
        and record.get("name") == LOCAL_DEMO_NAME
        and record.get("status") == "active"
        and record.get("pass_hash")
        and await verify_password(
            LOCAL_DEMO_PASSWORD,
            record.get("pass_salt", ""),
            record.get("pass_hash", ""),
        )
    )
    if valid:
        if not bool(int(row.get("is_admin") or 0)):
            await d1_run(
                env,
                "UPDATE users SET is_admin=1 WHERE user_bi=?",
                name_bi,
            )
        return
    salt, password_hash = await hash_password(LOCAL_DEMO_PASSWORD)
    await _save_account_full(
        env,
        name_bi,
        {
            "name": LOCAL_DEMO_NAME,
            "email": LOCAL_DEMO_EMAIL,
            "kind": "user",
            "status": "active",
            "pass_salt": salt,
            "pass_hash": password_hash,
            "email_verified": True,
            "created_at": int(Date.now()),
        },
        email_bi=email_bi,
        ip_bi=to_js(None),
        is_admin=1,
    )


async def _account_login(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)

    # Log in by email or node name (the "universal access" credential).
    identifier = clean_string(
        data.get("nodeName", "") or data.get("identifier", "") or
        data.get("email", ""), 254).strip().lower()
    password = (data.get("password", "") or "")[:256]
    totp = clean_string(data.get("totp", ""), 10)
    pubkey = clean_string(data.get("pubkey", ""), 120)
    device_ts = clean_string(data.get("deviceTs", ""), 20)
    device_sig = clean_string(data.get("deviceSig", ""), 200)

    await _ensure_local_demo_account(
        env, request, identifier, password)

    # Failed attempts consume atomic source and source+identifier budgets. They
    # never block verification of correct credentials, so an attacker cannot
    # lock a known victim out merely by submitting their identifier.
    id_bi = await blind_index(env, identifier) if identifier else ""
    if not id_bi:
        return json_response({"error": "invalid_credentials"}, status=401)
    attempt_keys = await _login_attempt_keys(env, request, identifier)

    rec = None
    if "@" in identifier:
        email_bi = await blind_index(env, identifier)
        row = await d1_first(
            env, "SELECT data FROM users WHERE email_bi=?", email_bi)
        if row:
            rec = await decrypt_row(env, row["data"])
    elif valid_node_name(identifier):
        _, rec = await _account_row(env, identifier)

    if rec is not None and rec.get("status") != "active":
        if rec.get("pass_hash") and await verify_password(
                password, rec.get("pass_salt", ""), rec.get("pass_hash", "")):
            for attempt_key in attempt_keys:
                await _login_clear(env, attempt_key)
            return json_response({"error": "account_disabled"}, status=403)

    ok = (rec is not None and rec.get("status") == "active" and
          rec.get("pass_hash") and
          await verify_password(password, rec.get("pass_salt", ""),
                                rec.get("pass_hash", "")))
    if not ok:
        return await _login_failure_response(
            env, attempt_keys, "invalid_credentials")
    # TOTP is only enforced for accounts that have enrolled it. A bad code counts
    # toward the lockout but the password was already correct, so the distinct
    # error here doesn't aid account enumeration.
    if rec.get("totp_enrolled"):
        if not await totp_verify(rec.get("totp_secret", ""), totp):
            return await _login_failure_response(
                env, attempt_keys, "bad_totp")
    for attempt_key in attempt_keys:
        await _login_clear(env, attempt_key)

    # Multi-device account model: password/TOTP authenticates the human account;
    # a supplied pubkey identifies/registers this particular desktop node. Any
    # number of desktop nodes may be enabled for the same account. The legacy
    # accounts.pubkey remains as the primary/first desktop key for compatibility,
    # but a different registered desktop key is no longer a login failure.
    name_bi = await blind_index(env, rec.get("name", ""))
    device = None
    desktop_capable = False
    device_kind = ""
    if pubkey:
        account_name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
        try:
            device_canonical = _device_bind_canonical(
                account_name, pubkey, device_ts)
        except ValueError:
            device_canonical = b""
        if (not device_canonical or not device_sig or not _ts_ok(device_ts)
                or not await ed25519_verify(
                    pubkey, device_sig, device_canonical)):
            return json_response(
                {"error": "device_proof_required"}, status=401)
        owner_row = await d1_first(
            env, "SELECT user_bi FROM nodes WHERE node_bi=?", name_bi)
        target_user_bi = (owner_row or {}).get("user_bi") or name_bi
        proven_users = await _device_proven_user_bis(env, pubkey)
        if any(user_bi != target_user_bi for user_bi in proven_users):
            return json_response({"error": "device_key_conflict"}, status=409)
        await _device_retire_unproven_claims(env, name_bi, pubkey)
        await _register_account_device(
            env, name_bi, pubkey, "desktop_node",
            clean_string(data.get("deviceLabel", ""), 120),
            proof_verified=True, target_user_bi=target_user_bi)
        device = await _account_device_for_pubkey(env, name_bi, pubkey)
        final_proven_users = await _device_proven_user_bis(env, pubkey)
        device_caps = clean_string(
            (device or {}).get("capabilities", ""), 512).split(",")
        if (not device
                or CONTRIBUTION_KEY_PROOF_CAPABILITY not in device_caps
                or target_user_bi not in final_proven_users
                or any(user_bi != target_user_bi
                       for user_bi in final_proven_users)):
            return json_response({"error": "device_key_conflict"}, status=409)
        if not rec.get("pubkey"):
            rec["pubkey"] = pubkey
            await _save_account(env, name_bi, rec)
        try:
            await touch_registered_node(env, name_bi, rec)
        except Exception:
            pass
        caps = device.get("capabilities", DESKTOP_NODE_CAPABILITIES) if device else DESKTOP_NODE_CAPABILITIES
        if isinstance(caps, str):
            caps = [c for c in caps.split(",") if c]
        enabled = bool(device.get("enabled", True)) and not bool(device.get("revoked_at", 0)) if device else True
        primary_key_matched = pubkey == clean_string(rec.get("pubkey", ""), 120)
        desktop_capable = primary_key_matched and enabled and "owner_sign" in caps
        session_caps = caps if desktop_capable else CLIENT_CAPABILITIES.split(",")
        device_kind = device.get("kind", "desktop_node") if device else "desktop_node"
        payload = await _account_public_payload(
            env, rec,
            session_device_label=_account_session_device_label(
                request, desktop=True),
            session_client_ip=_account_session_client_ip(request))
        payload = _with_session_capabilities(
            payload, session_kind="desktop_node", device_kind=device_kind,
            key_matched=True, desktop_capable=desktop_capable,
            capabilities=session_caps)
        return json_response(
            payload,
            extra_headers={
                "Set-Cookie": _account_session_cookie(payload["sessionToken"])
            },
        )

    payload = await _account_public_payload(
        env, rec,
        session_device_label=_account_session_device_label(request),
        session_client_ip=_account_session_client_ip(request))
    payload = _with_session_capabilities(
        payload, session_kind="account", device_kind="web_or_mobile",
        key_matched=False, desktop_capable=False)
    return json_response(
        payload,
        extra_headers={
            "Set-Cookie": _account_session_cookie(payload["sessionToken"])
        },
    )


async def _account_rotate(env, request):
    """Rotate an active account's bound Ed25519 key after old-key approval.

    The desktop client may omit nodeName in its rotation record; in that case
    the relay resolves the account by oldPubkey, or treats an already-finished
    newPubkey binding plus prev_pubkeys entry as an idempotent retry.
    """
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)

    name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    old_pubkey = clean_string(data.get("oldPubkey", ""), 120)
    new_pubkey = clean_string(data.get("newPubkey", ""), 120)
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("signature") or data.get("sig", ""), 200)

    if name:
        if not valid_node_name(name):
            return json_response({"error": "invalid_node_id"}, status=400)
    if not valid_node_pubkey(old_pubkey) or not valid_node_pubkey(new_pubkey):
        return json_response({"error": "invalid_pubkey"}, status=400)
    if not _ts_ok(ts):
        return json_response({"error": "stale_request"}, status=401)
    canonical = ("forkmesh-rotate-v1\n" + old_pubkey + "\n" +
                 new_pubkey + "\n" + str(ts)).encode()

    if name:
        name_bi, rec = await _account_row(env, name)
    else:
        name_bi, rec = await _account_row_by_pubkey(env, old_pubkey)
        if not rec:
            _, next_rec = await _account_row_by_pubkey(env, new_pubkey)
            next_name = clean_string(
                (next_rec or {}).get("name", ""), MAX_NODE_NAME).lower()
            next_current_pubkey = clean_string(
                (next_rec or {}).get("pubkey", ""), 120)
            next_prev_pubkeys = (next_rec or {}).get("prev_pubkeys")
            if (next_rec and next_rec.get("status") == "active" and
                    next_current_pubkey == new_pubkey and
                    isinstance(next_prev_pubkeys, list) and
                    old_pubkey in next_prev_pubkeys):
                if not valid_node_name(next_name):
                    return json_response({"error": "invalid_node_id"}, status=400)
                if not await ed25519_verify(old_pubkey, signature, canonical):
                    return json_response({"error": "bad_signature"}, status=401)
                return json_response(
                    {"ok": True, "nodeName": next_name, "pubkey": new_pubkey})
        if rec:
            name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
            if not valid_node_name(name):
                return json_response({"error": "invalid_node_id"}, status=400)
    if not rec or rec.get("status") != "active":
        return json_response({"error": "no_account"}, status=404)

    current_pubkey = clean_string(rec.get("pubkey", ""), 120)
    if current_pubkey == new_pubkey:
        return json_response({"ok": True, "nodeName": name, "pubkey": new_pubkey})
    if current_pubkey != old_pubkey:
        return json_response({"error": "not_bound"}, status=403)

    if not await ed25519_verify(old_pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)

    existing_bi, _ = await _account_row_by_pubkey(env, new_pubkey)
    if existing_bi and existing_bi != name_bi:
        return json_response({"error": "pubkey_taken"}, status=409)

    prev_pubkeys = rec.get("prev_pubkeys")
    if not isinstance(prev_pubkeys, list):
        prev_pubkeys = []
    if old_pubkey not in prev_pubkeys:
        prev_pubkeys.append(old_pubkey)
    rec["pubkey"] = new_pubkey
    rec["prev_pubkeys"] = prev_pubkeys
    rec["rotated_at"] = int(Date.now())
    await _save_account(env, name_bi, rec)
    await _account_revoke_sessions(env, name_bi)
    return json_response({"ok": True, "nodeName": name, "pubkey": new_pubkey})


async def _account_logout(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    token, _ = _request_account_session_token(request, data)
    account_bi, _rec, session_id = await _account_session_lookup(
        env, token, touch=False)
    if account_bi and session_id:
        await _account_revoke_sessions(env, account_bi, session_id)
    return json_response(
        {"ok": True},
        extra_headers={"Set-Cookie": _clear_account_session_cookie()},
        cache_control="no-store, max-age=0, must-revalidate",
    )


async def _account_last_seen(env, account_bi, floor_ts=0):
    """Newest activity stamp across this account's devices and nodes.

    Session stamps are already in hand from the listing read, so they come in as
    floor_ts; the devices/nodes maxima share one statement to keep the account
    screen off the multi-query path that overloaded the free plan.
    """
    floor_ts = int(floor_ts or 0)
    row = await d1_first(
        env,
        "SELECT MAX(seen) AS seen FROM ("
        "SELECT COALESCE(MAX(last_seen),0) AS seen FROM account_devices "
        "WHERE account_bi=? UNION ALL "
        "SELECT COALESCE(MAX(last_seen),0) FROM nodes WHERE user_bi=?)",
        account_bi, account_bi,
    )
    try:
        return max(floor_ts, int((row or {}).get("seen") or 0))
    except (TypeError, ValueError):
        return floor_ts


async def _account_sessions(env, request, target_session_id=""):
    """List or revoke this account's own sessions.

    The listing is strictly self-scoped: it is reachable only with a live
    session token for the account whose rows it returns, so the sign-in address
    on each row is visible to that owner alone.
    """
    method = method_name(request)
    token, cookie_auth = _request_account_session_token(request, {})
    if (
        cookie_auth
        and method == "DELETE"
        and not _request_same_origin(request)
    ):
        token = ""
    account_bi, rec, current_session_id = await _account_session_lookup(
        env, token, touch=method == "GET")
    if not account_bi or not rec or not current_session_id:
        return json_response(
            {"error": "invalid_session"}, status=401,
            cache_control="no-store, max-age=0, must-revalidate")

    now = int(Date.now())
    actor = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
    if method == "GET" and not target_session_id:
        rows = await d1_all(
            env,
            "SELECT session_id,created_at,last_seen_at,expires_at,"
            "device_label,client_ip "
            "FROM account_sessions WHERE account_bi=? AND revoked_at=0 "
            "AND expires_at>? ORDER BY last_seen_at DESC,created_at DESC "
            "LIMIT ?",
            account_bi, now, ACCOUNT_SESSION_MAX_ACTIVE,
        )
        sessions = []
        for row in rows or []:
            session_id = clean_string(row.get("session_id", ""), 64)
            if not re.fullmatch(r"[A-Za-z0-9_-]{24,64}", session_id):
                continue
            sessions.append({
                "id": session_id,
                "deviceLabel": (
                    clean_string(row.get("device_label", ""), 80)
                    or "Unknown device"
                ),
                "ipAddress": clean_string(row.get("client_ip", ""), 64),
                "createdAt": int(row.get("created_at") or 0),
                "lastSeenAt": int(row.get("last_seen_at") or 0),
                "expiresAt": int(row.get("expires_at") or 0),
                "current": session_id == current_session_id,
            })
        return json_response(
            {
                "ok": True,
                "sessions": sessions,
                # Account-level activity for the settings screen: when this
                # account was last active anywhere (sessions, linked devices,
                # nodes) and when it was last emailed, with the send outcome.
                "account": {
                    "lastSeenAt": await _account_last_seen(
                        env, account_bi,
                        max([s["lastSeenAt"] for s in sessions] or [0])),
                    **_account_email_activity(rec),
                },
                "privacyNotice": (
                    "Only you can see this list. Each row shows a broad device "
                    "category, the address the sign-in came from, and session "
                    "timestamps. Raw user agents are never stored, and no "
                    "other account can read these rows."
                ),
            },
            cache_control="no-store, max-age=0, must-revalidate",
        )

    if method != "DELETE":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"allow": "GET, DELETE"})

    target_session_id = clean_string(target_session_id, 64).strip()
    revoke_current = False
    if target_session_id == "others":
        await d1_run(
            env,
            "UPDATE account_sessions SET revoked_at=? "
            "WHERE account_bi=? AND session_id<>? AND revoked_at=0",
            now, account_bi, current_session_id,
        )
        audit_target = "all-other-devices"
        audit_scope = "others"
    elif target_session_id == "all":
        # "Log out everywhere" also drops the calling device, so a lost or
        # shared browser can be cleared in one action.
        await _account_revoke_sessions(env, account_bi)
        revoke_current = True
        audit_target = "all-devices"
        audit_scope = "all"
    else:
        if not re.fullmatch(r"[A-Za-z0-9_-]{24,64}", target_session_id):
            return json_response(
                {"error": "invalid_session_id"}, status=400,
                cache_control="no-store, max-age=0, must-revalidate")
        owned = await d1_first(
            env,
            "SELECT session_id FROM account_sessions "
            "WHERE account_bi=? AND session_id=? AND revoked_at=0 "
            "AND expires_at>?",
            account_bi, target_session_id, now,
        )
        if not owned:
            return json_response(
                {"error": "session_not_found"}, status=404,
                cache_control="no-store, max-age=0, must-revalidate")
        await _account_revoke_sessions(
            env, account_bi, target_session_id)
        revoke_current = target_session_id == current_session_id
        audit_target = target_session_id
        audit_scope = "current" if revoke_current else "device"

    await _audit_sensitive_action(
        env, actor, "account.session_revoke", "account_session",
        audit_target, "success", {"scope": audit_scope})
    headers = (
        {"Set-Cookie": _clear_account_session_cookie()}
        if revoke_current else None
    )
    return json_response(
        {"ok": True, "currentRevoked": revoke_current},
        extra_headers=headers,
        cache_control="no-store, max-age=0, must-revalidate",
    )


async def _account_admin_session(env, request):
    # Re-mint the HttpOnly `forkmesh_admin` page cookie from a still-valid
    # account session token, so an admin the app already treats as logged in
    # (localStorage session + 30-day forkmesh_session marker) doesn't have to
    # retype their password just to open the admin dashboard. The 12h admin
    # cookie is set only by _account_login and lapses long before the login
    # session does, which is why the admin page used to bounce a logged-in
    # admin back to /login (adhoc #163). The session token — issued only to an
    # already-authenticated caller and refreshed on every account poll — proves
    # identity here; is_admin gates the grant, so this never escalates.
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    token, cookie_auth = _request_account_session_token(request, data)
    if cookie_auth and not _request_same_origin(request):
        token = ""
    name = await _account_session_token_name(env, token)
    if not name or not await _is_admin(env, name):
        return json_response(
            {"error": "not_admin"},
            status=403,
            extra_headers={"Set-Cookie": _clear_account_session_cookie()},
            cache_control="no-store, max-age=0, must-revalidate",
        )
    admin_path = _admin_path(env)
    admin_url = ("/" + admin_path + "?admin=" + quote(name)) if admin_path else ""
    return json_response(
        {"ok": True, "nodeName": name, "adminUrl": admin_url},
        extra_headers={"Set-Cookie": _account_session_cookie(token)},
        cache_control="no-store, max-age=0, must-revalidate",
    )


def _random_bytes(n):
    return bytes(js_crypto.getRandomValues(Uint8Array.new(n)).to_py())


# A running node calls this on an interval to stay eligible for the reward
# split. Signed with the account's key so only the key holder can mark its node
# online; optionally updates the payout Solana address.
async def _account_heartbeat(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    solana = clean_string(data.get("solana", ""), 64)
    avatar_png, avatar_error = clean_avatar_png(data.get("avatarPng", ""))
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    if avatar_error:
        status = 413 if avatar_error == "avatar_too_large" else 400
        return json_response({"error": avatar_error}, status=status)
    name_bi, rec = await _account_row(env, name)
    if not rec or rec.get("status") != "active":
        return json_response({"ok": True, "online": False})
    pubkey = rec.get("pubkey", "")
    if not pubkey or not _ts_ok(ts):
        return json_response({"error": "unauthorized"}, status=401)
    try:
        signature_version = int(data.get("signatureVersion", 1) or 1)
    except (TypeError, ValueError):
        signature_version = 0
    wallet_mutation = bool(
        solana and SOLANA_RE.match(solana)
        and rec.get("solana") != solana)
    if wallet_mutation and signature_version != 2:
        return json_response({
            "error": "wallet_binding_signature_required",
            "requiredSignatureVersion": 2,
        }, status=426)
    canonical = (
        ("forkmesh-heartbeat-v2\n" + name + "\n" + solana + "\n" + ts)
        if signature_version == 2
        else ("forkmesh-heartbeat-v1\n" + name + "\n" + ts)
    ).encode()
    if not await ed25519_verify(pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)

    # Issue #346: the node itself is the only thing that knows when its local
    # Claude Code usage window refilled after running out, so it rides this
    # already-signed heartbeat to ask for a notification (opt-in on the
    # desktop side). Not part of the signed canonical string, same as solana/
    # avatarPng above — worst case a stale replay re-flags a notification the
    # recipient already has, not a forgeable action on someone else's account.
    credits_kind = clean_string(data.get("creditsRefilled", ""), 10)
    if credits_kind in ("5h", "weekly"):
        window = "5-hour" if credits_kind == "5h" else "weekly"
        await enqueue_notification(
            env, name, "credits_refilled",
            "Claude Code credits refilled",
            body=("Your " + window + " usage window has reset — Claude Code "
                  "credits are available again."),
            source="credits_refilled",
            dedupe="credits_refilled:" + credits_kind,
        )

    # Nodes can update the email preferences for the user account that owns
    # them. A linked owner controls all owned-node digest behavior from one
    # account record; unowned nodes update themselves.
    prefs_bi = name_bi
    prefs_rec = rec
    owner = clean_string(rec.get("owner", ""), MAX_NODE_NAME).lower()
    if owner:
        owner_bi, owner_rec = await _account_row(env, owner)
        if owner_rec and owner_rec.get("status") == "active":
            prefs_bi = owner_bi
            prefs_rec = owner_rec
    prefs_changed = False
    if "emailNotifications" in data:
        email_notifications = bool(data.get("emailNotifications"))
        if bool(prefs_rec.get("email_notifications", True)) != email_notifications:
            if email_notifications:
                prefs_rec.pop("email_notifications", None)
            else:
                prefs_rec["email_notifications"] = False
            prefs_changed = True
    if "notificationPreferences" in data:
        cleaner = globals().get("_clean_notification_preferences")
        if callable(cleaner):
            prefs = cleaner(data.get("notificationPreferences"), prefs_rec)
        elif isinstance(data.get("notificationPreferences"), dict):
            prefs = dict(data.get("notificationPreferences"))
        else:
            prefs = dict(prefs_rec.get("notification_preferences") or {})
        if prefs_rec.get("notification_preferences", {}) != prefs:
            prefs_rec["notification_preferences"] = prefs
            prefs_changed = True
    if prefs_changed:
        await _save_account(env, prefs_bi, prefs_rec)
        if prefs_bi == name_bi:
            rec = prefs_rec

    # Keep the payout address current if the node sent a valid one.
    if wallet_mutation:
        rec["solana"] = solana
        await _save_account(env, name_bi, rec)
        await _audit_sensitive_action(
            env, name, "wallet.payout_address_bind", "account", name,
            "success", {"signatureVersion": signature_version})
    if avatar_png and rec.get("avatar_png") != avatar_png:
        rec["avatar_png"] = avatar_png
        rec["avatar_updated_at"] = int(Date.now())
        await _save_account(env, name_bi, rec)

    await d1_run(
        env,
        "INSERT INTO account_presence (name_bi, ts) VALUES (?, ?) "
        "ON CONFLICT(name_bi) DO UPDATE SET ts=excluded.ts",
        name_bi, int(Date.now()),
    )
    try:
        await touch_registered_node(env, name_bi, rec)
    except Exception:
        pass

    # Report this node's payout-wallet balance in the heartbeat reply so the
    # client doesn't have to poll Solana itself. We track the last public balance
    # seen; an increase means an incoming transfer arrived. This user-owned
    # balance is display metadata and never gates reward eligibility.
    wallet = rec.get("solana", "")
    balance_lamports = None
    balance_increased = False
    # Throttle the external Solana RPC to once per wallet per 5 minutes per
    # isolate: one subrequest on EVERY 60s heartbeat from every node was pure
    # overhead (donations are surfaced within minutes either way).
    now_ms = int(Date.now())
    # Keyed by account+wallet: accounts sharing a payout wallet must each
    # keep their own balance-change baseline.
    probe_key = str(name_bi) + ":" + wallet
    last_probe = _HEARTBEAT_BALANCE_PROBES.get(probe_key, 0)
    if (wallet and SOLANA_RE.match(wallet)
            and now_ms - last_probe >= HEARTBEAT_SOLANA_BALANCE_MIN_MS):
        _HEARTBEAT_BALANCE_PROBES[probe_key] = now_ms
        if len(_HEARTBEAT_BALANCE_PROBES) > 5000:
            _HEARTBEAT_BALANCE_PROBES.clear()
        try:
            balance_lamports = await asyncio.wait_for(
                _solana_balance_lamports(env, wallet),
                timeout=HEARTBEAT_SOLANA_BALANCE_TIMEOUT_MS / 1000,
            )
        except Exception:
            balance_lamports = None
        if balance_lamports is not None:
            prev = rec.get("last_balance_lamports")
            if isinstance(prev, int) and balance_lamports > prev:
                balance_increased = True
            if prev != balance_lamports:
                rec["last_balance_lamports"] = balance_lamports
                await _save_account(env, name_bi, rec)

    prefs_reader = globals().get("notification_email_preferences")
    if callable(prefs_reader):
        notification_preferences = prefs_reader(prefs_rec)
    else:
        notification_preferences = dict(
            prefs_rec.get("notification_preferences") or {})
    response = {"ok": True, "online": True,
                "hasPayoutAddress": bool(rec.get("solana")),
                "payoutCustody": "external-self-custodial-public-address",
                "payoutNotice": (
                    "The heartbeat shares a public payout address and optional "
                    "public balance only. ForkMesh holds no wallet key or user "
                    "funds, and balance never gates reward eligibility."
                ),
                "isAdmin": await _is_admin(env, name),
                "emailNotifications": prefs_rec.get("email_notifications") is not False,
                "notificationPreferences": notification_preferences}
    if balance_lamports is not None:
        response["balanceLamports"] = balance_lamports
        response["balanceFundsState"] = "user-owned-external-wallet"
        response["balanceIncreased"] = balance_increased
    # A pending website claim (adhoc #53) rides back on the signed heartbeat:
    # only the node's key holder ever sees the confirmation code, and the node
    # shows it on its own screen for the claiming user to type into the site.
    # Expired claims are cleaned off the record here.
    claim = _claim_pending(rec, int(Date.now()))
    if claim:
        response["claim"] = {"user": claim.get("user", ""),
                             "code": claim.get("code", "")}
    elif rec.get("claim_pending"):
        rec.pop("claim_pending", None)
        await _save_account(env, name_bi, rec)
    # An admin-initiated ownership takeover (adhoc #141) rides back the same
    # way: only the node's own signed heartbeat carries it, so only whoever is
    # actually logged into that machine ever sees the prompt.
    transfer = _transfer_pending(rec, int(Date.now()))
    if transfer:
        response["ownershipTransfer"] = {"admin": transfer.get("admin", "")}
    elif rec.get("ownership_transfer_pending"):
        rec.pop("ownership_transfer_pending", None)
        await _save_account(env, name_bi, rec)
    # Accepted peer mirror requests (issue #385) ride back on this node's own
    # signed heartbeat, the same rail as claim/ownership above: the desktop node
    # clones each repo it agreed to mirror. It reports the ids it has acted on in
    # `mirrorRequestsAck` (not part of the signed canonical, like creditsRefilled)
    # so an accepted request stops being redelivered once the node has it.
    ack_ids = data.get("mirrorRequestsAck")
    if isinstance(ack_ids, list) and rec.get("mirror_requests"):
        remaining = ack_mirror_requests(rec.get("mirror_requests"), ack_ids)
        if remaining != rec.get("mirror_requests"):
            rec["mirror_requests"] = remaining
            await _save_account(env, name_bi, rec)
    if rec.get("mirror_requests"):
        pending_mirrors = accepted_mirror_requests(rec.get("mirror_requests"))
        if pending_mirrors:
            response["mirrorRequests"] = pending_mirrors
    return json_response(response)


async def _mirroring_owners(env):
    # Set of owner names that actually mirror a repo for another node, used to
    # keep single-repo-only nodes out of reward consideration (issue #94). Best
    # effort: on any read error return None so callers keep their prior behaviour
    # (fail open) rather than starving every node of its share.
    try:
        rows = await d1_all(
            env, "SELECT data FROM repositories WHERE is_private = 0")
    except Exception:
        return None
    records = []
    for row in rows or []:
        rec = await decrypt_row(env, row.get("data"))
        if not rec:
            continue
        if rec.get("visibility") != "public":
            continue
        if _is_blocked_catalog_identity(env, rec.get("owner"), rec.get("name")):
            continue
        records.append(rec)
    return mirroring_owner_set(records)


async def _online_payout_addresses(env):
    # Deduplicated payout addresses of currently-online, active accounts that
    # actually mirror a repo for another node. A node hosting only its own
    # un-mirrored repos adds no redundancy, so it is left out of consideration
    # (issue #94). Stale presence rows self-heal here so the table stays bounded.
    cutoff = int(Date.now()) - ACCOUNT_PRESENCE_STALE_MS
    try:
        await d1_run(env, "DELETE FROM account_presence WHERE ts < ?", cutoff)
    except Exception:
        pass
    mirroring = await _mirroring_owners(env)
    rows = await d1_all(
        env, "SELECT name_bi FROM account_presence WHERE ts >= ? ORDER BY ts DESC",
        cutoff,
    )
    seen = set()
    addresses = []
    for r in rows:
        row = await d1_first(
            env, "SELECT name, data FROM nodes WHERE node_bi=?", r["name_bi"])
        if not row:
            continue
        rec = await decrypt_row(env, row["data"])
        if not rec or rec.get("status") != "active":
            continue
        owner = clean_string(row.get("name") or rec.get("name", ""), MAX_NODE_NAME)
        # Only nodes that mirror a repo shared with another node earn a share.
        if mirroring is not None and owner.lower() not in mirroring:
            continue
        solana = (rec.get("solana") or "").strip()
        if not solana or not SOLANA_RE.match(solana) or solana in seen:
            continue
        seen.add(solana)
        addresses.append(solana)
    # Federated rewards intentionally do not use this historical address-only
    # helper. They enter both randomized and instant plans exclusively through
    # _eligible_reward_snapshot's signed, fresh attestation path.
    return addresses


# --- Community reward-pool address (issue #308) ------------------------------
# A public configured address may receive voluntary contributions. The Worker
# reads its balance and prepares unsigned distribution intents; the instance
# owner's self-custodial desktop signer alone can authorize a transfer.
REWARD_CLUSTER_GENESIS_HASHES = {
    "mainnet-beta": "5eykt4UsFv8P8NJdTREpY1vzqKqZKvdpKuc147dw2N9d",
    "devnet": "EtWTRABZaYq6iMfeYKouRu166VU2xqa1wcaWoxPkrZBG",
    "testnet": "4uhcVJyU9pJkvQyS88uRDiswHXSCkY3zQawwpjk2NsNY",
}
REWARD_CANONICAL_RPC_HOSTS = {
    "api.mainnet-beta.solana.com": "mainnet-beta",
    "api.devnet.solana.com": "devnet",
    "api.testnet.solana.com": "testnet",
}


def _reward_network(env):
    value = clean_string(
        getattr(env, "COMMUNITY_REWARD_NETWORK", "mainnet-beta"), 32
    ).strip().lower()
    return value if value in REWARD_CLUSTER_GENESIS_HASHES else ""


def _reward_rpc_url(env):
    raw = clean_string(
        getattr(env, "COMMUNITY_REWARD_RPC_URL", ""), 500).strip()
    try:
        parsed = urlparse(raw)
    except Exception:
        return ""
    if (
        parsed.scheme.lower() != "https"
        or not parsed.hostname
        or parsed.username
        or parsed.password
        or parsed.query
        or parsed.fragment
    ):
        return ""
    network = _reward_network(env)
    canonical_network = REWARD_CANONICAL_RPC_HOSTS.get(
        parsed.hostname.lower().rstrip("."))
    if not network or (
        canonical_network is not None and canonical_network != network
    ):
        return ""
    return raw


class _RewardRpcEnvironment:
    """Narrow view that keeps the reward test network separate from legacy RPCs."""

    def __init__(self, env):
        self.SOLANA_NETWORK = _reward_network(env)
        self.SOLANA_RPC_URL = _reward_rpc_url(env)


async def _reward_solana_rpc(env, method, params):
    if not _reward_network(env) or not _reward_rpc_url(env):
        return None
    return await _solana_rpc(_RewardRpcEnvironment(env), method, params)


# Per-isolate memo of the reward-pool network proof. The proof is two Solana
# RPC round trips (getGenesisHash + getAccountInfo) whose answers are stable
# configuration facts — a cluster's genesis hash is immutable and the funded
# pool account does not stop existing — yet it used to run on EVERY
# /api/accounts/central-fund view. Public RPC endpoints rate-limit, so each
# transient 429/timeout surfaced as a 503 on the page (2026-07-24 error-log
# burst). A verified (network, rpc_url, address) triple is trusted for the
# fresh TTL without touching the RPC, and kept as a stale fallback when a
# re-proof attempt fails, bounded so a truly dead RPC still fails closed.
_REWARD_POOL_VERIFY_MEMO = {"key": None, "ts": 0}
REWARD_POOL_VERIFY_FRESH_MS = 60 * 60 * 1000
REWARD_POOL_VERIFY_STALE_MAX_MS = 24 * 60 * 60 * 1000


async def _reward_pool_network_verified(env, address):
    """Prove the RPC cluster and configured public pool account fail closed."""
    network = _reward_network(env)
    rpc_url = _reward_rpc_url(env)
    if (
        not network
        or not rpc_url
        or not address
        or not SOLANA_RE.match(address)
    ):
        return False
    memo_key = (network, rpc_url, address)
    now = int(Date.now())
    memo = _REWARD_POOL_VERIFY_MEMO
    if (
        memo["key"] == memo_key
        and now - memo["ts"] < REWARD_POOL_VERIFY_FRESH_MS
    ):
        return True
    genesis = await _reward_solana_rpc(env, "getGenesisHash", [])
    if (
        not isinstance(genesis, dict)
        or not hmac.compare_digest(
            str(genesis.get("result") or ""),
            REWARD_CLUSTER_GENESIS_HASHES[network],
        )
    ):
        # A wrong-cluster ANSWER is disqualifying and clears the fallback; a
        # missing answer (rate limit, timeout → None) is transient and may
        # still serve from the bounded stale window.
        if isinstance(genesis, dict):
            memo["key"] = None
            return False
        return bool(
            memo["key"] == memo_key
            and now - memo["ts"] < REWARD_POOL_VERIFY_STALE_MAX_MS
        )
    account = await _reward_solana_rpc(
        env,
        "getAccountInfo",
        [address, {"encoding": "base64", "commitment": "finalized"}],
    )
    if not isinstance(account, dict):
        return bool(
            memo["key"] == memo_key
            and now - memo["ts"] < REWARD_POOL_VERIFY_STALE_MAX_MS
        )
    result = account.get("result")
    verified = bool(
        isinstance(result, dict)
        and isinstance(result.get("value"), dict)
    )
    if verified:
        memo["key"] = memo_key
        memo["ts"] = now
    else:
        memo["key"] = None
    return verified


async def _reward_balance_lamports(env, address):
    if not address or not SOLANA_RE.match(address):
        return None
    response = await _reward_solana_rpc(env, "getBalance", [address])
    if not isinstance(response, dict):
        return None
    result = response.get("result")
    if not isinstance(result, dict):
        return None
    try:
        return int(result.get("value"))
    except (TypeError, ValueError):
        return None


async def _reward_public_entropy(env):
    response = await _reward_solana_rpc(
        env, "getLatestBlockhash", [{"commitment": "finalized"}])
    if not isinstance(response, dict):
        return ""
    try:
        return clean_string(
            response["result"]["value"]["blockhash"], 120).strip()
    except Exception:
        return ""


def _reward_config(env):
    return {
        "intervalMs": reward_policy.bounded_int(
            getattr(env, "REWARD_INTERVAL_MS", ""),
            CENTRAL_FUND_DISTRIBUTION_INTERVAL_MS,
            15 * 60 * 1000,
            24 * 60 * 60 * 1000,
        ),
        "jitterMs": reward_policy.bounded_int(
            getattr(env, "REWARD_JITTER_MAX_MS", ""),
            REWARD_DEFAULT_JITTER_MS,
            0,
            12 * 60 * 60 * 1000,
        ),
        "amountLamports": reward_policy.bounded_int(
            getattr(env, "REWARD_AMOUNT_LAMPORTS", ""),
            REWARD_DEFAULT_AMOUNT_LAMPORTS,
            1_000,
            10 * LAMPORTS_PER_SOL,
        ),
        "minimumUptimeMs": reward_policy.bounded_int(
            getattr(env, "REWARD_MIN_UPTIME_MS", ""),
            REWARD_DEFAULT_MIN_UPTIME_MS,
            0,
            30 * 24 * 60 * 60 * 1000,
        ),
        "minimumContributionUnits": reward_policy.bounded_int(
            getattr(env, "REWARD_MIN_CONTRIBUTION_UNITS", ""),
            0,
            0,
            1_000_000,
        ),
        "healthFreshMs": reward_policy.bounded_int(
            getattr(env, "REWARD_HEALTH_FRESH_MS", ""),
            REWARD_ENDPOINT_FRESH_MS,
            60 * 1000,
            60 * 60 * 1000,
        ),
    }


def _reward_explorer_url(network, signature="", address=""):
    base = "https://explorer.solana.com/"
    if signature:
        base += "tx/" + quote(signature)
    elif address:
        base += "address/" + quote(address)
    suffix = "" if network == "mainnet-beta" else "?cluster=" + quote(network)
    return base + suffix


async def _eligible_reward_snapshot(env, now=None):
    """Build eligibility from server-observed, signed HTTPS health facts."""
    now = int(now if now is not None else Date.now())
    config = _reward_config(env)
    cutoff = now - config["healthFreshMs"]
    expected_refs = await _https_mirror_expected_forkmesh_refs(env)
    rows = await d1_all(
        env,
        "SELECT e.node_bi, e.node_name, e.base_url, e.public_key, e.checked_at, "
        "e.healthy, e.integrity, e.abuse_blocked, "
        "e.forkmesh_verified_at, e.forkmesh_refs_sha256, "
        "e.forkmesh_operations_sha256, e.forkmesh_operations_json, "
        "e.forkmesh_active, e.registration_sig, e.issued_at, "
        "e.health_sig, e.health_message, p.ts AS presence_ts, n.data, "
        "o.first_verified_at, o.last_verified_at, "
        "o.consecutive_checks, o.contribution_units "
        "FROM mirror_https_endpoints e "
        "JOIN account_presence p ON p.name_bi=e.node_bi "
        "JOIN nodes n ON n.node_bi=e.node_bi "
        "LEFT JOIN reward_node_observations o ON o.node_bi=e.node_bi "
        "WHERE p.ts>=? AND e.checked_at>=? "
        "AND e.forkmesh_verified_at>=? "
        "ORDER BY e.node_name ASC LIMIT 2000",
        now - ACCOUNT_PRESENCE_STALE_MS, cutoff, cutoff,
    )
    candidates = []
    for row in rows or []:
        node_bi = str(row.get("node_bi") or "")
        record = await decrypt_row(env, row.get("data"))
        if not node_bi or not record or record.get("status") != "active":
            continue
        last_verified = int(row.get("last_verified_at") or 0)
        if last_verified and now - last_verified <= REWARD_OBSERVATION_GAP_MS:
            first_verified = int(row.get("first_verified_at") or now)
            consecutive = int(row.get("consecutive_checks") or 0) + 1
        else:
            first_verified = now
            consecutive = 1
        contribution_units = max(
            0, int(row.get("contribution_units") or 0))
        await d1_run(
            env,
            "INSERT INTO reward_node_observations "
            "(node_bi, first_verified_at, last_verified_at, "
            "consecutive_checks, contribution_units) VALUES (?,?,?,?,?) "
            "ON CONFLICT(node_bi) DO UPDATE SET "
            "first_verified_at=excluded.first_verified_at, "
            "last_verified_at=excluded.last_verified_at, "
            "consecutive_checks=excluded.consecutive_checks, "
            "contribution_units=MAX("
            "reward_node_observations.contribution_units,"
            "excluded.contribution_units)",
            node_bi, first_verified, now, consecutive, contribution_units,
        )
        node_name = clean_string(
            row.get("node_name") or record.get("name"), MAX_NODE_NAME
        ).strip().lower()
        owner = clean_string(
            record.get("owner") or node_name, MAX_NODE_NAME).strip().lower()
        operator_id = await blind_index(env, "reward-operator:" + owner)
        public_key = clean_string(row.get("public_key"), 160).strip()
        refs_hash = clean_string(
            row.get("forkmesh_refs_sha256"), 64).lower()
        operations_hash = clean_string(
            row.get("forkmesh_operations_sha256"), 64).lower()
        try:
            operations = json.loads(
                str(row.get("forkmesh_operations_json") or "[]"))
        except Exception:
            operations = []
        normalized_operations_hash = https_routing.operations_sha256(operations)
        required_operations_ok = bool(
            normalized_operations_hash
            and hmac.compare_digest(
                normalized_operations_hash, operations_hash)
            and HTTPS_MIRROR_REQUIRED_FORKMESH_OPERATIONS.issubset(
                set(operations))
        )
        allowed_identity_keys = await _owner_signing_pubkeys(env, node_name)
        signed_attestation = await _verified_federated_reward_attestation(
            env,
            {
                "name": node_name,
                "operator": owner,
                "wallet": str(record.get("solana") or "").strip(),
                "publicKey": public_key,
                "baseUrl": row.get("base_url"),
                "registrationSignature": row.get("registration_sig"),
                "registrationIssuedAt": row.get("issued_at"),
                "healthMessage": row.get("health_message"),
                "healthSignature": row.get("health_sig"),
                "checkedAt": row.get("checked_at"),
                "healthy": True,
                "integrity": "ok",
                "mirrorsForkMesh": True,
                "requiredOperationsVerified": required_operations_ok,
                "abuseFlagged": False,
                "forkmeshVerifiedAt": row.get("forkmesh_verified_at"),
                "refsSha256": refs_hash,
                "operationsSha256": operations_hash,
            },
            now,
            expected_refs,
            config["healthFreshMs"],
        )
        endpoint_ok = bool(
            signed_attestation
            and public_key in allowed_identity_keys
            and required_operations_ok
            and not int(row.get("abuse_blocked") or 0)
        )
        candidates.append({
            "nodeId": node_name,
            "operatorId": operator_id,
            "deviceId": hashlib.sha256(public_key.encode()).hexdigest(),
            "walletAddress": str(record.get("solana") or "").strip(),
            "attestationSourceApproved": True,
            "identitySignatureVerified": endpoint_ok,
            "healthAttestationSignatureVerified": endpoint_ok,
            "healthAttestationFresh": bool(
                int(row.get("checked_at") or 0) >= cutoff
                and int(row.get("forkmesh_verified_at") or 0) >= cutoff),
            "online": (
                int(row.get("presence_ts") or 0)
                >= now - ACCOUNT_PRESENCE_STALE_MS
            ),
            "healthy": endpoint_ok,
            "mirrorsForkMesh": bool(int(
                row.get("forkmesh_active") or 0)),
            "integrity": (
                "signed-manifest-verified" if endpoint_ok else "unknown"
            ),
            "abuseFlagged": bool(int(row.get("abuse_blocked") or 0)),
            "observedUptimeMs": max(0, now - first_verified),
            "contributionUnits": contribution_units,
            "healthCheckedAt": int(row.get("checked_at") or 0),
            "attestationId": hashlib.sha256(
                (
                    node_bi + "\0" + refs_hash + "\0"
                    + operations_hash + "\0"
                    + str(row.get("forkmesh_verified_at") or 0)
                ).encode()
            ).hexdigest(),
        })
    if _is_main_relay(env):
        federated_rows = await d1_all(
            env,
            "SELECT fp.*,r.label AS relay_label "
            "FROM federated_presence fp "
            "JOIN relays r ON r.relay_bi=fp.relay_bi "
            "WHERE r.status='approved' AND fp.ts>=? "
            "AND fp.checked_at>=? AND fp.forkmesh_verified_at>=? "
            "AND fp.healthy=1 AND fp.integrity='ok' "
            "AND fp.forkmesh_active=1 AND fp.abuse_blocked=0 "
            "ORDER BY fp.relay_bi,fp.name LIMIT 2000",
            now - ACCOUNT_PRESENCE_STALE_MS, cutoff, cutoff,
        )
        for row in federated_rows or []:
            item = await _verified_federated_reward_attestation(
                env,
                {
                    "name": row.get("name"),
                    "operator": row.get("name"),
                    "wallet": row.get("wallet"),
                    "publicKey": row.get("public_key"),
                    "baseUrl": row.get("base_url"),
                    "registrationSignature": row.get("registration_sig"),
                    "registrationIssuedAt": row.get(
                        "registration_issued_at"),
                    "healthMessage": row.get("health_message"),
                    "healthSignature": row.get("health_sig"),
                    "checkedAt": row.get("checked_at"),
                    "healthy": bool(int(row.get("healthy") or 0)),
                    "integrity": row.get("integrity"),
                    "mirrorsForkMesh": bool(
                        int(row.get("forkmesh_active") or 0)),
                    "forkmeshVerifiedAt": row.get(
                        "forkmesh_verified_at"),
                    "refsSha256": row.get("forkmesh_refs_sha256"),
                    "operationsSha256": row.get(
                        "forkmesh_operations_sha256"),
                    "requiredOperationsVerified": True,
                    "abuseFlagged": bool(
                        int(row.get("abuse_blocked") or 0)),
                },
                now,
                expected_refs,
                config["healthFreshMs"],
            )
            operator_id = str(row.get("operator_id") or "")
            device_id = str(row.get("device_id") or "")
            attestation_id = str(row.get("attestation_id") or "")
            relay_bi = str(row.get("relay_bi") or "")
            if (
                not item
                or not operator_id
                or not hmac.compare_digest(
                    device_id, item.get("deviceId") or "")
                or not re.fullmatch(r"[0-9a-f]{64}", attestation_id)
                or not relay_bi
            ):
                continue
            candidates.append({
                "nodeId": (
                    "relay-" + relay_bi[:16] + "-"
                    + item["name"]),
                "operatorId": operator_id,
                "deviceId": device_id,
                "walletAddress": item["wallet"],
                "attestationSourceApproved": True,
                "identitySignatureVerified": True,
                "healthAttestationSignatureVerified": True,
                "healthAttestationFresh": True,
                "online": int(row.get("ts") or 0) >= (
                    now - ACCOUNT_PRESENCE_STALE_MS),
                "healthy": True,
                "mirrorsForkMesh": True,
                "integrity": "signed-manifest-verified",
                "abuseFlagged": False,
                "observedUptimeMs": max(
                    0, now - int(row.get("first_verified_at") or now)),
                "contributionUnits": 0,
                "healthCheckedAt": item["checkedAt"],
                "attestationId": attestation_id,
                "relayLabel": clean_string(
                    row.get("relay_label") or "relay", 80),
            })
    snapshot = reward_policy.eligibility_snapshot(
        candidates,
        minimum_uptime_ms=config["minimumUptimeMs"],
        minimum_contribution_units=config["minimumContributionUnits"],
    )
    snapshot["generatedAt"] = now
    snapshot["source"] = (
        "signed HTTPS identity + fresh Cloudflare health check + "
        "forkmesh/forkmesh refs integrity proof + server-observed presence; "
        "approved federated relays additionally preserve and forward the "
        "original node-signed registration and health messages"
    )
    if _is_main_relay(env):
        snapshot.setdefault("limitations", []).append(
            "An approved federated relay attests that it performed the "
            "network challenge. Relay approval is a revocable trust boundary, "
            "not proof of personhood or universal node trust."
        )
    return snapshot


def _reward_pool_address(env):
    """Resolve the public reward destination without loading wallet material.

    COMMUNITY_REWARD_POOL_ADDRESS is the explicit modern override. Existing
    ForkMesh deployments historically supplied the same public destination as
    TREASURY_SOLANA_ADDRESS, so that name remains a compatibility fallback.
    A non-empty explicit override fails closed later if it is invalid instead
    of silently sending contributors to a different configured address.
    """
    primary = clean_string(
        getattr(env, "COMMUNITY_REWARD_POOL_ADDRESS", ""), 80).strip()
    if primary:
        return primary
    return clean_string(
        getattr(env, "TREASURY_SOLANA_ADDRESS", ""), 80).strip()


async def _central_fund_record(env):
    # The pool address is public configuration. Its private key lives in the
    # instance owner's local signer and is never generated, uploaded or loaded
    # by Cloudflare.
    address = _reward_pool_address(env)
    if (
        not SOLANA_RE.match(address)
        or not await _reward_pool_network_verified(env, address)
    ):
        return None
    signer_account = clean_string(
        getattr(env, "REWARD_SIGNER_ACCOUNT", "")
        or getattr(env, "INSTANCE_OWNER_ACCOUNT", ""),
        MAX_NODE_NAME,
    ).strip().lower()
    return {
        "address": address,
        "signer_account": signer_account,
        "custody": "external-local-signer",
        "network": _reward_network(env),
    }


async def _save_central_fund(env, rec):
    # Compatibility symbol: central-fund state is now derived from public
    # configuration + append-only signing intents, never an encrypted key row.
    del env, rec
    return False


async def _central_fund_public(env):
    # Public contribution payload: configured address, selected-network balance,
    # direct contribution choices, and independently verifiable finalized history.
    rec = await _central_fund_record(env)
    if not rec:
        return None
    addr = rec.get("address", "")
    network = rec.get("network", "mainnet-beta")
    balance = await _reward_balance_lamports(env, addr)
    latest = await d1_first(
        env,
        "SELECT intent_id, status, created_at, tx_signature, completed_at "
        "FROM chain_intents WHERE kind IN "
        "('community_reward_random','community_reward_instant_distribution') "
        "ORDER BY created_at DESC LIMIT 1",
    )
    latest_round = await d1_first(
        env,
        "SELECT round_id,status,interval_start,scheduled_at,execute_after,"
        "schedule_entropy,snapshot_data,selection_data,intent_id,"
        "completed_at FROM reward_rounds "
        "ORDER BY interval_start DESC LIMIT 1",
    )
    round_public = None
    if latest_round:
        try:
            round_snapshot = json.loads(
                str(latest_round.get("snapshot_data") or "{}"))
        except Exception:
            round_snapshot = {}
        try:
            round_selection = json.loads(
                str(latest_round.get("selection_data") or "{}"))
        except Exception:
            round_selection = {}
        rejection_counts = {}
        for rejected in round_snapshot.get("rejected") or []:
            reason = clean_string(
                (rejected or {}).get("reason"), 80).strip()
            if reason:
                rejection_counts[reason] = (
                    int(rejection_counts.get(reason) or 0) + 1)
        candidate = (
            round_selection.get("candidate")
            if isinstance(round_selection, dict) else {}
        ) or {}
        round_public = {
            "roundId": str(latest_round.get("round_id") or ""),
            "status": str(latest_round.get("status") or ""),
            "intervalStart": int(
                latest_round.get("interval_start") or 0),
            "scheduledAt": int(latest_round.get("scheduled_at") or 0),
            "executeAfter": int(latest_round.get("execute_after") or 0),
            "scheduleEntropy": str(
                latest_round.get("schedule_entropy") or ""),
            "scheduleEntropySource": (
                network + "-finalized-solana-blockhash"
            ),
            "snapshotHash": str(
                round_snapshot.get("snapshotHash") or ""),
            "eligibleCount": len(round_snapshot.get("eligible") or []),
            "rejectionCounts": rejection_counts,
            "policy": round_snapshot.get("policy") or {},
            "limitations": round_snapshot.get("limitations") or [],
            "selection": ({
                "algorithm": str(
                    round_selection.get("algorithm") or ""),
                "selectedIndex": int(
                    round_selection.get("selectedIndex") or 0),
                "eligibleCount": int(
                    round_selection.get("eligibleCount") or 0),
                "snapshotHash": str(
                    round_selection.get("snapshotHash") or ""),
                "entropySource": str(
                    round_selection.get("entropySource") or ""),
                "publicEntropy": str(
                    round_selection.get("publicEntropy") or ""),
                "selectedNodeId": str(candidate.get("nodeId") or ""),
                "selectedWalletAddress": str(
                    candidate.get("walletAddress") or ""),
            } if round_selection else None),
            "intentId": str(latest_round.get("intent_id") or ""),
            "completedAt": int(latest_round.get("completed_at") or 0),
        }
    completed = await d1_all(
        env,
        "SELECT intent_id, kind, status, data, created_at, tx_signature, "
        "completed_at FROM chain_intents WHERE kind IN "
        "('community_reward_random','community_reward_instant_distribution') "
        "AND status='completed' ORDER BY completed_at DESC LIMIT 20",
    )
    transactions = []
    for row in completed or []:
        try:
            plan = json.loads(str(row.get("data") or "{}"))
        except Exception:
            plan = {}
        for transfer in (plan.get("transfers") or [])[:200]:
            if not isinstance(transfer, dict):
                continue
            transactions.append({
                "eventId": (
                    str(row.get("intent_id") or "") + ":"
                    + str(len(transactions))
                ),
                "type": (
                    "instant-all-nodes"
                    if row.get("kind")
                    == "community_reward_instant_distribution"
                    else "randomized-node-reward"
                ),
                "recipient": str(transfer.get("address") or ""),
                "recipientNode": str(
                    transfer.get("nodeId")
                    or (plan.get("selection") or {}).get("selectedNodeId")
                    or ""
                ),
                "lamports": int(transfer.get("lamports") or 0),
                "amountSol": _amount_sol(
                    int(transfer.get("lamports") or 0)),
                "status": "completed-on-chain",
                "transactionSignature": str(
                    row.get("tx_signature") or ""),
                "completedAt": int(row.get("completed_at") or 0),
                "explorerUrl": _reward_explorer_url(
                    network, signature=str(row.get("tx_signature") or "")),
            })
    contribution_rows = await d1_all(
        env,
        "SELECT contribution_id, mode, amount_lamports, status, "
        "tx_signature, confirmed_at, distribution_intent_id "
        "FROM reward_contributions "
        "WHERE status NOT IN ('prepared','expired') "
        "ORDER BY confirmed_at DESC LIMIT 20",
    )
    contributions = [{
        "contributionId": str(row.get("contribution_id") or ""),
        "mode": str(row.get("mode") or ""),
        "amountLamports": int(row.get("amount_lamports") or 0),
        "amountSol": _amount_sol(int(row.get("amount_lamports") or 0)),
        "status": str(row.get("status") or ""),
        "transactionSignature": str(row.get("tx_signature") or ""),
        "confirmedAt": int(row.get("confirmed_at") or 0),
        "distributionIntentId": str(
            row.get("distribution_intent_id") or ""),
        "explorerUrl": _reward_explorer_url(
            network, signature=str(row.get("tx_signature") or "")),
    } for row in contribution_rows or []]
    config = _reward_config(env)
    return {
        "address": addr,
        "network": network,
        "uri": _solana_pay_uri(
            addr, 0, message="ForkMesh voluntary trickle-pool contribution"),
        "explorerUrl": _reward_explorer_url(network, address=addr),
        "balanceLamports": balance if balance is not None else 0,
        "balanceSol": _amount_sol(balance or 0),
        "distributionIntervalMs": config["intervalMs"],
        "rewardAmountLamports": config["amountLamports"],
        "randomJitterMaxMs": config["jitterMs"],
        "custody": "external-local-signer",
        "privateKeyLocation": "instance-owner-device",
        "privateKeyStoredByWorker": False,
        "fundStates": {
            "userOwnedFunds": (
                "Remain in each contributor or recipient's self-custodial "
                "wallet until that wallet signs a transaction."
            ),
            "communityFundedPool": (
                "The public on-chain address and balance shown above."
            ),
            "pendingRewards": (
                "Ledger allocations only; funds remain in the public source "
                "wallet for at most 24 hours."
            ),
            "completedOnChainTransfers": (
                "Finalized signatures linked in the event history."
            ),
        },
        "contributionOptions": [
            {
                "mode": "trickle",
                "label": "Add to the randomized funding pool",
                "effect": (
                    "A direct wallet-to-pool transfer remains available for "
                    "configurable randomized eligible-node rewards."
                ),
            },
            {
                "mode": "instant_all_nodes",
                "label": "Distribute this contribution to all eligible nodes",
                "effect": (
                    "After the incoming transfer is finalized, the local pool "
                    "owner receives one reviewed unsigned all-node intent."
                ),
            },
        ],
        "contributionEndpoint": "/api/rewards/contributions",
        "programParticipation": {
            "type": "voluntary-community-support",
            "userWalletSignatureRequired": True,
            "forkMeshSignsContributorTransfer": False,
            "ownershipInterestGranted": False,
            "financialReturnPromised": False,
        },
        "transactions": transactions[:40],
        "contributions": contributions,
        "latestRound": round_public,
        "notice": (
            "Non-custodial: ForkMesh does not hold or control user funds and "
            "never receives a private key. The private pool signing key remains "
            "only on the instance owner's device. Voluntary contributions and "
            "community rewards are incentives, not investments, and do not "
            "guarantee a return."
        ),
        "latestIntent": ({
            "intentId": str(latest.get("intent_id") or ""),
            "status": str(latest.get("status") or ""),
            "createdAt": int(latest.get("created_at") or 0),
            "transactionSignature": str(
                latest.get("tx_signature") or ""),
            "completedAt": int(latest.get("completed_at") or 0),
        } if latest else None),
    }


async def _distribute_central_fund(env):
    # Cron first commits an auditable jittered round, then (after that public
    # time) freezes fresh eligibility and uses a finalized Solana blockhash to
    # select exactly one node. It only writes an unsigned plan.
    if not _is_main_relay(env):
        return False
    rec = await _central_fund_record(env)
    if not rec:
        return False
    now = int(Date.now())
    config = _reward_config(env)
    # Expired unsigned work cannot stall later rounds indefinitely.
    await d1_run(
        env,
        "UPDATE chain_intents SET status='expired' "
        "WHERE kind='community_reward_random' "
        "AND status IN ('pending_signature','submitted') "
        "AND expires_at>0 AND expires_at<=?",
        now,
    )
    await d1_run(
        env,
        "UPDATE reward_rounds SET status='expired' "
        "WHERE status='awaiting_signature' AND intent_id IN "
        "(SELECT intent_id FROM chain_intents WHERE status='expired')",
    )
    pending = await d1_first(
        env,
        "SELECT intent_id FROM chain_intents "
        "WHERE kind='community_reward_random' "
        "AND status IN ('pending_signature','submitted') "
        "AND (expires_at=0 OR expires_at>?) LIMIT 1",
        now,
    )
    if pending:
        return False
    round_row = await d1_first(
        env,
        "SELECT * FROM reward_rounds WHERE status='scheduled' "
        "ORDER BY execute_after ASC LIMIT 1",
    )
    if not round_row:
        interval_start = now - (now % config["intervalMs"])
        round_id = (
            _reward_network(env) + ":" + str(interval_start)
        )
        existing = await d1_first(
            env, "SELECT * FROM reward_rounds WHERE round_id=?", round_id)
        if existing:
            return False
        schedule_entropy = await _reward_public_entropy(env)
        if not schedule_entropy:
            return False
        initial_snapshot = await _eligible_reward_snapshot(env, now)
        if not initial_snapshot.get("eligible"):
            return False
        offset = reward_policy.schedule_offset_ms(
            round_id=round_id,
            public_entropy=schedule_entropy,
            jitter_window_ms=min(
                config["jitterMs"], max(0, config["intervalMs"] - 1)),
        )
        execute_after = interval_start + offset
        await d1_run(
            env,
            "INSERT INTO reward_rounds "
            "(round_id,status,interval_start,scheduled_at,execute_after,"
            "schedule_entropy,snapshot_data) "
            "VALUES (?,'scheduled',?,?,?,?,?)",
            round_id, interval_start, now, execute_after,
            schedule_entropy,
            json.dumps(
                initial_snapshot, sort_keys=True, separators=(",", ":")),
        )
        await _audit_sensitive_action(
            env, "", "reward.round_schedule", "reward_round", round_id,
            "requested", {
                "executeAfter": execute_after,
                "eligibleCount": len(initial_snapshot.get("eligible") or []),
                "snapshotHash": initial_snapshot.get("snapshotHash", ""),
                "entropySource": (
                    _reward_network(env)
                    + "-finalized-solana-blockhash"
                ),
            })
        if execute_after > now:
            return True
        round_row = {
            "round_id": round_id,
            "execute_after": execute_after,
        }
    if int(round_row.get("execute_after") or 0) > now:
        return False

    snapshot = await _eligible_reward_snapshot(env, now)
    selection_entropy = await _reward_public_entropy(env)
    selection = reward_policy.select_candidate(
        snapshot,
        round_id=str(round_row.get("round_id") or ""),
        public_entropy=selection_entropy,
        entropy_source=(
            _reward_network(env) + "-finalized-solana-blockhash"),
    )
    if not selection:
        return False
    from_addr = rec.get("address", "")
    if not SOLANA_RE.match(from_addr or ""):
        return False
    balance = await _reward_balance_lamports(env, from_addr)
    if balance is None:
        return False
    amount = config["amountLamports"]
    if int(balance) < amount + REWARD_POOL_FEE_RESERVE_LAMPORTS:
        return False
    selected = selection.get("candidate") or {}
    destination = str(selected.get("walletAddress") or "")
    if not SOLANA_RE.match(destination) or destination == from_addr:
        return False
    intent_id = _random_bytes(16).hex()
    plan = {
        "v": 2,
        "network": _reward_network(env),
        "sourceAddress": from_addr,
        "custody": {
            "forkMeshHoldsUserKeys": False,
            "fundsRemainInSourceWalletUntilSigned": True,
        },
        "signing": {
            "required": True,
            "performed": False,
            "method": "external-local-qt",
        },
        "transfers": [{
            "address": destination,
            "lamports": amount,
            "nodeId": str(selected.get("nodeId") or ""),
        }],
        "eligibility": snapshot,
        "selection": dict(selection, selectedNodeId=str(
            selected.get("nodeId") or "")),
        "policy": "randomized-eligible-mirror-v2",
        "generatedAt": now,
        "notice": (
            "Voluntary community incentive; not an investment and no "
            "financial return is promised."
        ),
    }
    await d1_run(
        env,
        "INSERT INTO chain_intents "
        "(intent_id, kind, source_address, signer_account, status, data, "
        "created_at, expires_at) VALUES (?,?,?,?,'pending_signature',?,?,?)",
        intent_id, "community_reward_random", from_addr,
        rec.get("signer_account", ""),
        json.dumps(plan, sort_keys=True, separators=(",", ":")),
        now, now + 4 * 60 * 60 * 1000,
    )
    await d1_run(
        env,
        "UPDATE reward_rounds SET status='awaiting_signature', "
        "selection_data=?, intent_id=? WHERE round_id=? "
        "AND status='scheduled'",
        json.dumps(selection, sort_keys=True, separators=(",", ":")),
        intent_id, round_row.get("round_id"),
    )
    await _audit_sensitive_action(
        env, "", "reward.intent_create", "chain_intent", intent_id,
        "requested", {
            "kind": "community_reward_random",
            "roundId": round_row.get("round_id"),
            "selectedNodeId": selected.get("nodeId", ""),
            "eligibleCount": selection.get("eligibleCount", 0),
            "snapshotHash": selection.get("snapshotHash", ""),
            "lamports": amount,
        })
    return True


async def _solana_contribution_details(env, signature, *, pool_address,
                                       reference_address, amount_lamports):
    """Validate one finalized, referenced System transfer into the pool."""
    if (not re.fullmatch(r"[1-9A-HJ-NP-Za-km-z]{64,120}",
                         str(signature or ""))
            or not SOLANA_RE.match(pool_address or "")
            or not SOLANA_RE.match(reference_address or "")
            or int(amount_lamports or 0) <= 0):
        return False
    response = await _reward_solana_rpc(
        env,
        "getTransaction",
        [signature, {
            "encoding": "jsonParsed",
            "commitment": "finalized",
            "maxSupportedTransactionVersion": 0,
        }],
    )
    if not isinstance(response, dict):
        return None
    result = response.get("result")
    if result is None:
        return None
    if not isinstance(result, dict):
        return False
    meta = result.get("meta")
    transaction = result.get("transaction")
    if (not isinstance(meta, dict) or meta.get("err") is not None
            or not isinstance(transaction, dict)
            or signature not in (transaction.get("signatures") or [])):
        return False
    message = transaction.get("message")
    if not isinstance(message, dict):
        return False
    account_keys = []
    for key in message.get("accountKeys") or []:
        if isinstance(key, dict):
            account_keys.append(str(key.get("pubkey") or ""))
        else:
            account_keys.append(str(key or ""))
    # The per-intent Solana Pay reference prevents one public transaction from
    # being claimed under a different contribution choice.
    if reference_address not in account_keys:
        return False
    actual = []
    for instruction in message.get("instructions") or []:
        if not isinstance(instruction, dict):
            return False
        if str(instruction.get("program") or "").lower() != "system":
            return False
        parsed = instruction.get("parsed")
        if (not isinstance(parsed, dict)
                or parsed.get("type") != "transfer"):
            return False
        info = parsed.get("info")
        if not isinstance(info, dict):
            return False
        try:
            lamports = int(info.get("lamports") or 0)
        except (TypeError, ValueError):
            return False
        actual.append({
            "sourceAddress": str(info.get("source") or ""),
            "destinationAddress": str(info.get("destination") or ""),
            "lamports": lamports,
        })
    if len(actual) != 1:
        return False
    transfer = actual[0]
    if (not SOLANA_RE.match(transfer["sourceAddress"])
            or transfer["sourceAddress"] == pool_address
            or transfer["destinationAddress"] != pool_address
            or transfer["lamports"] != int(amount_lamports)):
        return False
    return transfer


async def _create_instant_distribution_intent(env, contribution):
    """Turn one finalized contribution into a size-safe unsigned intent batch."""
    contribution = contribution or {}
    if contribution.get("distribution_intent_id"):
        rows = await d1_all(
            env,
            "SELECT intent_id FROM reward_contribution_intents "
            "WHERE contribution_id=? ORDER BY chunk_index ASC",
            contribution.get("contribution_id"),
        )
        return [
            str(row.get("intent_id") or "")
            for row in rows or []
            if row.get("intent_id")
        ]
    rec = await _central_fund_record(env)
    if not rec or not rec.get("signer_account"):
        return []
    now = int(Date.now())
    snapshot = await _eligible_reward_snapshot(env, now)
    eligible = list(snapshot.get("eligible") or [])
    if not eligible:
        return []
    total = int(contribution.get("amount_lamports") or 0)
    chunk_count = (
        len(eligible) + REWARD_TRANSFERS_PER_INTENT - 1
    ) // REWARD_TRANSFERS_PER_INTENT
    fee_reserve = REWARD_POOL_FEE_RESERVE_LAMPORTS * chunk_count
    distributable = total - fee_reserve
    per_node = distributable // len(eligible) if eligible else 0
    if per_node <= 0:
        return []
    balance = await _reward_balance_lamports(env, rec.get("address"))
    required = per_node * len(eligible) + fee_reserve
    if balance is None or int(balance) < required:
        return []
    transfers = [{
        "address": item["walletAddress"],
        "lamports": per_node,
        "nodeId": item["nodeId"],
    } for item in eligible]
    contribution_id = str(contribution.get("contribution_id") or "")
    eligibility_summary = {
        "snapshotHash": snapshot.get("snapshotHash", ""),
        "eligibleCount": len(eligible),
        "rejected": snapshot.get("rejected", []),
        "policy": snapshot.get("policy", {}),
        "limitations": snapshot.get("limitations", []),
        "source": snapshot.get("source", ""),
    }
    statements = []
    intent_ids = []
    for chunk_index in range(chunk_count):
        intent_id = _random_bytes(16).hex()
        intent_ids.append(intent_id)
        start = chunk_index * REWARD_TRANSFERS_PER_INTENT
        chunk = transfers[start:start + REWARD_TRANSFERS_PER_INTENT]
        plan = {
            "v": 2,
            "network": rec.get("network", "mainnet-beta"),
            "sourceAddress": rec.get("address", ""),
            "custody": {
                "forkMeshHoldsUserKeys": False,
                "fundsRemainInSourceWalletUntilSigned": True,
            },
            "signing": {
                "required": True,
                "performed": False,
                "method": "external-local-qt",
            },
            "transfers": chunk,
            "eligibility": eligibility_summary,
            "policy": "instant-all-eligible-mirrors-v1",
            "contributionId": contribution_id,
            "contributionLamports": total,
            "distributedLamports": per_node * len(eligible),
            "retainedForNetworkFeesAndRemainder": (
                total - per_node * len(eligible)
            ),
            "batch": {
                "chunkIndex": chunk_index,
                "chunkCount": chunk_count,
                "maximumTransfersPerTransaction": (
                    REWARD_TRANSFERS_PER_INTENT
                ),
            },
            "generatedAt": now,
            "notice": (
                "Voluntary community incentive; not an investment and no "
                "financial return is promised."
            ),
        }
        statements.extend([
            (
                "INSERT INTO chain_intents "
                "(intent_id,kind,source_address,signer_account,status,data,"
                "created_at,expires_at) "
                "VALUES (?,?,?,?,'pending_signature',?,?,?)",
                (
                    intent_id,
                    "community_reward_instant_distribution",
                    rec.get("address", ""),
                    rec.get("signer_account", ""),
                    json.dumps(
                        plan, sort_keys=True, separators=(",", ":")),
                    now,
                    now + 4 * 60 * 60 * 1000,
                ),
            ),
            (
                "INSERT INTO reward_contribution_intents "
                "(contribution_id,intent_id,chunk_index,chunk_count,status) "
                "VALUES (?,?,?,?,'pending_signature')",
                (
                    contribution_id, intent_id, chunk_index, chunk_count,
                ),
            ),
        ])
    statements.append((
        "UPDATE reward_contributions "
        "SET status='awaiting_distribution', distribution_intent_id=? "
        "WHERE contribution_id=? AND distribution_intent_id=''",
        (intent_ids[0], contribution_id),
    ))
    await _contribution_run_batch(env, statements)
    await _audit_sensitive_action(
        env, "", "reward.instant_intent_create",
        "reward_contribution", contribution_id,
        "requested", {
            "contributionId": contribution_id,
            "eligibleCount": len(eligible),
            "snapshotHash": snapshot.get("snapshotHash", ""),
            "distributedLamports": per_node * len(eligible),
            "intentCount": chunk_count,
            "maximumTransfersPerIntent": REWARD_TRANSFERS_PER_INTENT,
        })
    return intent_ids


async def _finalize_reward_contribution(env, row, signature, details):
    now = int(Date.now())
    mode = str(row.get("mode") or "")
    status = (
        "confirmed_waiting_for_nodes"
        if mode == "instant_all_nodes"
        else "confirmed_in_pool"
    )
    await d1_run(
        env,
        "UPDATE reward_contributions SET status=?, tx_signature=?, "
        "source_address=?, confirmed_at=? WHERE contribution_id=? "
        "AND status IN ('prepared','awaiting_finality')",
        status, signature, details.get("sourceAddress", ""), now,
        row.get("contribution_id"),
    )
    row = dict(row)
    row.update({
        "status": status,
        "tx_signature": signature,
        "source_address": details.get("sourceAddress", ""),
        "confirmed_at": now,
    })
    if mode == "instant_all_nodes":
        intent_ids = await _create_instant_distribution_intent(env, row)
        if intent_ids:
            row["status"] = "awaiting_distribution"
            row["distribution_intent_id"] = intent_ids[0]
            row["distribution_intent_ids"] = intent_ids
    await _audit_sensitive_action(
        env, "", "reward.contribution_confirm", "reward_contribution",
        str(row.get("contribution_id") or ""), "success", {
            "mode": mode,
            "lamports": int(row.get("amount_lamports") or 0),
            "transactionSignature": signature,
        })
    return row


async def _process_waiting_reward_contributions(env):
    rows = await d1_all(
        env,
        "SELECT * FROM reward_contributions "
        "WHERE mode='instant_all_nodes' "
        "AND status='confirmed_waiting_for_nodes' "
        "AND distribution_intent_id='' "
        "ORDER BY confirmed_at ASC LIMIT 20",
    )
    created = 0
    for row in rows or []:
        if await _create_instant_distribution_intent(env, row):
            created += 1
    return created


async def verify_submitted_reward_contributions(env):
    now = int(Date.now())
    await d1_run(
        env,
        "UPDATE reward_contributions SET status='expired' "
        "WHERE status='prepared' AND expires_at<=?",
        now,
    )
    rows = await d1_all(
        env,
        "SELECT * FROM reward_contributions "
        "WHERE status='awaiting_finality' "
        "ORDER BY created_at ASC LIMIT 25",
    )
    rec = await _central_fund_record(env)
    if not rec:
        return
    for row in rows or []:
        details = await _solana_contribution_details(
            env, row.get("tx_signature"),
            pool_address=rec.get("address", ""),
            reference_address=row.get("reference_address", ""),
            amount_lamports=int(row.get("amount_lamports") or 0),
        )
        if isinstance(details, dict):
            await _finalize_reward_contribution(
                env, row, row.get("tx_signature"), details)
        elif details is False:
            await d1_run(
                env,
                "UPDATE reward_contributions SET status='rejected' "
                "WHERE contribution_id=? AND status='awaiting_finality'",
                row.get("contribution_id"),
            )
    await _process_waiting_reward_contributions(env)


async def reward_contributions_handler(env, request):
    """Prepare/confirm voluntary direct-to-pool Solana Pay transfers."""
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    rec = await _central_fund_record(env)
    if not rec:
        return json_response(
            {"error": "community_pool_not_configured"}, status=503)
    action = clean_string(data.get("action", "prepare"), 20).lower()
    now = int(Date.now())
    if action == "prepare":
        mode = clean_string(data.get("mode", ""), 32).lower()
        try:
            amount = int(data.get("amountLamports") or 0)
        except (TypeError, ValueError):
            amount = 0
        if mode not in ("trickle", "instant_all_nodes"):
            return json_response(
                {"error": "invalid_contribution_mode"}, status=400)
        if not (
            REWARD_CONTRIBUTION_MIN_LAMPORTS
            <= amount
            <= REWARD_CONTRIBUTION_MAX_LAMPORTS
        ):
            return json_response({
                "error": "invalid_contribution_amount",
                "minimumLamports": REWARD_CONTRIBUTION_MIN_LAMPORTS,
                "maximumLamports": REWARD_CONTRIBUTION_MAX_LAMPORTS,
            }, status=400)
        recent = await d1_first(
            env,
            "SELECT COUNT(*) AS c FROM reward_contributions "
            "WHERE created_at>=?",
            now - REWARD_CONTRIBUTION_EXPIRES_MS,
        )
        if int((recent or {}).get("c") or 0) >= 1000:
            return json_response(
                {"error": "contribution_queue_busy"}, status=429)
        contribution_id = _random_bytes(16).hex()
        reference = _base58_encode(_random_bytes(32))
        expires_at = now + REWARD_CONTRIBUTION_EXPIRES_MS
        await d1_run(
            env,
            "INSERT INTO reward_contributions "
            "(contribution_id,mode,amount_lamports,reference_address,"
            "status,created_at,expires_at) "
            "VALUES (?,?,?,?,'prepared',?,?)",
            contribution_id, mode, amount, reference, now, expires_at,
        )
        return json_response({
            "ok": True,
            "contributionId": contribution_id,
            "mode": mode,
            "amountLamports": amount,
            "amountSol": _amount_sol(amount),
            "poolAddress": rec.get("address", ""),
            "network": rec.get("network", "mainnet-beta"),
            "referenceAddress": reference,
            "expiresAt": expires_at,
            "uri": _solana_pay_uri(
                rec.get("address", ""), amount, reference=reference,
                message=(
                    "ForkMesh instant eligible-node contribution"
                    if mode == "instant_all_nodes"
                    else "ForkMesh randomized reward-pool contribution"
                ),
            ),
            "custody": "direct-self-custodial-wallet-to-public-pool",
            "programParticipation": "voluntary-community-support",
            "userWalletSignatureRequired": True,
            "forkMeshSignsContributorTransfer": False,
            "ownershipInterestGranted": False,
            "financialReturnPromised": False,
            "notice": (
                "ForkMesh never receives your wallet key. Your wallet signs "
                "a direct public transfer; this is a voluntary community "
                "incentive, not an investment or guaranteed return."
            ),
        }, status=201, cache_control="no-store")
    if action != "confirm":
        return json_response({"error": "invalid_action"}, status=400)
    contribution_id = security_control.normalize_incident_id(
        data.get("contributionId"))
    signature = clean_string(
        data.get("transactionSignature", ""), 120).strip()
    if (not contribution_id
            or not re.fullmatch(
                r"[1-9A-HJ-NP-Za-km-z]{64,120}", signature)):
        return json_response(
            {"error": "invalid_contribution_confirmation"}, status=400)
    row = await d1_first(
        env,
        "SELECT * FROM reward_contributions WHERE contribution_id=?",
        contribution_id,
    )
    if not row:
        return json_response({"error": "not_found"}, status=404)
    if row.get("status") in (
            "confirmed_in_pool", "confirmed_waiting_for_nodes",
            "awaiting_distribution", "distributed"):
        if row.get("tx_signature") != signature:
            return json_response(
                {"error": "contribution_already_confirmed"}, status=409)
        return json_response({
            "ok": True,
            "status": row.get("status"),
            "distributionIntentId": str(
                row.get("distribution_intent_id") or ""),
            "custody": "public-community-pool",
            "fundsLocation": "public-community-pool",
            "notice": (
                "The wallet-signed contribution is already confirmed in the "
                "public community pool. ForkMesh retained no contributor key; "
                "any distribution still requires the external local signer "
                "and final on-chain verification."
            ),
        }, cache_control="no-store")
    if int(row.get("expires_at") or 0) <= now:
        await d1_run(
            env,
            "UPDATE reward_contributions SET status='expired' "
            "WHERE contribution_id=? AND status='prepared'",
            contribution_id,
        )
        return json_response({"error": "contribution_expired"}, status=410)
    replay = await d1_first(
        env,
        "SELECT contribution_id FROM reward_contributions "
        "WHERE tx_signature=? AND contribution_id<>?",
        signature, contribution_id,
    )
    if replay:
        return json_response({"error": "transaction_replay"}, status=409)
    details = await _solana_contribution_details(
        env, signature,
        pool_address=rec.get("address", ""),
        reference_address=row.get("reference_address", ""),
        amount_lamports=int(row.get("amount_lamports") or 0),
    )
    if details is False:
        return json_response(
            {"error": "contribution_transaction_mismatch"}, status=409)
    if details is None:
        await d1_run(
            env,
            "UPDATE reward_contributions "
            "SET status='awaiting_finality', tx_signature=? "
            "WHERE contribution_id=? AND status='prepared'",
            signature, contribution_id,
        )
        return json_response({
            "ok": True,
            "status": "awaiting_finality",
            "custody": "direct-self-custodial-wallet-to-public-pool",
            "fundsLocation": "awaiting-finalized-public-transfer",
            "notice": (
                "Non-custodial: ForkMesh retained no wallet key. No "
                "distribution occurs until the direct public transfer's "
                "finality is verified."
            ),
        }, status=202, cache_control="no-store")
    completed = await _finalize_reward_contribution(
        env, row, signature, details)
    return json_response({
        "ok": True,
        "status": completed.get("status"),
        "distributionIntentId": str(
            completed.get("distribution_intent_id") or ""),
        "distributionIntentIds": list(
            completed.get("distribution_intent_ids") or []),
        "transactionSignature": signature,
        "explorerUrl": _reward_explorer_url(
            rec.get("network", "mainnet-beta"), signature=signature),
        "custody": "public-community-pool",
        "fundsLocation": "public-community-pool",
        "notice": (
            "The direct wallet-signed contribution is finalized in the public "
            "community pool. ForkMesh retained no contributor key. A prepared "
            "distribution is not complete until its separate finalized "
            "on-chain transfer is verified."
        ),
    }, cache_control="no-store")


def _chain_intent_public(row, include_plan=False):
    row = row or {}
    result = {
        "intentId": str(row.get("intent_id") or ""),
        "kind": str(row.get("kind") or ""),
        "sourceAddress": str(row.get("source_address") or ""),
        "status": str(row.get("status") or ""),
        "createdAt": int(row.get("created_at") or 0),
        "expiresAt": int(row.get("expires_at") or 0),
        "transactionSignature": str(row.get("tx_signature") or ""),
        "completedAt": int(row.get("completed_at") or 0),
        "custody": "external-local-signer",
    }
    if include_plan:
        try:
            plan = json.loads(str(row.get("data") or "{}"))
        except Exception:
            plan = {}
        result["plan"] = plan if isinstance(plan, dict) else {}
    return result


async def _solana_transaction_matches_plan(env, signature, plan):
    """Return True/False for a finalized exact System transfer, None if absent."""
    if not signature or not isinstance(plan, dict):
        return False
    rpc = (
        _reward_solana_rpc
        if str(plan.get("network") or "") in (
            "devnet", "testnet", "mainnet-beta")
        else _solana_rpc
    )
    response = await rpc(
        env,
        "getTransaction",
        [signature, {
            "encoding": "jsonParsed",
            "commitment": "finalized",
            "maxSupportedTransactionVersion": 0,
        }],
    )
    if not isinstance(response, dict):
        return None
    result = response.get("result")
    if result is None:
        return None
    if not isinstance(result, dict):
        return False
    meta = result.get("meta")
    transaction = result.get("transaction")
    if (not isinstance(meta, dict) or meta.get("err") is not None
            or not isinstance(transaction, dict)):
        return False
    signatures = transaction.get("signatures")
    if not isinstance(signatures, list) or signature not in signatures:
        return False
    message = transaction.get("message")
    instructions = (
        message.get("instructions") if isinstance(message, dict) else None)
    if not isinstance(instructions, list):
        return False
    actual = []
    for instruction in instructions:
        if not isinstance(instruction, dict):
            return False
        # The local signer is intentionally limited to ordinary System Program
        # transfers. Any opaque/custom instruction makes the intent unverifiable.
        program = str(instruction.get("program") or "").lower()
        parsed = instruction.get("parsed")
        if program != "system" or not isinstance(parsed, dict):
            return False
        if parsed.get("type") != "transfer":
            return False
        info = parsed.get("info")
        if not isinstance(info, dict):
            return False
        source = str(info.get("source") or "")
        destination = str(info.get("destination") or "")
        try:
            lamports = int(info.get("lamports") or 0)
        except (TypeError, ValueError):
            return False
        if (source != plan.get("sourceAddress")
                or not SOLANA_RE.match(destination) or lamports <= 0):
            return False
        actual.append((destination, lamports))
    expected = []
    for transfer in plan.get("transfers") or []:
        if not isinstance(transfer, dict):
            return False
        destination = str(transfer.get("address") or "")
        try:
            lamports = int(transfer.get("lamports") or 0)
        except (TypeError, ValueError):
            return False
        if not SOLANA_RE.match(destination) or lamports <= 0:
            return False
        expected.append((destination, lamports))
    return bool(expected) and actual == expected


async def _mark_chain_intent_failed(env, row, status):
    """Propagate a rejected/expired chunk to its public contribution batch."""
    if (row or {}).get("kind") != "community_reward_instant_distribution":
        return
    normalized = status if status in ("rejected", "expired") else "rejected"
    await d1_run(
        env,
        "UPDATE reward_contribution_intents SET status=? "
        "WHERE intent_id=?",
        normalized, row.get("intent_id"),
    )
    link = await d1_first(
        env,
        "SELECT contribution_id FROM reward_contribution_intents "
        "WHERE intent_id=?",
        row.get("intent_id"),
    )
    if link:
        await d1_run(
            env,
            "UPDATE reward_contributions SET status='distribution_failed' "
            "WHERE contribution_id=? "
            "AND status='awaiting_distribution'",
            link.get("contribution_id"),
        )


async def _complete_chain_intent(env, row, signature):
    now = int(Date.now())
    await d1_run(
        env,
        "UPDATE chain_intents SET status='completed', tx_signature=?, "
        "completed_at=? WHERE intent_id=? "
        "AND status IN ('pending_signature','submitted')",
        signature, now, row.get("intent_id"),
    )
    try:
        plan = json.loads(str(row.get("data") or "{}"))
    except Exception:
        plan = {}
    if row.get("kind") in (
            "community_reward_random",
            "community_reward_instant_distribution"):
        for transfer in plan.get("transfers") or []:
            address = str(transfer.get("address") or "")
            try:
                lamports = int(transfer.get("lamports") or 0)
            except (TypeError, ValueError):
                lamports = 0
            if SOLANA_RE.match(address) and lamports > 0:
                await _record_funds_received(
                    env, "mainnode", address, "", lamports)
        if row.get("kind") == "community_reward_random":
            await d1_run(
                env,
                "UPDATE reward_rounds SET status='completed', completed_at=? "
                "WHERE intent_id=? AND status='awaiting_signature'",
                now, row.get("intent_id"),
            )
        else:
            await d1_run(
                env,
                "UPDATE reward_contribution_intents SET status='completed' "
                "WHERE intent_id=?",
                row.get("intent_id"),
            )
            link = await d1_first(
                env,
                "SELECT contribution_id FROM reward_contribution_intents "
                "WHERE intent_id=?",
                row.get("intent_id"),
            )
            if link:
                remaining = await d1_first(
                    env,
                    "SELECT COUNT(*) AS c FROM reward_contribution_intents "
                    "WHERE contribution_id=? AND status<>'completed'",
                    link.get("contribution_id"),
                )
                if int((remaining or {}).get("c") or 0) == 0:
                    await d1_run(
                        env,
                        "UPDATE reward_contributions "
                        "SET status='distributed' "
                        "WHERE contribution_id=? "
                        "AND status='awaiting_distribution'",
                        link.get("contribution_id"),
                    )
    if row.get("kind") == "pending_reward":
        await d1_run(
            env,
            "UPDATE pending_rewards SET status='completed', tx_signature=? "
            "WHERE intent_id=? AND status='ready'",
            signature, row.get("intent_id"),
        )


async def reward_signing_jobs_handler(env, request):
    """Local-signer queue: public transfer plans in, signature receipt out."""
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST"):
        return json_response({"error": "method_not_allowed"}, status=405)
    if method == "GET":
        params = parse_qs(urlparse(request.url).query)
        signer = clean_string(
            params.get("signer", [""])[0], MAX_NODE_NAME).strip().lower()
        ts = clean_string(params.get("ts", [""])[0], 20)
        sig = clean_string(params.get("sig", [""])[0], 200)
        canonical = (
            "forkmesh-reward-jobs-v1\n" + signer + "\n" + ts
        ).encode()
        configured = (
            getattr(env, "REWARD_SIGNER_ACCOUNT", "")
            or getattr(env, "INSTANCE_OWNER_ACCOUNT", "")
            or ""
        ).strip().lower()
        if (not configured or signer != configured or not _ts_ok(ts)
                or not await _verify_owner_signature(
                    env, signer, sig, canonical)):
            return json_response({"error": "unauthorized"}, status=401)
        rows = await d1_all(
            env,
            "SELECT * FROM chain_intents WHERE signer_account=? "
            "AND status IN ('pending_signature','submitted') "
            "ORDER BY created_at ASC LIMIT 50",
            signer,
        )
        return json_response({
            "ok": True,
            "jobs": [_chain_intent_public(row, include_plan=True)
                     for row in rows or []],
            "custody": "external-local-signer",
            "notice": (
                "Sign only after the local client validates source, network, "
                "amount limits and every System Program transfer."
            ),
        }, cache_control="no-store")

    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    signer = clean_string(
        data.get("signer", ""), MAX_NODE_NAME).strip().lower()
    intent_id = security_control.normalize_incident_id(data.get("intentId"))
    tx_signature = clean_string(data.get("transactionSignature", ""), 120)
    ts = clean_string(data.get("ts", ""), 20)
    sig = clean_string(data.get("sig", ""), 200)
    configured = (
        getattr(env, "REWARD_SIGNER_ACCOUNT", "")
        or getattr(env, "INSTANCE_OWNER_ACCOUNT", "")
        or ""
    ).strip().lower()
    canonical = (
        "forkmesh-reward-submit-v1\n" + signer + "\n" + intent_id +
        "\n" + tx_signature + "\n" + ts
    ).encode()
    if (not configured or signer != configured or not intent_id
            or not tx_signature or not _ts_ok(ts)
            or not await _verify_owner_signature(env, signer, sig, canonical)):
        return json_response({"error": "unauthorized"}, status=401)
    row = await d1_first(
        env,
        "SELECT * FROM chain_intents WHERE intent_id=? "
        "AND signer_account=?",
        intent_id, signer,
    )
    if not row:
        return json_response({"error": "not_found"}, status=404)
    if row.get("status") == "completed":
        if row.get("tx_signature") != tx_signature:
            return json_response({"error": "intent_already_completed"},
                                 status=409)
        return json_response({
            "ok": True,
            "job": _chain_intent_public(row),
            "custody": "external-local-signer",
            "notice": (
                "The completed state reflects a finalized transfer matching "
                "the exact public plan. ForkMesh never received the local pool "
                "private key."
            ),
        }, cache_control="no-store")
    if row.get("status") not in ("pending_signature", "submitted"):
        return json_response(
            {"error": "intent_not_signable",
             "status": str(row.get("status") or "")},
            status=409,
            cache_control="no-store",
        )
    now = int(Date.now())
    if int(row.get("expires_at") or 0) <= now:
        await d1_run(
            env,
            "UPDATE chain_intents SET status='expired' "
            "WHERE intent_id=? AND status IN "
            "('pending_signature','submitted')",
            intent_id,
        )
        await _mark_chain_intent_failed(env, row, "expired")
        return json_response(
            {"error": "intent_expired"}, status=410,
            cache_control="no-store",
        )
    existing_signature = str(row.get("tx_signature") or "")
    if (row.get("status") == "submitted" and existing_signature
            and existing_signature != tx_signature):
        return json_response(
            {"error": "intent_signature_mismatch"}, status=409,
            cache_control="no-store",
        )
    replay = await d1_first(
        env,
        "SELECT intent_id FROM chain_intents WHERE tx_signature=? "
        "AND intent_id<>?",
        tx_signature, intent_id,
    )
    if replay:
        return json_response({"error": "transaction_replay"}, status=409)
    try:
        plan = json.loads(str(row.get("data") or "{}"))
    except Exception:
        plan = {}
    matches = await _solana_transaction_matches_plan(
        env, tx_signature, plan)
    if matches is False:
        await d1_run(
            env,
            "UPDATE chain_intents SET status='rejected', tx_signature=? "
            "WHERE intent_id=?",
            tx_signature, intent_id,
        )
        await _mark_chain_intent_failed(env, row, "rejected")
        await _audit_sensitive_action(
            env, signer, "reward.intent_reject", "chain_intent", intent_id,
            "denied", {"reason": "transaction_plan_mismatch"})
        return json_response(
            {"error": "transaction_plan_mismatch"}, status=409)
    if matches is None:
        await d1_run(
            env,
            "UPDATE chain_intents SET status='submitted', tx_signature=? "
            "WHERE intent_id=? AND status='pending_signature'",
            tx_signature, intent_id,
        )
        await _audit_sensitive_action(
            env, signer, "reward.intent_submit", "chain_intent", intent_id,
            "requested", {"verification": "pending_finality"})
        return json_response({
            "ok": True,
            "status": "submitted",
            "verification": "pending_finality",
            "custody": "external-local-signer",
            "fundsState": "pending-finality",
            "notice": (
                "Submission is not a completed transfer. The pool private key "
                "remained on the owner device, and completion requires a "
                "finalized transaction matching the exact public plan."
            ),
        }, status=202, cache_control="no-store")
    await _complete_chain_intent(env, row, tx_signature)
    await _audit_sensitive_action(
        env, signer, "reward.intent_complete", "chain_intent", intent_id,
        "success", {"verification": "finalized_exact_plan"})
    row["status"] = "completed"
    row["tx_signature"] = tx_signature
    row["completed_at"] = int(Date.now())
    return json_response({
        "ok": True,
        "job": _chain_intent_public(row),
        "custody": "external-local-signer",
        "notice": (
            "The completed state reflects a finalized transfer matching the "
            "exact public plan. ForkMesh never received the local pool private "
            "key."
        ),
    }, cache_control="no-store")


async def verify_submitted_chain_intents(env):
    await ensure_schema(env)
    now = int(Date.now())
    expired = await d1_all(
        env,
        "SELECT * FROM chain_intents "
        "WHERE kind='community_reward_instant_distribution' "
        "AND status IN ('pending_signature','submitted') "
        "AND expires_at>0 AND expires_at<=? LIMIT 50",
        now,
    )
    for row in expired or []:
        await d1_run(
            env,
            "UPDATE chain_intents SET status='expired' "
            "WHERE intent_id=? "
            "AND status IN ('pending_signature','submitted')",
            row.get("intent_id"),
        )
        await _mark_chain_intent_failed(env, row, "expired")
    rows = await d1_all(
        env,
        "SELECT * FROM chain_intents WHERE status='submitted' "
        "ORDER BY created_at ASC LIMIT 25",
    )
    for row in rows or []:
        try:
            plan = json.loads(str(row.get("data") or "{}"))
        except Exception:
            plan = {}
        matches = await _solana_transaction_matches_plan(
            env, row.get("tx_signature"), plan)
        if matches is True:
            await _complete_chain_intent(
                env, row, row.get("tx_signature"))
        elif matches is False:
            await d1_run(
                env,
                "UPDATE chain_intents SET status='rejected' "
                "WHERE intent_id=?",
                row.get("intent_id"),
            )
            await _mark_chain_intent_failed(env, row, "rejected")


async def pending_reward_award_handler(env, request):
    """Create a 24-hour ledger allocation authorized by the local signer owner."""
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    signer = clean_string(
        data.get("signer", ""), MAX_NODE_NAME).strip().lower()
    recipient = clean_string(
        data.get("recipient", ""), MAX_NODE_NAME).strip().lower()
    ts = clean_string(data.get("ts", ""), 20)
    sig = clean_string(data.get("sig", ""), 200)
    try:
        amount = int(data.get("amountLamports") or 0)
    except (TypeError, ValueError):
        amount = 0
    configured = (
        getattr(env, "REWARD_SIGNER_ACCOUNT", "")
        or getattr(env, "INSTANCE_OWNER_ACCOUNT", "")
        or ""
    ).strip().lower()
    canonical = (
        "forkmesh-pending-award-v1\n" + signer + "\n" + recipient
        + "\n" + str(amount) + "\n" + ts
    ).encode()
    if (not configured or signer != configured or not recipient
            or not _ts_ok(ts)
            or not await _verify_owner_signature(
                env, signer, sig, canonical)):
        return json_response({"error": "unauthorized"}, status=401)
    if not (1_000 <= amount <= 10 * LAMPORTS_PER_SOL):
        return json_response({"error": "invalid_reward_amount"}, status=400)
    recipient_bi, recipient_rec = await _account_row(env, recipient)
    if (not recipient_rec
            or recipient_rec.get("status") != "active"):
        return json_response({"error": "recipient_not_found"}, status=404)
    if SOLANA_RE.match(str(recipient_rec.get("solana") or "")):
        return json_response(
            {"error": "recipient_already_has_payout_wallet"}, status=409)
    source = await _central_fund_record(env)
    if not source:
        return json_response(
            {"error": "community_pool_not_configured"}, status=503)
    now = int(Date.now())
    reward_id = _random_bytes(16).hex()
    expires_at = now + REWARD_PENDING_EXPIRES_MS
    await d1_run(
        env,
        "INSERT INTO pending_rewards "
        "(reward_id,recipient_bi,recipient_name,source_address,"
        "amount_lamports,status,created_at,expires_at) "
        "VALUES (?,?,?, ?,?,'pending_wallet',?,?)",
        reward_id, recipient_bi, "", source.get("address", ""),
        amount, now, expires_at,
    )
    await enqueue_notification(
        env, recipient, "pending_reward",
        "Community reward pending",
        body=(
            "Add a public self-custodial Solana address within 24 hours "
            "to claim this allocation."
        ),
        source="community_reward",
        dedupe="pending_reward:" + reward_id,
    )
    await _audit_sensitive_action(
        env, signer, "reward.pending_allocate", "pending_reward",
        reward_id, "requested", {
            "recipientToken": await blind_index(
                env, "reward-recipient:" + recipient),
            "amountLamports": amount,
            "expiresAt": expires_at,
            "fundsLocation": "external-community-pool",
        })
    return json_response({
        "ok": True,
        "rewardId": reward_id,
        "status": "pending_wallet",
        "amountLamports": amount,
        "createdAt": now,
        "expiresAt": expires_at,
        "fundsLocation": "external-community-pool",
        "custody": "ledger-allocation-only",
        "notice": (
            "No wallet was created and no funds moved. The allocation expires "
            "after 24 hours and remains in its external source wallet unless "
            "the recipient supplies a self-custodial public address."
        ),
    }, status=201, cache_control="no-store")


async def pending_rewards_handler(env, request):
    """Owner ledger for walletless rewards; funds stay in the source wallet."""
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST"):
        return json_response({"error": "method_not_allowed"}, status=405)
    data = {}
    if method == "POST":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
    account_bi, rec = await _account_session_record(env, request, data)
    actor = (rec.get("name", "") if rec else "").strip().lower()
    if not actor:
        return json_response({"error": "invalid_session"}, status=401)
    now = int(Date.now())
    if method == "GET":
        rows = await d1_all(
            env,
            "SELECT reward_id, source_address, amount_lamports, "
            "wallet_address, status, created_at, expires_at, intent_id, "
            "tx_signature FROM pending_rewards WHERE recipient_bi=? "
            "ORDER BY created_at DESC LIMIT 100",
            account_bi,
        )
        rewards = [{
            "rewardId": str(row.get("reward_id") or ""),
            "sourceAddress": str(row.get("source_address") or ""),
            "amountLamports": int(row.get("amount_lamports") or 0),
            "walletAddress": str(row.get("wallet_address") or ""),
            "status": str(row.get("status") or ""),
            "createdAt": int(row.get("created_at") or 0),
            "expiresAt": int(row.get("expires_at") or 0),
            "intentId": str(row.get("intent_id") or ""),
            "transactionSignature": str(row.get("tx_signature") or ""),
            "fundsLocation": (
                "external-source-wallet"
                if row.get("status") != "completed"
                else "completed-on-chain-transfer"),
        } for row in rows or []]
        return json_response({
            "ok": True,
            "rewards": rewards,
            "custody": "external-local-signer",
            "notice": (
                "A pending reward is a temporary ledger allocation. ForkMesh "
                "does not create a wallet or hold funds for you."
            ),
        }, cache_control="no-store")

    reward_id = security_control.normalize_incident_id(data.get("rewardId"))
    wallet = clean_string(data.get("walletAddress", ""), 64).strip()
    if not reward_id or not SOLANA_RE.match(wallet):
        return json_response({"error": "invalid_reward_claim"}, status=400)
    row = await d1_first(
        env,
        "SELECT * FROM pending_rewards WHERE reward_id=? "
        "AND recipient_bi=?",
        reward_id, account_bi,
    )
    if not row:
        return json_response({"error": "not_found"}, status=404)
    if row.get("status") == "completed":
        return json_response({
            "ok": True, "status": "completed",
            "transactionSignature": str(row.get("tx_signature") or ""),
            "fundsLocation": "completed-on-chain-transfer",
            "custody": "external-self-custodial-recipient",
            "notice": (
                "This reward is complete only because its finalized public "
                "transaction was verified. ForkMesh did not create or retain "
                "a wallet or private key for the recipient."
            ),
        }, cache_control="no-store")
    if row.get("status") != "pending_wallet":
        return json_response({"error": "reward_not_claimable"}, status=409)
    if int(row.get("expires_at") or 0) <= now:
        await d1_run(
            env,
            "UPDATE pending_rewards SET status='expired' "
            "WHERE reward_id=? AND status='pending_wallet'",
            reward_id,
        )
        return json_response({
            "error": "reward_expired",
            "fundsLocation": "external-source-wallet",
            "custody": "ledger-allocation-only",
            "notice": (
                "The ledger allocation expired without a transfer. No wallet "
                "was created, and the funds remain in the external source "
                "wallet."
            ),
        }, status=410, cache_control="no-store")
    signer = (
        getattr(env, "REWARD_SIGNER_ACCOUNT", "")
        or getattr(env, "INSTANCE_OWNER_ACCOUNT", "")
        or ""
    ).strip().lower()
    if not signer:
        return json_response(
            {"error": "external_signer_not_configured"}, status=503)
    intent_id = _random_bytes(16).hex()
    plan = {
        "v": 2,
        "network": _reward_network(env),
        "sourceAddress": str(row.get("source_address") or ""),
        "custody": {
            "forkMeshHoldsUserKeys": False,
            "fundsRemainInSourceWalletUntilSigned": True,
        },
        "signing": {
            "required": True,
            "performed": False,
            "method": "external-local-qt",
        },
        "transfers": [{
            "address": wallet,
            "lamports": int(row.get("amount_lamports") or 0),
        }],
        "policy": "pending-reward-claim-v1",
        "rewardId": reward_id,
        "generatedAt": now,
    }
    await d1_run(
        env,
        "INSERT INTO chain_intents "
        "(intent_id, kind, source_address, signer_account, status, data, "
        "created_at, expires_at) VALUES "
        "(?,?,?,?,'pending_signature',?,?,?)",
        intent_id, "pending_reward", row.get("source_address"), signer,
        json.dumps(plan, sort_keys=True, separators=(",", ":")),
        now, int(row.get("expires_at") or 0),
    )
    await d1_run(
        env,
        "UPDATE pending_rewards SET wallet_address=?, status='ready', "
        "intent_id=? WHERE reward_id=? AND recipient_bi=? "
        "AND status='pending_wallet'",
        wallet, intent_id, reward_id, account_bi,
    )
    await _audit_sensitive_action(
        env, actor, "reward.wallet_claim", "pending_reward", reward_id,
        "requested", {"intentId": intent_id})
    return json_response({
        "ok": True,
        "status": "ready",
        "intentId": intent_id,
        "custody": "external-local-signer",
        "fundsLocation": "external-source-wallet",
        "notice": (
            "Ready means an unsigned plan is awaiting explicit approval by the "
            "external local signer. Funds remain in the source wallet until a "
            "matching transfer is signed and finalized."
        ),
    }, status=202, cache_control="no-store")


async def expire_pending_rewards(env):
    await ensure_schema(env)
    now = int(Date.now())
    await d1_run(
        env,
        "UPDATE pending_rewards SET status='expired', wallet_address='' "
        "WHERE status='pending_wallet' AND expires_at<=?",
        now,
    )
    # A signing plan not completed before the allocation deadline expires too;
    # the source wallet never sent funds, so this releases the reservation.
    await d1_run(
        env,
        "UPDATE chain_intents SET status='expired' "
        "WHERE kind='pending_reward' "
        "AND status IN ('pending_signature','submitted') "
        "AND expires_at>0 AND expires_at<=?",
        now,
    )
    await d1_run(
        env,
        "UPDATE pending_rewards SET status='expired', wallet_address='' "
        "WHERE status='ready' AND expires_at<=? "
        "AND intent_id IN (SELECT intent_id FROM chain_intents "
        "WHERE status='expired')",
        now,
    )


# --- Disabled legacy issue-bounty storage -----------------------------------
# Worker-created escrow wallets and automatic payouts are frozen. These helpers
# remain solely to read/migrate historical records; new bounty funding must use
# an external self-custodial wallet and a reviewed program or multisig.


async def _bounty_bi(env, owner, repo, number, kind=""):
    # kind "" is an issue bounty (key "<owner>/<repo>#<number>", unchanged);
    # kind "pr" is a per-pull-request bounty (key "…#pr-<number>"), so an issue
    # and a pull request that happen to share a number never collide.
    prefix = (kind + "-") if kind else ""
    return await blind_index(
        env, owner + "/" + repo + "#" + prefix + str(int(number)))


async def _load_bounty(env, bounty_bi):
    row = await d1_first(
        env, "SELECT data FROM issue_bounty WHERE bounty_bi=?", bounty_bi)
    if not row:
        return None
    return await decrypt_row(env, row.get("data", ""))


def _bounty_public(rec):
    # Never leak the deposit key; only payout-safe fields go back to clients.
    legacy_frozen = (
        rec.get("status") != "paid"
        and not bool(rec.get("legacy_custody_migrated_at"))
    )
    return {
        "address": rec.get("address", ""),
        "amountUsd": rec.get("amount_usd", 0),
        "requiredLamports": rec.get("required_lamports", 0),
        "amountSol": _amount_sol(rec.get("required_lamports", 0)),
        "receivedLamports": rec.get("received_lamports", 0),
        "confirmed": bool(rec.get("confirmed")),
        "status": "legacy_frozen" if legacy_frozen
                  else rec.get("status", "open"),
        "custody": (
            "migration-required" if legacy_frozen
            else "completed-on-chain" if rec.get("status") == "paid"
            else "external-self-custodial"),
        "nonCustodialNotice": (
            "New Worker-held escrow is disabled. A legacy escrow can move "
            "only through the operator's offline migration."
        ),
        "featureState": "migration-only",
        "fundsLocation": "historical-external-address",
        "payee": rec.get("payee", ""),
        "payoutSig": rec.get("payout_sig", ""),
        # Never return a payable URI for a frozen historical address.
        "uri": "",
    }


async def bounties_handler(env, request, owner, repo):
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    action = (data.get("action") or "create").strip()

    # A historical bounty row must not turn a private repository name into a
    # probeable status oracle. Resolve the repository and its normal owner/share
    # boundary before deriving or reading the bounty blind index; missing and
    # unauthorized private repositories deliberately share the same 404 shape.
    viewer = await _authed_account_name(env, request, data)
    if await _repository_access_context(
            env, request, owner, repo, viewer=viewer) is None:
        return _private_replica_not_found()

    if action in ("wallet", "create", "payout"):
        return json_response({
            "error": "legacy_custody_disabled",
            "custody": "external-self-custodial",
            "notice": (
                "ForkMesh no longer creates inbuilt wallets or Worker-held "
                "bounty escrow. Use a direct external-wallet payment; pooled "
                "escrow requires a reviewed Solana program or multisig."
            ),
        }, status=410, cache_control="no-store")

    try:
        number = int(data.get("number", 0))
    except (TypeError, ValueError):
        number = 0
    if number <= 0:
        return json_response({"error": "number_required"}, status=400)
    # kind "" is an issue bounty; "pr" is a per-pull-request bounty (issue #347),
    # keyed separately so an issue and a PR sharing a number never collide.
    kind = clean_string(data.get("kind", ""), 8)
    if kind not in ("", "pr"):
        kind = ""
    bounty_bi = await _bounty_bi(env, owner, repo, number, kind)
    rec = await _load_bounty(env, bounty_bi)

    if rec is None:
        return json_response({"error": "no_bounty"}, status=404)

    if action == "status":
        # Public historical status only. Work on a projection so polling never
        # re-encrypts a retained key-bearing row.
        rec = dict(rec)
        if rec.get("status") != "paid" and rec.get("address"):
            balance = await _solana_balance_lamports(env, rec["address"])
            if balance is not None:
                rec["received_lamports"] = int(balance)
                required = int(rec.get("required_lamports", 0) or 0)
                if balance > 0 and balance >= required:
                    rec["confirmed"] = True
                    rec["status"] = "funded"
        return json_response(_bounty_public(rec))

    return json_response({"error": "bad_action"}, status=400)


# Cap on collaborators per repo, so one owner can't fill the table with shares.
MAX_REPO_GRANTEES = 100


async def _active_public_recipient_bundles(env, account_bis):
    """Return each account's newest valid, active public-only MirrorCrypto key.

    A repository owner needs these public halves to seal one ciphertext content
    key to the exact collaborator set.  Private halves never enter this API.
    Invalid or revoked rows are deliberately omitted so callers fail closed
    instead of publishing ciphertext to an unverified/stale recipient.
    """
    unique_bis = []
    seen = set()
    for account_bi in account_bis or []:
        account_bi = str(account_bi or "")
        if account_bi and account_bi not in seen:
            unique_bis.append(account_bi)
            seen.add(account_bi)
    if not unique_bis:
        return {}
    rows = await d1_all(
        env,
        "SELECT account_bi, key_id, public_bundle, created_at FROM "
        "owner_encryption_keys WHERE revoked_at=0 AND account_bi IN (%s) "
        "ORDER BY created_at DESC"
        % ",".join("?" for _ in unique_bis),
        *unique_bis,
    )
    bundles = {}
    for row in rows or []:
        account_bi = str(row.get("account_bi") or "")
        # ORDER BY makes the first valid row the newest for this account.  If a
        # newer malformed row exists, continue so an older *valid and active*
        # registration can still be used.
        if not account_bi or account_bi in bundles:
            continue
        try:
            public_bundle = json.loads(str(row.get("public_bundle") or ""))
        except Exception:
            continue
        valid = security_control.validate_owner_public_bundle(public_bundle)
        if not valid or valid["kid"] != str(row.get("key_id") or ""):
            continue
        bundles[account_bi] = {
            "keyId": valid["kid"],
            "publicBundle": {
                "v": valid["v"],
                "x25519": valid["x25519"],
                "mlkem768": valid["mlkem768"],
            },
            "createdAt": int(row.get("created_at") or 0),
        }
    return bundles


async def shares_handler(env, request, owner, repo):
    # Private-repo collaborator ACL (issue #9). Every operation is authorized by
    # the OWNER account's key — only the owner may grant/revoke/list who a private
    # repo is shared with. A grantee then sees the repo in their authenticated
    # catalog and clones it with their own key (verify_share_view_token); none of
    # that is gated here, only the membership list is.
    await ensure_schema(env)
    method = method_name(request)
    repo_bi = await blind_index(env, owner + "/" + repo)
    audit_repo_target = owner + "/" + repo
    try:
        owner_pub = await _owner_pubkey(env, owner)
    except Exception:
        raise
    if not owner_pub:
        return json_response({"error": "account_required"}, status=403)

    if method == "GET":
        # List current grantees for the owner's Collaborators UI. Owner-signed so
        # the membership of a private repo isn't world-readable.
        params = parse_qs(urlparse(request.url).query)
        ts = clean_string(params.get("ts", [""])[0], 20)
        sig = clean_string(params.get("sig", [""])[0], 200)
        canonical = ("forkmesh-shares-list-v1\n" + owner + "\n" + repo + "\n" +
                     str(ts)).encode()
        if not (_ts_ok(ts) and await ed25519_verify(owner_pub, sig, canonical)):
            return json_response({"error": "unauthorized"}, status=401)
        rows = await d1_all(
            env,
            "SELECT grantee_bi, data FROM repo_shares "
            "WHERE repo_bi=? ORDER BY ts ASC",
            repo_bi,
        )
        grantees = []
        grantee_rows = []
        for row in rows:
            rec = await decrypt_row(env, row["data"])
            if rec and rec.get("grantee"):
                grantee = clean_string(
                    rec.get("grantee", ""), MAX_NODE_NAME).lower()
                grantee_bi = str(row.get("grantee_bi") or "")
                if grantee and grantee_bi:
                    grantees.append(grantee)
                    grantee_rows.append((grantee, grantee_bi))
        bundles = await _active_public_recipient_bundles(
            env, [grantee_bi for _, grantee_bi in grantee_rows])
        recipients = []
        missing = []
        for grantee, grantee_bi in grantee_rows:
            bundle = bundles.get(grantee_bi)
            if not bundle:
                missing.append(grantee)
                continue
            recipients.append({"grantee": grantee, **bundle})
        return json_response({
            "ok": True,
            # Retain the names-only field for older owner clients.  It is still
            # behind the owner signature and never enters a public catalog.
            "grantees": grantees,
            "recipients": recipients,
            "encryptionReady": not missing,
            "missingEncryptionKeys": missing,
            "privateKeysStored": False,
        }, cache_control="no-store")

    if method in ("POST", "DELETE"):
        try:
            data = await bounded_json_request(request)
        except Exception:
            data = {}
        # DELETE is accepted as an alias for action=remove so the verb can carry
        # intent even when a client can't easily attach a body to a DELETE.
        action = "remove" if method == "DELETE" else \
            (clean_string(data.get("action", "add"), 12) or "add")
        if action not in ("add", "remove"):
            return json_response({"error": "bad_action"}, status=400)
        audit_action = (
            "repository.collaborator_revoke"
            if action == "remove" else "repository.collaborator_grant")
        grantee = clean_string(data.get("grantee", ""), MAX_NODE_NAME).lower()
        audit_target = (
            audit_repo_target + "/" + grantee
            if grantee else audit_repo_target)
        ts = clean_string(str(data.get("ts", "")), 20)
        sig = clean_string(data.get("sig", ""), 200)
        if not grantee:
            return json_response({"error": "grantee_required"}, status=400)
        if grantee == owner:
            return json_response({"error": "cannot_share_with_self"}, status=400)
        # The action is bound into the signature so an "add" token can never be
        # replayed as a "remove" (or vice versa).
        canonical = ("forkmesh-share-v1\n" + owner + "\n" + repo + "\n" +
                     grantee + "\n" + action + "\n" + str(ts)).encode()
        try:
            authorized = (
                _ts_ok(ts)
                and await ed25519_verify(owner_pub, sig, canonical))
        except Exception:
            await _audit_sensitive_action(
                env, owner, audit_action, "repository_collaborator",
                audit_target, "failed",
                {"reason": "signature_check_error"})
            raise
        if not authorized:
            await _audit_sensitive_action(
                env, owner, audit_action, "repository_collaborator",
                audit_target, "denied", {"reason": "unauthorized"})
            return json_response({"error": "unauthorized"}, status=401)
        grantee_bi = await blind_index(env, grantee)

        if action == "remove":
            try:
                await d1_run(
                    env,
                    "DELETE FROM repo_shares "
                    "WHERE repo_bi=? AND grantee_bi=?",
                    repo_bi, grantee_bi)
            except Exception:
                await _audit_sensitive_action(
                    env, owner, audit_action, "repository_collaborator",
                    audit_target, "failed", {"reason": "mutation_error"})
                raise
            await _audit_sensitive_action(
                env, owner, audit_action, "repository_collaborator",
                audit_target, "success")
            return json_response({"ok": True, "grantee": grantee, "shared": False})

        # add: the grantee must be a real account (so a token signed by their key
        # can ever verify), and the per-repo cap must not be exceeded.
        try:
            if not await _owner_pubkey(env, grantee):
                await _audit_sensitive_action(
                    env, owner, audit_action, "repository_collaborator",
                    audit_target, "denied", {"reason": "unknown_account"})
                return json_response({"error": "unknown_account"}, status=404)
            recipient_bundles = await _active_public_recipient_bundles(
                env, [grantee_bi])
            recipient = recipient_bundles.get(grantee_bi)
            if not recipient:
                # Do not create an ACL that the owner cannot immediately turn
                # into an exact encrypted recipient set.
                await _audit_sensitive_action(
                    env, owner, audit_action, "repository_collaborator",
                    audit_target, "denied",
                    {"reason": "encryption_key_required"})
                return json_response({
                    "error": "grantee_encryption_key_required",
                    "grantee": grantee,
                    "shared": False,
                }, status=409, cache_control="no-store")
            existing = await d1_first(
                env,
                "SELECT 1 AS one FROM repo_shares "
                "WHERE repo_bi=? AND grantee_bi=?",
                repo_bi, grantee_bi)
            if not existing:
                count_row = await d1_first(
                    env,
                    "SELECT COUNT(*) AS n FROM repo_shares WHERE repo_bi=?",
                    repo_bi)
                if (
                    count_row
                    and int(count_row.get("n") or 0) >= MAX_REPO_GRANTEES
                ):
                    await _audit_sensitive_action(
                        env, owner, audit_action,
                        "repository_collaborator", audit_target, "denied",
                        {"reason": "collaborator_limit"})
                    return json_response(
                        {"error": "too_many_grantees"}, status=429)
            now = int(Date.now())
            enc = await encrypt_row(
                env,
                {"grantee": grantee, "owner": owner, "repo": repo, "ts": now})
            await d1_run(
                env,
                "INSERT INTO repo_shares (repo_bi, grantee_bi, data, ts) "
                "VALUES (?,?,?,?) ON CONFLICT(repo_bi, grantee_bi) DO UPDATE SET "
                "data=excluded.data, ts=excluded.ts",
                repo_bi, grantee_bi, enc, now)
        except Exception:
            await _audit_sensitive_action(
                env, owner, audit_action, "repository_collaborator",
                audit_target, "failed", {"reason": "mutation_error"})
            raise
        await _audit_sensitive_action(
            env, owner, audit_action, "repository_collaborator",
            audit_target, "success", {"alreadyPresent": bool(existing)})
        await enqueue_notification(env, grantee, "repo_shared",
                                   owner + " shared " + owner + "/" + repo + " with you",
                                   body="You can now view and clone this private repository with your own node key.",
                                   repo=owner + "/" + repo,
                                   href=repo_web_href(owner, repo),
                                   actor=owner, source="repo_share",
                                   dedupe="share:" + owner + "/" + repo + ":" + grantee)
        return json_response({
            "ok": True,
            "grantee": grantee,
            "shared": True,
            "recipient": {"grantee": grantee, **recipient},
            "privateKeysStored": False,
        }, cache_control="no-store")

    return json_response({"error": "method_not_allowed"}, status=405)


# --- Organizations + teams (issue #388) --------------------------------------
# Users create organizations, add accounts to them, and group members into
# teams that hold one repository permission over every repo linked under the
# org. Org owners/admins administer the org itself and implicitly hold 'admin'
# repo permission; plain members hold 'read'; team membership raises that to
# the team's permission. The org name fronts the linked repos' URLs — the
# /<org>/<repo> git endpoints and /api/repo/<org>/<repo>/... are rewritten to
# the hosting node's namespace before routing (see org_alias_rewrite), so
# mirror nodes and clients keep operating on the canonical node namespace
# while the public URL shows the organization's name.

ORG_ROLES = ("owner", "admin", "member")
# Repository permission ladder, weakest to strongest (issue #388: read /
# write / maintain / admin). Tuple order IS the ranking.
TEAM_PERMISSIONS = ("read", "write", "maintain", "admin")
MAX_ORGS_PER_ACCOUNT = 10
MAX_ORG_MEMBERS = 200
MAX_ORG_TEAMS = 50
MAX_ORG_REPOS = 200
ORG_WORLD_ACCESS_VALUES = ("public", "restricted", "private")

# Org repo-alias resolution memo: "org/repo" -> (node owner or "", ts),
# per-isolate so the hot repo/git routes don't pay a D1 read per request
# (including the common negative case: the owner segment is a plain node
# name). Short TTL so a new link/unlink takes effect quickly; mutating
# handlers clear it inline for same-isolate read-your-writes.
_ORG_ALIAS_MEMO = {}
ORG_ALIAS_MEMO_TTL_MS = 30 * 1000
ORG_ALIAS_MEMO_MAX = 512


def _org_logo_url(value):
    raw = clean_string(value or "", 500).strip()
    if not raw:
        return ""
    try:
        parsed = urlparse(raw)
    except Exception:
        return ""
    if (
        parsed.scheme != "https"
        or not parsed.hostname
        or parsed.username is not None
        or parsed.password is not None
        or parsed.fragment
    ):
        return ""
    return parsed.geturl()


def _org_world_access(value, fallback=None):
    source = value if isinstance(value, dict) else {}
    base = {"lobby": "public", "floors": "restricted",
            "offices": "restricted"}
    if isinstance(fallback, dict):
        for field in base:
            selected = str(fallback.get(field) or "").strip().lower()
            if selected in ORG_WORLD_ACCESS_VALUES:
                base[field] = selected
    return {
        field: (
            str(source.get(field) or base.get(field) or "").strip().lower()
            if str(source.get(field) or base.get(field) or "").strip().lower()
            in ORG_WORLD_ACCESS_VALUES
            else base[field]
        )
        for field in ("lobby", "floors", "offices")
    }


def _org_world_access_allowed(level, viewer_role):
    level = str(level or "private").lower()
    role = str(viewer_role or "").lower()
    if level == "public":
        return True
    if level == "restricted":
        return role in ORG_ROLES
    return role in ("owner", "admin")


def team_permission_rank(permission):
    # Index into TEAM_PERMISSIONS, -1 for unknown — so comparisons read as
    # rank(x) >= rank("write") and an unknown permission never qualifies.
    try:
        return TEAM_PERMISSIONS.index((permission or "").strip().lower())
    except ValueError:
        return -1


async def _org_row(env, org):
    # (org_bi, orgs row or None) for an org name. org_bi is keyed under an
    # "org:" prefix so it can never collide with an account blind index.
    org = (org or "").strip().lower()
    org_bi = await blind_index(env, "org:" + org)
    row = await d1_first(
        env, "SELECT name, data, created_at FROM orgs WHERE org_bi=?", org_bi)
    return org_bi, row


async def _org_role(env, org_bi, account):
    # The account's role in the org ('owner'/'admin'/'member') or "".
    if not account:
        return ""
    member_bi = await blind_index(env, account)
    row = await d1_first(
        env, "SELECT role FROM org_members WHERE org_bi=? AND member_bi=?",
        org_bi, member_bi)
    return str((row or {}).get("role") or "")


async def _org_permission(env, org_bi, account):
    # The strongest repository permission `account` holds in the org: role
    # owner/admin => 'admin', plain membership => 'read', team membership
    # raises 'read' to the best team's permission. "" for non-members.
    role = await _org_role(env, org_bi, account)
    if role in ("owner", "admin"):
        return "admin"
    if not role:
        return ""
    member_bi = await blind_index(env, account)
    rows = await d1_all(
        env,
        "SELECT t.permission AS permission FROM org_team_members m "
        "JOIN org_teams t ON t.org_bi = m.org_bi AND t.team = m.team "
        "WHERE m.org_bi=? AND m.member_bi=?",
        org_bi, member_bi)
    best = "read"
    for row in rows or []:
        perm = str(row.get("permission") or "")
        if team_permission_rank(perm) > team_permission_rank(best):
            best = perm
    return best


async def _org_write_allowed(env, owner, repo, pusher):
    # True when some org links owner/repo and the pusher holds write-or-better
    # permission there. Fail closed: any error must never grant push access.
    if not owner or not repo or not pusher:
        return False
    try:
        await ensure_schema(env)
        rows = await d1_all(
            env, "SELECT org_bi FROM org_repos WHERE node_owner=? AND repo=?",
            owner.lower(), repo.lower())
        for row in rows or []:
            perm = await _org_permission(
                env, str(row.get("org_bi") or ""), pusher)
            if team_permission_rank(perm) >= team_permission_rank("write"):
                return True
        return False
    except Exception:
        return False


async def verify_org_push_token(env, pusher, owner, repo, ts, sig):
    # Org-team write gate for git push (issue #388): a member of an org team
    # with write+ permission on a linked repo may run receive-pack against it,
    # signing with their OWN key (the node owner never hands out its key).
    # Distinct canonical prefix so an owner push token or a share-view token
    # can never be replayed here, and vice versa. owner/repo are the CANONICAL
    # node namespace — the org alias is rewritten away before the push gate.
    if not pusher or not owner or not repo or not sig or not _ts_ok(ts):
        return False
    if pusher == owner:
        return False  # the owner authenticates via verify_push_token, not here
    pubkey = await _owner_pubkey(env, pusher)
    if not pubkey:
        return False
    canonical = ("forkmesh-org-push-v1\n" + pusher + "\n" + owner + "\n" +
                 repo + "\n" + str(ts)).encode()
    if not await ed25519_verify(pubkey, sig, canonical):
        return False
    return await _org_write_allowed(env, owner, repo, pusher)


async def _org_repo_node(env, org, repo):
    # Node owner serving /<org>/<repo>, or "" when the pair is not a
    # registered alias. Fail closed on any error: "" simply means "not an org
    # URL" and the request proceeds unrewritten.
    org = (org or "").strip().lower()
    repo = (repo or "").strip().lower()
    if not org or not repo:
        return ""
    now = int(Date.now())
    key = org + "/" + repo
    hit = _ORG_ALIAS_MEMO.get(key)
    if hit and now - hit[1] < ORG_ALIAS_MEMO_TTL_MS:
        return hit[0]
    node = ""
    try:
        await ensure_schema(env)
        org_bi = await blind_index(env, "org:" + org)
        row = await d1_first(
            env, "SELECT node_owner FROM org_repos WHERE org_bi=? AND repo=?",
            org_bi, repo)
        node = str((row or {}).get("node_owner") or "").strip().lower()
        if not valid_node_name(node) or node == org:
            node = ""
    except Exception:
        return ""
    if len(_ORG_ALIAS_MEMO) >= ORG_ALIAS_MEMO_MAX:
        _ORG_ALIAS_MEMO.clear()
    _ORG_ALIAS_MEMO[key] = (node, now)
    return node


async def org_alias_rewrite(env, request, url):
    # Organization repo aliases (issue #388): the /<org>/<repo> git endpoints
    # and every /api/repo/<org>/<repo>/... path serve the linked node's repo
    # under the organization's name. The rewrite is worker-internal — no
    # redirect, the org name stays in the address bar and clone URL — and runs
    # before any route matching, so everything downstream (auth canonicals,
    # direct gateway routing and blind indexes) sees the canonical
    # /<node>/<repo> path exactly as if the node
    # URL had been requested. Org names can never collide with account names
    # (both creation paths reject the other namespace), so an existing node's
    # URL is never rewritten. Returns the rewritten (request, url) or None.
    match = (REPO_API_PREFIX_RE.match(url.path) or GIT_INFO_RE.match(url.path)
             or GIT_PACK_RE.match(url.path) or GIT_RECEIVE_RE.match(url.path))
    if not match:
        return None
    owner = safe_segment(match.group(1))
    repo = safe_segment(match.group(2))
    if not owner or not repo:
        return None
    node = await _org_repo_node(env, owner, repo)
    if not node:
        return None
    new_path = (url.path[:match.start(1)] + quote(node) +
                url.path[match.end(1):])
    new_url = url._replace(path=new_path).geturl()
    # Route internally with the canonical parsed URL while preserving the
    # original Request object.  Fetch's second Request constructor argument is
    # a RequestInit mapping, not another Request; passing the Worker Request
    # there aborts the Python isolate.  Downstream handlers receive owner/repo
    # from the rewritten URL, while retaining the single-use body, trusted
    # request.cf metadata, headers, and the public alias URL presented by the
    # caller.
    return request, urlparse(new_url)


class _OrganizationSuccessionRuntime:
    """Least-privilege adapter for organization-role succession.

    Deliberately absent: platform-admin checks, repository/account mutation,
    encryption-key access, wallet/reward helpers, agent state, and device
    ownership mutation. Device/node timestamps are read only to establish the
    configured owner's most recent activity.
    """

    def __init__(self, env, request=None):
        self.env = env
        self.request = request

    def method(self):
        return method_name(self.request) if self.request is not None else "GET"

    def now(self):
        return int(Date.now())

    def new_id(self):
        return _ap_uuid()

    def response(self, data, status=200, cache_control=None,
                 extra_headers=None):
        return json_response(
            data,
            status=status,
            cache_control=cache_control,
            extra_headers=extra_headers,
        )

    async def ensure_schema(self):
        await ensure_schema(self.env)

    async def json_body(self, limit):
        if self.request is None:
            return None, "invalid_json"
        try:
            raw_length = self.request.headers.get("content-length") or ""
            if raw_length and int(raw_length) > int(limit):
                return None, "payload_too_large"
        except (TypeError, ValueError):
            return None, "invalid_content_length"
        try:
            raw = await self.request.text()
        except Exception:
            return None, "invalid_json"
        if len(str(raw or "").encode("utf-8")) > int(limit):
            return None, "payload_too_large"
        if not str(raw or "").strip():
            return {}, ""
        try:
            data = json.loads(raw)
        except Exception:
            return None, "invalid_json"
        return (data, "") if isinstance(data, dict) else (None, "invalid_json")

    async def session(self, data=None):
        return await _account_session_record(
            self.env, self.request,
            data if isinstance(data, dict) else {})

    async def organization(self, org):
        return await _org_row(self.env, org)

    async def org_role(self, org_bi, account):
        return await _org_role(self.env, org_bi, account)

    async def org_members(self, org_bi):
        return await d1_all(
            self.env,
            "SELECT member_bi,name,role,created_at FROM org_members "
            "WHERE org_bi=? ORDER BY created_at ASC",
            org_bi,
        )

    async def account(self, name):
        name = clean_string(name or "", MAX_NODE_NAME).strip().lower()
        if not valid_node_name(name):
            return "", ""
        account_bi, rec = await _account_row(self.env, name)
        if (
            not rec
            or rec.get("status") != "active"
            or _account_kind(rec) != "user"
        ):
            return "", ""
        return str(account_bi or ""), name

    async def owner_activity(self, owner_bi, stored_at):
        # Only generalized last-seen maxima are used; no device identifier,
        # label, platform, location, user-agent, or personal payload enters
        # succession storage or responses.
        device = await d1_first(
            self.env,
            "SELECT COALESCE(MAX(last_seen),0) AS last_seen "
            "FROM account_devices WHERE account_bi=? AND enabled=1 "
            "AND revoked_at=0",
            owner_bi,
        )
        node = await d1_first(
            self.env,
            "SELECT COALESCE(MAX(last_seen),0) AS last_seen "
            "FROM nodes WHERE user_bi=?",
            owner_bi,
        )
        return max(
            int(stored_at or 0),
            int((device or {}).get("last_seen") or 0),
            int((node or {}).get("last_seen") or 0),
        )

    async def d1_all(self, sql, *args):
        return await d1_all(self.env, sql, *args)

    async def d1_first(self, sql, *args):
        return await d1_first(self.env, sql, *args)

    async def d1_run(self, sql, *args):
        return await d1_run(self.env, sql, *args)

    async def batch(self, statements):
        return await _contribution_run_batch(self.env, statements)

    async def notify(self, recipient, title, body, dedupe):
        return await enqueue_notification(
            self.env,
            recipient,
            "org_succession",
            title,
            body=body,
            href="",
            source="organization_succession",
            dedupe=dedupe,
        )


async def organization_succession_handler(env, request, org, action=""):
    return await organization_succession_api.handle(
        _OrganizationSuccessionRuntime(env, request), org, action)


async def process_organization_succession_warnings(env):
    return await organization_succession_api.process_warnings(
        _OrganizationSuccessionRuntime(env), limit=50)


async def world_organizations_handler(env, request):
    """List only organization lobbies this world viewer may enter.

    The general ``/api/orgs`` collection is a signed-in management list. World
    guests need a separate, deliberately narrow directory so a public lobby is
    discoverable without making restricted/private organizations enumerable.
    Floor repositories, team layouts, and office rosters remain behind their
    independent organization handlers and access checks.
    """
    if method_name(request) != "GET":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            extra_headers={"allow": "GET"})
    await ensure_schema(env)
    _, viewer_rec = await _account_session_record(env, request)
    viewer = (
        viewer_rec.get("name", "") if viewer_rec else ""
    ).strip().lower()
    rows = await d1_all(
        env,
        "SELECT org_bi, name, data, created_at FROM orgs "
        "ORDER BY created_at DESC LIMIT 64",
    )
    organizations = []
    for row in rows or []:
        org_bi = str(row.get("org_bi") or "")
        rec = await decrypt_row(env, row.get("data"))
        if not org_bi or not isinstance(rec, dict):
            continue
        viewer_role = (
            await _org_role(env, org_bi, viewer) if viewer else "")
        access = _org_world_access(rec.get("worldAccess"))
        if not _org_world_access_allowed(access["lobby"], viewer_role):
            continue
        organizations.append({
            "name": str(row.get("name") or ""),
            "displayName": clean_string(rec.get("displayName", ""), 80),
            "description": clean_string(rec.get("description", ""), 500),
            "logoUrl": _org_logo_url(rec.get("logoUrl", "")),
            "role": viewer_role,
            "worldAccess": access,
            "worldCapabilities": {
                "lobby": True,
                "floors": _org_world_access_allowed(
                    access["floors"], viewer_role),
                "offices": _org_world_access_allowed(
                    access["offices"], viewer_role),
            },
        })
    return json_response(
        {
            "ok": True,
            "organizations": organizations,
            "visibility": "enterable-lobbies-only",
        },
        cache_control="no-store, max-age=0, must-revalidate",
        extra_headers={"x-content-type-options": "nosniff"},
    )


async def orgs_handler(env, request):
    # POST /api/orgs creates an organization for the logged-in account (who
    # becomes its first 'owner' member); GET lists the orgs the session
    # account belongs to. Org names share the /<name>/<repo> URL namespace
    # with accounts, so creation rejects any name an account holds — and the
    # account reserve/signup paths reject org names — keeping the org-alias
    # URL rewrite collision-free.
    await ensure_schema(env)
    method = method_name(request)
    if method == "GET":
        account_bi, account_rec = await _account_session_record(env, request)
        if not account_rec:
            return json_response({"error": "invalid_session"}, status=401)
        rows = await d1_all(
            env,
            "SELECT o.name AS name, m.role AS role FROM org_members m "
            "JOIN orgs o ON o.org_bi = m.org_bi WHERE m.member_bi=? "
            "ORDER BY o.name",
            account_bi)
        return json_response({"ok": True, "orgs": [
            {"name": str(r.get("name") or ""), "role": str(r.get("role") or "")}
            for r in rows or []]})
    if method != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    account_bi, account_rec = await _account_session_record(env, request, data)
    if not account_rec:
        return json_response({"error": "invalid_session"}, status=401)
    account = (account_rec.get("name", "") or "").strip().lower()
    name = clean_string(data.get("name", ""), MAX_NODE_NAME).lower()
    if not valid_node_name(name):
        return json_response({"error": "invalid_org_name"}, status=400)
    # The name must be free in BOTH namespaces: any account row (active or
    # mid-signup) blocks it, and so does an existing org.
    _, existing_account = await _account_row(env, name)
    if existing_account:
        return json_response({"error": "org_name_taken"}, status=409)
    org_bi, existing_org = await _org_row(env, name)
    if existing_org:
        return json_response({"error": "org_name_taken"}, status=409)
    owned = await d1_first(
        env,
        "SELECT COUNT(*) AS n FROM org_members WHERE member_bi=? AND role='owner'",
        account_bi)
    if owned and int(owned.get("n") or 0) >= MAX_ORGS_PER_ACCOUNT:
        return json_response({"error": "too_many_orgs"}, status=429)
    now = int(Date.now())
    enc = await encrypt_row(env, {
        "name": name,
        "displayName": clean_string(data.get("displayName", ""), 80),
        "description": clean_string(data.get("description", ""), 500),
        "logoUrl": _org_logo_url(data.get("logoUrl", "")),
        "worldAccess": _org_world_access(data.get("worldAccess")),
        "creator": account,
        "createdAt": now,
    })
    await d1_run(
        env, "INSERT INTO orgs (org_bi, name, data, created_at) VALUES (?,?,?,?)",
        org_bi, name, enc, now)
    await d1_run(
        env,
        "INSERT OR REPLACE INTO org_members "
        "(org_bi, member_bi, role, name, created_at) VALUES (?,?,?,?,?)",
        org_bi, account_bi, "owner", account, now)
    return json_response({"ok": True, "org": name, "role": "owner"}, status=201)


async def org_handler(env, request, org):
    # GET: public org profile (identity, counts, linked repos — the same
    # visibility as the public account lookup). DELETE: dissolve the org and
    # all its rows — org owners only.
    await ensure_schema(env)
    method = method_name(request)
    org_bi, row = await _org_row(env, org)
    if not row:
        return json_response({"error": "not_found"}, status=404)
    if method == "GET":
        rec = await decrypt_row(env, row.get("data")) or {}
        members = await d1_first(
            env, "SELECT COUNT(*) AS n FROM org_members WHERE org_bi=?", org_bi)
        teams = await d1_first(
            env, "SELECT COUNT(*) AS n FROM org_teams WHERE org_bi=?", org_bi)
        repos = await d1_all(
            env,
            "SELECT repo, node_owner FROM org_repos WHERE org_bi=? ORDER BY repo",
            org_bi)
        _, viewer_rec = await _account_session_record(env, request)
        viewer = (viewer_rec.get("name", "") if viewer_rec else "").strip().lower()
        viewer_role = await _org_role(env, org_bi, viewer) if viewer else ""
        world_access = _org_world_access(rec.get("worldAccess"))
        floors_visible = _org_world_access_allowed(
            world_access["floors"], viewer_role)
        visible_repos = []
        for linked in (repos or []) if floors_visible else []:
            linked_repo = safe_segment(str(linked.get("repo") or ""))
            node_owner = clean_string(
                linked.get("node_owner") or "", MAX_NODE_NAME).lower()
            if not linked_repo or not node_owner:
                continue
            if await _repo_is_private(env, node_owner, linked_repo):
                allowed = bool(
                    viewer and (
                        viewer == node_owner
                        or await _account_owns_node(
                            env, viewer, node_owner)
                        or await _repo_shared_with(
                            env, node_owner, linked_repo, viewer)
                    )
                )
                if not allowed:
                    continue
            visible_repos.append({"repo": linked_repo, "node": node_owner})
        return json_response({
            "ok": True,
            "org": str(row.get("name") or ""),
            "displayName": rec.get("displayName", ""),
            "description": rec.get("description", ""),
            "logoUrl": _org_logo_url(rec.get("logoUrl", "")),
            "worldAccess": world_access,
            "worldCapabilities": {
                "lobby": _org_world_access_allowed(
                    world_access["lobby"], viewer_role),
                "floors": floors_visible,
                "offices": _org_world_access_allowed(
                    world_access["offices"], viewer_role),
            },
            "createdAt": int(row.get("created_at") or 0),
            "members": int((members or {}).get("n") or 0),
            "teams": int((teams or {}).get("n") or 0),
            "repos": visible_repos,
            "viewerRole": viewer_role,
        }, cache_control="no-store")
    if method == "PATCH":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        _, account_rec = await _account_session_record(
            env, request, data)
        account = (
            account_rec.get("name", "") if account_rec else ""
        ).strip().lower()
        role = await _org_role(env, org_bi, account) if account else ""
        if role not in ("owner", "admin"):
            return json_response({"error": "forbidden"}, status=403)
        rec = await decrypt_row(env, row.get("data")) or {}
        if "displayName" in data:
            rec["displayName"] = clean_string(
                data.get("displayName", ""), 80)
        if "description" in data:
            rec["description"] = clean_string(
                data.get("description", ""), 500)
        if "logoUrl" in data:
            logo = _org_logo_url(data.get("logoUrl", ""))
            if str(data.get("logoUrl") or "").strip() and not logo:
                return json_response({"error": "invalid_logo_url"}, status=400)
            rec["logoUrl"] = logo
        if "worldAccess" in data:
            if not isinstance(data.get("worldAccess"), dict):
                return json_response(
                    {"error": "invalid_world_access"}, status=400)
            supplied = data["worldAccess"]
            if any(
                str(supplied.get(field) or "").strip().lower()
                not in ORG_WORLD_ACCESS_VALUES
                for field in ("lobby", "floors", "offices")
            ):
                return json_response(
                    {"error": "invalid_world_access"}, status=400)
            rec["worldAccess"] = _org_world_access(
                supplied, rec.get("worldAccess"))
        await d1_run(
            env, "UPDATE orgs SET data=? WHERE org_bi=?",
            await encrypt_row(env, rec), org_bi)
        await _audit_sensitive_action(
            env, account, "organization_world_settings_update",
            "organization", str(row.get("name") or ""),
            outcome="success",
            details={
                "logoChanged": "logoUrl" in data,
                "accessChanged": "worldAccess" in data,
            })
        return json_response({
            "ok": True,
            "org": str(row.get("name") or ""),
            "logoUrl": _org_logo_url(rec.get("logoUrl", "")),
            "worldAccess": _org_world_access(rec.get("worldAccess")),
        }, cache_control="no-store")
    if method == "DELETE":
        try:
            data = await bounded_json_request(request)
        except Exception:
            data = {}
        _, account_rec = await _account_session_record(
            env, request, data)
        account = (account_rec.get("name", "") if account_rec else "").strip().lower()
        if not account:
            return json_response({"error": "invalid_session"}, status=401)
        if await _org_role(env, org_bi, account) != "owner":
            await _audit_sensitive_action(
                env, account, "organization.delete", "organization",
                str(row.get("name") or org), "denied",
                {"reason": "owner_role_required"})
            return json_response({"error": "forbidden"}, status=403)
        try:
            linked = await d1_all(
                env, "SELECT repo FROM org_repos WHERE org_bi=?", org_bi)
            for linked_repo in linked or []:
                scope = str(org).lower() + "/" + str(
                    linked_repo.get("repo") or "").lower()
                await d1_run(
                    env, "DELETE FROM ap_digest_queues WHERE scope_bi=?",
                    await _ap_digest_scope_bi(env, scope))
            await d1_run(env, "DELETE FROM org_repos WHERE org_bi=?", org_bi)
            await d1_run(
                env, "DELETE FROM org_team_members WHERE org_bi=?", org_bi)
            await d1_run(env, "DELETE FROM org_teams WHERE org_bi=?", org_bi)
            await d1_run(env, "DELETE FROM org_members WHERE org_bi=?", org_bi)
            await d1_run(
                env, "DELETE FROM ap_org_digest_settings WHERE org_bi=?", org_bi)
            await d1_run(env, "DELETE FROM orgs WHERE org_bi=?", org_bi)
        except Exception:
            await _audit_sensitive_action(
                env, account, "organization.delete", "organization",
                str(row.get("name") or org), "failed",
                {"reason": "mutation_error"})
            raise
        _ORG_ALIAS_MEMO.clear()
        await _audit_sensitive_action(
            env, account, "organization.delete", "organization",
            str(row.get("name") or org), "success",
            {"linkedRepositories": len(linked or [])})
        return json_response({"ok": True, "org": str(row.get("name") or ""),
                              "deleted": True})
    return json_response({"error": "method_not_allowed"}, status=405)


async def org_members_handler(env, request, org):
    # GET: role-gated office roster according to the organization's world
    # visibility policy. POST: add an account or change its role — this is the
    # "invite": the new member is notified, like a repo share. DELETE: remove
    # a member. Writes require an owner/admin session; only owners may grant,
    # demote, or remove owners/admins, and the last owner can never leave.
    await ensure_schema(env)
    method = method_name(request)
    org_bi, row = await _org_row(env, org)
    if not row:
        return json_response({"error": "not_found"}, status=404)
    org_name = str(row.get("name") or "")
    if method == "GET":
        _, viewer_rec = await _account_session_record(env, request)
        viewer = (
            viewer_rec.get("name", "") if viewer_rec else ""
        ).strip().lower()
        viewer_role = (
            await _org_role(env, org_bi, viewer) if viewer else "")
        org_rec = await decrypt_row(env, row.get("data")) or {}
        access = _org_world_access(org_rec.get("worldAccess"))
        if not _org_world_access_allowed(
                access["offices"], viewer_role):
            return json_response({"error": "forbidden"}, status=403)
        if not viewer_role:
            # A public office hallway does not let an organization expose each
            # member's profile on that person's behalf. Anonymous visitors get
            # an aggregate only; named office cards remain member-visible.
            count = await d1_first(
                env,
                "SELECT COUNT(*) AS n FROM org_members WHERE org_bi=?",
                org_bi,
            )
            return json_response({
                "ok": True,
                "visibility": "public-redacted",
                "memberCount": int((count or {}).get("n") or 0),
                "members": [],
            }, cache_control="no-store")
        rows = await d1_all(
            env,
            "SELECT name, role, created_at FROM org_members WHERE org_bi=? "
            "ORDER BY created_at ASC",
            org_bi)
        # Each member's team list rides along so a roster reader never has to
        # fan out one request per team. This is the same org-internal layout
        # the per-team member listing already shows any member.
        team_rows = await d1_all(
            env,
            "SELECT name, team FROM org_team_members WHERE org_bi=? "
            "ORDER BY team ASC",
            org_bi)
        teams_by_member = {}
        for r in team_rows or []:
            teams_by_member.setdefault(
                str(r.get("name") or ""), []).append(str(r.get("team") or ""))
        return json_response({"ok": True, "visibility": access["offices"],
                              "members": [
            {"name": str(r.get("name") or ""),
             "role": str(r.get("role") or ""),
             "since": int(r.get("created_at") or 0),
             "teams": teams_by_member.get(str(r.get("name") or ""), [])}
            for r in rows or []]}, cache_control="no-store")
    if method not in ("POST", "DELETE"):
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    _, account_rec = await _account_session_record(env, request, data)
    account = (account_rec.get("name", "") if account_rec else "").strip().lower()
    if not account:
        return json_response({"error": "invalid_session"}, status=401)
    member = clean_string(data.get("member", ""), MAX_NODE_NAME).lower()
    caller_role = await _org_role(env, org_bi, account)
    if caller_role not in ("owner", "admin"):
        await _audit_sensitive_action(
            env, account,
            "organization.member_remove"
            if method == "DELETE" else "organization.member_change",
            "organization_member", org_name + "/" + member, "denied",
            {"reason": "insufficient_role"})
        return json_response({"error": "forbidden"}, status=403)
    if not member:
        return json_response({"error": "member_required"}, status=400)
    member_bi = await blind_index(env, member)
    existing = await d1_first(
        env, "SELECT role FROM org_members WHERE org_bi=? AND member_bi=?",
        org_bi, member_bi)
    existing_role = str((existing or {}).get("role") or "")

    if method == "DELETE":
        if not existing:
            return json_response({"error": "not_found"}, status=404)
        if existing_role in ("owner", "admin") and caller_role != "owner":
            await _audit_sensitive_action(
                env, account, "organization.member_remove",
                "organization_member", org_name + "/" + member, "denied",
                {"reason": "owner_role_required",
                 "existingRole": existing_role})
            return json_response({"error": "forbidden"}, status=403)
        if existing_role == "owner" and await _org_owner_count(env, org_bi) <= 1:
            await _audit_sensitive_action(
                env, account, "organization.member_remove",
                "organization_member", org_name + "/" + member, "denied",
                {"reason": "last_owner"})
            return json_response({"error": "last_owner"}, status=400)
        try:
            await d1_run(
                env,
                "DELETE FROM org_team_members WHERE org_bi=? AND member_bi=?",
                org_bi, member_bi)
            await d1_run(
                env, "DELETE FROM org_members WHERE org_bi=? AND member_bi=?",
                org_bi, member_bi)
        except Exception:
            await _audit_sensitive_action(
                env, account, "organization.member_remove",
                "organization_member", org_name + "/" + member, "failed",
                {"reason": "mutation_error",
                 "existingRole": existing_role})
            raise
        await _audit_sensitive_action(
            env, account, "organization.member_remove",
            "organization_member", org_name + "/" + member, "success",
            {"existingRole": existing_role})
        return json_response({"ok": True, "member": member, "removed": True})

    role = clean_string(data.get("role", "member"), 12).lower() or "member"
    if role not in ORG_ROLES:
        return json_response({"error": "bad_role"}, status=400)
    # Only owners hand out (or take away) the administrative roles.
    if caller_role != "owner" and (role in ("owner", "admin") or
                                   existing_role in ("owner", "admin")):
        await _audit_sensitive_action(
            env, account, "organization.role_change",
            "organization_member", org_name + "/" + member, "denied",
            {"reason": "owner_role_required", "role": role,
             "existingRole": existing_role})
        return json_response({"error": "forbidden"}, status=403)
    if (existing_role == "owner" and role != "owner" and
            await _org_owner_count(env, org_bi) <= 1):
        await _audit_sensitive_action(
            env, account, "organization.role_change",
            "organization_member", org_name + "/" + member, "denied",
            {"reason": "last_owner", "role": role,
             "existingRole": existing_role})
        return json_response({"error": "last_owner"}, status=400)
    _, member_rec = await _account_row(env, member)
    if not member_rec:
        return json_response({"error": "unknown_account"}, status=404)
    if not existing:
        count_row = await d1_first(
            env, "SELECT COUNT(*) AS n FROM org_members WHERE org_bi=?", org_bi)
        if count_row and int(count_row.get("n") or 0) >= MAX_ORG_MEMBERS:
            return json_response({"error": "too_many_members"}, status=429)
    audit_action = (
        "organization.role_change"
        if existing else "organization.member_add")
    try:
        await d1_run(
            env,
            "INSERT INTO org_members "
            "(org_bi, member_bi, role, name, created_at) "
            "VALUES (?,?,?,?,?) ON CONFLICT(org_bi, member_bi) DO UPDATE SET "
            "role=excluded.role",
            org_bi, member_bi, role, member, int(Date.now()))
    except Exception:
        await _audit_sensitive_action(
            env, account, audit_action,
            "organization_member", org_name + "/" + member, "failed",
            {"reason": "mutation_error", "role": role,
             "existingRole": existing_role})
        raise
    await _audit_sensitive_action(
        env, account, audit_action,
        "organization_member", org_name + "/" + member, "success",
        {"role": role, "existingRole": existing_role})
    if not existing:
        await enqueue_notification(
            env, member, "org_invite",
            account + " added you to the " + org_name + " organization",
            body="Your role: " + role + ".",
            actor=account, source="org",
            dedupe="org-member:" + org_name + ":" + member)
    return json_response({"ok": True, "member": member, "role": role})


async def _org_owner_count(env, org_bi):
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS n FROM org_members WHERE org_bi=? AND role='owner'",
        org_bi)
    return int((row or {}).get("n") or 0)


async def org_teams_handler(env, request, org):
    # Teams: named member subsets holding one repository permission over the
    # org's linked repos. GET lists them (org members only — the permission
    # layout is org-internal); POST creates a team or updates its permission;
    # DELETE removes a team. Writes require an owner/admin session.
    await ensure_schema(env)
    method = method_name(request)
    org_bi, row = await _org_row(env, org)
    if not row:
        return json_response({"error": "not_found"}, status=404)
    org_name = str(row.get("name") or "")
    if method == "GET":
        _, viewer_rec = await _account_session_record(env, request)
        viewer = (viewer_rec.get("name", "") if viewer_rec else "").strip().lower()
        viewer_role = (
            await _org_role(env, org_bi, viewer) if viewer else "")
        org_rec = await decrypt_row(env, row.get("data")) or {}
        access = _org_world_access(org_rec.get("worldAccess"))
        if not _org_world_access_allowed(
                access["floors"], viewer_role):
            return json_response({"error": "forbidden"}, status=403)
        rows = await d1_all(
            env,
            "SELECT t.team AS team, t.permission AS permission, "
            "COUNT(m.member_bi) AS members FROM org_teams t "
            "LEFT JOIN org_team_members m "
            "ON m.org_bi = t.org_bi AND m.team = t.team "
            "WHERE t.org_bi=? GROUP BY t.team, t.permission ORDER BY t.team",
            org_bi)
        return json_response({"ok": True, "visibility": access["floors"],
                              "teams": [
            {"team": str(r.get("team") or ""),
             "permission": str(r.get("permission") or ""),
             "members": int(r.get("members") or 0)}
            for r in rows or []]}, cache_control="no-store")
    if method not in ("POST", "DELETE"):
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    _, account_rec = await _account_session_record(env, request, data)
    account = (account_rec.get("name", "") if account_rec else "").strip().lower()
    if not account:
        return json_response({"error": "invalid_session"}, status=401)
    team = clean_string(data.get("team", ""), MAX_NODE_NAME).lower()
    if await _org_role(env, org_bi, account) not in ("owner", "admin"):
        await _audit_sensitive_action(
            env, account,
            "organization.team_delete"
            if method == "DELETE" else "organization.team_change",
            "organization_team", org_name + "/" + team, "denied",
            {"reason": "insufficient_role"})
        return json_response({"error": "forbidden"}, status=403)
    if not valid_node_name(team):
        return json_response({"error": "invalid_team_name"}, status=400)
    if method == "DELETE":
        try:
            await d1_run(
                env, "DELETE FROM org_team_members WHERE org_bi=? AND team=?",
                org_bi, team)
            await d1_run(
                env, "DELETE FROM org_teams WHERE org_bi=? AND team=?",
                org_bi, team)
        except Exception:
            await _audit_sensitive_action(
                env, account, "organization.team_delete",
                "organization_team", org_name + "/" + team, "failed",
                {"reason": "mutation_error"})
            raise
        await _audit_sensitive_action(
            env, account, "organization.team_delete",
            "organization_team", org_name + "/" + team, "success")
        return json_response({"ok": True, "team": team, "deleted": True})
    permission = clean_string(data.get("permission", "read"), 12).lower() or "read"
    if permission not in TEAM_PERMISSIONS:
        return json_response({"error": "bad_permission"}, status=400)
    existing = await d1_first(
        env, "SELECT 1 AS one FROM org_teams WHERE org_bi=? AND team=?",
        org_bi, team)
    if not existing:
        count_row = await d1_first(
            env, "SELECT COUNT(*) AS n FROM org_teams WHERE org_bi=?", org_bi)
        if count_row and int(count_row.get("n") or 0) >= MAX_ORG_TEAMS:
            return json_response({"error": "too_many_teams"}, status=429)
    audit_action = (
        "organization.team_permission_change"
        if existing else "organization.team_create")
    try:
        await d1_run(
            env,
            "INSERT INTO org_teams (org_bi, team, permission, created_at) "
            "VALUES (?,?,?,?) ON CONFLICT(org_bi, team) DO UPDATE SET "
            "permission=excluded.permission",
            org_bi, team, permission, int(Date.now()))
    except Exception:
        await _audit_sensitive_action(
            env, account, audit_action,
            "organization_team", org_name + "/" + team, "failed",
            {"reason": "mutation_error", "permission": permission})
        raise
    await _audit_sensitive_action(
        env, account, audit_action,
        "organization_team", org_name + "/" + team, "success",
        {"permission": permission})
    return json_response({"ok": True, "team": team, "permission": permission})


async def org_team_members_handler(env, request, org, team):
    # Who is on one team. GET is org-member visible; POST adds an EXISTING org
    # member to the team (team membership can only ever raise a member's
    # permission, never smuggle in an outsider); DELETE removes. Writes
    # require an owner/admin session.
    await ensure_schema(env)
    method = method_name(request)
    org_bi, row = await _org_row(env, org)
    if not row:
        return json_response({"error": "not_found"}, status=404)
    org_name = str(row.get("name") or "")
    team = (team or "").strip().lower()
    team_row = await d1_first(
        env, "SELECT permission FROM org_teams WHERE org_bi=? AND team=?",
        org_bi, team)
    if not team_row:
        return json_response({"error": "not_found"}, status=404)
    if method == "GET":
        _, viewer_rec = await _account_session_record(env, request)
        viewer = (viewer_rec.get("name", "") if viewer_rec else "").strip().lower()
        if not viewer or not await _org_role(env, org_bi, viewer):
            return json_response({"error": "forbidden"}, status=403)
        rows = await d1_all(
            env,
            "SELECT name, created_at FROM org_team_members "
            "WHERE org_bi=? AND team=? ORDER BY created_at ASC",
            org_bi, team)
        return json_response({
            "ok": True, "team": team,
            "permission": str(team_row.get("permission") or ""),
            "members": [{"name": str(r.get("name") or ""),
                         "since": int(r.get("created_at") or 0)}
                        for r in rows or []]})
    if method not in ("POST", "DELETE"):
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    _, account_rec = await _account_session_record(env, request, data)
    account = (account_rec.get("name", "") if account_rec else "").strip().lower()
    if not account:
        return json_response({"error": "invalid_session"}, status=401)
    member = clean_string(data.get("member", ""), MAX_NODE_NAME).lower()
    audit_action = (
        "organization.team_member_revoke"
        if method == "DELETE" else "organization.team_member_grant")
    if await _org_role(env, org_bi, account) not in ("owner", "admin"):
        await _audit_sensitive_action(
            env, account, audit_action, "organization_team_member",
            org_name + "/" + team + "/" + member, "denied",
            {"reason": "insufficient_role"})
        return json_response({"error": "forbidden"}, status=403)
    if not member:
        return json_response({"error": "member_required"}, status=400)
    member_bi = await blind_index(env, member)
    if method == "DELETE":
        try:
            await d1_run(
                env,
                "DELETE FROM org_team_members "
                "WHERE org_bi=? AND team=? AND member_bi=?",
                org_bi, team, member_bi)
        except Exception:
            await _audit_sensitive_action(
                env, account, audit_action, "organization_team_member",
                org_name + "/" + team + "/" + member, "failed",
                {"reason": "mutation_error"})
            raise
        await _audit_sensitive_action(
            env, account, audit_action, "organization_team_member",
            org_name + "/" + team + "/" + member, "success")
        return json_response({"ok": True, "team": team, "member": member,
                              "removed": True})
    if not await _org_role(env, org_bi, member):
        return json_response({"error": "not_a_member"}, status=400)
    try:
        await d1_run(
            env,
            "INSERT OR IGNORE INTO org_team_members "
            "(org_bi, team, member_bi, name, created_at) VALUES (?,?,?,?,?)",
            org_bi, team, member_bi, member, int(Date.now()))
    except Exception:
        await _audit_sensitive_action(
            env, account, audit_action, "organization_team_member",
            org_name + "/" + team + "/" + member, "failed",
            {"reason": "mutation_error"})
        raise
    await _audit_sensitive_action(
        env, account, audit_action, "organization_team_member",
        org_name + "/" + team + "/" + member, "success")
    return json_response({"ok": True, "team": team, "member": member,
                          "added": True})


async def org_repos_handler(env, request, org):
    # The alias map behind /<org>/<repo> URLs. GET is public routing data.
    # POST links a repo: the caller must be an org owner/admin AND the linked
    # node namespace must be the caller's own account or a node demonstrably
    # owned by that account — you can only bring your own fleet's published
    # repos under an org, so an org can never hijack another node's URL.
    # DELETE unlinks (owner/admin).
    await ensure_schema(env)
    method = method_name(request)
    org_bi, row = await _org_row(env, org)
    if not row:
        return json_response({"error": "not_found"}, status=404)
    org_name = str(row.get("name") or "")
    if method == "GET":
        rows = await d1_all(
            env,
            "SELECT repo, node_owner FROM org_repos WHERE org_bi=? ORDER BY repo",
            org_bi)
        # Organization aliases are public routing data only for explicitly
        # public repositories. A linked private repository is omitted unless
        # the signed-in viewer already owns it or has an explicit repo share;
        # org membership alone is not a plaintext/decryption grant.
        _, viewer_rec = await _account_session_record(env, request)
        viewer = (
            str((viewer_rec or {}).get("name") or "").strip().lower())
        visible = []
        for linked in rows or []:
            linked_repo = safe_segment(str(linked.get("repo") or ""))
            node_owner = clean_string(
                linked.get("node_owner") or "", MAX_NODE_NAME).lower()
            if not linked_repo or not node_owner:
                continue
            if await _repo_is_private(env, node_owner, linked_repo):
                allowed = bool(
                    viewer and (
                        viewer == node_owner
                        or await _account_owns_node(
                            env, viewer, node_owner)
                        or await _repo_shared_with(
                            env, node_owner, linked_repo, viewer)
                    )
                )
                if not allowed:
                    continue
            public_record = {"repo": linked_repo, "node": node_owner}
            # The gateway authorizes an organization SSH path by resolving it
            # back to this linked node before checking the allowlist. Publish
            # that stable organization URL here (rather than leaking the
            # backing-node path into the repo page) only when the backing
            # repository is explicitly enabled for SSH.
            ssh_url = _ssh_alias_repository_url(
                env, org_name, node_owner, linked_repo)
            if ssh_url:
                public_record["sshUrl"] = ssh_url
            visible.append(public_record)
        return json_response({"ok": True, "repos": visible},
                             cache_control="no-store")
    if method not in ("POST", "DELETE"):
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    _, account_rec = await _account_session_record(env, request, data)
    account = (account_rec.get("name", "") if account_rec else "").strip().lower()
    if not account:
        return json_response({"error": "invalid_session"}, status=401)
    repo = safe_segment(clean_string(data.get("repo", ""), MAX_REPO_SEGMENT))
    repo = (repo or "").lower()
    audit_action = (
        "organization.repo_unlink"
        if method == "DELETE" else "organization.repo_link")
    if await _org_role(env, org_bi, account) not in ("owner", "admin"):
        await _audit_sensitive_action(
            env, account, audit_action, "organization_repository",
            org_name + "/" + repo, "denied",
            {"reason": "insufficient_role"})
        return json_response({"error": "forbidden"}, status=403)
    if not repo:
        return json_response({"error": "repo_required"}, status=400)
    if method == "DELETE":
        try:
            await d1_run(
                env, "DELETE FROM org_repos WHERE org_bi=? AND repo=?",
                org_bi, repo)
            await d1_run(
                env, "DELETE FROM ap_digest_queues WHERE scope_bi=?",
                await _ap_digest_scope_bi(
                    env, str(org).lower() + "/" + repo.lower()))
        except Exception:
            await _audit_sensitive_action(
                env, account, audit_action, "organization_repository",
                org_name + "/" + repo, "failed",
                {"reason": "mutation_error"})
            raise
        _ORG_ALIAS_MEMO.clear()
        await _audit_sensitive_action(
            env, account, audit_action, "organization_repository",
            org_name + "/" + repo, "success")
        return json_response({"ok": True, "repo": repo, "linked": False})
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower() or account
    if not await _account_owns_node(env, account, node):
        await _audit_sensitive_action(
            env, account, audit_action, "organization_repository",
            org_name + "/" + repo, "denied",
            {"reason": "not_your_node"})
        return json_response({"error": "not_your_node"}, status=403)
    key_bi = await blind_index(env, node + "/" + repo)
    published = await d1_first(
        env, "SELECT 1 AS one FROM repositories WHERE key_bi=?", key_bi)
    if not published:
        return json_response({"error": "unknown_repo"}, status=404)
    existing = await d1_first(
        env, "SELECT 1 AS one FROM org_repos WHERE org_bi=? AND repo=?",
        org_bi, repo)
    if not existing:
        count_row = await d1_first(
            env, "SELECT COUNT(*) AS n FROM org_repos WHERE org_bi=?", org_bi)
        if count_row and int(count_row.get("n") or 0) >= MAX_ORG_REPOS:
            return json_response({"error": "too_many_repos"}, status=429)
    try:
        await d1_run(
            env,
            "INSERT INTO org_repos (org_bi, repo, node_owner, created_at) "
            "VALUES (?,?,?,?) ON CONFLICT(org_bi, repo) DO UPDATE SET "
            "node_owner=excluded.node_owner",
            org_bi, repo, node, int(Date.now()))
    except Exception:
        await _audit_sensitive_action(
            env, account, audit_action, "organization_repository",
            org_name + "/" + repo, "failed",
            {"reason": "mutation_error"})
        raise
    _ORG_ALIAS_MEMO.clear()
    await _audit_sensitive_action(
        env, account, audit_action, "organization_repository",
        org_name + "/" + repo, "success")
    return json_response({"ok": True, "repo": repo, "node": node,
                          "linked": True})


async def org_fediverse_handler(env, request, org):
    """Org-owner/admin controls for org-alias daily repository digests.

    This endpoint never edits the backing repository's settings. Its `enabled`
    value is an additional AND gate for aliases under this organization, and
    previews include only linked repositories that remain public.
    """
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST"):
        return json_response({"error": "method_not_allowed"}, status=405)
    org_bi, row = await _org_row(env, org)
    if not row:
        return json_response({"error": "not_found"}, status=404)
    data = {}
    if method == "POST":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
    _, account_rec = await _account_session_record(env, request, data)
    account = str((account_rec or {}).get("name") or "").strip().lower()
    if not account:
        return json_response({"error": "invalid_session"}, status=401)
    requested_enabled = (
        data.get("enabled")
        if method == "POST" and isinstance(data.get("enabled"), bool)
        else None)
    audit_action = (
        "organization.fediverse_enable"
        if requested_enabled is True
        else "organization.fediverse_disable"
        if requested_enabled is False
        else "organization.fediverse_change")
    org_name = str(row.get("name") or org)
    if await _org_role(env, org_bi, account) not in ("owner", "admin"):
        if method == "POST":
            await _audit_sensitive_action(
                env, account, audit_action, "organization",
                org_name, "denied", {"reason": "insufficient_role"})
        return json_response({"error": "forbidden"}, status=403)

    controls = await _ap_org_digest_settings_get(env, org_bi)
    if method == "POST":
        if "enabled" not in data or not isinstance(data.get("enabled"), bool):
            await _audit_sensitive_action(
                env, account, audit_action, "organization",
                org_name, "denied", {"reason": "enabled_required"})
            return json_response({"error": "enabled_required"}, status=400)
        controls = fedi_digest.normalize_controls({
            "enabled": data["enabled"], "preview": False})
        try:
            await d1_run(
                env,
                "INSERT INTO ap_org_digest_settings "
                "(org_bi, data, updated_at) VALUES (?,?,?) "
                "ON CONFLICT(org_bi) DO UPDATE SET "
                "data=excluded.data, updated_at=excluded.updated_at",
                org_bi, json.dumps(controls, separators=(",", ":")),
                int(Date.now()))
        except Exception:
            await _audit_sensitive_action(
                env, account, audit_action, "organization",
                org_name, "failed", {"reason": "settings_mutation_error"})
            raise
        await _audit_sensitive_action(
            env, account, audit_action, "organization",
            org_name, "success",
            {"enabled": bool(controls["enabled"])})
        if not controls["enabled"]:
            try:
                queued_scopes = await d1_all(
                    env,
                    "SELECT repo FROM org_repos WHERE org_bi=? "
                    "ORDER BY repo LIMIT ?",
                    org_bi, MAX_ORG_REPOS)
                for item in queued_scopes or []:
                    scope = str(org).lower() + "/" + str(
                        item.get("repo") or "").lower()
                    await d1_run(
                        env, "DELETE FROM ap_digest_queues WHERE scope_bi=?",
                        await _ap_digest_scope_bi(env, scope))
            except Exception:
                await _audit_sensitive_action(
                    env, account, "organization.fediverse_queue_purge",
                    "organization", org_name, "failed",
                    {"reason": "queue_purge_error"})
                raise
            await _audit_sensitive_action(
                env, account, "organization.fediverse_queue_purge",
                "organization", org_name, "success",
                {"linkedScopes": len(queued_scopes or [])})

    linked = await d1_all(
        env,
        "SELECT repo, node_owner FROM org_repos WHERE org_bi=? "
        "ORDER BY repo LIMIT ?",
        org_bi, MAX_ORG_REPOS)
    previews = []
    for item in linked or []:
        repo = clean_string(item.get("repo"), MAX_REPO_SEGMENT).strip()
        source_owner = clean_string(
            item.get("node_owner"), MAX_NODE_NAME).strip().lower()
        if not repo or not source_owner:
            continue
        # Organization membership is not a private-repository content grant.
        # Private links are omitted, exactly like the public org repo list.
        if await _repo_is_private(env, source_owner, repo):
            continue
        owner_settings = await _ap_repo_settings_get(
            env, source_owner, repo)
        preview = await _ap_digest_preview(
            env, str(org).lower() + "/" + repo.lower())
        preview.update({
            "repo": repo,
            "sourceOwner": source_owner,
            "ownerEnabled": bool(
                owner_settings["federate"]
                and owner_settings["broadcastEvents"]),
            "enabled": bool(
                controls["enabled"]
                and owner_settings["federate"]
                and owner_settings["broadcastEvents"]),
        })
        previews.append(preview)
    return json_response({
        "ok": True,
        "org": org_name,
        "controls": controls,
        "repos": previews,
        "ownerBoundary": (
            "Organization controls cannot override repository-owner settings."),
    }, cache_control="no-store")


# --- Admins + manual email verification -------------------------------------
# A user is "set as administrator" via the users.is_admin column in the DB
# (UPDATE users SET is_admin=1 WHERE username='<user>'). Admins' clients are
# notified when a new user joins and can verify the new user's email by hand
# until an email service (e.g. SES) is wired up.

async def _is_admin(env, name):
    # Admin status lives in the users.is_admin column. Grant it directly in the
    # DB: UPDATE users SET is_admin=1 WHERE username='<user>'.
    name = (name or "").strip().lower()
    if not name:
        return False
    name_bi = await blind_index(env, name)
    try:
        row = await d1_first(
            env, "SELECT is_admin FROM users WHERE user_bi=?", name_bi)
    except Exception:
        return False  # column may predate migration 0006
    return bool(row and int(row.get("is_admin", 0) or 0))


async def _has_role(env, name, role, scope_type="platform", scope=""):
    name = clean_string(name or "", MAX_NODE_NAME).strip().lower()
    role = security_control.normalize_role(role)
    scope_type = security_control.normalize_scope_type(scope_type)
    if not name or not role or not security_control.role_scope_allowed(
            role, scope_type):
        return False
    # Preserve the existing administrator flag as the platform-administrator
    # grant only. It does not imply moderator/security-reviewer/decryption roles.
    if (role == "platform_administrator" and scope_type == "platform"
            and await _is_admin(env, name)):
        return True
    await ensure_schema(env)
    account_bi = await blind_index(env, name)
    scope_bi = (
        await blind_index(env, scope)
        if scope_type != "platform" and scope else ""
    )
    now = int(Date.now())
    row = await d1_first(
        env,
        "SELECT 1 AS one FROM role_grants WHERE account_bi=? AND role=? "
        "AND scope_type=? AND scope_bi=? AND revoked_at=0 "
        "AND (expires_at=0 OR expires_at>?)",
        account_bi, role, scope_type, scope_bi, now,
    )
    return bool(row)


async def _audit_sensitive_action(env, actor, action, target_type="",
                                  target="", outcome="success", details=None):
    """Append a metadata-only record for a sensitive state transition."""
    await ensure_schema(env)
    actor = clean_string(actor or "", MAX_NODE_NAME).strip().lower()
    clean_action = re.sub(
        r"[^a-z0-9_.-]", "", str(action or "").strip().lower())[:100]
    clean_target_type = re.sub(
        r"[^a-z0-9_.-]", "", str(target_type or "").strip().lower())[:40]
    clean_outcome = (
        str(outcome or "unknown").strip().lower()
        if str(outcome or "").strip().lower()
        in ("success", "denied", "failed", "requested") else "unknown"
    )
    actor_bi = await blind_index(env, actor) if actor else None
    target_token = (
        await blind_index(
            env, "audit:" + clean_target_type + ":" + str(target or ""))
        if target else ""
    )
    safe_details = security_control.sanitize_audit_details(details or {})
    await d1_run(
        env,
        "INSERT INTO sensitive_audit_log "
        "(ts, actor_bi, actor_label, action, target_type, target_token, "
        "outcome, details) VALUES (?,?,?,?,?,?,?,?)",
        int(Date.now()), actor_bi, actor, clean_action, clean_target_type,
        target_token, clean_outcome,
        json.dumps(safe_details, sort_keys=True, separators=(",", ":")),
    )


async def security_roles_handler(env, request):
    await ensure_schema(env)
    method = method_name(request)
    data = {}
    if method == "POST":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
    _, actor_rec = await _account_session_record(env, request, data)
    actor = (actor_rec.get("name", "") if actor_rec else "").strip().lower()
    if not actor:
        return json_response({"error": "invalid_session"}, status=401)
    is_platform_admin = await _has_role(
        env, actor, "platform_administrator")

    if method == "GET":
        params = parse_qs(urlparse(request.url).query)
        target = clean_string(
            params.get("target", [actor])[0], MAX_NODE_NAME).strip().lower()
        if target != actor and not is_platform_admin:
            return json_response({"error": "forbidden"}, status=403)
        target_bi, target_rec = await _account_row(env, target)
        if not target_rec:
            return json_response({"error": "not_found"}, status=404)
        now = int(Date.now())
        rows = await d1_all(
            env,
            "SELECT role, scope_type, scope_bi, granted_at, expires_at "
            "FROM role_grants WHERE account_bi=? AND revoked_at=0 "
            "AND (expires_at=0 OR expires_at>?) ORDER BY granted_at DESC",
            target_bi, now,
        )
        grants = [{
            "role": security_control.normalize_role(row.get("role")),
            "scopeType": security_control.normalize_scope_type(
                row.get("scope_type")),
            # Scope identifiers are blind indexes. Only the grantee/admin sees
            # the token, and no private repository name is recoverable from it.
            "scopeToken": str(row.get("scope_bi") or ""),
            "grantedAt": int(row.get("granted_at") or 0),
            "expiresAt": int(row.get("expires_at") or 0),
        } for row in rows or [] if security_control.normalize_role(
            row.get("role"))]
        if await _is_admin(env, target):
            grants.append({
                "role": "platform_administrator",
                "scopeType": "platform",
                "scopeToken": "",
                "grantedAt": 0,
                "expiresAt": 0,
                "legacyGrant": True,
            })
        return json_response({
            "ok": True,
            "target": target,
            "grants": grants,
        }, cache_control="no-store")

    if method != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    if not is_platform_admin:
        await _audit_sensitive_action(
            env, actor, "role.change", "role", "", "denied",
            {"reason": "insufficient_role"})
        return json_response({"error": "forbidden"}, status=403)
    target = clean_string(data.get("target", ""), MAX_NODE_NAME).strip().lower()
    role = security_control.normalize_role(data.get("role"))
    scope_type = security_control.normalize_scope_type(
        data.get("scopeType", "platform"))
    scope = clean_string(data.get("scope", ""), 240).strip().lower()
    action = str(data.get("action") or "grant").strip().lower()
    if (not target or not role or not scope_type
            or not security_control.role_scope_allowed(role, scope_type)
            or (scope_type != "platform" and not scope)):
        return json_response({"error": "invalid_role_grant"}, status=400)
    target_bi, target_rec = await _account_row(env, target)
    if not target_rec:
        return json_response({"error": "target_not_found"}, status=404)
    scope_bi = (
        await blind_index(env, scope) if scope_type != "platform" else ""
    )
    now = int(Date.now())
    if action == "revoke":
        await d1_run(
            env,
            "UPDATE role_grants SET revoked_at=? WHERE account_bi=? "
            "AND role=? AND scope_type=? AND scope_bi=?",
            now, target_bi, role, scope_type, scope_bi,
        )
    elif action == "grant":
        try:
            expires_at = int(data.get("expiresAt") or 0)
        except (TypeError, ValueError):
            expires_at = 0
        if expires_at and expires_at <= now:
            return json_response({"error": "invalid_expiration"}, status=400)
        actor_bi = await blind_index(env, actor)
        await d1_run(
            env,
            "INSERT INTO role_grants "
            "(account_bi, role, scope_type, scope_bi, granted_by_bi, "
            "granted_at, expires_at, revoked_at) VALUES (?,?,?,?,?,?,?,0) "
            "ON CONFLICT(account_bi,role,scope_type,scope_bi) DO UPDATE SET "
            "granted_by_bi=excluded.granted_by_bi, "
            "granted_at=excluded.granted_at, "
            "expires_at=excluded.expires_at, revoked_at=0",
            target_bi, role, scope_type, scope_bi, actor_bi, now, expires_at,
        )
    else:
        return json_response({"error": "invalid_action"}, status=400)
    await _audit_sensitive_action(
        env, actor, "role." + action, "account", target, "success",
        {"role": role, "scopeType": scope_type})
    return json_response({
        "ok": True, "action": action, "target": target, "role": role,
        "scopeType": scope_type,
    }, cache_control="no-store")


async def security_audit_handler(env, request):
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    _, rec = await _account_session_record(env, request)
    actor = (rec.get("name", "") if rec else "").strip().lower()
    if not actor or not await _has_role(
            env, actor, "platform_administrator"):
        return json_response({"error": "forbidden"}, status=403)
    rows = await d1_all(
        env,
        "SELECT ts, actor_label, action, target_type, target_token, "
        "outcome, details FROM sensitive_audit_log "
        "ORDER BY id DESC LIMIT 500",
    )
    events = []
    for row in rows or []:
        try:
            details = json.loads(str(row.get("details") or "{}"))
        except Exception:
            details = {}
        events.append({
            "ts": int(row.get("ts") or 0),
            "actor": str(row.get("actor_label") or ""),
            "action": str(row.get("action") or ""),
            "targetType": str(row.get("target_type") or ""),
            "targetToken": str(row.get("target_token") or ""),
            "outcome": str(row.get("outcome") or ""),
            "details": security_control.sanitize_audit_details(details),
        })
    return json_response({"ok": True, "events": events},
                         cache_control="no-store")


async def cleanup_sensitive_audit_records(env):
    await ensure_schema(env)
    now = int(Date.now())
    await d1_run(
        env, "DELETE FROM sensitive_audit_log WHERE ts<?",
        now - SECURITY_AUDIT_RETAIN_MS)


# --- Achievement badges (adhoc #370) -----------------------------------------
# Public recognition marks, similar in shape to org teams: a fixed catalog
# (badges.py) awarded once per account, either automatically at a real
# platform event (see the call sites of _award_badge below) or by a platform
# administrator. Awards are permanent — later losing eligibility does not
# revoke an already-earned badge.
FIRST_100_USERS_LIMIT = 100
WORLD_FIRST_HOUR_BADGE_MS = 60 * 60 * 1000


async def _award_badge(env, name, name_bi, slug, granted_by="system"):
    slug = badge_catalog.normalize_badge_slug(slug)
    if not slug or not name_bi:
        return
    await ensure_schema(env)
    await d1_run(
        env,
        "INSERT OR IGNORE INTO badge_awards "
        "(badge_slug, account_bi, name, granted_by, created_at) "
        "VALUES (?,?,?,?,?)",
        slug, name_bi, name, (granted_by or "system"), int(Date.now()))


async def _account_badges(env, name_bi):
    rows = await d1_all(
        env,
        "SELECT badge_slug, granted_by, created_at FROM badge_awards "
        "WHERE account_bi=? ORDER BY created_at", name_bi)
    out = []
    for row in rows or []:
        info = badge_catalog.badge_definition(row.get("badge_slug"))
        if not info:
            continue
        granted_by = str(row.get("granted_by") or "system")
        out.append({
            "slug": str(row.get("badge_slug") or ""),
            "name": info["name"],
            "description": info["description"],
            "icon": info["icon"],
            "grantedBy": "system" if granted_by == "system" else "admin",
            "awardedAt": int(row.get("created_at") or 0),
        })
    return out


async def badges_catalog_handler(env, request):
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    return json_response(
        {"ok": True, "badges": badge_catalog.public_catalog()},
        cache_seconds=3600)


async def account_badges_handler(env, request, raw_name):
    # GET: the badges one account has earned (public — same visibility as the
    # public account lookup). POST/DELETE: a platform administrator grants or
    # revokes one badge.
    await ensure_schema(env)
    name = clean_string(raw_name or "", MAX_NODE_NAME).strip().lower()
    if not valid_node_name(name):
        return json_response({"error": "invalid_account"}, status=400)
    name_bi, rec = await _account_row(env, name)
    if not rec:
        return json_response({"error": "not_found"}, status=404)
    method = method_name(request)
    if method == "GET":
        return json_response(
            {"ok": True, "account": name,
             "badges": await _account_badges(env, name_bi)},
            cache_seconds=30)
    if method not in ("POST", "DELETE"):
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        data = {}
    _, actor_rec = await _account_session_record(env, request, data)
    actor = (actor_rec.get("name", "") if actor_rec else "").strip().lower()
    audit_action = "badge.grant" if method == "POST" else "badge.revoke"
    if not actor or not await _has_role(env, actor, "platform_administrator"):
        await _audit_sensitive_action(
            env, actor, audit_action, "account_badge", name, "denied",
            {"reason": "insufficient_role"})
        return json_response({"error": "forbidden"}, status=403)
    slug = badge_catalog.normalize_badge_slug(data.get("slug", ""))
    if not slug:
        return json_response({"error": "invalid_badge"}, status=400)
    if method == "DELETE":
        await d1_run(
            env, "DELETE FROM badge_awards WHERE badge_slug=? AND account_bi=?",
            slug, name_bi)
        await _audit_sensitive_action(
            env, actor, audit_action, "account_badge", name + "/" + slug,
            "success")
        return json_response(
            {"ok": True, "account": name, "slug": slug, "revoked": True})
    await _award_badge(env, name, name_bi, slug, granted_by=actor)
    await _audit_sensitive_action(
        env, actor, audit_action, "account_badge", name + "/" + slug,
        "success")
    return json_response(
        {"ok": True, "account": name, "slug": slug, "granted": True},
        status=201)


async def _admin_authorized(env, node, ts, sig, canonical):
    # The requesting admin proves control of their node's key, and the account
    # must have is_admin set. Returns the admin's record on success, else None.
    node = (node or "").strip().lower()
    if not await _is_admin(env, node) or not _ts_ok(ts):
        return None
    _, rec = await _account_row(env, node)
    if not rec or rec.get("status") != "active":
        return None
    pubkey = rec.get("pubkey", "")
    if not pubkey or not await ed25519_verify(pubkey, sig, canonical):
        return None
    return rec


async def _enqueue_verification(env, name_bi, name, email):
    blob = await encrypt_row(
        env, {"name": name, "email": email, "joinedAt": int(Date.now())})
    await d1_run(
        env,
        "INSERT INTO pending_verifications (name_bi, data) VALUES (?,?) "
        "ON CONFLICT(name_bi) DO UPDATE SET data=excluded.data",
        name_bi, blob,
    )


async def _admin_pending(env, request):
    params = parse_qs(urlparse(request.url).query)
    node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    ts = clean_string(params.get("ts", [""])[0], 20)
    sig = clean_string(params.get("sig", [""])[0], 200)
    canonical = ("forkmesh-admin-pending-v1\n" + node + "\n" + ts).encode()
    if not await _admin_authorized(env, node, ts, sig, canonical):
        return json_response({"error": "unauthorized"}, status=401)
    rows = await d1_all(env, "SELECT data FROM pending_verifications")
    pending = [rec for rec in
               [await decrypt_row(env, r["data"]) for r in rows] if rec]
    pending.sort(key=lambda x: x.get("joinedAt", 0))
    return json_response({"ok": True, "pending": pending})


async def _admin_verify_email(env, request):
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower()
    target = clean_string(data.get("target", ""), MAX_NODE_NAME).lower()
    ts = clean_string(data.get("ts", ""), 20)
    sig = clean_string(data.get("sig", ""), 200)
    canonical = ("forkmesh-admin-verify-email-v1\n" + node + "\n" + target +
                 "\n" + ts).encode()
    if not await _admin_authorized(env, node, ts, sig, canonical):
        return json_response({"error": "unauthorized"}, status=401)

    target_bi, trec = await _account_row(env, target)
    if not trec:
        return json_response({"error": "no_such_account"}, status=404)
    trec["email_verified"] = True
    await _save_account(env, target_bi, trec)
    await d1_run(env, "DELETE FROM pending_verifications WHERE name_bi=?", target_bi)
    await _audit_sensitive_action(
        env, node, "admin.email_verify", "account", target, "success", {})
    return json_response({"ok": True, "target": target, "emailVerified": True})


# --- Transactional email (Mailtrap) -----------------------------------------
# Signup confirmation goes out through Mailtrap's HTTP sending API. The token is
# a Worker secret (MAILTRAP_API_TOKEN, pushed from .env.production by deploy.sh).
# When it's unset the sender is a no-op, so a fork without an email provider
# still works — callers fall back to the admin verification queue.
MAILTRAP_SEND_URL = "https://send.api.mailtrap.io/api/send"


async def _send_email(env, to_email, subject, text, html=None,
                      from_email=None, from_name=None):
    token = (getattr(env, "MAILTRAP_API_TOKEN", "") or "").strip()
    if not token or not to_email:
        return False
    sender = (from_email or getattr(env, "MAILTRAP_SENDER", "")
              or "no-reply@forkmesh.com").strip()
    sender_name = (from_name or getattr(env, "MAILTRAP_SENDER_NAME", "")
                   or "ForkMesh").strip()
    url = (getattr(env, "MAILTRAP_API_URL", "") or MAILTRAP_SEND_URL).strip()
    payload = {
        "from": {"email": sender, "name": sender_name},
        "to": [{"email": to_email}],
        "subject": subject,
        "text": text,
    }
    if html:
        payload["html"] = html
    try:
        resp = await js_fetch_with_timeout(
            url,
            {
                "method": "POST",
                "headers": {
                    "content-type": "application/json",
                    "authorization": "Bearer " + token,
                },
                "body": json.dumps(payload),
            },
            CRON_OUTBOUND_FETCH_TIMEOUT_SECONDS,
        )
        return 200 <= int(getattr(resp, "status", 0)) < 300
    except Exception:
        return False


# --- Account email activity ---------------------------------------------------
#
# Every account-directed send stamps the recipient's own (encrypted) record with
# when the mail went out, a coarse kind, and whether the provider accepted it,
# so the account screen can answer "when were they last emailed, and did it
# land?" without a second log table. Subject and body are never stored here, and
# the stamp is private to the account: it rides the authenticated sessions read,
# not the public profile lookup.

ACCOUNT_EMAIL_STATUS_DELIVERED = "delivered"
ACCOUNT_EMAIL_STATUS_FAILED = "failed"


def _stamp_account_email(rec, kind, ok, now=None):
    """Stamp the last account-directed email onto an already-loaded record."""
    if not isinstance(rec, dict):
        return rec
    rec["last_email_ts"] = int(now if now is not None else Date.now())
    rec["last_email_kind"] = clean_string(kind or "", 40)
    rec["last_email_ok"] = bool(ok)
    return rec


async def _record_account_email(env, name, kind, ok):
    """Load, stamp, and persist the record for a send addressed by node name."""
    name = clean_string(name or "", MAX_NODE_NAME).strip().lower()
    if not valid_node_name(name):
        return
    try:
        name_bi, rec = await _account_row(env, name)
        if not name_bi or not rec:
            return
        await _save_account(env, name_bi, _stamp_account_email(rec, kind, ok))
    except Exception:
        pass


def _account_email_activity(rec):
    """Public shape of the last-email stamp for the account screen."""
    try:
        ts = int((rec or {}).get("last_email_ts") or 0)
    except (TypeError, ValueError):
        ts = 0
    if ts <= 0:
        return {"lastEmailAt": 0, "lastEmailStatus": "", "lastEmailKind": ""}
    return {
        "lastEmailAt": ts,
        "lastEmailStatus": (
            ACCOUNT_EMAIL_STATUS_DELIVERED if rec.get("last_email_ok")
            else ACCOUNT_EMAIL_STATUS_FAILED),
        "lastEmailKind": clean_string(rec.get("last_email_kind", ""), 40),
    }


# --- External GitHub/GitLab/Codeberg metadata imports -----------------------
#
# Provider imports live in a separate D1 namespace from the mirror catalog.
# repository_imports.py owns the provider-neutral policy/service layer; these
# small adapters supply Worker HTTP, account authorization, and mirror proof.

async def _repository_provider_fetch(env, provider, path, token=""):
    from js import fetch as js_fetch
    if provider not in repository_import.PROVIDERS:
        return {"status": 400, "data": {}, "headers": {}}
    if (not isinstance(path, str) or not path.startswith("/")
            or len(path) > 2000 or "\r" in path or "\n" in path):
        return {"status": 400, "data": {}, "headers": {}}
    headers = {
        "accept": "application/json",
        "user-agent": "ForkMesh-repository-metadata/1.0",
    }
    if provider == "github":
        headers["accept"] = "application/vnd.github+json"
        headers["x-github-api-version"] = "2026-03-10"
        if token:
            headers["authorization"] = "Bearer " + token
    elif provider == "codeberg":
        # Codeberg runs Forgejo's Gitea-compatible API. Its access token is
        # request-scoped exactly like the other provider credentials and is
        # never persisted or forwarded across a redirect.
        if token:
            headers["authorization"] = "token " + token
    elif token:
        # GitLab personal/project access tokens are scoped request credentials.
        # They are never included in a record, log, exception, or D1 write.
        headers["private-token"] = token
    url = repository_import.provider_api_origin(provider) + path
    try:
        response = await js_fetch(
            url, to_js({"method": "GET", "headers": headers,
                        # Never forward a request-scoped provider credential
                        # across an HTTP redirect. Metadata endpoints are
                        # canonical; a moved repository can be re-imported
                        # from its new canonical web URL.
                        "redirect": "manual"}))
        status = int(getattr(response, "status", 0) or 0)
        response_headers = {}
        for name in (
                "x-ratelimit-limit", "x-ratelimit-remaining",
                "x-ratelimit-reset", "ratelimit-limit",
                "ratelimit-remaining", "ratelimit-reset", "retry-after",
                "content-length"):
            try:
                value = response.headers.get(name)
            except Exception:
                value = None
            if value is not None:
                response_headers[name] = str(value)
        try:
            announced = int(response_headers.get("content-length") or 0)
        except (TypeError, ValueError):
            announced = 0
        if announced > repository_import.MAX_PROVIDER_BODY:
            return {
                "status": 502, "data": {}, "headers": response_headers,
                "error": "provider_response_too_large",
            }
        text = str(await response.text())
        if len(text.encode("utf-8")) > repository_import.MAX_PROVIDER_BODY:
            return {
                "status": 502, "data": {}, "headers": response_headers,
                "error": "provider_response_too_large",
            }
        try:
            data = json.loads(text) if text else {}
        except Exception:
            data = {}
        return {
            "status": status,
            "data": data,
            "headers": response_headers,
        }
    except Exception:
        # Never include exception text: a provider/runtime failure can echo
        # request headers, including the one-use authorization token.
        return {"status": 502, "data": {}, "headers": {}}


async def _repository_import_operator_eligible(env, actor, node):
    actor = clean_string(actor, MAX_NODE_NAME).strip().lower()
    node = clean_string(node, MAX_NODE_NAME).strip().lower()
    if not actor or not node:
        return False
    try:
        _, account = await _account_row(env, actor)
        return bool(
            account and account.get("status") == "active"
            and await _account_owns_node(env, actor, node))
    except Exception:
        return False


async def _repository_import_moderator(env, actor):
    try:
        return bool(
            await _has_role(env, actor, "platform_administrator")
            or await _has_role(env, actor, "moderator"))
    except Exception:
        return False


async def _repository_import_target_owner(env, actor, target):
    actor = clean_string(actor, MAX_NODE_NAME).strip().lower()
    target = clean_string(target, MAX_NODE_NAME).strip().lower() or actor
    if not actor or not target:
        return None
    if target == actor:
        return {
            "name": actor,
            "kind": "user",
            "ownerBi": await blind_index(env, actor),
        }
    org_bi, row = await _org_row(env, target)
    if not row or await _org_role(env, org_bi, actor) not in (
            "owner", "admin"):
        return None
    return {
        "name": str(row.get("name") or target).lower(),
        "kind": "organization",
        "ownerBi": org_bi,
    }


async def _repository_import_can_manage_owner(env, actor, owner_bi):
    actor = clean_string(actor, MAX_NODE_NAME).strip().lower()
    owner_bi = str(owner_bi or "")
    if not actor or not owner_bi:
        return False
    actor_bi = await blind_index(env, actor)
    if hmac.compare_digest(actor_bi, owner_bi):
        return True
    row = await d1_first(
        env,
        "SELECT role FROM org_members WHERE org_bi=? AND member_bi=?",
        owner_bi, actor_bi,
    )
    return str((row or {}).get("role") or "") in ("owner", "admin")


async def _repository_import_mirror_status(
        env, actor, external_record, target_status, data):
    owner = clean_string(
        data.get("mirrorOwner") or actor, MAX_NODE_NAME).strip().lower()
    name = safe_segment(clean_string(
        data.get("mirrorName") or external_record.get("name"),
        MAX_REPO_SEGMENT))
    if not owner or not name:
        return {"verified": False}
    try:
        if owner != actor and not await _account_owns_node(env, actor, owner):
            return {"verified": False}
        repo_bi = await blind_index(env, owner + "/" + name)
        row = await d1_first(
            env,
            "SELECT is_private, data FROM repositories WHERE key_bi=?",
            repo_bi,
        )
        if not row:
            return {"verified": False}
        # Linking a public external stub to a private catalog entry would make
        # the public status disclose that the private repo exists. Do not trust
        # the historical plaintext flag by itself: migration 0011 defaulted
        # old/ambiguous rows to public.
        catalog_record = await decrypt_row(env, row.get("data"))
        visibility = (catalog_record or {}).get("visibility")
        if visibility not in ("public", "private"):
            return {"verified": False}
        if (visibility == "private") != bool(external_record.get("isPrivate")):
            return {"verified": False}
        cutoff = int(Date.now()) - HOST_PRESENCE_STALE_MS
        live = await d1_first(
            env,
            "SELECT 1 AS one FROM host_presence WHERE repo_bi=? AND ts>=?",
            repo_bi, cutoff,
        )
        return {
            "verified": True,
            "owner": owner,
            "name": name,
            "live": bool(live),
        }
    except Exception:
        return {"verified": False}


async def _repository_invitation_token(
        env, import_id, invitation_id, email):
    canonical = (
        "forkmesh-contributor-invitation-v1\n" + str(import_id) + "\n"
        + str(invitation_id) + "\n" + str(email).strip().lower()
    ).encode()
    return hmac.new(
        _account_session_secret(env), canonical, "sha256").hexdigest()


async def _repository_import_audit(
        env, actor, action, target_type, target, outcome, details):
    await _audit_sensitive_action(
        env, actor, action, target_type, target, outcome, details)


def _repository_import_service():
    return repository_import.RepositoryImportService({
        "json_response": json_response,
        "ensure_schema": ensure_schema,
        "d1_all": d1_all,
        "d1_first": d1_first,
        "d1_run": d1_run,
        "encrypt_row": encrypt_row,
        "decrypt_row": decrypt_row,
        "blind_index": blind_index,
        "session_record": _account_session_record,
        "provider_fetch": _repository_provider_fetch,
        "send_email": _send_email,
        "audit": _repository_import_audit,
        "invitation_token": _repository_invitation_token,
        "operator_eligible": _repository_import_operator_eligible,
        "is_moderator": _repository_import_moderator,
        "target_owner": _repository_import_target_owner,
        "can_manage_owner": _repository_import_can_manage_owner,
        "mirror_status": _repository_import_mirror_status,
        "public_origin": _public_base_url,
        "now_ms": lambda: int(Date.now()),
    })


async def repository_imports_handler(env, request, path):
    service = _repository_import_service()
    return await service.handle(env, request, path)


async def _email_verify_token(env, name, email):
    # Stateless, deterministic confirm token bound to (name, email). Only the
    # server can compute it (keyed by DATA_KEY via the blind-index HMAC key, with
    # its own domain-separation prefix), so a valid token in the link proves the
    # recipient controls the mailbox — no token column or extra storage needed.
    key = await _hmac_key(env)
    msg = ("forkmesh-email-verify-v1\n" + (name or "") + "\n" + (email or "")).encode()
    sig = await js_crypto.subtle.sign("HMAC", key, _to_js(msg))
    return bytes(Uint8Array.new(sig).to_py()).hex()[:32]


def _public_base_url(env, request):
    base = (getattr(env, "PUBLIC_BASE_URL", "") or "").strip().rstrip("/")
    if base:
        return base
    try:
        u = urlparse(request.url)
        if u.scheme and u.netloc:
            return u.scheme + "://" + u.netloc
    except Exception:
        pass
    return ""


