async def _repo_notification_target(env, repo_bi):
    row = await d1_first(env, "SELECT data FROM repositories WHERE key_bi=?", repo_bi)
    if not row:
        return "", ""
    rec = await decrypt_row(env, row.get("data", ""))
    if not rec:
        return "", ""
    return (clean_string(rec.get("owner", ""), MAX_NODE_NAME).lower(),
            clean_string(rec.get("name", ""), MAX_REPO_SEGMENT))


async def notify_host_status(env, repo_bi, kind):
    owner, repo = await _repo_notification_target(env, repo_bi)
    if not owner or not repo:
        return
    title = "Host online" if kind == "host_online" else "Host offline"
    await enqueue_notification(
        env, owner, kind, title + " for " + owner + "/" + repo,
        body=("A desktop host is reachable." if kind == "host_online"
              else "No live host has checked in recently."),
        repo=owner + "/" + repo,
        href=repo_web_href(owner, repo),
        source="host", dedupe=kind + ":" + repo_bi,
    )


async def notify_stale_hosts_offline(env, cutoff):
    rows = await d1_all(env, "SELECT repo_bi FROM host_presence WHERE ts < ?", cutoff)
    for row in rows:
        repo_bi = row.get("repo_bi")
        if repo_bi:
            await notify_host_status(env, repo_bi, "host_offline")


async def notifications_handler(env, request):
    await ensure_schema(env)
    method = method_name(request)
    if method == "GET":
        params = parse_qs(urlparse(request.url).query)
        node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
        if not valid_node_name(node):
            return json_response({"error": "node_required"}, status=400)
        # A notification inbox is private to its owner: only the account itself,
        # proven by its session token (bearer header on this GET), may read it.
        if await _authed_account_name(env, request) != node:
            return json_response({"error": "unauthorized"}, status=401)
        try:
            limit = int(params.get("limit", ["40"])[0])
        except (TypeError, ValueError):
            limit = 40
        limit = max(1, min(limit, MAX_NOTIFICATIONS_FETCH))
        recipient_bi = await blind_index(env, node)
        rows = await d1_all(
            env,
            """SELECT dedupe_bi, ts, read_at, data FROM notifications
               WHERE recipient_bi=? ORDER BY ts DESC LIMIT ?""",
            recipient_bi, limit,
        )
        items = []
        unread = 0
        # Derive the AES key once for the whole page instead of per row: each
        # derivation is its own async WebCrypto round trip, and this endpoint is
        # polled often enough that N sequential round trips (one per notification)
        # measurably drags out the request.
        row_key = await _data_key(env) if rows else None
        for row in rows:
            rec = await decrypt_row(env, row.get("data", ""), key=row_key)
            if not rec:
                continue
            read_at = int(row.get("read_at") or 0)
            rec["id"] = row.get("dedupe_bi", "")
            rec["readAt"] = read_at
            rec["ts"] = int(row.get("ts") or rec.get("ts") or 0)
            if not read_at:
                unread += 1
            items.append(rec)
        return json_response({"ok": True, "notifications": items, "unread": unread})

    if method == "POST":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower()
        if not valid_node_name(node):
            return json_response({"error": "node_required"}, status=400)
        # Marking notifications read mutates the owner's inbox: same session gate
        # as the GET (token from the POST body or an Authorization: Bearer header).
        if await _authed_account_name(env, request, data) != node:
            return json_response({"error": "unauthorized"}, status=401)
        recipient_bi = await blind_index(env, node)
        now = int(Date.now())
        if data.get("all"):
            await d1_run(
                env, "UPDATE notifications SET read_at=? WHERE recipient_bi=?",
                now, recipient_bi)
            return json_response({"ok": True})
        ids = data.get("ids") if isinstance(data.get("ids"), list) else []
        for item_id in ids[:MAX_NOTIFICATIONS_FETCH]:
            item_id = clean_string(item_id, 160)
            if item_id:
                await d1_run(
                    env,
                    "UPDATE notifications SET read_at=? WHERE recipient_bi=? AND dedupe_bi=?",
                    now, recipient_bi, item_id)
        return json_response({"ok": True})

    return json_response({"error": "method_not_allowed"}, status=405)


async def mirror_requests_handler(env, request):
    # Peer mirror requests (issue #385): a repo owner asks another node to
    # mirror their repo, the target's holder accepts or rejects, and on accept
    # that node starts mirroring. The request is parked as a bounded list on the
    # TARGET account record (heartbeat-delivered, like claim/ownership-transfer);
    # accepted entries ride back on the target node's signed heartbeat so its
    # desktop clones the repo. All actions are session-gated (the dashboard
    # login), exactly like the notification inbox this feeds.
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    action = clean_string(data.get("action", "create"), 20) or "create"
    actor = await _authed_account_name(env, request, data)
    if not valid_node_name(actor):
        return json_response({"error": "unauthorized"}, status=401)
    now = int(Date.now())

    if action == "create":
        target = clean_string(data.get("target", ""), MAX_NODE_NAME).lower()
        owner = clean_string(data.get("owner", ""), MAX_NODE_NAME).lower()
        repo = clean_string(data.get("repo", ""), MAX_REPO_SEGMENT).strip()
        if not valid_node_name(target) or not valid_node_name(owner) or not repo:
            return json_response({"error": "bad_request"}, status=400)
        # "Ask a node to mirror YOUR repo": only the repo owner (proven by the
        # session, not a self-asserted body field) may send the request.
        if owner != actor:
            return json_response({"error": "forbidden"}, status=403)
        if target == owner:
            return json_response({"error": "self_target"}, status=400)
        if await _repo_is_private(env, owner, repo):
            # Mirroring is a public-repo affair (the /mirrors payload and clone
            # fallback are public-only); private repos need a share token flow.
            return json_response({"error": "private_repo"}, status=400)
        key_bi = await blind_index(env, owner + "/" + repo)
        repo_row = await d1_first(
            env, "SELECT data FROM repositories WHERE key_bi=?", key_bi)
        if not repo_row:
            return json_response({"error": "repo_not_found"}, status=404)
        target_bi, target_rec = await _account_row(env, target)
        if not target_rec or target_rec.get("status") != "active":
            return json_response({"error": "target_not_found"}, status=404)
        req_id = mirror_request_id(owner, repo, target)
        entry = {"id": req_id, "requester": owner, "owner": owner, "repo": repo,
                 "status": "pending", "ts": now}
        target_rec["mirror_requests"] = add_mirror_request(
            target_rec.get("mirror_requests"), entry)
        await _save_account(env, target_bi, target_rec)
        await enqueue_notification(
            env, target, "mirror_request", "Mirror request from " + owner,
            body=(owner + " asked your node to mirror " + owner + "/" + repo +
                  ". Accept to start mirroring it."),
            repo=owner + "/" + repo, href=repo_web_href(owner, repo),
            actor=owner, source="mirror_request",
            dedupe="mirror_request:" + req_id,
            meta={"requestId": req_id, "owner": owner, "repo": repo,
                  "requester": owner, "state": "pending"})
        return json_response({"ok": True, "requestId": req_id, "status": "pending"})

    if action in ("accept", "reject"):
        req_id = clean_string(data.get("requestId", ""), 200).strip().lower()
        if not req_id:
            return json_response({"error": "bad_request"}, status=400)
        target_bi, target_rec = await _account_row(env, actor)
        if not target_rec:
            return json_response({"error": "unauthorized"}, status=401)
        existing = find_mirror_request(target_rec.get("mirror_requests"), req_id)
        if not existing:
            return json_response({"error": "not_found"}, status=404)
        status = "accepted" if action == "accept" else "rejected"
        updated_list, updated = set_mirror_request_status(
            target_rec.get("mirror_requests"), req_id, status, ts=now)
        target_rec["mirror_requests"] = updated_list
        await _save_account(env, target_bi, target_rec)
        owner = clean_string((updated or {}).get("owner", ""), MAX_NODE_NAME).lower()
        repo = clean_string((updated or {}).get("repo", ""), MAX_REPO_SEGMENT).strip()
        requester = clean_string(
            (updated or {}).get("requester", ""), MAX_NODE_NAME).lower()
        # Let the requester know the outcome (recipient != actor is guaranteed:
        # a request never targets its own owner).
        if requester and owner and repo:
            verb = "accepted" if action == "accept" else "declined"
            tail = (" — their node will start mirroring it shortly."
                    if action == "accept" else ".")
            await enqueue_notification(
                env, requester, "mirror_request",
                actor + " " + verb + " your mirror request",
                body=(actor + " " + verb + " your request to mirror " +
                      owner + "/" + repo + tail),
                repo=owner + "/" + repo, href=repo_web_href(owner, repo),
                actor=actor, source="mirror_request",
                dedupe="mirror_request_reply:" + req_id + ":" + status,
                meta={"requestId": req_id, "owner": owner, "repo": repo,
                      "state": status})
        return json_response({"ok": True, "status": status})

    return json_response({"error": "bad_action"}, status=400)


async def subscribe_handler(env, request, owner, repo):
    # Signed subscribe/unsubscribe for one issue or PR thread (issue #361). The
    # request is signed with the node's own Ed25519 key — the same proof of
    # control as a heartbeat — so only the account holder can watch or mute a
    # thread on their own behalf.
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower()
    source = clean_string(data.get("source", ""), 20)
    if source not in ("issue", "pull"):
        return json_response({"error": "bad_source"}, status=400)
    try:
        number = int(data.get("number", 0))
    except (TypeError, ValueError):
        number = 0
    if number <= 0:
        return json_response({"error": "bad_number"}, status=400)
    subscribed = bool(data.get("subscribed", True))
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    if not valid_node_name(node) or not _ts_ok(ts):
        return json_response({"error": "unauthorized"}, status=401)
    _, rec = await _account_row(env, node)
    pubkey = rec.get("pubkey", "") if rec else ""
    if not pubkey:
        return json_response({"error": "unauthorized"}, status=401)
    canonical = ("forkmesh-subscribe-v1\n" + owner + "/" + repo + "\n" + source +
                 "\n" + str(number) + "\n" + ("1" if subscribed else "0") +
                 "\n" + ts).encode()
    if not await ed25519_verify(pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)
    privacy_reader = globals().get("_repo_is_private")
    if callable(privacy_reader) and await privacy_reader(env, owner, repo):
        viewers = {
            node,
            clean_string((rec or {}).get("owner", ""), MAX_NODE_NAME).lower(),
        }
        viewers.discard("")
        allowed = False
        for viewer in viewers:
            if (viewer == str(owner).lower()
                    or await _account_owns_node(env, viewer, owner)):
                allowed = True
                break
        if not allowed:
            repo_bi = await blind_index(env, owner + "/" + repo)
            for viewer in viewers:
                grantee_bi = await blind_index(env, viewer)
                shared = await d1_first(
                    env,
                    "SELECT 1 AS one FROM repo_shares "
                    "WHERE repo_bi=? AND grantee_bi=?",
                    repo_bi, grantee_bi,
                )
                if shared:
                    allowed = True
                    break
        if not allowed:
            return json_response({"error": "not_found"}, status=404)
    await subscribe_thread(env, owner, repo, source, number, node,
                           muted=not subscribed)
    return json_response({"ok": True, "subscribed": subscribed})


async def send_notification_digests(env):
    # Cron: roll each recipient's unread notifications into a single email so a
    # reply reaches people who don't have the app open (issue #361). Only the main
    # relay sends mail; recipients need a verified email and must not have opted
    # out. Best-effort — never raise from the cron.
    if not _is_main_relay(env):
        return
    await ensure_schema(env)
    now = int(Date.now())
    max_age_cut = now - NOTIFICATION_DIGEST_MIN_AGE_MS
    recips = await d1_all(
        env,
        "SELECT DISTINCT recipient_bi FROM notifications "
        "WHERE read_at=0 AND ts<=? LIMIT ?",
        max_age_cut, NOTIFICATION_DIGEST_MAX_RECIPIENTS)
    for recip in recips or []:
        recipient_bi = recip.get("recipient_bi")
        if not recipient_bi:
            continue
        acct = await d1_first(
            env, "SELECT data FROM users WHERE user_bi=?", recipient_bi)
        if not acct:
            acct = await d1_first(
                env, "SELECT data FROM nodes WHERE node_bi=?", recipient_bi)
        if not acct:
            continue
        rec = await decrypt_row(env, acct.get("data", ""))
        if not rec or rec.get("status") != "active":
            continue
        # Use the node owner's email if the node has an owner; otherwise use the node's email.
        email_rec = rec
        owner = clean_string(rec.get("owner", ""), MAX_NODE_NAME).lower()
        if owner:
            _, owner_rec = await _account_row(env, owner)
            if owner_rec and owner_rec.get("status") == "active":
                email_rec = owner_rec
        email = clean_string(email_rec.get("email", ""), 254).strip()
        if not email or not email_rec.get("email_verified"):
            continue
        if email_rec.get("email_notifications") is False:
            continue  # explicit opt-out
        last = int(rec.get("last_digest_ts", 0) or 0)
        if last and now - last < NOTIFICATION_DIGEST_INTERVAL_MS:
            continue
        rows = await d1_all(
            env,
            "SELECT ts, data FROM notifications "
            "WHERE recipient_bi=? AND read_at=0 AND ts>? AND ts<=? "
            "ORDER BY ts DESC LIMIT ?",
            recipient_bi, last, max_age_cut, NOTIFICATION_DIGEST_MAX_ITEMS)
        items = []
        newest = last
        prefs = notification_email_preferences(email_rec)
        for row in rows or []:
            row_ts = int(row.get("ts") or 0)
            newest = max(newest, row_ts)
            payload = await decrypt_row(env, row.get("data", ""))
            if not payload:
                continue
            kind = clean_string(payload.get("kind", ""), 40)
            if not prefs.get(kind, False):
                continue
            items.append(payload)
        if not items:
            if newest > last:
                rec["last_digest_ts"] = newest
                await _save_account(env, recipient_bi, rec)
            continue
        node = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
        subject, text, html = _notification_digest_email(node, items)
        ok = await _send_email(env, email, subject, text, html)
        if ok:
            rec["last_digest_ts"] = newest
        _stamp_account_email(rec, "notifications", ok, now)
        await _save_account(env, recipient_bi, rec)
    await send_general_chat_digests(env)


async def _general_chat_encrypted_message_count(env, since_ts, until_ts):
    await ensure_schema(env)
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS c FROM chat_history "
        "WHERE room_key=? AND ts>? AND ts<=?",
        FLAGSHIP_ROOM_KEY, int(since_ts or 0), int(until_ts or 0),
    )
    return int((row or {}).get("c") or 0)


async def send_general_chat_digests(env):
    # The #general room history is retained as encrypted frames. The daily email
    # intentionally reports only a count since the recipient's last digest; it
    # never decrypts or embeds message text.
    if not _is_main_relay(env):
        return
    await ensure_schema(env)
    now = int(Date.now())
    # Recipients come from the authoritative users table (accounts is legacy and
    # is drained as records migrate); it only holds user-kind records, exactly
    # the population eligible for this digest.
    rows = await d1_all(
        env,
        "SELECT user_bi AS name_bi, data FROM users ORDER BY username LIMIT ?",
        GENERAL_CHAT_EMAIL_MAX_RECIPIENTS,
    )
    for row in rows or []:
        name_bi = row.get("name_bi")
        if not name_bi:
            continue
        rec = await decrypt_row(env, row.get("data", ""))
        if not rec or rec.get("status") != "active" or _account_kind(rec) != "user":
            continue
        email = clean_string(rec.get("email", ""), 254).strip()
        if not email or not rec.get("email_verified"):
            continue
        if rec.get("email_notifications") is False:
            continue
        if not notification_email_enabled(rec, "general_chat"):
            continue
        last = int(rec.get("last_general_chat_digest_ts", 0) or 0)
        if last and now - last < GENERAL_CHAT_EMAIL_INTERVAL_MS:
            continue
        since = max(last, now - GENERAL_CHAT_EMAIL_LOOKBACK_MS)
        count = await _general_chat_encrypted_message_count(env, since, now)
        if count <= 0:
            rec["last_general_chat_digest_ts"] = now
            await _save_account(env, name_bi, rec)
            continue
        name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
        subject, text, html = _general_chat_digest_email(name, count)
        ok = await _send_email(env, email, subject, text, html)
        if ok:
            rec["last_general_chat_digest_ts"] = now
        _stamp_account_email(rec, "general_chat", ok, now)
        await _save_account(env, name_bi, rec)


def _forkmesh_email_card_html(heading, intro_html, body_html, footer_html=""):
    # Inline light colors are the reliable fallback for older mail clients;
    # clients that honor the native setting apply the dark override below.
    return (
        "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">"
        "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
        "<meta name=\"color-scheme\" content=\"light dark\">"
        "<meta name=\"supported-color-schemes\" content=\"light dark\">"
        "<style>:root{color-scheme:light dark;supported-color-schemes:light dark}"
        "@media (prefers-color-scheme:dark){body,.fm-bg{background:#090909!important;"
        "color:#f5f5f5!important}.fm-card{background:#141416!important;"
        "border-color:#313134!important}.fm-h1,.fm-strong,.fm-item-title{"
        "color:#f5f5f5!important}.fm-text,.fm-item-body{color:#d4d4d8!important}"
        ".fm-brand,.fm-muted{color:#a3a3a3!important}.fm-item{background:#0f0f11"
        "!important;border-color:#313134!important}.fm-link{color:#4ade80!important}}"
        "</style>"
        "</head>"
        "<body style=\"margin:0;padding:0;background:#f4f4f5\">"
        "<div class=\"fm-bg\" style=\"margin:0;padding:28px 16px;background:#f4f4f5;"
        "font-family:'ForkMesh Lato',-apple-system,BlinkMacSystemFont,"
        "Segoe UI,Helvetica,Arial,sans-serif;color:#18181b;line-height:1.55\">"
        "<div class=\"fm-card\" style=\"max-width:560px;margin:0 auto;border:1px solid #d4d4d8;"
        "border-radius:8px;background:#ffffff;padding:24px\">"
        "<p class=\"fm-brand\" style=\"margin:0 0 22px;color:#52525b;font-size:13px;"
        "letter-spacing:0;font-weight:700\">ForkMesh</p>"
        "<h1 class=\"fm-h1\" style=\"margin:0 0 14px;color:#18181b;font-size:24px;"
        "line-height:1.25;font-weight:800\">" + heading + "</h1>"
        "<p class=\"fm-text\" style=\"margin:0 0 18px;color:#3f3f46;font-size:15px\">" +
        intro_html + "</p>" + body_html +
        (footer_html if footer_html else "") +
        "</div></div></body></html>")


def _format_email_ts(ts_ms):
    """Human-readable UTC timestamp for email bodies, e.g. '2026-07-09 14:32
    UTC'. Sortable/unambiguous rather than locale-flavored, and built from
    time.gmtime/strftime with only the portable %Y/%m/%d/%H/%M directives —
    no timezone database, no platform-specific no-leading-zero flags (those
    aren't guaranteed to work under Pyodide's WASM libc)."""
    try:
        ts_ms = int(ts_ms or 0)
        if ts_ms <= 0:
            return ""
        return time.strftime("%Y-%m-%d %H:%M UTC", time.gmtime(ts_ms / 1000))
    except Exception:
        return ""


def _notification_digest_email(node, items):
    n = len(items)
    subject = ("ForkMesh: " + str(n) + " new notification" +
               ("s" if n != 1 else ""))
    lines = ["Hi " + node + ",", "",
             "You have " + str(n) + " unread ForkMesh notification" +
             ("s" if n != 1 else "") + ":", ""]
    html_items = []
    for it in items:
        title = clean_string(it.get("title", ""), 160) or "Notification"
        body = clean_string(it.get("body", ""), 300)
        repo = clean_string(it.get("repo", ""), 180)
        actor = clean_string(it.get("actor", ""), 120)
        meta_in = it.get("meta")
        try:
            number = int((meta_in or {}).get("number", 0) or 0)
        except (TypeError, ValueError):
            number = 0
        when = _format_email_ts(it.get("ts"))
        # "[owner/repo] #42 Title", falling back gracefully as each piece is
        # missing (a brand-new PR/comment has no number yet; an old digest
        # backlog item might predate actor tracking).
        prefix = ("[" + repo + "] ") if repo else ""
        number_prefix = ("#" + str(number) + " ") if number > 0 else ""
        lines.append("- " + prefix + number_prefix + title)
        # A second indented line for who/when, only when there's something to
        # show — matches the existing "    body" indent convention below.
        who_when = " · ".join(filter(None, [
            ("by " + actor) if actor else "", when]))
        if who_when:
            lines.append("    " + who_when)
        if body:
            lines.append("    " + body)
        meta_html = " &middot; ".join(filter(None, [
            _html_escape("#" + str(number)) if number > 0 else "",
            ("by <strong>" + _html_escape(actor) + "</strong>") if actor else "",
            _html_escape(when) if when else "",
        ]))
        html_items.append(
            "<div class=\"fm-item\" style=\"border:1px solid #313134;border-radius:8px;"
            "background:#0f0f11;padding:12px 14px;margin:0 0 10px\">"
            "<p class=\"fm-item-title\" style=\"margin:0;color:#f5f5f5;font-size:14px;"
            "font-weight:800\">" + _html_escape(prefix + title) + "</p>" +
            ("<p class=\"fm-muted\" style=\"margin:4px 0 0;color:#8a8a93;font-size:12px\">" +
             meta_html + "</p>" if meta_html else "") +
            ("<p class=\"fm-item-body\" style=\"margin:6px 0 0;color:#a3a3a3;font-size:13px;"
             "line-height:1.45\">" + _html_escape(body) + "</p>"
             if body else "") + "</div>")
    lines += ["", "Open ForkMesh to read and reply.",
              "To stop these emails, turn off email notifications in your "
              "profile settings."]
    text = "\n".join(lines)
    html = _forkmesh_email_card_html(
        _html_escape(str(n) + " new notification" + ("s" if n != 1 else "")),
        "Hi <strong class=\"fm-strong\" style=\"color:#f5f5f5\">" +
        _html_escape(node or "there") +
        "</strong>, you have " + str(n) + " unread ForkMesh notification" +
        ("s" if n != 1 else "") + ".",
        "<div style=\"margin:0 0 18px\">" + "".join(html_items) + "</div>"
        "<p class=\"fm-text\" style=\"margin:0 0 16px;color:#d4d4d8;font-size:14px\">Open "
        "ForkMesh to read and reply.</p>",
        "<p class=\"fm-muted\" style=\"margin:22px 0 0;color:#8a8a93;font-size:12px\">To stop "
        "these emails, update email notifications in your profile settings."
        "</p>",
    )
    return subject, text, html


def _general_chat_digest_email(node, count):
    n = int(count or 0)
    subject = ("ForkMesh: " + str(n) + " encrypted #general message" +
               ("s" if n != 1 else ""))
    text = (
        "Hi " + (node or "there") + ",\n\n"
        "You have " + str(n) + " encrypted #general message" +
        ("s" if n != 1 else "") + " since your last digest.\n\n"
        "Message contents are not sent over email. Log in on the web or open "
        "the ForkMesh app to read and reply.\n\n"
        "To stop these emails, update email notifications in your profile settings.")
    html = _forkmesh_email_card_html(
        _html_escape(str(n) + " encrypted #general message" +
                     ("s" if n != 1 else "")),
        "Hi <strong class=\"fm-strong\" style=\"color:#f5f5f5\">" +
        _html_escape(node or "there") +
        "</strong>, #general has encrypted activity since your last digest.",
        "<div class=\"fm-item\" style=\"border:1px solid #313134;border-radius:8px;"
        "background:#0f0f11;padding:14px;margin:0 0 18px\">"
        "<p class=\"fm-item-title\" style=\"margin:0;color:#f5f5f5;font-size:28px;"
        "font-weight:800;line-height:1\">"
        + str(n) + "</p>"
        "<p class=\"fm-item-body\" style=\"margin:8px 0 0;color:#d4d4d8;font-size:14px\">encrypted "
        "#general message" + ("s" if n != 1 else "") + " waiting</p>"
        "</div>"
        "<p class=\"fm-text\" style=\"margin:0;color:#d4d4d8;font-size:14px\">Message contents "
        "are not sent over email. Log in on the web or open the ForkMesh app "
        "to read and reply.</p>",
        "<p class=\"fm-muted\" style=\"margin:22px 0 0;color:#8a8a93;font-size:12px\">To stop "
        "these emails, update email notifications in your profile settings."
        "</p>",
    )
    return subject, text, html


def _html_escape(text):
    return (str(text or "").replace("&", "&amp;").replace("<", "&lt;")
            .replace(">", "&gt;").replace('"', "&quot;"))


def _build_rev(env):
    # The git rev deploy.sh stamps as a Worker var on every production deploy.
    try:
        val = env.BUILD_REV
        if val:
            return str(val)
    except (AttributeError, TypeError):
        pass
    return "dev"


async def poll_handler(env, request):
    # One lightweight digest the client polls on its regular tick INSTEAD of
    # separately re-fetching the full profile (/api/accounts/<name> — avatar and
    # all) and the full notification list every time. It returns only cheap
    # change tokens (a couple of indexed reads, no avatar blob, no per-row
    # notification decrypt); the client fires those heavier fetches only when a
    # token here actually moves. Rolling three per-minute polls into one keeps
    # the hot dashboard path off the Worker CPU limit.
    await ensure_schema(env)
    params = parse_qs(urlparse(request.url).query)
    node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    out = {"ok": True, "rev": _build_rev(env)}
    if not valid_node_name(node):
        return json_response(out)
    # The digest exposes the account's own profile-change token and unread count,
    # so it is returned only to the account itself (session bearer token). Anyone
    # else — or an anonymous poll — gets just the build rev, no per-account data.
    if await _authed_account_name(env, request) != node:
        return json_response(out)
    name_bi, rec = await _account_row(env, node)
    if rec:
        # Token folds the profile fields the dashboard actually re-renders, so a
        # change to any of them (verification, avatar, admin grant, ownership)
        # invalidates it and triggers the full /api/accounts/<name> fetch.
        out["profile"] = {"token": ":".join(str(x) for x in (
            rec.get("status", ""),
            1 if rec.get("email_verified") else 0,
            rec.get("avatar_updated_at", 0) or 0,
            1 if await _is_admin(env, node) else 0,
            rec.get("owner", "") or "",
        ))}
        # Unread count is returned outright so the bell badge updates from the
        # poll alone; token (latest ts + row total) moves on any add/remove so
        # the full list is re-pulled only when it changed.
        notif = await d1_first(
            env,
            "SELECT COUNT(*) AS total, "
            "SUM(CASE WHEN read_at=0 THEN 1 ELSE 0 END) AS unread, "
            "MAX(ts) AS latest FROM notifications WHERE recipient_bi=?",
            name_bi)
        total = int((notif or {}).get("total") or 0)
        unread = int((notif or {}).get("unread") or 0)
        latest = int((notif or {}).get("latest") or 0)
        out["notif"] = {"unread": unread, "token": str(latest) + ":" + str(total)}
    return json_response(out)


def _forkbot_extract_mention_command(message):
    text = clean_string(message, FORKBOT_MAX_COMMAND).strip()
    if not text:
        return ""
    match = re.search(
        r"(?is)(?:^|[^A-Za-z0-9_-])@?forkbot\b[:,]?\s*(.*)$", text)
    return match.group(1).strip() if match else ""


def _forkbot_parse_issue_command(command):
    # Fast, offline path for an explicitly phrased request ("create an issue
    # to ..."). A miss here is NOT a rejection: the handler falls back to the
    # AI intent classifier (_forkbot_ai_interpret), which recognises the same
    # intent from natural phrasing ("forkbot can you track the flaky login
    # test?") and from the surrounding conversation. This regex just spares an
    # AI round trip for the obvious wording and still works when AI is off.
    text = clean_string(command, FORKBOT_MAX_COMMAND).strip()
    if not text:
        return None
    # Verb-first ("create an issue to ...") or noun-first ("issue to ...",
    # "bug: ...") — both common phrasings, both answerable offline.
    match = re.match(
        r"(?is)^(?:please\s+|can\s+you\s+|could\s+you\s+|would\s+you\s+|"
        r"pls\s+|plz\s+)*"
        r"(?:(?:create|open|file|make|report|log|raise|add|track|submit)\s+)?"
        r"(?:an?\s+|a\s+new\s+)?"
        r"(?:issue|bug|ticket|task|feature\s+request)\b"
        r"\s*(?:(?:to|for|about|that|saying|called|titled|re|regarding)\s+|"
        r"[:\-]\s*)?"
        r"(.+)$",
        text,
    )
    if not match:
        return None
    description = re.sub(r"\s+", " ", match.group(1)).strip(" .:-")
    if len(description) < 3:
        return None
    return {"description": description}


def _forkbot_command_hints_issue(command):
    """Cheap offline signal that a ForkBot mention is about recording work —
    used ONLY when the AI classifier is unreachable, so an unreachable model
    degrades to filing the raw request instead of refusing with the help hint
    (that refusal is exactly what users saw while the AI binding was silently
    failing)."""
    return bool(re.search(
        r"(?i)\b(issues?|bugs?|tickets?|tasks?|todo|feature\s+request|"
        r"create|open|file|track|log|report)\b",
        clean_string(command, FORKBOT_MAX_COMMAND)))


def _forkbot_polite_prefix():
    # Shared lead-in the offline parsers strip: "please can you ..." etc.
    return (r"(?:please\s+|can\s+you\s+|could\s+you\s+|would\s+you\s+|"
            r"pls\s+|plz\s+)*")


def _forkbot_parse_list_command(command):
    """Offline fast path for "list the last N issues" phrasings. Mirrors the
    create-issue fast path: a miss is NOT a rejection (the AI classifier still
    gets a shot at natural wording), a hit spares the AI round trip and keeps
    the feature working when AI is off. Returns {"count": n} or None."""
    text = clean_string(command, FORKBOT_MAX_COMMAND).strip()
    if not text:
        return None
    match = re.match(
        r"(?is)^" + _forkbot_polite_prefix() +
        r"(?:list|show(?:\s+me)?|display|give\s+me|what\s+are)\s+"
        r"(?:the\s+)?(?:last|latest|most\s+recent|recent|newest)?\s*"
        r"(\d{1,3})?\s*(?:few\s+)?issues\b",
        text,
    )
    if not match:
        return None
    try:
        count = int(match.group(1) or FORKBOT_LIST_DEFAULT)
    except (TypeError, ValueError):
        count = FORKBOT_LIST_DEFAULT
    return {"count": max(1, min(count, FORKBOT_LIST_MAX))}


def _forkbot_parse_count_command(command):
    """Offline fast path for "how many issues are there" phrasings. These ask
    for a total, not a listing, so they must not fall through to the list
    parser above (which would hand back a few issues and never say how many
    exist in total). Returns True or None."""
    text = clean_string(command, FORKBOT_MAX_COMMAND).strip()
    if not text:
        return None
    match = re.match(
        r"(?is)^" + _forkbot_polite_prefix() +
        r"(?:how\s+many\s+issues\b(?:\s+are\s+there|\s+exist|"
        r"\s+do\s+we\s+have)?|"
        r"(?:what(?:'s|\s+is)\s+the\s+)?(?:number|count)\s+of\s+issues|"
        r"issue\s+count)\s*[?.!]*$",
        text,
    )
    return {} if match else None


def _forkbot_parse_search_command(command):
    """Offline fast path for "search issues for X" phrasings. Requires the
    word issue(s) so a bare "find the bug" still flows to the create/AI paths.
    Returns {"query": text} or None."""
    text = clean_string(command, FORKBOT_MAX_COMMAND).strip()
    if not text:
        return None
    match = re.match(
        r"(?is)^" + _forkbot_polite_prefix() +
        r"(?:search|find|look\s+(?:for|up)|grep)\s+"
        r"(?:the\s+|any\s+|all\s+)?(?:open\s+|closed\s+)?issues?\b\s*"
        r"(?:(?:for|about|regarding|matching|mentioning|containing|on|with)"
        r"\s+)?[:\-]?\s*(.+)$",
        text,
    )
    if not match:
        return None
    query = re.sub(r"\s+", " ", match.group(1)).strip(" .:-\"'")
    if len(query) < 2:
        return None
    return {"query": query[:100]}


def _forkbot_parse_agent_command(command):
    """Offline fast path for "start an agent on the latest issue / issue #N".
    Returns {"issueNumber": n} (0 = the most recent issue) or None."""
    text = clean_string(command, FORKBOT_MAX_COMMAND).strip()
    if not text:
        return None
    match = re.match(
        r"(?is)^" + _forkbot_polite_prefix() +
        r"(?:start|run|launch|kick\s+off|spin\s+up|put|assign|set|sic)\s+"
        r"(?:an?\s+)?(?:coding\s+|code\s+)?agent\s+"
        r"(?:on|to|at|for|onto|against)?\s*(?:the\s+)?"
        r"(?:most\s+recent|latest|newest|last|recent)?\s*"
        r"issue\s*(?:#\s*)?(\d+)?",
        text,
    )
    if not match:
        return None
    try:
        number = int(match.group(1) or 0)
    except (TypeError, ValueError):
        number = 0
    return {"issueNumber": number}


def _forkbot_parse_show_command(command):
    """Offline fast path for "show issue #N" / "show the latest issue".
    "open issue ..." intentionally stays with the create-issue parser (there
    "open" is the filing verb). Returns {"issueNumber": n} (0 = latest) or
    None."""
    text = clean_string(command, FORKBOT_MAX_COMMAND).strip()
    if not text:
        return None
    match = re.match(
        r"(?is)^" + _forkbot_polite_prefix() +
        r"(?:show(?:\s+me)?|view|describe|summarize|"
        r"what(?:'s|\s+is)\s+(?:in|the\s+status\s+of))\s+"
        r"(?:the\s+)?(?:most\s+recent\s+|latest\s+|newest\s+|last\s+)?"
        r"issue\s*(?:#\s*)?(\d+)?\s*$",
        text,
    )
    if not match:
        return None
    try:
        number = int(match.group(1) or 0)
    except (TypeError, ValueError):
        number = 0
    return {"issueNumber": number}


def _forkbot_parse_help_command(command):
    text = clean_string(command, FORKBOT_MAX_COMMAND).strip().lower()
    if not text:
        return False
    return bool(re.match(
        r"^(?:help|\?+|what\s+can\s+you\s+do|what\s+do\s+you\s+do|"
        r"commands|usage)\s*[!.?]*$", text))


def _forkbot_help_message():
    # Also the fallback reply for anything ForkBot could not map to an action,
    # so it doubles as discoverable usage text.
    return (
        "I can open an issue from the conversation (\"forkbot open an issue "
        "for the flaky login test\"), list recent issues (\"forkbot list the "
        "last 5 issues\" - up to %d), say how many issues there are "
        "(\"forkbot how many issues are there?\"), search issues (\"forkbot "
        "search issues for relay retries\"), show one issue (\"forkbot show "
        "issue #12\"), and - for the repo owner - start a coding agent "
        "(\"forkbot start an agent on the latest issue\")." % FORKBOT_LIST_MAX
    )


def _forkbot_context_text(context):
    """Flatten the recent conversation the client forwarded into a short,
    plain-text transcript for the AI. Each entry is {sender, text}; the client
    already excludes ForkBot's own lines and caps the count, but we bound it
    again here so a hostile client can't blow the prompt budget."""
    if not isinstance(context, list):
        return ""
    lines = []
    for entry in context[-FORKBOT_CONTEXT_MAX_MESSAGES:]:
        if not isinstance(entry, dict):
            continue
        sender = clean_string(entry.get("sender", ""), MAX_NODE_NAME).strip() or "user"
        text = clean_string(entry.get("text", ""), FORKBOT_CONTEXT_MAX_CHARS).strip()
        if not text:
            continue
        lines.append("%s: %s" % (sender, text))
    return "\n".join(lines)


def _forkbot_issue_title(description):
    text = re.sub(r"\s+", " ", clean_string(description, 240)).strip(" .:-")
    if not text:
        return "Issue from #general"
    for sep in (". ", "! ", "? "):
        idx = text.find(sep)
        if 12 <= idx <= 120:
            text = text[:idx]
            break
    if len(text) > 120:
        text = text[:117].rstrip() + "..."
    return text or "Issue from #general"


def _forkbot_fallback_issue_fields(description):
    body = clean_string(description, MAX_ISSUE_BYTES).strip()
    title = _forkbot_issue_title(body)
    return {"title": title, "body": body}


def _forkbot_json_object_from_text(text):
    if not isinstance(text, str):
        return None
    raw = text.strip()
    if not raw:
        return None
    try:
        parsed = json.loads(raw)
        return parsed if isinstance(parsed, dict) else None
    except Exception:
        pass
    start = raw.find("{")
    end = raw.rfind("}")
    if start >= 0 and end > start:
        try:
            parsed = json.loads(raw[start:end + 1])
            return parsed if isinstance(parsed, dict) else None
        except Exception:
            return None
    return None


def _forkbot_clean_ai_issue_fields(parsed):
    if not isinstance(parsed, dict):
        return None
    title = clean_string(parsed.get("title", ""), 240).strip()
    body = clean_string(parsed.get("body", ""), MAX_ISSUE_BYTES).strip()
    if not title or not body:
        return None
    return {"title": _forkbot_issue_title(title), "body": body}


async def _forkbot_run_ai(env, system_prompt, user_prompt, schema=None):
    """Run the Workers AI chat model and return the raw response text/object
    (or None). Shared by the issue-drafting and intent-classification helpers.

    When `schema` is given, the first attempt requests Workers AI JSON mode
    (response_format json_schema) so a supporting model MUST return valid
    JSON; models/plans without JSON mode fall back to a plain prompt-only
    attempt. Every failure path logs the reason — the original implementation
    swallowed all exceptions, which left ForkBot silently degraded (raw-echo
    issue titles, natural requests answered with the help hint) with nothing
    in the logs to say why."""
    ai = getattr(env, "AI", None)
    if ai is None or js_nullish(ai) or not hasattr(ai, "run"):
        await log_error(
            env, 500, "AI", "forkbot/ai",
            "ForkBot AI unavailable: env.AI binding is missing")
        return None
    model = clean_string(getattr(env, "FORKBOT_AI_MODEL", ""), 120) or \
        FORKBOT_AI_DEFAULT_MODEL
    base_payload = {
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_prompt},
        ],
        "max_tokens": 512,
    }
    attempts = []
    if schema:
        with_format = dict(base_payload)
        with_format["response_format"] = {
            "type": "json_schema", "json_schema": schema,
        }
        attempts.append(with_format)
    attempts.append(base_payload)
    result = None
    ran = False
    last_error = None
    for payload in attempts:
        try:
            result = await ai.run(model, to_js(payload))
            ran = True
            break
        except Exception as error:
            last_error = error
            continue
    if not ran:
        await log_error(
            env, 500, "AI", "forkbot/ai",
            "ForkBot AI call failed (%s): %s"
            % (model, _safe_error_text(last_error)[:300]))
        return None
    try:
        if hasattr(result, "to_py"):
            result = result.to_py()
    except Exception:
        pass
    if isinstance(result, dict):
        for key in ("response", "text", "output"):
            value = result.get(key)
            if isinstance(value, str):
                return value
            # JSON mode returns the parsed object under "response".
            if isinstance(value, dict):
                return value
        # Some bindings return the parsed object directly rather than a text
        # field; hand the dict back so the caller can read fields off it.
        return result
    if isinstance(result, str):
        return result
    await log_error(
        env, 500, "AI", "forkbot/ai",
        "ForkBot AI returned an unusable %s response (%s)"
        % (type(result).__name__, model))
    return None


# JSON schemas for Workers AI JSON mode: a supporting model is FORCED to emit
# exactly these shapes, eliminating the markdown-fence / chatty-preamble
# failure modes small instruct models are prone to.
FORKBOT_ISSUE_FIELDS_SCHEMA = {
    "type": "object",
    "properties": {
        "title": {"type": "string"},
        "body": {"type": "string"},
    },
    "required": ["title", "body"],
}
FORKBOT_INTENT_SCHEMA = {
    "type": "object",
    "properties": {
        "intent": {"type": "string", "enum": [
            "create_issue", "list_issues", "count_issues", "search_issues",
            "show_issue", "start_agent", "help", "none"]},
        "title": {"type": "string"},
        "body": {"type": "string"},
        "count": {"type": "integer"},
        "query": {"type": "string"},
        "issueNumber": {"type": "integer"},
    },
    "required": ["intent"],
}


async def _forkbot_ai_issue_fields(env, description, context_text=""):
    system_prompt = (
        "You turn a chat request into a ForkMesh issue. Use the conversation "
        "context to resolve what the user is referring to. Respond with ONLY "
        'one JSON object, no other text: {"title":"short summary",'
        '"body":"what is wrong or what needs doing, with detail from the '
        'conversation"}.'
    )
    user_prompt = clean_string(description, FORKBOT_MAX_COMMAND)
    if context_text:
        user_prompt = (
            "Recent conversation:\n" + context_text +
            "\n\nRequest: " + user_prompt)
    result = await _forkbot_run_ai(
        env, system_prompt, user_prompt, schema=FORKBOT_ISSUE_FIELDS_SCHEMA)
    if result is None:
        return None
    if isinstance(result, dict):
        return _forkbot_clean_ai_issue_fields(result)
    return _forkbot_clean_ai_issue_fields(_forkbot_json_object_from_text(result))


async def _forkbot_ai_interpret(env, command, context_text=""):
    """Decide from meaning (not fixed phrasing) which ForkBot action the user
    wants — pulling the subject from the recent conversation when the mention
    itself is only a pointer ("forkbot log that").

    Returns one of:
      {"intent": "create_issue", "title", "body"}
      {"intent": "list_issues", "count"}
      {"intent": "count_issues"}
      {"intent": "search_issues", "query"}
      {"intent": "show_issue", "issueNumber"}   (0 = the most recent issue)
      {"intent": "start_agent", "issueNumber"}  (0 = the most recent issue)
      {"intent": "help"} / {"intent": "none"}
    or None when the model is unavailable/unparseable — callers treat None as
    "AI could not decide" and fall back to a heuristic, NOT as a refusal."""
    system_prompt = (
        "You are ForkBot, an assistant in a ForkMesh chat room. Classify what "
        "the user wants and respond with ONLY one JSON object, no other text. "
        "Actions: record a bug/task/feature as an issue -> "
        '{"intent":"create_issue","title":"short summary","body":"the problem '
        'or task, with detail from the conversation"}; list recent issues -> '
        '{"intent":"list_issues","count":N} (how many they asked for, 5 if '
        "unspecified); asking for a TOTAL count of issues rather than a list "
        '-> {"intent":"count_issues"}; search existing issues for a topic -> '
        '{"intent":"search_issues","query":"the search words"}; show one '
        'existing issue -> {"intent":"show_issue","issueNumber":N} (0 for the '
        "most recent); start a coding agent working on an issue -> "
        '{"intent":"start_agent","issueNumber":N} (0 for the most recent); '
        'asking what ForkBot can do -> {"intent":"help"}. When in doubt and '
        "the message describes a problem, task, or request, treat it as "
        "create_issue; a greeting or small talk is "
        '{"intent":"none"}. Examples: "issue to add dark mode" -> '
        '{"intent":"create_issue","title":"Add dark mode","body":"Add dark '
        'mode."}; "what came in this week?" -> '
        '{"intent":"list_issues","count":5}; "how many issues are there?" -> '
        '{"intent":"count_issues"}; "anything about relay retries?" '
        '-> {"intent":"search_issues","query":"relay retries"}; "get an '
        'agent going on that new issue" -> '
        '{"intent":"start_agent","issueNumber":0}; "hello!" -> '
        '{"intent":"none"}.'
    )
    user_prompt = command
    if context_text:
        user_prompt = (
            "Recent conversation:\n" + context_text +
            "\n\nMessage to ForkBot: " + command)
    result = await _forkbot_run_ai(
        env, system_prompt, user_prompt, schema=FORKBOT_INTENT_SCHEMA)
    if result is None:
        return None
    parsed = result if isinstance(result, dict) else \
        _forkbot_json_object_from_text(result)
    if not isinstance(parsed, dict):
        return None
    intent = clean_string(parsed.get("intent", ""), 40).strip().lower()
    if intent == "list_issues":
        try:
            count = int(parsed.get("count", FORKBOT_LIST_DEFAULT)
                        or FORKBOT_LIST_DEFAULT)
        except (TypeError, ValueError):
            count = FORKBOT_LIST_DEFAULT
        return {"intent": "list_issues",
                "count": max(1, min(count, FORKBOT_LIST_MAX))}
    if intent == "count_issues":
        return {"intent": "count_issues"}
    if intent == "search_issues":
        query = clean_string(parsed.get("query", ""), 100).strip()
        if not query:
            return None
        return {"intent": "search_issues", "query": query}
    if intent in ("show_issue", "start_agent"):
        try:
            number = int(parsed.get("issueNumber", 0) or 0)
        except (TypeError, ValueError):
            number = 0
        return {"intent": intent, "issueNumber": max(0, number)}
    if intent == "help":
        return {"intent": "help"}
    if intent not in ("create_issue", "none"):
        # Some models omit the field but still return title/body when they
        # decided to draft an issue; treat a usable draft as create_issue.
        intent = "create_issue" if (parsed.get("title") or parsed.get("body")) \
            else "none"
    if intent != "create_issue":
        return {"intent": "none"}
    fields = _forkbot_clean_ai_issue_fields(parsed)
    if not fields:
        # The model wanted an issue but produced no usable draft — let the
        # caller's heuristic take over instead of refusing.
        return None
    return {"intent": "create_issue", "title": fields["title"],
            "body": fields["body"]}


async def _forkbot_repo_gateway_json(env, owner, repo, action_query):
    """Read public repository data through the normal HTTPS mirror gateway."""
    owner = safe_segment(owner)
    repo = safe_segment(repo)
    action = clean_string(action_query, 400).lstrip("/")
    if (
        not owner or not repo
        or not re.match(
            r"^(tree|blobs|blob|raw|history|commit|branches|search|stats|sizes)"
            r"(?:\?|$)",
            action,
        )
    ):
        return None
    try:
        origin = _public_base_url(env).rstrip("/")
        response = await asyncio.wait_for(
            js_fetch(
                "%s/api/repo/%s/%s/%s"
                % (origin, quote(owner), quote(repo), action)
            ),
            timeout=FORKBOT_GATEWAY_TIMEOUT_MS / 1000,
        )
        if int(getattr(response, "status", 0) or 0) != 200:
            return None
        data = await response.json()
        if hasattr(data, "to_py"):
            data = data.to_py()
        return data if isinstance(data, dict) else None
    except Exception:
        return None


def _forkbot_missing_tree(data):
    # The host answers "that folder isn't in git yet" in a few git-flavored
    # ways (same set the dashboard's isMissingMirrorFolder knows); all of them
    # mean "no issues filed", not "host unreachable".
    error = str((data or {}).get("error", "")).lower()
    return any(marker in error for marker in (
        "not_found", "not a valid object name", "pathspec",
        "does not exist", "unknown revision"))


def _forkbot_issue_json_path(number, subdir=""):
    # Issues are split by status into .forkmesh/issues/open/<N>/ and
    # .forkmesh/issues/closed/<N>/ (adhoc #14); pre-split mirrors keep the
    # numbered folder directly under the root (subdir "").
    base = ".forkmesh/issues"
    if subdir:
        base += "/" + subdir
    return "%s/%d/issue-%d.json" % (base, int(number), int(number))


def _forkbot_issue_json_candidates(number):
    """Every path issue <number>'s record may live at, most likely first."""
    return [_forkbot_issue_json_path(number, subdir)
            for subdir in ("open", "closed", "")]


def _forkbot_blob_text(blob):
    if not isinstance(blob, dict) or not blob.get("ok"):
        return ""
    content = blob.get("content", "")
    if not isinstance(content, str):
        return ""
    if blob.get("encoding") == "base64":
        try:
            return base64.b64decode(content).decode("utf-8", "replace")
        except Exception:
            return ""
    return content


def _forkbot_parse_issue_record(text, number):
    """Reduce one .forkmesh/issues/<N>/issue-<N>.json blob to the fields a chat
    line needs. Tolerant of junk: a malformed record still yields a usable
    "#N" stub rather than dropping the issue from the list."""
    try:
        parsed = json.loads(text or "{}")
    except Exception:
        parsed = None
    if not isinstance(parsed, dict):
        parsed = {}
    events = parsed.get("events")
    open_event = {}
    if isinstance(events, list):
        for event in events:
            if isinstance(event, dict) and event.get("type") == "open":
                open_event = event
                break
    title = clean_string(
        parsed.get("title") or open_event.get("title") or "", 240).strip()
    return {
        "number": int(parsed.get("number") or number or 0),
        "title": title or ("issue #%d" % int(number or 0)),
        "status": clean_string(
            parsed.get("status") or parsed.get("state") or "open", 40),
        "author": clean_string(
            parsed.get("authorName") or open_event.get("authorName") or
            parsed.get("author") or open_event.get("author") or "unknown",
            MAX_NODE_NAME),
        "body": clean_string(
            open_event.get("body") or parsed.get("body") or "", 600).strip(),
    }


async def _forkbot_recent_issue_numbers(env, owner, repo):
    """Issue numbers committed to the live mirror, newest first. Returns None
    when no host could serve the tree (offline), [] when the repo simply has
    no issues folder yet. Issues are split into open/ and closed/ status
    folders (adhoc #14); numbered folders directly under the root are the
    pre-split legacy layout."""
    root = await _forkbot_repo_gateway_json(
        env, owner, repo, "tree?path=" + quote(".forkmesh/issues", safe=""))
    if root is None:
        return None
    entries = root.get("entries")
    if not isinstance(entries, list):
        return [] if _forkbot_missing_tree(root) else None
    numbers = set()
    subdirs = []
    for entry in entries:
        if not isinstance(entry, dict) or entry.get("type") != "tree":
            continue
        name = str(entry.get("name", ""))
        if name.isdigit():
            numbers.add(int(name))
        elif name in ("open", "closed"):
            subdirs.append(name)
    for subdir in subdirs:
        tree = await _forkbot_repo_gateway_json(
            env, owner, repo,
            "tree?path=" + quote(".forkmesh/issues/" + subdir, safe=""))
        sub_entries = tree.get("entries") if isinstance(tree, dict) else None
        if not isinstance(sub_entries, list):
            continue
        for entry in sub_entries:
            if not isinstance(entry, dict) or entry.get("type") != "tree":
                continue
            name = str(entry.get("name", ""))
            if name.isdigit():
                numbers.add(int(name))
    return sorted(numbers, reverse=True)


async def _forkbot_load_issue_records(env, owner, repo, numbers):
    """Batched read of the given issues' JSON records over the live tunnel
    (one /blobs round trip, like the website's issue list). Unreadable issues
    are skipped; returns records in the order requested."""
    numbers = [int(n) for n in numbers][:FORKBOT_LIST_MAX]
    if not numbers:
        return []
    # A record lives at open/<N>/, closed/<N>/, or the pre-split legacy <N>/
    # depending on its status; ask for every candidate in the one batch (3 ×
    # FORKBOT_LIST_MAX stays within MAX_BLOB_BATCH) and keep whichever answered.
    query = "&".join(
        "path=" + quote(path, safe="")
        for n in numbers for path in _forkbot_issue_json_candidates(n))
    data = await _forkbot_repo_gateway_json(env, owner, repo, "blobs?" + query)
    blobs = data.get("blobs") if isinstance(data, dict) else None
    if not isinstance(blobs, dict):
        return []
    records = []
    for number in numbers:
        text = ""
        for path in _forkbot_issue_json_candidates(number):
            text = _forkbot_blob_text(blobs.get(path))
            if text:
                break
        if not text:
            continue
        records.append(_forkbot_parse_issue_record(text, number))
    return records


async def _forkbot_search_issues(env, owner, repo, query):
    """One host-side git grep over the mirror (the /search tunnel op, issue
    #360); ForkBot only reads the issues bucket. Returns the matches, or None
    when no host answered."""
    data = await _forkbot_repo_gateway_json(
        env, owner, repo, "search?q=" + quote(query, safe=""))
    if not isinstance(data, dict) or not data.get("ok"):
        return None
    issues = data.get("issues")
    if not isinstance(issues, list):
        return []
    matches = []
    for hit in issues:
        if not isinstance(hit, dict):
            continue
        try:
            number = int(hit.get("number", 0) or 0)
        except (TypeError, ValueError):
            continue
        if number <= 0:
            continue
        matches.append({
            "number": number,
            "title": clean_string(hit.get("title", ""), 240).strip()
            or ("issue #%d" % number),
            "snippet": clean_string(hit.get("snippet", ""), 200).strip(),
        })
    return matches


def _forkbot_issue_lines(records):
    lines = []
    for record in records:
        line = "#%d %s (%s" % (
            record["number"], record["title"], record["status"])
        if record.get("author") and record["author"] != "unknown":
            line += ", by " + record["author"]
        lines.append(line + ")")
    return "\n".join(lines)


async def _forkbot_next_issue_number(env, repo_bi, owner, repo):
    """Allocate a proposed issue number for a ForkBot-created issue.

    Desktop nodes assign the authoritative number when they merge the inbox
    (nextNumber() = highest issue dir + 1) and keep a proposed number when its
    slot is free, so the goal here is to propose the same number the desktop
    would — and never propose one twice. We seed/re-anchor a persisted per-repo
    counter from the catalog's published issueMaxNumber (the desktop's real max
    at its last publish), then hand out the next value and advance. Best-effort:
    on any storage hiccup we fall back to 0 (the desktop assigns and the reply
    just omits a number) rather than failing the issue creation."""
    seed_next = 1
    try:
        row = await d1_first(
            env, "SELECT data FROM repositories WHERE key_bi=?", repo_bi)
        rec = await decrypt_row(env, row.get("data")) if row else None
        if rec:
            for key in ("issueMaxNumber", "issueCount"):
                value = rec.get(key)
                if value in (None, ""):
                    continue
                try:
                    seed_next = max(seed_next, int(value) + 1)
                    break
                except (TypeError, ValueError):
                    continue
    except Exception:
        pass
    try:
        # Seed on first use / re-anchor upward to the catalog max, never
        # backward (MAX keeps already-handed-out numbers monotonic).
        await d1_run(
            env,
            "INSERT INTO issue_seq (repo_bi, next_number) VALUES (?, ?) "
            "ON CONFLICT(repo_bi) DO UPDATE SET "
            "next_number = MAX(issue_seq.next_number, ?)",
            repo_bi, seed_next, seed_next,
        )
        seq_row = await d1_first(
            env, "SELECT next_number FROM issue_seq WHERE repo_bi=?", repo_bi)
        number = int((seq_row or {}).get("next_number", seed_next) or seed_next)
        await d1_run(
            env, "UPDATE issue_seq SET next_number=? WHERE repo_bi=?",
            number + 1, repo_bi)
        return number
    except Exception:
        return 0


def _forkbot_attributed_body(body, source, actor):
    """Append a footer crediting ForkBot and the human who asked for the issue,
    so a reader of the merged issue can see it came from a chat request rather
    than assuming a person typed it up. The fediverse path builds its own
    "Filed from a fediverse mention by ..." attribution before calling in, so
    only the default chat source gets the footer here (avoids double-crediting).
    """
    if source != "forkbot":
        return body
    if actor and actor != FORKBOT_AUTHOR:
        footer = "Filed by ForkBot at @%s's request via chat." % actor
    else:
        footer = "Filed by ForkBot via chat."
    body = (body or "").rstrip()
    if not body:
        return "_%s_" % footer
    return "%s\n\n---\n_%s_" % (body, footer)


async def _forkbot_rekey_alias_inbox(env, alias_owner, host_owner, repo,
                                     repo_bi):
    """Recover issue-inbox rows an earlier release filed under an organization
    alias's blind index. No drain ever looked there (see _forkbot_enqueue_issue),
    so those submissions are stranded; move them onto the backing node's key so
    the next sync delivers them. Idempotent (the alias key ends up empty) and
    best-effort — a hiccup here must never fail the new submission. The stored
    item carries no owner binding, so re-keying it is a pure routing fix."""
    if not host_owner or host_owner == alias_owner:
        return
    try:
        alias_bi = await blind_index(env, alias_owner + "/" + repo)
        if alias_bi and alias_bi != repo_bi:
            await d1_run(
                env, "UPDATE issue_inbox SET repo_bi=? WHERE repo_bi=?",
                repo_bi, alias_bi)
    except Exception:
        pass


async def _forkbot_enqueue_issue(env, owner, repo, title, body, requester,
                                 source="forkbot", labels=None,
                                 attachments=None,
                                 federated_mention_id="",
                                 federated_remote_url=""):
    """Queue a relay-authored issue for the owner's desktop node. ForkBot chat
    requests use the defaults. A manually reviewed fediverse item can reuse
    this path with its random review id so the owner node can later confirm
    the exact issue it materialized; inbound posts never call this directly."""
    await ensure_schema(env)
    # ForkBot names the repo by its PUBLIC url (forkmesh/forkmesh), which is an
    # organization alias. Every drain path — the node's per-repo GET and the
    # consolidated GET /api/sync — reads the inbox under the backing node's
    # blind index, because /api/repo/... is org_alias_rewrite'd before routing
    # and /api/sync selects the repositories rows the account actually owns.
    # Keying the insert on the alias therefore dead-letters the row: it sits in
    # issue_inbox forever and never reaches the repository. Resolve org->node
    # for the storage key and the owner-directed notifications (a no-op for a
    # plain node name); public strings/URLs stay on the alias in the caller.
    host_owner = await _ap_org_alias_owner(env, owner, repo)
    repo_bi = await blind_index(env, host_owner + "/" + repo)
    await _forkbot_rekey_alias_inbox(env, owner, host_owner, repo, repo_bi)
    count = await d1_first(
        env, "SELECT COUNT(*) AS c FROM issue_inbox WHERE repo_bi=?", repo_bi)
    if count and int(count.get("c", 0) or 0) >= MAX_PENDING_ISSUES:
        return False, "inbox_full"
    submitter_bi = await blind_index(env, FORKBOT_AUTHOR)
    if await _inbox_author_over_quota(env, "issue_inbox", repo_bi, submitter_bi):
        return False, "author_quota"

    now = int(Date.now())
    actor = clean_string(requester, MAX_NODE_NAME).lower() or FORKBOT_AUTHOR
    body = _forkbot_attributed_body(body, source, actor)
    # Proposed number the desktop honors when the slot is free (0 = let the
    # desktop assign). Allocated before the insert so it lands in the stored
    # item and can be echoed straight back to the chat.
    number = await _forkbot_next_issue_number(env, repo_bi, owner, repo)
    tracked_mention_id = clean_string(federated_mention_id, 32).lower()
    if not re.fullmatch(r"[a-f0-9]{32}", tracked_mention_id):
        tracked_mention_id = ""
    event = {
        "type": "open",
        "id": (
            "fediverse-review-" + tracked_mention_id
            if tracked_mention_id else "forkbot-%d" % now
        ),
        "author": FORKBOT_AUTHOR,
        "authorName": FORKBOT_NAME,
        "ts": now,
        "title": clean_string(title, 240),
        "body": clean_string(body, MAX_ISSUE_BYTES),
        "attachments": [entry["name"] for entry in (attachments or [])],
        "sig": "",
    }
    item = {
        "number": number,
        "titleIfNew": event["title"],
        "event": event,
        "meta": {
            "labels": list(labels) if labels else ["forkbot"],
            "milestone": "",
            "priority": 0,
            "assignees": [],
            "wantsAgent": False,
            "model": "",
            "provider": "",
        },
        "submitter": FORKBOT_AUTHOR,
        "submittedAt": now,
        "source": source,
        "requestedBy": actor,
        "issueNumber": number,
    }
    if tracked_mention_id:
        item["fediverseMentionId"] = tracked_mention_id
        item["fediverseRemoteUrl"] = clean_string(
            federated_remote_url, 1600)
    if attachments:
        item["attachmentData"] = [
            {"name": entry["name"], "data": entry["data"]}
            for entry in attachments]
    await d1_run(
        env,
        "INSERT INTO issue_inbox (repo_bi, data, submitter_bi) VALUES (?,?,?)",
        repo_bi, await encrypt_row(env, item), submitter_bi,
    )
    await _record_contributor(env, FORKBOT_AUTHOR, "issues")
    await _best_effort_inbox_side_effect(
        notify_pending_inbox(
            env, host_owner, repo, "issue", FORKBOT_AUTHOR,
            item.get("titleIfNew", ""), number))
    await _best_effort_inbox_side_effect(
        notify_mentions(
            env, host_owner, repo, FORKBOT_AUTHOR, item.get("titleIfNew", ""),
            event.get("body", ""), repo_web_href(owner, repo), "issue",
            number=number))
    # Same push every other inbox write does: the owner's node syncs on the
    # event frame instead of waiting out the 5-15 minute fallback poll.
    await notify_repo_host(env, host_owner, repo, "issues")
    return True, item


async def _forkbot_enqueue_agent_request(env, owner, repo, number, requester):
    """Queue a "start a coding agent on issue #number" request through the
    same signed-inbox channel as everything else: a ForkBot comment event on
    the existing issue whose meta carries wantsAgent. The owner's desktop node
    starts the agent when it merges the inbox — the relay never runs anything
    itself. Caller has already verified the requester is the repo owner/admin
    (the same privilege gate issues_handler applies to wantsAgent)."""
    await ensure_schema(env)
    # Key the row the way every drain reads it — see _forkbot_enqueue_issue.
    host_owner = await _ap_org_alias_owner(env, owner, repo)
    repo_bi = await blind_index(env, host_owner + "/" + repo)
    await _forkbot_rekey_alias_inbox(env, owner, host_owner, repo, repo_bi)
    count = await d1_first(
        env, "SELECT COUNT(*) AS c FROM issue_inbox WHERE repo_bi=?", repo_bi)
    if count and int(count.get("c", 0) or 0) >= MAX_PENDING_ISSUES:
        return False, "inbox_full"
    submitter_bi = await blind_index(env, FORKBOT_AUTHOR)
    if await _inbox_author_over_quota(env, "issue_inbox", repo_bi, submitter_bi):
        return False, "author_quota"

    now = int(Date.now())
    actor = clean_string(requester, MAX_NODE_NAME).lower() or FORKBOT_AUTHOR
    event = {
        "type": "comment",
        "id": "forkbot-agent-%d" % now,
        "author": FORKBOT_AUTHOR,
        "authorName": FORKBOT_NAME,
        "ts": now,
        "body": "@%s asked ForkBot to start a coding agent on this issue."
                % actor,
        "attachments": [],
        "sig": "",
    }
    item = {
        "number": int(number),
        "titleIfNew": "",
        "event": event,
        "meta": {
            "labels": [],
            "milestone": "",
            "priority": 0,
            "assignees": [],
            "wantsAgent": True,
            "model": "",
            "provider": "",
        },
        "submitter": FORKBOT_AUTHOR,
        "submittedAt": now,
        "source": "forkbot",
        "requestedBy": actor,
    }
    await d1_run(
        env,
        "INSERT INTO issue_inbox (repo_bi, data, submitter_bi) VALUES (?,?,?)",
        repo_bi, await encrypt_row(env, item), submitter_bi,
    )
    await _best_effort_inbox_side_effect(
        notify_pending_inbox(
            env, host_owner, repo, "issue", FORKBOT_AUTHOR,
            "agent request for issue #%d" % int(number), int(number)))
    await notify_repo_host(env, host_owner, repo, "issues")
    return True, item


def _forkbot_gateway_offline_reply(owner, repo):
    return json_response({
        "ok": True,
        "action": "issues_unavailable",
        "botMessage": (
            "I couldn't reach a live host for %s/%s — issues are served from "
            "the owner's desktop node. Try again once it's back online."
        ) % (owner, repo),
    })


async def _forkbot_action_count(env, owner, repo):
    # A "how many" question wants a total, not a capped listing — reusing
    # _forkbot_action_list here would silently truncate at FORKBOT_LIST_MAX
    # and never actually answer the question asked.
    numbers = await _forkbot_recent_issue_numbers(env, owner, repo)
    if numbers is None:
        return _forkbot_gateway_offline_reply(owner, repo)
    total = len(numbers)
    if not total:
        message = "No issues have been filed in %s/%s yet." % (owner, repo)
    else:
        message = "There %s %d issue%s in %s/%s." % (
            "is" if total == 1 else "are", total,
            "" if total == 1 else "s", owner, repo)
    return json_response({
        "ok": True, "action": "issues_counted", "count": total,
        "botMessage": message,
    })


async def _forkbot_action_list(env, owner, repo, count):
    numbers = await _forkbot_recent_issue_numbers(env, owner, repo)
    if numbers is None:
        return _forkbot_gateway_offline_reply(owner, repo)
    issue_url = repo_web_href(owner, repo) + "/issues"
    if not numbers:
        return json_response({
            "ok": True, "action": "issues_listed", "issues": [],
            "botMessage": "No issues have been filed in %s/%s yet."
                          % (owner, repo),
        })
    records = await _forkbot_load_issue_records(env, owner, repo,
                                                numbers[:count])
    if not records:
        return _forkbot_gateway_offline_reply(owner, repo)
    lines = _forkbot_issue_lines(records)
    header = "Last %d issue%s in %s/%s:" % (
        len(records), "" if len(records) == 1 else "s", owner, repo)
    footer = "Full list: " + issue_url
    if len(numbers) > len(records):
        footer = ("Say \"list the last N issues\" for more (up to %d). "
                  % FORKBOT_LIST_MAX) + footer
    return json_response({
        "ok": True,
        "action": "issues_listed",
        "owner": owner,
        "repo": repo,
        "issues": records,
        "botMessage": header + "\n" + lines + "\n" + footer,
    })


async def _forkbot_action_search(env, owner, repo, query):
    matches = await _forkbot_search_issues(env, owner, repo, query)
    if matches is None:
        return _forkbot_gateway_offline_reply(owner, repo)
    if not matches:
        return json_response({
            "ok": True, "action": "issues_searched", "query": query,
            "issues": [],
            "botMessage": "No issues matching \"%s\" in %s/%s."
                          % (query, owner, repo),
        })
    top = matches[:FORKBOT_SEARCH_MAX]
    lines = []
    for hit in top:
        line = "#%d %s" % (hit["number"], hit["title"])
        if hit.get("snippet"):
            line += " — " + hit["snippet"]
        lines.append(line)
    header = "Issues matching \"%s\" in %s/%s:" % (query, owner, repo)
    if len(matches) > len(top):
        header = "Top %d of %d issues matching \"%s\" in %s/%s:" % (
            len(top), len(matches), query, owner, repo)
    return json_response({
        "ok": True,
        "action": "issues_searched",
        "owner": owner,
        "repo": repo,
        "query": query,
        "issues": top,
        "botMessage": header + "\n" + "\n".join(lines),
    })


async def _forkbot_action_show(env, owner, repo, number):
    if number <= 0:
        numbers = await _forkbot_recent_issue_numbers(env, owner, repo)
        if numbers is None:
            return _forkbot_gateway_offline_reply(owner, repo)
        if not numbers:
            return json_response({
                "ok": True, "action": "issue_shown", "issue": None,
                "botMessage": "No issues have been filed in %s/%s yet."
                              % (owner, repo),
            })
        number = numbers[0]
    records = await _forkbot_load_issue_records(env, owner, repo, [number])
    if not records:
        return json_response({
            "ok": True, "action": "issue_shown", "issue": None,
            "botMessage": (
                "I couldn't read issue #%d from a live %s/%s host — it may "
                "not exist, or the owner's node is offline."
            ) % (number, owner, repo),
        })
    record = records[0]
    bot_message = "#%d %s (%s, opened by %s)." % (
        record["number"], record["title"], record["status"], record["author"])
    if record.get("body"):
        bot_message += " " + record["body"]
    return json_response({
        "ok": True,
        "action": "issue_shown",
        "owner": owner,
        "repo": repo,
        "issue": record,
        "botMessage": bot_message,
    })


async def _forkbot_action_start_agent(env, owner, repo, number, sender):
    # Starting a coding agent on the owner's machine is an immediate,
    # unreviewed side effect, so it keeps the same privilege gate the web
    # issue form's wantsAgent has (adhoc #225): the repo owner's account or a
    # network admin. Chat sender names are client-claimed, matching the trust
    # model of the web form's ownerAccount field.
    requester = clean_string(sender, MAX_NODE_NAME).strip().lower()
    # When the repo is fronted by an organization alias, the account that owns
    # it (and whose node would run the agent) is the backing node, not the org
    # name in the URL — check against both so the real owner isn't refused.
    host_owner = (await _ap_org_alias_owner(env, owner, repo)).lower()
    authorized = bool(requester) and (
        requester == owner.lower() or requester == host_owner
        or await _is_admin(env, requester))
    if not authorized:
        return json_response({
            "ok": True,
            "action": "agent_denied",
            "botMessage": (
                "Starting a coding agent is limited to the repo owner (or a "
                "network admin) — ask %s to kick it off."
            ) % owner,
        })
    numbers = await _forkbot_recent_issue_numbers(env, owner, repo)
    if numbers is None:
        return _forkbot_gateway_offline_reply(owner, repo)
    if not numbers:
        return json_response({
            "ok": True, "action": "agent_denied",
            "botMessage": "There are no issues in %s/%s to start an agent on."
                          % (owner, repo),
        })
    if number <= 0:
        number = numbers[0]
    elif number not in numbers:
        return json_response({
            "ok": True, "action": "agent_denied",
            "botMessage": "Issue #%d isn't in the %s/%s mirror."
                          % (number, owner, repo),
        })
    records = await _forkbot_load_issue_records(env, owner, repo, [number])
    title = records[0]["title"] if records else ""
    ok, result = await _forkbot_enqueue_agent_request(
        env, owner, repo, number, requester)
    if not ok:
        return json_response({"error": result}, status=429)
    bot_message = (
        "Queued a coding agent for issue #%d%s in %s/%s. The owner's node "
        "will start it when it next syncs the inbox."
    ) % (number, (": " + title) if title else "", owner, repo)
    return json_response({
        "ok": True,
        "action": "agent_requested",
        "owner": owner,
        "repo": repo,
        "issueNumber": number,
        "title": title,
        "botMessage": bot_message,
    }, status=201)


async def forkbot_chat_handler(env, request):
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    if not isinstance(data, dict):
        return json_response({"error": "invalid_json"}, status=400)

    message = clean_string(data.get("message", ""), FORKBOT_MAX_COMMAND)
    command = _forkbot_extract_mention_command(message)
    if not command:
        return json_response({"ok": True, "ignored": True})

    # Recent (client-decrypted) conversation the mention sits in, so ForkBot can
    # resolve "that bug" / "the issue we discussed" instead of only the one line.
    context_text = _forkbot_context_text(data.get("context"))
    sender = clean_string(data.get("sender", ""), MAX_NODE_NAME)
    owner = FORKBOT_DEFAULT_OWNER
    repo = FORKBOT_DEFAULT_REPO

    # Decide the action. Prefer meaning over fixed wording:
    #  1. Cheap regexes catch explicitly phrased commands offline (list /
    #     search / start-agent / show / help / create), sparing an AI round
    #     trip and keeping every command working when AI is off.
    #  2. Otherwise the AI classifier reads the command + conversation and
    #     picks the intent (drafting the issue when one is wanted).
    #  3. AI unreachable (None — distinct from a confident "none") but the
    #     message plainly talks about issues/bugs/tracking: file the raw text
    #     rather than refusing. Only a confident "none" or a message with no
    #     work-recording signal at all gets the help hint.
    action = None
    for intent_name, parser in (
            ("count_issues", _forkbot_parse_count_command),
            ("list_issues", _forkbot_parse_list_command),
            ("search_issues", _forkbot_parse_search_command),
            ("start_agent", _forkbot_parse_agent_command),
            ("show_issue", _forkbot_parse_show_command)):
        parsed_intent = parser(command)
        if parsed_intent is not None:
            action = {"intent": intent_name, **parsed_intent}
            break
    if action is None and _forkbot_parse_help_command(command):
        action = {"intent": "help"}

    fields = None
    if action is None:
        parsed = _forkbot_parse_issue_command(command)
        if parsed:
            action = {"intent": "create_issue"}
            fields = await _forkbot_ai_issue_fields(
                env, parsed["description"], context_text)
            if not fields:
                fields = _forkbot_fallback_issue_fields(parsed["description"])
        else:
            interpreted = await _forkbot_ai_interpret(env, command, context_text)
            if interpreted and interpreted.get("intent") == "create_issue":
                action = {"intent": "create_issue"}
                fields = {"title": interpreted["title"],
                          "body": interpreted["body"]}
            elif interpreted and interpreted.get("intent") != "none":
                action = interpreted
            elif interpreted is None and _forkbot_command_hints_issue(command):
                action = {"intent": "create_issue"}
                fields = _forkbot_fallback_issue_fields(command)

    intent = (action or {}).get("intent", "")
    if intent == "count_issues":
        return await _forkbot_action_count(env, owner, repo)
    if intent == "list_issues":
        return await _forkbot_action_list(env, owner, repo, action["count"])
    if intent == "search_issues":
        return await _forkbot_action_search(env, owner, repo, action["query"])
    if intent == "show_issue":
        return await _forkbot_action_show(
            env, owner, repo, int(action.get("issueNumber", 0) or 0))
    if intent == "start_agent":
        return await _forkbot_action_start_agent(
            env, owner, repo, int(action.get("issueNumber", 0) or 0), sender)

    if intent != "create_issue" or not fields or not fields.get("body"):
        return json_response({
            "ok": True,
            "action": "help",
            "botMessage": _forkbot_help_message(),
        })

    ok, result = await _forkbot_enqueue_issue(
        env, owner, repo, fields["title"], fields["body"], sender)
    if not ok:
        return json_response({"error": result}, status=429)
    title = result.get("titleIfNew", fields["title"])
    number = int(result.get("issueNumber", 0) or 0)
    # /owner/repo/issues is the web route for the repo's issue list; the number
    # is the proposed one the desktop honors when it merges the inbox.
    issue_url = repo_web_href(owner, repo) + "/issues"
    if number > 0:
        bot_message = (
            "Opened issue #%d in %s/%s: %s. It'll show at %s once the owner "
            "node syncs the inbox."
        ) % (number, owner, repo, title, issue_url)
    else:
        bot_message = (
            "Opened an issue in %s/%s: %s. It'll show at %s once the owner "
            "node syncs the inbox."
        ) % (owner, repo, title, issue_url)
    return json_response({
        "ok": True,
        "action": "issue_created",
        "owner": owner,
        "repo": repo,
        "title": title,
        "issueNumber": number,
        "issueUrl": issue_url,
        "botMessage": bot_message,
    }, status=201)


def _clean_issue_attachment_data(value):
    """Validate the base64 image bytes a no-write-access node ships alongside a
    signed issue/comment "open"/"comment" event (see MAX_ISSUE_ATTACHMENT_BYTES).
    Returns (cleaned_list, error); cleaned_list entries are {"name","data"} with
    data re-encoded from the decoded bytes so nothing but valid base64 survives."""
    if not isinstance(value, list):
        return [], None
    if len(value) > MAX_ISSUE_ATTACHMENTS:
        return [], "too_many_attachments"
    cleaned = []
    for entry in value:
        if not isinstance(entry, dict):
            return [], "bad_attachment"
        name = entry.get("name", "")
        if not isinstance(name, str) or not ISSUE_ATTACHMENT_NAME_RE.match(name):
            return [], "bad_attachment"
        data = entry.get("data", "")
        if not isinstance(data, str) or len(data) > 4 * (
                (MAX_ISSUE_ATTACHMENT_BYTES + 2) // 3):
            return [], "attachment_too_large"
        try:
            raw = base64.b64decode(data, validate=True)
        except Exception:
            return [], "bad_attachment"
        if len(raw) > MAX_ISSUE_ATTACHMENT_BYTES:
            return [], "attachment_too_large"
        cleaned.append({"name": name, "data": base64.b64encode(raw).decode()})
    return cleaned, None


async def _log_inbox_drain(env, repo_bi, kind, count):
    # Audit trail for inbox acks (adhoc #97): one row per non-empty drain so a
    # "web-filed item vanished but never synced" report is traceable. Content-free
    # (blind-indexed repo, a count) and best-effort — never fail the ack over it.
    if count <= 0:
        return
    try:
        await d1_run(
            env,
            "INSERT INTO inbox_drain_log (ts, repo_bi, kind, count) VALUES (?,?,?,?)",
            int(Date.now()), repo_bi, kind, int(count))
    except Exception:
        pass


def _drain_ids_from_request(request):
    # ?ids=1,2,3 on an inbox-drain DELETE: the node acks exactly the rows it
    # merged, so a submission inserted after the node's read survives to the
    # next sync instead of being swept away undelivered (adhoc #97).
    params = parse_qs(urlparse(request.url).query)
    raw = params.get("ids", [""])[0]
    ids = []
    for part in raw.split(","):
        part = part.strip()
        if not part:
            continue
        try:
            ids.append(int(part))
        except (TypeError, ValueError):
            continue
    return ids


async def _authorized_mirror_issue_signing_key(env, request, owner, repo):
    """Authorize one fresh direct-HTTPS node that mirrors this public repo.

    The caller signs with the account-bound key registered for its endpoint.
    Repository membership comes from the same owner-pinned public mirror group
    used by direct reads, so merely being an online ForkMesh node is not enough.
    """
    if await _repo_is_private(env, owner, repo):
        return "", ""
    params = parse_qs(urlparse(request.url).query)
    signer = safe_segment(params.get("owner", [""])[0])
    ts = params.get("ts", [""])[0]
    sig = params.get("sig", [""])[0]
    if not signer or not ts or not sig:
        return "", ""
    try:
        if abs(int(Date.now()) - int(ts)) > LOGIN_MAX_SKEW_MS:
            return "", ""
    except (TypeError, ValueError):
        return "", ""
    try:
        original = REPO_API_PREFIX_RE.match(urlparse(request.url).path)
        public_owner = (
            safe_segment(original.group(1)) if original else owner)
        public_repo = (
            safe_segment(original.group(2)) if original else repo)
        context = await _https_mirror_public_context(
            env, public_owner, public_repo)
    except Exception:
        context = None
    if not context:
        return "", ""
    allowed_nodes = {
        str(value or "").strip().lower()
        for value in context.get("nodes", set())
    }
    now = int(Date.now())
    rows = await d1_all(
        env,
        """SELECT node_name,public_key FROM mirror_https_endpoints
            WHERE checked_at>=? AND forkmesh_verified_at>=?
              AND healthy=1 AND forkmesh_active=1
              AND integrity='ok' AND abuse_blocked=0""",
        now - HTTPS_MIRROR_STATUS_FRESH_MS,
        now - HTTPS_MIRROR_STATUS_FRESH_MS,
    )
    canonical = (
        "forkmesh-issues-pull-v1\n" + signer + "\n" + ts
    ).encode()
    for row in rows or []:
        node = clean_string(
            row.get("node_name", ""), MAX_NODE_NAME).strip().lower()
        public_key = clean_string(row.get("public_key", ""), 160).strip()
        if (
            node not in allowed_nodes
            or not valid_node_pubkey(public_key)
            or public_key not in await _owner_signing_pubkeys(env, node)
        ):
            continue
        if await ed25519_verify(public_key, sig, canonical):
            return public_key, node
    return "", ""


async def _claim_issue_inbox(
        env, repo_bi, signing_key, mirror_only=False):
    """Lease every currently available row to one authorized desktop device.

    The UPDATE predicate makes competing drains converge on one winner per row:
    once one device writes its opaque claimant index, another device cannot
    overwrite it until the bounded lease expires.
    """
    if not signing_key:
        return ""
    claimant_bi = await blind_index(
        env, "issue-inbox-claim:" + signing_key)
    now = int(Date.now())
    mirror_clause = " AND mirrored_at=0" if mirror_only else ""
    await d1_run(
        env,
        "UPDATE issue_inbox SET claimed_by_bi=?, claim_expires_at=? "
        "WHERE repo_bi=? AND (claimed_by_bi='' OR claim_expires_at<=? "
        "OR claimed_by_bi=?)" + mirror_clause,
        claimant_bi, now + ISSUE_INBOX_CLAIM_TTL_MS, repo_bi, now,
        claimant_bi,
    )
    return claimant_bi


async def _materialize_issue_inbox_on_mirror(
        env, request, repo_bi, claimant_bi, mirror_node):
    """Mark exact rows visible on one mirror without consuming owner delivery."""
    ids = _drain_ids_from_request(request)
    if not ids or not claimant_bi or not mirror_node:
        return 0
    marks = ",".join("?" for _ in ids)
    mirror_bi = await blind_index(env, "issue-mirror:" + mirror_node)
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS c FROM issue_inbox WHERE repo_bi=? "
        "AND id IN (%s) AND claimed_by_bi=? AND mirrored_at=0" % marks,
        repo_bi, *ids, claimant_bi,
    )
    count = int((row or {}).get("c") or 0)
    if count:
        await d1_run(
            env,
            "UPDATE issue_inbox SET mirrored_by_bi=?,mirrored_at=?,"
            "claimed_by_bi='',claim_expires_at=0 WHERE repo_bi=? "
            "AND id IN (%s) AND claimed_by_bi=? AND mirrored_at=0" % marks,
            mirror_bi, int(Date.now()), repo_bi, *ids, claimant_bi,
        )
    return count


async def _drain_issue_inbox(env, request, repo_bi, claimant_bi=""):
    """Ack (delete) the exact issue-inbox rows named by ?ids=, returning how many
    were removed, and record the drain in inbox_drain_log. Rows the node did not
    ack (including a submission that arrived after it read the queue) are left
    for the next sync; a request with no ids removes nothing (adhoc #97)."""
    ids = _drain_ids_from_request(request)
    if not ids:
        return 0
    marks = ",".join("?" for _ in ids)
    claim_clause = " AND claimed_by_bi=?" if claimant_bi else ""
    args = (repo_bi, *ids, *([claimant_bi] if claimant_bi else []))
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS c FROM issue_inbox WHERE repo_bi=? "
        "AND id IN (%s)" % marks + claim_clause,
        *args)
    removed = int(row.get("c", 0)) if row else 0
    if claimant_bi:
        await d1_run(
            env,
            "DELETE FROM issue_inbox WHERE repo_bi=? AND id IN (%s) "
            "AND claimed_by_bi=?" % marks,
            *args)
    else:
        await d1_run(
            env,
            "DELETE FROM issue_inbox WHERE repo_bi=? AND id IN (%s)" % marks,
            repo_bi, *ids)
    await _log_inbox_drain(env, repo_bi, "issues", removed)
    return removed


async def _confirm_fediverse_issue_materializations(env, request):
    """Apply bounded owner-node confirmations carried by a signed inbox ack."""
    values = parse_qs(urlparse(request.url).query).get("materialized", [""])
    raw = values[0] if values else ""
    runtime = _WorldCommunityRuntime(env, request)
    confirmed = 0
    for value in str(raw or "").split(",")[:MAX_PENDING_PER_AUTHOR]:
        mention_id, separator, number_text = value.partition(":")
        if (
            not separator
            or not re.fullmatch(r"[a-f0-9]{32}", mention_id)
        ):
            continue
        try:
            number = int(number_text)
        except (TypeError, ValueError):
            continue
        if number <= 0:
            continue
        if await fediverse_mentions_api.confirm_materialized(
            runtime, mention_id, number
        ):
            confirmed += 1
    return confirmed


async def issues_handler(env, request, owner, repo):
    await ensure_schema(env)
    method = method_name(request)
    repo_bi = await blind_index(env, owner + "/" + repo)
    if method == "POST":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        event = data.get("event")
        if not isinstance(event, dict):
            return json_response({"error": "event_required"}, status=400)
        try:
            number = int(data.get("number", 0))
        except (TypeError, ValueError):
            number = 0
        if len((event.get("body", "") or "").encode("utf-8")) > MAX_ISSUE_BYTES:
            return json_response({"error": "issue_too_large"}, status=413)
        if not await verify_issue_event(number, event):
            return json_response({"error": "bad_signature"}, status=401)
        # Screenshots the submitter had no working tree to copy in ride along as
        # base64 bytes, named to match the signed event's attachments list.
        attachment_data, attach_err = _clean_issue_attachment_data(
            data.get("attachmentData"))
        if attach_err:
            status = 413 if attach_err in (
                "too_many_attachments", "attachment_too_large") else 400
            return json_response({"error": attach_err}, status=status)
        count = await d1_first(
            env, "SELECT COUNT(*) AS c FROM issue_inbox WHERE repo_bi=?", repo_bi
        )
        if count and count.get("c", 0) >= MAX_PENDING_ISSUES:
            return json_response({"error": "inbox_full"}, status=429)
        submitter_bi = await blind_index(env, event.get("author", ""))
        if await _inbox_author_over_quota(env, "issue_inbox", repo_bi, submitter_bi):
            return json_response({"error": "author_quota"}, status=429)
        # Issue-level metadata for a new issue (labels/milestone/priority/
        # assignees). Not signature-bound; the owner applies it on merge. Bounded
        # to keep a submission small and the lists sane.
        meta_in = data.get("meta")
        meta = {}
        if isinstance(meta_in, dict):
            labels = meta_in.get("labels")
            assignees = meta_in.get("assignees")
            try:
                priority = int(meta_in.get("priority", 0))
            except (TypeError, ValueError):
                priority = 0
            # "wantsAgent" makes the owner's node start a coding agent on this
            # issue automatically once merged — unlike the other meta fields
            # above, that's an immediate, unreviewed side effect, so it's only
            # honored when the request comes from a privileged account: the repo
            # owner, or an admin acting on the owner's behalf (adhoc #225).
            wants_agent = False
            agent_model = ""
            agent_provider = ""
            if meta_in.get("wantsAgent"):
                ok, err = await _authorize_owner_account(env, owner, data, request)
                if not ok:
                    return err
                wants_agent = True
                # Optional model choice (e.g. "opus"/"sonnet"/"haiku"/"fable" or a
                # full model id) for the agent the desktop node auto-starts on this
                # issue; empty leaves the provider's own default. Only meaningful
                # alongside wantsAgent, so it's not parsed otherwise.
                agent_model = clean_string(meta_in.get("model", ""), 60)
                # Optional agent-provider choice from the web dropdown (adhoc #234);
                # only a known provider is honored, else the node picks its default.
                provider_in = clean_string(meta_in.get("provider", ""), 40)
                if provider_in in ("claude-code", "claude-api", "openai"):
                    agent_provider = provider_in
            meta = {
                "labels": [clean_string(x, 60) for x in (labels or [])][:20]
                if isinstance(labels, list) else [],
                "milestone": clean_string(meta_in.get("milestone", ""), 120),
                "project": clean_string(meta_in.get("project", ""), 120),
                "priority": priority if 0 <= priority <= 99 else 0,
                "assignees": [clean_string(x, 60) for x in (assignees or [])][:20]
                if isinstance(assignees, list) else [],
                "wantsAgent": wants_agent,
                "model": agent_model,
                "provider": agent_provider,
            }
        item = {
            "number": number,
            "titleIfNew": clean_string(data.get("titleIfNew", ""), 240),
            "event": event,
            "meta": meta,
            "attachmentData": attachment_data,
            "submitter": clean_string(event.get("author", ""), 120),
            "submittedAt": int(Date.now()),
        }
        await d1_run(
            env,
            "INSERT INTO issue_inbox (repo_bi, data, submitter_bi) VALUES (?,?,?)",
            repo_bi, await encrypt_row(env, item), submitter_bi,
        )
        await _record_contributor(env, event.get("author", ""), "issues")
        actor = clean_string(event.get("authorName", "") or event.get("author", ""), MAX_NODE_NAME).lower()
        await _best_effort_inbox_side_effect(
            notify_pending_inbox(
                env, owner, repo, "issue", actor, item.get("titleIfNew", ""),
                number))
        await _best_effort_inbox_side_effect(
            notify_mentions(
                env, owner, repo, actor, item.get("titleIfNew", ""),
                event.get("body", ""), repo_web_href(owner, repo), "issue",
                number=number))
        assignees = list(meta.get("assignees", [])) if isinstance(meta, dict) else []
        if isinstance(event.get("assignees"), list):
            assignees.extend(event.get("assignees"))
        await _best_effort_inbox_side_effect(
            notify_issue_assignees(
                env, owner, repo, assignees, actor, item.get("titleIfNew", ""),
                number))
        # Subscriptions (issue #361): tell everyone already following this issue
        # about the new activity, then auto-subscribe the commenter so they hear
        # about later replies. Both no-op for a brand-new issue (number 0).
        await _best_effort_inbox_side_effect(
            notify_subscribers(
                env, owner, repo, "issue", number, actor,
                item.get("titleIfNew", ""), event.get("body", ""),
                repo_web_href(owner, repo)))
        await _best_effort_inbox_side_effect(
            subscribe_thread(env, owner, repo, "issue", number, actor))
        await notify_repo_host(env, owner, repo, "issues")
        await notify_repo_mirrors(env, owner, repo, "issues")
        # Fediverse: announce content events (opens/comments — never labels or
        # status flips) to any followers of the repo/author actors.
        if event.get("type") in ("open", "comment"):
            await _best_effort_inbox_side_effect(_ap_publish_repo_event(
                env, request, owner, repo, "issue", event.get("type"),
                number, item.get("titleIfNew", ""), event.get("body", ""),
                event.get("authorName", "")))
        return json_response({"ok": True}, status=201)

    if method == "GET":
        mirror_intake = (
            parse_qs(urlparse(request.url).query).get("mirror", [""])[0]
            == "1")
        mirror_node = ""
        if mirror_intake:
            signing_key, mirror_node = (
                await _authorized_mirror_issue_signing_key(
                    env, request, owner, repo))
        else:
            signing_key = await _authorized_repo_inbox_signing_key(
                env, request, owner, repo)
        if not signing_key:
            return json_response({"error": "unauthorized"}, status=401)
        claimant_bi = await _claim_issue_inbox(
            env, repo_bi, signing_key, mirror_only=mirror_intake)
        mirror_filter = " AND mirrored_at=0" if mirror_intake else ""
        rows = await d1_all(
            env,
            "SELECT id, data FROM issue_inbox "
            "WHERE repo_bi=? AND claimed_by_bi=?" + mirror_filter
            + " ORDER BY id ASC",
            repo_bi, claimant_bi,
        )
        pending = []
        for r in rows:
            rec = await decrypt_row(env, r["data"])
            if rec:
                # The row id lets the node ack exactly what it merged so a
                # submission that lands mid-drain isn't swept away undelivered
                # (adhoc #97) — the "stayed pending, then vanished, never synced"
                # bug. A DELETE must name the ids to remove; without them the
                # drain removes nothing.
                rec["id"] = r.get("id")
                pending.append(rec)
        return json_response({
            "ok": True,
            "pending": pending,
            "mirrorIntake": mirror_intake,
            "mirror": mirror_node,
        })

    if method == "DELETE":
        mirror_intake = (
            parse_qs(urlparse(request.url).query).get("mirror", [""])[0]
            == "1")
        mirror_node = ""
        if mirror_intake:
            signing_key, mirror_node = (
                await _authorized_mirror_issue_signing_key(
                    env, request, owner, repo))
        else:
            signing_key = await _authorized_repo_inbox_signing_key(
                env, request, owner, repo)
        if not signing_key:
            return json_response({"error": "unauthorized"}, status=401)
        claimant_bi = await blind_index(
            env, "issue-inbox-claim:" + signing_key)
        if mirror_intake:
            materialized = await _materialize_issue_inbox_on_mirror(
                env, request, repo_bi, claimant_bi, mirror_node)
            return json_response({
                "ok": True,
                "drained": 0,
                "materialized": materialized,
                "retainedForSource": True,
            })
        materialized = await _confirm_fediverse_issue_materializations(
            env, request)
        removed = await _drain_issue_inbox(
            env, request, repo_bi, claimant_bi)
        return json_response({
            "ok": True,
            "drained": removed,
            "materialized": materialized,
        })

    return json_response({"error": "method_not_allowed"}, status=405)


async def pulls_handler(env, request, owner, repo):
    await ensure_schema(env)
    method = method_name(request)
    repo_bi = await blind_index(env, owner + "/" + repo)
    if method == "POST":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        # A submission is either a whole new PR ("pull") or a signed conversation
        # event ("event" + "number") — a comment or review on an existing PR.
        event = data.get("event")
        if isinstance(event, dict):
            try:
                number = int(data.get("number", 0))
            except (TypeError, ValueError):
                number = 0
            if len((event.get("body", "") or "").encode("utf-8")) > MAX_ISSUE_BYTES:
                return json_response({"error": "event_too_large"}, status=413)
            if not await verify_pull_comment_event(number, event):
                return json_response({"error": "bad_signature"}, status=401)
            count = await d1_first(
                env, "SELECT COUNT(*) AS c FROM pull_inbox WHERE repo_bi=?", repo_bi
            )
            if count and count.get("c", 0) >= MAX_PENDING_PULLS:
                return json_response({"error": "inbox_full"}, status=429)
            submitter_bi = await blind_index(env, event.get("author", ""))
            if await _inbox_author_over_quota(
                    env, "pull_inbox", repo_bi, submitter_bi):
                return json_response({"error": "author_quota"}, status=429)
            item = {
                "number": number,
                "event": event,
                "submitter": clean_string(event.get("author", ""), 120),
                "submittedAt": int(Date.now()),
            }
            await d1_run(
                env,
                "INSERT INTO pull_inbox (repo_bi, data, submitter_bi) "
                "VALUES (?,?,?)",
                repo_bi, await encrypt_row(env, item), submitter_bi,
            )
            await _record_contributor(env, event.get("author", ""), "pulls")
            actor = clean_string(event.get("authorName", "") or event.get("author", ""), MAX_NODE_NAME).lower()
            await notify_pending_inbox(env, owner, repo, "pull", actor, event.get("body", ""), number)
            await notify_mentions(env, owner, repo, actor, "Pull request comment", event.get("body", ""),
                                  repo_web_href(owner, repo), "pull", number=number)
            # Subscriptions (issue #361): fan the comment out to the PR's
            # followers, then auto-subscribe the commenter.
            await notify_subscribers(env, owner, repo, "pull", number, actor,
                                     "Pull request comment", event.get("body", ""),
                                     repo_web_href(owner, repo))
            await subscribe_thread(env, owner, repo, "pull", number, actor)
            await notify_repo_host(env, owner, repo, "pulls")
            if event.get("type") in ("comment", "review"):
                await _best_effort_inbox_side_effect(_ap_publish_repo_event(
                    env, request, owner, repo, "pull", event.get("type"),
                    number, "", event.get("body", ""),
                    event.get("authorName", "")))
            return json_response({"ok": True}, status=201)
        pull = data.get("pull")
        if not isinstance(pull, dict):
            return json_response({"error": "pull_required"}, status=400)
        signed_fields = ("title", "base", "head", "patch", "commits")
        if any(
                field in pull and not isinstance(pull.get(field), str)
                for field in signed_fields):
            return json_response({"error": "pull_invalid"}, status=400)
        description = (
            pull.get("description")
            if "description" in pull else pull.get("body", ""))
        if not isinstance(description, str):
            return json_response({"error": "pull_invalid"}, status=400)
        if len(description.encode("utf-8")) > MAX_ISSUE_BYTES:
            return json_response(
                {"error": "description_too_large"}, status=413)
        # `description` is the native Qt wire name. Normalize legacy browser
        # `body` submissions before encrypting the inbox item so either kind of
        # sender drains into the same lossless PullRequest representation.
        pull["description"] = description
        pull.pop("body", None)
        pull_bytes = len((pull.get("patch", "") or "").encode("utf-8")) + len(
            (pull.get("commits", "") or "").encode("utf-8"))
        if pull_bytes > MAX_PULL_BYTES:
            return json_response({"error": "pull_too_large"}, status=413)
        if not await verify_pull_event(pull):
            return json_response({"error": "bad_signature"}, status=401)
        count = await d1_first(
            env, "SELECT COUNT(*) AS c FROM pull_inbox WHERE repo_bi=?", repo_bi
        )
        if count and count.get("c", 0) >= MAX_PENDING_PULLS:
            return json_response({"error": "inbox_full"}, status=429)
        submitter_bi = await blind_index(env, pull.get("author", ""))
        if await _inbox_author_over_quota(env, "pull_inbox", repo_bi, submitter_bi):
            return json_response({"error": "author_quota"}, status=429)
        item = {
            "pull": pull,
            "submitter": clean_string(pull.get("author", ""), 120),
            "submittedAt": int(Date.now()),
        }
        await d1_run(
            env,
            "INSERT INTO pull_inbox (repo_bi, data, submitter_bi) VALUES (?,?,?)",
            repo_bi, await encrypt_row(env, item), submitter_bi,
        )
        await _record_contributor(env, pull.get("author", ""), "pulls")
        actor = clean_string(pull.get("authorName", "") or pull.get("author", ""), MAX_NODE_NAME).lower()
        title = clean_string(pull.get("title", "") or pull.get("subject", ""), 240)
        await notify_pending_inbox(env, owner, repo, "pull", actor, title, 0)
        await notify_mentions(env, owner, repo, actor, title, description,
                              repo_web_href(owner, repo), "pull")
        await notify_repo_host(env, owner, repo, "pulls")
        # Badge (adhoc #44): render the PR's visual fingerprint from the
        # signed patch and attach it to the federated note as its lead image.
        # Best-effort — a badge failure must never block the submission.
        badge = None
        try:
            stats = patch_file_stats(pull.get("patch", "") or "")
            if stats:
                png = pull_badge_png(
                    title, clean_string(
                        pull.get("authorName", "") or pull.get("author", ""),
                        MAX_NODE_NAME), stats)
                badge = {"mediaType": "image/png",
                         "data": base64.b64encode(png).decode("ascii")}
        except Exception:
            badge = None
        await _best_effort_inbox_side_effect(_ap_publish_repo_event(
            env, request, owner, repo, "pull", "open", 0, title,
            description, pull.get("authorName", ""),
            extra_images=[badge] if badge else None))
        return json_response({"ok": True}, status=201)

    if method == "GET":
        if not await _authorize_repo_inbox_owner(
                env, request, owner, repo):
            return json_response({"error": "unauthorized"}, status=401)
        rows = await d1_all(
            env, "SELECT data FROM pull_inbox WHERE repo_bi=? ORDER BY id ASC",
            repo_bi,
        )
        pending = [rec for rec in
                   [await decrypt_row(env, r["data"]) for r in rows] if rec]
        return json_response({"ok": True, "pending": pending})

    if method == "DELETE":
        if not await _authorize_repo_inbox_owner(
                env, request, owner, repo):
            return json_response({"error": "unauthorized"}, status=401)
        await d1_run(env, "DELETE FROM pull_inbox WHERE repo_bi=?", repo_bi)
        return json_response({"ok": True})

    return json_response({"error": "method_not_allowed"}, status=405)


async def commits_handler(env, request, owner, repo):
    await ensure_schema(env)
    method = method_name(request)
    repo_bi = await blind_index(env, owner + "/" + repo)
    if method == "POST":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        comment = data.get("comment")
        sha = clean_string(data.get("sha", ""), 40)
        if not isinstance(comment, dict) or not sha:
            return json_response({"error": "comment_required"}, status=400)
        if len((comment.get("body", "") or "").encode("utf-8")) > MAX_COMMIT_COMMENT_BYTES:
            return json_response({"error": "comment_too_large"}, status=413)
        if not await verify_commit_comment_event(sha, comment):
            return json_response({"error": "bad_signature"}, status=401)
        count = await d1_first(
            env, "SELECT COUNT(*) AS c FROM commit_inbox WHERE repo_bi=?", repo_bi
        )
        if count and count.get("c", 0) >= MAX_PENDING_COMMIT_COMMENTS:
            return json_response({"error": "inbox_full"}, status=429)
        submitter_bi = await blind_index(env, comment.get("author", ""))
        if await _inbox_author_over_quota(env, "commit_inbox", repo_bi, submitter_bi):
            return json_response({"error": "author_quota"}, status=429)
        item = {
            "sha": sha,
            "comment": comment,
            "submitter": clean_string(comment.get("author", ""), 120),
            "submittedAt": int(Date.now()),
        }
        await d1_run(
            env,
            "INSERT INTO commit_inbox (repo_bi, data, submitter_bi) VALUES (?,?,?)",
            repo_bi, await encrypt_row(env, item), submitter_bi,
        )
        await _record_contributor(env, comment.get("author", ""), "commits")
        actor = clean_string(comment.get("authorName", "") or comment.get("author", ""), MAX_NODE_NAME).lower()
        await notify_pending_inbox(env, owner, repo, "commit_comment", actor, sha, 0)
        await notify_mentions(env, owner, repo, actor, "Commit " + sha[:12], comment.get("body", ""),
                              repo_web_href(owner, repo), "commit_comment")
        await notify_repo_host(env, owner, repo, "commits")
        await _best_effort_inbox_side_effect(_ap_publish_repo_event(
            env, request, owner, repo, "commit", "comment", sha, "",
            comment.get("body", ""), comment.get("authorName", "")))
        return json_response({"ok": True}, status=201)

    if method == "GET":
        if not await _authorize_owner(env, request, owner):
            return json_response({"error": "unauthorized"}, status=401)
        rows = await d1_all(
            env, "SELECT data FROM commit_inbox WHERE repo_bi=? ORDER BY id ASC",
            repo_bi,
        )
        pending = [rec for rec in
                   [await decrypt_row(env, r["data"]) for r in rows] if rec]
        return json_response({"ok": True, "pending": pending})

    if method == "DELETE":
        if not await _authorize_owner(env, request, owner):
            return json_response({"error": "unauthorized"}, status=401)
        await d1_run(env, "DELETE FROM commit_inbox WHERE repo_bi=?", repo_bi)
        return json_response({"ok": True})

    return json_response({"error": "method_not_allowed"}, status=405)


