async def repo_pending_counts_handler(env, request, owner, repo):
    # GET /api/repo/{owner}/{repo}/pending — content-free tallies of inbox
    # items still waiting for the owner node's next sync, so the website can
    # badge the Issues/Pulls/Discussions/Commits tabs with "N pending".
    # Public: the counts reveal only submission volume (submissions come from
    # the public anyway); the items themselves stay encrypted and owner-gated
    # behind the per-topic GET routes. One UNION round trip, edge-cacheable
    # briefly so repeated page views don't re-hit D1.
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    # Submission volume is still repository metadata. Private and unpublished
    # names return the same response and never expose whether inbox rows exist.
    privacy_reader = globals().get("_repo_is_private")
    if callable(privacy_reader) and await privacy_reader(env, owner, repo):
        return json_response({"error": "not_found"}, status=404)
    await ensure_schema(env)
    repo_bi = await blind_index(env, owner + "/" + repo)
    rows = await d1_all(
        env,
        "SELECT 'issues' AS k, COUNT(*) AS c FROM issue_inbox "
        "WHERE repo_bi=? AND mirrored_at=0 "
        "UNION ALL SELECT 'pulls', COUNT(*) FROM pull_inbox WHERE repo_bi=? "
        "UNION ALL SELECT 'discussions', COUNT(*) FROM discussion_inbox WHERE repo_bi=? "
        "UNION ALL SELECT 'commits', COUNT(*) FROM commit_inbox WHERE repo_bi=?",
        repo_bi, repo_bi, repo_bi, repo_bi,
    )
    counts = {str(r.get("k") or ""): int(r.get("c") or 0) for r in rows or []}
    return json_response({
        "ok": True,
        "pending": {
            "issues": counts.get("issues", 0),
            "pulls": counts.get("pulls", 0),
            "discussions": counts.get("discussions", 0),
            "commits": counts.get("commits", 0),
        },
    }, cache_seconds=30)


async def sync_handler(env, request):
    # GET /api/sync?owner={name}&ts=&sig= — one signed round-trip returning
    # everything the owner's desktop node needs across ALL of its repos:
    # pending issue/pull/discussion/commit inbox items, queued agent prompts
    # (drained on read, same semantics as GET /agents), and the relay's pinned
    # repo state. This replaces the node's old fast polling (4 inbox GETs per
    # repo every 60s + agents every 30s + catalog list for pin checks): the
    # node now calls this on a bounded HTTPS polling schedule.
    # Auth reuses the forkmesh-issues-pull-v1 drain token (_authorize_owner).
    await ensure_schema(env)
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    params = parse_qs(urlparse(request.url).query)
    owner = safe_segment(params.get("owner", [""])[0])
    signing_key = await _authorized_owner_signing_key(
        env, request, owner)
    if not signing_key:
        return json_response({"error": "unauthorized"}, status=401)
    issue_claimant_bi = await blind_index(
        env, "issue-inbox-claim:" + signing_key)
    owner_bi = await blind_index(env, owner)
    rows = await d1_all(
        env, "SELECT key_bi, data FROM repositories WHERE owner_bi=?", owner_bi)
    repo_bis = [row["key_bi"] for row in rows]
    # One query per table across ALL of the owner's repos (IN-list) instead of
    # six queries per repo: /api/sync fires on every pushed event frame AND
    # the fallback poll, and the old 6N sequential D1 roundtrips were a top
    # contributor to the 2026-07-11 free-plan overload. Table names are fixed
    # literals (same convention as _inbox_author_over_quota); inbox items are
    # NOT deleted here — the node acks a merged inbox with its per-repo DELETE.
    marks = ",".join("?" for _ in repo_bis)
    by_repo = {}      # repo_bi -> {topic: [decrypted rows...]}
    merge_sync_by_repo = {}  # repo_bi -> published exact-OID merge receipts
    drain_ids = {}    # repo_bi -> {table: [row ids read]}, for exact deletes
    if repo_bis:
        now = int(Date.now())
        await d1_run(
            env,
            "UPDATE issue_inbox SET claimed_by_bi=?, claim_expires_at=? "
            f"WHERE repo_bi IN ({marks}) AND "
            "(claimed_by_bi='' OR claim_expires_at<=? OR claimed_by_bi=?)",
            issue_claimant_bi, now + ISSUE_INBOX_CLAIM_TTL_MS,
            *repo_bis, now, issue_claimant_bi,
        )
        for topic, table, ordered in (
                ("issues", "issue_inbox", True),
                ("pulls", "pull_inbox", True),
                ("discussions", "discussion_inbox", True),
                ("commits", "commit_inbox", True),
                ("agentPrompts", "agent_prompts", True),
                ("aboutUpdate", "about_inbox", False)):
            order = " ORDER BY id ASC" if ordered else ""
            id_col = "rowid AS drain_id" if table == "about_inbox" else "id AS drain_id"
            claim_filter = (
                " AND claimed_by_bi=?" if table == "issue_inbox" else "")
            table_rows = await d1_all(
                env,
                f"SELECT repo_bi, data, {id_col} FROM {table}"
                f" WHERE repo_bi IN ({marks})" + claim_filter + order,
                *repo_bis,
                *([issue_claimant_bi] if table == "issue_inbox" else []))
            for r in table_rows or []:
                owner_crypto = globals().get("security_control")
                sealed = (
                    owner_crypto.decode_owner_envelope(r.get("data"))
                    if table == "agent_prompts" and owner_crypto is not None
                    else None
                )
                if sealed:
                    routing = sealed.get("routing") or {}
                    item = {
                        "queueId": int(r.get("drain_id") or 0),
                        "agentId": int(routing.get("agentId") or 0),
                        "queuedAt": int(routing.get("queuedAt") or 0),
                        "encrypted": True,
                        "envelope": sealed["envelope"],
                    }
                elif table == "agent_prompts" and owner_crypto is not None:
                    # Production always enforces owner-sealed agent payloads.
                    # A legacy row cannot be safely decrypted by the relay; it
                    # is retained for an owner-run offline migration instead.
                    item = None
                else:
                    item = await decrypt_row(env, r.get("data"))
                if item:
                    # Carry the inbox row id so a node draining from /api/sync
                    # can ack exactly what it merged (DELETE ...?ids=), leaving
                    # any submission that landed mid-drain for the next sync
                    # instead of blanket-deleting it undelivered (adhoc #97).
                    drain_id = r.get("drain_id")
                    if drain_id is not None and topic in (
                            "issues", "pulls", "discussions", "commits"):
                        item["id"] = drain_id
                    by_repo.setdefault(r.get("repo_bi"), {}) \
                        .setdefault(topic, []).append(item)
                # Track the exact rows READ (even undecryptable ones — they
                # can never be delivered, so draining them is correct) so the
                # drain deletes below can't sweep away rows inserted while
                # this request was still decrypting (drop-undelivered race).
                # Owner-sealed prompts are acknowledged only after the desktop
                # decrypts and accepts them. Legacy prompts keep drain-on-read
                # compatibility; About updates are unchanged.
                if (table == "about_inbox"
                        or (table == "agent_prompts" and not sealed
                            and owner_crypto is None)):
                    drain_ids.setdefault(r.get("repo_bi"), {}) \
                        .setdefault(table, []).append(r.get("drain_id"))
        # A merge performed while the source-of-truth node was offline is a
        # durable relay job, not an ordinary PR event. Carry its exact,
        # already-validated public object IDs in the same signed sync response
        # so the owner node can reconcile the published mirror state later.
        # The selected mirror, actor, paths, and credentials never leave D1.
        merge_rows = await d1_all(
            env,
            "SELECT repo_bi,request_id,pull_number,result,updated_at "
            "FROM repo_merge_jobs "
            f"WHERE repo_bi IN ({marks}) AND status='succeeded' "
            "AND expires_at>? ORDER BY updated_at ASC",
            *repo_bis, now,
        )
        for merge_row in merge_rows or []:
            try:
                result = json.loads(str(merge_row.get("result") or ""))
            except Exception:
                continue
            request_id = clean_string(
                merge_row.get("request_id", ""), 80).strip()
            fields = {
                key: str(result.get(key) or "").strip().lower()
                for key in (
                    "baseBefore", "head", "pullsBefore",
                    "baseAfter", "pullsAfter",
                )
            }
            try:
                pull_number = int(merge_row.get("pull_number") or 0)
            except (TypeError, ValueError, OverflowError):
                continue
            if (
                result.get("ok") is not True
                or result.get("status") != "merged"
                or result.get("published") is not True
                or str(result.get("requestId") or "") != request_id
                or not HTTPS_MIRROR_MERGE_REQUEST_RE.fullmatch(request_id)
                or not 1 <= pull_number <= 999999999
                or any(
                    not re.fullmatch(
                        r"(?:[0-9a-f]{40}|[0-9a-f]{64})", oid)
                    for oid in fields.values()
                )
                or len({len(oid) for oid in fields.values()}) != 1
            ):
                continue
            merge_sync_by_repo.setdefault(
                merge_row.get("repo_bi"), []).append({
                    "requestId": request_id,
                    "pullNumber": pull_number,
                    **fields,
                })
    repos = []
    for row in rows:
        rec = await decrypt_row(env, row["data"])
        if not rec:
            continue
        repo_bi = row["key_bi"]
        pending = by_repo.get(repo_bi, {})
        entry = {
            "name": clean_string(rec.get("name", ""), 120),
            "owner": clean_string(rec.get("owner", owner), 120),
            # The relay's currently pinned state, so the node can detect pin
            # drift without fetching the whole catalog list.
            "stateHash": rec.get("stateHash", ""),
            "updatedAt": rec.get("updatedAt", ""),
            "source": rec.get("source", ""),
            "issues": pending.get("issues", []),
            "pulls": pending.get("pulls", []),
            "discussions": pending.get("discussions", []),
            "commits": pending.get("commits", []),
            "mirrorMerges": merge_sync_by_repo.get(repo_bi, []),
        }
        # Drain-on-read deletes target the EXACT rows this request read (by
        # id), never the whole repo_bi: a prompt/About edit inserted while
        # this request was decrypting must survive for the next sync instead
        # of being swept away undelivered.
        prompts = pending.get("agentPrompts", [])
        prompt_ids = drain_ids.get(repo_bi, {}).get("agent_prompts", [])
        if prompt_ids:
            await d1_run(
                env,
                "DELETE FROM agent_prompts WHERE id IN (%s)"
                % ",".join("?" for _ in prompt_ids),
                *prompt_ids)
        entry["agentPrompts"] = prompts
        if any(bool(p.get("encrypted")) for p in prompts
               if isinstance(p, dict)):
            entry["agentPromptAckPath"] = (
                "/api/repo/%s/%s/agents/ack" % (
                    entry.get("owner", owner), entry.get("name", "")))
        # Web About edits, drained on read like agent prompts: the node writes
        # the change into the repo's committed .forkmesh/info.json.
        abouts = pending.get("aboutUpdate", [])
        about_ids = drain_ids.get(repo_bi, {}).get("about_inbox", [])
        if abouts:
            entry["aboutUpdate"] = abouts[0]
        if about_ids:
            await d1_run(
                env,
                "DELETE FROM about_inbox WHERE rowid IN (%s)"
                % ",".join("?" for _ in about_ids),
                *about_ids)
        repos.append(entry)
    return json_response(
        {"ok": True, "serverTime": int(Date.now()), "repos": repos})


# --- Owner-only encryption control plane -----------------------------------

async def owner_encryption_keys_handler(env, request):
    """Register or revoke public recipient bundles for the signed-in owner.

    The private X25519/ML-KEM halves never cross this API. Platform
    administrators intentionally have no read or write override.
    """
    await ensure_schema(env)
    method = method_name(request)
    data = {}
    if method in ("POST", "DELETE"):
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
    account_bi, rec = await _account_session_record(env, request, data)
    actor = (rec.get("name", "") if rec else "").strip().lower()
    if not actor:
        return json_response({"error": "invalid_session"}, status=401)

    if method == "GET":
        rows = await d1_all(
            env,
            "SELECT key_id, public_bundle, created_at FROM "
            "owner_encryption_keys WHERE account_bi=? AND revoked_at=0 "
            "ORDER BY created_at DESC",
            account_bi,
        )
        keys = []
        for row in rows or []:
            try:
                bundle = json.loads(str(row.get("public_bundle") or ""))
            except Exception:
                continue
            valid = security_control.validate_owner_public_bundle(bundle)
            if valid and valid["kid"] == row.get("key_id"):
                keys.append({
                    "keyId": valid["kid"],
                    "publicBundle": {
                        "v": valid["v"],
                        "x25519": valid["x25519"],
                        "mlkem768": valid["mlkem768"],
                    },
                    "createdAt": int(row.get("created_at") or 0),
                })
        return json_response({
            "ok": True,
            "keys": keys,
            "custody": "owner-device-only",
            "privateKeysStored": False,
        }, cache_control="no-store")

    if method == "POST":
        valid = security_control.validate_owner_public_bundle(
            data.get("publicBundle"))
        if not valid:
            return json_response({"error": "invalid_public_bundle"}, status=400)
        now = int(Date.now())
        public_bundle = {
            "v": valid["v"],
            "x25519": valid["x25519"],
            "mlkem768": valid["mlkem768"],
        }
        await d1_run(
            env,
            "INSERT INTO owner_encryption_keys "
            "(account_bi, key_id, public_bundle, created_at, revoked_at) "
            "VALUES (?,?,?,?,0) ON CONFLICT(account_bi,key_id) DO UPDATE SET "
            "public_bundle=excluded.public_bundle, revoked_at=0",
            account_bi, valid["kid"],
            json.dumps(public_bundle, sort_keys=True, separators=(",", ":")),
            now,
        )
        await _audit_sensitive_action(
            env, actor, "owner_encryption_key.register", "account", actor,
            "success", {"keyId": valid["kid"], "publicOnly": True})
        return json_response({
            "ok": True,
            "keyId": valid["kid"],
            "custody": "owner-device-only",
            "privateKeysStored": False,
        }, status=201, cache_control="no-store")

    if method == "DELETE":
        key_id = clean_string(data.get("keyId", ""), 128)
        if not re.fullmatch(r"[A-Za-z0-9_-]{16,128}", key_id):
            return json_response({"error": "invalid_key_id"}, status=400)
        now = int(Date.now())
        await d1_run(
            env,
            "UPDATE owner_encryption_keys SET revoked_at=? "
            "WHERE account_bi=? AND key_id=?",
            now, account_bi, key_id,
        )
        # A policy still naming the revoked key remains strict and therefore
        # rejects new ciphertext until the owner rotates it; it never silently
        # falls back to Worker-readable plaintext.
        await _audit_sensitive_action(
            env, actor, "owner_encryption_key.revoke", "account", actor,
            "success", {"keyId": key_id})
        return json_response({"ok": True, "revoked": True},
                             cache_control="no-store")

    return json_response({"error": "method_not_allowed"}, status=405)


async def _repo_privacy_policy(env, owner, repo):
    repo_bi = await blind_index(env, owner + "/" + repo)
    try:
        row = await d1_first(
            env,
            "SELECT owner_bi, owner_key_id, require_agent_e2ee, "
            "require_mirror_encryption, updated_at FROM repo_privacy_policy "
            "WHERE repo_bi=?",
            repo_bi,
        )
    except Exception:
        # A control-plane outage must never reactivate a plaintext path.
        return {
            "repoBi": repo_bi,
            "ownerKeyId": "",
            "requireAgentE2EE": True,
            "requireMirrorEncryption": True,
            "policyUnavailable": True,
            "updatedAt": 0,
        }
    if not row:
        return {
            "repoBi": repo_bi,
            "ownerKeyId": "",
            # Confidentiality is a mandatory platform boundary, not an
            # owner-disableable preference. Until a recipient key is
            # registered, writes fail closed with an upgrade/setup response.
            "requireAgentE2EE": True,
            "requireMirrorEncryption": True,
            "policyUnavailable": False,
            "updatedAt": 0,
        }
    return {
        "repoBi": repo_bi,
        "ownerBi": str(row.get("owner_bi") or ""),
        "ownerKeyId": str(row.get("owner_key_id") or ""),
        # Old rows may contain zero from the pre-E2EE rollout. Do not let that
        # historical value reactivate a server-readable data path.
        "requireAgentE2EE": True,
        "requireMirrorEncryption": True,
        "policyUnavailable": False,
        "updatedAt": int(row.get("updated_at") or 0),
    }


async def repo_privacy_handler(env, request, owner, repo):
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST"):
        return json_response({"error": "method_not_allowed"}, status=405)
    data = {}
    if method == "POST":
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
    ok, err = await _authorize_owner_account(
        env, owner, data, request, allow_admin=False)
    if not ok:
        return err
    actor_bi, actor_rec = await _account_session_record(env, request, data)
    actor = (actor_rec.get("name", "") if actor_rec else "").strip().lower()
    policy_reader = globals().get("_repo_privacy_policy")
    policy = (
        await policy_reader(env, owner, repo)
        if callable(policy_reader) else {
            # A missing policy reader is a control-plane failure, never a
            # reason to reactivate relay-readable private data.
            "ownerKeyId": "", "requireAgentE2EE": True,
            "requireMirrorEncryption": True,
        }
    )

    if method == "POST":
        require_agent = True
        require_mirror = True
        key_id = clean_string(
            data.get("ownerKeyId", "") or policy.get("ownerKeyId", ""), 128)
        key = await d1_first(
            env,
            "SELECT 1 AS one FROM owner_encryption_keys "
            "WHERE account_bi=? AND key_id=? AND revoked_at=0",
            actor_bi, key_id,
        )
        if not key:
            return json_response(
                {"error": "active_owner_key_required"}, status=400)
        now = int(Date.now())
        await d1_run(
            env,
            "INSERT INTO repo_privacy_policy "
            "(repo_bi, owner_bi, owner_key_id, require_agent_e2ee, "
            "require_mirror_encryption, updated_at) VALUES (?,?,?,?,?,?) "
            "ON CONFLICT(repo_bi) DO UPDATE SET "
            "owner_bi=excluded.owner_bi, owner_key_id=excluded.owner_key_id, "
            "require_agent_e2ee=excluded.require_agent_e2ee, "
            "require_mirror_encryption=excluded.require_mirror_encryption, "
            "updated_at=excluded.updated_at",
            policy["repoBi"], actor_bi, key_id,
            1 if require_agent else 0, 1 if require_mirror else 0, now,
        )
        await _audit_sensitive_action(
            env, actor, "repository.privacy_policy", "repository",
            owner + "/" + repo, "success",
            {"agentE2EE": require_agent, "mirrorEncryption": require_mirror,
             "keyId": key_id})
        policy = await _repo_privacy_policy(env, owner, repo)

    return json_response({
        "ok": True,
        "ownerKeyId": policy.get("ownerKeyId", ""),
        "requireAgentE2EE": bool(policy.get("requireAgentE2EE")),
        "requireMirrorEncryption": bool(
            policy.get("requireMirrorEncryption")),
        "agentBoundary": "owner-only-e2ee",
        # This policy is an enforcement requirement/attestation gate. Actual
        # encrypted-at-rest mirror storage is performed and verified locally by
        # an upgraded Qt node; the Worker cannot inspect a node's disk.
        "mirrorBoundary": "client-encryption-required",
        "updatedAt": int(policy.get("updatedAt") or 0),
    }, cache_control="no-store")


# --- Agent-session sync (website "Agents" tab, adhoc #182) ------------------
#
# The desktop app runs Claude Code coding "agent" sessions per repo/issue.
# There's no existing sync of that state to the worker; these three routes
# add it end to end:
#   POST /agents        desktop -> worker: full-replace push of this repo's
#                        sessions, authenticated like an issue-inbox drain
#                        (_authorize_owner: ts+sig query params).
#   GET  /agents         desktop -> worker: drain (select + delete) any
#                        prompts the website queued for this repo's agents.
#   POST /agents/list    website -> worker: owner-password-gated read of the
#                        current session list (browsers hold no signing key).
#   POST /agents/<id>/prompt
#                        website -> worker: owner-password-gated, queue one
#                        text prompt for a specific running agent.
def _clean_agent_session(item):
    """Normalize one posted agent-session dict, or None if it's unusable."""
    if not isinstance(item, dict):
        return None
    try:
        agent_id = int(item.get("id", 0))
    except (TypeError, ValueError):
        return None
    if not agent_id:
        return None
    out = {"id": agent_id}
    try:
        out["issueNumber"] = int(item.get("issueNumber", 0) or 0)
    except (TypeError, ValueError):
        out["issueNumber"] = 0
    out["issueTitle"] = clean_string(item.get("issueTitle", ""), MAX_AGENT_TITLE)
    # Bounded run-log tail for the website's live transcript view (adhoc #259);
    # empty for pushes from older desktop builds that don't send it.
    out["transcript"] = clean_string(item.get("transcript", ""), MAX_AGENT_TRANSCRIPT)
    for field in ("status", "provider", "model", "branchName", "lastError"):
        out[field] = clean_string(item.get(field, ""), MAX_AGENT_STRING)
    for field in ("createdAtMs", "startedAtMs", "finishedAtMs", "numTurns", "durationMs"):
        try:
            out[field] = int(item.get(field, 0) or 0)
        except (TypeError, ValueError):
            out[field] = 0
    try:
        out["costUsd"] = float(item.get("costUsd", 0) or 0)
    except (TypeError, ValueError):
        out["costUsd"] = 0.0
    return out


async def agents_handler(env, request, owner, repo):
    await ensure_schema(env)
    method = method_name(request)
    repo_bi = await blind_index(env, owner + "/" + repo)
    policy_reader = globals().get("_repo_privacy_policy")
    policy = (
        await policy_reader(env, owner, repo)
        if callable(policy_reader) else {
            "ownerKeyId": "", "requireAgentE2EE": True,
            "requireMirrorEncryption": True,
        }
    )

    if method == "POST":
        if not await _authorize_owner(env, request, owner):
            return json_response({"error": "unauthorized"}, status=401)
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        if policy.get("requireAgentE2EE") and not policy.get("ownerKeyId"):
            return json_response({
                "error": "active_owner_key_required",
                "setupPath": "/api/security/owner-keys",
            }, status=428)
        encrypted_in = data.get("encryptedSessions")
        encrypted_rows = []
        if isinstance(encrypted_in, list):
            for item in encrypted_in[:MAX_AGENT_SESSIONS]:
                if not isinstance(item, dict):
                    return json_response(
                        {"error": "invalid_encrypted_session"}, status=400)
                try:
                    agent_id = int(item.get("id", 0))
                except (TypeError, ValueError):
                    agent_id = 0
                owner_crypto = globals().get("security_control")
                envelope = (
                    owner_crypto.validate_owner_envelope(item.get("envelope"))
                    if owner_crypto is not None else None)
                if not agent_id or not envelope:
                    return json_response(
                        {"error": "invalid_encrypted_session"}, status=400)
                required_kid = policy.get("ownerKeyId", "")
                envelope_kid = owner_crypto.owner_envelope_key_id(envelope)
                if required_kid and envelope_kid != required_kid:
                    return json_response(
                        {"error": "wrong_owner_key",
                         "requiredKeyId": required_kid},
                        status=409)
                encoded = owner_crypto.encode_owner_envelope(
                    envelope, {"agentId": agent_id})
                encrypted_rows.append((str(agent_id), encoded))
        if policy.get("requireAgentE2EE") and not isinstance(encrypted_in, list):
            return json_response(
                {
                    "error": "owner_encryption_required",
                    "requiredKeyId": policy.get("ownerKeyId", ""),
                },
                status=426,
            )
        if isinstance(encrypted_in, list):
            # Full replacement is safe because every row remains opaque to the
            # relay and its administrators. Duplicate ids keep the last entry.
            by_id = {agent_id: encoded for agent_id, encoded in encrypted_rows}
            encrypted_rows = list(by_id.items())
            digest = hashlib.sha256(
                "\n".join(encoded for _, encoded in encrypted_rows).encode()
            ).hexdigest()
            if _AGENT_PUSH_DIGESTS.get(repo_bi) == digest:
                return json_response({
                    "ok": True,
                    "unchanged": True,
                    "privacyBoundary": "owner-only-e2ee",
                })
            await d1_run(env, "DELETE FROM repo_agents WHERE repo_bi=?", repo_bi)
            now = int(Date.now())
            for start in range(0, len(encrypted_rows), 20):
                chunk = encrypted_rows[start:start + 20]
                placeholders = ",".join("(?,?,?,?)" for _ in chunk)
                args = []
                for agent_id, encoded in chunk:
                    args.extend((repo_bi, agent_id, encoded, now))
                if chunk:
                    await d1_run(
                        env,
                        "INSERT INTO repo_agents "
                        "(repo_bi, agent_id, data, updated_at) VALUES "
                        + placeholders,
                        *args)
            _AGENT_PUSH_DIGESTS[repo_bi] = digest
            if len(_AGENT_PUSH_DIGESTS) > 2000:
                _AGENT_PUSH_DIGESTS.clear()
            return json_response({
                "ok": True,
                "privacyBoundary": "owner-only-e2ee",
                "serverCanDecrypt": False,
            })

        sessions_in = data.get("sessions")
        if not isinstance(sessions_in, list):
            sessions_in = []
        # Cap to the most recent MAX_AGENT_SESSIONS entries rather than
        # rejecting the whole push outright (same truncate-not-reject
        # convention as the labels/assignees lists in issues_handler).
        sessions = [s for s in
                    (_clean_agent_session(item) for item in sessions_in[:MAX_AGENT_SESSIONS]) if s]
        # Dedupe by id, keeping the last occurrence: repo_agents is keyed on
        # (repo_bi, agent_id), so a payload with a repeated id would otherwise
        # violate that primary key on the second INSERT below.
        by_id = {}
        for session in sessions:
            by_id[session["id"]] = session
        sessions = list(by_id.values())
        # No-op short-circuit: the desktop's 30s safety-net timer mostly
        # re-pushes an identical snapshot. Re-encrypting and rewriting up to
        # MAX_AGENT_SESSIONS rows (hundreds of AES-GCM ops + inserts) for a
        # byte-identical payload was the single strongest CPU spike in the
        # 2026-07-11 free-plan overload. The digest memo is per-isolate: a
        # cold isolate rewrites once, then skips.
        digest = hashlib.sha256(
            json.dumps(sessions, sort_keys=True,
                       separators=(",", ":")).encode()).hexdigest()
        if _AGENT_PUSH_DIGESTS.get(repo_bi) == digest:
            return json_response({"ok": True, "unchanged": True})
        # Full-replace semantics: the desktop always pushes its whole current
        # view of this repo's sessions, so the stored set is exactly that.
        await d1_run(env, "DELETE FROM repo_agents WHERE repo_bi=?", repo_bi)
        now = int(Date.now())
        # Multi-row INSERT (chunked under D1's bound-parameter limit) instead
        # of one awaited roundtrip per session.
        encrypted = []
        for session in sessions:
            encrypted.append(
                (str(session["id"]), await encrypt_row(env, session)))
        for start in range(0, len(encrypted), 20):
            chunk = encrypted[start:start + 20]
            placeholders = ",".join("(?,?,?,?)" for _ in chunk)
            args = []
            for agent_id, enc in chunk:
                args.extend((repo_bi, agent_id, enc, now))
            await d1_run(
                env,
                "INSERT INTO repo_agents (repo_bi, agent_id, data, updated_at)"
                " VALUES " + placeholders,
                *args)
        _AGENT_PUSH_DIGESTS[repo_bi] = digest
        if len(_AGENT_PUSH_DIGESTS) > 2000:
            _AGENT_PUSH_DIGESTS.clear()
        # Keep the legacy response shape for older Qt nodes. The privacy
        # boundary is advertised by the policy/list endpoints; adding fields
        # here broke clients that compare this acknowledgement exactly.
        return json_response({"ok": True})

    if method == "GET":
        if not await _authorize_owner(env, request, owner):
            return json_response({"error": "unauthorized"}, status=401)
        if policy.get("requireAgentE2EE") and not policy.get("ownerKeyId"):
            return json_response({
                "error": "active_owner_key_required",
                "setupPath": "/api/security/owner-keys",
            }, status=428)
        rows = await d1_all(
            env,
            "SELECT id, data FROM agent_prompts WHERE repo_bi=? ORDER BY id ASC",
            repo_bi,
        )
        prompts = []
        encrypted_prompts = []
        legacy_rows = []
        legacy_held = 0
        for row in rows or []:
            owner_crypto = globals().get("security_control")
            sealed = (
                owner_crypto.decode_owner_envelope(row.get("data"))
                if owner_crypto is not None else None)
            if sealed:
                routing = sealed.get("routing") or {}
                encrypted_prompts.append({
                    "queueId": int(row.get("id") or 0),
                    "agentId": int(routing.get("agentId") or 0),
                    "queuedAt": int(routing.get("queuedAt") or 0),
                    "envelope": sealed["envelope"],
                })
                continue
            if policy.get("requireAgentE2EE"):
                # Never decrypt pre-boundary prompt rows in the Worker. They
                # remain held for an explicit offline owner migration.
                legacy_held += 1
                continue
            rec = await decrypt_row(env, row.get("data"))
            if rec:
                rec["queueId"] = int(row.get("id") or 0)
                prompts.append(rec)
            legacy_rows.append(row)
        # Legacy clients keep drain-on-read compatibility. Owner-sealed prompts
        # require an explicit ack after local decryption, so a wrong/revoked key
        # cannot destroy the only queued ciphertext.
        if legacy_rows:
            await d1_run(
                env,
                "DELETE FROM agent_prompts WHERE id IN (%s)"
                % ",".join("?" for _ in legacy_rows),
                *[r["id"] for r in legacy_rows])
        return json_response({
            "ok": True,
            "prompts": prompts,
            "encryptedPrompts": encrypted_prompts,
            "ackPath": "/api/repo/%s/%s/agents/ack" % (owner, repo),
            "legacyRowsHeldForOwnerMigration": legacy_held,
            "privacyBoundary": (
                "owner-only-e2ee" if policy.get("requireAgentE2EE")
                else "owner-only-e2ee" if encrypted_prompts and not prompts
                else "mixed" if encrypted_prompts else "legacy-server-readable"),
            "serverCanDecryptEncryptedPrompts": False,
        })

    return json_response({"error": "method_not_allowed"}, status=405)


async def agents_list_handler(env, request, owner, repo):
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    ok, err = await _authorize_owner_account(
        env, owner, data, request, allow_admin=False)
    if not ok:
        return err
    policy_reader = globals().get("_repo_privacy_policy")
    policy = (
        await policy_reader(env, owner, repo)
        if callable(policy_reader) else {
            "ownerKeyId": "", "requireAgentE2EE": True,
            "requireMirrorEncryption": True,
        }
    )
    repo_bi = await blind_index(env, owner + "/" + repo)
    rows = await d1_all(
        env, "SELECT data FROM repo_agents WHERE repo_bi=? ORDER BY updated_at DESC",
        repo_bi,
    )
    agents = []
    encrypted_agents = []
    legacy_held = 0
    for row in rows or []:
        owner_crypto = globals().get("security_control")
        sealed = (
            owner_crypto.decode_owner_envelope(row.get("data"))
            if owner_crypto is not None else None)
        if sealed:
            routing = sealed.get("routing") or {}
            encrypted_agents.append({
                "id": int(routing.get("agentId") or 0),
                "envelope": sealed["envelope"],
            })
            continue
        if policy.get("requireAgentE2EE"):
            legacy_held += 1
            continue
        rec = await decrypt_row(env, row.get("data"))
        if rec:
            agents.append(rec)
    # The transcript tail can be large; keep it out of the list payload and let
    # the detail page fetch just the selected agent's transcript on demand.
    for rec in agents:
        rec.pop("transcript", None)
    return json_response({
        "ok": True,
        "agents": agents,
        "encryptedAgents": encrypted_agents,
        "legacyRowsHeldForOwnerMigration": legacy_held,
        "privacyBoundary": (
            "owner-only-e2ee" if policy.get("requireAgentE2EE")
            else "owner-only-e2ee" if encrypted_agents and not agents
            else "mixed" if encrypted_agents else "legacy-server-readable"),
        "serverCanDecryptEncryptedAgents": False,
    }, cache_control="no-store")


async def agents_transcript_handler(env, request, owner, repo, agent_id):
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    ok, err = await _authorize_owner_account(
        env, owner, data, request, allow_admin=False)
    if not ok:
        return err
    policy_reader = globals().get("_repo_privacy_policy")
    policy = (
        await policy_reader(env, owner, repo)
        if callable(policy_reader) else {
            "ownerKeyId": "", "requireAgentE2EE": True,
            "requireMirrorEncryption": True,
        }
    )
    repo_bi = await blind_index(env, owner + "/" + repo)
    row = await d1_first(
        env, "SELECT data FROM repo_agents WHERE repo_bi=? AND agent_id=?",
        repo_bi, str(agent_id),
    )
    owner_crypto = globals().get("security_control")
    sealed = (
        owner_crypto.decode_owner_envelope(row.get("data"))
        if row and owner_crypto is not None else None)
    if sealed:
        return json_response({
            "ok": True,
            "encrypted": True,
            "envelope": sealed["envelope"],
            "privacyBoundary": "owner-only-e2ee",
            "serverCanDecrypt": False,
        }, cache_control="no-store")
    if policy.get("requireAgentE2EE") and row:
        return json_response({
            "error": "legacy_data_unavailable",
            "migration": "owner-device-required",
        }, status=410, cache_control="no-store")
    rec = await decrypt_row(env, row["data"]) if row else None
    if not rec:
        return json_response({"error": "not_found"}, status=404)
    return json_response({
        "ok": True,
        "transcript": rec.get("transcript", ""),
        "status": rec.get("status", ""),
        "privacyBoundary": "legacy-server-readable",
        "serverCanDecrypt": True,
    })


async def agents_prompt_handler(env, request, owner, repo, agent_id):
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    ok, err = await _authorize_owner_account(
        env, owner, data, request, allow_admin=False)
    if not ok:
        return err
    policy_reader = globals().get("_repo_privacy_policy")
    policy = (
        await policy_reader(env, owner, repo)
        if callable(policy_reader) else {
            "ownerKeyId": "", "requireAgentE2EE": True,
            "requireMirrorEncryption": True,
        }
    )
    owner_crypto = globals().get("security_control")
    if policy.get("requireAgentE2EE") and not policy.get("ownerKeyId"):
        return json_response({
            "error": "active_owner_key_required",
            "setupPath": "/api/security/owner-keys",
        }, status=428)
    envelope = (
        owner_crypto.validate_owner_envelope(data.get("envelope"))
        if owner_crypto is not None else None)
    if envelope:
        required_kid = policy.get("ownerKeyId", "")
        envelope_kid = owner_crypto.owner_envelope_key_id(envelope)
        if required_kid and envelope_kid != required_kid:
            return json_response(
                {"error": "wrong_owner_key", "requiredKeyId": required_kid},
                status=409)
        repo_bi = await blind_index(env, owner + "/" + repo)
        count = await d1_first(
            env,
            "SELECT COUNT(*) AS c FROM agent_prompts WHERE repo_bi=?",
            repo_bi,
        )
        if count and count.get("c", 0) >= MAX_PENDING_AGENT_PROMPTS:
            return json_response({"error": "prompt_queue_full"}, status=429)
        now = int(Date.now())
        encoded = owner_crypto.encode_owner_envelope(
            envelope, {"agentId": agent_id, "queuedAt": now})
        await d1_run(
            env,
            "INSERT INTO agent_prompts (repo_bi, agent_id, data, queued_at) "
            "VALUES (?,?,?,?)",
            repo_bi, agent_id, encoded, now,
        )
        await notify_repo_host(env, owner, repo, "agents")
        return json_response({
            "ok": True,
            "privacyBoundary": "owner-only-e2ee",
            "serverCanDecrypt": False,
        })
    if policy.get("requireAgentE2EE"):
        return json_response(
            {
                "error": "owner_encryption_required",
                "requiredKeyId": policy.get("ownerKeyId", ""),
            },
            status=426,
        )
    text = str(data.get("text", "") or "").strip()
    if not text:
        return json_response({"error": "text_required"}, status=400)
    if len(text) > MAX_AGENT_PROMPT_TEXT:
        return json_response({"error": "text_too_long"}, status=400)
    repo_bi = await blind_index(env, owner + "/" + repo)
    count = await d1_first(
        env, "SELECT COUNT(*) AS c FROM agent_prompts WHERE repo_bi=?", repo_bi
    )
    if count and count.get("c", 0) >= MAX_PENDING_AGENT_PROMPTS:
        return json_response({"error": "prompt_queue_full"}, status=429)
    now = int(Date.now())
    item = {"agentId": agent_id, "text": text, "queuedAt": now}
    # Optional agent-provider choice from the website's top-of-list composer
    # (adhoc #271): only meaningful when starting a brand-new agent, and only a
    # known provider is honored — else the node falls back to its own default.
    provider_in = clean_string(data.get("provider", ""), 40)
    if provider_in in ("claude-code", "claude-api", "openai"):
        item["provider"] = provider_in
    # Optional agent-model choice (adhoc #276): lets the owner choose which
    # Claude model the agent uses (e.g. "claude-opus-4-8", "claude-sonnet-4-6",
    # "claude-haiku-4-5", "fable-5"). Only meaningful when starting a brand-new
    # agent, and empty leaves the provider's own default in place.
    model_in = clean_string(data.get("model", ""), 60)
    if model_in:
        item["model"] = model_in
    # Optional pasted/attached screenshots (adhoc #78): data: URLs the node
    # writes into the agent's working tree so the agent can see them. Only
    # meaningful when starting a brand-new agent; bounded in count and size.
    images_in = data.get("images", [])
    if isinstance(images_in, list) and images_in:
        images = []
        total = 0
        for entry in images_in:
            if len(images) >= MAX_AGENT_PROMPT_IMAGES:
                break
            src = entry if isinstance(entry, str) else ""
            if not src.startswith("data:image/"):
                continue
            if len(src) > MAX_AGENT_PROMPT_IMAGE_BYTES:
                return json_response({"error": "image_too_large"}, status=400)
            total += len(src)
            if total > MAX_AGENT_PROMPT_IMAGES_TOTAL_BYTES:
                return json_response({"error": "images_too_large"}, status=400)
            images.append(src)
        if images:
            item["images"] = images
    await d1_run(
        env,
        "INSERT INTO agent_prompts (repo_bi, agent_id, data, queued_at) "
        "VALUES (?,?,?,?)",
        repo_bi, agent_id, await encrypt_row(env, item), now,
    )
    await notify_repo_host(env, owner, repo, "agents")
    return json_response({"ok": True})


async def agents_ack_handler(env, request, owner, repo):
    """Delete only owner-sealed prompts accepted by the owner's local client."""
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    if not await _authorize_owner(env, request, owner):
        return json_response({"error": "unauthorized"}, status=401)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    raw_ids = data.get("queueIds")
    if not isinstance(raw_ids, list):
        return json_response({"error": "queue_ids_required"}, status=400)
    queue_ids = []
    for value in raw_ids[:MAX_PENDING_AGENT_PROMPTS]:
        try:
            value = int(value)
        except (TypeError, ValueError):
            continue
        if value > 0 and value not in queue_ids:
            queue_ids.append(value)
    if not queue_ids:
        return json_response({"ok": True, "acknowledged": 0})
    repo_bi = await blind_index(env, owner + "/" + repo)
    rows = await d1_all(
        env,
        "SELECT id, data FROM agent_prompts WHERE repo_bi=? AND id IN (%s)"
        % ",".join("?" for _ in queue_ids),
        repo_bi, *queue_ids,
    )
    sealed_ids = [
        int(row.get("id") or 0) for row in rows or []
        if (globals().get("security_control") is not None
            and globals()["security_control"].decode_owner_envelope(
                row.get("data")))
    ]
    if sealed_ids:
        await d1_run(
            env,
            "DELETE FROM agent_prompts WHERE repo_bi=? AND id IN (%s)"
            % ",".join("?" for _ in sealed_ids),
            repo_bi, *sealed_ids,
        )
    return json_response({"ok": True, "acknowledged": len(sealed_ids)})


# --- Organization-scoped Claude/Codex bots ---------------------------------
#
# This is intentionally NOT an authorization shortcut into repo_agents. Those
# rows remain owner-device E2EE. Organization bots have their own encrypted-at-
# rest session/job tables, are visible and controllable only by current members
# of the organization's Engineering team, and execute only after the selected
# mirror runs a tool-free Claude Haiku safety preflight.
ORG_AGENT_PROVIDERS = ("claude-code", "codex")
ORG_AGENT_MODEL_ALIASES = {
    "claude-code": {
        "haiku": "claude-haiku-4-5",
        "sonnet": "claude-sonnet-4-6",
        "opus": "claude-opus-4-8",
        "fable": "claude-fable-5",
    },
    "codex": {
        "sol": "gpt-5.6-sol",
        "luna": "gpt-5.6-luna",
        "terra": "gpt-5.6-terra",
    },
}
ORG_AGENT_SESSION_STATUSES = (
    "security_pending", "queued", "running", "completed", "failed", "rejected",
)
ORG_AGENT_MAX_PROMPT = 8000
ORG_AGENT_MAX_SESSIONS = 50
ORG_AGENT_MAX_HISTORY = 80
ORG_AGENT_JOB_LEASE_MS = 2 * 60 * 1000


async def _org_agent_member_context(env, request, org, repo, data=None):
    org = clean_string(org, MAX_NODE_NAME).strip().lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT).strip().lower()
    if not valid_node_name(org) or not safe_segment(repo):
        return None, json_response({"error": "not_found"}, status=404)
    org_bi, org_row = await _org_row(env, org)
    if not org_row:
        return None, json_response({"error": "not_found"}, status=404)
    account_bi, account = await _account_session_record(
        env, request, data if isinstance(data, dict) else None)
    actor = clean_string(
        (account or {}).get("name"), MAX_NODE_NAME).strip().lower()
    if not account_bi or not actor:
        return None, json_response({"error": "invalid_session"}, status=401)
    role = await _org_role(env, org_bi, actor)
    if role not in ORG_ROLES:
        return None, json_response({"error": "forbidden"}, status=403)
    engineering = await d1_first(
        env,
        "SELECT 1 AS one FROM org_team_members "
        "WHERE org_bi=? AND team='engineering' AND member_bi=?",
        org_bi, str(account_bi),
    )
    if not engineering:
        return None, json_response(
            {
                "error": "engineering_team_required",
                "requiredTeam": "engineering",
            },
            status=403,
            cache_control="no-store",
        )
    linked = await d1_first(
        env,
        "SELECT node_owner FROM org_repos WHERE org_bi=? AND repo=?",
        org_bi, repo,
    )
    node_owner = clean_string(
        (linked or {}).get("node_owner"), MAX_NODE_NAME).strip().lower()
    if not valid_node_name(node_owner):
        return None, json_response({"error": "repository_not_linked"}, status=404)
    return {
        "org": org,
        "orgBi": org_bi,
        "repo": repo,
        "nodeOwner": node_owner,
        "accountBi": str(account_bi),
        "actor": actor,
        "role": role,
    }, None


async def _org_agent_target_mirror(
    env, context, provider, preferred_node="",
):
    now = int(Date.now())
    rows = await _decrypted_public_catalog(env, now)
    records = [
        row.get("data") or {}
        for row in rows or []
        if not row.get("is_private")
    ]
    target = next((
        record for record in records
        if (
            str(record.get("owner") or "").strip().lower()
            == context["nodeOwner"].lower()
            and str(record.get("name") or "").strip().lower()
            == context["repo"].lower()
        )
    ), None)
    if not target:
        return ""
    eligible = agent_provider_mirror_candidates(
        records,
        target,
        context["nodeOwner"],
        provider,
        now,
        10 * 60 * 1000,
    )
    preferred = clean_string(
        preferred_node, MAX_NODE_NAME).strip().lower()
    if preferred:
        return (
            preferred
            if valid_node_name(preferred) and preferred in eligible
            else ""
        )
    if eligible and valid_node_name(eligible[0]):
        return eligible[0]
    # A source node is not described as a headless mirror. Fail closed rather
    # than silently running an org member's prompt on a different trust class.
    return ""


def _org_agent_info_projection(value):
    value = value if isinstance(value, dict) else {}
    text_fields = {
        "owner": MAX_NODE_NAME,
        "repository": MAX_REPO_SEGMENT,
        "provider": 40,
        "model": 120,
        "mode": 80,
        "status": 32,
        "branchName": 240,
        "baseRef": 64,
        "baseBranch": 240,
        "lastError": 1000,
    }
    output = {
        key: clean_string(value.get(key), maximum)
        for key, maximum in text_fields.items()
    }
    for key in (
        "issueNumber", "prNumber", "promptTokens", "completionTokens",
        "totalTokens", "contextTokens", "contextWindow", "maxOutputTokens",
        "estimatedCredits", "numTurns", "durationMs", "createdAt",
        "startedAt", "finishedAt", "mergedAt",
    ):
        try:
            number = int(value.get(key) or 0)
        except (TypeError, ValueError):
            number = 0
        output[key] = max(0, min(number, 2 ** 53 - 1))
    try:
        cost = float(value.get("costUsd") or 0)
    except (TypeError, ValueError):
        cost = 0
    output["costUsd"] = max(0, min(cost, 1_000_000))
    output["createPr"] = value.get("createPr") is True
    output["merged"] = value.get("merged") is True
    return output


def _org_agent_availability_projection(value):
    value = value if isinstance(value, dict) else {}
    login_state = clean_string(value.get("loginState"), 20).lower()
    if login_state not in ("available", "missing", "unknown"):
        login_state = "unknown"
    return {
        "provider": clean_string(value.get("provider"), 40),
        "binaryFound": value.get("binaryFound") is True,
        "loginState": login_state,
        "message": clean_string(value.get("message"), 400),
        "credentialSource": clean_string(
            value.get("credentialSource"), 60),
    }


def _org_agent_session_projection(row, record):
    history = (
        record.get("history") if isinstance(record.get("history"), list) else []
    )
    status = str(row.get("status") or "")
    updated_at = int(row.get("updated_at") or 0)
    age_ms = max(0, int(Date.now()) - updated_at) if updated_at else 0
    availability = _org_agent_availability_projection(
        record.get("availability"))
    agent_info = _org_agent_info_projection(record.get("agentInfo"))
    diagnostic = {
        "code": "waiting_for_mirror",
        "level": "pending",
        "message": "Waiting for the selected mirror to claim this job.",
    }
    if (
        status == "security_pending"
        and int(record.get("localAgentId") or 0) <= 0
        and not availability.get("message")
        and age_ms >= 90 * 1000
    ):
        diagnostic = {
            "code": "mirror_not_claiming_jobs",
            "level": "attention",
            "message": (
                "The selected mirror has not claimed this job. Confirm its Qt "
                "app is running, this repository is published locally, "
                "website agent publishing is enabled, and the node can sign "
                "for the mirror account."
            ),
        }
    elif (
        availability.get("binaryFound") is False
        or availability.get("loginState") == "missing"
    ):
        diagnostic = {
            "code": (
                "provider_binary_missing"
                if availability.get("binaryFound") is False
                else "provider_credential_missing"
            ),
            "level": "attention",
            "message": availability.get("message") or (
                "The selected mirror is missing the provider runtime or "
                "supported headless authorization."
            ),
        }
    elif status in ("failed", "rejected"):
        diagnostic = {
            "code": "agent_" + status,
            "level": "attention",
            "message": (
                agent_info.get("lastError")
                or str((record.get("security") or {}).get("reason") or "")
                or "The mirror reported that this session needs attention."
            ),
        }
    elif status in ("running", "queued", "completed"):
        diagnostic = {
            "code": status,
            "level": "ok" if status == "completed" else "active",
            "message": {
                "running": "The mirror is running this agent session.",
                "queued": "The mirror accepted the job and is preparing it.",
                "completed": "The mirror completed this agent session.",
            }[status],
        }
    return {
        "id": str(row.get("session_id") or ""),
        "org": str(record.get("org") or ""),
        "repo": str(row.get("repo") or ""),
        "provider": str(row.get("provider") or ""),
        "status": status,
        "displayStatus": (
            "attention"
            if diagnostic.get("level") == "attention"
            else status
        ),
        "targetNode": str(row.get("target_node") or ""),
        "title": clean_string(record.get("title"), 160),
        "createdBy": clean_string(record.get("createdBy"), MAX_NODE_NAME),
        "createdAt": int(row.get("created_at") or 0),
        "updatedAt": updated_at,
        "completedAt": int(row.get("completed_at") or 0),
        "localAgentId": int(record.get("localAgentId") or 0),
        "taskKey": clean_string(record.get("taskKey"), 96),
        "issueNumber": max(0, min(
            int(record.get("issueNumber") or 0), 10_000_000)),
        "requestedModel": clean_string(record.get("requestedModel"), 60),
        "history": history[-ORG_AGENT_MAX_HISTORY:],
        "security": record.get("security") or {},
        "agentInfo": agent_info,
        "availability": availability,
        "diagnostic": diagnostic,
    }


async def _org_agent_session_row(env, context, session_id):
    row = await d1_first(
        env,
        "SELECT session_id,org_bi,repo,target_node,provider,status,data,"
        "created_at,updated_at,completed_at FROM org_agent_sessions "
        "WHERE session_id=? AND org_bi=? AND repo=?",
        session_id, context["orgBi"], context["repo"],
    )
    if not row:
        return None, None
    record = await decrypt_row(env, row.get("data"))
    if (
        not isinstance(record, dict)
        or str(record.get("org") or "").lower() != context["org"]
        or str(record.get("repo") or "").lower() != context["repo"]
    ):
        return None, None
    return row, record


async def org_agent_bots_handler(env, request, org, repo):
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST"):
        return json_response({"error": "method_not_allowed"}, status=405)
    data = {}
    if method == "POST":
        if not _request_same_origin(request):
            return json_response({"error": "origin_not_allowed"}, status=403)
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
    context, error = await _org_agent_member_context(
        env, request, org, repo, data)
    if error:
        return error
    if method == "GET":
        rows = await d1_all(
            env,
            "SELECT session_id,org_bi,repo,target_node,provider,status,data,"
            "created_at,updated_at,completed_at FROM org_agent_sessions "
            "WHERE org_bi=? AND repo=? ORDER BY updated_at DESC LIMIT ?",
            context["orgBi"], context["repo"], ORG_AGENT_MAX_SESSIONS,
        )
        sessions = []
        for row in rows or []:
            record = await decrypt_row(env, row.get("data"))
            if (
                isinstance(record, dict)
                and str(record.get("org") or "").lower() == context["org"]
                and str(record.get("repo") or "").lower() == context["repo"]
            ):
                sessions.append(_org_agent_session_projection(row, record))
        return json_response({
            "ok": True,
            "organization": context["org"],
            "repository": context["repo"],
            "memberRole": context["role"],
            "requiredTeam": "engineering",
            "engineeringAccess": True,
            "providers": list(ORG_AGENT_PROVIDERS),
            "models": {
                provider: list(ORG_AGENT_MODEL_ALIASES[provider].keys())
                for provider in ORG_AGENT_PROVIDERS
            },
            "sessions": sessions,
            "privacyBoundary": "engineering-team-encrypted-at-rest",
            "securityGate": "claude-haiku-tool-free-fail-closed",
        }, cache_control="no-store")

    provider = clean_string(data.get("provider"), 40).strip().lower()
    prompt = clean_string(data.get("prompt"), ORG_AGENT_MAX_PROMPT).strip()
    if provider not in ORG_AGENT_PROVIDERS:
        return json_response({"error": "invalid_provider"}, status=400)
    model_alias = clean_string(data.get("model"), 30).strip().lower()
    model = ORG_AGENT_MODEL_ALIASES.get(provider, {}).get(model_alias)
    if model_alias and not model:
        return json_response({"error": "invalid_model"}, status=400)
    if not prompt:
        return json_response({"error": "prompt_required"}, status=400)
    preferred_node = clean_string(
        data.get("targetNode"), MAX_NODE_NAME).strip().lower()
    if preferred_node and not valid_node_name(preferred_node):
        return json_response({"error": "invalid_target_node"}, status=400)
    target_node = await _org_agent_target_mirror(
        env, context, provider, preferred_node)
    if not target_node:
        return json_response(
            {"error": "no_eligible_headless_mirror"}, status=503,
            extra_headers=EXPECTED_DEGRADED_HEADERS)
    now = int(Date.now())
    session_id = _ap_uuid()
    task_key = clean_string(data.get("taskKey"), 96).strip()
    if task_key and not re.fullmatch(
        r"(?:task:[a-z0-9-]{1,48}|"
        r"issue:[a-z0-9-]{1,40}/[a-z0-9._-]{1,60}#[1-9][0-9]{0,8})",
        task_key,
    ):
        return json_response({"error": "invalid_task_key"}, status=400)
    try:
        issue_number = int(data.get("issueNumber") or 0)
    except (TypeError, ValueError):
        issue_number = 0
    if issue_number < 0 or issue_number > 10_000_000:
        return json_response({"error": "invalid_issue_number"}, status=400)
    if issue_number and task_key != (
        "issue:%s/%s#%d" % (context["org"], context["repo"], issue_number)
    ):
        return json_response({"error": "invalid_issue_task_key"}, status=400)
    title = clean_string(
        data.get("title") or prompt.split("\n", 1)[0], 160).strip()
    record = {
        "org": context["org"],
        "repo": context["repo"],
        "nodeOwner": context["nodeOwner"],
        "targetNode": target_node,
        "provider": provider,
        "title": title,
        "createdBy": context["actor"],
        "localAgentId": 0,
        "taskKey": task_key,
        "issueNumber": issue_number,
        "requestedModel": model or "",
        "requestedModelAlias": model_alias,
        "security": {"state": "pending", "model": "haiku"},
        "history": [{
            "role": "user",
            "author": context["actor"],
            "text": prompt,
            "at": now,
            "state": "security_pending",
        }],
    }
    job = {
        "kind": "start",
        "sessionId": session_id,
        "organization": context["org"],
        "repositoryOwner": target_node,
        "repositoryName": context["repo"],
        "provider": provider,
        "prompt": prompt,
        "taskKey": task_key,
        "issueNumber": issue_number,
        "model": model or "",
        "requestedBy": context["actor"],
        "securityCheck": {
            "provider": "claude-code",
            "model": "haiku",
            "tools": False,
            "failClosed": True,
        },
    }
    await d1_run(
        env,
        "INSERT INTO org_agent_sessions "
        "(session_id,org_bi,repo,target_node,provider,status,created_by_bi,"
        "data,created_at,updated_at,completed_at) VALUES (?,?,?,?,?,?,?,?,?,?,0)",
        session_id, context["orgBi"], context["repo"], target_node, provider,
        "security_pending", context["accountBi"],
        await encrypt_row(env, record), now, now,
    )
    await d1_run(
        env,
        "INSERT INTO org_agent_jobs "
        "(session_id,org_bi,target_node,repo,provider,status,lease_id,data,"
        "created_at,updated_at) VALUES (?,?,?,?,?,'queued','',?,?,?)",
        session_id, context["orgBi"], target_node, context["repo"], provider,
        await encrypt_row(env, job), now, now,
    )
    await _audit_sensitive_action(
        env, context["actor"], "organization.agent_start",
        "organization_agent", context["org"] + "/" + context["repo"] +
        "/" + session_id, "success",
        {
            "provider": provider,
            "model": model or "provider-default",
            "issueNumber": issue_number,
            "targetNode": target_node,
        })
    await notify_repo_host(env, target_node, context["repo"], "org-agents")
    return json_response({
        "ok": True,
        "session": _org_agent_session_projection({
            "session_id": session_id,
            "repo": context["repo"],
            "target_node": target_node,
            "provider": provider,
            "status": "security_pending",
            "created_at": now,
            "updated_at": now,
            "completed_at": 0,
        }, record),
    }, status=202, cache_control="no-store")


async def org_agent_bot_handler(env, request, org, repo, session_id):
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST"):
        return json_response({"error": "method_not_allowed"}, status=405)
    data = {}
    if method == "POST":
        if not _request_same_origin(request):
            return json_response({"error": "origin_not_allowed"}, status=403)
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
    context, error = await _org_agent_member_context(
        env, request, org, repo, data)
    if error:
        return error
    row, record = await _org_agent_session_row(
        env, context, clean_string(session_id, 64))
    if not row:
        return json_response({"error": "not_found"}, status=404)
    if method == "GET":
        return json_response({
            "ok": True,
            "session": _org_agent_session_projection(row, record),
        }, cache_control="no-store")
    if str(row.get("status") or "") not in ("running", "queued"):
        return json_response({"error": "session_not_promptable"}, status=409)
    local_agent_id = int(record.get("localAgentId") or 0)
    if local_agent_id <= 0:
        return json_response({"error": "agent_not_ready"}, status=409)
    prompt = clean_string(data.get("prompt"), ORG_AGENT_MAX_PROMPT).strip()
    if not prompt:
        return json_response({"error": "prompt_required"}, status=400)
    now = int(Date.now())
    history = record.get("history")
    if not isinstance(history, list):
        history = []
    history.append({
        "role": "user",
        "author": context["actor"],
        "text": prompt,
        "at": now,
        "state": "security_pending",
    })
    record["history"] = history[-ORG_AGENT_MAX_HISTORY:]
    record["security"] = {"state": "pending", "model": "haiku"}
    job = {
        "kind": "steer",
        "sessionId": str(row.get("session_id") or ""),
        "organization": context["org"],
        "repositoryOwner": str(row.get("target_node") or ""),
        "repositoryName": context["repo"],
        "provider": str(row.get("provider") or ""),
        "prompt": prompt,
        "localAgentId": local_agent_id,
        "taskKey": clean_string(record.get("taskKey"), 96),
        "requestedBy": context["actor"],
        "securityCheck": {
            "provider": "claude-code",
            "model": "haiku",
            "tools": False,
            "failClosed": True,
        },
    }
    await d1_run(
        env,
        "UPDATE org_agent_sessions SET status='security_pending',data=?,"
        "updated_at=? WHERE session_id=? AND org_bi=?",
        await encrypt_row(env, record), now, row["session_id"], context["orgBi"],
    )
    await d1_run(
        env,
        "INSERT INTO org_agent_jobs "
        "(session_id,org_bi,target_node,repo,provider,status,lease_id,data,"
        "created_at,updated_at) VALUES (?,?,?,?,?,'queued','',?,?,?)",
        row["session_id"], context["orgBi"], row["target_node"],
        context["repo"], row["provider"], await encrypt_row(env, job), now, now,
    )
    await _audit_sensitive_action(
        env, context["actor"], "organization.agent_prompt",
        "organization_agent", context["org"] + "/" + context["repo"] +
        "/" + row["session_id"], "success")
    await notify_repo_host(
        env, row["target_node"], context["repo"], "org-agents")
    return json_response({"ok": True, "status": "security_pending"},
                         status=202, cache_control="no-store")


async def repo_org_agent_jobs_handler(env, request, owner, repo):
    await ensure_schema(env)
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    if not await _authorize_owner(env, request, owner):
        return json_response({"error": "unauthorized"}, status=401)
    owner = clean_string(owner, MAX_NODE_NAME).strip().lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT).strip().lower()
    now = int(Date.now())
    await d1_run(
        env,
        "UPDATE org_agent_jobs SET status='queued',lease_id='',updated_at=? "
        "WHERE target_node=? AND repo=? AND status='leased' AND updated_at<?",
        now, owner, repo, now - ORG_AGENT_JOB_LEASE_MS,
    )
    rows = await d1_all(
        env,
        "SELECT id,session_id,data FROM org_agent_jobs "
        "WHERE target_node=? AND repo=? AND status='queued' ORDER BY id LIMIT 8",
        owner, repo,
    )
    jobs = []
    for row in rows or []:
        job_id = int(row.get("id") or 0)
        record = await decrypt_row(env, row.get("data"))
        if not job_id or not isinstance(record, dict):
            continue
        lease_id = _ap_uuid()
        await d1_run(
            env,
            "UPDATE org_agent_jobs SET status='leased',lease_id=?,updated_at=? "
            "WHERE id=? AND target_node=? AND status='queued'",
            lease_id, now, job_id, owner,
        )
        jobs.append({
            "jobId": job_id,
            "leaseId": lease_id,
            **record,
        })
    return json_response({
        "ok": True,
        "jobs": jobs,
        "securityGate": "claude-haiku-tool-free-fail-closed",
    }, cache_control="no-store")


async def repo_org_agent_job_result_handler(
        env, request, owner, repo, job_id):
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    if not await _authorize_owner(env, request, owner):
        return json_response({"error": "unauthorized"}, status=401)
    try:
        data = await bounded_json_request(request)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    owner = clean_string(owner, MAX_NODE_NAME).strip().lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT).strip().lower()
    lease_id = clean_string(data.get("leaseId"), 64)
    row = await d1_first(
        env,
        "SELECT id,session_id,org_bi,provider,data FROM org_agent_jobs "
        "WHERE id=? AND target_node=? AND repo=? "
        "AND status IN ('leased','running') "
        "AND lease_id=?",
        int(job_id), owner, repo, lease_id,
    )
    if not row:
        return json_response({"error": "lease_not_found"}, status=409)
    job = await decrypt_row(env, row.get("data"))
    session_row = await d1_first(
        env,
        "SELECT session_id,status,created_by_bi,data FROM org_agent_sessions "
        "WHERE session_id=? AND org_bi=? AND target_node=?",
        row["session_id"], row["org_bi"], owner,
    )
    session = (
        await decrypt_row(env, session_row.get("data"))
        if session_row else None)
    if not isinstance(job, dict) or not isinstance(session, dict):
        return json_response({"error": "invalid_job_state"}, status=409)
    verdict = clean_string(data.get("securityVerdict"), 20).lower()
    run_status = clean_string(data.get("status"), 20).lower()
    if verdict not in ("approved", "rejected"):
        verdict = "rejected"
    if run_status not in ("running", "completed", "failed", "rejected"):
        run_status = "rejected"
    # Exact fail-closed coupling: a run cannot become active unless the node
    # reports that its tool-free Haiku preflight approved this exact leased job.
    if verdict != "approved" and run_status != "rejected":
        run_status = "rejected"
    now = int(Date.now())
    session["security"] = {
        "state": verdict,
        "model": "haiku",
        "reason": clean_string(data.get("securityReason"), 240),
        "at": now,
    }
    local_agent_id = int(data.get("localAgentId") or 0)
    if verdict == "approved" and local_agent_id > 0:
        session["localAgentId"] = local_agent_id
    if isinstance(data.get("agentInfo"), dict):
        session["agentInfo"] = _org_agent_info_projection(
            data.get("agentInfo"))
    if isinstance(data.get("availability"), dict):
        session["availability"] = _org_agent_availability_projection(
            data.get("availability"))
    history = session.get("history")
    if not isinstance(history, list):
        history = []
    result_text = clean_string(
        data.get("result") or data.get("transcript"), MAX_AGENT_TRANSCRIPT)
    history.append({
        "role": "assistant" if verdict == "approved" else "security",
        "author": str(row.get("provider") or "agent"),
        "text": result_text or (
            "Prompt approved by Haiku and dispatched."
            if verdict == "approved"
            else "Prompt rejected by the Haiku security preflight."
        ),
        "at": now,
        "state": run_status,
    })
    session["history"] = history[-ORG_AGENT_MAX_HISTORY:]
    completed_at = now if run_status in ("completed", "failed", "rejected") else 0
    await d1_run(
        env,
        "UPDATE org_agent_sessions SET status=?,data=?,updated_at=?,"
        "completed_at=? WHERE session_id=? AND org_bi=?",
        run_status, await encrypt_row(env, session), now, completed_at,
        row["session_id"], row["org_bi"],
    )
    keep_running = (
        str(job.get("kind") or "") == "start"
        and verdict == "approved"
        and run_status == "running"
    )
    await d1_run(
        env,
        "UPDATE org_agent_jobs SET status=?,updated_at=? "
        "WHERE id=? AND lease_id=?",
        "running" if keep_running else "done", now, int(job_id), lease_id,
    )
    task_key = clean_string(session.get("taskKey"), 96)
    if (
        str(row.get("provider") or "") == "codex"
        and run_status == "completed"
        and re.fullmatch(
            r"(?:task:[a-z0-9-]{1,48}|"
            r"issue:[a-z0-9-]{1,40}/[a-z0-9._-]{1,60}#[1-9][0-9]{0,8})",
            task_key,
        )
    ):
        board_kind = "issue" if task_key.startswith("issue:") else "task"
        await d1_run(
            env,
            "INSERT INTO world_build_board_items "
            "(item_key,kind,owner,repo,issue_number,title,priority,"
            "updated_by_bi,updated_at,completed_at,completed_by_bi) "
            "VALUES (?,?, '', '',0,'',64,?,?,?,?) "
            "ON CONFLICT(item_key) DO UPDATE SET completed_at=excluded.completed_at,"
            "completed_by_bi=excluded.completed_by_bi,"
            "updated_by_bi=excluded.updated_by_bi,updated_at=excluded.updated_at",
            task_key, board_kind, session_row.get("created_by_bi") or "",
            now, now, session_row.get("created_by_bi") or "",
        )
        qa_title = clean_string(
            session.get("prompt") or task_key.replace("task:", ""),
            160,
        ).strip()
        await d1_run(
            env,
            "INSERT INTO world_qa_items("
            "item_key,title,how_to_test,source_key,added_at,active) "
            "VALUES(?,?,?,?,?,1) ON CONFLICT(item_key) DO UPDATE SET "
            "title=excluded.title,how_to_test=excluded.how_to_test,"
            "source_key=excluded.source_key,added_at=excluded.added_at,"
            "active=1",
            task_key,
            qa_title or "Completed agent task",
            (
                "Open the completed feature and follow its normal user flow. "
                "Confirm the requested behavior works, existing behavior did "
                "not regress, and no console or network error appears."
            ),
            task_key,
            now,
        )
    await _audit_sensitive_action(
        env, owner, "organization.agent_job_result", "organization_agent",
        str(row["session_id"]), "success",
        {"securityVerdict": verdict, "status": run_status})
    return json_response({"ok": True, "status": run_status},
                         cache_control="no-store")


# --- Error log + admin dashboard -------------------------------------------

def _sentry_dsn_parts(dsn):
    dsn = str(dsn or "").strip()
    if not dsn:
        return None
    try:
        parsed = urlparse(dsn)
    except Exception:
        return None
    if parsed.scheme not in ("http", "https"):
        return None
    public_key = parsed.username or ""
    host = parsed.hostname or ""
    if parsed.port:
        host += ":" + str(parsed.port)
    path_parts = [p for p in (parsed.path or "").split("/") if p]
    if not public_key or not host or not path_parts:
        return None
    project_id = path_parts[-1]
    path_prefix = "/" + "/".join(path_parts[:-1]) if len(path_parts) > 1 else ""
    return {
        "dsn": dsn,
        "endpoint": "%s://%s%s/api/%s/envelope/" % (
            parsed.scheme, host, path_prefix, project_id),
        "auth": (
            "Sentry sentry_version=7, sentry_key=%s, sentry_client=%s" %
            (public_key, SENTRY_CLIENT)
        ),
    }


def _sentry_event_id():
    try:
        rnd = js_crypto.getRandomValues(Uint8Array.new(16))
        return "".join("%02x" % int(rnd[i]) for i in range(16))
    except Exception:
        return ("%032x" % int(Date.now()))[-32:]


def _sentry_header(request, name):
    try:
        return str(request.headers.get(name) or "")
    except Exception:
        return ""


def _sentry_safe_url(request):
    try:
        raw = str(getattr(request, "url", "") or "")
        parsed = urlparse(raw)
        if parsed.scheme and parsed.netloc:
            return parsed.scheme + "://" + parsed.netloc + (parsed.path or "/")
        return raw.split("?", 1)[0][:2000]
    except Exception:
        return ""


def _sentry_host(request):
    try:
        parsed = urlparse(str(getattr(request, "url", "") or ""))
        if parsed.netloc:
            return parsed.netloc[:255]
    except Exception:
        pass
    return _sentry_header(request, "host")[:255]


def _sentry_request_payload(request, privacy_safe_path=""):
    if request is None:
        return None
    headers = {}
    # Browser/OS and content-negotiation fingerprints are unnecessary for
    # diagnosing a Worker failure. Keep only the service host and Cloudflare's
    # incident correlation id; authorization, cookies, IP-derived values,
    # referrers and user-agent never enter the Sentry envelope.
    for name in ("host", "cf-ray"):
        value = _sentry_header(request, name)
        if value:
            headers[name] = value
    if "host" not in headers:
        host = _sentry_host(request)
        if host:
            headers["host"] = host
    safe_url = _sentry_safe_url(request)
    privacy_safe_path = str(privacy_safe_path or "").strip()
    if privacy_safe_path:
        # The event's transaction path has already passed through
        # _privacy_safe_log_path. Reuse that projection in request.url too;
        # otherwise Sentry would receive the raw private repository name even
        # though the top-level transaction was correctly redacted.
        try:
            parsed = urlparse(safe_url)
            if parsed.scheme and parsed.netloc:
                safe_url = (
                    parsed.scheme + "://" + parsed.netloc
                    + (privacy_safe_path
                       if privacy_safe_path.startswith("/")
                       else "/" + privacy_safe_path)
                )
            else:
                safe_url = privacy_safe_path
        except Exception:
            safe_url = privacy_safe_path
    return {
        "url": safe_url,
        "method": method_name(request),
        "headers": headers,
    }


def _sentry_cloudflare_context(request, ray="", error_code="", service="forkmesh"):
    ctx = {
        "service": str(service or "forkmesh"),
        "worker": str(service or "forkmesh"),
    }
    if error_code:
        ctx["error_code"] = str(error_code)
    ray = str(ray or "")
    if ray:
        ctx["ray_id"] = ray
        ctx["ray"] = ray
    if ray and "-" in ray:
        ctx["colo"] = ray.rsplit("-", 1)[-1]
    cf = getattr(request, "cf", None) if request is not None else None
    if cf is not None:
        # A coarse edge colo and transport versions are enough to diagnose
        # region/protocol faults. Country, timezone, client RTT, cipher and
        # request-priority details add fingerprinting value without enough
        # operational value, so they are deliberately excluded.
        for key in ("colo", "httpProtocol", "tlsVersion"):
            try:
                value = getattr(cf, key)
            except Exception:
                value = None
            if value is not None:
                ctx[key] = str(value)[:120]
    return ctx


def _sentry_environment(env):
    for name in ("SENTRY_ENVIRONMENT", "ENVIRONMENT", "WORKER_ENV", "ENV"):
        try:
            value = getattr(env, name)
        except Exception:
            value = None
        if value:
            return str(value)[:120]
    return ""


def _sentry_stack_frames(error):
    tb = getattr(error, "__traceback__", None)
    if tb is None:
        return []
    frames = []
    try:
        extracted = traceback.extract_tb(tb)
    except Exception:
        return []
    for frame in extracted[-50:]:
        item = {
            "filename": frame.filename,
            "function": frame.name,
            "lineno": frame.lineno,
        }
        if frame.line:
            item["context_line"] = frame.line
        frames.append(item)
    return frames


def _sentry_event_payload(env, status, method, path, message, ray="",
                          request=None, error=None, cloudflare_error_code="",
                          service="forkmesh"):
    text = _privacy_safe_error_text(path, message)
    cf_context = _sentry_cloudflare_context(
        request, ray, cloudflare_error_code, service)
    tags = {
        "runtime": "cloudflare-python-worker",
        "method": str(method or ""),
        "status": str(status or ""),
        "service": str(service or "forkmesh"),
        "worker": str(service or "forkmesh"),
    }
    if cloudflare_error_code:
        tags["cloudflare.error_code"] = str(cloudflare_error_code)
    if ray:
        tags["cloudflare.ray_id"] = str(ray)
    if cf_context.get("colo"):
        tags["cloudflare.colo"] = str(cf_context.get("colo"))
    host = _sentry_host(request)
    if host:
        tags["host"] = host
    event = {
        "event_id": _sentry_event_id(),
        "timestamp": int(Date.now()) / 1000,
        "platform": "python",
        "logger": "forkmesh.cloudflare_worker",
        "level": "error" if int(status or 0) >= 500 else "warning",
        "message": text[:1000] or ("HTTP " + str(status)),
        "transaction": str(path or ""),
        "server_name": str(getattr(env, "NODE_NAME", "") or "cloudflare-worker"),
        "release": _build_rev(env),
        "tags": tags,
        "contexts": {
            "cloudflare": cf_context,
            "runtime": {
                "name": "Cloudflare Python Workers",
                "service": str(service or "forkmesh"),
            },
        },
        "extra": {"error_log_message": text[:8000]},
    }
    environment = _sentry_environment(env)
    if environment:
        event["environment"] = environment
    req = _sentry_request_payload(request, path)
    if req:
        event["request"] = req
    if error is not None:
        exception = {
            "type": type(error).__name__,
            "value": (
                "Repository-route exception details redacted."
                if _privacy_redacted_log_path(path)
                else _safe_error_text(error)[:1000]
            ),
        }
        frames = _sentry_stack_frames(error)
        if frames:
            exception["stacktrace"] = {"frames": frames}
        event["exception"] = {"values": [exception]}
    return event


async def capture_sentry_error(env, status, method, path, message, ray="",
                               request=None, error=None,
                               cloudflare_error_code="", service="forkmesh"):
    """Send one Sentry event with vanilla Python + Worker fetch. Best-effort."""
    try:
        parts = _sentry_dsn_parts(getattr(env, "SENTRY_DSN", ""))
        if not parts:
            return False
        event = _sentry_event_payload(
            env, status, method, path, message, ray, request, error,
            cloudflare_error_code, service)
        envelope = (
            json.dumps({"event_id": event["event_id"], "dsn": parts["dsn"]}) +
            "\n" + json.dumps({"type": "event"}) +
            "\n" + json.dumps(event) + "\n"
        )
        resp = await js_fetch_with_timeout(
            parts["endpoint"],
            {
                "method": "POST",
                "headers": {
                    "content-type": "application/x-sentry-envelope",
                    "x-sentry-auth": parts["auth"],
                },
                "body": envelope,
            },
            CRON_OUTBOUND_FETCH_TIMEOUT_SECONDS,
        )
        return 200 <= int(getattr(resp, "status", 0)) < 300
    except Exception:
        return False


def _sentry_int_env(env, name, default, minimum=1, maximum=1440):
    try:
        raw = getattr(env, name)
    except Exception:
        raw = None
    try:
        value = int(str(raw or "").strip())
    except Exception:
        value = int(default)
    if value < minimum:
        return int(minimum)
    if value > maximum:
        return int(maximum)
    return value


def _sentry_cron_monitor_slug(env):
    for name in ("SENTRY_CRON_MONITOR_SLUG", "SENTRY_MONITOR_SLUG"):
        try:
            value = getattr(env, name)
        except Exception:
            value = None
        value = str(value or "").strip()
        if value:
            return value[:200]
    return SENTRY_CRON_MONITOR_SLUG


def _scheduled_cron_expression(controller):
    for name in ("cron", "schedule"):
        try:
            value = getattr(controller, name)
        except Exception:
            value = None
        value = str(value or "").strip()
        if value:
            return value[:120]
    return "* * * * *"


def _sentry_cron_monitor_config(env, cron):
    cron = str(cron or "").strip() or "* * * * *"
    try:
        timezone = str(getattr(env, "SENTRY_CRON_TIMEZONE", "") or "UTC")
    except Exception:
        timezone = "UTC"
    return {
        "schedule": {"type": "crontab", "value": cron[:120]},
        "checkin_margin": _sentry_int_env(
            env, "SENTRY_CRON_CHECKIN_MARGIN_MINUTES",
            SENTRY_CRON_CHECKIN_MARGIN_MINUTES),
        "max_runtime": _sentry_int_env(
            env, "SENTRY_CRON_MAX_RUNTIME_MINUTES",
            SENTRY_CRON_MAX_RUNTIME_MINUTES),
        "timezone": timezone[:120] or "UTC",
    }


async def capture_sentry_cron_check_in(env, status, check_in_id="",
                                       cron="", duration=None):
    """Send a Sentry Cron Monitoring check-in. Best-effort."""
    try:
        parts = _sentry_dsn_parts(getattr(env, "SENTRY_DSN", ""))
        if not parts:
            return False
        status = str(status or "").strip().lower()
        if status not in ("in_progress", "ok", "error"):
            return False
        check_in_id = str(check_in_id or "").strip() or _sentry_event_id()
        cron = str(cron or "").strip() or "* * * * *"
        payload = {
            "check_in_id": check_in_id[:64],
            "monitor_slug": _sentry_cron_monitor_slug(env),
            "status": status,
            "monitor_config": _sentry_cron_monitor_config(env, cron),
        }
        environment = _sentry_environment(env)
        if environment:
            payload["environment"] = environment
        release = _build_rev(env)
        if release:
            payload["release"] = release
        if duration is not None:
            try:
                payload["duration"] = max(0.0, float(duration))
            except Exception:
                pass
        envelope = (
            json.dumps({"event_id": check_in_id[:32], "dsn": parts["dsn"]}) +
            "\n" + json.dumps({"type": "check_in"}) +
            "\n" + json.dumps(payload) + "\n"
        )
        resp = await js_fetch_with_timeout(
            parts["endpoint"],
            {
                "method": "POST",
                "headers": {
                    "content-type": "application/x-sentry-envelope",
                    "x-sentry-auth": parts["auth"],
                },
                "body": envelope,
            },
            CRON_OUTBOUND_FETCH_TIMEOUT_SECONDS,
        )
        return 200 <= int(getattr(resp, "status", 0)) < 300
    except Exception:
        return False


def _consume_background_task(task, label):
    try:
        task.result()
    except BaseException as error:
        if type(error).__name__ == "CancelledError":
            return


def _fire_and_forget(coro, label="background"):
    try:
        task = asyncio.ensure_future(coro)
    except BaseException:
        try:
            close = getattr(coro, "close", None)
            if close is not None:
                close()
        except BaseException:
            pass
        return None
    try:
        task.add_done_callback(
            lambda done: _consume_background_task(done, label))
    except BaseException:
        pass
    return task


async def _write_error_log(env, status, method, path, message, ray=""):
    try:
        message = _privacy_safe_error_text(path, message)
        await ensure_schema(env)
        await d1_run(
            env,
            """INSERT INTO error_log (ts, status, method, path, message, ray)
               VALUES (?,?,?,?,?,?)""",
            int(Date.now()), int(status), str(method or ""), str(path or ""),
            str(message or "")[:1000], str(ray or ""),
        )
        # Keep only the most-recent MAX_ERROR_LOG rows so the table is bounded.
        await d1_run(
            env,
            """DELETE FROM error_log WHERE id NOT IN
               (SELECT id FROM error_log ORDER BY id DESC LIMIT ?)""",
            MAX_ERROR_LOG,
        )
    except Exception:
        pass


def _privacy_redacted_log_path(path):
    path = str(path or "")
    return (
        path in (
            "/private-or-unpublished-repository",
            "/repository-route-redacted",
            "/api/private-replicas/[opaque]",
        )
        or path.startswith("/private-or-unpublished-repository/")
        or path.startswith("/repository-route-redacted/")
    )


def _privacy_safe_error_text(path, message):
    """Remove exception/detail text when the route identity was redacted."""
    if _privacy_redacted_log_path(path):
        # Two fixed, worker-authored message shapes carry no route identity
        # (no path, no exception text) and are the only diagnostic signal a
        # redacted row has — blanket-redacting them made every private-route
        # 5xx indistinguishable from every other.
        text = str(message or "")
        if (
            text.startswith("response status ")
            and len(text) == len("response status ") + 3
            and text[-3:].isdigit()
        ):
            return text
        return "Repository-route error details redacted."
    return str(message or "")


def _privacy_redacted_route_kind(path):
    """An identity-free route-family tag for a redacted repository path.

    Owner/repo (and any deeper user-named path parts) are dropped entirely —
    what survives is only WHICH fixed route family failed: the git protocol
    step, a release blob, the browser page, or the /api/repo sub-route's fixed
    name (issues/tree/star/…). Without this, every redacted 5xx collapsed
    into one indistinguishable bucket and recurring failures could not even
    be told apart by endpoint (2026-07-24 error-log entries)."""
    if GIT_INFO_RE.match(path):
        return "[git-info-refs]"
    if GIT_PACK_RE.match(path):
        return "[git-upload-pack]"
    if GIT_RECEIVE_RE.match(path):
        return "[git-receive-pack]"
    if RELEASE_BLOB_RE.match(path):
        return "[release-blob]"
    api = REPO_API_PREFIX_RE.match(path)
    if api:
        rest = path[api.end(2):].strip("/")
        route = safe_segment(rest.split("/", 1)[0]) if rest else ""
        # The first segment after /api/repo/<o>/<r>/ is a fixed route name
        # from the worker's own routing table, never user data; anything
        # unrecognizably long is a probe and collapses to a generic tag.
        if route and len(route) <= 32:
            return "[api:" + route + "]"
        return "[api]"
    return "[page]"


async def _privacy_safe_log_path(env, path):
    """Redact names from private, missing, or visibility-unknown repo routes."""
    path = str(path or "")
    # Opaque ids are identity-free and not sufficient authorization, so their
    # presence in unavoidable edge request logs does not reveal a repository.
    # Application/Sentry logs do not need the locator at all: redact it there to
    # avoid turning an error report into a reusable private-route hint.
    if path == "/api/private-replicas" or path.startswith(
            "/api/private-replicas/"):
        return "/api/private-replicas/[opaque]"
    match = REPO_API_PREFIX_RE.match(path)
    if not match:
        for pattern in (
                GIT_INFO_RE, GIT_PACK_RE, GIT_RECEIVE_RE,
                RELEASE_BLOB_RE):
            match = pattern.match(path)
            if match:
                break
    owner = ""
    repo = ""
    if match:
        owner = safe_segment(match.group(1))
        repo = safe_segment(match.group(2))
    elif looks_like_repo_route(path):
        # Browser repository pages (/owner/repo and their tab/tree/blob deep
        # links) are repository routes too. Never let an exception log become
        # a name-existence oracle for a private or unpublished path.
        parts = [part for part in path.split("/") if part]
        owner = safe_segment(unquote(parts[0])) if len(parts) >= 2 else ""
        repo = safe_segment(unquote(parts[1])) if len(parts) >= 2 else ""
    else:
        return path
    if not owner or not repo:
        return "/repository-route-redacted/" + _privacy_redacted_route_kind(
            path)
    if await _repo_is_private(env, owner, repo):
        return ("/private-or-unpublished-repository/"
                + _privacy_redacted_route_kind(path))
    return path


async def capture_worker_exception(env, request, url, error):
    """Capture the Python exception that Cloudflare will surface as Error 1101."""
    try:
        ray = _sentry_header(request, "cf-ray")
    except BaseException:
        ray = ""
    try:
        method = method_name(request)
    except BaseException:
        method = "GET"
    try:
        path = getattr(url, "path", "") or _sentry_safe_url(request)
    except BaseException:
        path = ""
    try:
        path = await _privacy_safe_log_path(env, path)
    except BaseException:
        path = "/repository-route-redacted"
    try:
        message = repr(error) + "\n" + traceback.format_exc()
    except BaseException:
        message = _safe_error_text(error)
    try:
        await capture_sentry_error(
            env, 500, method, path, message, ray,
            request=request,
            error=error,
            cloudflare_error_code="1101",
            service="forkmesh",
        )
    except BaseException:
        pass
    try:
        await _write_error_log(env, 500, method, path, message, ray)
    except BaseException:
        pass


def _html_escape(value):
    return (
        str(value)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
    )


