def _render_admin_nav(tables, active, counts=None, admin_query="", sort_records=False):
    counts = counts or {}
    if sort_records:
        tables = sorted(tables, key=lambda t: counts.get(t, 0), reverse=True)
    toggle_label = "A–Z" if sort_records else "Sort by records"
    toggle_href = _admin_href(admin_query, table=active,
                              sort=("name" if sort_records else "records"))
    links = ['<div class="sec">Tables <a class="navsort" href="%s">%s</a></div>'
             % (toggle_href, toggle_label)]
    for t in tables:
        label = "Error logs" if t == "error_log" else t
        cls = ' class="active"' if t == active else ""
        n = counts.get(t)
        suffix = (' <span class="navcount">%d</span>' % n) if n is not None else ""
        # Carry the active sort along: sort state lives only in the URL, so a
        # table link that dropped it would silently reset the nav to the
        # most-records-first default.
        links.append('<a href="%s"%s>%s%s</a>'
                     % (_admin_href(admin_query, table=t,
                                    sort=("records" if sort_records else "name")),
                        cls, _html_escape(label), suffix))
    return "<nav>" + "".join(links) + "</nav>"


def render_admin_html(env_stats, tables, active_table, table_html, banner="",
                      counts=None, csrf_field="", admin_query="",
                      sort_records=False, operational_alerts_enabled=False):
    banner_html = ('<div class="banner">%s</div>' % _html_escape(banner)) if banner else ""
    return (
        "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">"
        "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"
        "<meta name=\"color-scheme\" content=\"light dark\">"
        "<title>forkmesh · admin</title>"
        # site-header.js is deferred (it also injects the header markup), so on
        # its own it would only stamp html.light/html.dark AFTER first paint —
        # a visible dark→light flash. This blocking pre-paint snippet mirrors
        # its resolveTheme() (same localStorage keys, then OS preference) and
        # stamps the class before any CSS paints, killing the flash. The
        # deferred script re-applies the same value and owns the toggle.
        "<script>(function(){try{"
        "var k=['forkmesh.dashboard.theme','forkmesh.theme'],t='';"
        "for(var i=0;i<k.length;i++){var v=localStorage.getItem(k[i]);"
        "if(v==='light'||v==='dark'){t=v;break;}}"
        "if(!t)t=(window.matchMedia&&window.matchMedia("
        "'(prefers-color-scheme: light)').matches)?'light':'dark';"
        "var r=document.documentElement,l=t==='light';"
        "r.classList.toggle('light',l);r.classList.toggle('dark',!l);"
        "r.style.colorScheme=l?'light':'dark';"
        "}catch(e){}})();</script>"
        # The universal site header (brand, nav, account chip) + the theme
        # engine it carries: site-header.js stamps html.light/html.dark from
        # the visitor's saved choice or OS preference, which ADMIN_STYLE's
        # variable palette keys off. styles.css supplies the header's own
        # tokens; ADMIN_STYLE loads after it so the admin rules win.
        "<link rel=\"stylesheet\" href=\"/styles.css\">"
        "<link rel=\"stylesheet\" href=\"/site-header.css\">"
        "<script src=\"/posthog.js\"></script>"
        "<script src=\"/site-header.js\" defer></script>"
        "<style>" + ADMIN_STYLE + "</style></head><body>"
        "<div data-forkmesh-header=\"simple\"></div>"
        # .ab-root scopes every admin style rule so they cannot leak into the
        # injected site header above (and vice versa).
        "<div class=\"ab-root\">"
        "<header><h1>forkmesh · admin</h1>"
        "<div class=\"meta\">Live Durable Object load, every D1 table, and "
        "Solana payment-reference status.</div></header>"
        + _render_admin_stats(env_stats)
        + _render_admin_operational_alerts(
            operational_alerts_enabled, csrf_field, admin_query)
        + _render_admin_repo_terms_flags(csrf_field, admin_query)
        + '<div class="tools"><form method="post" action="%s" '
          'onsubmit="return confirm(\'Show legacy custody migration status?\')">'
          % _admin_href(admin_query, action="disburse")
          + csrf_field +
          '<button type="submit">Legacy custody status</button></form>'
          '<span class="meta">Worker signing and automated sweeps are disabled. '
          'Historical encrypted deposit rows require an offline, balance-'
          'reconciled migration; this console cannot access or use wallet '
          'seeds.</span></div>'
        + '<div class="tools"><form method="post" action="%s" '
          'onsubmit="return confirm(\'Request ownership transfer for this node?\')">'
          % _admin_href(admin_query, action="request_ownership")
          + csrf_field +
          '<input type="text" name="target" placeholder="node to take (name)" '
          'autocomplete="off" required>'
          '<input type="text" name="owner" placeholder="new owner (account name)" '
          'autocomplete="off" required>'
          '<button type="submit">Request ownership transfer</button></form>'
          '<span class="meta">Parks a pending transfer on the node\'s own '
          'account record — it only completes once that node\'s current '
          'owner approves the confirmation prompt on its own client.</span></div>'
        + banner_html
        + '<div class="layout">'
        + _render_admin_nav(tables, active_table, counts, admin_query, sort_records)
        + "<main>" + table_html + "</main>"
        + "</div></div>"
        "<script>for (const el of document.querySelectorAll('[data-ts]')){"
        "const ms=Number(el.getAttribute('data-ts'));"
        "if(ms)el.textContent=new Date(ms).toLocaleString();}"
        "if(location.hash==='#operational-alerts'){"
        "var a=document.getElementById('operational-alerts');"
        "if(a){a.scrollIntoView({block:'center'});a.focus({preventScroll:true});}"
        "}</script>"
        "</body></html>"
    )


async def _admin_set_password(env, name, password):
    # Reset a user account's login password. The is_admin-gated admin page
    # supplies a node name and a new password; we PBKDF2-hash it and overwrite
    # pass_salt / pass_hash on the encrypted account record, leaving
    # email/solana/etc intact.
    name = clean_string(name or "", MAX_NODE_NAME).lower()
    if not name:
        return "Set password failed: a node name is required."
    if len(password or "") < 8:
        return "Set password failed: password must be at least 8 characters."
    password = password[:256]
    name_bi, rec = await _account_row(env, name)
    if not rec:
        return "Set password failed: no account named '%s'." % name
    salt, phash = await hash_password(password)
    rec["pass_salt"] = salt
    rec["pass_hash"] = phash
    rec.setdefault("status", "active")
    await _save_account(env, name_bi, rec)
    await _account_revoke_sessions(env, name_bi)
    return "Password updated for '%s'. The user can log in with it now." % name


async def _admin_resend_verification(env, request, name):
    # Re-send the email-confirmation link for a user account from the admin page.
    # Mirrors the self-service resendVerification path in the account-update
    # endpoint: send via Mailtrap when configured, otherwise fall back to the
    # pending_verifications queue for manual admin verification.
    name = clean_string(name or "", MAX_NODE_NAME).lower()
    if not name:
        return "Resend verify email failed: a node name is required."
    name_bi, rec = await _account_row(env, name)
    if not rec:
        return "Resend verify email failed: no account named '%s'." % name
    email = rec.get("email", "")
    if not email:
        return "Resend verify email failed: '%s' has no email on file." % name
    if rec.get("email_verified"):
        return "'%s' is already verified; no email sent." % name
    sent = await _send_verification_email(env, request, name, email)
    if sent:
        return "Verification email re-sent to %s for '%s'." % (email, name)
    await _enqueue_verification(env, name_bi, name, email)
    return ("Email is not configured; queued '%s' for manual verification "
            "instead." % name)


async def _admin_console_request_ownership(env, target, owner):
    # Operator-console counterpart to _admin_request_ownership: the operator is
    # already authenticated via Basic Auth + CSRF for this whole page, so no
    # node-key signature is needed here. Still only PARKS a pending marker —
    # the transfer completes only once the target node's own signed heartbeat
    # decision (approve/deny) comes back, same as the signed API path.
    target = clean_string(target or "", MAX_NODE_NAME).strip().lower()
    owner = clean_string(owner or "", MAX_NODE_NAME).strip().lower()
    if not target or not owner:
        return "Ownership request failed: both a node and a new owner are required."
    if not valid_node_name(owner):
        return "Ownership request failed: '%s' is not a valid account name." % owner
    owner_bi, owner_rec = await _account_row(env, owner)
    if not owner_rec or owner_rec.get("status") != "active":
        return "Ownership request failed: no active account named '%s'." % owner
    ok, result = await _park_ownership_transfer(env, target, owner)
    if not ok:
        return "Ownership request failed for '%s': %s." % (target, result)
    if result.get("alreadyOwned"):
        return "'%s' is already owned by '%s'." % (target, owner)
    return ("Ownership transfer requested: '%s' now needs to approve/deny from "
            "its own client before '%s' takes ownership." % (target, owner))


async def _admin_disburse(env):
    del env
    return (
        "Legacy Worker-held deposit sweeps are disabled. Export D1 and run the "
        "offline custody migration after reconciling every on-chain balance; "
        "the web admin cannot access or use retained wallet seeds."
    )


# --- Direct HTTPS mirror discovery, health, and masked routing --------------
#
# Repository bytes use ordinary HTTPS between this edge router and an
# independently operated mirror. D1 retains only signed endpoint identity and
# health metadata. The desktop host WebSocket remains a control/update channel;
# public browse, clone, and release reads below never fall back to it.

HTTPS_MIRROR_ENDPOINT_PATH = "/api/mirrors/https"
HTTPS_MIRROR_PRIVATE_ROUTE_PATH = "/api/mirrors/private"
HTTPS_MIRROR_MANIFEST_MAX_BYTES = 128 * 1024
# Two oldest endpoints per minute supports twenty mirrors inside the ten-minute
# routing freshness window while keeping a fully timed-out alarm comfortably
# below its next wake-up.
HTTPS_MIRROR_HEALTH_BATCH = 2
HTTPS_MIRROR_FETCH_TIMEOUT_SECONDS = 20
HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS = 6
HTTPS_MIRROR_BODY_MAX_BYTES = 8 * 1024 * 1024
HTTPS_MIRROR_MERGE_BODY_MAX_BYTES = 8 * 1024
HTTPS_MIRROR_MERGE_RESULT_MAX_BYTES = 16 * 1024
HTTPS_MIRROR_ACTIONS_RESULT_MAX_BYTES = 256 * 1024
HTTPS_MIRROR_ACTIONS_RUN_LIMIT = 20
HTTPS_MIRROR_ACTIONS_LOG_TAIL_MAX_BYTES = 16 * 1024
HTTPS_MIRROR_ACTIONS_LEASE_MAX_MS = 15 * 60 * 1000
HTTPS_MIRROR_ACTIONS_CLOCK_SKEW_MS = 60 * 1000
HTTPS_MIRROR_MERGE_REQUEST_RE = re.compile(r"^[A-Za-z0-9_-]{12,80}$")
HTTPS_MIRROR_MERGE_JOB_RETENTION_MS = 7 * 24 * 60 * 60 * 1000
HTTPS_MIRROR_MERGE_JOB_REPO_LIMIT = 256
HTTPS_MIRROR_MERGE_JOB_GLOBAL_LIMIT = 10_000
HTTPS_MIRROR_MERGE_JOB_CLEANUP_BATCH = 512
HTTPS_MIRROR_REQUIRED_FORKMESH_OPERATIONS = frozenset({
    "git-info-refs", "git-upload-pack", "tree", "blob", "raw",
})
HTTPS_MIRROR_RETRY_STATUSES = frozenset({
    401, 403, 404, 408, 425, 429, 500, 502, 503, 504,
})
# A health endpoint's timeout/rate-limit/server failure is inconclusive: keep a
# prior signed lease until its normal freshness deadline. Authentication and
# missing-route responses are definitive for this public control endpoint and
# therefore still fail closed immediately.
HTTPS_MIRROR_HEALTH_TRANSIENT_STATUSES = frozenset({
    408, 425, 429, 500, 502, 503, 504,
})
HTTPS_MIRROR_REPO_PROOF_TTL_MS = 60 * 1000
HTTPS_MIRROR_REPO_PROOF_MEMO_MAX = 500
_HTTPS_MIRROR_REPO_PROOF_MEMO = {}


def _https_mirror_router_public_key(env):
    value = clean_string(
        getattr(env, "MIRROR_ROUTER_PUBLIC_KEY", ""), 120).strip()
    return value if valid_node_pubkey(value) else ""


def _https_mirror_router_seed(env):
    # This is a Cloudflare Worker secret, never a D1 field, response value,
    # log field, endpoint argument, or node/wallet credential.
    value = clean_string(
        getattr(env, "MIRROR_ROUTER_SIGNING_SEED", ""), 120).strip()
    return value if re.fullmatch(r"[A-Za-z0-9_-]{43}", value) else ""


def _https_mirror_registration_payload(data):
    if not isinstance(data, dict):
        return None
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).strip().lower()
    base_url = https_routing.normalize_base_url(data.get("baseUrl"))
    public_key = clean_string(data.get("publicKey", ""), 120).strip()
    signature = clean_string(data.get("signature", ""), 200).strip()
    try:
        issued_at = int(data.get("issuedAt") or 0)
    except (TypeError, ValueError):
        return None
    message = https_routing.registration_message(
        node, base_url, public_key, issued_at)
    if (
        not message
        or not valid_node_pubkey(public_key)
        or not re.fullmatch(r"[A-Za-z0-9_-]{86}", signature)
    ):
        return None
    return {
        "node": node,
        "baseUrl": base_url,
        "publicKey": public_key,
        "issuedAt": issued_at,
        "signature": signature,
        "message": message,
    }


async def _https_mirror_fetch_text(
        url, max_bytes, timeout_seconds, accept="application/json"):
    """Fetch a bounded control document without forwarding caller metadata."""
    try:
        response = await js_fetch_with_timeout(
            url,
            {
                "method": "GET",
                "headers": {
                    "accept": accept,
                    "user-agent": "ForkMesh-HTTPS-router/1.0",
                },
                "redirect": "manual",
            },
            timeout_seconds,
        )
        status = int(getattr(response, "status", 0) or 0)
        try:
            announced = int(response.headers.get("content-length") or 0)
        except Exception:
            announced = 0
        if announced > max_bytes:
            return status, ""
        text = str(await response.text())
        if len(text.encode("utf-8")) > max_bytes:
            return status, ""
        return status, text
    except Exception:
        return 0, ""


_CLOUDFLARE_EDGE_RANGES_MEMO = {"checkedAt": 0, "documents": ()}
_HTTPS_MIRROR_EDGE_DNS_MEMO = {}
CLOUDFLARE_EDGE_RANGES_TTL_MS = 24 * 60 * 60 * 1000
HTTPS_MIRROR_EDGE_DNS_TTL_MS = 2 * 60 * 1000


async def _cloudflare_edge_range_documents():
    """Fetch Cloudflare's official bounded IP-range documents."""
    now = int(Date.now())
    cached = _CLOUDFLARE_EDGE_RANGES_MEMO
    documents = cached.get("documents") or ()
    if (
        len(documents) == 2
        and now - int(cached.get("checkedAt") or 0)
        <= CLOUDFLARE_EDGE_RANGES_TTL_MS
    ):
        return documents
    fetched = []
    for url in (
            "https://www.cloudflare.com/ips-v4",
            "https://www.cloudflare.com/ips-v6"):
        status, text = await _https_mirror_fetch_text(
            url, 16 * 1024, HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS)
        if status != 200 or not text:
            return ()
        fetched.append(text)
    documents = tuple(fetched)
    # Validate the documents before caching them. A minimal synthetic DNS
    # answer is enough to exercise strict CIDR parsing without trusting it as a
    # real endpoint decision.
    try:
        first_network = str(documents[0]).split()[0]
        probe = str(ipaddress.ip_network(first_network, strict=True).network_address)
    except (IndexError, ValueError):
        return ()
    if not https_routing.cloudflare_proxied_dns_answers(
            [{"Status": 0, "Answer": [{"type": 1, "data": probe}]}],
            documents):
        return ()
    cached["checkedAt"] = now
    cached["documents"] = documents
    return documents


async def _https_mirror_cloudflare_dns_ok(base_url):
    """Independently verify that an endpoint resolves to Cloudflare's edge.

    ``None`` means the independent verifier itself was temporarily unavailable
    (DoH/range-document timeout or malformed upstream response).  Callers that
    establish a new endpoint still treat that as a rejection.  The recurring
    health check can distinguish it from a definitive non-Cloudflare answer and
    let an existing signed lease expire naturally instead of flickering offline
    on one control-plane timeout.
    """
    normalized = https_routing.normalize_base_url(base_url)
    try:
        hostname = urlparse(normalized).hostname or ""
    except Exception:
        hostname = ""
    if not hostname:
        return False
    now = int(Date.now())
    memo = _HTTPS_MIRROR_EDGE_DNS_MEMO.get(hostname)
    if (
        memo
        and now - int(memo.get("checkedAt") or 0)
        <= HTTPS_MIRROR_EDGE_DNS_TTL_MS
    ):
        return bool(memo.get("ok"))
    cidr_documents = await _cloudflare_edge_range_documents()
    if not cidr_documents:
        return None
    payloads = []
    for record_type in ("A", "AAAA"):
        target = (
            "https://cloudflare-dns.com/dns-query?name="
            + quote(hostname)
            + "&type="
            + record_type
        )
        status, text = await _https_mirror_fetch_text(
            target,
            HTTPS_MIRROR_MANIFEST_MAX_BYTES,
            HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS,
            "application/dns-json",
        )
        if status != 200 or not text:
            return None
        try:
            payloads.append(json.loads(text))
        except Exception:
            return None
    ok = https_routing.cloudflare_proxied_dns_answers(
        payloads, cidr_documents)
    _HTTPS_MIRROR_EDGE_DNS_MEMO[hostname] = {
        "checkedAt": now,
        "ok": bool(ok),
    }
    return bool(ok)


async def _https_mirror_manifest_ok(registration):
    status, text = await _https_mirror_fetch_text(
        registration["baseUrl"] + "/forkmesh-mirror.json",
        HTTPS_MIRROR_MANIFEST_MAX_BYTES,
        HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS,
    )
    if status != 200 or not text:
        return False
    try:
        manifest = json.loads(text)
    except Exception:
        return False
    checked = https_routing.validate_tunnel_manifest(
        manifest,
        registration["baseUrl"],
        registration["node"],
        registration["publicKey"],
    )
    return bool(
        checked
        and await ed25519_verify(
            registration["publicKey"],
            checked["signature"],
            checked["payload"],
        )
    )


async def _https_mirror_node_organizations(env, node):
    """Public organization aliases linked to this endpoint's node."""
    try:
        rows = await d1_all(
            env,
            """SELECT DISTINCT o.name AS name
                 FROM org_repos r JOIN orgs o ON o.org_bi=r.org_bi
                WHERE r.node_owner=? ORDER BY o.name LIMIT 100""",
            node,
        )
        return [
            clean_string(row.get("name", ""), MAX_NODE_NAME).lower()
            for row in rows or []
            if valid_node_name(
                clean_string(row.get("name", ""), MAX_NODE_NAME).lower())
        ]
    except Exception:
        return []


async def https_mirror_endpoint_handler(env, request):
    """Register/update an account-bound, signed Cloudflare Tunnel endpoint."""
    method = method_name(request)
    router_key = _https_mirror_router_public_key(env)
    if method == "GET":
        # Endpoint rows and repository membership are deliberately not listed.
        return json_response({
            "ok": bool(router_key),
            "protocol": "forkmesh-masked-proxy-v1",
            "registration": "forkmesh-https-endpoint-v1",
            "routerPublicKey": router_key,
            "nonCustodial": True,
            "repositoryBytesInD1": False,
        }, status=200 if router_key else 503,
           cache_control="public, max-age=300")
    if method != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        announced = int(request.headers.get("content-length") or 0)
    except Exception:
        announced = 0
    if announced > HTTPS_MIRROR_MANIFEST_MAX_BYTES:
        return json_response({"error": "request_too_large"}, status=413)
    try:
        raw = str(await request.text())
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    if len(raw.encode("utf-8")) > HTTPS_MIRROR_MANIFEST_MAX_BYTES:
        return json_response({"error": "request_too_large"}, status=413)
    try:
        data = json.loads(raw)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    registration = _https_mirror_registration_payload(data)
    if not registration or not _ts_ok(registration["issuedAt"]):
        return json_response({"error": "invalid_registration"}, status=400)
    await ensure_schema(env)

    # The manifest cannot self-assert a new identity: its key must already be
    # bound to the named node as its primary or an enabled owner-sign device.
    allowed_keys = await _owner_signing_pubkeys(env, registration["node"])
    if (
        registration["publicKey"] not in allowed_keys
        or not await ed25519_verify(
            registration["publicKey"],
            registration["signature"],
            registration["message"].encode("utf-8"),
        )
    ):
        return json_response({"error": "unauthorized"}, status=401)
    existing = await d1_first(
        env,
        """SELECT base_url,public_key,registration_sig,issued_at
             FROM mirror_https_endpoints WHERE node_name=?""",
        registration["node"],
    )
    if existing:
        old_issued = int(existing.get("issued_at") or 0)
        same = bool(
            existing.get("base_url") == registration["baseUrl"]
            and existing.get("public_key") == registration["publicKey"]
            and existing.get("registration_sig") == registration["signature"])
        if registration["issuedAt"] < old_issued or (
                registration["issuedAt"] == old_issued and not same):
            return json_response(
                {"error": "stale_registration"}, status=409)
    if not await _https_mirror_cloudflare_dns_ok(registration["baseUrl"]):
        return json_response(
            {"error": "cloudflare_proxied_dns_required"}, status=400)
    if not await _https_mirror_manifest_ok(registration):
        return json_response({"error": "invalid_manifest"}, status=400)

    now = int(Date.now())
    node_bi = await blind_index(env, registration["node"])
    region = world_request_country(request)
    await d1_run(
        env,
        """INSERT INTO mirror_https_endpoints
             (node_bi,node_name,base_url,public_key,registration_sig,issued_at,
              checked_at,latency_ms,region,healthy,integrity,abuse_blocked,
              health_sig,forkmesh_verified_at,forkmesh_refs_sha256,
              forkmesh_operations_sha256,forkmesh_operations_json,
              forkmesh_active,health_message,
              updated_at)
             VALUES (?,?,?,?,?,?,0,0,?,0,'unknown',0,'',0,'','','[]',0,'',?)
             ON CONFLICT(node_bi) DO UPDATE SET
               node_name=excluded.node_name,base_url=excluded.base_url,
               public_key=excluded.public_key,
               registration_sig=excluded.registration_sig,
               issued_at=excluded.issued_at,region=excluded.region,
               healthy=0,integrity='unknown',health_sig='',
               forkmesh_verified_at=0,forkmesh_refs_sha256='',
               forkmesh_operations_sha256='',forkmesh_operations_json='[]',
               forkmesh_active=0,
               health_message='',
               updated_at=excluded.updated_at""",
        node_bi,
        registration["node"],
        registration["baseUrl"],
        registration["publicKey"],
        registration["signature"],
        registration["issuedAt"],
        region,
        now,
    )
    try:
        _, node_rec = await _account_row(env, registration["node"])
        await touch_registered_node(env, node_bi, node_rec)
    except Exception:
        pass
    # Registration resets the endpoint to pending so a replayed registration
    # can never preserve an old healthy lease. Challenge this exact,
    # account-bound endpoint immediately after the durable write. This is what
    # lets every independent mirror renew its own short lease without relying
    # on the scheduled Worker cron (or pretending to be the organization's
    # canonical catalog publisher). The verifier still requires Cloudflare
    # proxied DNS, the registered Ed25519 key, and the canonical repository
    # state pin, so acceptance here does not grant trust by itself.
    health_active = await _https_mirror_refresh_registered_health(
        env, registration["node"])
    return json_response({
        "ok": True,
        "node": registration["node"],
        "baseUrl": registration["baseUrl"],
        "routerPublicKey": router_key,
        "organizations": await _https_mirror_node_organizations(
            env, registration["node"]),
        "health": "active" if health_active else "pending",
        "repositoryBytesInD1": False,
    }, status=201, cache_control="no-store")


def _https_mirror_private_route_payload(data):
    """Validate one owner-signed opaque private-replica binding."""
    if not isinstance(data, dict):
        return None
    owner = clean_string(data.get("owner", ""), MAX_NODE_NAME).strip().lower()
    repo = clean_string(data.get("repository", ""), MAX_REPO_SEGMENT).strip()
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).strip().lower()
    opaque_id = clean_string(data.get("opaqueId", ""), 64).strip().lower()
    replica_sha256 = clean_string(
        data.get("replicaSha256", ""), 64).strip().lower()
    signature = clean_string(data.get("signature", ""), 200).strip()
    active = data.get("active")
    try:
        key_epoch = int(data.get("keyEpoch") or 0)
        issued_at = int(data.get("issuedAt") or 0)
    except (TypeError, ValueError):
        return None
    message = https_routing.private_route_message(
        owner, repo, node, opaque_id, replica_sha256, key_epoch, active,
        issued_at)
    if (
        not message
        or not re.fullmatch(r"[A-Za-z0-9_-]{86}", signature)
    ):
        return None
    return {
        "owner": owner,
        "repo": repo,
        "node": node,
        "opaqueId": opaque_id,
        "replicaSha256": replica_sha256,
        "keyEpoch": key_epoch,
        "active": active,
        "issuedAt": issued_at,
        "signature": signature,
        "message": message,
    }


async def _https_mirror_private_record(env, owner, repo):
    """Return an exact private catalog row without ever listing private rows."""
    owner = clean_string(owner, MAX_NODE_NAME).strip().lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT).strip()
    if not valid_node_name(owner) or not safe_segment(repo):
        return None
    try:
        repo_bi = await blind_index(env, owner + "/" + repo)
        row = await d1_first(
            env,
            "SELECT is_private,data FROM repositories WHERE key_bi=?",
            repo_bi,
        )
        if not row or int(row.get("is_private", 0) or 0) != 1:
            return None
        record = await decrypt_row(env, row.get("data"))
        if (
            not record
            or record.get("visibility") != "private"
            or str(record.get("owner") or "").lower() != owner
            or str(record.get("name") or "") != repo
            or record.get("mirrorEncryption") != "owner-sealed-v1"
            or int(record.get("keyEpoch") or 0) < 1
        ):
            return None
        return {
            "repoBi": repo_bi,
            "keyEpoch": int(record["keyEpoch"]),
            "owner": owner,
            "repo": repo,
        }
    except Exception:
        return None


async def _https_mirror_private_access_record(env, opaque_id):
    """Resolve one opaque access id to exactly one encrypted private record.

    The random id is the only repository locator accepted on the client-facing
    private transport.  It is not sufficient authorization: after this exact
    lookup, the caller must still prove owner/share access using HTTP Basic.
    Multiple active bindings may legitimately use the same id for mirrors of
    the same repository, but an id that maps to more than one repository fails
    closed instead of becoming an ambiguity or existence oracle.
    """
    opaque_id = clean_string(opaque_id, 64).strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", opaque_id):
        return None
    try:
        await ensure_schema(env)
        routes = await d1_all(
            env,
            """SELECT DISTINCT repo_bi,key_epoch
                 FROM private_mirror_routes
                WHERE opaque_replica_id=? AND active=1""",
            opaque_id,
        )
        repo_bis = {
            str(route.get("repo_bi") or "")
            for route in routes or []
            if route.get("repo_bi")
        }
        if len(repo_bis) != 1:
            return None
        repo_bi = next(iter(repo_bis))
        row = await d1_first(
            env,
            "SELECT is_private,data FROM repositories WHERE key_bi=?",
            repo_bi,
        )
        if not row or int(row.get("is_private", 0) or 0) != 1:
            return None
        record = await decrypt_row(env, row.get("data"))
        owner = clean_string(
            (record or {}).get("owner", ""), MAX_NODE_NAME).strip().lower()
        repo = clean_string(
            (record or {}).get("name", ""), MAX_REPO_SEGMENT).strip()
        try:
            key_epoch = int((record or {}).get("keyEpoch") or 0)
        except (TypeError, ValueError):
            return None
        if (
            not record
            or record.get("visibility") != "private"
            or record.get("mirrorEncryption") != "owner-sealed-v1"
            or not valid_node_name(owner)
            or not safe_segment(repo)
            or key_epoch < 1
            or not any(
                int(route.get("key_epoch") or 0) == key_epoch
                for route in routes or []
            )
            or not hmac.compare_digest(
                repo_bi, await blind_index(env, owner + "/" + repo))
        ):
            return None
        return {
            "repoBi": repo_bi,
            "keyEpoch": key_epoch,
            "owner": owner,
            "repo": repo,
        }
    except Exception:
        return None


async def _https_mirror_private_catalog_access_id(
        env, repo_bi, key_epoch):
    """Return one current opaque locator for an already-authorized catalog row."""
    try:
        row = await d1_first(
            env,
            """SELECT opaque_replica_id
                 FROM private_mirror_routes
                WHERE repo_bi=? AND active=1 AND key_epoch=?
                ORDER BY updated_at DESC LIMIT 1""",
            repo_bi, int(key_epoch),
        )
        opaque_id = clean_string(
            (row or {}).get("opaque_replica_id", ""), 64).strip().lower()
        if re.fullmatch(r"[0-9a-f]{64}", opaque_id):
            return opaque_id
    except Exception:
        pass
    return ""


async def https_mirror_private_route_handler(env, request):
    """Create, rotate, or revoke a blind-indexed private ciphertext route."""
    method = method_name(request)
    if method == "GET":
        # This endpoint deliberately has no list operation.
        return json_response({
            "ok": True,
            "protocol": "forkmesh-private-route-v1",
            "transport": "owner-sealed-opaque-archive-v1",
            "repositoryBytesInD1": False,
            "privateRoutesListed": False,
        }, cache_control="public, max-age=300")
    if method != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        announced = int(request.headers.get("content-length") or 0)
    except Exception:
        announced = 0
    if announced > HTTPS_MIRROR_MANIFEST_MAX_BYTES:
        return json_response({"error": "request_too_large"}, status=413)
    try:
        raw = str(await request.text())
    except Exception:
        return json_response({"error": "not_found"}, status=404)
    if len(raw.encode("utf-8")) > HTTPS_MIRROR_MANIFEST_MAX_BYTES:
        return json_response({"error": "request_too_large"}, status=413)
    try:
        binding = _https_mirror_private_route_payload(json.loads(raw))
    except Exception:
        binding = None
    if not binding or not _ts_ok(binding["issuedAt"]):
        return json_response({"error": "not_found"}, status=404)
    await ensure_schema(env)
    private_record = await _https_mirror_private_record(
        env, binding["owner"], binding["repo"])
    owner_key = await _owner_pubkey(env, binding["owner"])
    if (
        not private_record
        or not owner_key
        or private_record["keyEpoch"] != binding["keyEpoch"]
        or not await ed25519_verify(
            owner_key,
            binding["signature"],
            binding["message"].encode("utf-8"),
        )
    ):
        return json_response({"error": "not_found"}, status=404)
    endpoint = await d1_first(
        env,
        "SELECT node_bi FROM mirror_https_endpoints WHERE node_name=?",
        binding["node"],
    )
    if not endpoint:
        return json_response({"error": "not_found"}, status=404)
    node_bi = str(endpoint.get("node_bi") or "")
    binding_bi = await blind_index(
        env,
        "private-route:" + binding["owner"] + "/" + binding["repo"]
        + ":" + binding["node"],
    )
    existing = await d1_first(
        env,
        """SELECT issued_at,owner_sig,active,opaque_replica_id,
                  replica_sha256,key_epoch
             FROM private_mirror_routes WHERE binding_bi=?""",
        binding_bi,
    )
    if existing:
        old_issued = int(existing.get("issued_at") or 0)
        same = bool(
            old_issued == binding["issuedAt"]
            and existing.get("owner_sig") == binding["signature"]
            and bool(existing.get("active")) == binding["active"]
            and existing.get("opaque_replica_id") == binding["opaqueId"]
            and existing.get("replica_sha256") == binding["replicaSha256"]
            and int(existing.get("key_epoch") or 0) == binding["keyEpoch"])
        if binding["issuedAt"] < old_issued or (
                binding["issuedAt"] == old_issued and not same):
            return json_response({"error": "stale_registration"}, status=409)
    collision = await d1_first(
        env,
        """SELECT binding_bi FROM private_mirror_routes
            WHERE opaque_replica_id=? AND repo_bi<>? LIMIT 1""",
        binding["opaqueId"], private_record["repoBi"],
    )
    if collision:
        return json_response({"error": "route_conflict"}, status=409)
    now = int(Date.now())
    await d1_run(
        env,
        """INSERT INTO private_mirror_routes
             (binding_bi,repo_bi,node_bi,opaque_replica_id,replica_sha256,
              key_epoch,owner_sig,issued_at,active,updated_at)
             VALUES (?,?,?,?,?,?,?,?,?,?)
             ON CONFLICT(binding_bi) DO UPDATE SET
               node_bi=excluded.node_bi,
               opaque_replica_id=excluded.opaque_replica_id,
               replica_sha256=excluded.replica_sha256,
               key_epoch=excluded.key_epoch,owner_sig=excluded.owner_sig,
               issued_at=excluded.issued_at,active=excluded.active,
               updated_at=excluded.updated_at""",
        binding_bi,
        private_record["repoBi"],
        node_bi,
        binding["opaqueId"],
        binding["replicaSha256"],
        binding["keyEpoch"],
        binding["signature"],
        binding["issuedAt"],
        1 if binding["active"] else 0,
        now,
    )
    return json_response({
        "ok": True,
        "active": binding["active"],
        "keyEpoch": binding["keyEpoch"],
        "privateAccessId": (
            binding["opaqueId"] if binding["active"] else ""),
        "accessPath": (
            "/api/private-replicas/" + binding["opaqueId"]
            if binding["active"] else ""),
        "repositoryBytesInD1": False,
    }, status=201, cache_control="no-store")


async def _https_mirror_expected_forkmesh_refs(env):
    """Owner-attested refs digest for the public flagship repository.

    ``forkmesh`` may be an organization namespace rather than an account.  In
    that case its public URL is backed by a linked node's catalog row; resolve
    that alias for the state pin while health challenges continue to name the
    stable public ``forkmesh/forkmesh`` gateway alias.
    """
    try:
        owner = await _org_repo_node(env, "forkmesh", "forkmesh") or "forkmesh"
        key_bi = await blind_index(env, owner + "/forkmesh")
        row = await d1_first(
            env,
            "SELECT data,is_private FROM repositories WHERE key_bi=?",
            key_bi,
        )
        if not row or int(row.get("is_private", 1) or 0) != 0:
            return ""
        record = await decrypt_row(env, row.get("data"))
        digest = clean_string((record or {}).get("stateHash", ""), 64).lower()
        if (
            not record
            or record.get("visibility") != "public"
            or not re.fullmatch(r"[0-9a-f]{64}", digest)
        ):
            return ""
        return digest
    except Exception:
        return ""


async def _https_mirror_accepted_forkmesh_refs(env):
    """Current and recent source-attested states accepted during convergence.

    The source publication and a mirror refresh cannot commit atomically across
    independent machines.  Keep the direct-HTTPS lease valid while a healthy
    mirror still serves a recent state that the source genuinely signed; an
    unknown state remains rejected by the health challenge.
    """
    try:
        owner = await _org_repo_node(env, "forkmesh", "forkmesh") or "forkmesh"
        key_bi = await blind_index(env, owner + "/forkmesh")
        row = await d1_first(
            env,
            "SELECT data,is_private FROM repositories WHERE key_bi=?",
            key_bi,
        )
        if not row or int(row.get("is_private", 1) or 0) != 0:
            return frozenset()
        record = await decrypt_row(env, row.get("data"))
        if not record or record.get("visibility") != "public":
            return frozenset()
        pins = set()
        current = clean_string(record.get("stateHash", ""), 64).lower()
        if re.fullmatch(r"[0-9a-f]{64}", current):
            pins.add(current)
        history = await d1_all(
            env,
            "SELECT state_hash FROM repo_state_history WHERE key_bi=? "
            "ORDER BY ts DESC LIMIT ?",
            key_bi,
            STATE_PIN_HISTORY,
        )
        for item in history or []:
            digest = clean_string(
                item.get("state_hash", ""), 64).strip().lower()
            if re.fullmatch(r"[0-9a-f]{64}", digest):
                pins.add(digest)
        return frozenset(pins)
    except Exception:
        return frozenset()


def _https_mirror_refs_match(refs_digest, accepted_refs):
    """Compare a proof with a bounded set of exact source-signed ref states."""
    digest = str(refs_digest or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", digest):
        return False
    candidates = (
        (accepted_refs,)
        if isinstance(accepted_refs, str)
        else (accepted_refs or ())
    )
    return any(
        re.fullmatch(r"[0-9a-f]{64}", str(item or "").strip().lower())
        and hmac.compare_digest(digest, str(item).strip().lower())
        for item in candidates
    )


async def _https_mirror_refresh_registered_health(env, node):
    """Best-effort activation for one exact registered endpoint.

    The endpoint row is already account-bound and signature-verified by the
    registration handler. Health is nevertheless established only by a fresh
    node-signed challenge whose repository digest matches the canonical public
    state pin.
    """
    node = clean_string(node, MAX_NODE_NAME).strip().lower()
    if not valid_node_name(node):
        return False
    try:
        row = await d1_first(
            env,
            """SELECT node_bi,node_name,base_url,public_key
                 FROM mirror_https_endpoints WHERE node_name=?""",
            node,
        )
        if not row:
            return False
        accepted = await _https_mirror_accepted_forkmesh_refs(env)
        if not accepted:
            return False
        return bool(await _https_mirror_health_one(env, row, accepted))
    except Exception:
        # Registration remains safely pending. A transient control-plane fetch
        # failure must not roll back its authenticated endpoint record.
        return False


async def _https_mirror_refresh_catalog_publisher_health(env, record):
    """Best-effort activation for one signed public flagship publication.

    Catalog authorization already binds ``record["owner"]`` and its maintainer
    signature to an active account. This lookup stays scoped to that exact node;
    ``_https_mirror_health_one`` then independently rechecks its bound signing
    key, Cloudflare-proxied DNS, and fresh node-signed repository proof.
    """
    if (
        not isinstance(record, dict)
        or record.get("visibility") != "public"
        or clean_string(record.get("name", ""), MAX_REPO_SEGMENT).lower()
        != "forkmesh"
    ):
        return False
    node = clean_string(
        record.get("owner", ""), MAX_NODE_NAME).strip().lower()
    if not valid_node_name(node):
        return False
    try:
        canonical_node = clean_string(
            await _org_repo_node(env, "forkmesh", "forkmesh"),
            MAX_NODE_NAME,
        ).strip().lower()
        canonical_node = canonical_node or "forkmesh"
        if node != canonical_node:
            return False
        return bool(await _https_mirror_refresh_registered_health(env, node))
    except Exception:
        # Publication is already authorized and durable. Health remains pending
        # or is cleared by the verifier; a control-plane fetch/storage failure
        # must not turn that successful catalog write into an error response.
        return False


async def _https_mirror_mark_failed(env, row, now):
    await d1_run(
        env,
        """UPDATE mirror_https_endpoints
              SET checked_at=?,healthy=0,integrity='failed',health_sig='',
                  forkmesh_verified_at=0,forkmesh_refs_sha256='',
                  forkmesh_operations_sha256='',
                  forkmesh_operations_json='[]',forkmesh_active=0,
                  health_message='',updated_at=?
            WHERE node_bi=?""",
        now, now, row.get("node_bi"),
    )


async def _https_mirror_mark_transient(env, row, now):
    # Record only the attempt time.  checked_at/forkmesh_verified_at remain the
    # last successful signed proof, so routing naturally stops at the normal
    # freshness deadline if the outage persists.  Keeping updated_at separate
    # also lets oldest-attempt-first scheduling rotate past this endpoint.
    await d1_run(
        env,
        """UPDATE mirror_https_endpoints
              SET updated_at=?
            WHERE node_bi=?""",
        now, row.get("node_bi"),
    )


async def _https_mirror_health_one(env, row, accepted_forkmesh_refs):
    """Verify one fresh node-signed health and forkmesh/forkmesh proof."""
    now = int(Date.now())
    node = clean_string(row.get("node_name", ""), MAX_NODE_NAME).lower()
    public_key = clean_string(row.get("public_key", ""), 120)
    base_url = https_routing.normalize_base_url(row.get("base_url"))
    if (
        not valid_node_name(node)
        or not valid_node_pubkey(public_key)
        or not base_url
        or public_key not in await _owner_signing_pubkeys(env, node)
    ):
        await _https_mirror_mark_failed(env, row, now)
        return False
    dns_ok = await _https_mirror_cloudflare_dns_ok(base_url)
    if dns_ok is None:
        await _https_mirror_mark_transient(env, row, now)
        return False
    if not dns_ok:
        await _https_mirror_mark_failed(env, row, now)
        return False
    nonce = _b64url_encode(_random_bytes(18))
    target = (
        base_url + "/health?nonce=" + quote(nonce)
        + "&issuedAt=" + str(now)
        + "&owner=forkmesh&repo=forkmesh"
    )
    started = int(Date.now())
    status, text = await _https_mirror_fetch_text(
        target,
        HTTPS_MIRROR_MANIFEST_MAX_BYTES,
        HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS,
    )
    latency = max(0, min(60_000, int(Date.now()) - started))
    if status == 0 or status in HTTPS_MIRROR_HEALTH_TRANSIENT_STATUSES:
        await _https_mirror_mark_transient(env, row, now)
        return False
    try:
        data = json.loads(text) if text else {}
    except Exception:
        data = {}
    try:
        proof = data.get("repositoryProof")
        challenge = data.get("challenge")
        operations = proof.get("operations")
        operations_digest = https_routing.operations_sha256(operations)
        available = proof.get("available") is True
        proof_integrity = str(proof.get("integrity") or "").lower()
        refs_digest = str(proof.get("refsSha256") or "").lower()
        claimed_operations_digest = str(
            proof.get("operationsSha256") or "").lower()
        message = https_routing.repository_health_challenge(
            node,
            nonce,
            now,
            proof.get("owner"),
            proof.get("repository"),
            available,
            proof_integrity,
            refs_digest,
            claimed_operations_digest,
        )
        signature = str(challenge.get("signature") or "")
        valid = bool(
            isinstance(data, dict)
            and data.get("node") == node
            and data.get("publicKey") == public_key
            and data.get("transport") == "direct-https"
            and isinstance(proof, dict)
            and proof.get("owner") == "forkmesh"
            and proof.get("repository") == "forkmesh"
            and isinstance(challenge, dict)
            and challenge.get("messageType")
            == "forkmesh-https-health-repository-v1"
            and challenge.get("nonce") == nonce
            and int(challenge.get("issuedAt") or 0) == now
            and challenge.get("algorithm") == "Ed25519"
            and challenge.get("encoding") == "base64url-no-padding"
            and message
            and challenge.get("messageSha256")
            == hashlib.sha256(message.encode("utf-8")).hexdigest()
            and operations_digest
            and operations_digest == claimed_operations_digest
            and await ed25519_verify(
                public_key, signature, message.encode("utf-8"))
        )
    except Exception:
        valid = False
        signature = ""
        operations = []
        operations_digest = ""
        available = False
        proof_integrity = "unavailable"
        refs_digest = ""
    if not valid:
        await _https_mirror_mark_failed(env, row, now)
        return False
    general_healthy = bool(
        status == 200
        and data.get("ok") is True
        and data.get("integrity") == "ok"
    )
    forkmesh_active = bool(
        general_healthy
        and available
        and proof_integrity == "ok"
        and _https_mirror_refs_match(
            refs_digest, accepted_forkmesh_refs)
        and HTTPS_MIRROR_REQUIRED_FORKMESH_OPERATIONS.issubset(
            set(operations))
    )
    verified_at = now if forkmesh_active else 0
    await d1_run(
        env,
        """UPDATE mirror_https_endpoints
              SET checked_at=?,latency_ms=?,healthy=?,integrity=?,
                  health_sig=?,forkmesh_verified_at=?,
                  forkmesh_refs_sha256=?,forkmesh_operations_sha256=?,
                  forkmesh_operations_json=?,
                  forkmesh_active=?,health_message=?,updated_at=?
            WHERE node_bi=?""",
        now,
        latency,
        1 if general_healthy else 0,
        "ok" if general_healthy else "degraded",
        signature,
        verified_at,
        refs_digest if available else "",
        operations_digest if available else "",
        json.dumps(
            operations if available else [],
            separators=(",", ":"),
        ),
        1 if forkmesh_active else 0,
        message if valid else "",
        now,
        row.get("node_bi"),
    )
    if general_healthy:
        # A fresh identity-bound challenge is a real node activity signal.
        await d1_run(
            env, "UPDATE nodes SET last_seen=? WHERE node_bi=?",
            now, row.get("node_bi"))
    # Callers that renew a public routing lease need to know whether this exact
    # repository is eligible for rotation, not merely whether the node's
    # generic health endpoint answered.
    return forkmesh_active


async def https_mirror_health_cron(env):
    """Challenge a bounded oldest-first batch; no repository bytes enter D1."""
    await ensure_schema(env)
    rows = await d1_all(
        env,
        """SELECT node_bi,node_name,base_url,public_key
             FROM mirror_https_endpoints
            ORDER BY
              CASE WHEN updated_at > checked_at
                   THEN updated_at ELSE checked_at END ASC,
              node_name ASC
            LIMIT ?""",
        HTTPS_MIRROR_HEALTH_BATCH,
    )
    if not rows:
        return
    accepted = await _https_mirror_accepted_forkmesh_refs(env)
    # A missing canonical state pin is a control-plane read failure, not proof
    # that every independent mirror became invalid simultaneously.  Preserve
    # their existing leases; the next minute retries the bounded batch.
    if not accepted:
        return
    # Keep the alarm runner on one Python task. Python fan-out/timeout wrappers
    # create nested Pyodide tasks which can poison a later scheduled wrapper
    # with "Cannot enter into task" after the invocation has already ended.
    # Oldest-first ordering plus the bounded batch still rotates every endpoint.
    for row in rows:
        try:
            await _https_mirror_health_one(env, row, accepted)
        except BaseException:
            continue


async def _https_mirror_private_candidates(
        env, private_record, preferred_region):
    """Resolve only active, current-epoch opaque routes after authorization."""
    rows = await d1_all(
        env,
        """SELECT r.opaque_replica_id,r.replica_sha256,r.key_epoch,
                  e.node_name,e.base_url,e.public_key,e.registration_sig,
                  e.issued_at,e.checked_at,e.latency_ms,e.region,e.healthy,
                  e.integrity,e.abuse_blocked
             FROM private_mirror_routes r
             JOIN mirror_https_endpoints e ON e.node_bi=r.node_bi
            WHERE r.repo_bi=? AND r.active=1 AND r.key_epoch=?""",
        private_record["repoBi"], private_record["keyEpoch"],
    )
    route_by_node = {}
    records = []
    for row in rows or []:
        node = clean_string(
            row.get("node_name", ""), MAX_NODE_NAME).strip().lower()
        opaque_id = clean_string(
            row.get("opaque_replica_id", ""), 64).strip().lower()
        digest = clean_string(
            row.get("replica_sha256", ""), 64).strip().lower()
        if (
            not valid_node_name(node)
            or not re.fullmatch(r"[0-9a-f]{64}", opaque_id)
            or not re.fullmatch(r"[0-9a-f]{64}", digest)
        ):
            continue
        projected = _https_mirror_endpoint_projection(row)
        records.append(projected)
        route_by_node[node] = {
            "opaqueId": opaque_id,
            "replicaSha256": digest,
            "keyEpoch": int(row.get("key_epoch") or 0),
        }
    cursor_row = await d1_first(
        env, "SELECT cursor FROM edge_route_cursor WHERE repo_bi=?",
        private_record["repoBi"])
    selected = https_routing.select_endpoints(
        records,
        int(Date.now()),
        preferred_region=preferred_region,
        cursor=int((cursor_row or {}).get("cursor") or 0),
    )
    for endpoint in selected:
        endpoint.update(route_by_node.get(endpoint["node"], {}))
    return [
        endpoint for endpoint in selected
        if endpoint.get("opaqueId") and endpoint.get("replicaSha256")
    ]


async def _https_mirror_private_request_authorized(
        env, request, private_record):
    """Verify owner/share Basic auth after the opaque route was resolved.

    Private read credentials are never accepted from a URL or query string and
    are never forwarded to a mirror.  Repository identity comes only from the
    encrypted record selected by the random opaque id.
    """
    if not private_record:
        return False
    return await _basic_auth_view_ok(
        env,
        private_record.get("owner", ""),
        private_record.get("repo", ""),
        request,
    )


def _private_replica_not_found():
    """One cache-safe denial shape for unknown, inactive, and unauthorized ids."""
    return json_response(
        {"error": "not_found"}, status=404,
        cache_control="no-store, max-age=0, must-revalidate")


async def _https_mirror_private_access_handler(
        env, request, url, opaque_id):
    """Authorize and serve an identity-free private-replica request."""
    # A query would put credentials or repository hints into intermediary and
    # platform logs. Even harmless-looking query parameters are rejected so
    # there is exactly one supported private client request shape.
    if method_name(request) not in ("GET", "HEAD") or url.query:
        return _private_replica_not_found()
    private_record = await _https_mirror_private_access_record(env, opaque_id)
    if (
        private_record is None
        or not await _https_mirror_private_request_authorized(
            env, request, private_record)
    ):
        return _private_replica_not_found()
    return await _https_mirror_private_proxy(env, request, private_record)


async def _https_mirror_private_proxy(env, request, private_record):
    """Stream an authorized owner-sealed archive; never request plaintext."""
    method = method_name(request)
    if method not in ("GET", "HEAD"):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    if private_record is None:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    router_public_key = _https_mirror_router_public_key(env)
    router_seed = _https_mirror_router_seed(env)
    if not router_public_key or not router_seed:
        return json_response(
            {"error": "mirror_unavailable"}, status=503,
            cache_control="no-store")
    candidates = await _https_mirror_private_candidates(
        env, private_record, world_request_country(request))
    if not candidates:
        return json_response(
            {"error": "mirror_unavailable"}, status=503,
            cache_control="no-store")
    from js import fetch as js_fetch
    for endpoint in candidates:
        target = https_routing.masked_private_replica_url(
            endpoint["baseUrl"], endpoint["opaqueId"])
        parsed_target = urlparse(target)
        signed_path = parsed_target.path
        request_id = _b64url_encode(_random_bytes(18))
        issued_at = int(Date.now())
        body_digest = https_routing.empty_body_sha256()
        message = https_routing.request_message(
            endpoint["node"], method, signed_path, body_digest, request_id,
            issued_at)
        signature = await ed25519_sign(
            router_public_key, router_seed, message.encode("utf-8"))
        if not target or not message or not signature:
            continue
        headers = {
            "X-ForkMesh-Node": endpoint["node"],
            "X-ForkMesh-Request-Id": request_id,
            "X-ForkMesh-Issued-At": str(issued_at),
            "X-ForkMesh-Body-Sha256": body_digest,
            "X-ForkMesh-Signature": signature,
        }
        try:
            upstream = await asyncio.wait_for(
                js_fetch(JsRequest.new(
                    target,
                    to_js({
                        "method": method,
                        "headers": headers,
                        "redirect": "manual",
                    }),
                )),
                timeout=HTTPS_MIRROR_FETCH_TIMEOUT_SECONDS,
            )
            status = int(getattr(upstream, "status", 0) or 0)
        except Exception:
            upstream = None
            status = 0
        if upstream is None or status != 200:
            continue
        try:
            content_type = str(
                upstream.headers.get("content-type") or "").split(";", 1)[0]
            etag = str(upstream.headers.get("etag") or "")
            announced = int(upstream.headers.get("content-length") or 0)
        except Exception:
            continue
        expected_etag = '"sha256-' + endpoint["replicaSha256"] + '"'
        if (
            content_type
            != "application/vnd.forkmesh.private-replica+json"
            or not hmac.compare_digest(etag, expected_etag)
            or announced <= 0
            or announced > 2 * 1024 * 1024 * 1024
        ):
            continue
        raw_headers = {}
        for name in (
            "content-type", "content-length", "etag", "content-disposition",
        ):
            try:
                value = upstream.headers.get(name)
            except Exception:
                value = None
            if value is not None:
                raw_headers[name] = str(value)
        response_headers = https_routing.response_headers(raw_headers)
        response_headers["cache-control"] = (
            "no-store, max-age=0, must-revalidate")
        await _https_mirror_route_advance(
            env, private_record, endpoint["node"], "private-replica")
        return JsResponse.new(
            upstream.body,
            to_js({"status": 200, "headers": response_headers}),
        )
    return json_response(
        {"error": "mirror_unavailable"}, status=503,
        cache_control="no-store")


async def _hosted_repository_import_route(env, owner, repo):
    """Resolve one public logical import name to its physical mirror catalog."""
    owner_l = clean_string(owner, MAX_NODE_NAME).strip().lower()
    repo_l = clean_string(repo, MAX_REPO_SEGMENT).strip().lower()
    if not valid_node_name(owner_l) or not safe_segment(repo_l):
        return None
    rows = await d1_all(
        env,
        "SELECT data FROM repository_imports "
        "WHERE is_private=0 AND status='actively_mirrored' "
        "ORDER BY updated_at DESC LIMIT ?",
        repository_import.MAX_PUBLIC_IMPORTS,
    )
    for row in rows or []:
        record = await decrypt_row(env, row.get("data"))
        if not isinstance(record, dict):
            continue
        target_owner = clean_string(
            record.get("targetOwner"), MAX_NODE_NAME).strip().lower()
        name = clean_string(
            record.get("name"), MAX_REPO_SEGMENT).strip().lower()
        if target_owner != owner_l or name != repo_l:
            continue
        mirror = record.get("mirror") or {}
        mirror_owner = clean_string(
            mirror.get("owner"), MAX_NODE_NAME).strip().lower()
        mirror_name = clean_string(
            mirror.get("name"), MAX_REPO_SEGMENT).strip()
        if (
                mirror_owner in ("mirror2", "mirror3")
                and valid_node_name(mirror_owner)
                and safe_segment(mirror_name)):
            return mirror_owner, mirror_name
    return None


async def _https_mirror_public_context(env, owner, repo):
    """Return canonical public repo identity and integrity-approved node set."""
    owner_l = clean_string(owner, MAX_NODE_NAME).strip().lower()
    repo_l = clean_string(repo, MAX_REPO_SEGMENT).strip().lower()
    if not valid_node_name(owner_l) or not safe_segment(repo_l):
        return None
    try:
        await ensure_schema(env)
        now = int(Date.now())
        rows = [
            row for row in await _decrypted_public_catalog(env, now)
            if (
                not row.get("is_private")
                and (row.get("data") or {}).get("visibility") == "public"
                and not _is_blocked_catalog_identity(
                    env,
                    (row.get("data") or {}).get("owner"),
                    (row.get("data") or {}).get("name"),
                )
            )
        ]
        target_row = None
        for row in rows:
            record = row.get("data") or {}
            if (
                str(record.get("owner") or "").lower() == owner_l
                and str(record.get("name") or "").lower() == repo_l
            ):
                target_row = row
                break
        if not target_row:
            hosted_route = await _hosted_repository_import_route(
                env, owner_l, repo_l)
            if hosted_route:
                hosted_owner, hosted_repo = hosted_route
                for row in rows:
                    record = row.get("data") or {}
                    if (
                            str(record.get("owner") or "").lower()
                            == hosted_owner
                            and str(record.get("name") or "").lower()
                            == hosted_repo.lower()):
                        target_row = row
                        break
            if not target_row:
                return None
        target = target_row["data"]
        members = [
            row for row in rows
            if repo_mirror_same_group(target, row.get("data") or {})
        ]
        group_keys = [
            str(row.get("key_bi") or "")
            for row in members if row.get("key_bi")
        ]
        history = {}
        for offset in range(0, len(group_keys), 80):
            key_batch = group_keys[offset:offset + 80]
            history_rows = await d1_all(
                env,
                "SELECT key_bi,state_hash FROM repo_state_history"
                " WHERE key_bi IN (%s)"
                % ",".join("?" for _ in key_batch),
                *key_batch,
            )
            for item in history_rows or []:
                history.setdefault(
                    str(item.get("key_bi") or ""), []).append(
                        item.get("state_hash"))
        # An organization administrator can explicitly link one of their owned
        # mirror nodes as the canonical backing node for an organization URL.
        # In that case the linked record is the organization-owner attestation:
        # use its signed current/history pins, then admit only peer mirrors that
        # publish one of those exact states. This avoids an unrelated same-name
        # local-node record overriding the explicit organization link while
        # retaining the stricter source-of-truth pin policy everywhere else.
        linked_target = await d1_first(
            env,
            "SELECT 1 AS linked FROM org_repos "
            "WHERE node_owner=? AND repo=? LIMIT 1",
            owner_l,
            repo_l,
        )
        if (
            linked_target
            and str(target.get("source") or "").strip().lower()
            == "remote-clone"
        ):
            pins = set()
            current_pins = set()
            target_state = clean_string(
                target.get("stateHash", ""), 64).lower()
            if re.fullmatch(r"[0-9a-f]{64}", target_state):
                pins.add(target_state)
                current_pins.add(target_state)
            for state in history.get(
                    str(target_row.get("key_bi") or ""), []):
                state = clean_string(state, 64).lower()
                if re.fullmatch(r"[0-9a-f]{64}", state):
                    pins.add(state)
            pins = pins or None
        else:
            pins = clone_state_pins(
                target, target_row.get("key_bi"), members, history)
            current_pins = set()
            for row in members:
                record = row.get("data") or {}
                state = clean_string(
                    record.get("stateHash", ""), 64).lower()
                if (
                    str(record.get("source") or "local-node")
                    == "local-node"
                    and re.fullmatch(r"[0-9a-f]{64}", state)
                ):
                    current_pins.add(state)
        # Direct routing never uses the legacy unpinned fail-open behavior. An
        # owner must publish an authenticated refs digest before a remote
        # endpoint can advertise or resolve that repository.
        if not pins:
            return None
        allowed = set()
        current_nodes = set()
        source = None
        for row in members:
            record = row.get("data") or {}
            node = clean_string(
                record.get("owner", ""), MAX_NODE_NAME).lower()
            state = clean_string(record.get("stateHash", ""), 64).lower()
            if not valid_node_name(node):
                continue
            if pins and state not in pins:
                continue
            allowed.add(node)
            if state in current_pins:
                current_nodes.add(node)
            if (
                source is None
                and str(record.get("source") or "local-node")
                == "local-node"
            ):
                source = record
        if not allowed:
            return None
        canonical = source or target
        canonical_owner = clean_string(
            canonical.get("owner", ""), MAX_NODE_NAME).lower()
        canonical_repo = clean_string(
            canonical.get("name", ""), MAX_REPO_SEGMENT)
        if (
            not valid_node_name(canonical_owner)
            or not safe_segment(canonical_repo)
        ):
            return None
        return {
            "owner": canonical_owner,
            "repo": canonical_repo,
            "nodes": allowed,
            # Ordinary reads prefer the newest source generation. Recent
            # signed generations remain available strictly as failover while
            # their nodes converge.
            "currentNodes": current_nodes,
            "pins": set(pins),
            "repoBi": await blind_index(
                env, canonical_owner + "/" + canonical_repo.lower()),
        }
    except Exception:
        return None


def _https_mirror_endpoint_projection(row):
    return {
        "node": row.get("node_name"),
        "baseUrl": row.get("base_url"),
        "publicKey": row.get("public_key"),
        "signature": row.get("registration_sig"),
        "issuedAt": row.get("issued_at"),
        "checkedAt": row.get("checked_at"),
        "latencyMs": row.get("latency_ms"),
        "region": row.get("region"),
        "healthy": bool(row.get("healthy")),
        "integrity": row.get("integrity"),
        "abuseBlocked": bool(row.get("abuse_blocked")),
    }


async def _https_mirror_candidates(env, context, preferred_region, sticky=""):
    rows = await d1_all(
        env,
        """SELECT node_name,base_url,public_key,registration_sig,issued_at,
                  checked_at,latency_ms,region,healthy,integrity,abuse_blocked
             FROM mirror_https_endpoints""",
    )
    records = [
        _https_mirror_endpoint_projection(row)
        for row in rows or []
        if str(row.get("node_name") or "").lower() in context["nodes"]
    ]
    cursor_row = await d1_first(
        env, "SELECT cursor FROM edge_route_cursor WHERE repo_bi=?",
        context["repoBi"])
    selected = https_routing.select_endpoints(
        records,
        int(Date.now()),
        preferred_region=preferred_region,
        cursor=int((cursor_row or {}).get("cursor") or 0),
    )
    current_nodes = {
        str(node or "").lower()
        for node in context.get("currentNodes", set())
    }
    if current_nodes:
        selected.sort(
            key=lambda item: (
                0 if str(item.get("node") or "").lower()
                in current_nodes else 1
            )
        )
    sticky = str(sticky or "").lower()
    if sticky:
        selected.sort(key=lambda item: 0 if item["node"] == sticky else 1)
    return selected


async def _https_mirror_clone_pin(env, context):
    row = await d1_first(
        env,
        "SELECT owner,ts FROM clone_sticky WHERE repo_bi=?",
        context["repoBi"],
    )
    if (
        row
        and int(Date.now()) - int(row.get("ts") or 0) <= CLONE_STICKY_MS
    ):
        return clean_string(row.get("owner", ""), MAX_NODE_NAME).lower()
    return ""


async def _https_mirror_route_advance(env, context, served_node, operation):
    now = int(Date.now())
    # A Git clone has two requests: info/refs selects the next mirror and the
    # upload-pack body is pinned to that same mirror. Advancing for both made a
    # two-node fleet move the cursor by two per clone and therefore select the
    # same node forever. Advance once for info/refs (and once for each ordinary
    # browse/release request), but never advance again for its sticky
    # git-upload-pack continuation.
    if operation != "git-upload-pack":
        await d1_run(
            env,
            """INSERT INTO edge_route_cursor(repo_bi,cursor,updated_at)
                 VALUES (?,1,?)
                 ON CONFLICT(repo_bi) DO UPDATE SET
                   cursor=edge_route_cursor.cursor+1,
                   updated_at=excluded.updated_at""",
            context["repoBi"], now,
        )
    if operation == "git-info-refs":
        await d1_run(
            env,
            """INSERT INTO clone_sticky(repo_bi,owner,ts) VALUES (?,?,?)
                 ON CONFLICT(repo_bi) DO UPDATE SET
                   owner=excluded.owner,ts=excluded.ts""",
            context["repoBi"], served_node, now,
        )


def _https_mirror_request_query(url, operation, release_sha=""):
    params = parse_qs(url.query, keep_blank_values=True)
    if operation == "git-info-refs":
        return {"service": "git-upload-pack"}
    if operation == "release-blob":
        return {"sha256": release_sha}
    output = {}
    if operation == "blobs":
        paths = params.get("path", [])[:MAX_BLOB_BATCH]
        if paths:
            output["path"] = paths
    elif operation == "search":
        query = params.get("q", params.get("path", [""]))[0]
        if query:
            output["path"] = query
    elif operation == "compare":
        for key in ("base", "head"):
            if params.get(key):
                output[key] = params[key][0]
    elif operation in ("tree", "blob", "raw", "commit"):
        if params.get("path"):
            output["path"] = params["path"][0]
    if params.get("ref"):
        output["ref"] = params["ref"][0]
    return output


async def _https_mirror_repository_proof(env, endpoint, context, operation):
    """Require a fresh signed refs/operation proof for this public repo."""
    now = int(Date.now())
    route_owner = context.get("routeOwner") or context["owner"]
    pins_key = ",".join(sorted(context["pins"]))
    memo_key = (
        endpoint["node"], route_owner, context["repo"], pins_key)
    memo = _HTTPS_MIRROR_REPO_PROOF_MEMO.get(memo_key)
    if memo and now - memo["checkedAt"] <= HTTPS_MIRROR_REPO_PROOF_TTL_MS:
        return operation in memo["operations"]
    nonce = _b64url_encode(_random_bytes(18))
    target = (
        endpoint["baseUrl"] + "/health?nonce=" + quote(nonce)
        + "&issuedAt=" + str(now)
        + "&owner=" + quote(route_owner)
        + "&repo=" + quote(context["repo"])
    )
    status, text = await _https_mirror_fetch_text(
        target,
        HTTPS_MIRROR_MANIFEST_MAX_BYTES,
        HTTPS_MIRROR_CONTROL_FETCH_TIMEOUT_SECONDS,
    )
    try:
        data = json.loads(text) if text else {}
        proof = data.get("repositoryProof")
        challenge = data.get("challenge")
        operations = proof.get("operations")
        operations_digest = https_routing.operations_sha256(operations)
        refs_digest = str(proof.get("refsSha256") or "").lower()
        claimed_operations_digest = str(
            proof.get("operationsSha256") or "").lower()
        message = https_routing.repository_health_challenge(
            endpoint["node"],
            nonce,
            now,
            proof.get("owner"),
            proof.get("repository"),
            proof.get("available") is True,
            proof.get("integrity"),
            refs_digest,
            claimed_operations_digest,
        )
        valid = bool(
            status == 200
            and isinstance(data, dict)
            and data.get("ok") is True
            and data.get("integrity") == "ok"
            and data.get("node") == endpoint["node"]
            and data.get("publicKey") == endpoint["publicKey"]
            and data.get("transport") == "direct-https"
            and isinstance(proof, dict)
            and proof.get("owner") == route_owner
            and proof.get("repository") == context["repo"]
            and proof.get("available") is True
            and proof.get("integrity") == "ok"
            and refs_digest in context["pins"]
            and operations_digest
            and operations_digest == claimed_operations_digest
            and isinstance(challenge, dict)
            and challenge.get("messageType")
            == "forkmesh-https-health-repository-v1"
            and challenge.get("nonce") == nonce
            and int(challenge.get("issuedAt") or 0) == now
            and challenge.get("algorithm") == "Ed25519"
            and challenge.get("encoding") == "base64url-no-padding"
            and challenge.get("messageSha256")
            == hashlib.sha256(message.encode("utf-8")).hexdigest()
            and await ed25519_verify(
                endpoint["publicKey"],
                str(challenge.get("signature") or ""),
                message.encode("utf-8"),
            )
        )
    except Exception:
        valid = False
        operations = []
    if not valid:
        return False
    if len(_HTTPS_MIRROR_REPO_PROOF_MEMO) >= HTTPS_MIRROR_REPO_PROOF_MEMO_MAX:
        _HTTPS_MIRROR_REPO_PROOF_MEMO.clear()
    _HTTPS_MIRROR_REPO_PROOF_MEMO[memo_key] = {
        "checkedAt": now,
        "operations": frozenset(operations),
    }
    return operation in set(operations)


def _https_mirror_merge_body(raw, pull_number):
    """Validate the small account request before any node sees it."""
    if not isinstance(raw, str) or not raw or (
            len(raw.encode("utf-8")) > HTTPS_MIRROR_MERGE_BODY_MAX_BYTES):
        return None

    def reject_duplicates(pairs):
        output = {}
        for key, value in pairs:
            if key in output:
                raise ValueError("duplicate")
            output[key] = value
        return output

    try:
        value = json.loads(raw, object_pairs_hook=reject_duplicates)
    except Exception:
        return None
    required = {
        "schemaVersion", "type", "pullNumber", "requestId",
        "expectedBaseOid", "expectedHeadOid", "expectedPullsOid",
    }
    if (
        not isinstance(value, dict)
        or not required.issubset(value)
        or set(value) - required - {"sessionToken"}
        or value.get("schemaVersion") != 1
        or value.get("type") != "forkmesh.pull-merge-v1"
    ):
        return None
    try:
        number = int(value.get("pullNumber"))
    except (TypeError, ValueError, OverflowError):
        return None
    request_id = clean_string(value.get("requestId", ""), 80).strip()
    oids = {
        field: clean_string(value.get(field, ""), 64).strip().lower()
        for field in (
            "expectedBaseOid", "expectedHeadOid", "expectedPullsOid")
    }
    if (
        number != int(pull_number)
        or not HTTPS_MIRROR_MERGE_REQUEST_RE.fullmatch(request_id)
        or any(
            not re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", oid)
            for oid in oids.values()
        )
        or len({len(oid) for oid in oids.values()}) != 1
    ):
        return None
    return {
        "schemaVersion": 1,
        "type": "forkmesh.pull-merge-v1",
        "pullNumber": number,
        "requestId": request_id,
        **oids,
        **({
            "sessionToken": clean_string(
                value.get("sessionToken", ""), 512).strip()
        } if value.get("sessionToken") else {}),
    }


def _https_mirror_merge_result(value, request):
    """Return a bounded node result or None; no origin data is projected."""
    if not isinstance(value, dict):
        return None
    request_id = str(value.get("requestId") or "")
    status = str(value.get("status") or "")
    if request_id != request["requestId"]:
        return None
    if status == "processing":
        if value.get("ok") is not True:
            return None
        return {
            "ok": True,
            "status": "processing",
            "requestId": request_id,
        }
    if status == "failed":
        error = str(value.get("error") or "")
        if error not in {
            "merge_conflict", "pull_not_found", "pull_not_open",
            "stale_base", "stale_head", "stale_pull_metadata",
            "unsupported_pull",
        }:
            return None
        return {
            "ok": False,
            "status": "failed",
            "requestId": request_id,
            "error": error,
        }
    if (
        status != "merged"
        or value.get("ok") is not True
        or value.get("published") is not True
    ):
        return None
    output = {
        "ok": True,
        "status": "merged",
        "requestId": request_id,
        "published": True,
    }
    expected = {
        "baseBefore": request["expectedBaseOid"],
        "head": request["expectedHeadOid"],
        "pullsBefore": request["expectedPullsOid"],
    }
    for field in (
            "baseBefore", "head", "pullsBefore", "baseAfter", "pullsAfter"):
        oid = str(value.get(field) or "").strip().lower()
        if (
            not re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", oid)
            or (field in expected and not hmac.compare_digest(
                oid, expected[field]))
        ):
            return None
        output[field] = oid
    return output


async def _https_mirror_merge_proxy(env, endpoint, context, request):
    """Submit/poll one job on its permanently selected signed mirror."""
    if not await _https_mirror_repository_proof(
            env, endpoint, context, "merge-pull"):
        return 0, None
    body = json.dumps(
        request, sort_keys=True, separators=(",", ":")).encode("utf-8")
    target = https_routing.masked_target_url(
        endpoint["baseUrl"], context["owner"], context["repo"], "merge-pull")
    parsed_target = urlparse(target)
    signed_path = parsed_target.path
    request_id = _b64url_encode(_random_bytes(18))
    issued_at = int(Date.now())
    body_digest = hashlib.sha256(body).hexdigest()
    message = https_routing.request_message(
        endpoint["node"], "POST", signed_path, body_digest, request_id,
        issued_at)
    router_public_key = _https_mirror_router_public_key(env)
    router_seed = _https_mirror_router_seed(env)
    signature = (
        await ed25519_sign(
            router_public_key, router_seed, message.encode("utf-8"))
        if target and message and router_public_key and router_seed else "")
    if not signature:
        return 0, None
    headers = {
        "Content-Type": "application/json",
        "X-ForkMesh-Node": endpoint["node"],
        "X-ForkMesh-Request-Id": request_id,
        "X-ForkMesh-Issued-At": str(issued_at),
        "X-ForkMesh-Body-Sha256": body_digest,
        "X-ForkMesh-Signature": signature,
    }
    try:
        upstream = await asyncio.wait_for(
            js_fetch(JsRequest.new(
                target,
                to_js({
                    "method": "POST",
                    "headers": headers,
                    "body": Uint8Array.new(_to_js(body)),
                    "redirect": "manual",
                }),
            )),
            timeout=HTTPS_MIRROR_FETCH_TIMEOUT_SECONDS,
        )
        status = int(getattr(upstream, "status", 0) or 0)
        announced = int(upstream.headers.get("content-length") or 0)
        if announced > HTTPS_MIRROR_MERGE_RESULT_MAX_BYTES:
            return 0, None
        raw = str(await upstream.text())
        if len(raw.encode("utf-8")) > HTTPS_MIRROR_MERGE_RESULT_MAX_BYTES:
            return 0, None
        value = json.loads(raw)
    except Exception:
        return 0, None
    checked = _https_mirror_merge_result(value, request)
    if (
        checked is None
        or status not in (200, 202, 404, 409)
        or (checked["status"] == "processing" and status != 202)
        or (checked["status"] == "merged" and status != 200)
        or (checked["status"] == "failed" and status not in (404, 409))
    ):
        return 0, None
    return status, checked


def _https_mirror_actions_result(value, expected_node, now):
    """Validate and reduce one owner-authorized, already-redacted run summary."""
    required = {"ok", "node", "updatedAt", "expiresAt", "runs"}
    if (
        not isinstance(value, dict)
        or set(value) != required
        or value.get("ok") is not True
        or value.get("node") != expected_node
        or isinstance(value.get("updatedAt"), bool)
        or isinstance(value.get("expiresAt"), bool)
    ):
        return None
    try:
        updated_at = int(value.get("updatedAt"))
        expires_at = int(value.get("expiresAt"))
    except (TypeError, ValueError, OverflowError):
        return None
    if (
        updated_at < now - HTTPS_MIRROR_ACTIONS_LEASE_MAX_MS
        or updated_at > now + HTTPS_MIRROR_ACTIONS_CLOCK_SKEW_MS
        or expires_at <= now
        or expires_at <= updated_at
        or expires_at - updated_at > HTTPS_MIRROR_ACTIONS_LEASE_MAX_MS
    ):
        return None
    runs = value.get("runs")
    if (
        not isinstance(runs, list)
        or len(runs) > HTTPS_MIRROR_ACTIONS_RUN_LIMIT
    ):
        return None
    statuses = {
        "awaiting-approval", "queued", "running", "success", "failed",
        "rejected", "cancelled", "skipped",
    }
    fields = {
        "id", "workflow", "commit", "ref", "status",
        "createdAt", "startedAt", "finishedAt", "logTail",
    }
    output_runs = []
    for item in runs:
        if not isinstance(item, dict) or set(item) != fields:
            return None
        if any(
            isinstance(item.get(field), bool)
            for field in ("id", "createdAt", "startedAt", "finishedAt")
        ):
            return None
        try:
            run_id = int(item.get("id"))
            created_at = int(item.get("createdAt"))
            started_at = int(item.get("startedAt"))
            finished_at = int(item.get("finishedAt"))
        except (TypeError, ValueError, OverflowError):
            return None
        workflow = str(item.get("workflow") or "").strip()
        commit = str(item.get("commit") or "").strip().lower()
        ref = str(item.get("ref") or "").strip()
        status_value = str(item.get("status") or "")
        log_tail = str(item.get("logTail") or "")
        if (
            not 1 <= run_id <= 2147483647
            or not 1 <= len(workflow) <= 160
            or any(char in workflow for char in ("\x00", "\r", "\n"))
            or not re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", commit)
            or not 1 <= len(ref) <= 160
            or any(char in ref for char in ("\x00", "\r", "\n"))
            or status_value not in statuses
            or min(created_at, started_at, finished_at) < 0
            or max(created_at, started_at, finished_at)
                > now + HTTPS_MIRROR_ACTIONS_CLOCK_SKEW_MS
            or len(log_tail.encode("utf-8"))
                > HTTPS_MIRROR_ACTIONS_LOG_TAIL_MAX_BYTES
            or "\x00" in log_tail
        ):
            return None
        output_runs.append({
            "id": run_id,
            "workflow": workflow,
            "commit": commit,
            "ref": ref,
            "status": status_value,
            "createdAt": created_at,
            "startedAt": started_at,
            "finishedAt": finished_at,
            "logTail": log_tail,
        })
    return {
        "ok": True,
        "node": expected_node,
        "updatedAt": updated_at,
        "expiresAt": expires_at,
        "runs": output_runs,
    }


async def _https_mirror_actions_proxy(env, endpoint, context):
    """Read one bounded summary through an attested operation-specific route."""
    if not await _https_mirror_repository_proof(
            env, endpoint, context, "actions-status"):
        return None
    target = https_routing.masked_target_url(
        endpoint["baseUrl"], context["owner"], context["repo"],
        "actions-status")
    parsed_target = urlparse(target)
    request_id = _b64url_encode(_random_bytes(18))
    issued_at = int(Date.now())
    body_digest = hashlib.sha256(b"").hexdigest()
    message = https_routing.request_message(
        endpoint["node"], "GET", parsed_target.path, body_digest, request_id,
        issued_at)
    router_public_key = _https_mirror_router_public_key(env)
    router_seed = _https_mirror_router_seed(env)
    signature = (
        await ed25519_sign(
            router_public_key, router_seed, message.encode("utf-8"))
        if target and message and router_public_key and router_seed else "")
    if not signature:
        return None
    headers = {
        "X-ForkMesh-Node": endpoint["node"],
        "X-ForkMesh-Request-Id": request_id,
        "X-ForkMesh-Issued-At": str(issued_at),
        "X-ForkMesh-Body-Sha256": body_digest,
        "X-ForkMesh-Signature": signature,
    }
    try:
        upstream = await asyncio.wait_for(
            js_fetch(JsRequest.new(
                target,
                to_js({
                    "method": "GET",
                    "headers": headers,
                    "redirect": "manual",
                }),
            )),
            timeout=HTTPS_MIRROR_FETCH_TIMEOUT_SECONDS,
        )
        if int(getattr(upstream, "status", 0) or 0) != 200:
            return None
        announced = int(upstream.headers.get("content-length") or 0)
        if announced > HTTPS_MIRROR_ACTIONS_RESULT_MAX_BYTES:
            return None
        raw = str(await upstream.text())
        if len(raw.encode("utf-8")) > HTTPS_MIRROR_ACTIONS_RESULT_MAX_BYTES:
            return None
        value = json.loads(raw)
    except Exception:
        return None
    return _https_mirror_actions_result(
        value, endpoint["node"], int(Date.now()))


async def repository_actions_status_handler(env, request, owner, repo):
    """Return private redacted executor state to the owner or org writer."""
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    context = await _https_mirror_public_context(env, owner, repo)
    if context is None:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    _, actor_record = await _account_session_record(env, request)
    actor = clean_string(
        (actor_record or {}).get("name", ""), MAX_NODE_NAME).strip().lower()
    if not actor:
        return json_response(
            {"error": "invalid_session"}, status=401,
            cache_control="no-store")
    try:
        authorized = bool(
            actor == context["owner"]
            or await _account_owns_node(env, actor, context["owner"])
            or await _org_write_allowed(
                env, context["owner"], context["repo"], actor)
        )
    except Exception:
        authorized = False
    target = context["owner"] + "/" + context["repo"]
    if not authorized:
        await _audit_sensitive_action(
            env, actor, "repository.actions_status", "repository", target,
            "denied", {})
        return json_response(
            {"error": "forbidden"}, status=403,
            cache_control="no-store")
    candidates = await _https_mirror_candidates(
        env, context, world_request_country(request))
    for candidate in candidates:
        result = await _https_mirror_actions_proxy(
            env, candidate, context)
        if result is not None:
            await _audit_sensitive_action(
                env, actor, "repository.actions_status", "repository",
                target, "success", {"node": candidate["node"]})
            return json_response(
                result,
                cache_control="private, no-store, max-age=0, must-revalidate")
    return json_response(
        {"error": "actions_status_unavailable"}, status=503,
        cache_control="no-store")


async def _organization_owner_can_merge_repo(
        env, request, canonical_owner, repo, actor):
    """Require the signed-in actor to own the org alias in the original URL.

    The internal router has already rewritten /api/repo/<org>/<repo> to the
    backing node namespace. Merge-via-mirror is intentionally narrower than
    ordinary team write access until group merge policy exists: direct node
    URLs, organization admins, maintainers, and writers all fail closed.
    """
    if not actor:
        return False
    try:
        original = urlparse(request.url)
        match = REPO_API_PREFIX_RE.match(original.path)
    except Exception:
        return False
    if not match:
        return False
    alias_owner = (safe_segment(match.group(1)) or "").strip().lower()
    alias_repo = (safe_segment(match.group(2)) or "").strip().lower()
    canonical_owner = str(canonical_owner or "").strip().lower()
    repo = str(repo or "").strip().lower()
    if (
        not alias_owner
        or alias_owner == canonical_owner
        or alias_repo != repo
    ):
        return False
    org_bi, org_row = await _org_row(env, alias_owner)
    if not org_row:
        return False
    linked = await d1_first(
        env,
        "SELECT 1 AS ok FROM org_repos "
        "WHERE org_bi=? AND repo=? AND node_owner=?",
        org_bi, repo, canonical_owner,
    )
    if not linked:
        return False
    return await _org_role(env, org_bi, actor) == "owner"


def _https_mirror_merge_response(value):
    status = str((value or {}).get("status") or "")
    if status == "processing":
        code = 202
    elif status == "merged":
        code = 200
    elif (value or {}).get("error") == "pull_not_found":
        code = 404
    else:
        code = 409
    return json_response(
        value, status=code,
        cache_control="no-store, max-age=0, must-revalidate")


async def _repo_merge_jobs_make_room(env, repo_bi, now):
    """Expire bounded batches and enforce hard per-repo/global row ceilings.

    Terminal rows are oldest-first eviction candidates when a ceiling is
    reached. In-flight rows are never evicted merely to admit another request;
    the caller fails closed with 429 instead.
    """
    await d1_run(
        env,
        """DELETE FROM repo_merge_jobs WHERE request_id IN (
               SELECT request_id FROM repo_merge_jobs
                WHERE expires_at<=?
                ORDER BY expires_at ASC
                LIMIT %d)""" % HTTPS_MIRROR_MERGE_JOB_CLEANUP_BATCH,
        int(now),
    )

    async def counts():
        row = await d1_first(
            env,
            """SELECT COUNT(*) AS total,
                      COALESCE(SUM(CASE WHEN repo_bi=? THEN 1 ELSE 0 END),0)
                        AS repo_count
                 FROM repo_merge_jobs""",
            repo_bi,
        )
        return (
            int((row or {}).get("total") or 0),
            int((row or {}).get("repo_count") or 0),
        )

    total, repo_count = await counts()
    if repo_count >= HTTPS_MIRROR_MERGE_JOB_REPO_LIMIT:
        remove = min(
            HTTPS_MIRROR_MERGE_JOB_CLEANUP_BATCH,
            repo_count - HTTPS_MIRROR_MERGE_JOB_REPO_LIMIT + 1,
        )
        await d1_run(
            env,
            """DELETE FROM repo_merge_jobs WHERE request_id IN (
                   SELECT request_id FROM repo_merge_jobs
                    WHERE repo_bi=? AND status IN ('succeeded','failed')
                    ORDER BY updated_at ASC
                    LIMIT ?)""",
            repo_bi, remove,
        )
        total, repo_count = await counts()
    if total >= HTTPS_MIRROR_MERGE_JOB_GLOBAL_LIMIT:
        remove = min(
            HTTPS_MIRROR_MERGE_JOB_CLEANUP_BATCH,
            total - HTTPS_MIRROR_MERGE_JOB_GLOBAL_LIMIT + 1,
        )
        await d1_run(
            env,
            """DELETE FROM repo_merge_jobs WHERE request_id IN (
                   SELECT request_id FROM repo_merge_jobs
                    WHERE status IN ('succeeded','failed')
                    ORDER BY updated_at ASC
                    LIMIT ?)""",
            remove,
        )
        total, repo_count = await counts()
    return (
        repo_count < HTTPS_MIRROR_MERGE_JOB_REPO_LIMIT
        and total < HTTPS_MIRROR_MERGE_JOB_GLOBAL_LIMIT
    )


async def repository_pull_merge_handler(
        env, request, owner, repo, pull_number):
    """Authorize, pin, dispatch, and durably reconcile one merge job."""
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    context = await _https_mirror_public_context(env, owner, repo)
    if context is None:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    try:
        announced = int(request.headers.get("content-length") or 0)
    except Exception:
        announced = 0
    if announced > HTTPS_MIRROR_MERGE_BODY_MAX_BYTES:
        return json_response({"error": "request_too_large"}, status=413)
    try:
        raw = str(await request.text())
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    data = _https_mirror_merge_body(raw, pull_number)
    if data is None:
        return json_response({"error": "invalid_request"}, status=400)
    actor_bi, actor_record = await _account_session_record(env, request, data)
    actor = clean_string(
        (actor_record or {}).get("name", ""), MAX_NODE_NAME).strip().lower()
    if not actor:
        return json_response({"error": "invalid_session"}, status=401)
    try:
        authorized = await _organization_owner_can_merge_repo(
            env, request, context["owner"], context["repo"], actor)
    except Exception:
        authorized = False
    target = context["owner"] + "/" + context["repo"]
    if not authorized:
        await _audit_sensitive_action(
            env, actor, "repository.pull_merge", "repository", target,
            "denied", {"pullNumber": int(pull_number)})
        return json_response({"error": "forbidden"}, status=403)

    node_request = {
        key: value for key, value in data.items() if key != "sessionToken"
    }
    digest_value = {
        **node_request,
        "actor": actor,
        "owner": context["owner"],
        "repository": context["repo"],
    }
    request_digest = hashlib.sha256(json.dumps(
        digest_value, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")).hexdigest()
    await ensure_schema(env)
    now = int(Date.now())
    # Delete this exact expired id first; otherwise its primary key could make
    # INSERT OR IGNORE look successful while no live job can be read back.
    await d1_run(
        env,
        "DELETE FROM repo_merge_jobs WHERE request_id=? AND expires_at<=?",
        node_request["requestId"], now,
    )
    row = await d1_first(
        env,
        """SELECT request_digest,repo_bi,actor_bi,pull_number,selected_node,
                  status,result,expires_at
             FROM repo_merge_jobs WHERE request_id=? AND expires_at>?""",
        node_request["requestId"], now,
    )
    job_created = False
    if row is None:
        if not await _repo_merge_jobs_make_room(
                env, context["repoBi"], now):
            return json_response(
                {"error": "merge_queue_full"}, status=429,
                cache_control="no-store")
        candidates = await _https_mirror_candidates(
            env, context, world_request_country(request))
        selected = None
        for candidate in candidates:
            if await _https_mirror_repository_proof(
                    env, candidate, context, "merge-pull"):
                selected = candidate
                break
        if selected is None:
            return json_response(
                {"error": "merge_node_unavailable"}, status=503,
                cache_control="no-store")
        expires_at = now + HTTPS_MIRROR_MERGE_JOB_RETENTION_MS
        try:
            await d1_run(
                env,
                """INSERT OR IGNORE INTO repo_merge_jobs
                     (request_id,request_digest,repo_bi,actor_bi,pull_number,
                      selected_node,status,result,created_at,updated_at,expires_at)
                     VALUES (?,?,?,?,?,?,'requested','',?,?,?)""",
                node_request["requestId"], request_digest, context["repoBi"],
                actor_bi, int(pull_number), selected["node"], now, now,
                expires_at,
            )
            job_created = True
        except Exception:
            # The schema triggers are the final concurrency-safe hard bounds.
            # Re-read first because an identical request may have won the race;
            # only a genuinely absent row is a full queue.
            job_created = False
        row = await d1_first(
            env,
            """SELECT request_digest,repo_bi,actor_bi,pull_number,selected_node,
                      status,result,expires_at
                 FROM repo_merge_jobs WHERE request_id=? AND expires_at>?""",
            node_request["requestId"], now,
        )
        if row is None:
            return json_response(
                {"error": "merge_queue_full"}, status=429,
                cache_control="no-store")
    if (
        not row
        or not hmac.compare_digest(
            str(row.get("request_digest") or ""), request_digest)
        or not hmac.compare_digest(
            str(row.get("repo_bi") or ""), context["repoBi"])
        or not hmac.compare_digest(
            str(row.get("actor_bi") or ""), actor_bi)
        or int(row.get("pull_number") or 0) != int(pull_number)
    ):
        return json_response(
            {"error": "request_id_reused"}, status=409,
            cache_control="no-store")
    if row.get("status") in ("succeeded", "failed"):
        try:
            result = json.loads(str(row.get("result") or ""))
        except Exception:
            result = None
        checked = _https_mirror_merge_result(result, node_request)
        if checked is None or checked.get("status") == "processing":
            return json_response(
                {"error": "merge_state_unavailable"}, status=503,
                cache_control="no-store")
        return _https_mirror_merge_response(checked)

    selected_node = clean_string(
        row.get("selected_node", ""), MAX_NODE_NAME).strip().lower()
    candidates = await _https_mirror_candidates(
        env, context, world_request_country(request), sticky=selected_node)
    endpoint = next(
        (candidate for candidate in candidates
         if candidate["node"] == selected_node),
        None,
    )
    if endpoint is None:
        return json_response(
            {"error": "merge_node_unavailable"}, status=503,
            cache_control="no-store")
    upstream_status, result = await _https_mirror_merge_proxy(
        env, endpoint, context, node_request)
    if result is None:
        # An uncertain transport result never fails over: the selected node may
        # already have committed the exact idempotent request.
        return json_response(
            {"error": "merge_status_pending"}, status=503,
            cache_control="no-store")
    if upstream_status == 202:
        if job_created:
            await _audit_sensitive_action(
                env, actor, "repository.pull_merge", "repository", target,
                "requested", {"pullNumber": int(pull_number)})
        return _https_mirror_merge_response(result)
    terminal = "succeeded" if result["status"] == "merged" else "failed"
    encoded = json.dumps(
        result, sort_keys=True, separators=(",", ":"))
    if len(encoded.encode("utf-8")) > HTTPS_MIRROR_MERGE_RESULT_MAX_BYTES:
        return json_response(
            {"error": "merge_state_unavailable"}, status=503,
            cache_control="no-store")
    await d1_run(
        env,
        """UPDATE repo_merge_jobs SET status=?,result=?,updated_at=?,expires_at=?
             WHERE request_id=? AND status='requested'""",
        terminal, encoded, int(Date.now()),
        int(Date.now()) + HTTPS_MIRROR_MERGE_JOB_RETENTION_MS,
        node_request["requestId"],
    )
    await _audit_sensitive_action(
        env, actor, "repository.pull_merge", "repository", target,
        "success" if terminal == "succeeded" else "failed",
        {"pullNumber": int(pull_number),
         "reason": str(result.get("error") or "")})
    if terminal == "succeeded":
        # Wake the source node immediately. Its next signed /api/sync response
        # now includes the exact published receipt from repo_merge_jobs.
        await notify_repo_host(
            env, context["owner"], context["repo"], "mirror_merge")
    return _https_mirror_merge_response(result)


async def _https_mirror_proxy(
        env, request, owner, repo, operation, release_sha="", bypass_cache=False):
    """Stream a public read through healthy endpoints under the original URL."""
    context = await _https_mirror_public_context(env, owner, repo)
    if context is None:
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    # org_alias_rewrite gives access checks and pin selection the canonical
    # backing node. Repository bytes must still be requested from the gateway
    # under the untouched public organization identity. The rewrite preserves
    # request.url, so recover only an alias that D1 verifies maps to that node.
    try:
        original_url = urlparse(str(getattr(request, "url", "") or ""))
        original_match = (
            GIT_INFO_RE.match(original_url.path)
            or GIT_PACK_RE.match(original_url.path)
            or RELEASE_BLOB_RE.match(original_url.path)
            or REPO_HOST_RE.match(original_url.path)
        )
        route_owner = (
            safe_segment(original_match.group(1)) if original_match else "")
        route_repo = (
            safe_segment(original_match.group(2)) if original_match else "")
        if (
            route_owner
            and route_repo == context["repo"]
            and route_owner != context["owner"]
            and await _org_repo_node(
                env, route_owner, route_repo) == context["owner"]
        ):
            context = dict(context)
            context["routeOwner"] = route_owner
            context["repoBi"] = await blind_index(
                env, route_owner + "/" + route_repo)
    except Exception:
        pass
    method = method_name(request)
    if operation == "git-upload-pack" and method != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    if operation != "git-upload-pack" and method not in ("GET", "HEAD"):
        return json_response({"error": "method_not_allowed"}, status=405)
    query = _https_mirror_request_query(
        urlparse(request.url), operation, release_sha=release_sha)
    metadata_cache_key = (
        repository_metadata_cache_key(context, operation, query)
        if method == "GET" else ""
    )
    cached_metadata = (
        await repository_metadata_cache_get(metadata_cache_key)
        if not bypass_cache else None)
    if cached_metadata is not None:
        return cached_metadata
    body = b""
    if method == "POST":
        try:
            announced = int(request.headers.get("content-length") or 0)
        except Exception:
            announced = 0
        if announced > HTTPS_MIRROR_BODY_MAX_BYTES:
            return Response("request too large", status=413)
        try:
            body = bytes(await request.bytes())
        except Exception:
            return Response("invalid request body", status=400)
        if len(body) > HTTPS_MIRROR_BODY_MAX_BYTES:
            return Response("request too large", status=413)
    router_public_key = _https_mirror_router_public_key(env)
    router_seed = _https_mirror_router_seed(env)
    if not router_public_key or not router_seed:
        return json_response(
            {"error": "mirror_unavailable"}, status=503,
            cache_control="no-store")
    sticky = (
        await _https_mirror_clone_pin(env, context)
        if operation == "git-upload-pack" else "")
    candidates = await _https_mirror_candidates(
        env, context, world_request_country(request), sticky=sticky)
    if not candidates:
        return json_response(
            {"error": "mirror_unavailable"}, status=503,
            cache_control="no-store")
    from js import fetch as js_fetch
    for endpoint in candidates:
        if not await _https_mirror_repository_proof(
                env, endpoint, context, operation):
            continue
        target = https_routing.masked_target_url(
            endpoint["baseUrl"],
            context.get("routeOwner") or context["owner"],
            context["repo"],
            operation,
            query,
        )
        parsed_target = urlparse(target)
        signed_path = parsed_target.path + (
            ("?" + parsed_target.query) if parsed_target.query else "")
        body_digest = hashlib.sha256(body).hexdigest()
        request_id = _b64url_encode(_random_bytes(18))
        issued_at = int(Date.now())
        message = https_routing.request_message(
            endpoint["node"],
            method,
            signed_path,
            body_digest,
            request_id,
            issued_at,
        )
        signature = await ed25519_sign(
            router_public_key, router_seed, message.encode("utf-8"))
        if not target or not message or not signature:
            continue
        headers = {
            "X-ForkMesh-Node": endpoint["node"],
            "X-ForkMesh-Request-Id": request_id,
            "X-ForkMesh-Issued-At": str(issued_at),
            "X-ForkMesh-Body-Sha256": body_digest,
            "X-ForkMesh-Signature": signature,
        }
        if operation == "git-upload-pack":
            headers["Content-Type"] = (
                "application/x-git-upload-pack-request")
            encoding = request.headers.get("content-encoding")
            if encoding:
                headers["Content-Encoding"] = encoding
        init = {
            "method": method,
            "headers": headers,
            "redirect": "manual",
        }
        if method == "POST":
            init["body"] = Uint8Array.new(_to_js(body))
        try:
            upstream = await js_fetch_with_timeout(
                target, init, HTTPS_MIRROR_FETCH_TIMEOUT_SECONDS)
            status = int(getattr(upstream, "status", 0) or 0)
        except Exception:
            status = 0
            upstream = None
        if upstream is None or status in HTTPS_MIRROR_RETRY_STATUSES:
            # A fresh signed repository proof owns the endpoint's shared
            # integrity state. A request-local timeout, missing optional path,
            # or transient 5xx still fails over, but must not poison the
            # endpoint for every other visitor. Persistent availability is
            # re-evaluated by the signed health cron. Capability/auth rejection
            # remains a hard failure because the endpoint can no longer honor
            # requests signed by this router.
            if status in (401, 403):
                try:
                    await d1_run(
                        env,
                        """UPDATE mirror_https_endpoints
                              SET healthy=0,integrity='failed',
                                  forkmesh_active=0,updated_at=?
                            WHERE node_name=?""",
                        int(Date.now()), endpoint["node"])
                except Exception:
                    pass
            continue
        raw_headers = {}
        for name in (
            "content-type", "content-length", "content-range",
            "accept-ranges", "etag", "last-modified", "cache-control",
            "content-disposition",
        ):
            try:
                value = upstream.headers.get(name)
            except Exception:
                value = None
            if value is not None:
                raw_headers[name] = str(value)
        response_headers = https_routing.response_headers(raw_headers)
        # A public node name is safe operational provenance (it is already
        # listed on the repository's Mirrors tab). Attach it only to the live
        # upstream response that this request actually selected. Edge-held
        # metadata responses are rebuilt by repository_metadata_cache_get
        # without this header, so a cache hit can never falsely claim that a
        # particular mirror just served it.
        response_headers["X-ForkMesh-Served-By"] = endpoint["node"]
        await _https_mirror_route_advance(
            env, context, endpoint["node"], operation)
        if not bypass_cache:
            await repository_metadata_cache_put(
                metadata_cache_key, upstream, status)
        # The private endpoint origin remains masked. The public node identity
        # above is bounded routing provenance; repository bytes still stream
        # without being materialized by the Worker.
        return JsResponse.new(
            upstream.body,
            to_js({"status": status, "headers": response_headers}),
        )
    return json_response(
        {"error": "mirror_unavailable"}, status=503,
        cache_control="no-store")


class Default(WorkerEntrypoint):
    async def scheduled(self, controller, env, ctx):
        # Keep the platform Cron Trigger deliberately tiny. It starts (and then
        # once a minute reconciles) a singleton Durable Object alarm. The alarm
        # re-arms itself before work, so a stateless Python wrapper poisoned by
        # another request or a killed maintenance batch cannot stop the runner.
        await _cron_runner_kick(self.env)

    async def _run_scheduled_jobs(self, controller=None, env=None, ctx=None):
        # Cron trigger (every minute, see [triggers] in wrangler.toml).
        #
        # Only the two once-a-minute samples run on every tick; everything else
        # is staggered onto its own minute slot. Running all eight jobs plus
        # two Sentry round trips every minute — dozens of sequential D1 awaits
        # in a Pyodide worker, ~90 schema DDL statements first on a cold
        # isolate — routinely blew the invocation's resource limits, the
        # platform killed the tick with nothing logged, and the /status page
        # recorded the missing sample as downtime (~5% uptime shown while the
        # site was actually up). The samples also run FIRST, so even a tick
        # that dies in a later job has already landed its data point.
        cron_started_ms = int(Date.now())
        cron_failures = []
        minute = int(cron_started_ms // 60000)
        # Sentry cron monitor disabled for now (commented out on request).
        # The opening "in_progress" check-in and the closing ok/error check-in
        # below are left in place, commented, so the monitor can be re-enabled
        # by uncommenting both halves.
        #
        # cron_expression = _scheduled_cron_expression(controller)
        # cron_check_in_id = _sentry_event_id()
        # Send the "in_progress" check-in FIRST, before any D1/decrypt work,
        # so Sentry has proof this tick started even if the platform kills
        # the isolate later (cold Pyodide isolate blowing the invocation's
        # CPU/wall-clock budget - the same failure mode documented above for
        # /status samples). Without this, a killed tick sends nothing at all
        # and Sentry reports it as a "missed check-in" instead of a runtime
        # error, which is what actually happened; dropping the closing
        # ok/error check-in on the same check_in_id still only costs one
        # extra Sentry round trip per tick.
        # try:
        #     await capture_sentry_cron_check_in(
        #         self.env, "in_progress", check_in_id=cron_check_in_id,
        #         cron=cron_expression)
        # except BaseException:
        #     pass
        # The /status health sample runs FIRST: it is the cheapest job (no
        # row decryption) and the one whose absence shows publicly as fake
        # downtime, so a tick that dies partway (cold Pyodide isolate blowing
        # the invocation limits — cron runs in its own colo, where user
        # traffic never warms the isolate) has already landed its samples.
        try:
            await record_status_sample(self.env)
        except BaseException as error:
            await log_cron_error(
                self.env, "/cron/record-status-sample",
                "record_status_sample failed: " + _safe_error_text(error),
                error=error, failures=cron_failures)
        # Online-node sample for the /network/ activity graph (heavier: joins
        # + AES-GCM row decrypts per live host).
        try:
            await record_online_sample(self.env)
        except BaseException as error:
            await log_cron_error(
                self.env, "/cron/record-online-sample",
                "record_online_sample failed: " + _safe_error_text(error),
                error=error, failures=cron_failures)
        # Oldest-first bounded signed challenges keep direct HTTPS endpoints
        # inside the two-minute routing freshness window. This moves no
        # repository content: only identity, latency, integrity, and the
        # forkmesh/forkmesh refs proof are retained.
        try:
            await https_mirror_health_cron(self.env)
        except BaseException as error:
            await log_cron_error(
                self.env, "/cron/https-mirror-health",
                "https_mirror_health_cron failed: "
                + _safe_error_text(error),
                error=error, failures=cron_failures)
        # Public CelesTrak VISUAL OMM data changes slowly. One fixed-source
        # refresh every three hours (with an additional two-hour D1 guard)
        # keeps positions current without per-visitor upstream traffic or a
        # quota-burning minute poll. Expected upstream failures retain the
        # last-good snapshot and return normally; only local runtime/D1 faults
        # reach the bounded cron error log.
        if (
            minute % WORLD_SATELLITE_REFRESH_CRON_MINUTES
            == WORLD_SATELLITE_REFRESH_CRON_OFFSET
        ):
            try:
                await refresh_world_satellite_snapshot(
                    self.env, cron_started_ms)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/world-satellites",
                    "world satellite refresh failed: "
                    + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Confirm externally signed reward plans. This job only reads finalized
        # transactions and checks their exact System Program transfer list; it
        # has no signing key and never broadcasts a transaction.
        if minute % 5 == 1:
            try:
                await verify_submitted_chain_intents(self.env)
                await verify_submitted_reward_contributions(self.env)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/verify-reward-intents",
                    "reward finality verification failed: "
                    + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # ActivityPub outbound delivery: the publish path already best-effort
        # sends a few activities inline, this drains the retry backlog (one
        # cheap indexed SELECT when the queue is empty).
        if minute % 5 == 0:
            try:
                await ensure_schema(self.env)
                await _ap_drain_outbox(self.env, AP_CRON_DELIVERIES)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/activitypub-deliver",
                    "_ap_drain_outbox failed: " + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Automatic Fediverse activity is combined per repo/org alias and is
        # eligible no more than once per 24 hours. Processing is bounded and
        # only creates durable Notes/outbox rows; the normal delivery drain
        # above retains its established Retry-After/exponential backoff policy.
        if minute % 10 == 8:
            try:
                await ensure_schema(self.env)
                await _ap_process_digest_queues(
                    self.env, AP_DIGEST_CRON_BATCH)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/activitypub-digests",
                    "_ap_process_digest_queues failed: "
                    + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Follower presentation backfill: a repo's follower gallery shows each
        # account's published avatar and bio, which only lands in the cache when
        # that actor is next fetched. Three signed GETs every 20 minutes fills
        # the backlog in the background (one indexed SELECT when there is none).
        if minute % 20 == 12:
            try:
                await ensure_schema(self.env)
                await _ap_refresh_follower_profiles(
                    self.env, AP_PROFILE_REFRESH_BATCH,
                    (minute // 20) % AP_PROFILE_REFRESH_WINDOWS)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/activitypub-follower-profiles",
                    "_ap_refresh_follower_profiles failed: "
                    + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Relay federation: a federated relay registers + reports its online
        # nodes to the main relay (two outbound HTTP calls); the main relay
        # expires stale federated presence and sweeps confirmed signups.
        if minute % 5 == 2:
            try:
                await ensure_schema(self.env)
                await _federation_cron(self.env)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/federation-cron",
                    "federation_cron failed: " + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Email digest bridge (issue #361): per-recipient interval + min-age
        # gates inside already hold a digest back for several minutes, so a
        # 5-minute cadence adds no user-visible latency.
        if minute % 5 == 3:
            try:
                await send_notification_digests(self.env)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/send-notification-digests",
                    "send_notification_digests failed: " + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Stale-node housekeeping expires transient presence and removes only
        # orphaned physical registrations. Repository/endpoint-backed nodes
        # remain as offline catalog identity until fresh evidence returns.
        if minute % 15 == 4:
            try:
                await purge_stale_registered_nodes(self.env, force=True)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/purge-stale-nodes",
                    "purge_stale_registered_nodes failed: " + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Keep blocked phantom catalog entries (and their host presence) purged
        # even if no one loads /network/.
        if minute % 15 == 9:
            try:
                await purge_blocked_catalog(self.env)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/purge-blocked-catalog",
                    "purge_blocked_catalog failed: " + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Community reward pool: prepare an unsigned round about once an hour
        # (interval gate inside). The owner-device signer remains the only
        # component that can approve and broadcast the exact plan.
        if minute % 15 == 14:
            try:
                await ensure_schema(self.env)
                await _distribute_central_fund(self.env)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/distribute-central-fund",
                    "distribute_central_fund failed: " + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Retained chat history is only pruned per-room on client join
        # (ForkMeshRoom.fetch); sweep all rooms hourly so an idle room still
        # gets its 7-day-old messages deleted.
        if minute % 60 == 37:
            try:
                await chat_history_prune_expired(self.env)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/chat-history-prune-expired",
                    "chat_history_prune_expired failed: " + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Hourly: prune the reinstall/rotate account_devices sprawl (stale,
        # superseded keys), never an account's current signing key.
        if minute % 60 == 47:
            try:
                await ensure_schema(self.env)
                await purge_stale_account_devices(self.env)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/purge-stale-account-devices",
                    "purge_stale_account_devices failed: " + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Hourly: bound the inbound-website board. Referer headers are
        # attacker-controlled, so the long tail a spammer could grow is
        # dropped and only the busiest hosts are retained.
        if minute % 60 == 17:
            try:
                await prune_site_referrers(self.env)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/prune-site-referrers",
                    "prune_site_referrers failed: " + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Hourly organization-succession warning pass. It reads only the
        # configured owner's generalized activity maximum and emits at most one
        # deduplicated warning per inactivity deadline. It never opens a grace
        # case or transfers a role automatically.
        if minute % 60 == 42:
            try:
                await process_organization_succession_warnings(self.env)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/organization-succession-warnings",
                    "organization succession warning pass failed: "
                    + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Hourly retention for metadata-only sensitive-action audit records,
        # plus expiration of pending reward allocations.
        if minute % 60 == 52:
            try:
                await cleanup_sensitive_audit_records(self.env)
                await expire_pending_rewards(self.env)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/cleanup-sensitive-audit-records",
                    "cleanup_sensitive_audit_records failed: "
                    + _safe_error_text(error),
                    error=error, failures=cron_failures)
            try:
                await cleanup_world_media_records(self.env)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/cleanup-world-media-records",
                    "cleanup_world_media_records failed: "
                    + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Hourly: the once-per-user "How are we doing?" founder feedback email
        # for accounts that crossed the 24h-after-signup mark (batched; also
        # back-fills accounts that signed up before this feature shipped).
        if minute % 60 == 22:
            try:
                await _send_feedback_emails(self.env)
            except BaseException as error:
                await log_cron_error(
                    self.env, "/cron/feedback-emails",
                    "_send_feedback_emails failed: " + _safe_error_text(error),
                    error=error, failures=cron_failures)
        # Arm the independent liveness alarm only after the complete scheduled
        # handler reached its end. If Pyodide re-enters the event loop, the
        # platform kills the invocation, or a future uncaught exception escapes,
        # no heartbeat lands and the Durable Object can alert without relying on
        # this broken Cron Trigger to detect its own failure. The next completed
        # tick sends the one-time recovery message.
        try:
            await _cron_watchdog_completion(self.env)
        except BaseException as error:
            await log_cron_error(
                self.env, "/cron/watchdog-completion",
                "cron watchdog completion failed: " + _safe_error_text(error),
                error=error, failures=cron_failures)
        # Closing check-in for the same check_in_id sent above, so Sentry
        # resolves the "in_progress" marker to a final ok/error result.
        # Sentry cron monitor disabled for now (commented out on request);
        # re-enable together with the opening check-in above.
        # final_cron_status = "error" if cron_failures else "ok"
        # await capture_sentry_cron_check_in(
        #     self.env, final_cron_status, check_in_id=cron_check_in_id,
        #     cron=cron_expression,
        #     duration=(int(Date.now()) - cron_started_ms) / 1000)

    async def fetch(self, request):
        url = None
        try:
            url = urlparse(request.url)

            # Admin error dashboard at a secret, env-configured path. Its 401/403
            # responses are not logged, but unexpected exceptions are captured.
            admin_path = _admin_path(self.env)
            if admin_path and url.path.strip("/") == admin_path:
                return await self._admin(request)

            response = await self._route(request, url)
        except RequestBodyTooLarge:
            response = json_response(
                {"error": "request_too_large"},
                status=413,
                cache_control="no-store, max-age=0, must-revalidate",
            )
        except Exception as error:
            if str(error) == "legacy_custody_migration_required":
                return _legacy_custody_not_ready_response()
            try:
                await capture_worker_exception(self.env, request, url, error)
            except BaseException:
                pass
            # Re-raise so Cloudflare records the native Worker failure/Error 1101
            # while Sentry keeps the underlying Python exception and stack trace.
            raise
        try:
            status = int(getattr(response, "status", 200) or 200)
        except Exception:
            status = 200
        # Credit the website that sent this visitor. Gated to served page
        # navigations carrying an external Referer, so the extra D1 write only
        # happens on the rare request that is actually an inbound referral.
        await record_site_referral(self.env, request, url, status)
        # Blog reach is recorded from the same successfully served top-level
        # navigation. It stores totals, a fixed aggregate HLL projection and
        # per-post referring-host counters only.
        await record_blog_visit(self.env, request, url, status)
        if status >= 500:
            # An offline node's content being re-requested (502/503/504 on a
            # tunnel path) is expected in a P2P network — host_presence and
            # the /status git_hosting signal already reflect it. Logging every
            # hit cost a blocking Sentry call + a D1 write per response (a
            # single offline node's release blob generated hundreds of noise
            # rows a day and drowned out real failures). A 500 on the same
            # path is a real worker bug and still logs.
            if status in (502, 503, 504) and _is_tunnel_content_path(url.path):
                return response
            # Deliberate degraded answers (DO aborts already recorded with
            # their real reason, fail-closed 501s, unavailable upstreams) are
            # marked at the source; re-logging them as anonymous "response
            # status N" events only buried real bugs.
            if _response_is_expected_degraded(response):
                return response
            await log_error(
                self.env, status, method_name(request), url.path,
                "response status %d" % status, request.headers.get("cf-ray") or "",
                request=request,
            )
        return response

    async def _admin(self, request):
        await ensure_schema(self.env)
        if not await _check_admin_page_auth(self.env, request):
            if method_name(request) == "GET":
                url = urlparse(request.url)
                next_path = url.path + (("?" + url.query) if url.query else "")
                return Response(
                    "Admin login required.",
                    status=302,
                    headers={
                        "location": "/login?next=" + quote(next_path),
                        "cache-control": "no-store, max-age=0, must-revalidate",
                        "content-type": "text/plain; charset=utf-8",
                    },
                )
            return Response(
                "Admin account required.",
                status=403,
                headers={
                    "cache-control": "no-store, max-age=0, must-revalidate",
                    "content-type": "text/plain; charset=utf-8",
                },
            )
        params = parse_qs(urlparse(request.url).query)
        # Nav links carry ?admin= for continuity; fall back to the cookie's
        # name when the page was opened without the param (adhoc #168).
        account_cookie_name = await _account_cookie_name(self.env, request)
        admin_query = _admin_query(
            params.get("admin", [""])[0] or account_cookie_name)

        # POST action ?action=disburse reports migration-only custody status;
        # ?action=set_password resets a user account's login password. Every
        # state-changing POST must carry a CSRF token rendered into the admin
        # page, so a cross-site form cannot trigger these actions.
        banner = ""
        action = params.get("action", [""])[0]
        audit_details = {}
        csrf_field = ('<input type="hidden" name="csrf" value="%s">'
                      % _html_escape(_admin_csrf_token(self.env)))
        if method_name(request) == "POST":
            try:
                form = parse_qs(await request.text(), keep_blank_values=True)
            except Exception:
                form = {}
            if not _admin_csrf_ok(self.env, form):
                banner = ("Action blocked: invalid or missing CSRF token. "
                          "Reload the admin page and try again.")
            elif action == "disburse":
                try:
                    banner = await _admin_disburse(self.env)
                except Exception as error:
                    banner = "Disburse failed: " + repr(error)
            elif action == "set_password":
                try:
                    banner = await _admin_set_password(
                        self.env,
                        form.get("name", [""])[0],
                        form.get("password", [""])[0],
                    )
                except Exception as error:
                    banner = "Set password failed: " + repr(error)
            elif action == "resend_verify":
                try:
                    banner = await _admin_resend_verification(
                        self.env,
                        request,
                        form.get("name", [""])[0],
                    )
                except Exception as error:
                    banner = "Resend verify email failed: " + repr(error)
            elif action == "request_ownership":
                try:
                    banner = await _admin_console_request_ownership(
                        self.env,
                        form.get("target", [""])[0],
                        form.get("owner", [""])[0],
                    )
                except Exception as error:
                    banner = "Ownership request failed: " + repr(error)
            elif action == "set_operational_alerts":
                try:
                    enabled = form.get("enabled", [""])[0] == "1"
                    current_alerts = await _repo_alert_settings_get(
                        self.env, *FLAGSHIP_MONITOR_ID.split("/", 1))
                    updated_alerts = dict(current_alerts)
                    updated_alerts["statusEmails"] = enabled
                    await d1_run(
                        self.env,
                        "INSERT INTO repo_alert_settings "
                        "(repo_bi, data, updated_at) VALUES (?,?,?) "
                        "ON CONFLICT(repo_bi) DO UPDATE SET "
                        "data=excluded.data, updated_at=excluded.updated_at",
                        await _repo_alert_settings_bi(
                            self.env,
                            *FLAGSHIP_MONITOR_ID.split("/", 1)),
                        json.dumps(updated_alerts), int(Date.now()))
                    banner = (
                        "Operational alert email is now " +
                        ("enabled." if enabled else "disabled."))
                    audit_details = {"enabled": enabled}
                except Exception as error:
                    banner = (
                        "Operational alert update failed: " + repr(error))
            elif action == "set_repo_terms_flag":
                try:
                    owner = safe_segment(
                        form.get("owner", [""])[0]).lower()
                    repo = safe_segment(
                        form.get("repo", [""])[0]).lower()
                    category = clean_string(
                        form.get("category", [""])[0], 20).lower()
                    note = clean_string(form.get("note", [""])[0], 500)
                    clear = form.get("clear", [""])[0] == "1"
                    if (
                        not owner
                        or not repo
                        or category not in (
                            "spam", "malware", "harassment",
                            "illegal", "other",
                        )
                        or (not clear and not note)
                    ):
                        banner = "Repository Terms flag failed: invalid fields."
                    else:
                        repo_bi = await blind_index(
                            self.env, owner + "/" + repo)
                        exists = await d1_first(
                            self.env,
                            "SELECT 1 AS found FROM repositories "
                            "WHERE key_bi=? LIMIT 1",
                            repo_bi,
                        )
                        if not exists:
                            banner = (
                                "Repository Terms flag failed: repository "
                                "was not found."
                            )
                        else:
                            await d1_run(
                                self.env,
                                "INSERT INTO repo_terms_flags "
                                "(repo_bi,active,category,data,updated_by_bi,"
                                "updated_at) VALUES (?,?,?,?,?,?) "
                                "ON CONFLICT(repo_bi) DO UPDATE SET "
                                "active=excluded.active,"
                                "category=excluded.category,"
                                "data=excluded.data,"
                                "updated_by_bi=excluded.updated_by_bi,"
                                "updated_at=excluded.updated_at",
                                repo_bi,
                                0 if clear else 1,
                                category,
                                await encrypt_row(self.env, {
                                    "note": note,
                                    "actor": account_cookie_name,
                                }),
                                await blind_index(
                                    self.env, account_cookie_name),
                                int(Date.now()),
                            )
                            await purge_catalog_related_caches()
                            banner = (
                                "Repository Terms flag cleared."
                                if clear
                                else "Repository Terms flag applied."
                            )
                            audit_details = {
                                "active": not clear,
                                "category": category,
                            }
                except Exception as error:
                    banner = "Repository Terms flag failed: " + repr(error)
            elif action == "delete_rows":
                try:
                    tables = await _admin_list_tables(self.env)
                    table = params.get("table", [""])[0]
                    ids = [int(x) for x in form.get("ids", []) if str(x).isdigit()]
                    if table not in tables:
                        banner = "Delete failed: unknown table."
                    elif not _admin_purge_allowed(table):
                        banner = (
                            "Delete blocked: this table is read-only in the "
                            "generic administration browser."
                        )
                    elif not ids:
                        banner = "Delete: no rows were selected."
                    elif await _admin_selected_rows_have_wallet_keys(
                            self.env, table, ids):
                        banner = (
                            "Delete blocked: a selected row contains frozen "
                            "legacy wallet custody material. Use the explicit "
                            "offline migration."
                        )
                    else:
                        audit_details = {
                            "rowCount": len(ids),
                            "rowDigestBefore": (
                                await _admin_selected_rows_digest(
                                    self.env, table, ids
                                )
                            ),
                        }
                        # D1 caps bound parameters per query (~100), so delete in
                        # chunks rather than one giant IN (...) list.
                        chunk = 90
                        for start in range(0, len(ids), chunk):
                            batch = ids[start:start + chunk]
                            placeholders = ",".join(["?"] * len(batch))
                            await d1_run(
                                self.env,
                                "DELETE FROM " + table
                                + " WHERE rowid IN (" + placeholders + ")",
                                *batch,
                            )
                        banner = "Deleted %d row(s) from %s." % (len(ids), table)
                except Exception as error:
                    banner = "Delete failed: " + repr(error)
            elif action in ("update_row", "insert_row"):
                try:
                    tables = await _admin_list_tables(self.env)
                    table = params.get("table", [""])[0]
                    if table not in tables:
                        banner = "Save failed: unknown table."
                    else:
                        banner = (
                            "Save blocked: generic database mutation is "
                            "disabled; use a purpose-built audited action."
                        )
                except Exception as error:
                    banner = "Save failed: " + repr(error)

            if action in (
                    "disburse", "set_password", "resend_verify",
                    "request_ownership", "delete_rows", "update_row",
                    "insert_row", "set_operational_alerts",
                    "set_repo_terms_flag"):
                audit_actor = (
                    account_cookie_name
                    or params.get("admin", [""])[0])
                target_type = (
                    "account" if action in (
                        "set_password", "resend_verify",
                        "request_ownership")
                    else "platform_alerts"
                    if action == "set_operational_alerts"
                    else "repository"
                    if action == "set_repo_terms_flag"
                    else "database_table" if action in (
                        "delete_rows", "update_row", "insert_row")
                    else "legacy_custody")
                target = (
                    form.get("name", [""])[0] if action in (
                        "set_password", "resend_verify")
                    else form.get("target", [""])[0]
                    if action == "request_ownership"
                    else "forkmesh-system-checks"
                    if action == "set_operational_alerts"
                    else (
                        form.get("owner", [""])[0] + "/"
                        + form.get("repo", [""])[0]
                    )
                    if action == "set_repo_terms_flag"
                    else params.get("table", [""])[0])
                lowered_banner = str(banner or "").lower()
                outcome = (
                    "denied" if "blocked" in lowered_banner
                    else "failed" if "failed" in lowered_banner
                    else "success")
                await _audit_sensitive_action(
                    self.env, audit_actor, "admin.console_" + action,
                    target_type, target, outcome,
                    audit_details)

        # Left-nav table browser: pick the requested table (validated against the
        # live list), defaulting to the error log.
        tables = await _admin_list_tables(self.env)
        requested = params.get("table", [""])[0]
        if requested in tables:
            active = requested
        elif "error_log" in tables:
            active = "error_log"
        else:
            active = tables[0] if tables else ""

        # Edit/create forms are full-page GET views for the active table.
        if action == "edit" and active:
            rowid = params.get("rowid", [""])[0]
            table_html = await _render_row_form(
                self.env, active, rowid, csrf_field, admin_query)
        elif action == "new" and active:
            table_html = await _render_row_form(
                self.env, active, None, csrf_field, admin_query)
        else:
            table_html = (await _render_table_view(
                              self.env, active, csrf_field, admin_query)
                          if active
                          else '<div class="empty">No tables found.</div>')

        # Row counts for the left nav.
        counts = {}
        for t in tables:
            try:
                row = await d1_first(self.env, "SELECT COUNT(*) AS n FROM " + t)
                counts[t] = int((row or {}).get("n", 0) or 0)
            except Exception:
                counts[t] = 0
        stats = await admin_stats(self.env)
        operational_alerts_enabled = await _status_alert_emails_enabled(
            self.env)
        # Default the table browser to most-records-first; ?sort=name opts back
        # into the A–Z ordering.
        sort_records = params.get("sort", [""])[0] != "name"
        return Response(
            render_admin_html(stats, tables, active, table_html, banner, counts,
                              csrf_field=csrf_field, admin_query=admin_query,
                              sort_records=sort_records,
                              operational_alerts_enabled=(
                                  operational_alerts_enabled)),
            status=200,
            headers={"content-type": "text/html; charset=utf-8"},
        )

    async def _route(self, request, url):
        if url.path.rstrip("/") == HTTPS_MIRROR_ENDPOINT_PATH:
            return await https_mirror_endpoint_handler(self.env, request)
        if url.path.rstrip("/") == HTTPS_MIRROR_PRIVATE_ROUTE_PATH:
            return await https_mirror_private_route_handler(self.env, request)
        if url.path.rstrip("/") == "/api/ssh/authorize":
            return await ssh_gateway_authorize_handler(self.env, request)

        private_access_match = PRIVATE_REPLICA_ACCESS_RE.match(url.path)
        if private_access_match:
            return await _https_mirror_private_access_handler(
                self.env, request, url, private_access_match.group(1))

        # Organization repo aliases (issue #388): rewrite /<org>/<repo> git and
        # /api/repo/<org>/<repo>/... requests to the linked node's namespace
        # before any route matching — see org_alias_rewrite.
        aliased = await org_alias_rewrite(self.env, request, url)
        if aliased is not None:
            request, url = aliased

        # Public clone traffic uses signed, masked HTTPS. Private/missing paths
        # fail closed in _git_host. Private clients use only the identity-free
        # opaque endpoint above; named Git paths never advertise or proxy it.
        git_info = GIT_INFO_RE.match(url.path)
        if git_info:
            service = parse_qs(url.query).get("service", [""])[0]
            if service == "git-upload-pack":
                owner = safe_segment(git_info.group(1))
                repo = safe_segment(git_info.group(2))
                if (
                    owner and repo
                    and not await _repo_is_private(self.env, owner, repo)
                ):
                    return await _https_mirror_proxy(
                        self.env, request, owner, repo, "git-info-refs")
                return await self._git_host(request, owner, repo)
            if service == "git-receive-pack":
                return await self._git_push(
                    request, git_info.group(1), git_info.group(2))
        git_pack = GIT_PACK_RE.match(url.path)
        if git_pack and method_name(request) == "POST":
            owner = safe_segment(git_pack.group(1))
            repo = safe_segment(git_pack.group(2))
            if (
                owner and repo
                and not await _repo_is_private(self.env, owner, repo)
            ):
                return await _https_mirror_proxy(
                    self.env, request, owner, repo, "git-upload-pack")
            return await self._git_host(request, owner, repo)
        git_recv = GIT_RECEIVE_RE.match(url.path)
        if git_recv and method_name(request) == "POST":
            return await self._git_push(request, git_recv.group(1), git_recv.group(2))

        if url.path == "/" and method_name(request) in ("GET", "HEAD"):
            # Everyone enters the same world immediately. The app may use the
            # locally held session to render an authorized avatar and portals,
            # but the route itself never changes based on login state.
            return await self._serve_homepage(url)

        if url.path in BLOCKED_STATIC_HTML_PATHS:
            return await self._serve_not_found_page(url)

        if url.path in (
                blog_feed.FEED_PATH, "/blog/feed.xml",
                "/rss.xml", "/feed.xml"):
            return await blog_rss_handler(self.env, request)

        if url.path in ("/health", "/api/mainnode"):
            return json_response(
                {
                    "ok": True,
                    "service": "forkmesh-mainnode",
                    "node": getattr(self.env, "NODE_NAME", "forkmesh"),
                    "nodeSolanaAddress": getattr(self.env, "NODE_SOLANA_ADDRESS", ""),
                    "websocket": "/api/repo/{owner}/{repo}/rooms/{room}/ws",
                    "compatWebsocket": "/api/room/{room}/ws",
                    "capabilities": [
                        "encrypted-relay-rooms",
                        "repo-scoped-rooms",
                        "ephemeral-ciphertext-broadcast",
                    ],
                    "runtime": "python-workers",
                }
            )

        # Build/version marker for deploy verification. deploy.sh stamps BUILD_REV
        # (the git rev being shipped) as a Worker var on every production deploy and
        # then polls this endpoint: if the live rev never flips to the one it just
        # built, the upload didn't actually take effect on this origin (e.g. it hit
        # the wrong Cloudflare account — the account drift that let stale code keep
        # serving while the deploy reported success), and the script aborts loudly
        # instead of reporting a phantom success.
        if url.path in ("/api/version", "/api/version/"):
            return json_response(
                {
                    "ok": True,
                    "rev": _build_rev(self.env),
                    # deploy.sh stamps APP_VERSION (qt_client release number)
                    # alongside BUILD_REV; the dashboard header chip renders
                    # it. It was documented as echoed here but never was —
                    # which also left the chip's sessionStorage cache
                    # unreachable, so every page navigation refetched this.
                    "version": str(
                        getattr(self.env, "APP_VERSION", "") or ""),
                    "now": Date.now(),
                }
            )

        if url.path in ("/api/world/context", "/api/world/context/"):
            return world_context_handler(request)

        if url.path in ("/api/world/ticket", "/api/world/ticket/"):
            return await world_ticket_handler(self.env, request)

        if url.path in ("/api/world/client", "/api/world/client/"):
            return await world_client_profile_handler(self.env, request)

        if url.path in ("/api/world/inactive", "/api/world/inactive/"):
            return await world_inactive_handler(self.env, request)

        if url.path in ("/api/world/wallet", "/api/world/wallet/"):
            return await world_wallet_badge_handler(self.env, request)

        if url.path in ("/api/world/visitors", "/api/world/visitors/"):
            return await world_visitors_handler(self.env, request)

        if url.path in (
                "/api/world/social-posts", "/api/world/social-posts/"):
            return await world_social_posts_handler(self.env, request)

        if url.path in (
                "/api/world/satellites", "/api/world/satellites/"):
            return await world_satellites_handler(self.env, request)

        if url.path in ("/api/world/layout", "/api/world/layout/"):
            return await world_layout_handler(self.env, request)

        if url.path in (
                "/api/world/organizations",
                "/api/world/organizations/"):
            return await world_organizations_handler(self.env, request)
        if url.path in (
                "/api/world/instances",
                "/api/world/instances/"):
            return await world_relay_instances_handler(self.env, request)

        if (url.path == "/api/world/fediverse"
                or url.path == "/api/world/fediverse/"
                or url.path.startswith("/api/world/fediverse/")):
            return await world_fediverse_directory_handler(
                self.env, request, url.path)

        if (url.path == "/api/world/media"
                or url.path == "/api/world/media/"
                or url.path.startswith("/api/world/media/")):
            return await world_media_handler(
                self.env, request, url.path)

        if (url.path == "/api/world/events"
                or url.path == "/api/world/events/"
                or url.path.startswith("/api/world/events/")):
            return await world_events_handler(
                self.env, request, url.path)

        if (url.path == "/api/world/workshops"
                or url.path == "/api/world/workshops/"
                or url.path.startswith("/api/world/workshops/")):
            return await world_workshops_handler(
                self.env, request, url.path)

        if (url.path == "/api/world/community-ads"
                or url.path == "/api/world/community-ads/"
                or url.path.startswith("/api/world/community-ads/")):
            return await world_community_ads_handler(
                self.env, request, url.path)

        if (url.path == "/api/world/fediverse-mentions"
                or url.path == "/api/world/fediverse-mentions/"
                or url.path.startswith(
                    "/api/world/fediverse-mentions/")):
            return await world_fediverse_mentions_handler(
                self.env, request, url.path)

        if url.path in (
                "/api/world/moderation", "/api/world/moderation/"):
            return await world_moderation_handler(self.env, request)

        if url.path in (
                "/api/world/admin/nodes/delete",
                "/api/world/admin/nodes/delete/"):
            return await world_admin_delete_node_handler(self.env, request)

        if (
            url.path == "/api/world/office/marketing-tasks"
            or url.path == "/api/world/office/marketing-tasks/"
            or url.path.startswith("/api/world/office/marketing-tasks/")
        ):
            return await world_office_marketing_tasks_handler(
                self.env, request, url.path)

        if url.path in (
                "/api/world/build-board", "/api/world/build-board/"):
            return await world_build_board_handler(
                self.env, request, url.path)

        if url.path in (
                "/api/world/deploy-status", "/api/world/deploy-status/"):
            return await world_deploy_status_handler(self.env, request)

        if url.path in ("/api/world/qa", "/api/world/qa/"):
            return await world_qa_handler(self.env, request)

        if url.path in (
                "/api/world/preferences", "/api/world/preferences/"):
            return await world_preferences_handler(self.env, request)

        if url.path in (
                "/api/world/office/attendance",
                "/api/world/office/attendance/"):
            return await office_attendance_handler(self.env, request)

        if url.path in (
                "/api/world/office/general/status",
                "/api/world/office/general/status/"):
            return await office_general_status_handler(self.env, request)

        if url.path in (
                "/api/world/office/general/entry",
                "/api/world/office/general/entry/"):
            return await office_general_entry_handler(self.env, request)

        if url.path in (
                "/api/world/office/floors",
                "/api/world/office/floors/"):
            return await office_floor_access_handler(self.env, request)

        if url.path in (
                "/api/world/office/general/access",
                "/api/world/office/general/access/"):
            return await office_general_access_handler(self.env, request)

        if url.path in (
                "/api/world/office/general/ws",
                "/api/world/office/general/ws/"):
            return await _office_general_socket_handler(self.env, request)

        office_channel_socket = OFFICE_CHANNEL_WS_RE.fullmatch(url.path)
        if office_channel_socket:
            return await _office_channel_socket_handler(
                self.env, request, office_channel_socket.group(1))

        if url.path in ("/api/world/online", "/api/world/online/"):
            if method_name(request) != "GET":
                return json_response(
                    {"error": "method_not_allowed"},
                    status=405,
                    extra_headers={"allow": "GET"},
                )
            world_id = self.env.FORKMESH_WORLD.idFromName("town-square-v1")
            try:
                return await self.env.FORKMESH_WORLD.get(world_id).fetch(
                    JsRequest.new(
                        str(request.url),
                        to_js({"method": "GET"}),
                    )
                )
            except Exception:
                return json_response(
                    {"ok": False, "online": 0, "error": "unavailable"},
                    status=503,
                    extra_headers=EXPECTED_DEGRADED_HEADERS,
                )

        if url.path in ("/api/world/ws", "/api/world/ws/"):
            if method_name(request) != "GET":
                return json_response(
                    {"error": "method_not_allowed"},
                    status=405,
                    extra_headers={"allow": "GET"},
                )
            if not world_websocket_origin_allowed(request):
                return json_response({"error": "origin_not_allowed"}, status=403)
            query = parse_qs(url.query, keep_blank_values=False)
            ticket_values = query.get("ticket") or []
            trusted_claim = (
                _world_ticket_decode(self.env, ticket_values[0])
                if len(ticket_values) == 1 else None
            )
            if ticket_values and not trusted_claim:
                return json_response(
                    {"error": "invalid_world_session"},
                    status=401,
                    cache_control="no-store, max-age=0, must-revalidate",
                )
            if trusted_claim:
                try:
                    _account_bi, session_record = (
                        await _account_session_record(
                            self.env, request))
                    session_name = world_protocol.clean_display_name(
                        (session_record or {}).get("name"), "")
                    ticket_name = world_protocol.clean_display_name(
                        trusted_claim.get("name"), "")
                except Exception:
                    session_record = None
                    session_name = ""
                    ticket_name = ""
                if (
                    not session_record
                    or not session_name
                    or not hmac.compare_digest(
                        session_name.lower(), ticket_name.lower())
                ):
                    return json_response(
                        {"error": "invalid_world_session"},
                        status=401,
                        cache_control=(
                            "no-store, max-age=0, must-revalidate"),
                    )
            moderation_tokens = await _world_moderation_tokens(
                self.env, request)
            active_block = await _world_active_manual_block(
                self.env, moderation_tokens)
            if active_block:
                return json_response(
                    {
                        "error": "world_temporarily_blocked",
                        "targetType": active_block["targetType"],
                        "expiresAt": active_block["expiresAt"],
                        "notice": (
                            "This is a temporary manual administrator action; "
                            "it is not an automated abuse or quarantine result."
                        ),
                    },
                    status=403,
                    cache_control="no-store, max-age=0, must-revalidate",
                )
            world_id = self.env.FORKMESH_WORLD.idFromName("town-square-v1")
            last_error = None
            for _attempt in range(2):
                world_object = self.env.FORKMESH_WORLD.get(world_id)
                try:
                    return await world_object.fetch(
                        await world_durable_object_request(
                            request, trusted_claim, moderation_tokens))
                except Exception as error:
                    last_error = error
            await log_durable_object_abort(
                self.env, request, url.path, last_error)
            return json_response(
                {"error": "unavailable"}, status=503,
                extra_headers=EXPECTED_DEGRADED_HEADERS)

        if url.path in ("/simulate-sentry-error", "/simulate-sentry-error/"):
            division_by_zero = 1 / 0
            return json_response({"ok": False, "value": division_by_zero})

        # Cached aggregate stats for the homepage/network page. Served before the
        # per-repo handlers so a burst of visitors collapses to one computation
        # per colo per TTL instead of a Durable Object fan-out per page view.
        if url.path in ("/api/network/overview", "/api/network/overview/"):
            return await network_overview(self.env)

        if url.path in ("/api/network/stats", "/api/network/stats/"):
            include_payouts = parse_qs(url.query).get("payouts", [""])[0] == "1"
            return await network_stats(self.env, include_payouts=include_payouts)

        # 24-hour online-activity series for the /network/ graph.
        if url.path in ("/api/network/online-history", "/api/network/online-history/"):
            return await online_history(self.env)

        # Public ranking boards (node uptime + repos per owner) for /network/.
        if url.path in ("/api/network/leaderboards", "/api/network/leaderboards/"):
            return await network_leaderboards(self.env)

        # Referral-program board (clicks + signups per share link) for the
        # /referrals page and the World's referral leaderboard sign.
        if url.path in ("/api/referrals/leaderboard", "/api/referrals/leaderboard/"):
            return await referral_leaderboard(self.env)

        # Inbound website board (visits per referring hostname) for the
        # /referrals page.
        if url.path in ("/api/referrals/sites", "/api/referrals/sites/"):
            return await site_referrer_leaderboard(self.env)

        blog_metrics_prefix = "/api/blog/metrics/"
        if url.path.startswith(blog_metrics_prefix):
            slug = unquote(url.path[len(blog_metrics_prefix):]).strip("/")
            if method_name(request) != "GET":
                return json_response(
                    {"error": "method_not_allowed"}, status=405,
                    extra_headers={"allow": "GET"})
            return await blog_post_metrics(self.env, slug)

        # Rendered share-link card (og:image of the /r/<name> preview page).
        referral_card_match = REFERRAL_CARD_RE.match(url.path)
        if referral_card_match:
            return await referral_card_handler(
                self.env, request, unquote(referral_card_match.group(1)))

        # 30-day per-system uptime history for the public /status page.
        if url.path in ("/api/status", "/api/status/"):
            status_view = parse_qs(url.query).get("view", ["full"])[0]
            return await status_history(
                self.env, "world" if status_view == "world" else "full")

        # Installer clone source: pick the currently-online forkmesh host with
        # the most retained uptime instead of baking one node id into install.sh.
        if url.path in ("/api/install-source", "/api/install-source/"):
            return await install_source(self.env)

        # Anonymous per-step diagnostics posted by install.sh (no auth, no IP).
        if url.path in ("/api/install-diag", "/api/install-diag/"):
            return await install_diag_handler(self.env, request)

        # Anonymous docs/page feedback: like/dislike clicks with optional text.
        if url.path in ("/api/feedback", "/api/feedback/"):
            return await feedback_handler(self.env, request)

        # Private vulnerability reports — stored encrypted, emailed to security@.
        if url.path in ("/api/security/report", "/api/security/report/"):
            return await security_report_handler(self.env, request)

        if url.path in ("/api/security/roles", "/api/security/roles/"):
            return await security_roles_handler(self.env, request)

        if url.path in ("/api/security/audit", "/api/security/audit/"):
            return await security_audit_handler(self.env, request)

        if url.path in (
                "/api/security-scans/queue",
                "/api/security-scans/queue/"):
            return await repository_security_scan_queue_handler(
                self.env, request)

        if url.path in (
                "/api/security/owner-keys",
                "/api/security/owner-keys/"):
            return await owner_encryption_keys_handler(self.env, request)

        if url.path in (
                "/api/rewards/signing-jobs",
                "/api/rewards/signing-jobs/"):
            return await reward_signing_jobs_handler(self.env, request)

        if url.path in (
                "/api/rewards/pending",
                "/api/rewards/pending/"):
            return await pending_rewards_handler(self.env, request)

        if url.path in (
                "/api/rewards/pending-awards",
                "/api/rewards/pending-awards/"):
            return await pending_reward_award_handler(self.env, request)

        if url.path in (
                "/api/rewards/contributions",
                "/api/rewards/contributions/"):
            return await reward_contributions_handler(self.env, request)

        if url.path in ("/api/rewards/pool", "/api/rewards/pool/"):
            if method_name(request) != "GET":
                return json_response(
                    {"error": "method_not_allowed"}, status=405)
            return await _account_central_fund(self.env, request)

        # Persistent data lives in D1, not Durable Objects.
        if url.path in ("/api/repositories", "/api/repositories/"):
            return await catalog_handler(self.env, request)

        # GitHub/GitLab metadata imports and non-mirrored stubs are deliberately
        # separate from /api/repositories: only the latter represents a mirror
        # that ForkMesh can actually route or clone.
        if (url.path == "/api/repository-imports"
                or url.path == "/api/repository-imports/"
                or url.path.startswith("/api/repository-imports/")):
            return await repository_imports_handler(
                self.env, request, url.path)

        if url.path in ("/api/notifications", "/api/notifications/"):
            return await notifications_handler(self.env, request)

        # Peer mirror requests (issue #385): create/accept/reject a request
        # asking another node to mirror a repo. Session-gated like the inbox.
        if url.path in ("/api/mirror-requests", "/api/mirror-requests/"):
            return await mirror_requests_handler(self.env, request)

        # Consolidated lightweight status digest (version + profile/notification
        # change tokens) so the client polls once instead of re-fetching the
        # full profile and notification list every tick.
        if url.path in ("/api/poll", "/api/poll/"):
            return await poll_handler(self.env, request)

        # Shared room-chat key, derived server-side from DATA_KEY and handed only
        # to authenticated clients — replaces the old public app-wide constant.
        if url.path in ("/api/chat/room-key", "/api/chat/room-key/"):
            return await chat_room_key_handler(self.env, request)

        # Public chat-activity counters (message + user counts) that drive the
        # unread badge on the shared site header's chat icon.
        if url.path in ("/api/chat/activity", "/api/chat/activity/"):
            return await chat_activity_handler(self.env, request)

        # Private channel API and socket admission are checked before the
        # generic repository-room router. Authorization and current key-version
        # validation therefore happen before any Durable Object is selected.
        chat_channel_socket = CHAT_CHANNEL_WS_RE.match(url.path)
        if chat_channel_socket:
            return await _chat_channel_socket_handler(
                self.env, request, chat_channel_socket.group(1))
        if (
            CHAT_CHANNELS_RE.match(url.path)
            or CHAT_CHANNEL_MEMBERS_RE.match(url.path)
            or CHAT_CHANNEL_ROOM_ACCESS_RE.match(url.path)
            or CHAT_CHANNEL_HISTORY_RE.match(url.path)
        ):
            return await chat_channels_api.handle(
                _ChatChannelsRuntime(self.env, request), url.path)

        # Direct messages never inherit platform-administrator channel access.
        # Both HTTP room access and WebSocket admission check participant rows.
        chat_direct_socket = CHAT_DIRECT_MESSAGE_WS_RE.match(url.path)
        if chat_direct_socket:
            return await _chat_direct_socket_handler(
                self.env, request, chat_direct_socket.group(1))
        if (
            CHAT_DIRECT_MESSAGES_RE.match(url.path)
            or CHAT_DIRECT_MESSAGE_USERS_RE.match(url.path)
            or CHAT_DIRECT_MESSAGE_ROOM_ACCESS_RE.match(url.path)
            or CHAT_DIRECT_MESSAGE_READ_RE.match(url.path)
        ):
            return await chat_direct_messages_api.handle(
                _ChatDirectMessagesRuntime(self.env, request), url.path)

        # Chat-triggered Cloudflare AI interface. Clients forward explicit
        # "forkbot ..." mentions here; the Worker queues compatible issue-inbox
        # records and returns a bot reply for the encrypted room.
        if url.path in ("/api/sync", "/api/sync/"):
            return await sync_handler(self.env, request)

        # Live push channel that makes /api/sync event-driven: an owner node
        # holds one WebSocket here and each web submission triggers an instant
        # payload-free event frame (see notify_repo_host / ForkMeshNodes).
        if url.path in ("/api/nodes/events", "/api/nodes/events/"):
            return await node_events_handler(self.env, request)

        if url.path in ("/api/forkbot/chat", "/api/forkbot/chat/"):
            return await forkbot_chat_handler(self.env, request)

        # All /api/accounts/* paths (reserve, profile, follow, login, lookup)
        # are dispatched by accounts_handler.
        # Solana payout relay mesh (canonical /api/relay-mesh/*, legacy
        # /api/federation/* alias) — unrelated to ActivityPub, which is /ap/*.
        if (url.path.startswith("/api/relay-mesh/")
                or url.path.startswith("/api/federation/")):
            return await federation_handler(self.env, request)

        if url.path.startswith("/api/accounts/"):
            return await accounts_handler(self.env, request)

        # --- Organizations + teams (issue #388) --------------------------
        if ORGS_RE.match(url.path):
            return await orgs_handler(self.env, request)
        org_members_match = ORG_MEMBERS_RE.match(url.path)
        if org_members_match:
            org = safe_segment(org_members_match.group(1))
            if not org:
                return json_response({"error": "not_found"}, status=404)
            return await org_members_handler(self.env, request, org)
        org_team_members_match = ORG_TEAM_MEMBERS_RE.match(url.path)
        if org_team_members_match:
            org = safe_segment(org_team_members_match.group(1))
            team = safe_segment(org_team_members_match.group(2))
            if not org or not team:
                return json_response({"error": "not_found"}, status=404)
            return await org_team_members_handler(
                self.env, request, org, team)
        org_teams_match = ORG_TEAMS_RE.match(url.path)
        if org_teams_match:
            org = safe_segment(org_teams_match.group(1))
            if not org:
                return json_response({"error": "not_found"}, status=404)
            return await org_teams_handler(self.env, request, org)
        org_repos_match = ORG_REPOS_RE.match(url.path)
        if org_repos_match:
            org = safe_segment(org_repos_match.group(1))
            if not org:
                return json_response({"error": "not_found"}, status=404)
            return await org_repos_handler(self.env, request, org)
        org_succession_match = ORG_SUCCESSION_RE.match(url.path)
        if org_succession_match:
            org = safe_segment(org_succession_match.group(1))
            action = safe_segment(
                org_succession_match.group(2) or "", 40)
            if not org or (
                org_succession_match.group(2) and not action
            ):
                return json_response({"error": "not_found"}, status=404)
            return await organization_succession_handler(
                self.env, request, org, action)
        org_fediverse_match = ORG_FEDIVERSE_RE.match(url.path)
        if org_fediverse_match:
            org = safe_segment(org_fediverse_match.group(1))
            if not org:
                return json_response({"error": "not_found"}, status=404)
            return await org_fediverse_handler(
                self.env, request, org)
        org_match = ORG_RE.match(url.path)
        if org_match:
            org = safe_segment(org_match.group(1))
            if not org:
                return json_response({"error": "not_found"}, status=404)
            return await org_handler(self.env, request, org)

        # --- Achievement badges (adhoc #370) ------------------------------
        if BADGES_RE.match(url.path):
            return await badges_catalog_handler(self.env, request)
        badge_account_match = BADGE_ACCOUNT_RE.match(url.path)
        if badge_account_match:
            account = safe_segment(badge_account_match.group(1))
            if not account:
                return json_response({"error": "not_found"}, status=404)
            return await account_badges_handler(self.env, request, account)

        # Founders-outreach email console (/outreach): admins plus the
        # admin-managed outreach_team roster send from the founders address.
        if url.path == "/api/outreach" or url.path.startswith("/api/outreach/"):
            return await outreach_handler(self.env, request)

        # --- ActivityPub federation (fediverse) --------------------------
        # WebFinger/NodeInfo discovery plus the /ap/* actor, inbox, object
        # and collection endpoints. Kept clear of /api/federation/*, which is
        # the (unrelated) Solana payout relay mesh.
        if url.path == "/.well-known/webfinger":
            return await ap_webfinger_handler(self.env, request)
        if url.path == "/.well-known/host-meta":
            return await ap_hostmeta_handler(self.env, request)
        if url.path == "/.well-known/nodeinfo":
            return await ap_nodeinfo_handler(self.env, request, True)
        if url.path == "/nodeinfo/2.1":
            return await ap_nodeinfo_handler(self.env, request, False)
        if url.path in ("/ap/actor", "/ap/actor/"):
            return await _ap_actor_doc_response(
                self.env, request, AP_ACTOR_INSTANCE, AP_INSTANCE_HANDLE)
        if url.path in ("/ap/inbox", "/ap/actor/inbox"):
            return await ap_inbox_handler(self.env, request)
        ap_user_match = AP_USER_RE.match(url.path)
        if ap_user_match:
            return await _ap_actor_doc_response(
                self.env, request, AP_ACTOR_USER,
                ap_user_match.group(1).lower())
        ap_user_sub = AP_USER_SUB_RE.match(url.path)
        if ap_user_sub:
            if ap_user_sub.group(2) == "inbox":
                return await ap_inbox_handler(self.env, request)
            return await ap_collection_handler(
                self.env, request, AP_ACTOR_USER,
                ap_user_sub.group(1).lower(), ap_user_sub.group(2))
        ap_repo_match = AP_REPO_RE.match(url.path)
        if ap_repo_match:
            ap_owner = safe_segment(ap_repo_match.group(1))
            ap_repo_name = safe_segment(ap_repo_match.group(2))
            if not ap_owner or not ap_repo_name:
                return json_response({"error": "not_found"}, status=404)
            return await _ap_actor_doc_response(
                self.env, request, AP_ACTOR_REPO,
                ap.repo_handle(ap_owner.lower(), ap_repo_name.lower()))
        ap_repo_sub = AP_REPO_SUB_RE.match(url.path)
        if ap_repo_sub:
            ap_owner = safe_segment(ap_repo_sub.group(1))
            ap_repo_name = safe_segment(ap_repo_sub.group(2))
            if not ap_owner or not ap_repo_name:
                return json_response({"error": "not_found"}, status=404)
            if ap_repo_sub.group(3) == "inbox":
                return await ap_inbox_handler(self.env, request)
            return await ap_collection_handler(
                self.env, request, AP_ACTOR_REPO,
                ap.repo_handle(ap_owner.lower(), ap_repo_name.lower()),
                ap_repo_sub.group(3))
        ap_object_media_match = AP_OBJECT_MEDIA_RE.match(url.path)
        if ap_object_media_match:
            return await ap_object_media_handler(
                self.env, request, ap_object_media_match.group(1),
                ap_object_media_match.group(2))
        ap_object_match = AP_OBJECT_RE.match(url.path)
        if ap_object_match:
            return await ap_object_handler(
                self.env, request, ap_object_match.group(1))

        # Match the profile route on the percent-decoded, case-folded path:
        # links pasted from address bars / other apps often arrive as /%40name
        # (an encoded @) or /@Name, and both used to fall through to the 404
        # page instead of the profile.
        public_profile = re.match(
            r"^/@([a-z](?:[a-z0-9-]{0,61}[a-z0-9])?)(/repositories)?/?$",
            unquote(url.path).lower())
        if public_profile:
            # Fediverse clients resolve profile URLs with an ActivityPub
            # Accept header; hand them the actor document instead of HTML.
            if ap.wants_activity_json(request.headers.get("accept") or ""):
                return await _ap_actor_doc_response(
                    self.env, request, AP_ACTOR_USER,
                    public_profile.group(1))
            return await self._serve_profile_page(
                url, public_profile.group(1),
                repositories=bool(public_profile.group(2)))

        # /@owner.repo — a repo actor's fediverse profile page (a feed of its
        # federated posts). A user handle never contains a dot, so a dotted
        # /@handle is unambiguously a repo actor (see ap.split_handle). This is
        # the repo actor's `url`, so fediverse clients that resolve it with an
        # ActivityPub Accept header get the actor document instead of HTML.
        fedi_repo = re.match(r"^/@([^/]+)/?$", unquote(url.path))
        if fedi_repo:
            parsed = ap.split_handle(fedi_repo.group(1).lower())
            if parsed and parsed[0] == "repo":
                _, ph_owner, ph_repo = parsed
                if ap.wants_activity_json(request.headers.get("accept") or ""):
                    return await _ap_actor_doc_response(
                        self.env, request, AP_ACTOR_REPO,
                        ap.repo_handle(ph_owner, ph_repo))
                return await self._serve_repo_profile_page(
                    url, ph_owner, ph_repo)

        issues_match = REPO_ISSUES_RE.match(url.path)
        if issues_match:
            owner = safe_segment(issues_match.group(1))
            repo = safe_segment(issues_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            if (await _repo_is_private(self.env, owner, repo)
                    and not (method_name(request) in ("GET", "DELETE")
                             and await _authorize_owner(
                                 self.env, request, owner))):
                return json_response({"error": "not_found"}, status=404)
            return await issues_handler(self.env, request, owner, repo)

        pull_merge_match = REPO_PULL_MERGE_RE.match(url.path)
        if pull_merge_match:
            owner = safe_segment(pull_merge_match.group(1))
            repo = safe_segment(pull_merge_match.group(2))
            try:
                pull_number = int(pull_merge_match.group(3))
            except (TypeError, ValueError, OverflowError):
                pull_number = 0
            if not owner or not repo or pull_number <= 0:
                return json_response({"error": "not_found"}, status=404)
            return await repository_pull_merge_handler(
                self.env, request, owner, repo, pull_number)

        action_runs_match = REPO_ACTION_RUNS_RE.match(url.path)
        if action_runs_match:
            owner = safe_segment(action_runs_match.group(1))
            repo = safe_segment(action_runs_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await repository_actions_status_handler(
                self.env, request, owner, repo)

        pulls_match = REPO_PULLS_RE.match(url.path)
        if pulls_match:
            owner = safe_segment(pulls_match.group(1))
            repo = safe_segment(pulls_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            if (await _repo_is_private(self.env, owner, repo)
                    and not (method_name(request) in ("GET", "DELETE")
                             and await _authorize_owner(
                                 self.env, request, owner))):
                return json_response({"error": "not_found"}, status=404)
            return await pulls_handler(self.env, request, owner, repo)

        commits_match = REPO_COMMITS_RE.match(url.path)
        if commits_match:
            owner = safe_segment(commits_match.group(1))
            repo = safe_segment(commits_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            if (await _repo_is_private(self.env, owner, repo)
                    and not (method_name(request) in ("GET", "DELETE")
                             and await _authorize_owner(
                                 self.env, request, owner))):
                return json_response({"error": "not_found"}, status=404)
            return await commits_handler(self.env, request, owner, repo)

        discussions_match = REPO_DISCUSSIONS_RE.match(url.path)
        if discussions_match:
            owner = safe_segment(discussions_match.group(1))
            repo = safe_segment(discussions_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            if (await _repo_is_private(self.env, owner, repo)
                    and not (method_name(request) in ("GET", "DELETE")
                             and await _authorize_owner(
                                 self.env, request, owner))):
                return json_response({"error": "not_found"}, status=404)
            return await discussions_handler(self.env, request, owner, repo)

        pending_match = REPO_PENDING_RE.match(url.path)
        if pending_match:
            owner = safe_segment(pending_match.group(1))
            repo = safe_segment(pending_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await repo_pending_counts_handler(self.env, request, owner, repo)

        # Remote fediverse replies for a repo thread (public read), and the
        # owner-node push of release/merge announcements into the fediverse.
        fedi_comments_match = REPO_FEDI_COMMENTS_RE.match(url.path)
        if fedi_comments_match:
            owner = safe_segment(fedi_comments_match.group(1))
            repo = safe_segment(fedi_comments_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await fedi_comments_handler(self.env, request, owner, repo)

        ap_publish_match = REPO_AP_PUBLISH_RE.match(url.path)
        if ap_publish_match:
            owner = safe_segment(ap_publish_match.group(1))
            repo = safe_segment(ap_publish_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await ap_publish_handler(self.env, request, owner, repo)

        ap_digest_match = REPO_AP_DIGEST_RE.match(url.path)
        if ap_digest_match:
            owner = safe_segment(ap_digest_match.group(1))
            repo = safe_segment(ap_digest_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await ap_digest_handler(
                self.env, request, owner, repo)

        ap_posts_match = REPO_AP_POSTS_RE.match(url.path)
        if ap_posts_match:
            owner = safe_segment(ap_posts_match.group(1))
            repo = safe_segment(ap_posts_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await ap_posts_handler(self.env, request, owner, repo)

        repo_media_match = REPO_MEDIA_RE.match(url.path)
        if repo_media_match:
            owner = safe_segment(repo_media_match.group(1))
            repo = safe_segment(repo_media_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await repo_media_handler(
                self.env, request, owner, repo, repo_media_match.group(3))

        repo_card_match = REPO_CARD_RE.match(url.path)
        if repo_card_match:
            owner = safe_segment(repo_card_match.group(1))
            repo = safe_segment(repo_card_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await repo_card_handler(self.env, request, owner, repo)

        star_match = REPO_STAR_RE.match(url.path)
        if star_match:
            owner = safe_segment(star_match.group(1))
            repo = safe_segment(star_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await repo_star_handler(self.env, request, owner, repo)

        subscribe_match = REPO_SUBSCRIBE_RE.match(url.path)
        if subscribe_match:
            owner = safe_segment(subscribe_match.group(1))
            repo = safe_segment(subscribe_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await subscribe_handler(self.env, request, owner, repo)

        bounty_match = REPO_BOUNTY_RE.match(url.path)
        if bounty_match:
            owner = safe_segment(bounty_match.group(1))
            repo = safe_segment(bounty_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await bounties_handler(self.env, request, owner, repo)

        shares_match = REPO_SHARES_RE.match(url.path)
        if shares_match:
            owner = safe_segment(shares_match.group(1))
            repo = safe_segment(shares_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await shares_handler(self.env, request, owner, repo)

        security_scans_match = REPO_SECURITY_SCANS_RE.match(url.path)
        if security_scans_match:
            owner = safe_segment(security_scans_match.group(1))
            repo = safe_segment(security_scans_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await repository_security_scans_handler(
                self.env,
                request,
                owner,
                repo,
                security_scans_match.group(3),
            )

        mirrors_match = REPO_MIRRORS_RE.match(url.path)
        if mirrors_match:
            owner = safe_segment(mirrors_match.group(1))
            repo = safe_segment(mirrors_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await repo_mirrors_handler(self.env, request, owner, repo)

        logo_suggestions_match = REPO_LOGO_SUGGESTIONS_RE.match(url.path)
        if logo_suggestions_match:
            owner = safe_segment(logo_suggestions_match.group(1))
            repo = safe_segment(logo_suggestions_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await native_repository_logo_handler(
                self.env, request, owner, repo, suggestions=True)

        logo_match = REPO_LOGO_RE.match(url.path)
        if logo_match:
            owner = safe_segment(logo_match.group(1))
            repo = safe_segment(logo_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await native_repository_logo_handler(
                self.env, request, owner, repo)

        about_match = REPO_ABOUT_RE.match(url.path)
        if about_match:
            owner = safe_segment(about_match.group(1))
            repo = safe_segment(about_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await repo_about_handler(self.env, request, owner, repo)

        privacy_match = REPO_PRIVACY_RE.match(url.path)
        if privacy_match:
            owner = safe_segment(privacy_match.group(1))
            repo = safe_segment(privacy_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await repo_privacy_handler(
                self.env, request, owner, repo)

        org_agent_bot_match = ORG_AGENT_BOT_RE.match(url.path)
        if org_agent_bot_match:
            org = safe_segment(org_agent_bot_match.group(1))
            repo = safe_segment(org_agent_bot_match.group(2))
            session_id = safe_segment(org_agent_bot_match.group(3))
            if not org or not repo or not session_id:
                return json_response({"error": "not_found"}, status=404)
            return await org_agent_bot_handler(
                self.env, request, org, repo, session_id)

        org_agent_bots_match = ORG_AGENT_BOTS_RE.match(url.path)
        if org_agent_bots_match:
            org = safe_segment(org_agent_bots_match.group(1))
            repo = safe_segment(org_agent_bots_match.group(2))
            if not org or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await org_agent_bots_handler(
                self.env, request, org, repo)

        org_agent_job_result_match = REPO_ORG_AGENT_JOB_RESULT_RE.match(
            url.path)
        if org_agent_job_result_match:
            owner = safe_segment(org_agent_job_result_match.group(1))
            repo = safe_segment(org_agent_job_result_match.group(2))
            job_id = org_agent_job_result_match.group(3)
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await repo_org_agent_job_result_handler(
                self.env, request, owner, repo, job_id)

        org_agent_jobs_match = REPO_ORG_AGENT_JOBS_RE.match(url.path)
        if org_agent_jobs_match:
            owner = safe_segment(org_agent_jobs_match.group(1))
            repo = safe_segment(org_agent_jobs_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await repo_org_agent_jobs_handler(
                self.env, request, owner, repo)

        agents_list_match = REPO_AGENTS_LIST_RE.match(url.path)
        if agents_list_match:
            owner = safe_segment(agents_list_match.group(1))
            repo = safe_segment(agents_list_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await agents_list_handler(self.env, request, owner, repo)

        agents_ack_match = REPO_AGENTS_ACK_RE.match(url.path)
        if agents_ack_match:
            owner = safe_segment(agents_ack_match.group(1))
            repo = safe_segment(agents_ack_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await agents_ack_handler(
                self.env, request, owner, repo)

        agents_transcript_match = REPO_AGENTS_TRANSCRIPT_RE.match(url.path)
        if agents_transcript_match:
            owner = safe_segment(agents_transcript_match.group(1))
            repo = safe_segment(agents_transcript_match.group(2))
            agent_id = safe_segment(agents_transcript_match.group(3))
            if not owner or not repo or not agent_id:
                return json_response({"error": "not_found"}, status=404)
            return await agents_transcript_handler(self.env, request, owner, repo, agent_id)

        agents_prompt_match = REPO_AGENTS_PROMPT_RE.match(url.path)
        if agents_prompt_match:
            owner = safe_segment(agents_prompt_match.group(1))
            repo = safe_segment(agents_prompt_match.group(2))
            agent_id = safe_segment(agents_prompt_match.group(3))
            if not owner or not repo or not agent_id:
                return json_response({"error": "not_found"}, status=404)
            return await agents_prompt_handler(self.env, request, owner, repo, agent_id)

        agents_match = REPO_AGENTS_RE.match(url.path)
        if agents_match:
            owner = safe_segment(agents_match.group(1))
            repo = safe_segment(agents_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await agents_handler(self.env, request, owner, repo)

        release_downloads_match = REPO_RELEASE_DOWNLOADS_RE.match(url.path)
        if release_downloads_match:
            owner = safe_segment(release_downloads_match.group(1))
            repo = safe_segment(release_downloads_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            return await release_downloads_handler(self.env, request, owner, repo)

        release_blob_match = RELEASE_BLOB_RE.match(url.path)
        if release_blob_match:
            owner = safe_segment(release_blob_match.group(1))
            repo = safe_segment(release_blob_match.group(2))
            sha256 = release_blob_match.group(3)
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            if await _repo_is_private(self.env, owner, repo):
                return json_response({"error": "not_found"}, status=404)
            return await _https_mirror_proxy(
                self.env, request, owner, repo, "release-blob",
                release_sha=sha256)

        host_match = REPO_HOST_RE.match(url.path)
        if host_match:
            owner = safe_segment(host_match.group(1))
            repo = safe_segment(host_match.group(2))
            if not owner or not repo:
                return json_response({"error": "not_found"}, status=404)
            action = host_match.group(3)
            upgrade = (request.headers.get("upgrade") or "").lower()
            if (
                upgrade != "websocket"
                and action in {
                    "tree", "blobs", "blob", "raw", "history", "commit",
                    "compare", "branches", "search", "stats", "sizes",
                }
            ):
                if await _repo_is_private(self.env, owner, repo):
                    # Named private content routes are intentionally inert. The
                    # only private byte transport is the identity-free opaque
                    # endpoint, with authorization outside the URL.
                    return _private_replica_not_found()
                return await _https_mirror_proxy(
                    self.env, request, owner, repo, action)
            # The repository tunnel is permanently retired. Repository bytes
            # use ordinary HTTPS mirror routes; desktop clients use bounded
            # polling for control-plane changes.
            return json_response({
                "error": "repository_socket_transport_retired",
                "httpsMirrorRequired": True,
                "socketFallback": False,
            }, status=410, cache_control="no-store")

        room = room_key_from_path(url.path)
        if room:
            public_world_general = (
                room.get("key") == PUBLIC_WORLD_GENERAL_ROOM_KEY
            )
            if (
                not room.get("compat")
                and not public_world_general
                and await _repository_access_context(
                    self.env,
                    request,
                    room.get("owner", ""),
                    room.get("repo", ""),
                ) is None
            ):
                # Apply this before choosing or calling the Durable Object. A
                # guessed private/missing repository therefore cannot reveal
                # whether a room or retained history exists.
                return _private_replica_not_found()
            room_id = self.env.FORKMESH_MAINNODE_ROOM.idFromName(room["key"])
            # The platform can abort a room DO mid-request — the free-tier
            # duration cap kills long-lived requests, and any co-located DO
            # blowing the isolate's limits resets every in-flight request with
            # a generic "internal error". Both are transient: a fresh stub
            # lands on a replacement isolate, so retry once before failing.
            # Room requests carry no body (GET snapshot / WebSocket upgrade),
            # so re-driving durable_object_request is safe. Without this
            # guard the abort would escape Default.fetch as a Worker Error
            # 1101; with it, a persistent failure is recorded (the /status
            # page counts these) and answered with a retryable 503 that
            # leaks no exception detail to the client.
            last_error = None
            for _attempt in range(2):
                room_object = self.env.FORKMESH_MAINNODE_ROOM.get(room_id)
                try:
                    return await room_object.fetch(
                        await durable_object_request(request))
                except Exception as error:
                    last_error = error
            await log_durable_object_abort(
                self.env, request, url.path, last_error)
            return json_response(
                {"error": "unavailable"}, status=503,
                extra_headers=EXPECTED_DEGRADED_HEADERS)

        # Referral share links: count the click, bounce to signup. Matched
        # before the repo shortcut so /r/<name> never reads as owner/repo.
        referral_match = REFERRAL_LINK_RE.match(url.path)
        if referral_match:
            return await referral_click(
                self.env, unquote(referral_match.group(1)), request)

        # Repo shortcut URLs (/owner/repo and tab/tree/blob deep links) all
        # serve the prebuilt repo-detail page; its JS resolves the path. The
        # per-repo rel="me" head tags are injected at serve time so Mastodon
        # can verify the repo actor's profile link (green check) against this
        # very page — a static shared asset can't carry a per-repo link.
        if looks_like_repo_route(url.path):
            return await self._serve_repo_page(request, url)

        if url.path == "/dashboard" or url.path.startswith("/dashboard/"):
            # Legacy /dashboard?section=X links 308 to the per-page paths.
            target = dashboard_section_redirect(url.path, url.query)
            if target:
                return Response("", status=308, headers={"location": target})
            # /dashboard/repos/ -> /dashboard/repos (canonical, no trailing /).
            normalized = url.path.rstrip("/") or "/dashboard"
            if normalized != url.path and normalized in DASHBOARD_PAGE_ASSETS:
                return Response("", status=308, headers={"location": normalized})
            asset = DASHBOARD_PAGE_ASSETS.get(url.path)
            if asset:
                return await self._serve_dashboard_asset(url, asset)
            # Settings sub-tabs (/dashboard/settings/<tab>) share the settings
            # document; the client restores the tab from the path.
            if url.path.startswith("/dashboard/settings/"):
                return await self._serve_dashboard_asset(
                    url, DASHBOARD_PAGE_ASSETS["/dashboard/settings"])
            # Old bounced deep links (/dashboard/owner/repo[...]) move to the
            # clean repo path.
            rest = url.path[len("/dashboard"):]
            if looks_like_repo_route(rest):
                return Response("", status=308, headers={"location": rest})
            return await self._serve_not_found_page(url)

        return json_response({"error": "not_found"}, status=404)

    async def _serve_not_found_page(self, url):
        base = url.scheme + "://" + url.netloc + "/"
        try:
            resp = await self.env.ASSETS.fetch(base + "404.html")
            body = await resp.text()
        except Exception:
            body = "not found"
        return Response(
            body,
            status=404,
            headers={"content-type": "text/html; charset=utf-8"},
        )

    async def _serve_profile_page(self, url, name, repositories=False):
        # /@name — the FULL public profile: the same prebuilt dashboard
        # profile document (sidebar, contribution heatmap, activity feed,
        # repositories tab) with per-user head tags injected at serve time.
        # dashboard.js detects the /@name path and renders the named account's
        # public data instead of the logged-in session (public-profile mode).
        # Eligibility mirrors the fediverse actor: active + not private —
        # node-owner accounts get pages too, matching _ap_user_federates.
        # Served identically to every viewer (personalization happens in
        # dashboard.js), so the built page lives in the colo edge cache: it is
        # the rel=me verification target every follower server GETs after an
        # Update(Person), and those bursts must not each rebuild it at origin.
        # _ap_broadcast_actor_update purges the key on profile changes.
        origin = url.scheme + "://" + url.netloc
        await ensure_schema(self.env)
        _, rec = await _account_row(self.env, name)
        if (not rec or rec.get("status") != "active"
                or rec.get("profile_private")):
            return await self._serve_not_found_page(url)
        cache_key = "%s/@%s%s" % (
            origin, quote(name), "/repositories" if repositories else "")
        cached = await edge_cache_match(cache_key)
        if cached is not None:
            return cached
        asset = DASHBOARD_PAGE_ASSETS[
            "/dashboard/profile/repositories" if repositories
            else "/dashboard/profile"]
        base = url.scheme + "://" + url.netloc + "/"
        try:
            resp = await self.env.ASSETS.fetch(base + asset)
            body = await resp.text()
        except Exception:
            body = "<!doctype html><title>ForkMesh</title>"
        canonical = "%s/@%s" % (origin, quote(name))
        # rel="me" is the reciprocal half of the fediverse Person actor's
        # verified profile link (the actor's `url` is this page); the
        # alternate link lets fediverse software discover the actor from the
        # page URL.
        tags = (
            "<link rel=\"canonical\" href=\"%s\">"
            "<link rel=\"me\" href=\"%s\">"
            "<link rel=\"alternate\" type=\"application/activity+json\" "
            "href=\"%s/ap/users/%s\">"
            % (canonical, canonical, origin, quote(name)))
        if "</head>" in body:
            body = body.replace("</head>", tags + "</head>", 1)
        body = re.sub(r"<title>[^<]*</title>",
                      "<title>@%s · ForkMesh</title>" % _html_escape(name),
                      body, count=1)
        page = Response(body, status=200, headers={
            "content-type": "text/html; charset=utf-8",
            "cache-control": "public, max-age=300",
        })
        await edge_cache_put(cache_key, page)
        return page

    async def _serve_repo_page(self, request, url):
        # The shared repo-detail document, plus per-repo head tags:
        #  - <link rel="me" href="<repo actor url>"> — the reciprocal half of
        #    the repo actor's verified "Repository" row: that row links this git
        #    page, so Mastodon fetches it and looks for a rel=me back to the
        #    actor's `url` (the /@owner.repo fediverse profile) to mark it green;
        #  - <link rel="alternate" type="application/activity+json"> — lets
        #    fediverse software discover the actor straight from the page URL.
        # Identical for every viewer, and the rel=me verification target of
        # the repo actor: edge-cached so follower-server verification bursts
        # after an Update(Group) cost one origin build per colo per TTL.
        origin = url.scheme + "://" + url.netloc
        parts = [p for p in url.path.split("/") if p]
        owner = safe_segment(unquote(parts[0])) if len(parts) >= 2 else ""
        repo = safe_segment(unquote(parts[1])) if len(parts) >= 2 else ""
        cache_key = ""
        explicit_public = False
        data_owner = owner
        repo_record = {}
        social_version = ""
        if owner and repo:
            # Only an explicit public catalog row may contribute names,
            # description, actor links, or a shared cache entry. Private and
            # missing paths intentionally receive the same generic app shell;
            # authenticated client APIs decide whether the viewer may render
            # repository data. This keeps URL probing non-disclosing.
            #
            # An organization repo URL is a public alias, not the encrypted
            # catalog key. Resolve its linked node only for privacy/catalog
            # reads; canonical, actor, card and displayed identity below must
            # remain the organization URL the visitor actually requested.
            data_owner = await _org_repo_node(
                self.env, owner, repo) or owner
            explicit_public = not await _repo_is_private(
                self.env, data_owner, repo)
            if explicit_public:
                try:
                    await ensure_schema(self.env)
                    repo_bi = await blind_index(
                        self.env, data_owner + "/" + repo)
                    repo_row = await d1_first(
                        self.env,
                        "SELECT data FROM repositories WHERE key_bi=?",
                        repo_bi)
                    repo_record = (
                        await decrypt_row(self.env, repo_row.get("data"))
                        if repo_row else {})
                    explicit_public = bool(
                        repo_record
                        and repo_record.get("visibility") == "public"
                        and _catalog_record_matches_identity(
                            repo_record, data_owner, repo))
                except Exception:
                    # A crawler must never receive public metadata or a shared
                    # cache entry when the signed record cannot be re-read.
                    explicit_public = False
                    repo_record = {}
                if explicit_public:
                    social_version = _repository_social_version(repo_record)
                    # A state-less legacy record may still render its generic
                    # shell, but it cannot safely create a reusable social
                    # cache entry until it republishes a commit/state pin.
                    if social_version:
                        cache_key = "%s/%s/%s?repo-state=%s" % (
                            origin, quote(owner), quote(repo),
                            quote(social_version, safe=""))
                        cached = await edge_cache_match(cache_key)
                        if cached is not None:
                            return cached
        base = url.scheme + "://" + url.netloc + "/"
        try:
            resp = await self.env.ASSETS.fetch(base + DASHBOARD_REPO_ASSET)
            body = await resp.text()
        except Exception:
            body = "<!doctype html><title>ForkMesh Dashboard</title>"
        if owner and repo and explicit_public and "</head>" in body:
            canonical = "%s/%s/%s" % (origin, quote(owner), quote(repo))
            # The repo actor's `url` — the /@owner.repo fediverse profile — is
            # the rel=me target that verifies this page's "Repository" row.
            # Lowercased to match the actor id (handles are case-folded).
            fedi_profile = "%s/@%s.%s" % (origin, owner.lower(), repo.lower())
            # OpenGraph/Twitter card so social + fediverse shares of the repo
            # URL (the preview under a federated "new pull request" post, a
            # Slack unfurl, etc.) render the repo's rendered info card — name,
            # description and stats grid with the ForkMesh mark in the corner
            # (adhoc #46, see repo_card_handler / og_card.py) — instead of a
            # full-bleed logo. og:description carries the catalog description
            # so the unfurl text matches the repo, not the generic shell copy.
            og_image = "%s/api/repo/%s/%s/card.png" % (
                origin, quote(owner), quote(repo))
            if social_version:
                og_image += "?v=" + quote(social_version, safe="")
            og_description = str(
                repo_record.get("description", "") or "")
            if not og_description:
                og_description = ("%s/%s on ForkMesh — distributed Git "
                                  "hosting on a mesh of desktop nodes."
                                  % (owner, repo))
            title = "%s/%s - ForkMesh" % (owner, repo)
            tags = (
                "<link rel=\"canonical\" href=\"%s\">"
                "<link rel=\"me\" href=\"%s\">"
                "<link rel=\"alternate\" type=\"application/activity+json\" "
                "href=\"%s/ap/repos/%s/%s\">"
                "<meta property=\"og:type\" content=\"website\">"
                "<meta property=\"og:site_name\" content=\"ForkMesh\">"
                "<meta property=\"og:url\" content=\"%s\">"
                "<meta property=\"og:title\" content=\"%s\">"
                "<meta property=\"og:description\" content=\"%s\">"
                "<meta property=\"og:image\" content=\"%s\">"
                "<meta property=\"og:image:width\" content=\"%d\">"
                "<meta property=\"og:image:height\" content=\"%d\">"
                "<meta name=\"twitter:card\" content=\"summary_large_image\">"
                "<meta name=\"twitter:title\" content=\"%s\">"
                "<meta name=\"twitter:description\" content=\"%s\">"
                "<meta name=\"twitter:image\" content=\"%s\">"
                % (canonical, fedi_profile,
                   origin, quote(owner), quote(repo),
                   canonical, title, _html_escape(og_description), og_image,
                   og_card.CARD_W, og_card.CARD_H,
                   title, _html_escape(og_description), og_image))
            body = body.replace("</head>", tags + "</head>", 1)
        page = Response(body, status=200, headers={
            "content-type": "text/html; charset=utf-8",
            "cache-control": (
                "public, max-age=300" if cache_key
                else "no-store, max-age=0, must-revalidate"),
        })
        if cache_key:
            await edge_cache_put(cache_key, page)
        return page

    async def _serve_repo_profile_page(self, url, owner, repo):
        # The repo actor's `url`: a lightweight, edge-cached fediverse profile —
        # banner, avatar, bio, follower count and a feed of the repo's federated
        # posts — so a Mastodon user who clicks the repo handle (in a mention or
        # via the profile's external-link) lands on a social profile instead of
        # the git-forge page (adhoc #50). The code is one click away. Fediverse
        # clients that send an ActivityPub Accept header are handed the actor
        # document by the caller; this is the HTML view for browsers.
        origin = url.scheme + "://" + url.netloc
        handle = ap.repo_handle(owner.lower(), repo.lower())
        await ensure_schema(self.env)
        if (not await _ap_enabled(self.env)
                or not await _ap_repo_federates(self.env, owner, repo)):
            return await self._serve_not_found_page(url)
        data_owner = await _ap_org_alias_owner(
            self.env, owner, repo)
        cache_key = "%s/@%s" % (origin, handle)
        cached = await edge_cache_match(cache_key)
        if cached is not None:
            return cached
        key_bi = await blind_index(self.env, data_owner + "/" + repo)
        repo_row = await d1_first(
            self.env,
            "SELECT is_private, data FROM repositories WHERE key_bi=?", key_bi)
        if not repo_row:
            return await self._serve_not_found_page(url)
        rec = await decrypt_row(self.env, repo_row.get("data"))
        if (
            not rec
            or rec.get("visibility") != "public"
            or not _catalog_record_matches_identity(
                rec, data_owner, repo)
        ):
            return await self._serve_not_found_page(url)
        description = clean_string(
            (rec or {}).get("description", "") or "", 240).strip()
        # Branding: owner-uploaded logo/banner (repo About tab), else defaults.
        icon_url = AP_AVATAR_PATH
        image_url = AP_BANNER_PATH
        media_rows = await d1_all(
            self.env, "SELECT kind, updated_at FROM repo_media WHERE repo_bi=?",
            key_bi)
        for media in media_rows or []:
            media_url = "/api/repo/%s/%s/media/%s.png?v=%d" % (
                quote(owner), quote(repo), media.get("kind", ""),
                int(media.get("updated_at") or 0))
            if media.get("kind") == "logo":
                icon_url = media_url
            elif media.get("kind") == "banner":
                image_url = media_url
        if icon_url == AP_AVATAR_PATH:
            logo_version = _repository_social_version(rec)
            icon_url = "/api/repo/%s/%s/logo?image=1" % (
                quote(owner), quote(repo))
            if logo_version:
                icon_url += "&v=" + quote(logo_version, safe="")
        actor_bi = await _ap_actor_bi(self.env, AP_ACTOR_REPO, handle)
        followers_row = await d1_first(
            self.env, "SELECT COUNT(*) AS c FROM ap_followers WHERE actor_bi=?",
            actor_bi)
        followers = int((followers_row or {}).get("c") or 0)
        post_rows = await d1_all(
            self.env,
            "SELECT data, published FROM ap_objects WHERE actor_bi=?"
            " ORDER BY published DESC LIMIT 20", actor_bi)
        posts = []
        for row in post_rows or []:
            note_rec = await decrypt_row(self.env, row.get("data"))
            note = (note_rec or {}).get("note") or {}
            content = note.get("content") or ""  # our own generated, safe HTML
            if not content:
                continue
            when = ap.iso_utc(int(row.get("published") or 0))[:10]
            link = str(note.get("url") or "")
            link_html = ("<a class=\"lnk\" href=\"%s\">View →</a>"
                         % _html_escape(link)) if link else ""
            posts.append(
                "<article class=\"post\"><div class=\"body\">%s</div>"
                "<div class=\"meta\"><time>%s</time>%s</div></article>"
                % (content, _html_escape(when), link_html))
        if not posts:
            posts.append(
                "<p class=\"empty\">No federated posts yet — new issues, "
                "pull requests, discussions and releases will appear here.</p>")
        title = _html_escape("%s/%s" % (owner, repo))
        handle_full = _html_escape("@%s@%s" % (handle, _ap_domain_of(origin)))
        code_url = _html_escape(origin + repo_web_href(owner, repo))
        actor_json = _html_escape(
            "%s/ap/repos/%s/%s" % (origin, quote(owner), quote(repo)))
        bio = (_html_escape(description) if description else
               "ForkMesh repository — follow for new issues, pull "
               "requests, discussions and releases.")
        body = _repo_fedi_profile_html(
            title=title, bio=bio, handle_full=handle_full, code_url=code_url,
            actor_json=actor_json, icon_url=_html_escape(icon_url),
            image_url=_html_escape(image_url), followers=followers,
            post_count=len(post_rows or []), posts_html="\n".join(posts))
        page = Response(body, status=200, headers={
            "content-type": "text/html; charset=utf-8",
            "cache-control": "public, max-age=300",
        })
        await edge_cache_put(cache_key, page)
        return page

    async def _serve_dashboard_asset(self, url, asset_rel):
        # The per-page dashboard documents are generated by
        # tools/build_dashboard_assets.py. env.ASSETS.fetch serves the static
        # file directly from the assets binding, avoiding Pyodide CPU/GIL
        # pressure on hot dashboard navigation.
        base = url.scheme + "://" + url.netloc + "/"
        try:
            resp = await self.env.ASSETS.fetch(base + asset_rel)
            body = await resp.text()
        except Exception:
            body = "<!doctype html><title>ForkMesh Dashboard</title>"
        return Response(body, status=200, headers={
            "content-type": "text/html; charset=utf-8",
            "cache-control": "public, max-age=300",
        })

    async def _serve_homepage(self, url):
        # Root remains the regular product/source-code website for guests and
        # signed-in visitors alike. It embeds the World in a bounded iframe and
        # links to /world/ for full-screen play. no-cache permits ETag
        # revalidation without pinning an old shell after deploy.
        base = url.scheme + "://" + url.netloc + "/"
        # Stream the asset body rather than buffering and rebuilding the
        # highest-traffic document in the Python isolate.
        try:
            resp = await self.env.ASSETS.fetch(base + "index.html")
            return JsResponse.new(resp.body, to_js({
                "status": 200,
                "headers": {
                    "content-type": "text/html; charset=utf-8",
                    "cache-control": "no-cache",
                },
            }))
        except Exception:
            return Response(
                "<!doctype html><title>ForkMesh</title>",
                status=200,
                headers={
                    "content-type": "text/html; charset=utf-8",
                    "cache-control": "no-cache",
                },
            )

    async def _git_host(self, request, owner_raw, repo_raw):
        # Legacy compatibility boundary. Public clone traffic never reaches
        # this method; authorized private Git clients are directed to the
        # owner-sealed archive transport without consuming their request body.
        owner = safe_segment(owner_raw)
        repo = safe_segment(repo_raw)
        if not owner or not repo:
            return Response("not found", status=404)
        url = urlparse(request.url)
        is_info = url.path.endswith("/info/refs")
        # Named Git URLs never advertise or proxy private content. Authorized
        # private clients discover an opaque locator in their ACL-gated catalog
        # and use the dedicated identity-free HTTPS endpoint.
        repo_private = await _repo_is_private(self.env, owner, repo)
        if repo_private:
            return _private_replica_not_found()
        operation = "git-info-refs" if is_info else "git-upload-pack"
        return await _https_mirror_proxy(
            self.env, request, owner, repo, operation)

    async def _git_push(self, request, owner_raw, repo_raw):
        # Direct HTTPS receive-pack is not implemented yet, so fail closed
        # before reading a request body.
        del request
        owner = safe_segment(owner_raw)
        repo = safe_segment(repo_raw)
        if not owner or not repo:
            return Response("not found", status=404)
        # Deliberate fail-closed protocol answer (every push probe by a git
        # client or crawler lands here) — not a worker failure, so it carries
        # the expected-degraded marker instead of logging an error per probe.
        return json_response({
            "error": "direct_https_receive_pack_required",
            "repositoryBytesAccepted": False,
            "socketFallback": False,
        }, status=501, cache_control="no-store",
            extra_headers=EXPECTED_DEGRADED_HEADERS)


async def chat_history_recent(env, room_key):
    # The last few days of retained (encrypted) messages for a room, oldest
    # first, so a joining client can replay them in order.
    await ensure_schema(env)
    cutoff = int(Date.now()) - CHAT_HISTORY_RETAIN_MS
    rows = await d1_all(
        env,
        "SELECT body FROM chat_history WHERE room_key=? AND ts>=? "
        "ORDER BY ts ASC, msg_id ASC LIMIT ?",
        room_key, cutoff, CHAT_HISTORY_MAX_PER_ROOM,
    )
    return [str(r["body"]) for r in rows]


async def chat_history_since(env, room_key, since_ts=0):
    # The same retained (encrypted) frames chat_history_recent replays to a
    # joining socket, but stamped with their store time and filtered to what
    # landed after `since_ts`, so an HTTP client can poll a room incrementally.
    await ensure_schema(env)
    try:
        since = int(since_ts or 0)
    except (TypeError, ValueError):
        since = 0
    cutoff = max(since, int(Date.now()) - CHAT_HISTORY_RETAIN_MS)
    rows = await d1_all(
        env,
        "SELECT ts,body FROM chat_history WHERE room_key=? AND ts>? "
        "ORDER BY ts ASC, msg_id ASC LIMIT ?",
        room_key, cutoff, CHAT_HISTORY_MAX_PER_ROOM,
    )
    return [
        {"ts": int(r["ts"]), "body": str(r["body"])}
        for r in rows
    ]


async def chat_history_store(env, room_key, msg_id, ts, body):
    await ensure_schema(env)
    await d1_run(
        env,
        "INSERT INTO chat_history (room_key, msg_id, ts, body) VALUES (?, ?, ?, ?) "
        "ON CONFLICT(room_key, msg_id) DO NOTHING",
        room_key, msg_id, ts, body,
    )
    await _chat_history_prune_bounds(env, room_key)


async def _chat_history_prune_bounds(env, room_key):
    # Enforce count and aggregate-byte limits in one deterministic statement.
    # The body is an ASCII JSON envelope, so SQLite length(body) equals its UTF-8
    # storage bytes. Window totals are newest-first; any older overflow rows are
    # deleted without decrypting their contents.
    await d1_run(
        env,
        "DELETE FROM chat_history WHERE room_key=? AND msg_id IN ("
        "SELECT msg_id FROM ("
        "SELECT msg_id,"
        "ROW_NUMBER() OVER (ORDER BY ts DESC,msg_id DESC) AS row_number,"
        "SUM(length(body)) OVER (ORDER BY ts DESC,msg_id DESC) AS retained_bytes "
        "FROM chat_history WHERE room_key=?"
        ") WHERE row_number>? OR retained_bytes>?)",
        room_key,
        room_key,
        CHAT_HISTORY_MAX_PER_ROOM,
        CHAT_HISTORY_MAX_BYTES_PER_ROOM,
    )


async def chat_history_prune(env, room_key):
    # Drop anything past the retention window, then enforce count and aggregate
    # encrypted-byte limits before replaying the room.
    cutoff = int(Date.now()) - CHAT_HISTORY_RETAIN_MS
    await d1_run(env, "DELETE FROM chat_history WHERE room_key=? AND ts<?",
                 room_key, cutoff)
    await _chat_history_prune_bounds(env, room_key)


async def chat_history_prune_expired(env):
    # chat_history_prune() above only runs when a client joins that specific
    # room, so a room nobody reconnects to would otherwise retain messages
    # past the 7-day window forever. Sweep every room's expired rows on the
    # per-minute cron (adhoc #49) so retention is enforced regardless of
    # traffic.
    await ensure_schema(env)
    cutoff = int(Date.now()) - CHAT_HISTORY_RETAIN_MS
    await d1_run(env, "DELETE FROM chat_history WHERE ts<?", cutoff)


class ForkMeshCronWatchdog(DurableObject):
    """Alarm-backed observer for successful every-minute cron completions.

    A Cron Trigger cannot report that it stopped firing: its own code is no
    longer running. This singleton Durable Object receives a heartbeat only at
    the end of a completed tick and moves its alarm three minutes forward.
    When that independent alarm expires it sends one outage email; the first
    later completion sends one recovery email. Durable Object event
    serialization also keeps the transition and email deduplication races out
    of the stateless Python Worker isolate.
    """

    traffic_binding = "FORKMESH_CRON_WATCHDOG"

    async def fetch(self, request):
        if urlparse(request.url).path != "/cron-watchdog/completed":
            return json_response({"error": "not_found"}, status=404)
        now = int(Date.now())
        outage_started_at = int(
            await self.ctx.storage.get("outage_started_at") or 0)
        notified_state = str(
            await self.ctx.storage.get("notified_state") or "")

        # Only send "recovered" if recipients previously received "outage".
        # If the provider is temporarily unavailable, leave the state intact;
        # the next minute's completion heartbeat retries without duplicating a
        # successful transition.
        if outage_started_at and notified_state == "down":
            if await _send_cron_watchdog_email(
                    self.env, True, outage_started_at, now):
                await self.ctx.storage.put("outage_started_at", 0)
                await self.ctx.storage.put("notified_state", "up")
        elif outage_started_at:
            await self.ctx.storage.put("outage_started_at", 0)
            await self.ctx.storage.put("notified_state", "up")

        await self.ctx.storage.put("last_completion_at", now)
        await self.ctx.storage.setAlarm(now + CRON_WATCHDOG_GRACE_MS)
        durable_object_traffic_note(self, messages=1)
        await durable_object_traffic_flush(self)
        return json_response({"ok": True})

    async def alarm(self, alarm_info=None):
        now = int(Date.now())
        last_completion_at = int(
            await self.ctx.storage.get("last_completion_at") or 0)
        if not last_completion_at:
            return
        deadline = last_completion_at + CRON_WATCHDOG_GRACE_MS
        if now < deadline:
            # A heartbeat raced an already-dispatched alarm. Keep the newer
            # deadline instead of manufacturing an outage.
            await self.ctx.storage.setAlarm(deadline)
            return

        outage_started_at = int(
            await self.ctx.storage.get("outage_started_at") or 0)
        if not outage_started_at:
            outage_started_at = deadline
            await self.ctx.storage.put(
                "outage_started_at", outage_started_at)
        notified_state = str(
            await self.ctx.storage.get("notified_state") or "")
        if notified_state != "down":
            delivered = await _send_cron_watchdog_email(
                self.env, False, outage_started_at, now)
            if delivered:
                await self.ctx.storage.put("notified_state", "down")
                return
        # Retry an unavailable email provider/admin-recipient lookup without
        # depending on the still-missing Cron Trigger.
        await self.ctx.storage.setAlarm(now + CRON_WATCHDOG_RETRY_MS)


class _CronJobEntrypoint:
    """Minimal receiver for Default._run_scheduled_jobs' self.env contract."""

    def __init__(self, env):
        self.env = env


class ForkMeshCronRunner(DurableObject):
    """Alarm-backed, self-rearming owner of the scheduled maintenance loop.

    The stateless Cron Trigger is only a seed and liveness reconciliation path.
    The alarm is persisted for the next minute before the current batch starts.
    A platform kill therefore loses at most the current idempotent/bounded slot;
    it cannot erase the next wake-up. Duplicate alarm delivery is suppressed
    after a slot completes. A catchable failure records bounded diagnostics and
    advances to the already-armed next minute instead of creating a retry storm.
    """

    traffic_binding = "FORKMESH_CRON_RUNNER"

    async def fetch(self, request):
        if urlparse(request.url).path != "/cron-runner/kick":
            return json_response({"error": "not_found"}, status=404)
        now = int(Date.now())
        await self.ctx.storage.put("last_trigger_kick_at", now)
        await self.ctx.storage.setAlarm(now + CRON_RUNNER_KICK_DELAY_MS)
        return json_response({"ok": True})

    async def alarm(self, alarm_info=None):
        now = int(Date.now())
        minute_slot = now // CRON_RUNNER_INTERVAL_MS
        next_alarm = (
            (minute_slot + 1) * CRON_RUNNER_INTERVAL_MS
            + CRON_RUNNER_ALARM_OFFSET_MS
        )
        # Persist the successor before any D1, asset, network, or Python task
        # work. Even an uncatchable runtime/resource-limit kill leaves it armed.
        await self.ctx.storage.setAlarm(next_alarm)

        completed_slot = int(
            await self.ctx.storage.get("last_completed_slot") or -1)
        if completed_slot >= minute_slot:
            return
        await self.ctx.storage.put("last_started_slot", minute_slot)
        await self.ctx.storage.put("last_started_at", now)
        try:
            await Default._run_scheduled_jobs(
                _CronJobEntrypoint(self.env))
        except BaseException as error:
            await self.ctx.storage.put(
                "last_failure",
                _safe_error_text(error)[:1000],
            )
            await self.ctx.storage.put("last_failure_at", int(Date.now()))
            try:
                print("cron runner alarm failed: " + _safe_error_text(error))
            except BaseException:
                pass
            return
        await self.ctx.storage.put("last_completed_slot", minute_slot)
        await self.ctx.storage.put("last_completed_at", int(Date.now()))
        await self.ctx.storage.put("last_failure", "")


class ForkMeshWorld(DurableObject):
    """Ephemeral Town Square presence and movement relay.

    The object uses the WebSocket Hibernation API, with the current allowlisted
    public state held only in each live socket's attachment. It never opens
    Durable Object storage, KV, R2, or chat history, and the only D1 rows it
    writes are content-free aggregates (moderation blocks and the System
    Capacity byte counters). Once a socket closes there is no history to read
    back and its random peer id is gone.
    """

    traffic_binding = "FORKMESH_WORLD"

    async def fetch(self, request):
        path = urlparse(request.url).path
        if path.rstrip("/") == "/api/world/online":
            if method_name(request) != "GET":
                return json_response(
                    {"error": "method_not_allowed"},
                    status=405,
                    extra_headers={"allow": "GET"},
                )
            return json_response(
                {
                    "ok": True,
                    "online": len(self._live_sockets(cleanup=True)),
                    "now": int(Date.now()),
                },
                cache_seconds=10,
            )
        if path.rstrip("/") == "/api/world/manual-block":
            return await self._manual_block(request)
        if path.rstrip("/") == "/api/world/mirror-push":
            return await self._mirror_push(request)
        if path.rstrip("/") != "/api/world/ws":
            return json_response({"error": "not_found"}, status=404)

        upgrade = request.headers.get("upgrade")
        if not (upgrade and upgrade.lower() == "websocket"):
            return json_response(
                {"error": "websocket_required"},
                status=426,
                extra_headers={"upgrade": "websocket"},
            )

        now = int(Date.now())
        peers = self._live_sockets(cleanup=True)
        if len(peers) >= world_protocol.WORLD_MAX_CONNECTIONS:
            return json_response({"error": "world_full"}, status=429)
        if not self._connection_admitted(now):
            return json_response(
                {"error": "connection_rate_limited"},
                status=429,
                extra_headers={"retry-after": "10"},
            )

        try:
            raw_country = request.headers.get("x-forkmesh-country") or ""
        except Exception:
            raw_country = ""
        live_ids = {
            str(_ws_attr(peer, "id", "") or "") for peer in peers
        }
        peer_id = ""
        for _attempt in range(4):
            candidate = new_world_peer_id()
            if (
                re.fullmatch(r"[A-Za-z0-9_-]{1,32}", candidate or "")
                and candidate not in live_ids
            ):
                peer_id = candidate
                break
        if not peer_id:
            return json_response({"error": "identity_unavailable"}, status=503)
        country_source = world_protocol.approximate_country_code(raw_country)
        trusted_claim = {}
        is_admin = False
        ticket_nonce = ""
        try:
            encoded_claim = (
                request.headers.get("x-forkmesh-world-claim") or "")
            if encoded_claim and re.fullmatch(
                    r"[A-Za-z0-9_-]{1,1024}", encoded_claim):
                padded = encoded_claim + "=" * (
                    (4 - len(encoded_claim) % 4) % 4)
                candidate = json.loads(
                    base64.urlsafe_b64decode(padded).decode())
                if isinstance(candidate, dict):
                    candidate_nonce = str(
                        candidate.get("ticketNonce") or "")
                    if re.fullmatch(
                            r"[A-Za-z0-9_-]{8,32}", candidate_nonce):
                        trusted_claim = (
                            world_protocol.trusted_presence_claim(
                                candidate.get("name", ""),
                                candidate.get(
                                    "accountStatus", "Guest"),
                                candidate.get("nodeCount", 0)))
                        is_admin = candidate.get("isAdmin") is True
                        ticket_nonce = candidate_nonce
        except Exception:
            trusted_claim = {}
            is_admin = False
            ticket_nonce = ""
        if ticket_nonce and any(
                hmac.compare_digest(
                    str(_ws_attr(peer, "ticket_nonce", "") or ""),
                    ticket_nonce)
                for peer in peers):
            return json_response({"error": "ticket_replayed"}, status=409)

        # One account is one avatar. When the same signed-in person joins from
        # a second device (or a second visible tab), their earlier socket is
        # retired here instead of standing beside them as a twin: every viewer
        # keeps seeing exactly one figure for that account, and it is the one
        # the person is actually driving. Only the ticket-verified account name
        # can fold two sockets together — a guest may type any display name, so
        # guests are never combined and no unverified name can evict anyone.
        account_key = world_protocol.account_presence_key(
            trusted_claim.get("name", ""))
        if account_key:
            replaced = [
                peer for peer in peers
                if _ws_attr(peer, "account_key", "") == account_key
            ]
            for peer in replaced:
                self._depart(
                    peer, WORLD_ACCOUNT_TAKEOVER_CODE,
                    "moved to your newest device")
            if replaced:
                # The retired sockets release their arrival cells and drop out
                # of the newcomer's welcome snapshot.
                peers = self._live_sockets()

        state = world_protocol.default_presence(peer_id, now)
        blocked_slots = []
        for peer in peers:
            blocked_slots.append(_ws_attr(peer, "arrival_slot", -1))
            if _ws_attr(peer, "space", "") == "town-square":
                # A visitor who restored a saved spot onto an arrival cell
                # blocks that cell even without a matching reservation.
                blocked_slots.append(
                    world_protocol.arrival_slot_near_position(
                        _ws_attr(peer, "x", None), _ws_attr(peer, "z", None)))
        arrival_slot = world_protocol.first_available_arrival_slot(
            blocked_slots)
        state.update(world_protocol.arrival_position(arrival_slot))
        moderation_tokens = {}
        for target_type in ("ip", "agent"):
            try:
                token = str(request.headers.get(
                    "x-forkmesh-world-%s-token" % target_type) or "")
            except Exception:
                token = ""
            moderation_tokens[target_type] = (
                token if re.fullmatch(r"[a-f0-9]{64}", token) else "")
        try:
            client_ip = str(
                request.headers.get("x-forkmesh-world-private-ip") or "")
            client_ip = str(ipaddress.ip_address(client_ip))[:64]
        except Exception:
            client_ip = ""
        try:
            client_user_agent = clean_string(
                request.headers.get(
                    "x-forkmesh-world-private-agent") or "", 1024)
        except Exception:
            client_user_agent = ""
        if trusted_claim:
            # The name and operator count remain private attachment fields
            # until the owner's first presence frame opts into each one.
            state["accountStatus"] = trusted_claim["accountStatus"]

        client, server = WebSocketPair.new().object_values()
        self.ctx.acceptWebSocket(server, to_js(["world"]))
        self._save_attachment(
            server, state, last=now, rate_start=now, rate_count=0,
            country_source=country_source,
            trusted_name=trusted_claim.get("name", ""),
            trusted_node_count=trusted_claim.get("nodeCount", 0),
            arrival_slot=arrival_slot, is_admin=is_admin,
            ip_token=moderation_tokens["ip"],
            agent_token=moderation_tokens["agent"],
            client_ip=client_ip,
            client_user_agent=client_user_agent,
            ticket_nonce=ticket_nonce)

        # The only snapshot is the state of sockets alive right now. It is sent
        # directly from runtime attachments and is never persisted or replayed.
        snapshot = [
            self._presence_for_viewer(server, peer)
            for peer in peers
        ]
        self._safe_send(server, {
            "type": "welcome",
            "id": peer_id,
            "self": world_protocol.public_presence(state),
            "peers": snapshot,
        })
        self._broadcast({
            "type": "join",
            "peer": world_protocol.public_presence(state),
        }, exclude_id=peer_id, budgeted=True, moderation_subject=server)

        return JsResponse.new(
            None, to_js({"status": 101, "webSocket": client}))

    async def _mirror_push(self, request):
        """Relay a signed outer-Worker head-advance notice to every visitor.

        Only the outer Worker holds the control HMAC, so browser sockets can
        never inject or forge this frame. The frame itself carries no facts a
        client acts on directly — viewers re-read the signed public mirror
        payload and animate from that verified state.
        """
        if method_name(request) != "POST":
            return json_response({"error": "method_not_allowed"}, status=405)
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        if not isinstance(data, dict):
            return json_response({"error": "invalid_json"}, status=400)
        node = clean_string(data.get("node", ""), MAX_NODE_NAME).strip()
        repo = clean_string(data.get("repo", ""), 120).strip()
        commit = str(data.get("commit") or "").strip().lower()
        try:
            signature = str(
                request.headers.get("x-forkmesh-world-control") or "")
        except Exception:
            signature = ""
        expected = _world_mirror_push_signature(self.env, node, repo, commit)
        if (
            not node
            or not re.fullmatch(r"[0-9a-f]{40,64}", commit)
            or not hmac.compare_digest(signature, expected)
        ):
            return json_response({"error": "unauthorized"}, status=401)
        self._broadcast({
            "type": "mirror-push",
            "node": node,
            "repo": repo,
            # A short id is plenty for the announcement; the full head comes
            # from the signed mirror payload each client refreshes.
            "commit": commit[:12],
        })
        return json_response({"ok": True, "delivered": True})

    async def _manual_block(self, request):
        """Disconnect sockets selected by a signed outer-Worker command."""
        if method_name(request) != "POST":
            return json_response({"error": "method_not_allowed"}, status=405)
        try:
            data = await bounded_json_request(request)
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        if not isinstance(data, dict):
            return json_response({"error": "invalid_json"}, status=400)
        target_type = str(data.get("targetType") or "").strip().lower()
        subject_token = str(data.get("subjectToken") or "").strip().lower()
        try:
            expires_at = int(data.get("expiresAt") or 0)
        except (TypeError, ValueError):
            expires_at = 0
        try:
            signature = str(
                request.headers.get("x-forkmesh-world-control") or "")
        except Exception:
            signature = ""
        expected = _world_manual_control_signature(
            self.env, target_type, subject_token, expires_at)
        now = int(Date.now())
        if (
            target_type not in ("ip", "agent")
            or not re.fullmatch(r"[a-f0-9]{64}", subject_token)
            or expires_at <= now
            or expires_at > now + WORLD_MANUAL_BLOCK_MAX_MS
            or not hmac.compare_digest(signature, expected)
        ):
            return json_response({"error": "unauthorized"}, status=401)
        disconnected = 0
        token_field = target_type + "_token"
        for peer in list(self._live_sockets(cleanup=True)):
            if _ws_attr(peer, token_field, "") != subject_token:
                continue
            disconnected += 1
            self._depart(peer, 1008, "temporary manual moderation")
        return json_response({"ok": True, "disconnected": disconnected})

    def _socket_state(self, ws):
        attachment = _ws_attachment(ws)
        if attachment is None:
            return {}
        return {
            field: getattr(attachment, field, None)
            for field in world_protocol.WORLD_PUBLIC_FIELDS
        }

    def _save_attachment(self, ws, state, last, rate_start, rate_count,
                         departed=False, country_source=None,
                         trusted_name=None, trusted_node_count=None,
                         pending_knocks=None, arrival_slot=None, is_admin=None,
                         ip_token=None, agent_token=None, ticket_nonce=None,
                         client_ip=None, client_user_agent=None):
        if country_source is None:
            country_source = _ws_attr(ws, "country_source", "")
        if trusted_name is None:
            trusted_name = _ws_attr(ws, "trusted_name", "")
        if trusted_node_count is None:
            trusted_node_count = _ws_attr(ws, "trusted_node_count", 0)
        if pending_knocks is None:
            pending_knocks = _ws_attr(ws, "pending_knocks", [])
        if arrival_slot is None:
            arrival_slot = _ws_attr(ws, "arrival_slot", -1)
        if is_admin is None:
            is_admin = bool(_ws_attr(ws, "is_admin", False))
        if ip_token is None:
            ip_token = _ws_attr(ws, "ip_token", "")
        if agent_token is None:
            agent_token = _ws_attr(ws, "agent_token", "")
        if ticket_nonce is None:
            ticket_nonce = _ws_attr(ws, "ticket_nonce", "")
        if client_ip is None:
            client_ip = _ws_attr(ws, "client_ip", "")
        if client_user_agent is None:
            client_user_agent = _ws_attr(ws, "client_user_agent", "")
        pending_knocks = [
            str(peer_id)
            for peer_id in list(pending_knocks or [])[-8:]
            if re.fullmatch(r"[A-Za-z0-9_-]{1,64}", str(peer_id or ""))
        ]
        trusted_fields = world_protocol.trusted_presence_claim(
            trusted_name or "", "Guest", trusted_node_count)
        attachment = {
            **world_protocol.public_presence(state),
            # Kept only in this live socket attachment so a user's privacy
            # control can restore their edge-derived flag after hiding it.
            "country_source":
                world_protocol.approximate_country_code(country_source),
            # These server-validated sources never leave the attachment
            # directly. sanitize_message exposes them only when the user opts
            # into name/operator-belt sharing.
            "trusted_name": trusted_fields["name"] if trusted_name else "",
            "trusted_node_count": trusted_fields["nodeCount"],
            # The private "one account, one avatar" key. It never reaches a
            # frame; it only lets a later connection from the same verified
            # account retire this socket instead of standing beside it.
            "account_key": (
                world_protocol.account_presence_key(trusted_fields["name"])
                if trusted_name else ""),
            # These opaque rotating subjects and authorization bit remain
            # private attachment data. Only `_presence_for_viewer` can project
            # the handles, and only to a server-verified administrator.
            "is_admin": bool(is_admin),
            "ip_token": (
                str(ip_token)
                if re.fullmatch(r"[a-f0-9]{64}", str(ip_token or ""))
                else ""),
            "agent_token": (
                str(agent_token)
                if re.fullmatch(r"[a-f0-9]{64}", str(agent_token or ""))
                else ""),
            # Ephemeral guest-moderation detail. These fields live only in the
            # active socket attachment and are projected only to a
            # server-verified platform administrator by
            # `_presence_for_viewer`.
            "client_ip": clean_string(client_ip or "", 64),
            "client_user_agent": clean_string(
                client_user_agent or "", 1024),
            "ticket_nonce": (
                str(ticket_nonce)
                if re.fullmatch(
                    r"[A-Za-z0-9_-]{8,32}",
                    str(ticket_nonce or ""))
                else ""),
            # One-use, live-socket-only consent requests. They are never
            # persisted, broadcast, or exposed in the public presence record.
            "pending_knocks": pending_knocks,
            # A room-local collision-avoidance index. It is never broadcast,
            # persisted, or derived from an account/network identifier.
            "arrival_slot": int(arrival_slot),
            "last": int(last or 0),
            "rl_start": int(rate_start or 0),
            "rl_count": int(rate_count or 0),
            "departed": bool(departed),
        }
        try:
            ws.serializeAttachment(to_js(attachment))
        except Exception:
            pass

    def _presence_for_viewer(self, viewer, subject):
        public = world_protocol.public_presence(self._socket_state(subject))
        is_admin = bool(_ws_attr(viewer, "is_admin", False))
        if not is_admin:
            return public
        handles = {}
        for target_type in ("ip", "agent"):
            token = str(_ws_attr(subject, target_type + "_token", "") or "")
            if re.fullmatch(r"[a-f0-9]{64}", token):
                handles[target_type] = token
        if handles:
            public["moderationHandles"] = handles
        if str(public.get("accountStatus") or "Guest") == "Guest":
            ip_value = clean_string(
                _ws_attr(subject, "client_ip", "") or "", 64)
            agent_value = clean_string(
                _ws_attr(subject, "client_user_agent", "") or "", 1024)
            if ip_value or agent_value:
                public["adminGuestNetwork"] = {
                    "ipAddress": ip_value,
                    "userAgent": agent_value,
                }
        return public

    def _mark_departed(self, ws):
        self._save_attachment(
            ws,
            self._socket_state(ws),
            last=_ws_attr(ws, "last", 0),
            rate_start=_ws_attr(ws, "rl_start", 0),
            rate_count=_ws_attr(ws, "rl_count", 0),
            departed=True,
        )

    def _live_sockets(self, cleanup=False):
        now = int(Date.now())
        try:
            sockets = self.ctx.getWebSockets("world")
        except Exception:
            sockets = []
        live = []
        stale_ids = []
        for socket in sockets:
            # A close/error path marks the attachment before asking the runtime
            # to close it. Hibernation may still return that socket briefly;
            # exclude it without producing a duplicate leave frame.
            if bool(_ws_attr(socket, "departed", False)):
                if cleanup:
                    self._safe_close(socket, 1000, "")
                continue
            if world_protocol.presence_is_stale(
                    _ws_attr(socket, "last", 0), now):
                stale_id = _ws_attr(socket, "id")
                if stale_id:
                    stale_ids.append(stale_id)
                if cleanup:
                    self._mark_departed(socket)
                    self._safe_close(socket, 1001, "stale")
                continue
            live.append(socket)

        # Tell remaining clients to remove stale avatars immediately. Marking
        # the socket departed before close prevents webSocketClose from sending
        # the same leave twice.
        if cleanup and stale_ids:
            for stale_id in stale_ids:
                frame = {"type": "leave", "id": stale_id}
                for peer in live:
                    self._safe_send(peer, frame)
        return live

    def _rate_step(self, ws, state, now):
        allowed, start, count = world_protocol.advance_rate_window(
            _ws_attr(ws, "rl_start", 0),
            _ws_attr(ws, "rl_count", 0),
            now,
        )
        # Invalid or over-limit frames do not refresh last-seen and therefore
        # cannot keep a dead/spamming avatar alive indefinitely.
        self._save_attachment(
            ws, state,
            last=_ws_attr(ws, "last", 0),
            rate_start=start,
            rate_count=count,
            departed=bool(_ws_attr(ws, "departed", False)),
        )
        return allowed, start, count

    def _connection_admitted(self, now):
        allowed, start, count = world_protocol.advance_connection_window(
            getattr(self, "_connect_window", 0),
            getattr(self, "_connect_count", 0),
            now,
        )
        self._connect_window = start
        self._connect_count = count
        return allowed

    def _broadcast_admitted(self, now):
        allowed, start, count = world_protocol.advance_broadcast_window(
            getattr(self, "_broadcast_window", 0),
            getattr(self, "_broadcast_count", 0),
            now,
        )
        self._broadcast_window = start
        self._broadcast_count = count
        return allowed

    async def webSocketMessage(self, ws, message):
        if bool(_ws_attr(ws, "departed", False)):
            self._safe_close(ws, 1000, "")
            return
        if not isinstance(message, str):
            self._safe_close(ws, 1003, "text frames only")
            return
        if len(message.encode("utf-8")) > world_protocol.WORLD_MESSAGE_MAX_BYTES:
            self._safe_close(ws, 1009, "message too large")
            return
        durable_object_traffic_note(
            self, bytes_in=len(message.encode("utf-8")), messages=1)
        await durable_object_traffic_flush(self)

        state = self._socket_state(ws)
        if not state.get("id"):
            self._safe_close(ws, 1008, "invalid presence")
            return
        now = int(Date.now())
        if world_protocol.presence_is_stale(
                _ws_attr(ws, "last", 0), now):
            self._depart(ws, 1001, "stale")
            return
        allowed, rate_start, rate_count = self._rate_step(
            ws, state, now)
        # Every frame (including a heartbeat or invalid JSON) is an opportunity
        # to reap peers that vanished without a close event.
        self._live_sockets(cleanup=True)

        try:
            payload = json.loads(message)
        except Exception:
            if not allowed:
                self._safe_close(ws, 1008, "rate limit")
            return
        if not allowed:
            kind = (
                str(payload.get("type") or "").strip().lower()
                if isinstance(payload, dict) else ""
            )
            disposable = kind in ("move", "presence", "ping")
            hard_limit = world_protocol.WORLD_RATE_HARD_MAX_PER_WINDOW
            if disposable and rate_count <= hard_limit:
                # Keep the latest accepted attachment as the coalesced state.
                # A subsequent frame in a fresh window will carry the browser's
                # newest position/profile, so a normal connect+movement burst
                # sheds traffic instead of tearing down the multiplayer socket.
                return
            self._safe_close(
                ws,
                1008,
                "sustained rate limit" if disposable else "rate limit",
            )
            return
        interaction = world_protocol.sanitize_interaction(payload, state)
        if interaction is not None:
            # Home interactions are targeted, text-free consent frames. The
            # server keeps at most eight one-use knocks inside the live socket
            # attachment; hibernation/disconnect naturally expires them.
            # Sender identity always comes from the attachment, never JSON.
            self._save_attachment(
                ws, state, last=now,
                rate_start=rate_start, rate_count=rate_count)
            if interaction["kind"] == "knock":
                for peer in self._live_sockets(cleanup=True):
                    if (
                        _ws_attr(peer, "id") == interaction["target"]
                        and _ws_attr(peer, "publicDoor", "closed") == "knock"
                    ):
                        pending = list(
                            _ws_attr(peer, "pending_knocks", []) or [])
                        if state.get("id") not in pending:
                            pending.append(state.get("id"))
                        self._save_attachment(
                            peer,
                            self._socket_state(peer),
                            last=_ws_attr(peer, "last", now),
                            rate_start=_ws_attr(peer, "rl_start", now),
                            rate_count=_ws_attr(peer, "rl_count", 0),
                            pending_knocks=pending[-8:],
                        )
                        self._safe_send(peer, {
                            "type": "interaction",
                            "kind": "knock",
                            "from": state.get("id"),
                        })
                        break
            elif interaction["kind"] in ("home-grant", "home-decline"):
                pending = list(
                    _ws_attr(ws, "pending_knocks", []) or [])
                if interaction["target"] not in pending:
                    return
                pending = [
                    peer_id for peer_id in pending
                    if peer_id != interaction["target"]
                ]
                self._save_attachment(
                    ws, state, last=now,
                    rate_start=rate_start, rate_count=rate_count,
                    pending_knocks=pending,
                )
                for peer in self._live_sockets(cleanup=True):
                    if _ws_attr(peer, "id") == interaction["target"]:
                        self._safe_send(peer, {
                            "type": "interaction",
                            "kind": interaction["kind"],
                            "from": state.get("id"),
                        })
                        break
            else:
                self._broadcast({
                    "type": "interaction",
                    "kind": "emote",
                    "emote": interaction["emote"],
                    "from": state.get("id"),
                }, exclude_id=state.get("id"), budgeted=True)
            return
        sanitized = world_protocol.sanitize_message(
            payload, state, now,
            country_source=_ws_attr(ws, "country_source", ""),
            trusted_name=_ws_attr(ws, "trusted_name", ""),
            trusted_node_count=_ws_attr(ws, "trusted_node_count", 0))
        if sanitized is None:
            return
        kind, state = sanitized
        self._save_attachment(
            ws, state, last=now,
            rate_start=rate_start, rate_count=rate_count)

        if kind == "ping":
            self._safe_send(ws, {"type": "pong", "serverTimeMs": now})
            return
        if kind == "presence":
            frame = {
                "type": "presence",
                "peer": world_protocol.public_presence(state),
            }
        else:
            frame = world_protocol.movement_delta(state)
        self._broadcast(
            frame, exclude_id=state.get("id"), budgeted=True,
            moderation_subject=ws if kind == "presence" else None)

    async def webSocketClose(self, ws, code, reason, was_clean):
        self._depart(ws, 1000, "")
        # A closing socket is the last chance to bank this instance's pending
        # byte counts before the object hibernates.
        await durable_object_traffic_flush(self, force=True)

    async def webSocketError(self, ws, error):
        self._depart(ws, 1011, "socket error")

    # Hibernation events may be dispatched under either naming convention.
    web_socket_message = webSocketMessage
    web_socket_close = webSocketClose
    web_socket_error = webSocketError

    def _depart(self, ws, code, reason):
        peer_id = _ws_attr(ws, "id")
        departed = bool(_ws_attr(ws, "departed", False))
        self._mark_departed(ws)
        self._safe_close(ws, code, reason)
        if peer_id and not departed:
            self._broadcast(
                {"type": "leave", "id": peer_id},
                exclude_id=peer_id,
            )

    def _broadcast(self, frame, exclude_id=None, budgeted=False,
                   moderation_subject=None):
        if budgeted and not self._broadcast_admitted(int(Date.now())):
            # State still updates in the sender's attachment, so the next
            # welcome snapshot is current even when a hot movement delta drops.
            return
        for peer in self._live_sockets(cleanup=True):
            if exclude_id and _ws_attr(peer, "id") == exclude_id:
                continue
            outgoing = frame
            if (
                moderation_subject is not None
                and isinstance(frame.get("peer"), dict)
                and bool(_ws_attr(peer, "is_admin", False))
            ):
                outgoing = {
                    **frame,
                    "peer": self._presence_for_viewer(
                        peer, moderation_subject),
                }
            self._safe_send(peer, outgoing)

    def _safe_send(self, ws, frame):
        payload = json.dumps(frame, separators=(",", ":"))
        try:
            ws.send(payload)
        except Exception:
            self._safe_close(ws, 1011, "unavailable")
            return
        durable_object_traffic_note(
            self, bytes_out=len(payload.encode("utf-8")))

    def _safe_close(self, ws, code, reason):
        try:
            ws.close(code, reason)
        except Exception:
            pass


class ForkMeshOfficeRoom(DurableObject):
    """Ephemeral authorized avatar and chair relay for one Office room."""

    traffic_binding = "FORKMESH_OFFICE_ROOM"

    async def fetch(self, request):
        path = urlparse(request.url).path
        match = OFFICE_INTERNAL_RE.fullmatch(path)
        if not match:
            return json_response({"error": "not_found"}, status=404)
        scope, version_raw, action = match.groups()
        if action == "revoke" and method_name(request) == "POST":
            self._close_all(1008, "room access revoked")
            return json_response({"ok": True})
        if (
            action != "ws"
            or method_name(request) != "GET"
            or (request.headers.get("upgrade") or "").lower() != "websocket"
        ):
            return json_response({"error": "not_found"}, status=404)

        claim = self._claim(request)
        if (
            not claim
            or claim.get("scope") != scope
            or int(claim.get("version") or 0) != int(version_raw)
        ):
            return json_response({"error": "not_found"}, status=404)
        now = int(Date.now())
        peers = self._live_sockets(cleanup=True)
        if len(peers) >= world_protocol.OFFICE_MAX_CONNECTIONS:
            return json_response({"error": "room_full"}, status=429)
        ticket_nonce = str(claim.get("nonce") or "")
        if any(
                hmac.compare_digest(
                    str(_ws_attr(peer, "ticket_nonce", "") or ""),
                    ticket_nonce)
                for peer in peers):
            return json_response({"error": "ticket_replayed"}, status=409)

        # One account is one person in the room, exactly as in the Town Square
        # (see ForkMeshWorld). A member who opens this meeting on a second
        # device replaces their earlier socket instead of occupying two chairs
        # and two rows of "In this room". The fold key is the account binding
        # the room ticket was minted against, never a typed name.
        account_bi = str(claim.get("account_bi") or "")
        if re.fullmatch(r"[0-9a-f]{64}", account_bi):
            replaced = [
                peer for peer in peers
                if hmac.compare_digest(
                    str(_ws_attr(peer, "account_bi", "") or ""), account_bi)
            ]
            for peer in replaced:
                self._depart(
                    peer, WORLD_ACCOUNT_TAKEOVER_CODE,
                    "moved to your newest device")
            if replaced:
                # The retired sockets release their seats and drop out of the
                # newcomer's participant snapshot.
                peers = self._live_sockets()

        live_ids = {
            str(_ws_attr(peer, "id", "") or "") for peer in peers
        }
        participant_id = ""
        for _attempt in range(4):
            candidate = new_world_peer_id()
            if (
                re.fullmatch(r"[A-Za-z0-9_-]{1,32}", candidate or "")
                and candidate not in live_ids
            ):
                participant_id = candidate
                break
        if not participant_id:
            return json_response({"error": "identity_unavailable"}, status=503)
        state = world_protocol.default_office_presence(participant_id, now)
        sanitized = world_protocol.sanitize_office_message(
            {"type": "presence"},
            state,
            now,
            trusted_name=claim.get("name", ""),
            trusted_account_status=claim.get("accountStatus", "Guest"),
        )
        if sanitized is not None:
            _kind, state = sanitized
        client, server = WebSocketPair.new().object_values()
        self.ctx.acceptWebSocket(server, to_js(["office"]))
        self._save_socket(
            server,
            state,
            last=now,
            rate_start=now,
            rate_count=0,
            account_bi=claim.get("account_bi", ""),
            session_id=claim.get("session_id", ""),
            scope=scope,
            version=int(version_raw),
            trusted_name=claim.get("name", ""),
            trusted_status=claim.get("accountStatus", "Guest"),
            ticket_nonce=ticket_nonce,
            auth_checked_at=now,
        )
        self._safe_send(server, {
            "type": "welcome",
            "id": participant_id,
            "participants": [
                world_protocol.public_office_presence(
                    self._socket_state(peer))
                for peer in peers
            ],
        })
        self._broadcast({
            "type": "join",
            "participant": world_protocol.public_office_presence(state),
        }, exclude_id=participant_id, budgeted=True)
        return JsResponse.new(
            None, to_js({"status": 101, "webSocket": client}))

    def _claim(self, request):
        try:
            raw = request.headers.get("x-forkmesh-office-claim") or ""
            if not re.fullmatch(r"[A-Za-z0-9_-]{1,2048}", raw):
                return None
            padded = raw + "=" * ((4 - len(raw) % 4) % 4)
            claim = json.loads(base64.urlsafe_b64decode(padded).decode())
        except Exception:
            return None
        if not isinstance(claim, dict):
            return None
        scope = str(claim.get("scope") or "")
        if scope != "world-general" and not re.fullmatch(
                r"[0-9a-f]{32}", scope):
            return None
        account_bi = str(claim.get("account_bi") or "")
        if not re.fullmatch(r"[0-9a-f]{64}", account_bi):
            return None
        session_id = str(claim.get("session_id") or "")
        if not re.fullmatch(r"[A-Za-z0-9_-]{24,64}", session_id):
            return None
        try:
            version = int(claim.get("version") or 0)
        except (TypeError, ValueError):
            return None
        if version < 1:
            return None
        trusted = world_protocol.trusted_presence_claim(
            claim.get("name", ""),
            claim.get("accountStatus", "Guest"),
            0,
        )
        nonce = str(claim.get("nonce") or "")
        if not re.fullmatch(r"[A-Za-z0-9_-]{8,32}", nonce):
            return None
        return {
            "scope": scope,
            "version": version,
            "account_bi": account_bi,
            "session_id": session_id,
            "name": trusted["name"] if claim.get("name") else "",
            "accountStatus": trusted["accountStatus"],
            "nonce": nonce,
        }

    def _socket_state(self, ws):
        return {
            field: _ws_attr(ws, field)
            for field in world_protocol.OFFICE_PUBLIC_FIELDS
        }

    def _save_socket(self, ws, state, last, rate_start, rate_count,
                     departed=False, account_bi=None, session_id=None,
                     scope=None, version=None,
                     trusted_name=None, trusted_status=None,
                     ticket_nonce=None, auth_checked_at=None):
        if account_bi is None:
            account_bi = _ws_attr(ws, "account_bi", "")
        if session_id is None:
            session_id = _ws_attr(ws, "session_id", "")
        if scope is None:
            scope = _ws_attr(ws, "scope", "")
        if version is None:
            version = _ws_attr(ws, "version", 0)
        if trusted_name is None:
            trusted_name = _ws_attr(ws, "trusted_name", "")
        if trusted_status is None:
            trusted_status = _ws_attr(ws, "trusted_status", "Guest")
        if ticket_nonce is None:
            ticket_nonce = _ws_attr(ws, "ticket_nonce", "")
        if auth_checked_at is None:
            auth_checked_at = _ws_attr(ws, "auth_checked_at", 0)
        record = {
            **world_protocol.public_office_presence(state),
            "account_bi": str(account_bi or ""),
            "session_id": (
                str(session_id)
                if re.fullmatch(
                    r"[A-Za-z0-9_-]{24,64}", str(session_id or ""))
                else ""),
            "scope": str(scope or ""),
            "version": int(version or 0),
            "trusted_name": str(trusted_name or ""),
            "trusted_status": str(trusted_status or "Guest"),
            "ticket_nonce": (
                str(ticket_nonce)
                if re.fullmatch(
                    r"[A-Za-z0-9_-]{8,32}",
                    str(ticket_nonce or ""))
                else ""),
            "auth_checked_at": int(auth_checked_at or 0),
            "last": int(last or 0),
            "rl_start": int(rate_start or 0),
            "rl_count": int(rate_count or 0),
            "departed": bool(departed),
        }
        try:
            ws.serializeAttachment(to_js(record))
            return True
        except Exception:
            return False

    def _mark_departed(self, ws):
        self._save_socket(
            ws,
            self._socket_state(ws),
            last=_ws_attr(ws, "last", 0),
            rate_start=_ws_attr(ws, "rl_start", 0),
            rate_count=_ws_attr(ws, "rl_count", 0),
            departed=True,
        )

    def _live_sockets(self, cleanup=False):
        now = int(Date.now())
        try:
            sockets = self.ctx.getWebSockets("office")
        except Exception:
            sockets = []
        live = []
        stale_ids = []
        for socket in sockets:
            if bool(_ws_attr(socket, "departed", False)):
                if cleanup:
                    self._safe_close(socket, 1000, "")
                continue
            if world_protocol.office_presence_is_stale(
                    _ws_attr(socket, "last", 0), now):
                stale_id = _ws_attr(socket, "id", "")
                if stale_id:
                    stale_ids.append(stale_id)
                if cleanup:
                    self._mark_departed(socket)
                    self._safe_close(socket, 1001, "stale")
                continue
            live.append(socket)
        if cleanup:
            for stale_id in stale_ids:
                for peer in live:
                    self._safe_send(peer, {"type": "leave", "id": stale_id})
        return live

    def _rate_step(self, ws, state, now):
        allowed, start, count = world_protocol.advance_office_rate_window(
            _ws_attr(ws, "rl_start", 0),
            _ws_attr(ws, "rl_count", 0),
            now,
        )
        self._save_socket(
            ws,
            state,
            last=_ws_attr(ws, "last", 0),
            rate_start=start,
            rate_count=count,
            departed=bool(_ws_attr(ws, "departed", False)),
        )
        return allowed, start, count

    def _broadcast_admitted(self, now):
        allowed, start, count = world_protocol.advance_office_broadcast_window(
            getattr(self, "_broadcast_window", 0),
            getattr(self, "_broadcast_count", 0),
            now,
        )
        self._broadcast_window = start
        self._broadcast_count = count
        return allowed

    def _access_recheck_due(self, ws, now):
        try:
            checked_at = int(_ws_attr(ws, "auth_checked_at", 0) or 0)
            now = int(now)
        except (TypeError, ValueError):
            return True
        return (
            checked_at <= 0
            or now < checked_at
            or now - checked_at >= OFFICE_ACCESS_RECHECK_MS
        )

    async def _access_current_if_due(
            self, ws, state, now, rate_start, rate_count):
        """Revalidate once per bounded interval and persist the check time."""
        if not self._access_recheck_due(ws, now):
            return True
        if not await self._access_current(ws, now):
            self._depart(ws, 1008, "room access revoked")
            return False
        self._save_socket(
            ws,
            state,
            last=_ws_attr(ws, "last", 0),
            rate_start=rate_start,
            rate_count=rate_count,
            departed=bool(_ws_attr(ws, "departed", False)),
            auth_checked_at=now,
        )
        return True

    async def _access_current(self, ws, now=None):
        account_bi = str(_ws_attr(ws, "account_bi", "") or "")
        session_id = str(_ws_attr(ws, "session_id", "") or "")
        scope = str(_ws_attr(ws, "scope", "") or "")
        version = int(_ws_attr(ws, "version", 0) or 0)
        now = int(Date.now()) if now is None else int(now)
        if (
            not re.fullmatch(r"[0-9a-f]{64}", account_bi)
            or not re.fullmatch(r"[A-Za-z0-9_-]{24,64}", session_id)
        ):
            return False
        try:
            account = await d1_first(
                self.env,
                "SELECT u.data,u.is_admin FROM account_sessions s "
                "JOIN users u ON u.user_bi=s.account_bi "
                "WHERE s.session_id=? AND s.account_bi=? "
                "AND s.revoked_at=0 AND s.expires_at>?",
                session_id,
                account_bi,
                now,
            )
            if not account:
                return False
            account_record = await decrypt_row(self.env, account.get("data"))
            if (
                not account_record
                or account_record.get("status") != "active"
                or _account_kind(account_record) != "user"
            ):
                return False
            if scope == "world-general":
                return True
            channel = await d1_first(
                self.env,
                "SELECT data,key_version FROM chat_channels WHERE channel_id=?",
                scope,
            )
            if (
                not channel
                or int(channel.get("key_version") or 0) != version
            ):
                return False
            channel_record = await decrypt_row(
                self.env, channel.get("data"))
            if (
                isinstance(channel_record, dict)
                and channel_record.get("visibility") == "public"
            ):
                return True
            if bool(int(account.get("is_admin") or 0)):
                return True
            membership = await d1_first(
                self.env,
                "SELECT 1 AS allowed FROM chat_channel_members "
                "WHERE channel_id=? AND member_bi=?",
                scope,
                account_bi,
            )
            return bool(membership)
        except Exception:
            return False

    async def webSocketMessage(self, ws, message):
        if bool(_ws_attr(ws, "departed", False)):
            self._safe_close(ws, 1000, "")
            return
        if not isinstance(message, str):
            self._safe_close(ws, 1003, "text frames only")
            return
        if len(message.encode("utf-8")) > world_protocol.OFFICE_MESSAGE_MAX_BYTES:
            self._safe_close(ws, 1009, "message too large")
            return
        durable_object_traffic_note(
            self, bytes_in=len(message.encode("utf-8")), messages=1)
        await durable_object_traffic_flush(self)
        state = self._socket_state(ws)
        if not state.get("id"):
            self._safe_close(ws, 1008, "invalid presence")
            return
        now = int(Date.now())
        if world_protocol.office_presence_is_stale(
                _ws_attr(ws, "last", 0), now):
            self._depart(ws, 1001, "stale")
            return
        allowed, rate_start, rate_count = self._rate_step(ws, state, now)
        if not allowed:
            self._safe_close(ws, 1008, "rate limit")
            return
        if not await self._access_current_if_due(
                ws, state, now, rate_start, rate_count):
            return
        self._live_sockets(cleanup=True)
        try:
            payload = json.loads(message)
        except Exception:
            return
        if isinstance(payload, dict) and payload.get("type") == "seat-request":
            requested = str(payload.get("chairId") or "")
            occupied = {
                str(_ws_attr(peer, "chairId", "")): str(
                    _ws_attr(peer, "id", ""))
                for peer in self._live_sockets(cleanup=True)
                if peer is not ws and _ws_attr(peer, "chairId", "")
            }
            result, next_state = world_protocol.allocate_office_seat(
                state, requested, occupied)
            if result == "invalid":
                return
            if result == "denied":
                self._safe_send(ws, {
                    "type": "seat-denied",
                    "chairId": requested,
                    "message": "Seat just taken.",
                })
                return
            next_state["updatedAt"] = now
            self._save_socket(
                ws,
                next_state,
                last=now,
                rate_start=rate_start,
                rate_count=rate_count,
            )
            self._broadcast({
                "type": "seat",
                "participant": world_protocol.public_office_presence(
                    next_state),
            }, budgeted=True)
            return
        sanitized = world_protocol.sanitize_office_message(
            payload,
            state,
            now,
            trusted_name=_ws_attr(ws, "trusted_name", ""),
            trusted_account_status=_ws_attr(
                ws, "trusted_status", "Guest"),
        )
        if sanitized is None:
            return
        kind, next_state = sanitized
        self._save_socket(
            ws,
            next_state,
            last=now,
            rate_start=rate_start,
            rate_count=rate_count,
        )
        if kind == "ping":
            self._safe_send(ws, {"type": "pong", "serverTimeMs": now})
            return
        if kind == "presence":
            frame = {
                "type": "presence",
                "participant": world_protocol.public_office_presence(
                    next_state),
            }
        else:
            frame = world_protocol.office_movement_delta(next_state)
        self._broadcast(
            frame, exclude_id=state.get("id"), budgeted=True)

    async def webSocketClose(self, ws, code, reason, was_clean):
        self._depart(ws, 1000, "")
        await durable_object_traffic_flush(self, force=True)

    async def webSocketError(self, ws, error):
        self._depart(ws, 1011, "socket error")

    web_socket_message = webSocketMessage
    web_socket_close = webSocketClose
    web_socket_error = webSocketError

    def _depart(self, ws, code, reason):
        participant_id = _ws_attr(ws, "id", "")
        departed = bool(_ws_attr(ws, "departed", False))
        self._mark_departed(ws)
        self._safe_close(ws, code, reason)
        if participant_id and not departed:
            self._broadcast(
                {"type": "leave", "id": participant_id},
                exclude_id=participant_id,
                budgeted=True,
            )

    def _broadcast(self, frame, exclude_id=None, budgeted=False):
        if budgeted and not self._broadcast_admitted(int(Date.now())):
            return
        for peer in self._live_sockets(cleanup=False):
            if exclude_id and _ws_attr(peer, "id", "") == exclude_id:
                continue
            self._safe_send(peer, frame)

    def _safe_send(self, ws, frame):
        payload = json.dumps(frame, separators=(",", ":"))
        try:
            ws.send(payload)
        except Exception:
            self._safe_close(ws, 1011, "unavailable")
            return
        durable_object_traffic_note(
            self, bytes_out=len(payload.encode("utf-8")))

    def _close_all(self, code, reason):
        try:
            peers = self.ctx.getWebSockets("office")
        except Exception:
            peers = []
        for peer in peers:
            self._mark_departed(peer)
            self._safe_close(peer, code, reason)

    def _safe_close(self, ws, code, reason):
        try:
            ws.close(code, reason)
        except Exception:
            pass


class ForkMeshRoom(DurableObject):
    # Encrypted chat relay on the WebSocket Hibernation API. Sockets are accepted
    # via ctx.acceptWebSocket and serviced by the webSocketMessage/Close handlers
    # below, so the Durable Object is evicted from memory while a room is idle and
    # bills ~no duration. Connection state lives in the runtime
    # (ctx.getWebSockets("chat")), never in instance attributes — those would not
    # survive eviction. The read-only "observer" count socket was retired: the
    # live count is now served over HTTP via the cached /api/network/stats.
    traffic_binding = "FORKMESH_MAINNODE_ROOM"

    async def fetch(self, request):
        parsed_url = urlparse(request.url)
        path = parsed_url.path
        private_path = (
            CHAT_CHANNEL_DO_RE.match(path)
            or CHAT_DIRECT_MESSAGE_DO_RE.match(path)
        )
        if (
            private_path
            and private_path.group(3) == "revoke"
            and method_name(request) == "POST"
        ):
            self._close_all_chat_sockets(1008, "room access revoked")
            return json_response({"ok": True})

        upgrade = request.headers.get("upgrade")
        is_websocket = bool(upgrade) and upgrade.lower() == "websocket"

        if not is_websocket:
            # One-shot snapshot of the live client count (used by network_stats).
            return json_response({"ok": True, "clients": self._client_count()})

        if path.endswith("/clients"):
            return json_response({"error": "observers_removed"}, status=410)

        if self._client_count() >= MAX_CONNECTIONS:
            return json_response({"error": "room_full"}, status=429)

        # The room key identifies this room across hibernation; stash it on the
        # socket so webSocketMessage can scope retained history to this room.
        account_values = parse_qs(
            parsed_url.query, keep_blank_values=False
        ).get("account") or []
        account_bi = account_values[0] if len(account_values) == 1 else ""
        info = room_key_from_path(path, account_bi)
        room_key = info["key"] if info else None

        client, server = WebSocketPair.new().object_values()
        self.ctx.acceptWebSocket(server, to_js(["chat"]))
        server.serializeAttachment(to_js({
            "id": new_socket_id(), "room": room_key,
            "channel_id": (info or {}).get("channel_id", ""),
            "channel_version": (info or {}).get("channel_version", 0),
            "direct_id": (info or {}).get("direct_id", ""),
            "direct_version": (info or {}).get("direct_version", 0),
            "account_bi": (info or {}).get("account_bi", ""),
            "last": int(Date.now()),
        }))

        # Replay retained (still-encrypted) history to the joining client so new
        # users see some recent backlog even when no peer is online to send it.
        if room_key:
            try:
                await chat_history_prune(self.env, room_key)
                for body in await chat_history_recent(self.env, room_key):
                    try:
                        server.send(body)
                    except Exception:
                        pass
                    else:
                        durable_object_traffic_note(
                            self, bytes_out=len(str(body).encode("utf-8")))
            except Exception:
                pass
            await durable_object_traffic_flush(self)

        return JsResponse.new(None, to_js({"status": 101, "webSocket": client}))

    def _client_count(self):
        try:
            return len(self._live_chat_sockets(close_stale=True))
        except Exception:
            return 0

    def _live_chat_sockets(self, close_stale=False):
        now = int(Date.now())
        sockets = []
        try:
            peers = self.ctx.getWebSockets("chat")
        except Exception:
            return sockets
        for peer in peers:
            try:
                last = int(_ws_attr(peer, "last", 0) or 0)
            except (TypeError, ValueError):
                last = 0
            if not last or now - last > ROOM_CLIENT_STALE_MS:
                if close_stale:
                    self._safe_close(peer, 1001, "stale")
                continue
            sockets.append(peer)
        return sockets

    def _rate_ok(self, ws):
        # Per-socket token bucket kept in the hibernation attachment: at most
        # ROOM_MSG_MAX_PER_WINDOW frames per ROOM_MSG_WINDOW_MS. Returns False when
        # the sender is over budget (the frame should be dropped).
        now = int(Date.now())
        try:
            start = int(_ws_attr(ws, "rl_start", 0) or 0)
            count = int(_ws_attr(ws, "rl_count", 0) or 0)
        except (TypeError, ValueError):
            start, count = 0, 0
        if now - start >= ROOM_MSG_WINDOW_MS:
            start, count = now, 0
        count += 1
        try:
            ws.serializeAttachment(to_js({
                "id": _ws_attr(ws, "id"), "room": _ws_attr(ws, "room"),
                "channel_id": _ws_attr(ws, "channel_id", ""),
                "channel_version": _ws_attr(ws, "channel_version", 0),
                "direct_id": _ws_attr(ws, "direct_id", ""),
                "direct_version": _ws_attr(ws, "direct_version", 0),
                "account_bi": _ws_attr(ws, "account_bi", ""),
                "last": now, "rl_start": start, "rl_count": count,
            }))
        except Exception:
            pass
        return count <= ROOM_MSG_MAX_PER_WINDOW

    async def webSocketMessage(self, ws, message):
        if not isinstance(message, str):
            self._safe_close(ws, 1003, "text frames only")
            return
        if len(message.encode("utf-8")) > MAX_TEXT_BYTES:
            self._safe_close(ws, 1009, "message too large")
            return
        # Drop frames from a socket that is flooding (don't relay or retain them).
        if not self._rate_ok(ws):
            return
        if not await self._private_room_current(ws):
            self._close_all_chat_sockets(1008, "room access revoked")
            return
        frame_bytes = len(message.encode("utf-8"))
        durable_object_traffic_note(self, bytes_in=frame_bytes, messages=1)
        sender_id = _ws_attr(ws, "id")
        for peer in self._live_chat_sockets(close_stale=True):
            if _ws_attr(peer, "id") == sender_id:
                continue
            try:
                peer.send(message)
            except Exception:
                pass
            else:
                durable_object_traffic_note(self, bytes_out=frame_bytes)
        await durable_object_traffic_flush(self)

        # Retain durable conversation messages (still encrypted) for late joiners.
        await self._maybe_retain(ws, message)

    async def _maybe_retain(self, ws, message):
        room_key = _ws_attr(ws, "room")
        if not room_key:
            return
        message_bytes = len(message.encode("utf-8"))
        if message_bytes > CHAT_HISTORY_MAX_BODY:
            return  # don't retain very large frames (e.g. file transfers)
        try:
            envelope = json.loads(message)
        except Exception:
            return
        if not (
            isinstance(envelope, dict)
            and envelope.get("persist") is True
        ):
            return
        if not await self._retention_ingress_admitted(message_bytes):
            return
        try:
            # The message id lives inside the ciphertext, so key retention on a
            # hash of the opaque frame (dedupes accidental re-relays).
            msg_id = (await sha256_hex(message))[:40]
            await chat_history_store(self.env, room_key, msg_id,
                                     int(Date.now()), message)
            direct_id = str(_ws_attr(ws, "direct_id", "") or "")
            account_bi = str(_ws_attr(ws, "account_bi", "") or "")
            if (
                re.fullmatch(r"[0-9a-f]{32}", direct_id)
                and re.fullmatch(r"[0-9a-f]{64}", account_bi)
            ):
                await _chat_direct_message_retained(
                    self.env, direct_id, account_bi, int(Date.now()))
        except Exception:
            pass

    async def _private_room_current(self, ws):
        direct_id = _ws_attr(ws, "direct_id", "")
        if direct_id:
            try:
                direct_version = int(
                    _ws_attr(ws, "direct_version", 0) or 0)
                account_bi = str(_ws_attr(ws, "account_bi", "") or "")
                if not re.fullmatch(r"[0-9a-f]{64}", account_bi):
                    return False
                await ensure_schema(self.env)
                conversation = await d1_first(
                    self.env,
                    "SELECT data,key_version "
                    "FROM chat_direct_conversations "
                    "WHERE conversation_id=?",
                    direct_id,
                )
                if (
                    not conversation
                    or int(conversation.get("key_version") or 0)
                        != direct_version
                ):
                    return False
                record = await decrypt_row(
                    self.env, conversation.get("data"))
                if not isinstance(record, dict):
                    return False
                account = await d1_first(
                    self.env,
                    "SELECT data,is_admin FROM users WHERE user_bi=?",
                    account_bi,
                )
                if not account:
                    return False
                account_record = await decrypt_row(
                    self.env, account.get("data"))
                if (
                    not account_record
                    or account_record.get("status") != "active"
                    or _account_kind(account_record) != "user"
                ):
                    return False
                participant = await d1_first(
                    self.env,
                    "SELECT 1 AS allowed FROM chat_direct_participants "
                    "WHERE conversation_id=? AND participant_bi=?",
                    direct_id,
                    account_bi,
                )
                return bool(participant)
            except Exception:
                return False

        channel_id = _ws_attr(ws, "channel_id", "")
        if not channel_id:
            return True
        try:
            channel_version = int(_ws_attr(ws, "channel_version", 0) or 0)
            account_bi = str(_ws_attr(ws, "account_bi", "") or "")
            if not re.fullmatch(r"[0-9a-f]{64}", account_bi):
                return False
            await ensure_schema(self.env)
            channel = await d1_first(
                self.env,
                "SELECT data,key_version FROM chat_channels WHERE channel_id=?",
                channel_id,
            )
            if (
                not channel
                or int(channel.get("key_version") or 0) != channel_version
            ):
                return False
            channel_record = await decrypt_row(
                self.env, channel.get("data"))
            if not isinstance(channel_record, dict):
                return False
            account = await d1_first(
                self.env,
                "SELECT data,is_admin FROM users WHERE user_bi=?",
                account_bi,
            )
            if not account:
                return False
            account_record = await decrypt_row(
                self.env, account.get("data"))
            if (
                not account_record
                or account_record.get("status") != "active"
                or _account_kind(account_record) != "user"
            ):
                return False
            if bool(int(account.get("is_admin") or 0)):
                return True
            if channel_record.get("visibility") == "public":
                return True
            membership = await d1_first(
                self.env,
                "SELECT 1 AS allowed FROM chat_channel_members "
                "WHERE channel_id=? AND member_bi=?",
                channel_id,
                account_bi,
            )
            return bool(membership)
        except Exception:
            return False

    async def _retention_ingress_admitted(self, message_bytes):
        now = int(Date.now())
        try:
            state = await self.ctx.storage.get("chat_history_ingress")
        except Exception:
            return False
        if hasattr(state, "to_py"):
            state = state.to_py()
        if not isinstance(state, dict):
            state = {}
        try:
            start = int(state.get("start") or 0)
            used = int(state.get("bytes") or 0)
        except (TypeError, ValueError):
            start = 0
            used = 0
        if now - start >= CHAT_HISTORY_INGRESS_WINDOW_MS:
            start = now
            used = 0
        if message_bytes < 0 or (
            used + message_bytes > CHAT_HISTORY_INGRESS_MAX_BYTES
        ):
            try:
                await self.ctx.storage.put(
                    "chat_history_ingress",
                    to_js({"start": start, "bytes": used}),
                )
            except Exception:
                pass
            return False
        try:
            await self.ctx.storage.put(
                "chat_history_ingress",
                to_js({"start": start, "bytes": used + message_bytes}),
            )
        except Exception:
            return False
        return True

    def _close_all_chat_sockets(self, code, reason):
        try:
            peers = self.ctx.getWebSockets("chat")
        except Exception:
            peers = []
        for peer in peers:
            self._safe_close(peer, code, reason)

    async def webSocketClose(self, ws, code, reason, was_clean):
        self._safe_close(ws, 1000, "")
        await durable_object_traffic_flush(self, force=True)

    async def webSocketError(self, ws, error):
        return

    # Hibernation events may be dispatched under either naming convention.
    web_socket_message = webSocketMessage
    web_socket_close = webSocketClose
    web_socket_error = webSocketError

    def _safe_close(self, ws, code, reason):
        try:
            ws.close(code, reason)
        except Exception:
            pass


class ForkMeshNodes(DurableObject):
    # Per-owner push channel for desktop/headless nodes, on the WebSocket
    # Hibernation API like ForkMeshRoom: sockets are accepted via
    # ctx.acceptWebSocket(["node"]) and the live set is read back from
    # ctx.getWebSockets("node"), so an idle-but-connected fleet bills ~no
    # duration. Connection state lives only in the runtime/socket attachments
    # — instance attributes would not survive eviction.
    #
    # This DO deliberately carries NOTHING but payload-free
    # {"type":"event","topic","repo"} frames (relay -> node) and
    # {"type":"ping"} keepalives (node -> relay). Repository bytes, inbox
    # items and control commands all stay on their existing signed HTTPS
    # routes; a pushed frame only tells the node to run the one consolidated
    # GET /api/sync it would otherwise run on the slow fallback poll.
    traffic_binding = "FORKMESH_NODES"

    async def fetch(self, request):
        parsed_url = urlparse(request.url)
        path = parsed_url.path
        upgrade = request.headers.get("upgrade")
        is_websocket = bool(upgrade) and upgrade.lower() == "websocket"

        if not is_websocket:
            if path.endswith("/notify"):
                # Internal-only (node_events_handler forwards only WebSocket
                # upgrades, so this action is unreachable from the public
                # router): fan one event frame out to every live node socket.
                query = parse_qs(parsed_url.query)
                frame = json.dumps({
                    "type": "event",
                    "topic": clean_string(query.get("topic", [""])[0], 40),
                    "repo": clean_string(query.get("repo", [""])[0], 200),
                })
                delivered = 0
                frame_bytes = len(frame.encode("utf-8"))
                for peer in self._live_node_sockets(close_stale=True):
                    try:
                        peer.send(frame)
                        delivered += 1
                    except Exception:
                        pass
                    else:
                        durable_object_traffic_note(
                            self, bytes_out=frame_bytes, messages=1)
                await durable_object_traffic_flush(self)
                return json_response({"ok": True, "delivered": delivered})
            # One-shot snapshot of the live node count (internal diagnostics).
            return json_response(
                {"ok": True, "nodes": len(self._live_node_sockets())})

        if len(self._live_node_sockets(close_stale=True)) >= \
                NODE_EVENT_MAX_SOCKETS:
            return json_response({"error": "too_many_nodes"}, status=429)

        client, server = WebSocketPair.new().object_values()
        self.ctx.acceptWebSocket(server, to_js(["node"]))
        server.serializeAttachment(to_js({
            "id": new_socket_id(), "last": int(Date.now()),
        }))
        return JsResponse.new(None, to_js({"status": 101, "webSocket": client}))

    def _live_node_sockets(self, close_stale=False):
        now = int(Date.now())
        sockets = []
        try:
            peers = self.ctx.getWebSockets("node")
        except Exception:
            return sockets
        for peer in peers:
            try:
                last = int(_ws_attr(peer, "last", 0) or 0)
            except (TypeError, ValueError):
                last = 0
            if not last or now - last > NODE_SOCKET_STALE_MS:
                if close_stale:
                    self._safe_close(peer, 1001, "stale")
                continue
            sockets.append(peer)
        return sockets

    async def webSocketMessage(self, ws, message):
        # Nodes only ever send small {"type":"ping"} keepalives; anything else
        # is dropped (rate-limited) or the socket is closed. Each accepted
        # frame refreshes the socket's staleness clock in its attachment.
        if not isinstance(message, str):
            self._safe_close(ws, 1003, "text frames only")
            return
        if len(message.encode("utf-8")) > NODE_EVENT_MAX_FRAME_BYTES:
            self._safe_close(ws, 1009, "message too large")
            return
        durable_object_traffic_note(
            self, bytes_in=len(message.encode("utf-8")), messages=1)
        await durable_object_traffic_flush(self)
        now = int(Date.now())
        try:
            start = int(_ws_attr(ws, "rl_start", 0) or 0)
            count = int(_ws_attr(ws, "rl_count", 0) or 0)
        except (TypeError, ValueError):
            start, count = 0, 0
        if now - start >= NODE_EVENT_MSG_WINDOW_MS:
            start, count = now, 0
        count += 1
        try:
            ws.serializeAttachment(to_js({
                "id": _ws_attr(ws, "id"), "last": now,
                "rl_start": start, "rl_count": count,
            }))
        except Exception:
            pass
        if count > NODE_EVENT_MSG_MAX_PER_WINDOW:
            return
        try:
            kind = json.loads(message).get("type")
        except Exception:
            return
        if kind == "ping":
            pong = json.dumps({"type": "pong"})
            try:
                ws.send(pong)
            except Exception:
                pass
            else:
                durable_object_traffic_note(
                    self, bytes_out=len(pong.encode("utf-8")))

    async def webSocketClose(self, ws, code, reason, was_clean):
        self._safe_close(ws, 1000, "")
        await durable_object_traffic_flush(self, force=True)

    async def webSocketError(self, ws, error):
        return

    # Hibernation events may be dispatched under either naming convention.
    web_socket_message = webSocketMessage
    web_socket_close = webSocketClose
    web_socket_error = webSocketError

    def _safe_close(self, ws, code, reason):
        try:
            ws.close(code, reason)
        except Exception:
            pass
